 * the RuneLite API doesn't expose. These unarmed defaults look right for most
 * outfits; override them in the config if you want weapon-appropriate stances.
 */
public final class PlayerPose
{
	public static final int IDLE = 808;
	public static final int WALK = 819;
	public static final int RUN = 824;
	public static final int TURN_180 = 820;
	public static final int SIDESTEP_LEFT = 821;
	public static final int SIDESTEP_RIGHT = 822;
	public static final int IDLE_TURN = 823;

	private PlayerPose()
	{
	}
}

package com.follower.follower;

import lombok.extern.slf4j.Slf4j;

/**
 * A rule-sized version of the documenting errand: the follower stops, holds a
 * prop, plays a pose over it for a few seconds, and puts everything back.
 *
 * <p>The errand is the scheduler's moment; this is the RULE's. A line like
 * "That's going in the book" claims an act the player never sees, and the
 * whole point of the prop work is that the claim and the act can now happen
 * together. Which rules get one, with what prop and pose and for how long, is
 * authored in phrases.json - the engine stays ignorant of scrolls.
 *
 * <p>Same shape as the errand's scroll handling, and deliberately so: prop
 * and pose together on one tick, and the cleanup path is idempotent because
 * it runs from finish, abort and shutdown alike. One flourish at a time; a
 * second request while one is playing is dropped rather than queued, because
 * a follower that files a backlog of gestures stops reading as spontaneous.
 */
@Slf4j
public class PropFlourish
{
	private final FollowerEntity follower;
	private final ErrandController.Hands hands;

	private int holdTicks;
	private boolean active;

	public PropFlourish(FollowerEntity follower, ErrandController.Hands hands)
	{
		this.follower = follower;
		this.hands = hands;
	}

	public boolean isActive()
	{
		return active;
	}

	/**
	 * Starts the flourish, unless one is already playing.
	 *
	 * @return whether it started - a false means the line still says its
	 * words, just without the gesture, which is the right degradation
	 */
	public boolean start(int itemId, int poseId, int ticks)
	{
		if (active || itemId <= 0 || poseId <= 0)
		{
			return false;
		}
		active = true;
		holdTicks = Math.max(1, ticks);
		follower.stayHere();
		// Prop and pose on the same tick, and so the same rendered frame: the
		// appearance service's dump path is synchronous, so the model with the
		// prop in it is applied before hold() returns. A settle delay here
		// only ever produced the wrong order - idle hands holding a scroll.
		hands.hold(itemId);
		follower.setPoseOverride(poseId);
		log.debug("Flourish started: item {} pose {} for {} ticks", itemId, poseId, ticks);
		return true;
	}

	/** Call once per game tick, on the client thread. */
	public void tick()
	{
		if (!active)
		{
			return;
		}
		if (--holdTicks <= 0)
		{
			finish();
		}
	}

	private void finish()
	{
		putEverythingBack();
	}

	/**
	 * The interruption path: a scene change or the plugin shutting down. Same
	 * cleanup as finishing - releasing the follower to walk is harmless even
	 * when the interrupter is about to despawn it, and a path that leaves it
	 * planted is a stuck follower waiting to happen.
	 */
	public void abort()
	{
		if (!active)
		{
			return;
		}
		putEverythingBack();
	}

	private void putEverythingBack()
	{
		active = false;
		holdTicks = 0;
		follower.setPoseOverride(0);
		hands.release();
		follower.resumeFollowing();
	}
}

package com.follower.follower;

import com.follower.FollowerConfig;
import com.follower.appearance.SpotAnimRepository;
import com.follower.speech.TriggerContext;
import com.follower.speech.TriggerEvent;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

/**
 * Gets the follower out of the way when a fight starts, and gives it something
 * to do while it waits.
 *
 * <p>A following follower stands where a player wants to look: on the boss, on
 * the tile they are about to click, in the middle of the fight. It cannot
 * actually block anything - it is a client-side object with no collision - but
 * being visually in the way is enough of a problem during a kill. So when a
 * fight starts it walks clear and watches from a few tiles off.
 *
 * <p>Thrall mode is deliberately exempt. A possessed thrall is IN the fight by
 * definition, and sending it away would undo the whole feature.
 *
 * <p>Speech is not handled here beyond announcing the start and end of a fight.
 * Encouragement and the health and prayer warnings come from the ordinary rule
 * system, which never stopped running - the {@code combat} and {@code bossFight}
 * conditions exist so a rule can ask about a fight the same way it asks about
 * anything else.
 */
@Slf4j
public class SpectateController
{
	/**
	 * How far the follower tries to stand from the player while watching. Close
	 * enough to still read as a companion, far enough not to sit on top of the
	 * fight.
	 */
	private static final int WATCH_DISTANCE = 4;

	/**
	 * How far the follower may drift from its watching spot before it is moved
	 * again. Without this it would re-path every tick as the player shuffles.
	 *
	 * <p>Generous on purpose. Every re-seat ends the channelled spell, so a
	 * tight leash meant a boss that moves the player around - Scurrius was the
	 * case that showed it - reduced the whole sequence to repeated casting and
	 * sitting. A watcher standing well back is the point, so it only follows
	 * once genuinely left behind.
	 */
	private static final int RESEAT_DISTANCE = 12;

	/**
	 * How often the channelled graphic is renewed, in game ticks.
	 *
	 * <p>Two ticks is 1.2 seconds against a 1.34-second effect, so each renewal
	 * starts just before the last has faded and the ward looks continuous
	 * rather than blinking once in a while.
	 */
	private static final int SHIELD_MAINTAIN_TICKS = 2;

	/**
	 * How long the follower stays put after dispelling, so the closing
	 * animation is not cut off by it walking back. Movement always wins over an
	 * emote, so releasing on the same tick would kill the flourish outright.
	 */
	private static final int DISPEL_HOLD_TICKS = 4;

	private final Client client;
	private final FollowerEntity follower;
	private final FollowerConfig config;

	/**
	 * Read fresh on every use, never held. The engine REPLACES its context on
	 * every reset - each login screen, the memory eraser, a plugin toggle -
	 * and a controller holding the original object was reading a context
	 * that had stopped being refreshed: its isInCombat was false forever, so
	 * spectating never started again after the first relog. Cheers still
	 * fired (the rules read the live context), which is what made the boss
	 * fights look detected while the follower stood glued to the player.
	 */
	private final java.util.function.Supplier<TriggerContext> contextSource;
	private final SpotAnimRepository spotAnims;
	private final Consumer<TriggerEvent> speech;

	private TriggerContext context()
	{
		return contextSource.get();
	}

	/** Puts the follower's weapon and shield away while it channels. */
	private final java.util.function.Consumer<Boolean> disarm;

	/** Whether the follower is currently standing aside for a fight. */
	private boolean spectating;

	private WorldPoint watchTile;

	/**
	 * The shield is a three-part spell rather than a repeating effect: it is
	 * summoned once, channelled for as long as the follower stands and fights
	 * are still going, and finished off deliberately at the end.
	 */
	private enum Shield
	{
		NONE, SUMMONING, CHANNELLING
	}

	private Shield shield = Shield.NONE;
	private int ticksSinceShield;

	/** Counts down after a dispel; the follower walks back when it reaches zero. */
	private int releaseTicks;

	/**
	 * How long the follower must have stood still before it starts the spell.
	 *
	 * <p>Observed in a Scurrius fight: a summon began and was abandoned a second
	 * later because the player moved and the follower had to re-seat, which
	 * reads as a cast that goes nowhere. Waiting a couple of ticks costs
	 * nothing and means a spell is only started when there is a reasonable
	 * chance of holding it.
	 */
	private static final int SETTLE_DWELL_TICKS = 3;

	private int ticksSettled;

	/**
	 * Consecutive unsettled ticks before the channel is considered broken. A
	 * real walk lasts many ticks; a momentary wobble should not end a spell.
	 */
	private static final int UNSETTLED_DROP_TICKS = 3;

	private int ticksUnsettled;

	public SpectateController(Client client, FollowerEntity follower, FollowerConfig config,
		java.util.function.Supplier<TriggerContext> contextSource, SpotAnimRepository spotAnims,
		Consumer<TriggerEvent> speech, java.util.function.Consumer<Boolean> disarm)
	{
		this.client = client;
		this.follower = follower;
		this.config = config;
		this.contextSource = contextSource;
		this.spotAnims = spotAnims;
		this.speech = speech;
		this.disarm = disarm;
	}

	public boolean isSpectating()
	{
		return spectating;
	}

	/**
	 * Whether the spectate logic owns the follower's feet right now, which is
	 * a longer window than {@link #isSpectating()}.
	 *
	 * <p>stop() clears the flag at once but leaves the follower standing where
	 * it is for a few ticks, so the closing cast is not cut off by walking
	 * away. Through that gap the follower is parked and no longer counted as
	 * spectating, which is indistinguishable from a Stay the player asked for
	 * unless somebody asks this instead.
	 */
	public boolean holdsTheFeet()
	{
		return spectateOwnsTheFeet(spectating, releaseTicks);
	}

	/** The above as a decision, so it can be tested without a controller. */
	public static boolean spectateOwnsTheFeet(boolean spectating, int releaseTicks)
	{
		return spectating || releaseTicks > 0;
	}

	/**
	 * Why the follower is or is not standing clear right now, for
	 * {@code ::follower spectate}. Every gate in {@link #tick} reads back here,
	 * so a feature that silently does nothing can be diagnosed in one command
	 * rather than by guessing which condition failed.
	 */
	public String describe(boolean busy)
	{
		return "spectate: setting=" + config.spectateCombat()
			+ " busy=" + busy
			+ " spawned=" + follower.isSpawned()
			+ " inCombat=" + context().isInCombat()
			+ " target='" + context().getCombatTarget() + "' level=" + context().getCombatTargetLevel()
			+ " thieving=" + context().isThieving()
			+ " thievingSession=" + context().isInThievingSession()
			+ " boss=" + context().isBossFight()
			+ " | spectating=" + spectating
			+ " watchTile=" + watchTile
			+ " settled=" + follower.isSettled()
			+ " shield=" + shield
			+ " releaseTicks=" + releaseTicks;
	}

	/**
	 * @param busy true when something else owns the follower's feet - thrall
	 * mode or an errand - in which case spectating stays out of the way
	 */
	public void tick(boolean busy)
	{
		// A dispel in progress owns the feet until its animation has played.
		// The weapon comes back at the same moment, for the same reason: the
		// rebuild that returns it would otherwise cut the closing cast short.
		if (releaseTicks > 0 && --releaseTicks == 0)
		{
			disarm.accept(false);
			follower.resumeFollowing();
		}

		if (!config.spectateCombat() || busy || !follower.isSpawned())
		{
			if (spectating)
			{
				stop();
			}
			return;
		}

		// Thieving is not a fight and is not spectated. Standing clear was tried
		// and is the wrong shape: it holds one spot facing the action, which
		// reads as an audience. A player picking pockets wants the follower
		// gone, not watching - so the thieving session suppresses this outright
		// and the wandering takes over instead.
		if (!context().isInCombat() || context().isInThievingSession())
		{
			if (spectating)
			{
				stop();
			}
			return;
		}

		if (!spectating)
		{
			start(true);
		}
		else
		{
			holdPosition();
		}

		maybeCastShield();
	}

	/**
	 * @param announce whether this is a fight, which is worth saying something
	 * about. Thieving is not: it steps clear and keeps quiet.
	 */
	private void start(boolean announce)
	{
		spectating = true;
		announced = announce;
		releaseTicks = 0;
		unseatedTicks = 0;
		if (!moveClear())
		{
			// Nowhere to go is not a reason to keep announcing a fight; the
			// follower simply carries on following.
			log.debug("Nowhere to stand clear; staying put");
		}
		if (!announce)
		{
			log.debug("Standing clear while thieving");
			return;
		}
		log.debug("Spectating '{}' level {} boss={} shieldEnabled={}",
			context().getCombatTarget(), context().getCombatTargetLevel(),
			context().isBossFight(), config.spectateShield());
		speech.accept(TriggerEvent.combat(TriggerEvent.Type.COMBAT_START,
			context().getCombatTarget()));
	}

	/**
	 * Whether the current stand-clear was announced as a fight, so that only
	 * the ones that said hello say goodbye.
	 */
	private boolean announced;

	private void stop()
	{
		spectating = false;
		watchTile = null;
		unseatedTicks = 0;

		// Finishing the spell is its own moment: drop the channelled pose, play
		// the closing animation where it stands, and only walk back once it has
		// had time to play - movement would cut it off otherwise.
		boolean wasCasting = shield != Shield.NONE;
		dropChannel("fight over");
		// Stand, then cast: it gets to its feet before releasing the spell, so
		// the sequence closes the way it opened.
		if (wasCasting && castChain(
			new int[]{config.spectateShieldChannelEnd(), config.spectateShieldEndAnimation()},
			new int[]{config.spectateShieldEndGraphic(), config.spectateShieldEndGraphic()}))
		{
			// The weapon stays away until the closing cast has played: taking
			// it back rebuilds the model, and a rebuild would cut the animation
			// off mid-flourish.
			releaseTicks = DISPEL_HOLD_TICKS;
		}
		else
		{
			if (wasCasting)
			{
				disarm.accept(false);
			}
			follower.resumeFollowing();
		}

		// Only a fight says goodbye. A thieving stand-clear ended is the
		// follower simply coming back, which needs no remark.
		if (announced)
		{
			speech.accept(TriggerEvent.combat(TriggerEvent.Type.COMBAT_END,
				context().getCombatTarget()));
		}
		announced = false;
	}

	/** Re-seats the follower only once it has been left well behind. */
	private void holdPosition()
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getWorldLocation() == null)
		{
			return;
		}
		// Unseated - the first moveClear found nowhere to stand. That used to
		// be final: this method returned on a null watchTile, so a follower
		// that failed once in a cramped arena stood glued to the player for
		// the whole fight. Play report: a boss fight where it never stepped
		// clear. Fights move; tiles open up; try again every few ticks.
		if (watchTile == null)
		{
			if (++unseatedTicks % RESEAT_RETRY_TICKS == 0)
			{
				moveClear();
			}
			return;
		}
		// The seat is HELD through FollowerEntity's stayTile, and plenty of
		// hands can release that without telling this controller: the thrall
		// exit's stayHere/resumeFollowing/snapBeside chain, the leash snap,
		// scene recovery. Measuring watchTile against the PLAYER missed all
		// of them - the tile was still nearby, so the spectator stood glued
		// to the player casting wards while never stepping away. Play report:
		// "out of thrall mode they don't step away, but still do the magic
		// barrier animations." If the follower no longer holds ANY stay, it
		// was un-seated, whoever did it: take the seat again.
		if (!follower.isStaying()
			|| watchTile.distanceTo(local.getWorldLocation()) > RESEAT_DISTANCE
			|| watchTile.getPlane() != local.getWorldLocation().getPlane())
		{
			moveClear();
		}
	}

	/** Ticks spent spectating without a tile to stand on. */
	private int unseatedTicks;

	/** How often an unseated spectator looks again for somewhere to stand. */
	private static final int RESEAT_RETRY_TICKS = 5;

	/**
	 * Puts the follower behind the player, away from whatever is being fought.
	 *
	 * <p>The direction is the one that matters: standing "near the player" is no
	 * good if that happens to be between them and the boss. The vector from the
	 * target to the player, continued past the player, is the one place
	 * guaranteed not to be in the line of the fight. Tiles are tried outward
	 * from there, so a wall or a corner degrades to the next best angle rather
	 * than giving up.
	 */
	private boolean moveClear()
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getWorldLocation() == null)
		{
			return false;
		}
		WorldPoint player = local.getWorldLocation();

		Actor target = local.getInteracting();
		WorldPoint threat = target == null ? null : target.getWorldLocation();

		int dx;
		int dy;
		if (threat == null || threat.equals(player))
		{
			// Nothing to stand clear OF; just get out of arm's reach.
			dx = 0;
			dy = -1;
		}
		else
		{
			dx = Integer.signum(player.getX() - threat.getX());
			dy = Integer.signum(player.getY() - threat.getY());
			if (dx == 0 && dy == 0)
			{
				dy = -1;
			}
		}

		// Straight back first, then fanned out to either side, then the sides
		// themselves - a corner or a wall behind the player should not end with
		// the follower standing in the fight.
		int[][] offsets = {
			{dx, dy},
			{dx == 0 ? 1 : dx, dy == 0 ? 1 : dy},
			{dx == 0 ? -1 : dx, dy == 0 ? -1 : dy},
			{dy, dx},
			{-dy, -dx},
		};

		for (int[] direction : offsets)
		{
			for (int distance = WATCH_DISTANCE; distance >= 2; distance--)
			{
				WorldPoint candidate = new WorldPoint(
					player.getX() + direction[0] * distance,
					player.getY() + direction[1] * distance,
					player.getPlane());
				if (threat != null && candidate.distanceTo(threat) < 3)
				{
					continue;
				}
				if (follower.stayAt(candidate))
				{
					watchTile = candidate;
					return true;
				}
			}
		}

		// The away-from-the-threat fan is walled - a boss arena is exactly the
		// place where "behind the player" is stone. In a fight the goal is not
		// underfoot, and any tile at a distance that is not next to the threat
		// serves it. The full ring, nearest first, before giving up.
		for (int distance = 2; distance <= WATCH_DISTANCE; distance++)
		{
			for (int ox = -distance; ox <= distance; ox++)
			{
				for (int oy = -distance; oy <= distance; oy++)
				{
					if (Math.max(Math.abs(ox), Math.abs(oy)) != distance)
					{
						continue;
					}
					WorldPoint candidate = new WorldPoint(
						player.getX() + ox, player.getY() + oy, player.getPlane());
					if (threat != null && candidate.distanceTo(threat) < 3)
					{
						continue;
					}
					if (follower.stayAt(candidate))
					{
						watchTile = candidate;
						return true;
					}
				}
			}
		}
		return false;
	}

	/**
	 * The protective-shield flourish: a cast animation with a graphic on top,
	 * played on the follower itself while it watches a boss fight.
	 *
	 * <p>Both ids are settings rather than constants. Unlike a weapon's swing,
	 * which the game answers definitively, "what a protective shield looks
	 * like" has no correct answer to measure - so the honest thing is to pick a
	 * reasonable pair and let it be changed, with {@code ::follower gfx} to
	 * audition alternatives.
	 */
	private void maybeCastShield()
	{
		if (!config.spectateShield() || !context().isBossFight())
		{
			return;
		}
		// An emote started while the feet are still moving is cancelled by the
		// very next movement frame - movement always wins over an emote, which
		// is what stops a dancing follower gliding along behind you. The first
		// cast used to fire on the same tick the follower set off to stand
		// clear, so it was killed before a single particle appeared. Nothing is
		// cast until it has actually stopped at its watching spot.
		//
		// The same rule ends a channel: a follower that has to move cannot go
		// on channelling, so the pose is dropped and the spell begins again
		// once it has settled somewhere new.
		// Settled is not seated. A follower glued to the player - un-seated
		// by the thrall exit, a failed moveClear in a cramped arena, a leash
		// snap - is perfectly still and used to pass this gate, which is how
		// the ward got cast at the player's elbow instead of from the seat.
		// No stay held means no seat, and no seat means no spell.
		if (!follower.isSettled() || !follower.isStaying())
		{
			ticksSettled = 0;
			// One unsettled tick is not a journey. The fine position can leave
			// the tile centre for a moment without the follower going
			// anywhere, and dropping on that alone made the spell restart -
			// standing up out of the kneel and casting it again - while it was
			// supposed to be holding still.
			if (++ticksUnsettled >= UNSETTLED_DROP_TICKS)
			{
				// Broken by movement, so there is no closing animation to
				// protect: the weapon can come straight back.
				boolean wasCasting = shield != Shield.NONE;
				dropChannel("moved");
				if (wasCasting)
				{
					disarm.accept(false);
				}
			}
			return;
		}
		ticksUnsettled = 0;
		ticksSettled++;

		switch (shield)
		{
			case NONE:
				// Only begin once it has genuinely stopped, or the spell is
				// abandoned a second later when it has to re-seat.
				if (ticksSettled < SETTLE_DWELL_TICKS)
				{
					break;
				}
				// Cast, then sit, as one chain: the follower raises the ward
				// and settles into holding it without a gap between the two.
				// Nothing to play is not a reason to skip the channel.
				// The particle rides every stage, not just the cast: the ward is
				// meant to be visibly up from the moment it is raised.
				// Weapon and shield go away as the spell is raised, while the
				// cast covers the rebuild, rather than when the kneel starts.
				disarm.accept(true);
				if (castChain(
					new int[]{config.spectateShieldAnimation(), config.spectateShieldChannelStart()},
					new int[]{config.spectateShieldGraphic(), config.spectateShieldGraphic()}))
				{
					shield = Shield.SUMMONING;
				}
				else
				{
					startChannel();
				}
				break;

			case SUMMONING:
				// The summon is a one-shot; the channelled pose takes over the
				// moment it has played out, so the two read as one spell.
				if (!follower.isEmotePlaying())
				{
					startChannel();
				}
				break;

			case CHANNELLING:
				// A looping pose shows no particles of its own, so the graphic
				// is renewed on its own timer to keep the ward alive.
				if (++ticksSinceShield >= SHIELD_MAINTAIN_TICKS)
				{
					ticksSinceShield = 0;
					SpotAnimRepository.Entry renew =
						spotAnims.get(config.spectateShieldChannelGraphic());
					if (renew != null)
					{
						follower.playSpotAnim(renew);
					}
				}
				break;

			default:
				break;
		}
	}

	/**
	 * Starts the channelled pose. A pose override loops until it is cleared,
	 * unlike an emote, which is what "until it moves or the fight ends" needs.
	 */
	private void startChannel()
	{
		int channel = config.spectateShieldChannelAnimation();
		if (channel > 0)
		{
			follower.setPoseOverride(channel);
		}
		shield = Shield.CHANNELLING;
		// Renew on the very next tick rather than after a full interval, so the
		// ward does not go dark between the summon and the first top-up.
		ticksSinceShield = SHIELD_MAINTAIN_TICKS;
		log.debug("Shield: channelling, pose {}", channel);
	}

	/** Ends the channel and hands the follower's pose back to normal. */
	private void dropChannel(String reason)
	{
		if (shield != Shield.NONE)
		{
			log.debug("Shield: dropping from {} ({})", shield, reason);
		}
		if (shield == Shield.CHANNELLING)
		{
			follower.setPoseOverride(0);
		}
		shield = Shield.NONE;
	}

	/**
	 * Plays one stage of the shield.
	 *
	 * @return false when the stage has nothing configured, so a caller can tell
	 * a skipped stage from a played one
	 */
	/**
	 * Plays several stages back to back, each with its own optional graphic.
	 *
	 * <p>A zero animation is dropped from the chain rather than played, but its
	 * graphic is not: a stage may legitimately be particles alone.
	 *
	 * @return false only when the whole chain had nothing to show
	 */
	private boolean castChain(int[] animations, int[] graphicIds)
	{
		java.util.List<Integer> ids = new java.util.ArrayList<>();
		java.util.List<SpotAnimRepository.Entry> graphics = new java.util.ArrayList<>();
		boolean played = false;

		for (int i = 0; i < animations.length; i++)
		{
			SpotAnimRepository.Entry fx = spotAnims.get(graphicIds[i]);
			if (animations[i] > 0)
			{
				ids.add(animations[i]);
				graphics.add(fx);
			}
			else if (fx != null)
			{
				follower.playSpotAnim(fx);
				played = true;
			}
		}

		if (!ids.isEmpty())
		{
			int[] chain = new int[ids.size()];
			for (int i = 0; i < chain.length; i++)
			{
				chain[i] = ids.get(i);
			}
			// Kept, at debug: this is what showed the sit and stand were
			// running all along and the ids were the problem. ::follower
			// spectate reports the same state on demand without it.
			log.debug("Shield chain: animations {} settled={} emote={}",
				ids, follower.isSettled(), follower.isEmotePlaying());
			follower.playAnimations(chain,
				graphics.toArray(new SpotAnimRepository.Entry[0]));
			played = true;
		}
		return played;
	}

}

package com.follower.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;

/**
 * Learns which stand/walk/run animation set goes with which wielded weapon, by
 * watching real players.
 *
 * <p>A weapon's pose set lives in the game's weapon-stance data, which neither the
 * runtime API nor the cache's {@code ItemDefinition} exposes per item. But every
 * {@link net.runelite.api.Actor} reports its <em>resolved</em> pose ids, and every
 * player's wielded weapon is readable from their composition. Pairing the two gives
 * real, correct data rather than a hardcoded guess.
 *
 * <p>Your own character is the main teacher: equip a weapon and its stances are
 * learned immediately. Crowded areas fill the library quickly. Results persist to
 * {@code stances.json}.
 */
@Slf4j
@Singleton
public class StanceLibrary
{
	public static final String FILE_NAME = "stances.json";

	/** Weapon item id used for "nothing wielded". */
	public static final int UNARMED = 0;

	public static class Stance
	{
		public int idle;
		public int walk;
		public int run;

		/**
		 * The directional poses: back-pedal, side-steps, and turn-in-place -
		 * used when the follower moves while FACING something, the way an
		 * interacting player does. Entries saved before these fields existed
		 * deserialize them as 0; the pose selector falls back to {@code walk}
		 * (the client's own -1 fallback) until the weapon is observed again.
		 */
		public int walkBack;
		public int walkLeft;
		public int walkRight;
		public int turnLeft;
		public int turnRight;

		/**
		 * The weapon's attack animation, learned from players seen swinging it.
		 * Unlike the poses above an actor does not advertise this - it is a
		 * one-shot animation - so it is captured when a player animates while
		 * interacting with something. 0 until observed.
		 */
		public int attack;

		/**
		 * The swing for each attack style, indexed by the game's own style
		 * number (COM_MODE, 0-3). 0 in a slot means that style has not been
		 * seen; null means none have.
		 *
		 * <p>Only the LOCAL player can fill these. Which style anyone else has
		 * selected is not readable - varps are the local player's - so every
		 * other player in the scene can still only teach the generic swing
		 * above. That asymmetry is the whole reason this is a separate field
		 * rather than a replacement: the crowd teaches breadth, your own play
		 * teaches depth, and a weapon ends up with both.
		 *
		 * <p>Deliberately indexed by style NUMBER rather than named stab,
		 * slash or crush. What a style means depends on the weapon type, which
		 * would need a table the cache does not carry - and the follower never
		 * needs to know the name. It needs the animation that goes with the
		 * style the player has selected, and that is exactly what the index is.
		 */
		public int[] attackByStyle;

		public Stance()
		{
		}

		Stance(int idle, int walk, int run,
			int walkBack, int walkLeft, int walkRight, int turnLeft, int turnRight)
		{
			this.idle = idle;
			this.walk = walk;
			this.run = run;
			this.walkBack = walkBack;
			this.walkLeft = walkLeft;
			this.walkRight = walkRight;
			this.turnLeft = turnLeft;
			this.turnRight = turnRight;
		}

		boolean isComplete()
		{
			return idle > 0 && walk > 0 && run > 0;
		}

		boolean sameAs(Stance other)
		{
			return idle == other.idle && walk == other.walk && run == other.run
				&& walkBack == other.walkBack
				&& walkLeft == other.walkLeft && walkRight == other.walkRight
				&& turnLeft == other.turnLeft && turnRight == other.turnRight;
		}

		/**
		 * Same weapon CLASS: the idle/walk/run triple is what the game shares
		 * between weapons of a kind. Measured across 190 observed weapons,
		 * those triples collapse to 32 classes - every scimitar walks alike,
		 * every staff walks alike - which is what lets one weapon's attack
		 * stand in for its whole family.
		 */
		boolean sameClassAs(Stance other)
		{
			return idle == other.idle && walk == other.walk && run == other.run;
		}
	}

	private final Gson gson;
	private final com.follower.appearance.ModelRepository models;

	/** weapon item id -> stance set. */
	private final Map<Integer, Stance> stances = new HashMap<>();

	/** base item name -> a weapon id known to have that name's stance. */
	private Map<String, Integer> byBaseName;

	/** metal-stripped item name -> a weapon id, for inheriting across tiers. */
	private Map<String, Integer> byTierName;

	/** How many stances the name index was built from, so it rebuilds when they grow. */
	private int indexedSize = -1;

	/** weapon id -> the weapon whose stance it inherits, or 0 for none. */
	private final Map<Integer, Integer> donors = new HashMap<>();

	private Path file;
	private boolean dirty;

	@Inject
	public StanceLibrary(Gson gson, com.follower.appearance.ModelRepository models)
	{
		this.gson = gson;
		this.models = models;
		// Unarmed is known and never needs learning.
		stances.put(UNARMED, new Stance(PlayerPose.IDLE, PlayerPose.WALK, PlayerPose.RUN,
			PlayerPose.TURN_180, PlayerPose.SIDESTEP_LEFT, PlayerPose.SIDESTEP_RIGHT,
			PlayerPose.IDLE_TURN, PlayerPose.IDLE_TURN));
	}

	/**
	 * Loads the bundled starter library first, then whatever this install has
	 * observed on top of it.
	 *
	 * <p>Weapon animations cannot be read from the cache - measured, not
	 * assumed: item params hold combat stats, item category disagrees with
	 * the observed stances, and no struct carries a pose set. The client
	 * resolves them in script at equip time. Observation is therefore the
	 * only honest source, and shipping a library means a new install starts
	 * with hundreds of weapons already right instead of everything falling
	 * back to unarmed.
	 */
	public void load(Path dataDir)
	{
		file = dataDir.resolve(FILE_NAME);

		try (java.io.InputStream in = StanceLibrary.class
			.getResourceAsStream("/com/follower/" + FILE_NAME))
		{
			if (in != null)
			{
				int added = read(new java.io.BufferedReader(
					new java.io.InputStreamReader(in, StandardCharsets.UTF_8)));
				log.info("Loaded {} bundled weapon stances", added);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read the bundled stance library", e);
		}

		if (!Files.isRegularFile(file))
		{
			return;
		}
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			// Local observations win: this client saw them first-hand.
			log.info("Loaded {} learned weapon stances", read(reader));
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read {}", file, e);
		}
	}

	/** @return how many entries were taken from this source. */
	private int read(Reader reader)
	{
		Map<String, Stance> loaded = gson.fromJson(reader,
			new com.google.gson.reflect.TypeToken<Map<String, Stance>>()
			{
			}.getType());
		if (loaded == null)
		{
			return 0;
		}
		int added = 0;
		for (Map.Entry<String, Stance> entry : loaded.entrySet())
		{
			try
			{
				stances.put(Integer.parseInt(entry.getKey()), entry.getValue());
				added++;
			}
			catch (NumberFormatException ignored)
			{
				// Skip malformed key.
			}
		}
		return added;
	}

	/**
	 * Forgets every learned attack, keeping how each weapon is CARRIED.
	 *
	 * <p>For repairing a library that learned blocks as attacks before the
	 * observer could tell them apart. The carry poses are safe - they come
	 * from the composition rather than from a moment of combat - and an attack
	 * is re-learned within a fight or two of holding the weapon, so this costs
	 * a little accuracy briefly and fixes a follower that flinches instead of
	 * swinging.
	 */
	public void clearLearnedAttacks()
	{
		int cleared = 0;
		for (Stance stance : stances.values())
		{
			if (stance.attack > 0)
			{
				stance.attack = 0;
				cleared++;
			}
		}
		if (cleared > 0)
		{
			dirty = true;
			log.info("Cleared {} learned attack animation(s) for relearning", cleared);
		}
	}

	public void save()
	{
		if (!dirty || file == null)
		{
			return;
		}

		Map<String, Stance> out = new HashMap<>();
		for (Map.Entry<Integer, Stance> entry : stances.entrySet())
		{
			out.put(Integer.toString(entry.getKey()), entry.getValue());
		}

		try
		{
			Files.createDirectories(file.getParent());
			try (Writer writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8))
			{
				gson.toJson(out, writer);
			}
			dirty = false;
		}
		catch (IOException e)
		{
			log.warn("Could not write {}", file, e);
		}
	}

	/**
	 * Records the stance set of every player in the scene. Cheap enough to run each
	 * game tick; only genuinely new weapons cause a write.
	 */
	public void observe(Client client)
	{
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player == null)
			{
				continue;
			}
			learn(player);
		}
	}

	private void learn(Player player)
	{
		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return;
		}

		int raw = composition.getEquipmentId(KitType.WEAPON);
		// getEquipmentId returns the item id directly, or -1 when nothing is wielded.
		int weaponId = raw <= 0 ? UNARMED : raw;

		Stance observed = new Stance(
			player.getIdlePoseAnimation(),
			player.getWalkAnimation(),
			player.getRunAnimation(),
			player.getWalkRotate180(),
			player.getWalkRotateLeft(),
			player.getWalkRotateRight(),
			player.getIdleRotateLeft(),
			player.getIdleRotateRight());

		if (!observed.isComplete())
		{
			return;
		}

		Stance known = stances.get(weaponId);
		if (known != null && known.sameAs(observed))
		{
			return;
		}
		if (known != null)
		{
			// Poses changed but the attack did not: carry it across rather
			// than throwing away a hard-won observation.
			observed.attack = known.attack;
		}

		stances.put(weaponId, observed);
		dirty = true;
		log.debug("Learned stance for weapon {}: idle={} walk={} run={} back={} left={} right={}",
			weaponId, observed.idle, observed.walk, observed.run,
			observed.walkBack, observed.walkLeft, observed.walkRight);
	}

	/**
	 * Records a player's one-shot animation as their weapon's attack.
	 *
	 * <p>The gate is that they are INTERACTING with an actor: combat always
	 * has a target, while the animations that would otherwise pollute this -
	 * woodcutting, mining, cooking, emotes, eating - either target a scene
	 * object or nothing at all. Skilling with an axe therefore never gets
	 * mistaken for an axe attack.
	 */
	public void learnAttack(Player player, int animationId)
	{
		learnAttack(player, animationId, -1);
	}

	/**
	 * @param style the attack style the swing was performed in (COM_MODE,
	 * 0-3), or -1 when it cannot be known - which is every player but the
	 * local one
	 */
	public void learnAttack(Player player, int animationId, int style)
	{
		if (animationId <= 0 || player.getInteracting() == null)
		{
			return;
		}
		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return;
		}
		int raw = composition.getEquipmentId(KitType.WEAPON);
		int weaponId = raw <= 0 ? UNARMED : raw;

		Stance stance = stances.get(weaponId);
		if (stance == null || stance.attack == animationId)
		{
			// No pose set yet means the weapon is brand new to us; observe()
			// creates it on the next tick and the attack lands then.
			return;
		}
		if (style >= 0 && style < STYLES)
		{
			if (stance.attackByStyle == null)
			{
				stance.attackByStyle = new int[STYLES];
			}
			if (stance.attackByStyle[style] != animationId)
			{
				stance.attackByStyle[style] = animationId;
				dirty = true;
				log.debug("Learned attack animation {} for weapon {} in style {}",
					animationId, weaponId, style);
			}
		}

		// The generic slot is still written, and still by everyone: it is what
		// borrowing across a stance class reads, and what an unknown style
		// falls back to.
		if (stance.attack == animationId)
		{
			return;
		}
		stance.attack = animationId;
		dirty = true;
		log.debug("Learned attack animation {} for weapon {}", animationId, weaponId);
	}

	/**
	 * How a weapon is USED, which the pose set does not say.
	 *
	 * <p>Supplied by the plugin from the item's own equipment stats, because
	 * the pose triple describes how a weapon is CARRIED and nothing more. The
	 * 79-weapon class that walks like an unarmed player holds the Dragon
	 * harpoon and the Bow of faerdhinen side by side: identical carry, utterly
	 * different swing. Borrowing across that would put a chop on a bow.
	 *
	 * <p>Combat style alone turned out to be too coarse. That same class went
	 * on to collect a bow, a dart and a knife - all ranged, none animating
	 * remotely alike - and the follower would have shot a bow like a thrown
	 * dart. Handedness splits them cleanly, so the key carries both.
	 */
	public interface StyleSource
	{
		int MELEE = 0;
		int RANGED = 1;
		int MAGIC = 2;
		int UNKNOWN = -1;

		/** A style and handedness folded into one comparable key. */
		static int packed(int style, boolean twoHanded)
		{
			return style < 0 ? UNKNOWN : style * 2 + (twoHanded ? 1 : 0);
		}

		/** {@link #packed} for this item, or {@link #UNKNOWN}. */
		int usageOf(int itemId);
	}

	private StyleSource styleSource;

	public void setStyleSource(StyleSource styleSource)
	{
		this.styleSource = styleSource;
	}

	/**
	 * The attack animation to use for a weapon: its own if it has been seen
	 * used, otherwise one borrowed from a weapon that both carries AND fights
	 * the same way.
	 *
	 * <p>The borrow is what keeps this practical. Nobody owns every weapon, but
	 * weapons of a kind share a pose set, so seeing ONE scimitar swung covers
	 * every scimitar in the game.
	 *
	 * <p>Matching the pose class alone is not enough, though. It groups by how
	 * a weapon is carried, and melee and ranged weapons can be carried alike,
	 * so the combat style has to agree as well. When the style of either weapon
	 * cannot be established the borrow is refused outright: a wrong animation
	 * is worse than a plain one, which is the same reason the variant matching
	 * is exact rather than fuzzy.
	 *
	 * @return 0 when nothing can be borrowed, leaving the caller to fall back
	 */
	public int attackFor(int weaponItemId)
	{
		return attackFor(weaponItemId, -1);
	}

	/** How many attack styles the game numbers, for the per-style slots. */
	private static final int STYLES = 4;

	/**
	 * @param style the style the swing should be in (COM_MODE, 0-3), or -1 to
	 * take whatever the weapon is generally known to do
	 */
	public int attackFor(int weaponItemId, int style)
	{
		// forWeapon already resolves a trim variant to its plain original.
		Stance stance = forWeapon(weaponItemId);
		if (stance == null)
		{
			return 0;
		}
		// The style the player actually has selected wins when this weapon has
		// been swung in it. Not borrowed across the class: a style number means
		// different things on different weapon types, so another weapon's slot
		// 2 is not this weapon's slot 2.
		if (style >= 0 && style < STYLES && stance.attackByStyle != null
			&& stance.attackByStyle[style] > 0)
		{
			return stance.attackByStyle[style];
		}
		if (stance.attack > 0)
		{
			return stance.attack;
		}

		int usage = styleSource == null
			? StyleSource.UNKNOWN : styleSource.usageOf(weaponItemId);
		if (usage == StyleSource.UNKNOWN)
		{
			return 0;
		}

		// A class can hold several different attacks once a few of its weapons
		// have been seen: most share the generic swing for their kind, while
		// the occasional signature weapon has one all of its own. Taking the
		// first match would hand a plain battlestaff the Eye of ayak's unique
		// animation, and worse, WHICH one it took depended on hash order - the
		// same weapon could animate differently between sessions.
		//
		// So: whichever attack the most weapons of this class agree on, with
		// ties going to the lowest item id. Agreement finds the generic swing
		// as soon as two weapons share it, and the tie-break stands in until
		// then, since the plainer weapon of a kind is almost always the older
		// and lower-numbered one.
		Map<Integer, Integer> agreement = new HashMap<>();
		Map<Integer, Integer> lowestDonor = new HashMap<>();
		for (Map.Entry<Integer, Stance> entry : stances.entrySet())
		{
			Stance other = entry.getValue();
			if (other.attack <= 0 || !other.sameClassAs(stance)
				|| styleSource.usageOf(entry.getKey()) != usage)
			{
				continue;
			}
			agreement.merge(other.attack, 1, Integer::sum);
			lowestDonor.merge(other.attack, entry.getKey(), Math::min);
		}

		int best = 0;
		for (Map.Entry<Integer, Integer> candidate : agreement.entrySet())
		{
			if (best == 0
				|| candidate.getValue() > agreement.get(best)
				|| (candidate.getValue().equals(agreement.get(best))
					&& lowestDonor.get(candidate.getKey()) < lowestDonor.get(best)))
			{
				best = candidate.getKey();
			}
		}
		return best;
	}

	/**
	 * Sets a weapon's stance by hand, for weapons this account cannot wield
	 * and nobody nearby is carrying.
	 *
	 * <p>Weapon animations exist nowhere in the cache - item params hold
	 * combat stats, item category contradicts the observed stances, no struct
	 * carries a pose set, and a byte-level sweep of every archive turns up
	 * only NPC definitions and coincidence. The client assembles them at
	 * runtime. So when observation is impossible, a typed-in id from the
	 * wiki is the honest fallback: real data, just sourced by hand.
	 *
	 * @param attack 0 to leave the learned attack alone
	 */
	public void setManual(int weaponItemId, int idle, int walk, int run, int attack)
	{
		int id = weaponItemId <= 0 ? UNARMED : weaponItemId;
		Stance stance = stances.get(id);
		if (stance == null)
		{
			stance = new Stance();
			stances.put(id, stance);
		}
		stance.idle = idle;
		stance.walk = walk;
		stance.run = run;
		// Directional poses are optional; the selector falls back to walk,
		// which is the client's own behaviour for a stance that lacks them.
		if (attack > 0)
		{
			stance.attack = attack;
		}
		dirty = true;
		log.info("Stance set by hand for weapon {}: idle={} walk={} run={} attack={}",
			id, idle, walk, run, stance.attack);
	}

	/** A weapon's stance exactly as stored, or null when never seen or set. */
	public Stance describe(int weaponItemId)
	{
		return stances.get(weaponItemId <= 0 ? UNARMED : weaponItemId);
	}

	/** Every stance as stored, for auditing what the library actually holds. */
	public Map<Integer, Stance> all()
	{
		return java.util.Collections.unmodifiableMap(stances);
	}

	/**
	 * The stance for a weapon: its own if observed, else the one belonging to
	 * the same weapon under a different trim, else unarmed.
	 *
	 * <p>The inheritance is what makes the library cover far more than it has
	 * seen. An ornament kit, a trimmed or gilded version, a poisoned dagger, a
	 * charged or degraded state - all are the same weapon wearing a different
	 * name, and all animate identically. Checked before shipping: of the 13
	 * base-name groups the observed data contains, all 13 agree on their
	 * stance with no exceptions.
	 *
	 * <p>Failing that, the same weapon in a different metal: an Adamant
	 * longsword animates like a Black one. See {@link #tierBaseName(String)}
	 * for why that covers the plain tiers only.
	 *
	 * <p>Deliberately NOT a fuzzy match. Allowing one name to be a subset of
	 * another was measured at 96% - it equates "Dragon axe" with "Dragon
	 * felling axe" - and a wrong animation is worse than a plain one. Both
	 * inheritance steps above are exact matches on what is left after a known
	 * marker is removed, which is why they do not have that failure.
	 */
	public Stance forWeapon(int weaponItemId)
	{
		int id = weaponItemId <= 0 ? UNARMED : weaponItemId;
		Stance stance = stances.get(id);
		if (stance != null)
		{
			return stance;
		}
		Stance inherited = stances.get(donorFor(id));
		return inherited != null ? inherited : stances.get(UNARMED);
	}

	/** The weapon this one inherits its stance from, or 0 when there is none. */
	private int donorFor(int weaponItemId)
	{
		Integer cached = donors.get(weaponItemId);
		if (cached != null)
		{
			return cached;
		}

		if (byBaseName == null || indexedSize != stances.size())
		{
			buildNameIndex();
		}

		int donor = 0;
		String name = models.itemName(weaponItemId);
		String base = baseName(name);
		if (base != null)
		{
			Integer match = byBaseName.get(base);
			if (match != null && match != weaponItemId)
			{
				donor = match;
			}
		}
		// Second chance: the same weapon in a different metal.
		if (donor == 0)
		{
			String tierBase = tierBaseName(name);
			if (tierBase != null)
			{
				Integer match = byTierName.get(tierBase);
				if (match != null && match != weaponItemId)
				{
					donor = match;
				}
			}
		}
		donors.put(weaponItemId, donor);
		return donor;
	}

	private void buildNameIndex()
	{
		byBaseName = new HashMap<>();
		byTierName = new HashMap<>();
		for (Integer known : stances.keySet())
		{
			String name = models.itemName(known);
			String base = baseName(name);
			if (base != null)
			{
				// Lowest id wins: the plain version rather than a variant.
				byBaseName.merge(base, known, Math::min);
			}
			String tierBase = tierBaseName(name);
			if (tierBase != null)
			{
				byTierName.merge(tierBase, known, Math::min);
			}
		}
		indexedSize = stances.size();
		// Names may have arrived since the last resolution failed.
		donors.clear();
	}

	/**
	 * An item name with its metal tier removed, so "Adamant longsword" and
	 * "Black longsword" both become "longsword" - one weapon in two metals,
	 * which animate alike.
	 *
	 * <p>Returns null for anything that does not carry one of these tiers, so
	 * only tiered weapons ever join this index and an untiered weapon can never
	 * be pulled into a group by its noun alone.
	 *
	 * <p>Deliberately excludes dragon, crystal, gilded, 3rd age and the other
	 * ornamental tiers, which the game special-cases. That is measured, not
	 * assumed: across the observed library the plain metal tiers agree on their
	 * stance in all 5 groups that have more than one tier, with no exceptions,
	 * while including the special tiers introduces a real counterexample - the
	 * Dragon longsword stands at 809 where the Black longsword stands at 808.
	 * Admitting them would cover about 65 more weapons at the cost of being
	 * wrong about some of them, and a wrong animation is worse than a plain one.
	 */
	static String tierBaseName(String name)
	{
		String base = baseName(name);
		if (base == null)
		{
			return null;
		}
		java.util.regex.Matcher matcher = TIER_PREFIX.matcher(base);
		if (!matcher.find())
		{
			return null;
		}
		String stripped = base.substring(matcher.end()).trim();
		return stripped.isEmpty() ? null : stripped;
	}

	/** Plain metal tiers only - see {@link #tierBaseName(String)}. */
	private static final java.util.regex.Pattern TIER_PREFIX = java.util.regex.Pattern.compile(
		"^(bronze|iron|steel|black|white|mithril|adamant|rune|runite)\\s+");

	/**
	 * An item name with its variant markers removed, so every version of a
	 * weapon collapses to one key: "Abyssal whip (or)", "Dragon dagger(p++)"
	 * and "Dharok's greataxe 25" become "abyssal whip", "dragon dagger" and
	 * "dharok's greataxe".
	 *
	 * <p>Any trailing bracket goes, rather than a list of known markers. The
	 * list was the original approach and it silently rotted: it knew (p) but
	 * not (kp), so every karambwan-poisoned spear and hasta in the game sat
	 * uncovered next to the plain ones it should have inherited from, and the
	 * same held for the Bounty Hunter (bh) weapons, the Gauntlet's basic,
	 * attuned and perfected tiers, the blackjacks' (o) and (d), and charge
	 * counts like "Enchanted lyre(2)". Every marker the game has ever put in
	 * brackets denotes a state of the same weapon, never a different one.
	 *
	 * <p>Measured before adopting: stripping every trailing bracket collapses
	 * the observed library into 16 multi-item groups, and all 16 agree on their
	 * stance with no exceptions. The match stays EXACT on what remains, which
	 * is what keeps "Toxic staff (uncharged)" away from "Toxic staff of the
	 * dead" and why this does not reintroduce the fuzzy matching that was
	 * rejected at 96%.
	 */
	static String baseName(String name)
	{
		if (name == null || name.isEmpty() || "null".equals(name))
		{
			return null;
		}
		String base = name.toLowerCase(java.util.Locale.ROOT).trim();
		// Some items carry two markers, "(bh)(p++)", so strip repeatedly.
		String previous;
		do
		{
			previous = base;
			base = VARIANT_SUFFIX.matcher(base).replaceAll("").trim();
		}
		while (!base.equals(previous));
		base = DEGRADE_SUFFIX.matcher(base).replaceAll("").trim();
		return base.isEmpty() ? null : base;
	}

	/** Any bracketed marker: ornament, trim, poison, charge, tier, lock. */
	private static final java.util.regex.Pattern VARIANT_SUFFIX =
		java.util.regex.Pattern.compile("\\s*\\([^)]*\\)\\s*$");

	/** Trailing wear or charge level: "Dharok's greataxe 75". */
	private static final java.util.regex.Pattern DEGRADE_SUFFIX =
		java.util.regex.Pattern.compile("\\s+\\d+$");

	public boolean knows(int weaponItemId)
	{
		int id = weaponItemId <= 0 ? UNARMED : weaponItemId;
		return stances.containsKey(id) || donorFor(id) > 0;
	}

	public int size()
	{
		return stances.size();
	}
}

package com.follower.follower;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;

/**
 * An AnimationController that interpolates ACROSS the loop boundary.
 *
 * <p>The client's own smoothing glides every frame toward the next one - except
 * the last. RSSequenceDefinition sets {@code nextFrame = -1} when
 * {@code frame + 1} runs off the end ("the last frame is not interpolated"), so
 * the final frame of every looping animation is held statically for its full
 * duration and then snaps to the loop target. That hold is the skip. It exists
 * for real players too, but Jagex authors loops so the last pose sits close to
 * the first, which keeps it invisible on actors; the follower's poses showed it
 * plainly.
 *
 * <p>The fix: let the client do what it already does correctly - every frame
 * except the last - and take over only the final segment. Both endpoints of the
 * missing transition are obtainable as exact static poses
 * ({@code applyTransformations} with an unpacked frame index), so the wrap
 * becomes a vertex lerp between the true last pose and the true loop-target
 * pose, advanced by the same elapsed-tick clock the client uses. Adjacent
 * animation frames are small deltas, where a linear vertex blend and the
 * client's transform-level blend are visually indistinguishable.
 *
 * <p>Only active while animation smoothing accepts this animation id; with
 * smoothing off, nothing interpolates anywhere and the wrap is no different
 * from any other frame boundary.
 */
@Slf4j
public class WrapLerpController extends AnimationController
{
	private final Client client;

	/** Ticks elapsed within the current frame, approximated by observation. */
	private int elapsedInFrame;
	private int lastSeenFrame = -1;

	/**
	 * Endpoint poses snapshotted as flat xyz arrays. applyTransformations returns a
	 * model backed by the client's shared animation scratch buffer - the same arrays
	 * every call, overwritten - so holding Model references meant all "endpoints"
	 * aliased one buffer. Copying the floats out immediately sidesteps that.
	 */
	private float[] lastXyz;
	private float[] targetXyz;

	private int cachedAnimationId = -1;

	/**
	 * Set when the render temp is not safe to write; the lerp disables rather than
	 * corrupt models, and the measured trim takes over. Leaving just that frame to
	 * the client would not do: the same last frame comes round every loop, and it
	 * would hold and snap each time with no trim to hide it.
	 */
	private boolean unsafe;

	public WrapLerpController(Client client, Animation animation)
	{
		super(client, animation);
		this.client = client;
	}

	@Override
	public void tick(int ticks)
	{
		int before = getFrame();
		super.tick(ticks);

		// Track progress within the frame by observation rather than mirroring the
		// stepping algorithm: external setFrame calls and onFinished handlers can
		// move the frame in ways a mirror would drift from. The reset loses the
		// consumed remainder (a tick or two of 20+), invisible in a lerp fraction.
		if (getFrame() != before)
		{
			elapsedInFrame = 0;
			lastSeenFrame = getFrame();
		}
		else
		{
			elapsedInFrame += ticks;
		}
	}

	@Override
	public Model animate(Model model, AnimationController other)
	{
		Animation animation = getAnimation();
		if (animation == null || other != null || unsafe
			|| animation.isMayaAnim() || !smoothingAccepts(animation))
		{
			return super.animate(model, other);
		}

		int[] lengths = animation.getFrameLengths();
		int frame = getFrame();
		if (lengths == null || lengths.length < 2 || frame != lengths.length - 1)
		{
			return super.animate(model, other);
		}

		ensureEndpoints(model, animation, lengths.length);
		if (lastXyz == null || targetXyz == null)
		{
			return super.animate(model, other);
		}

		// The blend is written into the model the base controller returns: the
		// client's shared per-frame temp, which the client itself hands straight to
		// the renderer for every animated frame. Never into the base, though - a
		// frame with no transform can come back as the base itself, or sharing its
		// vertex arrays, and writing there would bend the follower's model for good.
		Model temp = super.animate(model, other);
		if (temp == null)
		{
			return null;
		}

		boolean separate = temp != model
			&& temp.getVerticesX() != model.getVerticesX()
			&& temp.getVerticesY() != model.getVerticesY()
			&& temp.getVerticesZ() != model.getVerticesZ();
		boolean sized = temp.getVerticesCount() * 3 == lastXyz.length
			&& lastXyz.length == targetXyz.length;
		if (!separate || !sized)
		{
			log.warn("Render temp is not safe to write (separate={}, sized={}); "
				+ "wrap interpolation disabled for this session", separate, sized);
			unsafe = true;
			lastXyz = null;
			targetXyz = null;
			return temp;
		}

		float t = Math.min(1f, elapsedInFrame / (float) Math.max(1, lengths[frame]));
		lerpInto(temp, lastXyz, targetXyz, t);
		return temp;
	}

	/** True when the safety guard has switched the lerp off for this session. */
	public boolean isDisabled()
	{
		return unsafe;
	}

	private boolean smoothingAccepts(Animation animation)
	{
		java.util.function.IntPredicate filter = client.getAnimationInterpolationFilter();
		return filter != null && filter.test(animation.getId());
	}

	/**
	 * The frame the default loop lands on, replicating AnimationController.loop():
	 * step back frameStep from the end, falling back to 0 when out of range.
	 */
	private int loopTargetFrame(Animation animation, int frames)
	{
		int target = frames - animation.getFrameStep();
		return target < 0 || target >= animation.getDuration() ? 0 : target;
	}

	private void ensureEndpoints(Model base, Animation animation, int frames)
	{
		if (cachedAnimationId == animation.getId())
		{
			return;
		}
		cachedAnimationId = animation.getId();
		lastXyz = null;
		targetXyz = null;

		// Snapshot each endpoint IMMEDIATELY - the next applyTransformations call
		// (ours or any animating actor's) overwrites the shared scratch buffer.
		lastXyz = snapshot(client.applyTransformations(base, animation, frames - 1, null, 0));
		targetXyz = snapshot(client.applyTransformations(base, animation,
			loopTargetFrame(animation, frames), null, 0));
	}

	/** Flattens a posed model's vertices into an owned array, or null. */
	private static float[] snapshot(Model posed)
	{
		if (posed == null || posed.getVerticesX() == null)
		{
			return null;
		}

		int count = posed.getVerticesCount();
		float[] outXyz = new float[count * 3];
		float[] x = posed.getVerticesX();
		float[] y = posed.getVerticesY();
		float[] z = posed.getVerticesZ();
		for (int i = 0; i < count; i++)
		{
			outXyz[i * 3] = x[i];
			outXyz[i * 3 + 1] = y[i];
			outXyz[i * 3 + 2] = z[i];
		}
		return outXyz;
	}

	private static void lerpInto(Model dest, float[] from, float[] to, float t)
	{
		int count = dest.getVerticesCount();
		float[] dx = dest.getVerticesX();
		float[] dy = dest.getVerticesY();
		float[] dz = dest.getVerticesZ();

		for (int i = 0; i < count; i++)
		{
			float ax = from[i * 3];
			float ay = from[i * 3 + 1];
			float az = from[i * 3 + 2];
			dx[i] = ax + (to[i * 3] - ax) * t;
			dy[i] = ay + (to[i * 3 + 1] - ay) * t;
			dz[i] = az + (to[i * 3 + 2] - az) * t;
		}
	}
}

package com.follower.follower;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Persists the per-animation wrap trims.
 *
 * <p>Measured values are cheap to recompute but deterministic, so saving them just
 * avoids redoing the work each session. Hand-tuned overrides are the ones that
 * genuinely must survive a restart.
 */
@Slf4j
@Singleton
public class WrapTrimStore
{
	public static final String FILE_NAME = "wrap-trims.json";

	public static class Saved
	{
		public Map<String, Integer> manual = new HashMap<>();
		public Map<String, Integer> measured = new HashMap<>();
	}

	private final Gson gson;
	private Path file;

	@Inject
	public WrapTrimStore(Gson gson)
	{
		this.gson = gson;
	}

	public void load(Path dataDir, FollowerEntity follower)
	{
		file = dataDir.resolve(FILE_NAME);
		if (!Files.isRegularFile(file))
		{
			return;
		}

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			Saved saved = gson.fromJson(reader, new TypeToken<Saved>()
			{
			}.getType());

			if (saved != null)
			{
				follower.restoreTrims(toIntKeys(saved.manual), toIntKeys(saved.measured));
				log.info("Loaded {} measured and {} manual wrap trims",
					saved.measured == null ? 0 : saved.measured.size(),
					saved.manual == null ? 0 : saved.manual.size());
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read {}", file, e);
		}
	}

	public void save(FollowerEntity follower)
	{
		if (file == null)
		{
			return;
		}

		Saved saved = new Saved();
		saved.manual = toStringKeys(follower.getWrapTrims());
		saved.measured = toStringKeys(follower.getMeasuredTrims());

		if (saved.manual.isEmpty() && saved.measured.isEmpty())
		{
			return;
		}

		try
		{
			Files.createDirectories(file.getParent());
			try (Writer writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8))
			{
				gson.toJson(saved, writer);
			}
			log.info("Saved {} measured and {} manual wrap trims",
				saved.measured.size(), saved.manual.size());
		}
		catch (IOException e)
		{
			log.warn("Could not write {}", file, e);
		}
	}

	private static Map<String, Integer> toStringKeys(Map<Integer, Integer> source)
	{
		Map<String, Integer> out = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : source.entrySet())
		{
			out.put(Integer.toString(entry.getKey()), entry.getValue());
		}
		return out;
	}

	private static Map<Integer, Integer> toIntKeys(Map<String, Integer> source)
	{
		Map<Integer, Integer> out = new HashMap<>();
		if (source == null)
		{
			return out;
		}
		for (Map.Entry<String, Integer> entry : source.entrySet())
		{
			try
			{
				out.put(Integer.parseInt(entry.getKey()), entry.getValue());
			}
			catch (NumberFormatException ignored)
			{
				// Skip malformed key.
			}
		}
		return out;
	}
}

package com.follower.share;

import com.follower.sound.VoiceLibrary;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;
import lombok.extern.slf4j.Slf4j;

/**
 * Packs: what one player has written, in a file they can hand to another.
 *
 * <p>A pack holds the customisations and nothing else. Exporting the whole rule
 * file would be simpler and much worse - two thousand lines of shipped content
 * would ride along, clobber whatever the recipient had written themselves, and
 * freeze them at the exporter's version of everything the plugin updates. So
 * the pack is a DIFF against the shipped defaults: rules that were added, lines
 * that were added to rules that already existed, and the sounds attached to any
 * of them.
 *
 * <p>Importing merges and never replaces, which is the same promise the startup
 * merge makes. A rule both people have gains the incoming lines rather than
 * losing the existing ones, so importing a friend's bank lines deepens the pool
 * instead of substituting for it.
 *
 * <p>Everything here treats the file as hostile, because a pack arrives from
 * somebody else: entry names are matched against a fixed list rather than
 * trusted as paths, sizes are capped before anything is read into memory, and
 * every line is put through the same rules the shipped ones must satisfy - a
 * line the game's bitmap font cannot draw is not a line, whoever wrote it.
 */
@Slf4j
public final class PackFile
{
	/** Names a pack may contain. Anything else is ignored, not resolved. */
	private static final String MANIFEST = "pack.json";
	private static final String RULES = "rules.json";
	private static final String SOUND_MAP = "sounds.json";
	private static final String SOUND_DIR = "sounds/";

	/** Caps, applied before reading, so a hostile pack cannot exhaust memory. */
	private static final int MAX_ENTRIES = 300;
	private static final long MAX_TOTAL_BYTES = 64L * 1024 * 1024;
	private static final long MAX_ENTRY_BYTES = 8L * 1024 * 1024;

	/** What a line has to be, whoever wrote it. Matches the shipped lints. */
	private static final int MAX_LINE = 85;

	/** Bulk caps. A pack must not be able to bury the player's own file. */
	private static final int MAX_RULES = 500;
	private static final int MAX_LINES = 5000;
	private static final int MAX_ID = 64;

	/** How deep the JSON may nest before we stop, rather than overflow. */
	private static final int MAX_DEPTH = 64;

	/** How much of a pack's own text we will ever put on screen. */
	private static final int MAX_SHOWN = 40;

	/**
	 * Names Windows opens as devices whatever extension is hung on them, and
	 * in whatever directory they appear. Writing to COM1 does not write a file.
	 */
	private static final Set<String> RESERVED = new HashSet<>(java.util.Arrays.asList(
		"con", "prn", "aux", "nul",
		"com1", "com2", "com3", "com4", "com5", "com6", "com7", "com8", "com9",
		"lpt1", "lpt2", "lpt3", "lpt4", "lpt5", "lpt6", "lpt7", "lpt8", "lpt9"));

	private PackFile()
	{
	}

	/** What a pack turned out to contain, for the report shown to the player. */
	public static final class Summary
	{
		public String name = "";
		public String author = "";
		public int rules;
		public int lines;
		public int sounds;
		public long bytes;
		public final List<String> problems = new ArrayList<>();

		public boolean isEmpty()
		{
			return rules == 0 && lines == 0 && sounds == 0;
		}
	}

	// ------------------------------------------------------------------ export

	/**
	 * Writes everything the player has added to a pack.
	 *
	 * @param shipped the plugin's own defaults, to diff against
	 */
	public static Summary export(Path zip, JsonObject mine, JsonObject shipped,
		VoiceLibrary voices, Gson gson, String author) throws IOException
	{
		Map<String, JsonObject> theirs = byId(shipped);
		JsonArray carried = new JsonArray();
		Set<String> carriedLines = new HashSet<>();
		Summary summary = new Summary();

		for (JsonElement element : mine.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			String id = optString(rule, "id");
			if (id.isEmpty() || !rule.has("say") || !rule.get("say").isJsonArray())
			{
				continue;
			}
			JsonObject original = theirs.get(id);

			if (original == null)
			{
				// Wholly the player's own: goes as it stands.
				carried.add(rule);
				summary.rules++;
				for (JsonElement line : rule.getAsJsonArray("say"))
				{
					carriedLines.add(line.getAsString());
					summary.lines++;
				}
				continue;
			}

			// A shipped rule the player has written into. Only the added lines
			// travel: the rest is the recipient's own copy to keep.
			Set<String> was = lines(original);
			JsonArray extra = new JsonArray();
			for (JsonElement line : rule.getAsJsonArray("say"))
			{
				if (!was.contains(line.getAsString()))
				{
					extra.add(line);
					carriedLines.add(line.getAsString());
				}
			}
			if (extra.size() > 0)
			{
				JsonObject slim = new JsonObject();
				slim.addProperty("id", id);
				slim.add("say", extra);
				carried.add(slim);
				summary.rules++;
				summary.lines += extra.size();
			}
		}

		// Only the sounds belonging to lines that are actually travelling.
		Map<String, String> soundMap = new LinkedHashMap<>();
		for (String line : carriedLines)
		{
			String file = voices.attachmentFor(line);
			if (file != null)
			{
				soundMap.put(line, file);
			}
		}

		JsonObject manifest = new JsonObject();
		manifest.addProperty("format", 1);
		manifest.addProperty("name", zip.getFileName().toString().replace(".zip", ""));
		manifest.addProperty("author", author == null ? "" : author);

		try (ZipOutputStream out = new ZipOutputStream(Files.newOutputStream(zip)))
		{
			write(out, MANIFEST, gson.toJson(manifest));
			JsonObject rules = new JsonObject();
			rules.add("rules", carried);
			write(out, RULES, gson.toJson(rules));
			write(out, SOUND_MAP, gson.toJson(soundMap));

			Set<String> written = new HashSet<>();
			for (String file : soundMap.values())
			{
				if (!written.add(file))
				{
					continue;
				}
				Path source = voices.getSoundsFolder().resolve(file);
				if (!Files.isRegularFile(source))
				{
					summary.problems.add("missing sound file, not included: " + file);
					continue;
				}
				long size = Files.size(source);
				if (size > MAX_ENTRY_BYTES)
				{
					summary.problems.add("too large to share, left out: " + file);
					continue;
				}
				out.putNextEntry(new ZipEntry(SOUND_DIR + file));
				Files.copy(source, out);
				out.closeEntry();
				summary.sounds++;
				summary.bytes += size;
			}
		}
		return summary;
	}

	private static void write(ZipOutputStream out, String name, String body) throws IOException
	{
		out.putNextEntry(new ZipEntry(name));
		out.write(body.getBytes(StandardCharsets.UTF_8));
		out.closeEntry();
	}

	// ------------------------------------------------------------------ import

	/** Everything a pack holds, read and checked but not yet applied. */
	public static final class Loaded
	{
		public final Summary summary = new Summary();
		public JsonArray rules = new JsonArray();
		public Map<String, String> sounds = new LinkedHashMap<>();
		public final Map<String, byte[]> audio = new LinkedHashMap<>();
	}

	/**
	 * Reads a pack without applying any of it, so the player can be shown what
	 * they are about to accept before they accept it.
	 */
	public static Loaded read(Path zip, Gson gson) throws IOException
	{
		Loaded loaded = new Loaded();
		long total = 0;
		int entries = 0;

		try (ZipInputStream in = new ZipInputStream(Files.newInputStream(zip)))
		{
			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				if (++entries > MAX_ENTRIES)
				{
					loaded.summary.problems.add("too many files in the pack; stopped reading");
					break;
				}
				String name = entry.getName();
				if (entry.isDirectory() || !safe(name))
				{
					continue;
				}

				byte[] body = read(in, MAX_ENTRY_BYTES);
				if (body == null)
				{
					loaded.summary.problems.add("a file in the pack was too large: " + name);
					continue;
				}
				total += body.length;
				if (total > MAX_TOTAL_BYTES)
				{
					loaded.summary.problems.add("the pack is too large; stopped reading");
					break;
				}

				if (MANIFEST.equals(name))
				{
					JsonObject manifest = parse(body, gson);
					if (manifest != null)
					{
						loaded.summary.name = forDisplay(optString(manifest, "name"));
						loaded.summary.author = forDisplay(optString(manifest, "author"));
					}
				}
				else if (RULES.equals(name))
				{
					JsonObject parsed = parse(body, gson);
					if (parsed != null && parsed.has("rules")
						&& parsed.get("rules").isJsonArray())
					{
						loaded.rules = parsed.getAsJsonArray("rules");
					}
				}
				else if (SOUND_MAP.equals(name))
				{
					JsonObject parsed = parse(body, gson);
					if (parsed != null)
					{
						for (Map.Entry<String, JsonElement> pair : parsed.entrySet())
						{
							if (pair.getValue().isJsonPrimitive())
							{
								loaded.sounds.put(pair.getKey(), pair.getValue().getAsString());
							}
						}
					}
				}
				else if (name.startsWith(SOUND_DIR))
				{
					String file = name.substring(SOUND_DIR.length());
					if (playable(file))
					{
						loaded.audio.put(file, body);
						loaded.summary.bytes += body.length;
					}
					else
					{
						loaded.summary.problems.add("not a sound the game can play: " + file);
					}
				}
			}
		}

		// Now the content itself, which is the half that reaches the screen.
		JsonArray checked = new JsonArray();
		for (JsonElement element : loaded.rules)
		{
			if (!element.isJsonObject())
			{
				continue;
			}
			JsonObject rule = element.getAsJsonObject();
			String id = optString(rule, "id");
			if (!idIsOurs(id) || !rule.has("say") || !rule.get("say").isJsonArray())
			{
				loaded.summary.problems.add("a rule with no lines, or an id that is not"
					+ " one of ours, was left out");
				continue;
			}
			if (loaded.summary.rules >= MAX_RULES || loaded.summary.lines >= MAX_LINES)
			{
				loaded.summary.problems.add("the pack holds more than we will take on;"
					+ " the rest was left out");
				break;
			}
			JsonArray good = new JsonArray();
			for (JsonElement line : rule.getAsJsonArray("say"))
			{
				if (loaded.summary.lines + good.size() >= MAX_LINES)
				{
					loaded.summary.problems.add("more lines than we will take on; the"
						+ " rest of " + id + " was left out");
					break;
				}
				String text = line.isJsonPrimitive() ? line.getAsString() : "";
				String fault = faultIn(text);
				if (fault == null)
				{
					good.add(text);
				}
				else
				{
					loaded.summary.problems.add(fault + ": " + shorten(text));
				}
			}
			if (good.size() == 0)
			{
				continue;
			}
			rule.add("say", good);
			checked.add(rule);
			loaded.summary.rules++;
			loaded.summary.lines += good.size();
		}
		loaded.rules = checked;
		loaded.summary.sounds = loaded.audio.size();
		return loaded;
	}

	/**
	 * A line the game cannot draw is not a line, whoever wrote it. The same
	 * three rules the shipped content is held to.
	 */
	private static String faultIn(String line)
	{
		if (line == null || line.trim().isEmpty())
		{
			return "empty line";
		}
		if (line.length() > MAX_LINE)
		{
			return "too long to read in the time it is shown";
		}
		for (int i = 0; i < line.length(); i++)
		{
			char c = line.charAt(i);
			if (c > 0x7F)
			{
				return "has a character the game's font cannot draw";
			}
			if (c < 0x20)
			{
				return "has a control character in it";
			}
			if (c == '<' || c == '>')
			{
				// Spoken lines can be mirrored into the chatbox, and
				// the chatbox reads Jagex markup: <col=ff0000>, <br>, <img=N>.
				// A stranger's tag would render on somebody's screen in
				// whatever colour and with whatever icon it asked for, which
				// is how a line becomes a forged system message. No shipped
				// line needs either bracket, so neither does anybody else's.
				return "has chat markup in it";
			}
		}
		return null;
	}

	/**
	 * An id is a key in our own bookkeeping rather than free text: it names
	 * cooldowns, matches rules across two people's files, and reaches the log.
	 */
	private static boolean idIsOurs(String id)
	{
		if (id.isEmpty() || id.length() > MAX_ID)
		{
			return false;
		}
		for (int i = 0; i < id.length(); i++)
		{
			char c = id.charAt(i);
			boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
				|| (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.';
			if (!ok)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Gson parses by recursion, so JSON nested deeply enough overflows the
	 * stack - and a StackOverflowError is an Error, which sails straight past
	 * the catch (Exception) around the import and out of the action listener.
	 * Depth is counted first, on the raw text, so the parser is never handed
	 * anything that could do it.
	 */
	private static JsonObject parse(byte[] body, Gson gson)
	{
		String text = new String(body, StandardCharsets.UTF_8);
		int depth = 0;
		boolean inString = false;
		boolean escaped = false;
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (escaped)
			{
				escaped = false;
			}
			else if (inString)
			{
				if (c == '\\')
				{
					escaped = true;
				}
				else if (c == '\"')
				{
					inString = false;
				}
			}
			else if (c == '\"')
			{
				inString = true;
			}
			else if (c == '{' || c == '[')
			{
				if (++depth > MAX_DEPTH)
				{
					return null;
				}
			}
			else if (c == '}' || c == ']')
			{
				depth--;
			}
		}
		try
		{
			return gson.fromJson(text, JsonObject.class);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			// Belt as well as braces. The count above should mean this never
			// fires, and a pack that finds a way past it is still refused
			// rather than thrown out of the window that asked for it.
			log.warn("Unreadable JSON in a pack", e);
			return null;
		}
	}

	/**
	 * Whether an entry name is one of ours. Matched against the fixed set
	 * rather than resolved as a path: a name is never turned into a location
	 * on disk, so there is nothing for a crafted one to escape into.
	 */
	private static boolean safe(String name)
	{
		if (name.contains("..") || name.startsWith("/") || name.contains("\\")
			|| name.contains(":"))
		{
			return false;
		}
		if (MANIFEST.equals(name) || RULES.equals(name) || SOUND_MAP.equals(name))
		{
			return true;
		}
		return name.startsWith(SOUND_DIR)
			&& name.indexOf('/', SOUND_DIR.length()) < 0
			&& name.length() > SOUND_DIR.length();
	}

	private static boolean playable(String file)
	{
		String lower = file.toLowerCase(Locale.ROOT);
		int dot = lower.indexOf('.');
		if (RESERVED.contains(dot < 0 ? lower : lower.substring(0, dot)))
		{
			return false;
		}
		return lower.endsWith(".wav") || lower.endsWith(".aif")
			|| lower.endsWith(".aiff") || lower.endsWith(".au");
	}

	private static byte[] read(InputStream in, long cap) throws IOException
	{
		java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();
		byte[] chunk = new byte[8192];
		long total = 0;
		int read;
		while ((read = in.read(chunk)) > 0)
		{
			total += read;
			if (total > cap)
			{
				return null;
			}
			buffer.write(chunk, 0, read);
		}
		return buffer.toByteArray();
	}

	/**
	 * Folds a read pack into the player's own files.
	 *
	 * @return what was actually taken on
	 */
	public static Summary apply(Loaded loaded, JsonObject mine, Path soundsFolder,
		VoiceLibrary voices) throws IOException
	{
		Summary applied = new Summary();
		Map<String, JsonObject> ours = byId(mine);
		JsonArray rules = mine.getAsJsonArray("rules");

		// Sound files first, so the attachments below can point at their real
		// names - a name already taken here belongs to a different recording.
		Map<String, String> renamed = new HashMap<>();
		Files.createDirectories(soundsFolder);
		for (Map.Entry<String, byte[]> file : loaded.audio.entrySet())
		{
			String name = file.getKey();
			Path target = soundsFolder.resolve(name);
			if (Files.exists(target))
			{
				if (same(target, file.getValue()))
				{
					// Already here, byte for byte. Importing the same pack
					// twice should be a no-op, not a folder full of -2, -3, -4.
					continue;
				}
				String stem = name.contains(".")
					? name.substring(0, name.lastIndexOf('.')) : name;
				String extension = name.substring(stem.length());
				for (int n = 2; Files.exists(target); n++)
				{
					name = stem + "-" + n + extension;
					target = soundsFolder.resolve(name);
				}
				renamed.put(file.getKey(), name);
			}
			Files.write(target, file.getValue());
			applied.sounds++;
			applied.bytes += file.getValue().length;
		}

		for (JsonElement element : loaded.rules)
		{
			JsonObject incoming = element.getAsJsonObject();
			String id = optString(incoming, "id");
			JsonObject existing = ours.get(id);

			if (existing == null)
			{
				if (!incoming.has("when"))
				{
					// Lines for a rule this player does not have. Adding them
					// would make a rule with nothing to fire it, which is worse
					// than saying so: their phrases.json is older than the
					// sender's, and the lines have nowhere to live yet.
					applied.problems.add("lines for a rule you do not have: " + id);
					continue;
				}
				rules.add(incoming);
				applied.rules++;
				applied.lines += incoming.getAsJsonArray("say").size();
				continue;
			}

			// Merge, never replace: their lines join yours.
			Set<String> have = lines(existing);
			JsonArray say = existing.getAsJsonArray("say");
			int added = 0;
			for (JsonElement line : incoming.getAsJsonArray("say"))
			{
				if (have.add(line.getAsString()))
				{
					say.add(line);
					added++;
				}
			}
			if (added > 0)
			{
				applied.rules++;
				applied.lines += added;
			}
		}

		// A pack may only give a voice to lines it actually carried, and only
		// where the player has not already given that line one of their own.
		// The sound map is a file of its own, so without this it could name
		// any line in the recipient's install - one that ships, or one they
		// had recorded themselves - and quietly speak over it.
		Set<String> arrived = new HashSet<>();
		for (JsonElement element : loaded.rules)
		{
			arrived.addAll(lines(element.getAsJsonObject()));
		}
		for (Map.Entry<String, String> pair : loaded.sounds.entrySet())
		{
			String line = pair.getKey();
			if (!loaded.audio.containsKey(pair.getValue()))
			{
				continue;
			}
			if (!arrived.contains(line))
			{
				applied.problems.add("a sound for a line the pack did not bring: "
					+ shorten(line));
				continue;
			}
			if (voices.attachmentFor(line) != null)
			{
				applied.problems.add("kept your own recording for: " + shorten(line));
				continue;
			}
			voices.attach(line, renamed.getOrDefault(pair.getValue(), pair.getValue()));
		}
		return applied;
	}

	// ------------------------------------------------------------------ shared

	private static boolean same(Path file, byte[] body)
	{
		try
		{
			return Files.size(file) == body.length
				&& java.util.Arrays.equals(Files.readAllBytes(file), body);
		}
		catch (IOException e)
		{
			return false;
		}
	}

	private static Map<String, JsonObject> byId(JsonObject file)
	{
		Map<String, JsonObject> map = new HashMap<>();
		if (file == null || !file.has("rules") || !file.get("rules").isJsonArray())
		{
			return map;
		}
		for (JsonElement element : file.getAsJsonArray("rules"))
		{
			if (element.isJsonObject())
			{
				String id = optString(element.getAsJsonObject(), "id");
				if (!id.isEmpty())
				{
					map.put(id, element.getAsJsonObject());
				}
			}
		}
		return map;
	}

	private static Set<String> lines(JsonObject rule)
	{
		Set<String> set = new HashSet<>();
		if (rule.has("say") && rule.get("say").isJsonArray())
		{
			for (JsonElement line : rule.getAsJsonArray("say"))
			{
				if (line.isJsonPrimitive())
				{
					set.add(line.getAsString());
				}
			}
		}
		return set;
	}

	private static String optString(JsonObject object, String key)
	{
		return object.has(key) && object.get(key).isJsonPrimitive()
			? object.get(key).getAsString() : "";
	}

	/**
	 * Text from a pack, made fit to put in front of somebody.
	 *
	 * <p>The import dialog is where the player decides whether to trust the
	 * pack, which makes it the last place its author should get to write. A
	 * newline in an author name, or in a refused line quoted back in the
	 * "left out" list, forges a line in that dialog - room enough for a
	 * reassurance nobody wrote. Angle brackets go too: Swing renders a label
	 * as HTML when the string opens with one, and the rule is easier to keep
	 * than the audit of every message that might one day begin with this.
	 */
	private static String forDisplay(String text)
	{
		if (text == null)
		{
			return "";
		}
		StringBuilder clean = new StringBuilder(Math.min(text.length(), MAX_SHOWN));
		for (int i = 0; i < text.length() && clean.length() < MAX_SHOWN; i++)
		{
			char c = text.charAt(i);
			clean.append(c < 0x20 || c > 0x7E || c == '<' || c == '>' ? ' ' : c);
		}
		String out = clean.toString().trim();
		return text.length() > MAX_SHOWN ? out + "..." : out;
	}

	private static String shorten(String text)
	{
		return forDisplay(text);
	}

	/** The plugin's own defaults, for the diff. */
	public static JsonObject shippedRules(Gson gson)
	{
		try (InputStream in = PackFile.class
			.getResourceAsStream("/com/follower/default-phrases.json"))
		{
			return in == null ? null
				: gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
					JsonObject.class);
		}
		catch (IOException e)
		{
			log.warn("Could not read the bundled defaults for the pack diff", e);
			return null;
		}
	}

	/** Writes a JSON file back out, used after an import. */
	public static void save(Path file, JsonObject data, Gson gson) throws IOException
	{
		try (OutputStream out = Files.newOutputStream(file))
		{
			out.write((gson.toJson(data) + "\n").getBytes(StandardCharsets.UTF_8));
		}
	}
}

package com.follower.sound;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.audio.AudioPlayer;
import lombok.extern.slf4j.Slf4j;

/**
 * The follower's voice: a sound file the player has attached to a line, played
 * when that line is spoken.
 *
 * <p>Keyed by the LINE ITSELF rather than by rule and index. A recording is of
 * particular words, so it belongs to those words: reorder a rule's lines and
 * every recording still follows its own line, and reword a line and the link
 * breaks, which is correct - the recording no longer says what the line says.
 * It also means the two thousand lines the plugin ships can be voiced exactly
 * like the ones the player writes, with no distinction anywhere in the code.
 *
 * <p>Nothing is bundled. The plugin ships no audio at all and never fetches
 * any: the player drops their own files into the sounds folder, which is the
 * only arrangement that is unambiguously theirs to make.
 *
 * <p>Java plays WAV, AIFF and AU and nothing else without help, which is worth
 * saying plainly in the interface rather than letting somebody discover it with
 * an MP3 and a silence.
 *
 * <p>Playback goes through RuneLite's own {@link AudioPlayer} rather than
 * {@code javax.sound} directly, which the Hub requires and which turns out to
 * be the smaller code anyway: it opens a line per sound and closes it when the
 * sound ends, and it closes the previous line before starting the next - so
 * the one mouth this used to keep by hand is simply how it behaves.
 */
@Slf4j
@Singleton
public class VoiceLibrary
{
	public static final String FILE_NAME = "sounds.json";

	/** Where the player's own recordings live, beside the rules that use them. */
	public static final String SOUND_DIR = "sounds";

	/** What Java can open without a decoder on the classpath. */
	private static final Set<String> PLAYABLE =
		new HashSet<>(java.util.Arrays.asList(".wav", ".aif", ".aiff", ".au"));

	private final Gson gson;
	private final AudioPlayer audio;

	private Path file;
	private Path sounds;

	/** Line text to file name. Insertion-ordered so the file reads sensibly. */
	private Map<String, String> attached = new LinkedHashMap<>();


	/** Files that failed to open; remembered so a broken one is logged once. */
	private final Set<String> refused = new HashSet<>();


	@Inject
	public VoiceLibrary(Gson gson, AudioPlayer audio)
	{
		this.gson = gson;
		this.audio = audio;
	}

	public void load(Path dataDir)
	{
		file = dataDir.resolve(FILE_NAME);
		sounds = dataDir.resolve(SOUND_DIR);
		attached = read();
		try
		{
			Files.createDirectories(sounds);
		}
		catch (IOException e)
		{
			log.warn("Could not create the sounds folder at {}", sounds, e);
		}
		log.debug("Voice library: {} line(s) with a sound", attached.size());
	}

	private Map<String, String> read()
	{
		if (file == null || !Files.isRegularFile(file))
		{
			return new LinkedHashMap<>();
		}
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			Map<String, String> parsed = gson.fromJson(reader,
				new TypeToken<LinkedHashMap<String, String>>()
				{
				}.getType());
			return parsed == null ? new LinkedHashMap<>() : parsed;
		}
		catch (IOException | JsonSyntaxException e)
		{
			// A hand-edited file that no longer parses costs the voices, not
			// the follower: it goes on speaking in text.
			log.warn("Could not read {}", file, e);
			return new LinkedHashMap<>();
		}
	}

	private void write()
	{
		if (file == null)
		{
			return;
		}
		try
		{
			Files.createDirectories(file.getParent());
			Files.write(file, (gson.toJson(attached) + "\n")
				.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.warn("Could not save {}", file, e);
		}
	}

	/** The sound files the player has put in the folder, for the picker. */
	public List<String> availableFiles()
	{
		if (sounds == null || !Files.isDirectory(sounds))
		{
			return Collections.emptyList();
		}
		List<String> found = new ArrayList<>();
		try (java.util.stream.Stream<Path> entries = Files.list(sounds))
		{
			entries.filter(Files::isRegularFile)
				.map(path -> path.getFileName().toString())
				.filter(VoiceLibrary::playable)
				.sorted(String.CASE_INSENSITIVE_ORDER)
				.forEach(found::add);
		}
		catch (IOException e)
		{
			log.warn("Could not list {}", sounds, e);
		}
		return found;
	}

	private static boolean playable(String fileName)
	{
		String lower = fileName.toLowerCase(Locale.ROOT);
		for (String extension : PLAYABLE)
		{
			if (lower.endsWith(extension))
			{
				return true;
			}
		}
		return false;
	}

	public Path getSoundsFolder()
	{
		return sounds;
	}

	/** The file attached to a line, or null. */
	public String attachmentFor(String line)
	{
		return line == null ? null : attached.get(line);
	}

	public boolean has(String line)
	{
		return attachmentFor(line) != null;
	}

	/** Attaches a file to a line, or detaches when the file is null. */
	public void attach(String line, String fileName)
	{
		if (line == null || line.isEmpty())
		{
			return;
		}
		if (fileName == null || fileName.isEmpty())
		{
			attached.remove(line);
		}
		else
		{
			attached.put(line, fileName);
		}
		write();
	}

	/**
	 * Speaks the line aloud, if a sound is attached to it.
	 *
	 * @param volume 0-100; 0 is silence and skips the work entirely
	 */
	public void play(String line, int volume)
	{
		if (volume <= 0)
		{
			return;
		}
		sound(attachmentFor(line), volume);
	}

	/** Plays a file directly, for the preview button in the editor. */
	public void preview(String fileName, int volume)
	{
		// Auditioning at nothing would look broken rather than quiet, so the
		// preview always makes a sound even with the volume slider at zero.
		sound(fileName, Math.max(1, volume));
	}

	private void sound(String fileName, int volume)
	{
		if (fileName == null || fileName.isEmpty()
			|| sounds == null || refused.contains(fileName))
		{
			return;
		}
		Path path = sounds.resolve(fileName);
		if (!Files.isRegularFile(path))
		{
			log.warn("Sound file {} is not in {}", fileName, sounds);
			refused.add(fileName);
			return;
		}
		try
		{
			audio.play(path.toFile(), gain(volume));
		}
		catch (Exception e)
		{
			// Deliberately everything: a file that will not open must not stop
			// the follower speaking, and the formats Java refuses are only the
			// commonest reason. Remembered, so it is complained about once.
			log.warn("Could not play {} - Java opens WAV, AIFF and AU only", fileName, e);
			refused.add(fileName);
		}
	}

	/**
	 * Percentage to the decibels the mixer speaks. 100 is the file as
	 * recorded, and every step down is a real halving rather than a linear
	 * fraction of a number nobody hears linearly.
	 */
	private static float gain(int volume)
	{
		return (float) (20.0 * Math.log10(Math.max(1, Math.min(100, volume)) / 100.0));
	}

	/**
	 * Forgets which files would not open, so a replaced file gets another
	 * chance next time. There are no lines of ours to release: every one
	 * belongs to {@link AudioPlayer} and closes itself when its sound ends.
	 */
	public void close()
	{
		refused.clear();
	}

	/** Re-reads the file, so hand edits and the editor agree. */
	public void reload()
	{
		attached = read();
		// A file that would not open may have been replaced by one that will.
		refused.clear();
	}

	/** How many lines currently have a voice, for the reload command to report. */
	public int attachmentCount()
	{
		return attached.size();
	}
}

package com.follower.speech;

/**
 * How much the follower talks, as a thing a player can choose.
 *
 * <p>This was a box asking for a number of milliseconds, which is a question
 * about the implementation rather than about the follower. The setting worth
 * having is the one Forspoken shipped and was widely praised for - a named
 * frequency, from barely to constantly - because "how chatty should my
 * companion be" is a preference and not a measurement.
 *
 * <p>The value is the floor between any two spoken lines. The mood scaling in
 * {@link SpeechEngine} still applies on top, so a quiet setting and a bad day
 * compound rather than fight.
 *
 * <p>Minimal exists because Quiet was not quiet enough for some people. Twelve
 * seconds between lines still allows five a minute, which reads as constant
 * to anybody who wanted the follower mostly for the company. Forty-five
 * seconds is about one remark a minute at most, and the idle wind-down scales
 * with it, so a long AFK on Minimal goes properly silent.
 */
public enum Chattiness
{
	MINIMAL("Minimal", 45_000L),
	QUIET("Quiet", 12_000L),
	OCCASIONAL("Occasional", 6_000L),
	NORMAL("Normal", 3_000L),
	CHATTY("Chatty", 1_500L);

	private final String label;
	private final long gapMs;

	Chattiness(String label, long gapMs)
	{
		this.label = label;
		this.gapMs = gapMs;
	}

	public long getGapMs()
	{
		return gapMs;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.follower.speech;

import java.util.List;
import java.util.Locale;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;

/**
 * One condition in a rule's {@code when} block. Deliberately a single flat class
 * with a {@code type} discriminator and optional fields, so the JSON stays
 * hand-editable and Gson needs no custom adapters.
 *
 * <p>Supported types:
 * <table>
 *   <tr><td>all / any / none</td><td>combinators over {@code conditions}</td></tr>
 *   <tr><td>npcSpawn / npcDespawn</td><td>{@code names} (wildcards ok) or {@code ids}</td></tr>
 *   <tr><td>npcNearby</td><td>{@code names}/{@code ids} plus {@code within} tiles</td></tr>
 *   <tr><td>healthBelow / healthAbove</td><td>{@code percent}</td></tr>
 *   <tr><td>prayerBelow / prayerAbove</td><td>{@code percent}, {@code requirePrayerActive}</td></tr>
 *   <tr><td>inRegion / regionEnter</td><td>{@code regions}, {@code anyLoadedRegion}</td></tr>
 *   <tr><td>inArea</td><td>{@code x1,y1,x2,y2,plane}</td></tr>
 *   <tr><td>chatMessage</td><td>{@code contains} or {@code regex}</td></tr>
 *   <tr><td>varbitEquals / varbitChanged</td><td>{@code varbit}, {@code value}</td></tr>
 *   <tr><td>animationSelf</td><td>{@code ids}</td></tr>
 *   <tr><td>levelUp</td><td>{@code names} (skill names)</td></tr>
 *   <tr><td>damageTaken</td><td>{@code minimum}</td></tr>
 *   <tr><td>itemEquipped</td><td>{@code ids}</td></tr>
 *   <tr><td>poisoned / venomed / skulled</td><td>no fields</td></tr>
 *   <tr><td>thrallStart / thrallSwitch / thrallEnd</td><td>no fields; {@code {style}} and, for a switch, {@code {from}}</td></tr>
 *   <tr><td>errandStart / errandEnd</td><td>optional {@code names} (errand names); {@code {errand}} placeholder</td></tr>
 *   <tr><td>petNearby</td><td>{@code within} — any NPC the game flags as a follower, i.e. any pet</td></tr>
 *   <tr><td>idleBelow</td><td>{@code ticks} — the other bound, for fidgets that should stop once resting</td></tr>
 *   <tr><td>playerDeath</td><td>no fields — the moment of death</td></tr>
 *   <tr><td>nearDeathSpot</td><td>{@code within} — standing near the session's last death, 2+ min after it</td></tr>
 *   <tr><td>lootWorth</td><td>{@code minimum} gp — {@code {item}} and {@code {value}} placeholders</td></tr>
 *   <tr><td>returnVisit</td><td>{@code minimum} — entering a region already visited that many times this session</td></tr>
 *   <tr><td>combat</td><td>no fields — true throughout a fight, including the gaps between targets</td></tr>
 *   <tr><td>bossFight</td><td>{@code minimum} — target combat level, default 100</td></tr>
 *   <tr><td>combatStart / combatEnd</td><td>optional {@code names}; {@code {npc}} placeholder</td></tr>
 *   <tr><td>npcKill</td><td>{@code minimum} / {@code maximum} combat level, optional {@code names} / {@code ids}, or {@code boss: true} for either big enough or named in the boss rules</td></tr>
 *   <tr><td>energyBelow</td><td>{@code percent}</td></tr>
 *   <tr><td>idle</td><td>{@code ticks}</td></tr>
 *   <tr><td>login / always</td><td>no fields</td></tr>
 *   <tr><td>chance</td><td>{@code percent} — rolled each evaluation</td></tr>
 *   <tr><td>tally</td><td>{@code of} counter name, {@code minimum} / {@code maximum} — a LIFETIME count</td></tr>
 *   <tr><td>personalBest</td><td>optional {@code names}; {@code {record}} {@code {value}} {@code {previous}}</td></tr>
 *   <tr><td>sessionCount</td><td>{@code minimum} / {@code every} — login only</td></tr>
 *   <tr><td>answered</td><td>{@code is} yes|no — the branch the player picked in the tree named by {@code asks}</td></tr>
 *   <tr><td>hovered</td><td>{@code ticks} — the mouse resting on the follower</td></tr>
 *   <tr><td>examined</td><td>no fields</td></tr>
 *   <tr><td>inventoryFree</td><td>{@code maximum} free slots — a warning, not a report</td></tr>
 *   <tr><td>playersNearby</td><td>{@code minimum} count, {@code within} tiles</td></tr>
 *   <tr><td>wanting</td><td>no fields — a want is open; usually used negated</td></tr>
 *   <tr><td>wantFulfilled / wantExpired</td><td>no fields; {@code {want}} placeholder</td></tr>
 *   <tr><td>feelsAbout</td><td>{@code is} liked|disliked — about the CURRENT region</td></tr>
 *   <tr><td>remembers</td><td>optional {@code is} incident key, {@code minimum} times; {@code {memory}}</td></tr>
 *   <tr><td>carrying</td><td>no fields — holding a souvenir; {@code {souvenir}}</td></tr>
 *   <tr><td>souvenirLost</td><td>no fields; {@code {souvenir}} names it one last time</td></tr>
 *   <tr><td>betting / betWon / betLost</td><td>no fields</td></tr>
 *   <tr><td>timeOfDay</td><td>{@code minimum} / {@code maximum} hour, 0-23, wrapping past midnight</td></tr>
 *   <tr><td>sessionMinutes</td><td>{@code minimum} / {@code maximum} minutes today</td></tr>
 *   <tr><td>dateIs</td><td>{@code month}/{@code day} on the player's own calendar, optional {@code untilMonth}/{@code untilDay} range wrapping past new year; {@code day} alone means that day of every month</td></tr>
 *   <tr><td>worldHop</td><td>no fields; {@code {world}} is the new world number</td></tr>
 *   <tr><td>gameUpdated</td><td>no fields — first login on a new game build</td></tr>
 *   <tr><td>notesEdited</td><td>no fields — phrases.json changed on disk and hot-reloaded</td></tr>
 *   <tr><td>musicUnlock</td><td>no fields; {@code {track}} names the new track</td></tr>
 *   <tr><td>musicTrack</td><td>optional {@code names} (wildcards ok) — the playing track changed; {@code {track}}</td></tr>
 *   <tr><td>collectionAdd</td><td>no fields; {@code {item}} is the new collection log entry</td></tr>
 *   <tr><td>questComplete</td><td>no fields; {@code {quest}} names the quest just finished</td></tr>
 *   <tr><td>geOffer</td><td>{@code is} bought|sold; {@code {item}} and {@code {value}}</td></tr>
 *   <tr><td>channelJoined / channelLeft</td><td>no fields; {@code {name}} says who</td></tr>
 *   <tr><td>npcShout</td><td>{@code names} (wildcards ok) and/or {@code contains}; {@code {npc}} and {@code {message}}</td></tr>
 *   <tr><td>examinedThing</td><td>optional {@code names} (wildcards ok) — the player examined something; {@code {target}}</td></tr>
 *   <tr><td>attendedAgain</td><td>no fields — the player is back from an absence the follower came round to check on</td></tr>
 *   <tr><td>minutesTaken</td><td>no fields — the follower finished minuting an NPC dialog</td></tr>
 * </table>
 *
 * <p>{@code npcNearby} also takes {@code minimum}/{@code maximum} combat level,
 * which on their own match any NPC in that bracket, and {@code visible}, which
 * additionally requires line of sight to the player - for lines that invite
 * the player to look at the thing.
 *
 * <p>{@code chatMessage} also takes {@code from} (player|others) and {@code is}
 * (a {@link net.runelite.api.ChatMessageType} name).
 */
@Slf4j
public class Condition
{
	public String type;

	public List<Condition> conditions;

	public List<String> names;
	public List<Integer> ids;
	public List<Integer> regions;

	public Integer percent;
	public Integer minimum;

	/**
	 * Whether the NPC has to be a BOSS, or has to NOT be one.
	 *
	 * <p>Three states. Left out, it does not care. True, only bosses.
	 * False, only things that are not, which is how the generic "well fought"
	 * stands aside for a boss's own send-off instead of talking over it.
	 *
	 * <p>A bigger question than any combat level, and the reason this is not
	 * just {@code minimum: 100}.
	 *
	 * <p>The level is only a proxy, and it is wrong in both directions. It was
	 * wrong for Brutus, who fights at thirty and is unmistakably a boss, so
	 * the follower neither stood clear of him nor said anything when he went
	 * down. The names the boss rules already list are the other half of the
	 * answer, and this consults both.
	 */
	public Boolean boss;
	public Integer maximum;
	public Integer within;
	public Integer ticks;
	public Integer varbit;
	public Integer value;

	/** Fire on every Nth occurrence rather than on each one. */
	public Integer every;

	/** dateIs: the day on the player's own calendar, optionally through a range. */
	public Integer month;
	public Integer day;
	public Integer untilMonth;
	public Integer untilDay;

	public Integer x1;
	public Integer y1;
	public Integer x2;
	public Integer y2;
	public Integer plane;

	public String contains;
	public String regex;

	/** A named band, for conditions that read better as a word than a number. */
	public String is;

	/** Which counter a tally or record condition is asking about. */
	public String of;

	/** Who said it: "player" for the local player's own chat, "others" for the rest. */
	public String from;

	public Boolean requirePrayerActive;
	public Boolean anyLoadedRegion;

	/**
	 * On {@code npcNearby}: the NPC must also have line of sight to the
	 * player, by the game's own collision rules. For lines that invite the
	 * player to LOOK - a callout at something behind a wall is worse than no
	 * callout, because one bad one teaches the player to stop checking.
	 * Opt-in per rule rather than a change to what npcNearby means, since
	 * plenty of uses are atmosphere rather than assertion.
	 */
	public Boolean visible;

	private transient Pattern compiledRegex;
	private transient List<Pattern> compiledNames;

	/**
	 * {@link #ids} and {@link #regions} unboxed, built on first use.
	 *
	 * <p>These two carry the bulk of the rule set - most rules are "wearing
	 * this" or "standing here" - and every rule is evaluated against every
	 * event, so a {@code List<Integer>.contains(int)} here means boxing the
	 * needle and walking a chain of Integers, hundreds of times per event.
	 */
	private transient int[] idsUnboxed;
	private transient int[] regionsUnboxed;

	private static int[] unbox(List<Integer> boxed)
	{
		int[] out = new int[boxed.size()];
		for (int i = 0; i < out.length; i++)
		{
			Integer value = boxed.get(i);
			out[i] = value == null ? Integer.MIN_VALUE : value;
		}
		return out;
	}

	private static boolean contains(int[] values, int wanted)
	{
		for (int value : values)
		{
			if (value == wanted)
			{
				return true;
			}
		}
		return false;
	}

	private boolean idsContain(int wanted)
	{
		if (ids == null)
		{
			return false;
		}
		if (idsUnboxed == null)
		{
			idsUnboxed = unbox(ids);
		}
		return contains(idsUnboxed, wanted);
	}

	/**
	 * The lowercased {@link #type}, cached: every rule is evaluated on every
	 * event, and re-lowercasing the discriminator allocated a string per
	 * evaluation across hundreds of rules.
	 */
	private transient String normalizedType;

	/**
	 * npcNearby scans the whole NPC list; its answer cannot change within a
	 * tick, so it is cached per {@link TriggerContext#getRefreshGeneration()}.
	 */
	private transient int nearbyGeneration = -1;
	private transient boolean nearbyCached;

	public boolean matches(TriggerContext ctx, TriggerEvent event)
	{
		if (type == null)
		{
			return false;
		}
		if (normalizedType == null)
		{
			normalizedType = type.toLowerCase(Locale.ROOT);
		}

		switch (normalizedType)
		{
			case "all":
				return allOf(ctx, event);
			case "any":
				return anyOf(ctx, event);
			case "none":
				return !anyOf(ctx, event);

			case "always":
				return true;

			case "chance":
				return ThreadLocalRandom.current().nextInt(100) < orDefault(percent, 100);

			case "npcspawn":
				return event.getType() == TriggerEvent.Type.NPC_SPAWN && matchesNpc(event);
			case "npcdespawn":
				return event.getType() == TriggerEvent.Type.NPC_DESPAWN && matchesNpc(event);

			case "npcnearby":
			{
				int generation = ctx.getRefreshGeneration();
				if (nearbyGeneration != generation)
				{
					nearbyGeneration = generation;
					nearbyCached = ctx.isNpcNearby(this::isNearbyCandidate,
						orDefault(within, 15), Boolean.TRUE.equals(visible));
				}
				return nearbyCached;
			}

			// Any NPC the game itself flags as a follower - every pet in the
			// game, and every one added later, without naming any of them.
			// Cached per tick like npcNearby, and for the same reason.
			case "petnearby":
			{
				int generation = ctx.getRefreshGeneration();
				if (nearbyGeneration != generation)
				{
					nearbyGeneration = generation;
					nearbyCached = ctx.isNpcNearby(
						npc -> npc.getComposition() != null && npc.getComposition().isFollower(),
						orDefault(within, 5));
				}
				return nearbyCached;
			}

			case "healthbelow":
				return ctx.getHitpointsPercent() < orDefault(percent, 50);
			case "healthabove":
				return ctx.getHitpointsPercent() > orDefault(percent, 50);

			case "prayerbelow":
				return ctx.getPrayerPercent() < orDefault(percent, 20)
					&& (!Boolean.TRUE.equals(requirePrayerActive) || ctx.isPrayerActive());
			case "prayerabove":
				return ctx.getPrayerPercent() > orDefault(percent, 20);

			case "inregion":
				return matchesRegion(ctx, ctx.getRegionId());
			case "regionenter":
				return event.getType() == TriggerEvent.Type.REGION_CHANGE && matchesRegion(ctx, event.getValue());

			case "inarea":
				return matchesArea(ctx);

			case "chatmessage":
				return event.getType() == TriggerEvent.Type.CHAT
					&& matchesChatType(event)
					&& matchesSpeaker(ctx, event)
					&& matchesText(event.getMessage());

			// The player answering something the follower asked, by picking a
			// branch in the conversation it opened. The options ARE the
			// vocabulary, so there is nothing to misread: yes and no from the
			// question trees, and the handful of named acts the everyday
			// script can perform - "gift" being the first.
			case "answered":
				return event.getType() == TriggerEvent.Type.ANSWERED
					&& (is == null || is.equalsIgnoreCase(event.getName()));

			case "varbitequals":
				return varbit != null && ctx.getClient().getVarbitValue(varbit) == orDefault(value, 1);
			case "varbitchanged":
				return event.getType() == TriggerEvent.Type.VARBIT
					&& varbit != null && event.getId() == varbit
					&& (value == null || event.getValue() == value);

			case "animationself":
				return event.getType() == TriggerEvent.Type.ANIMATION && idsContain(event.getId());

			case "levelup":
				return event.getType() == TriggerEvent.Type.LEVEL_UP && matchesText(event.getName());

			case "damagetaken":
				return event.getType() == TriggerEvent.Type.DAMAGE_TAKEN
					&& event.getValue() >= orDefault(minimum, 1);

			case "itemequipped":
			{
				if (ids == null)
				{
					return false;
				}
				if (idsUnboxed == null)
				{
					idsUnboxed = unbox(ids);
				}
				for (int id : idsUnboxed)
				{
					if (ctx.isEquipped(id))
					{
						return true;
					}
				}
				return false;
			}

			case "poisoned":
			{
				int poison = ctx.getClient().getVarpValue(net.runelite.api.gameval.VarPlayerID.POISON);
				return poison > 0 && poison < VENOM_THRESHOLD;
			}
			case "venomed":
				return ctx.getClient().getVarpValue(net.runelite.api.gameval.VarPlayerID.POISON) >= VENOM_THRESHOLD;

			case "skulled":
				return ctx.isSkulled();

			case "energybelow":
				return ctx.getEnergyPercent() < orDefault(percent, 20);

			case "idle":
				return ctx.getIdleTicks() >= orDefault(ticks, 50);

			// The other bound, so a fidget can be told apart from a full rest:
			// "been still a while" AND "not settled in for the night".
			case "idlebelow":
				return ctx.getIdleTicks() < orDefault(ticks, 500);

			case "playerdeath":
				return event.getType() == TriggerEvent.Type.PLAYER_DEATH;

			// Standing where the last death happened, well after the fact.
			case "neardeathspot":
				return ctx.isNearDeathSpot(orDefault(within, 5));

			case "lootworth":
				return event.getType() == TriggerEvent.Type.LOOT
					&& event.getValue() >= orDefault(minimum, 100_000);

			// Entering a region the session has already seen a few times.
			case "returnvisit":
				return event.getType() == TriggerEvent.Type.REGION_CHANGE
					&& ctx.getRegionVisits() >= orDefault(minimum, 5);

			// True through a whole fight, including the short gaps between a
			// target dying and the next being clicked, so a rule using this
			// does not flicker on and off mid-kill.
			case "combat":
				return ctx.isInCombat();

			// The same, but only for something big. "minimum" overrides the
			// default combat level for anyone who wants a different bar.
			case "bossfight":
				return ctx.isInCombat()
					&& ctx.getCombatTargetLevel() >= orDefault(minimum, 100);

			case "login":
				return event.getType() == TriggerEvent.Type.LOGIN;

			case "thrallstart":
				return event.getType() == TriggerEvent.Type.THRALL_START;
			case "thrallswitch":
				return event.getType() == TriggerEvent.Type.THRALL_SWITCH;
			case "thrallend":
				return event.getType() == TriggerEvent.Type.THRALL_END;

			case "errandstart":
				return event.getType() == TriggerEvent.Type.ERRAND_START
					&& (names == null || matchesAnyName(event.getName()));
			case "errandend":
				return event.getType() == TriggerEvent.Type.ERRAND_END
					&& (names == null || matchesAnyName(event.getName()));

			// The moment a fight starts or ends, as opposed to "combat", which
			// stays true throughout one. Optional names match what is fought.
			case "combatstart":
				return event.getType() == TriggerEvent.Type.COMBAT_START
					&& (names == null || matchesAnyName(event.getName()));
			case "combatend":
				return event.getType() == TriggerEvent.Type.COMBAT_END
					// The level comes from the context rather than the event,
					// which carries only the name: the target's level is still
					// the one the fight was fought at when this fires.
					&& (boss == null
						|| boss == ctx.isBoss(event.getName(), ctx.getCombatTargetLevel()))
					&& (names == null || matchesAnyName(event.getName()));

			// Something the player killed. "minimum"/"maximum" bracket the
			// victim's COMBAT LEVEL, which is how one rule celebrates a boss
			// and another shrugs at a chicken; "names"/"ids" narrow it further.
			// How the follower is feeling. "is" names a band (low, down, even,
			// good, high); minimum and maximum bracket the raw 0..100 for
			// anything that wants a finer edge than the bands give.
			case "mood":
			{
				if (is != null)
				{
					return is.equalsIgnoreCase(ctx.getMoodBand());
				}
				int value = ctx.getMood();
				return value >= orDefault(minimum, 0)
					&& value <= orDefault(maximum, 100);
			}

			case "npckill":
				return event.getType() == TriggerEvent.Type.NPC_KILL
					&& (boss == null
						|| boss == ctx.isBoss(event.getName(), event.getValue()))
					&& event.getValue() >= orDefault(minimum, 0)
					&& (maximum == null || event.getValue() <= maximum)
					&& (names == null && ids == null || matchesNpc(event))
					// "every": 50 fires on the fiftieth of THIS npc and every
					// fiftieth after, which is what makes a tally a remark.
					&& (every == null || every <= 0
						|| (event.getCount() > 0 && event.getCount() % every == 0));

			// The two ends of a thieving session. Everything between them is
			// silent, and these are what make that silence read as the
			// follower giving the player room rather than having broken.
			case "thievingstart":
				return event.getType() == TriggerEvent.Type.THIEVING_START;
			case "thievingend":
				return event.getType() == TriggerEvent.Type.THIEVING_END;

			// True for the whole session, unlike the two edges. Speech is muted
			// throughout, so this is really for animation-only rules - which
			// skip the mute, being movement rather than chatter.
			case "thieving":
				return ctx.isInThievingSession();

			// How long the follower went without seeing the player, in minutes.
			// Only meaningful on the login event, which is when it is worked
			// out; -1 means it has no idea, and must never read as "just now".
			case "awayfor":
				return event.getType() == TriggerEvent.Type.LOGIN
					&& ctx.getMinutesAway() >= 0
					&& ctx.getMinutesAway() >= orDefault(minimum, 60)
					&& (maximum == null || ctx.getMinutesAway() <= maximum);

			// A lifetime count, as against npcKill's "every" which fires on the
			// moment. This is state: it stays true once passed, so it belongs
			// alongside something that picks the moment to say it.
			// The incident the follower is still thinking about. "is" names a
			// particular one; without it, any incident will do - which is what
			// a generic "I still think about {memory}" line wants.
			case "remembers":
				return ctx.hasIncident()
					&& (is == null || is.equalsIgnoreCase(ctx.getIncidentKey()))
					&& ctx.getIncidentCount() >= orDefault(minimum, 1);

			// You clicked the tile the follower was standing on.
			case "underfoot":
				return event.getType() == TriggerEvent.Type.UNDERFOOT;

			// A challenge is outstanding, was met, or ran out. {challenge}
			// names it. "challenging" is mostly used negated, so the follower
			// does not set a second one over the top of the first.
			case "challenging":
				return ctx.isChallenging();
			case "challengemet":
				return event.getType() == TriggerEvent.Type.CHALLENGE_MET;
			case "challengefailed":
				return event.getType() == TriggerEvent.Type.CHALLENGE_FAILED;

			// Nobody has touched the camera for this long. Distinct from idle,
			// which a player working a furnace also satisfies.
			case "unattended":
				return ctx.getUnattendedTicks() >= orDefault(ticks, 200);

			// How long the follower has known you, in days, and the day of
			// the year it met you coming round again.
			// A player-commanded Stay: watched, parked, and free to have a
			// little life of its own.
			case "staying":
				return ctx.isFollowerStaying();

			// Standing in the Wilderness, as a state rather than the crossing.
			case "inwilderness":
				return ctx.isInWilderness();

			// A few ticks of breather after something ENDS - combat, a level,
			// an arrival, thieving, the bank. "is" names which ending; left
			// out, any ending counts.
			case "boundary":
				return ctx.isAtBoundary()
					&& (is == null || is.equalsIgnoreCase(ctx.getBoundaryKind()));

			case "daysknown":
				return ctx.getDaysKnown() >= orDefault(minimum, 1)
					&& (maximum == null || ctx.getDaysKnown() <= maximum);
			case "anniversary":
				return ctx.isAnniversary();

			// The player is "minimum" times better dressed than the day they
			// met. Needs a first-meeting figure to compare against, so it stays
			// quiet for a follower that has only ever known you rich.
			case "outgrew":
				return ctx.getTimesBetterDressed() >= orDefault(minimum, 10);

			// The follower has taken to calling you something. {nickname} says
			// it; without this guard the placeholder prints nothing.
			case "nicknamed":
				return ctx.hasNickname()
					&& (is == null || is.equalsIgnoreCase(ctx.getNickname()));

			// The player did what the follower suggested, or the window shut
			// without them. {advice} names what it was about. "is" narrows to
			// one piece of advice, so the food line and the bag line can react
			// differently.
			case "heeded":
				return event.getType() == TriggerEvent.Type.ADVICE_HEEDED
					&& (is == null || is.equalsIgnoreCase(ctx.getAdviceAbout()));
			case "ignored":
				return event.getType() == TriggerEvent.Type.ADVICE_IGNORED
					&& (is == null || is.equalsIgnoreCase(ctx.getAdviceAbout()));

			// Advice is outstanding. Used NEGATED, so the follower does not
			// give the same advice twice while still waiting on the first.
			case "advising":
				return ctx.isAdvising();

			// Something happened HERE that the follower has not let go of.
			// {here} says it. Distinct from "remembers", which holds one
			// incident wherever you are; this one is the place's, and waits
			// for you to come back to it.
			case "happenedhere":
				return ctx.hasPlaceMemory();

			// How strongly it feels about where it is standing, as a number
			// rather than a verdict, so a rule can want a STRONG opinion.
			// Negative is the bad direction.
			case "placescore":
			{
				int score = ctx.getPlaceScore();
				return (minimum == null || score >= minimum)
					&& (maximum == null || score <= maximum);
			}

			// A question is already on the table. Used NEGATED, and every rule
			// with an "asks" needs it: opening a second question replaces the
			// first, so without the guard a follower that asks to go somewhere
			// and then offers a game has silently withdrawn the outing, and the
			// player answers a question nobody is listening for.
			case "asking":
				return ctx.isAwaitingAnswer()
					&& (is == null || is.equalsIgnoreCase(ctx.getAskedTree()));

			// Carrying something it picked up. Mostly used negated, to stop it
			// picking up a second thing while its hands are full.
			case "carrying":
				return ctx.isCarrying();

			case "souvenirlost":
				return event.getType() == TriggerEvent.Type.SOUVENIR_LOST;

			// A prediction is outstanding. Negated, this stops it betting twice
			// on the same drop.
			case "betting":
				return ctx.isBetting();

			case "betwon":
				return event.getType() == TriggerEvent.Type.BET_WON;
			case "betlost":
				return event.getType() == TriggerEvent.Type.BET_LOST;

			// The hour on the player's own wall, not the game's. "minimum" and
			// "maximum" bound it, wrapping past midnight so a late-night window
			// can be written the way a person would say it: 23 to 5.
			case "timeofday":
			{
				int hour = ctx.getHourOfDay();
				int from = orDefault(minimum, 0);
				int to = orDefault(maximum, 23);
				return from <= to
					? hour >= from && hour <= to
					: hour >= from || hour <= to;
			}

			// How long today has run, in minutes.
			case "sessionminutes":
				return ctx.getSessionMinutes() >= orDefault(minimum, 60)
					&& (maximum == null || ctx.getSessionMinutes() <= maximum);

			// The date on the player's own calendar, like timeOfDay is the
			// player's own clock. A single day, or a range that may wrap past
			// new year the way a late-night window wraps past midnight - the
			// scribe dates its entries, so this is the most in-character
			// knowledge it could have. Rising-edge, so a matching day fires
			// once per session, same as anniversary.
			case "dateis":
			{
				if (day == null)
				{
					return false;
				}
				int today = ctx.getMonthDay();
				// Day alone means that day of EVERY month - the first of the
				// month is the scribe's favourite day of it.
				if (month == null)
				{
					return today % 100 == day;
				}
				int from = month * 100 + day;
				int to = untilMonth == null || untilDay == null
					? from : untilMonth * 100 + untilDay;
				return from <= to
					? today >= from && today <= to
					: today >= from || today <= to;
			}

			// A world hop landed. Rare by nature, so no flood guard needed.
			case "worldhop":
				return event.getType() == TriggerEvent.Type.WORLD_HOP;

			// First login since the game itself changed under everyone's feet.
			case "gameupdated":
				return event.getType() == TriggerEvent.Type.GAME_UPDATE;

			// The notebook was edited from outside and hot-reloaded. In-world
			// this is somebody writing in the scribe's own book.
			case "notesedited":
				return event.getType() == TriggerEvent.Type.NOTES_EDITED;

			case "musicunlock":
				return event.getType() == TriggerEvent.Type.MUSIC_UNLOCK;

			// The music changed to another track - the town's own song, where
			// musicUnlock is hearing one for the FIRST time. Names narrow it
			// to particular tracks, which is how a rule gets an opinion about
			// Sea Shanty 2 without one about everything.
			case "musictrack":
				return event.getType() == TriggerEvent.Type.TRACK_CHANGE
					&& (names == null || matchesAnyName(event.getName()));

			case "collectionadd":
				return event.getType() == TriggerEvent.Type.COLLECTION_ADD;

			case "questcomplete":
				return event.getType() == TriggerEvent.Type.QUEST_COMPLETE;

			// A Grand Exchange offer finished; "is" narrows to bought or sold.
			case "geoffer":
				return event.getType() == TriggerEvent.Type.GE_OFFER
					&& (is == null || is.equalsIgnoreCase(event.getName()));

			case "channeljoined":
				return event.getType() == TriggerEvent.Type.CHANNEL_JOIN;
			case "channelleft":
				return event.getType() == TriggerEvent.Type.CHANNEL_LEAVE;

			// A named NPC's overhead line. Names match like npcSpawn's and the
			// message like chatMessage's contains - spelled out here rather
			// than through matchesText, which would also try the message
			// against the NAMES and quietly widen what a rule matches.
			case "npcshout":
				return event.getType() == TriggerEvent.Type.NPC_SHOUT
					&& (names == null || matchesAnyName(event.getName()))
					&& (contains == null || event.getMessage().toLowerCase(Locale.ROOT)
						.contains(contains.toLowerCase(Locale.ROOT)));

			// How this particular follower feels about where it is standing.
			// The set is rolled once per character, so the answer is a fact
			// about your follower rather than about the game.
			case "feelsabout":
				return ctx.feelsAbout(is == null ? "liked" : is);

			// The ROLL alone, before experience overrode it. Paired with
			// placeScore, this is how a rule catches the two disagreeing -
			// which feelsAbout cannot express, having already resolved the
			// argument. The disagreement is where the temperament shows.
			case "rolledfeeling":
				return ctx.rolledFeeling(is == null ? "liked" : is);

			// The follower is hoping for something. Mostly used NEGATED, to stop
			// a second want being asked for while one is still open.
			case "wanting":
				return ctx.isWanting();

			// A small thing has been wished for and not yet found. Negated by
			// the wish rules (one hope at a time) and required by the gift's
			// thank-you, which names the thing via {wish}.
			case "wishing":
				return ctx.isWishing()
					&& (is == null || is.equalsIgnoreCase(ctx.getWishLabel()));

			// And the wished-for thing is actually in the player's bag. The
			// gift's thank-you requires this; the bluff rule requires its
			// absence - claiming to have found a feather is checkable, and a
			// follower that cannot tell is a follower that cannot see.
			case "wishitemheld":
				return ctx.isWishedItemInBag();

			case "wantfulfilled":
				return event.getType() == TriggerEvent.Type.WANT_FULFILLED;
			case "wantexpired":
				return event.getType() == TriggerEvent.Type.WANT_EXPIRED;

			// Room left in the bag. The point of this one is the WARNING - set
			// maximum to 2 and the follower speaks up while there is still
			// somewhere to put the next log, which is a companion paying
			// attention rather than a companion narrating a full inventory.
			case "inventoryfree":
			{
				int free = ctx.getFreeInventorySlots();
				return free <= orDefault(maximum, 2) && free >= orDefault(minimum, 0);
			}

			// How busy it is here. "within" is the radius, "minimum" how many
			// other players it takes before that counts as a crowd.
			case "playersnearby":
				return ctx.countPlayersNearby(orDefault(within, 10))
					>= orDefault(minimum, 5);

			// Somebody is looking at the follower. "ticks" is how long the mouse
			// has to rest on it: a cursor crossing the screen is not attention.
			case "hovered":
				return ctx.getHoverTicks() >= orDefault(ticks, 5);

			case "examined":
				return event.getType() == TriggerEvent.Type.EXAMINED;

			// The player examined something - the other direction. Names
			// narrow it to particular things, so the scarecrow can have its
			// own line without everything having one.
			case "examinedthing":
				return event.getType() == TriggerEvent.Type.EXAMINED_THING
					&& (names == null || matchesAnyName(event.getName()));

			// The player came back from a long absence during which the
			// follower walked round to peer at them. The check itself is
			// silent - the damper holds while nobody is there to read a line -
			// so this is the payoff, landing on a present player.
			case "attendedagain":
				return event.getType() == TriggerEvent.Type.ATTENDED_AGAIN;

			// The follower finished minuting one of the player's NPC dialogs:
			// it stepped aside, wrote through the meeting, and put the scroll
			// away as the box closed.
			case "minutestaken":
				return event.getType() == TriggerEvent.Type.MINUTES_TAKEN;

			case "tally":
			{
				if (of == null)
				{
					return false;
				}
				int counted = ctx.getTally(of);
				return counted >= orDefault(minimum, 1)
					&& (maximum == null || counted <= maximum);
			}

			// The moment a record was beaten. {record}, {value} and {previous}
			// are on the event; "names" narrows to particular records.
			case "personalbest":
				return event.getType() == TriggerEvent.Type.RECORD
					&& (names == null || matchesAnyName(event.getName()));

			// How many times the follower has been started up with this player.
			// Login only, which is the one moment it changes and the one moment
			// remarking on it is not out of nowhere.
			case "sessioncount":
			{
				if (event.getType() != TriggerEvent.Type.LOGIN)
				{
					return false;
				}
				int sessions = ctx.getSessionCount();
				return sessions >= orDefault(minimum, 1)
					&& (maximum == null || sessions <= maximum)
					&& (every == null || every <= 0 || sessions % every == 0);
			}

			// How long the player has been doing the same thing. Knows nothing
			// about trees or rocks: an animation running for minutes IS the
			// activity, so this covers every skill at once.
			case "repeating":
				return ctx.getRepeatingTicks() >= orDefault(ticks, 100)
					&& (ids == null || idsContain(ctx.getRepeatingAnimation()));

			default:
				log.warn("Unknown condition type '{}'", type);
				return false;
		}
	}

	private boolean allOf(TriggerContext ctx, TriggerEvent event)
	{
		if (conditions == null || conditions.isEmpty())
		{
			return true;
		}
		for (Condition child : conditions)
		{
			if (!child.matches(ctx, event))
			{
				return false;
			}
		}
		return true;
	}

	private boolean anyOf(TriggerContext ctx, TriggerEvent event)
	{
		if (conditions == null)
		{
			return false;
		}
		for (Condition child : conditions)
		{
			if (child.matches(ctx, event))
			{
				return true;
			}
		}
		return false;
	}

	private boolean matchesNpc(TriggerEvent event)
	{
		if (idsContain(event.getId()))
		{
			return true;
		}
		return names != null && matchesAnyName(event.getName());
	}

	/**
	 * Whether an NPC in the scene is one this rule cares about.
	 *
	 * <p>{@code minimum} and {@code maximum} bracket its COMBAT LEVEL, which is
	 * what turns npcNearby into "something big is standing near us" without
	 * naming a single monster - and keeps covering everything the game adds
	 * later. With no names or ids given, that bracket is the whole test.
	 */
	private boolean isNearbyCandidate(NPC npc)
	{
		if (minimum != null && npc.getCombatLevel() < minimum)
		{
			return false;
		}
		if (maximum != null && npc.getCombatLevel() > maximum)
		{
			return false;
		}
		if (names == null && ids == null)
		{
			return minimum != null || maximum != null;
		}
		return matchesNpcObject(npc);
	}

	private boolean matchesNpcObject(NPC npc)
	{
		if (idsContain(npc.getId()))
		{
			return true;
		}
		return names != null && npc.getName() != null && matchesAnyName(npc.getName());
	}

	private boolean matchesRegion(TriggerContext ctx, int currentRegion)
	{
		if (regions == null || regions.isEmpty())
		{
			return false;
		}
		if (regionsUnboxed == null)
		{
			regionsUnboxed = unbox(regions);
		}
		if (Boolean.TRUE.equals(anyLoadedRegion))
		{
			for (int region : regionsUnboxed)
			{
				if (ctx.isRegionLoaded(region))
				{
					return true;
				}
			}
			return false;
		}
		return contains(regionsUnboxed, currentRegion);
	}

	private boolean matchesArea(TriggerContext ctx)
	{
		if (ctx.getLocation() == null || x1 == null || y1 == null || x2 == null || y2 == null)
		{
			return false;
		}
		int px = ctx.getLocation().getX();
		int py = ctx.getLocation().getY();
		if (plane != null && ctx.getLocation().getPlane() != plane)
		{
			return false;
		}
		return px >= Math.min(x1, x2) && px <= Math.max(x1, x2)
			&& py >= Math.min(y1, y2) && py <= Math.max(y1, y2);
	}

	/**
	 * Narrows a chat rule to one kind of message. {@code is} takes the
	 * {@link net.runelite.api.ChatMessageType} name exactly as {@code ::follower
	 * chatwatch} prints it, so the way to write one of these is to watch the
	 * real message go past and copy what it says. No table of friendly aliases,
	 * because a table is a thing that drifts out of date silently.
	 */
	private boolean matchesChatType(TriggerEvent event)
	{
		if (is == null)
		{
			return true;
		}
		if (wantedChatType == Integer.MIN_VALUE)
		{
			int resolved = -1;
			try
			{
				resolved = net.runelite.api.ChatMessageType
					.valueOf(is.toUpperCase(Locale.ROOT)).getType();
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Unknown chat type '{}' - see ::follower chatwatch for the real names", is);
			}
			wantedChatType = resolved;
		}
		return wantedChatType >= 0 && event.getChatTypeId() == wantedChatType;
	}

	private transient int wantedChatType = Integer.MIN_VALUE;

	/**
	 * {@code from} is "player" for the local player's own lines and "others"
	 * for everybody else's. Absent means either.
	 */
	private boolean matchesSpeaker(TriggerContext ctx, TriggerEvent event)
	{
		if (from == null)
		{
			return true;
		}
		boolean mine = isFromPlayer(ctx, event);
		return "player".equalsIgnoreCase(from) ? mine : !mine;
	}

	private static boolean isFromPlayer(TriggerContext ctx, TriggerEvent event)
	{
		// Read straight off the client rather than through getPlayerName(),
		// which substitutes "you" when there is no player - a placeholder
		// fallback that would be a wrong ANSWER here.
		net.runelite.api.Player local = ctx.getClient().getLocalPlayer();
		String player = local == null || local.getName() == null ? "" : local.getName();
		if (player.isEmpty() || event.getName().isEmpty())
		{
			return false;
		}
		// The game pads display names with non-breaking spaces.
		return player.replace(' ', ' ').trim()
			.equalsIgnoreCase(event.getName().replace(' ', ' ').trim());
	}

	/** Matches against {@code contains} (case-insensitive), {@code regex}, or {@code names}. */
	private boolean matchesText(String text)
	{
		if (text == null)
		{
			return false;
		}
		if (contains != null && text.toLowerCase(Locale.ROOT).contains(contains.toLowerCase(Locale.ROOT)))
		{
			return true;
		}
		if (regex != null)
		{
			if (compiledRegex == null)
			{
				compiledRegex = Pattern.compile(regex, Pattern.CASE_INSENSITIVE);
			}
			if (compiledRegex.matcher(text).find())
			{
				return true;
			}
		}
		return names != null && matchesAnyName(text);
	}

	/** Name matching is case-insensitive and supports {@code *} wildcards. */
	/**
	 * Compiles one name pattern the way every {@code names} list here is
	 * matched: literal, case-insensitive, with {@code *} standing for any run
	 * of characters.
	 */
	public static Pattern compileName(String name)
	{
		StringBuilder pattern = new StringBuilder();
		for (String literal : name.split("\\*", -1))
		{
			if (pattern.length() > 0)
			{
				pattern.append(".*");
			}
			pattern.append(Pattern.quote(literal));
		}
		return Pattern.compile(pattern.toString(), Pattern.CASE_INSENSITIVE);
	}

	/** The game pads names with non-breaking spaces in places. */
	public static String normaliseName(String candidate)
	{
		return candidate == null ? "" : candidate.replace('\u00A0', ' ').trim();
	}

	private boolean matchesAnyName(String candidate)
	{
		if (candidate == null || names == null)
		{
			return false;
		}
		if (compiledNames == null)
		{
			compiledNames = new java.util.ArrayList<>(names.size());
			for (String name : names)
			{
				compiledNames.add(compileName(name));
			}
		}
		String normalised = normaliseName(candidate);
		for (Pattern pattern : compiledNames)
		{
			if (pattern.matcher(normalised).matches())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Every region id this condition tree names, for the trait roll - the
	 * follower's likes are drawn from the places the rule set already has
	 * opinions about, so the pool maintains itself as rules are added.
	 */
	public void collectRegions(java.util.Collection<Integer> into)
	{
		if (regions != null)
		{
			for (Integer region : regions)
			{
				if (region != null)
				{
					into.add(region);
				}
			}
		}
		if (conditions != null)
		{
			for (Condition child : conditions)
			{
				if (child != null)
				{
					child.collectRegions(into);
				}
			}
		}
	}

	/** Whether this condition tree contains the given type (case-insensitive). */
	public boolean usesType(String wanted)
	{
		if (wanted.equalsIgnoreCase(type))
		{
			return true;
		}
		if (conditions != null)
		{
			for (Condition child : conditions)
			{
				if (child != null && child.usesType(wanted))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static int orDefault(Integer boxed, int fallback)
	{
		return boxed == null ? fallback : boxed;
	}

	/**
	 * The poison varp holds small cycle values while poisoned; venom is encoded
	 * as the same varp pushed above a million. Same scheme RuneLite's own
	 * poison plugin decodes.
	 */
	private static final int VENOM_THRESHOLD = 1_000_000;
}

package com.follower.speech;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads dialogs.json and reloads it when it changes, exactly as
 * {@link RuleLoader} does for phrases.json - same poll, same defaults-on-first-
 * run, same refusal to replace good content with nothing on a bad read.
 */
@Slf4j
@Singleton
public class DialogLoader
{
	public static final String FILE_NAME = "dialogs.json";

	/** The bundled trees as of the last merge, for the three-way. */
	public static final String BASE_FILE = "dialogs-seen.json";

	/** Handled by the node pass rather than as a field of the tree. */
	private static final java.util.Set<String> TREE_FIELDS =
		new java.util.HashSet<>(java.util.Arrays.asList("nodes", "id"));

	/** Lines have their own pass; the id is what we matched on. */
	private static final java.util.Set<String> NODE_FIELDS =
		new java.util.HashSet<>(java.util.Arrays.asList("says", "id"));
	private static final String BUNDLED_DEFAULT = "/com/follower/default-dialogs.json";

	private static final int SUPPORTED_VERSION = 1;

	private final Gson gson;

	private Map<String, DialogTree> trees = Collections.emptyMap();

	@Getter
	private String status = "not loaded";

	@Getter
	private List<String> errors = Collections.emptyList();

	private Path file;
	private Path baseFile;
	private long lastModified = -1L;
	private long lastSize = -1L;

	@Inject
	public DialogLoader(Gson gson)
	{
		this.gson = gson;
	}

	public void initialise(Path dataDir)
	{
		initialise(dataDir, false);
	}

	/**
	 * @param mergeDefaults whether to fold newly bundled trees into an
	 * existing file first. The plugin passes true; the test harnesses supply
	 * exact files and pass false through the plain overload.
	 */
	public void initialise(Path dataDir, boolean mergeDefaults)
	{
		file = dataDir.resolve(FILE_NAME);
		baseFile = dataDir.resolve(BASE_FILE);
		if (!Files.exists(file))
		{
			writeDefaults();
		}
		else if (mergeDefaults)
		{
			mergeNewDefaults();
		}
		reload();
	}

	/**
	 * Folds bundled conversation changes into the player's file, three ways.
	 *
	 * <p>The same upgrade gap {@code phrases.json} had, and fixed the same way -
	 * see {@link ThreeWay}. Appending only whole new trees meant a reworded
	 * node, an added choice or a fixed dead end reached nobody who already had
	 * the plugin.
	 *
	 * <p>Trees merge at two levels because that is how they are built: the tree
	 * carries its own fields and a list of nodes, and each node carries its own
	 * fields and its lines. A node the update added arrives, a node it removed
	 * goes unless the player had already changed it, and a node they have
	 * rewritten is theirs.
	 */
	private void mergeNewDefaults()
	{
		try (InputStream in = DialogLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				return;
			}
			Gson pretty = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
			com.google.gson.JsonObject bundled = pretty.fromJson(
				new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			com.google.gson.JsonObject ours = pretty.fromJson(
				new String(Files.readAllBytes(file), java.nio.charset.StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			if (bundled == null || ours == null
				|| !bundled.has("trees") || !ours.has("trees"))
			{
				return;
			}

			com.google.gson.JsonObject base = readBase(pretty);
			java.util.Map<String, com.google.gson.JsonObject> mine =
				ThreeWay.byId(ThreeWay.array(ours, "trees"));
			java.util.Map<String, com.google.gson.JsonObject> was =
				ThreeWay.byId(ThreeWay.array(base, "trees"));

			com.google.gson.JsonArray trees = ours.getAsJsonArray("trees");
			int added = 0;
			int updated = 0;
			for (com.google.gson.JsonElement element : bundled.getAsJsonArray("trees"))
			{
				String id = ThreeWay.idOf(element);
				if (id == null)
				{
					continue;
				}
				com.google.gson.JsonObject held = mine.get(id);
				if (held == null)
				{
					trees.add(element);
					added++;
					continue;
				}
				if (mergeTree(held, was.get(id), element.getAsJsonObject()) > 0)
				{
					updated++;
				}
			}

			if (added > 0 || updated > 0)
			{
				Files.copy(file, file.resolveSibling(file.getFileName() + ".bak"),
					java.nio.file.StandardCopyOption.REPLACE_EXISTING);
				Files.write(file, (pretty.toJson(ours) + "\n")
					.getBytes(java.nio.charset.StandardCharsets.UTF_8));
				log.info("Merged {} new tree(s) and {} changed tree(s) into {}",
					added, updated, file);
			}

			// Last, and whether or not anything moved, so a merge that only
			// half-happened is retried rather than recorded as done.
			writeBase(bundled, pretty);
		}
		catch (Exception e)
		{
			log.warn("Could not merge new defaults into {}", file, e);
		}
	}

	/** One bundled tree, folded into the player's copy of it. */
	private static int mergeTree(com.google.gson.JsonObject held,
		com.google.gson.JsonObject base, com.google.gson.JsonObject bundled)
	{
		if (base == null)
		{
			return bootstrap(held, bundled);
		}

		int changes = ThreeWay.fields(held, base, bundled, TREE_FIELDS);

		com.google.gson.JsonArray nodes = ThreeWay.array(held, "nodes");
		com.google.gson.JsonArray shipped = ThreeWay.array(bundled, "nodes");
		if (nodes == null || shipped == null)
		{
			return changes;
		}
		java.util.Map<String, com.google.gson.JsonObject> wasNodes =
			ThreeWay.byId(ThreeWay.array(base, "nodes"));

		java.util.Set<String> shippedIds = new java.util.HashSet<>();
		for (com.google.gson.JsonElement element : shipped)
		{
			String id = ThreeWay.idOf(element);
			if (id != null)
			{
				shippedIds.add(id);
			}
		}

		// Rebuilt rather than edited in place, because a node can leave.
		java.util.List<com.google.gson.JsonObject> kept = new java.util.ArrayList<>();
		java.util.Set<String> keptIds = new java.util.HashSet<>();
		for (com.google.gson.JsonElement element : nodes)
		{
			if (!element.isJsonObject())
			{
				continue;
			}
			com.google.gson.JsonObject node = element.getAsJsonObject();
			String id = ThreeWay.idOf(element);
			com.google.gson.JsonObject before = id == null ? null : wasNodes.get(id);
			if (id != null && before != null && !shippedIds.contains(id)
				&& before.equals(node))
			{
				// The update removed it and the player never touched it.
				changes++;
				continue;
			}
			kept.add(node);
			if (id != null)
			{
				keptIds.add(id);
			}
		}

		for (com.google.gson.JsonElement element : shipped)
		{
			String id = ThreeWay.idOf(element);
			if (id == null)
			{
				continue;
			}
			com.google.gson.JsonObject now = element.getAsJsonObject();
			if (!keptIds.contains(id))
			{
				// Absent here: new upstream unless the player deleted it, and
				// the base is what tells the two apart.
				if (!wasNodes.containsKey(id))
				{
					kept.add(now);
					changes++;
				}
				continue;
			}
			com.google.gson.JsonObject node = null;
			for (com.google.gson.JsonObject candidate : kept)
			{
				if (id.equals(ThreeWay.idOf(candidate)))
				{
					node = candidate;
					break;
				}
			}
			// A node the base never had is one the player wrote; comparing it
			// with itself leaves it alone, which is the intent.
			com.google.gson.JsonObject before = wasNodes.getOrDefault(id, node);
			changes += ThreeWay.fields(node, before, now, NODE_FIELDS);
			changes += ThreeWay.strings(node, "says", before, now);
		}

		if (changes > 0)
		{
			com.google.gson.JsonArray out = new com.google.gson.JsonArray();
			for (com.google.gson.JsonObject node : kept)
			{
				out.add(node);
			}
			held.add("nodes", out);
		}
		return changes;
	}

	/**
	 * The first run, with no record of what shipped before. As with the rules,
	 * the only honest question left is whether the player has written into
	 * this tree at all: a tree holding nothing but shipped lines has not been,
	 * and can be brought up to date without taking anything from anybody.
	 */
	private static int bootstrap(com.google.gson.JsonObject held,
		com.google.gson.JsonObject bundled)
	{
		if (!ThreeWay.untouched(allSays(held), allSays(bundled)))
		{
			return 0;
		}
		if (held.equals(bundled))
		{
			return 0;
		}
		for (String key : new java.util.ArrayList<>(held.keySet()))
		{
			held.remove(key);
		}
		for (java.util.Map.Entry<String, com.google.gson.JsonElement> entry : bundled.entrySet())
		{
			held.add(entry.getKey(), entry.getValue());
		}
		return 1;
	}

	/** Every line the tree can speak, for the bootstrap's one question. */
	private static java.util.List<String> allSays(com.google.gson.JsonObject tree)
	{
		java.util.List<String> out = new java.util.ArrayList<>();
		com.google.gson.JsonArray nodes = ThreeWay.array(tree, "nodes");
		if (nodes == null)
		{
			return out;
		}
		for (com.google.gson.JsonElement element : nodes)
		{
			if (element.isJsonObject())
			{
				out.addAll(ThreeWay.strings(element.getAsJsonObject(), "says"));
			}
		}
		return out;
	}

	/** The trees as they shipped at the last merge, or null if never written. */
	private com.google.gson.JsonObject readBase(Gson pretty)
	{
		if (baseFile == null || !Files.exists(baseFile))
		{
			return null;
		}
		try
		{
			return pretty.fromJson(new String(Files.readAllBytes(baseFile),
				java.nio.charset.StandardCharsets.UTF_8), com.google.gson.JsonObject.class);
		}
		catch (Exception e)
		{
			log.warn("Could not read {}, merging without a base", baseFile, e);
			return null;
		}
	}

	private void writeBase(com.google.gson.JsonObject bundled, Gson pretty)
	{
		if (baseFile == null)
		{
			return;
		}
		try
		{
			Files.write(baseFile, (pretty.toJson(bundled) + "\n")
				.getBytes(java.nio.charset.StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			log.warn("Could not record the merged defaults in {}", baseFile, e);
		}
	}

	private static String treeIdOf(com.google.gson.JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		com.google.gson.JsonElement id = element.getAsJsonObject().get("id");
		return id != null && id.isJsonPrimitive() ? id.getAsString() : null;
	}

	public Path getFile()
	{
		return file;
	}

	public DialogTree get(String id)
	{
		return id == null ? null : trees.get(id);
	}

	/** Every tree, in file order. */
	public List<DialogTree> getTrees()
	{
		return new ArrayList<>(trees.values());
	}

	public boolean reloadIfChanged()
	{
		if (file == null || !Files.isRegularFile(file))
		{
			return false;
		}
		try
		{
			long modified = Files.getLastModifiedTime(file).toMillis();
			long size = Files.size(file);
			if (modified == lastModified && size == lastSize)
			{
				return false;
			}
		}
		catch (IOException e)
		{
			return false;
		}
		reload();
		return true;
	}

	public void reload()
	{
		if (file == null)
		{
			return;
		}

		List<String> problems = new ArrayList<>();

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			DialogFile parsed = gson.fromJson(reader, DialogFile.class);

			if (parsed == null)
			{
				// The same reasoning as phrases.json: an empty read is almost
				// always a poll landing between an editor truncating the file
				// and writing it back. Keep what we had and try again.
				errors = Collections.singletonList(
					"File is empty; keeping " + trees.size() + " previous trees");
				status = "empty file, keeping " + trees.size() + " previous trees";
				log.warn("dialogs.json read as empty; keeping the previous trees");
				return;
			}

			lastModified = Files.getLastModifiedTime(file).toMillis();
			lastSize = Files.size(file);

			if (parsed.version != SUPPORTED_VERSION)
			{
				problems.add("version is " + parsed.version
					+ ", plugin expects " + SUPPORTED_VERSION);
			}

			Map<String, DialogTree> valid = new LinkedHashMap<>();
			Set<String> seen = new HashSet<>();
			for (DialogTree tree : parsed.trees == null
				? Collections.<DialogTree>emptyList() : parsed.trees)
			{
				if (tree == null)
				{
					continue;
				}
				List<String> found = tree.problems();
				problems.addAll(found);
				if (!found.isEmpty())
				{
					// A broken tree is left out rather than half-loaded: a
					// conversation that dead-ends mid-branch is worse than one
					// that never opens, because the player is already in it.
					continue;
				}
				if (!seen.add(tree.id))
				{
					problems.add("Duplicate tree id '" + tree.id + "'");
				}
				valid.put(tree.id, tree);
			}

			trees = valid;
			errors = problems;
			status = valid.size() + " trees"
				+ (problems.isEmpty() ? "" : ", " + problems.size() + " warning(s)");
			// At INFO like the rule loader: when a conversation does not open,
			// the first thing worth knowing is whether it loaded at all.
			log.info("Loaded dialogs: {}", status);
		}
		catch (IOException e)
		{
			problems.add("Could not read " + file + ": " + e.getMessage());
			errors = problems;
			status = "read error";
		}
		catch (JsonParseException e)
		{
			// Keep the previous trees on a syntax error, as with phrases.json.
			problems.add("JSON error: " + e.getMessage());
			errors = problems;
			status = "syntax error, keeping " + trees.size() + " previous trees";
			log.warn("dialogs.json failed to parse", e);
		}
	}

	private void writeDefaults()
	{
		try (InputStream in = DialogLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				log.warn("Bundled {} is missing", BUNDLED_DEFAULT);
				return;
			}
			Files.createDirectories(file.getParent());
			Files.copy(in, file);
			log.debug("Wrote default dialogs to {}", file);
		}
		catch (IOException e)
		{
			log.warn("Could not write default dialogs to {}", file, e);
		}
	}

	public void restoreDefaults()
	{
		try
		{
			Files.deleteIfExists(file);
		}
		catch (IOException e)
		{
			log.warn("Could not remove {}", file, e);
		}
		writeDefaults();
		reload();
	}

	private static final class DialogFile
	{
		int version;
		List<DialogTree> trees;
	}
}

package com.follower.speech;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A conversation, as data.
 *
 * <p>The follower's everyday talk script is written in Java, which is fine for
 * something that never changes. These are different: they are the conversations
 * the follower STARTS, they replace the everyday one while they are open, and
 * they are where the player's answer to a question actually comes from. That
 * makes them content rather than plumbing, and content belongs in a file
 * somebody can edit without a compiler.
 *
 * <p>Nodes are a list rather than a map so their order survives a round trip
 * through the file, which is what lets the editor show them as a table in the
 * order they were written rather than in whatever order a hash gives back.
 */
public class DialogTree
{
	public String id;

	/** Free text, ignored by the plugin. */
	public String note;

	/** Which node the conversation opens on. Defaults to the first one. */
	public String start;

	public List<DialogNode> nodes;

	public static class DialogNode
	{
		public String id;

		/** Pages the FOLLOWER speaks, with its chathead. */
		public List<String> says;

		/** Pages the PLAYER speaks, with theirs. */
		public List<String> you;

		/** Where to go once the pages are done. Absent ends the conversation. */
		public String next;

		public List<DialogChoice> choices;

		/**
		 * Reaching this node answers the question the follower asked.
		 *
		 * <p>Any single plain word; {@code answered} rules match on it. This is
		 * the whole reason these trees exist: the answer used to be a word
		 * typed into public chat, which meant the follower was listening to the
		 * whole street and the player had to know the magic word. Picking an
		 * option cannot be misheard, cannot be ambiguous, and shows the player
		 * what their choices are - which is also why the vocabulary is not
		 * limited to yes and no. A menu offering "left" and "right" is exactly
		 * as unmistakable as one offering yes and no, and it can be a game.
		 */
		public String answer;

		public List<String> pages()
		{
			List<String> spoken = you != null && !you.isEmpty() ? you : says;
			return spoken == null ? new ArrayList<>() : spoken;
		}

		public boolean isPlayerSpeaking()
		{
			return you != null && !you.isEmpty();
		}
	}

	public static class DialogChoice
	{
		public String label;
		public String next;
	}

	/**
	 * Every problem that would stop this tree working, as sentences.
	 *
	 * <p>A dialog fails silently in the worst possible way - the box opens and
	 * closes again, or a branch dead-ends on a node id with a typo in it - so
	 * the checks are done once at load and reported, rather than discovered by
	 * a player halfway through a conversation.
	 */
	public List<String> problems()
	{
		List<String> found = new ArrayList<>();
		if (id == null || id.trim().isEmpty())
		{
			found.add("a tree with no id");
			return found;
		}
		if (nodes == null || nodes.isEmpty())
		{
			found.add(id + ": no nodes");
			return found;
		}

		Map<String, DialogNode> byId = new LinkedHashMap<>();
		for (DialogNode node : nodes)
		{
			if (node == null || node.id == null || node.id.trim().isEmpty())
			{
				found.add(id + ": a node with no id");
				continue;
			}
			if (byId.put(node.id, node) != null)
			{
				found.add(id + ": two nodes called '" + node.id + "'");
			}
		}

		String entry = startId();
		if (entry == null || !byId.containsKey(entry))
		{
			found.add(id + ": starts at '" + entry + "', which is not a node");
		}

		for (DialogNode node : byId.values())
		{
			if (node.next != null && !byId.containsKey(node.next))
			{
				found.add(id + ": '" + node.id + "' continues to '" + node.next
					+ "', which is not a node");
			}
			if (node.choices != null)
			{
				for (DialogChoice choice : node.choices)
				{
					if (choice == null || choice.label == null || choice.label.trim().isEmpty())
					{
						found.add(id + ": '" + node.id + "' has a choice with no label");
						continue;
					}
					if (choice.next == null || !byId.containsKey(choice.next))
					{
						found.add(id + ": '" + node.id + "' offers \"" + choice.label
							+ "\" leading to '" + choice.next + "', which is not a node");
					}
				}
			}
			if (node.answer != null && !node.answer.matches("[a-zA-Z0-9-]+"))
			{
				found.add(id + ": '" + node.id + "' answers '" + node.answer
					+ "'; an answer is a single plain word for a rule to match on");
			}
			if (node.pages().isEmpty() && node.choices == null && node.next == null)
			{
				found.add(id + ": '" + node.id + "' says nothing and goes nowhere");
			}
		}

		// A tree the follower opens to ask something, that the player cannot
		// answer, is a tree that wastes the one moment it had.
		boolean answerable = false;
		for (DialogNode node : byId.values())
		{
			if (node.answer != null)
			{
				answerable = true;
				break;
			}
		}
		if (!answerable)
		{
			found.add(id + ": no node answers anything, so nothing can come of it");
		}

		return found;
	}

	public String startId()
	{
		if (start != null && !start.trim().isEmpty())
		{
			return start;
		}
		return nodes == null || nodes.isEmpty() || nodes.get(0) == null
			? null : nodes.get(0).id;
	}

	public Map<String, DialogNode> byId()
	{
		Map<String, DialogNode> map = new LinkedHashMap<>();
		if (nodes != null)
		{
			for (DialogNode node : nodes)
			{
				if (node != null && node.id != null)
				{
					map.put(node.id, node);
				}
			}
		}
		return map;
	}
}

package com.follower.speech;

import com.follower.follower.FollowerEntity;
import com.follower.ui.ChatheadRenderer;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A conversation with the follower, drawn over the chatbox in the game's own
 * dialog style: chathead, speaker name, click-to-continue pages, and "Select an
 * Option" menus that branch.
 *
 * <p>Drawn rather than driven through the game's dialog interface because the
 * real dialog widgets only exist while the game itself has a conversation open,
 * and no script exists for a plugin to open one. The chathead is genuine even so
 * - {@link ChatheadRenderer} projects the follower's actual model - which is the
 * part a widget could never have shown, since a widget takes a model id and the
 * follower's model is composed in memory.
 */
@Singleton
@lombok.extern.slf4j.Slf4j
public class FollowerDialog extends Overlay
{
	/** One step of a conversation: some pages, then either options or a jump. */
	public static final class Node
	{
		private final String[] pages;
		private final boolean playerSpeaking;
		private String[] optionText = new String[0];
		private String[] optionNext = new String[0];
		private String next;

		/** Resolved fresh on every ENTRY to the node - a re-rolled joke, say. */
		private java.util.function.Supplier<String[]> dynamicPages;

		/** Latched when the node is reached, run when the conversation ENDS. */
		private Runnable onFinish;

		private Node(boolean playerSpeaking, String[] pages)
		{
			this.playerSpeaking = playerSpeaking;
			this.pages = pages;
		}

		/** The follower speaks these pages. */
		public static Node says(String... pages)
		{
			return new Node(false, pages);
		}

		/** The follower speaks pages resolved fresh each visit. */
		public static Node saysDynamic(java.util.function.Supplier<String[]> pages)
		{
			Node node = new Node(false, new String[0]);
			node.dynamicPages = pages;
			return node;
		}

		/** The player speaks these pages, with their own head and name. */
		public static Node you(String... pages)
		{
			return new Node(true, pages);
		}

		/** Continue to another node once the pages are done. */
		public Node then(String nodeId)
		{
			this.next = nodeId;
			return this;
		}

		/**
		 * Do something once the conversation is over, if this node was reached.
		 *
		 * <p>How a conversation reaches back out: reaching the node under "Go on
		 * then" is what tells the rules the player said yes.
		 *
		 * <p>Latched on arrival but run at the END, which is the whole point.
		 * The follower's reply to its own question goes overhead, and firing it
		 * the instant the branch is picked puts it above a dialog box the
		 * player is still reading - so the one line they were waiting for is
		 * the one they miss. Latched rather than run at the end unconditionally
		 * so that closing the box early still counts: the player answered, and
		 * whether they read the rest of it is their business.
		 */
		public Node onFinish(Runnable action)
		{
			this.onFinish = action;
			return this;
		}

		/**
		 * Runs the finish action now, if there is one. For the lint that
		 * cross-checks every answer a conversation can produce against the
		 * rules listening for one - the talk script's answers only exist
		 * inside these runnables, so the only honest way to enumerate them is
		 * to run them against a recording consumer.
		 */
		public void runFinish()
		{
			if (onFinish != null)
			{
				onFinish.run();
			}
		}

