	public FollowerDialog(Client client, FollowerEntity follower,
		MouseManager mouseManager, SpriteManager spriteManager,
		net.runelite.client.callback.ClientThread clientThread,
		com.follower.appearance.AppearanceComposer composer,
		net.runelite.client.input.KeyManager keyManager,
		com.follower.ui.GameFontRepository gameFonts)
	{
		this.client = client;
		this.follower = follower;
		this.mouseManager = mouseManager;
		this.spriteManager = spriteManager;
		this.clientThread = clientThread;
		this.composer = composer;
		this.keyManager = keyManager;
		this.gameFonts = gameFonts;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void register()
	{
		mouseManager.registerMouseListener(clickAdapter);
		keyManager.registerKeyListener(keyAdapter);
	}

	public void unregister()
	{
		mouseManager.unregisterMouseListener(clickAdapter);
		keyManager.unregisterKeyListener(keyAdapter);
	}

	public boolean isOpen()
	{
		return open;
	}

	/**
	 * Whatever the conversation reached that should happen once it is over.
	 * Held rather than run on arrival so the follower's spoken reply lands
	 * after the box is gone rather than over the top of it.
	 */
	private Runnable pendingFinish;

	private void latch(Node reached)
	{
		if (reached != null && reached.onFinish != null)
		{
			pendingFinish = reached.onFinish;
		}
	}

	/**
	 * Test seams. Reaching a node the real way needs a follower to face the
	 * player and a client to compose a chathead from, neither of which exists
	 * headlessly - and the behaviour worth pinning down here is only which
	 * moment the answer is delivered at. These touch the same fields and the
	 * same {@link #latch} and {@link #close} the real path does.
	 */
	void openForTest(Map<String, Node> conversation)
	{
		script = conversation;
		open = true;
		pendingFinish = null;
	}

	void reachForTest(String nodeId)
	{
		latch(script.get(nodeId));
	}

	public void close()
	{
		open = false;
		head = null;
		chatheadBase = null;
		talkAnimation = null;
		sweepMode = false;
		sweep = null;
		// An interrupt-close cancels any input still in flight, or a stale
		// queued action would fire a tick after the box is gone.
		pendingAction = null;
		awaitingContinue = false;
		pendingOptionIndex = -1;

		// Cleared before it runs: whatever it does, it must not be able to
		// arrive here a second time.
		Runnable finish = pendingFinish;
		pendingFinish = null;
		if (finish != null)
		{
			finish.run();
		}
	}

	/** Starts a conversation at {@code startId}. */
	public void start(String speakerName, Map<String, Node> conversation, String startId)
	{
		followerName = speakerName;
		script = conversation;
		open = true;
		// A fresh conversation inherits nothing from the last one; a leftover
		// would fire on the wrong ending entirely.
		pendingFinish = null;
		goTo(startId);
	}

	/** A one-off line with no branching. */
	public void say(String speakerName, String... pages)
	{
		Map<String, Node> single = new LinkedHashMap<>();
		single.put("start", Node.says(pages));
		start(speakerName, single, "start");
	}

	/** The current node's pages, resolved per ENTRY so dynamic nodes re-roll. */
	private String[] pages = new String[0];

	private void goTo(String nodeId)
	{
		node = nodeId == null ? null : script.get(nodeId);
		if (node == null)
		{
			close();
			return;
		}

		latch(node);

		pages = node.dynamicPages != null ? node.dynamicPages.get() : node.pages;
		page = 0;
		follower.facePlayer();
		refreshHead();
	}

	private void advance()
	{
		page++;
		if (page < pages.length || optionsVisible())
		{
			return;
		}
		if (node.next != null)
		{
			goTo(node.next);
		}
		else
		{
			close();
		}
	}

	private boolean optionsVisible()
	{
		return node != null && page >= pages.length && node.optionText.length > 0;
	}

	/** The composed dialogue-head model of the current speaker; null = fallback. */
	private net.runelite.api.Model chatheadBase;

	/**
	 * Angle-picker mode: the head drawn at every 45 degrees at once, labelled, so
	 * the right facing can be chosen by eye instead of guessed one value per
	 * rebuild. The game's own dialogs use yaw 0, but that is the client widget
	 * renderer's zero, which need not be this renderer's.
	 */
	private BufferedImage[] sweep;
	private boolean sweepMode;

	private static final int SWEEP_COUNT = 8;
	private static final int SWEEP_SIZE = 58;

	/** Yaw of each sweep cell, so the labels and the picked value always agree. */
	private int[] sweepYaws = new int[0];

	/**
	 * Builds the angle picker centred on {@code centre}, {@code step} apart, so it
	 * can go from a coarse eight-way sweep down to a fine one around a candidate.
	 * Client thread only - it composes a model.
	 */
	public void showSweep(com.follower.appearance.Outfit outfit, int centre, int step,
		boolean pitchAxis)
	{
		chatheadBase = outfit == null ? null : composer.composeChathead(outfit);
		net.runelite.api.Model crop = follower.getBaseModel();

		sweep = new BufferedImage[SWEEP_COUNT];
		sweepYaws = new int[SWEEP_COUNT];
		sweepIsPitch = pitchAxis;

		for (int i = 0; i < SWEEP_COUNT; i++)
		{
			int value = (centre + (i - SWEEP_COUNT / 2) * step) & 0x7ff;
			sweepYaws[i] = value;

			int yaw = pitchAxis ? headYaw : value;
			int pitch = pitchAxis ? value : headPitch;

			sweep[i] = chatheadBase != null
				? ChatheadRenderer.render(chatheadBase, null, SWEEP_SIZE, SWEEP_SIZE,
					yaw, pitch, headZoom, 1.0)
				: ChatheadRenderer.render(crop, null, SWEEP_SIZE, SWEEP_SIZE,
					yaw, pitch, headZoom, headFraction);
		}

		sweepMode = true;
		open = true;
	}

	private boolean sweepIsPitch;

	private void drawSweep(Graphics2D graphics)
	{
		graphics.setFont(PLAIN_12);
		int columns = 4;
		int cellW = bounds.width / columns;
		int rowH = (bounds.height - 18) / 2;

		for (int i = 0; i < SWEEP_COUNT; i++)
		{
			int cx = bounds.x + (i % columns) * cellW;
			int cy = bounds.y + (i / columns) * rowH + 6;

			if (sweep[i] != null)
			{
				graphics.drawImage(sweep[i], cx + (cellW - SWEEP_SIZE) / 2, cy, null);
			}
			drawCentred(graphics, String.valueOf(sweepYaws[i]),
				cx, cellW, cy + SWEEP_SIZE + 11, TEXT);
		}

		drawCentred(graphics, sweepIsPitch
				? "Best tilt? ::follower head pitch <number>"
				: "Best facing? ::follower head yaw <number>",
			bounds.x, bounds.width, bounds.y + bounds.height - 4, CONTINUE);
	}

	/** The talking animation state, advanced on the wall clock while drawing. */
	private net.runelite.api.Animation talkAnimation;
	private int talkFrame;
	private long talkCarryMs;
	private long lastTalkMs;

	/** The chathead talking sequence; tunable, since ids are folklore. */
	@lombok.Setter
	@lombok.Getter
	private int talkAnimationId = 588;

	/**
	 * Rebuilds the head for whoever is speaking, on the client thread - model
	 * loading is client-thread-only, and clicks that change speaker arrive on the
	 * AWT thread.
	 *
	 * <p>Prefers the game's own dialogue-head models (helm head variant, hair and
	 * jaw chatheads, coloured through the same palette as the body); falls back to
	 * cropping the body model when the dump has no head data for the outfit.
	 */
	private void refreshHead()
	{
		boolean player = node.playerSpeaking;
		headIsPlayer = player;

		clientThread.invoke(() ->
		{
			chatheadBase = null;
			head = null;
			talkAnimation = null;
			talkFrame = 0;
			talkCarryMs = 0;
			lastTalkMs = System.currentTimeMillis();

			com.follower.appearance.Outfit outfit = null;
			net.runelite.api.Model cropModel = null;

			if (player)
			{
				Player local = client.getLocalPlayer();
				if (local != null && local.getPlayerComposition() != null)
				{
					outfit = com.follower.appearance.Outfit.from(local.getPlayerComposition());
					// The live actor model is shared and recycled, so on the fallback
					// path it is rendered to an image immediately and never held.
					cropModel = local.getModel();
				}
			}
			else
			{
				outfit = followerOutfit == null ? null : followerOutfit.get();
				cropModel = follower.getBaseModel();
			}

			if (outfit != null)
			{
				chatheadBase = composer.composeChathead(outfit);
			}
			if (chatheadBase == null)
			{
				head = ChatheadRenderer.render(cropModel, null, headWidth(), headHeight(),
					headTurn(), headPitch, headZoom, headFraction, headWidth() / 2, originY());
			}
		});
	}

	/**
	 * The current animated head image, posed at the talking animation's current
	 * frame. Called from the overlay render pass, which runs on the client thread,
	 * so posing here is legal. The posed model comes back on the client's shared
	 * scratch buffer and is rendered to pixels immediately, never held.
	 */
	private BufferedImage animatedHead()
	{
		if (chatheadBase == null)
		{
			return head;
		}

		if (talkAnimation == null)
		{
			talkAnimation = client.loadAnimation(talkAnimationId);
			if (talkAnimation == null || talkAnimation.getFrameLengths() == null)
			{
				talkAnimation = null;
				return ChatheadRenderer.render(chatheadBase, null, headWidth(), headHeight(),
					headTurn(), headPitch, headZoom, 1.0, headWidth() / 2, originY());
			}
		}

		// Advance on the wall clock: frame lengths are in 20ms client cycles.
		int[] lengths = talkAnimation.getFrameLengths();
		long now = System.currentTimeMillis();
		talkCarryMs += Math.min(now - lastTalkMs, 600);
		lastTalkMs = now;
		while (talkCarryMs >= lengths[talkFrame] * 20L)
		{
			talkCarryMs -= lengths[talkFrame] * 20L;
			talkFrame = (talkFrame + 1) % lengths.length;
		}

		net.runelite.api.Model posed = client.applyTransformations(
			chatheadBase, talkAnimation, talkFrame, null, 0);
		return ChatheadRenderer.render(posed == null ? chatheadBase : posed,
			chatheadBase, headWidth(), headHeight(), headTurn(), headPitch, headZoom, 1.0, headWidth() / 2, originY());
	}

	private String speakerName()
	{
		if (!headIsPlayer)
		{
			return followerName;
		}
		Player local = client.getLocalPlayer();
		return local == null || local.getName() == null ? "You" : local.getName();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!open || (node == null && !sweepMode))
		{
			return null;
		}

		Widget chat = client.getWidget(InterfaceID.CHATBOX, 0);
		Rectangle area = chat != null && !chat.isHidden()
			? chat.getBounds()
			: new Rectangle(0, client.getCanvasHeight() - 165, 519, 165);
		if (area.width <= 0 || area.height <= BUTTON_STRIP)
		{
			return null;
		}

		// Stop short of the filter buttons, as the game's own dialog does - and
		// because bounds is also the click region, this leaves them clickable.
		bounds = new Rectangle(area.x, area.y, area.width, area.height - BUTTON_STRIP);

		// The game draws its text with a bitmap font and no antialiasing. Leaving
		// AA on softens and visibly thickens every glyph, which is what made this
		// box read as "bolder" than a real one even with the right typeface.
		graphics.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
			java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		graphics.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
			java.awt.RenderingHints.VALUE_ANTIALIAS_OFF);

		drawBackground(graphics);

		if (sweepMode)
		{
			drawSweep(graphics);
			return null;
		}

		if (optionsVisible())
		{
			drawOptions(graphics);
		}
		else
		{
			drawSpeech(graphics);
		}

		if (tuning)
		{
			graphics.setFont(PLAIN_12);
			graphics.setColor(HOVER);
			graphics.drawString("turn " + npcTurn + "  pitch " + headPitch
				+ "  (arrows adjust, shift = fine)", bounds.x + 6, bounds.y + 12);
		}

		return null;
	}

	private void drawBackground(Graphics2D graphics)
	{
		BufferedImage sprite = spriteManager.getSprite(CHATBOX_SPRITE, 0);
		if (sprite != null)
		{
			graphics.drawImage(sprite, bounds.x, bounds.y, bounds.width, bounds.height, null);
		}
		else
		{
			// The sprite loads asynchronously; a matched fill covers the first frames.
			graphics.setColor(PARCHMENT);
			graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
		}
	}

	private void drawSpeech(Graphics2D graphics)
	{
		BufferedImage face = animatedHead();

		// The canvas is anchored so the model's origin lands at the measured
		// widget centre, its top row IS the dialog's top row, and the blit clips
		// at the dialog bounds - so tall hair is cut exactly where the real chat
		// surface cuts it. The PLAYER'S head anchors at the measured right-side
		// cell, the way a real player dialog mirrors the NPC one.
		int headCentreX = headIsPlayer
			? playerHeadRect.x + playerHeadRect.width / 2
			: originX();
		if (face != null)
		{
			// Clip at the dialog INTERFACE edge - the inner parchment - which is
			// the surface the real client cuts models at. Clipping at the outer
			// chatbox frame let hair run about six pixels too high, over the
			// border, which a real head never does.
			java.awt.Shape oldClip = graphics.getClip();
			int clipTop = bounds.y + dialogInsetY + clipTopExtra;
			graphics.setClip(bounds.x + dialogInsetX, clipTop,
				bounds.width - dialogInsetX * 2, bounds.y + bounds.height - clipTop);
			graphics.drawImage(face,
				bounds.x + headCentreX - face.getWidth() / 2, bounds.y, null);
			graphics.setClip(oldClip);
		}

		// The measured text column: 380 wide at x=115 beside an NPC head on the
		// left, x=24 with the player's head on the right.
		com.follower.ui.GameFont font = gameFonts.get(DIALOG_FONT_ID);
		int cellX = bounds.x + (headIsPlayer ? PLAYER_TEXT_X : NPC_TEXT_X);

		drawCell(graphics, font, speakerName(), cellX, TEXT_WIDTH,
			bounds.y + NAME_TOP, NAME.getRGB() & 0xFFFFFF);

		String[] wrapped = wrap(graphics, font, pages[page], TEXT_WIDTH);
		int lineHeight = measuredLineHeight(wrapped.length);
		int top = bounds.y + BODY_TOP + (BODY_HEIGHT - wrapped.length * lineHeight) / 2;
		for (String line : wrapped)
		{
			drawCell(graphics, font, line, cellX, TEXT_WIDTH, top, 0x000000);
			top += lineHeight;
		}

		// The client's own in-flight text: after a continue click, the prompt
		// reads "Please wait..." in its BASE colour (no hover white) until the
		// tick lands.
		String prompt = awaitingContinue ? "Please wait..." : "Click here to continue";
		int promptTop = bounds.y + CONTINUE_TOP;
		int promptWidth = textWidth(graphics, font, prompt);
		continueBounds = new Rectangle(
			cellX + (TEXT_WIDTH - promptWidth) / 2, promptTop, promptWidth, ROW_HEIGHT);

		drawCell(graphics, font, prompt, cellX, TEXT_WIDTH, promptTop,
			!awaitingContinue && hovered(continueBounds) ? 0xFFFFFF : 0x0000FF);
	}

	/**
	 * One line centred in a measured cell: the game's own glyphs when the font
	 * dump is loaded, the bundled TTF otherwise. {@code top} is the line's top
	 * edge - the glyphs' baked offsets place them within it, exactly as the
	 * client's font renderer does.
	 */
	private void drawCell(Graphics2D graphics, com.follower.ui.GameFont font,
		String text, int cellX, int cellWidth, int top, int rgb)
	{
		if (font != null)
		{
			font.drawTop(graphics, text,
				cellX + (cellWidth - font.stringWidth(text)) / 2, top, rgb, false);
			return;
		}
		graphics.setFont(PLAIN_12);
		graphics.setColor(new Color(rgb));
		int width = graphics.getFontMetrics().stringWidth(text);
		graphics.drawString(text, cellX + (cellWidth - width) / 2, top + 13);
	}

	private int textWidth(Graphics2D graphics, com.follower.ui.GameFont font, String text)
	{
		if (font != null)
		{
			return font.stringWidth(text);
		}
		graphics.setFont(PLAIN_12);
		return graphics.getFontMetrics().stringWidth(text);
	}

	/** True when the mouse is inside {@code area} on the canvas. */
	private boolean hovered(Rectangle area)
	{
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		return mouse != null && area.contains(mouse.getX(), mouse.getY());
	}

	private void drawOptions(Graphics2D graphics)
	{
		com.follower.ui.GameFont font = gameFonts.get(DIALOG_FONT_ID);
		int cellX = bounds.x + OPTION_X;

		drawCell(graphics, font, "Select an option", cellX, OPTION_WIDTH,
			bounds.y + OPTION_HEADER_TOP, NAME.getRGB() & 0xFFFFFF);

		// The game's own sword ornaments beside the header, at their measured
		// cells - sprite 302 left, mirror 301 right.
		BufferedImage swordLeft = spriteManager.getSprite(SWORD_LEFT_SPRITE, 0);
		BufferedImage swordRight = spriteManager.getSprite(SWORD_RIGHT_SPRITE, 0);
		if (swordLeft != null)
		{
			graphics.drawImage(swordLeft, bounds.x + SWORD_LEFT_X, bounds.y + SWORD_Y, null);
		}
		if (swordRight != null)
		{
			graphics.drawImage(swordRight, bounds.x + SWORD_RIGHT_X, bounds.y + SWORD_Y, null);
		}

		int count = node.optionText.length;
		int step = optionStep(count);
		int cellHeight = optionCellHeight(count);
		optionBounds = new Rectangle[count];
		int top = bounds.y + optionFirstTop(count);
		for (int i = 0; i < count; i++)
		{
			Rectangle row = new Rectangle(cellX, top, OPTION_WIDTH, cellHeight);
			optionBounds[i] = row;

			// Options are vertically centred in their cell (yAlign=1); the
			// 16-tall cell is the font's own line box, so only taller cells
			// push the text down. A clicked option shows the client's own
			// "Please wait..." until the tick lands - and unlike the continue
			// button (whose colour the client forces to base), options keep
			// their hover white while waiting.
			String label = i == pendingOptionIndex ? "Please wait..." : node.optionText[i];
			drawCell(graphics, font, label, cellX, OPTION_WIDTH,
				top + (cellHeight - 16) / 2, hovered(row) ? 0xFFFFFF : 0x000000);
			top += step;
		}
	}

	/**
	 * Crisp flat text, centred in its column. Deliberately NO shadow: dialog text
	 * on parchment has none in the real client, and a shadow visibly fattens the
	 * glyphs - it was what made this box read "bolder" than a real one.
	 */
	private void drawCentred(Graphics2D graphics, String text,
		int left, int width, int y, Color color)
	{
		int textWidth = graphics.getFontMetrics().stringWidth(text);
		graphics.setColor(color);
		graphics.drawString(text, left + (width - textWidth) / 2, y);
	}

	/**
	 * Greedy word wrap measured with the GAME's own advances when available -
	 * wrap decisions have to agree with the renderer or lines land wrong. A
	 * single word longer than the column is left to overflow.
	 */
	private String[] wrap(Graphics2D graphics, com.follower.ui.GameFont font,
		String text, int maxWidth)
	{
		java.util.List<String> out = new java.util.ArrayList<>();
		StringBuilder line = new StringBuilder();

		for (String word : text.split(" "))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (textWidth(graphics, font, candidate) > maxWidth && line.length() > 0)
			{
				out.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(candidate);
			}
		}
		if (line.length() > 0)
		{
			out.add(line.toString());
		}
		return out.toArray(new String[0]);
	}
}

package com.follower.speech;

import com.follower.FollowerConfig;
import com.follower.follower.FollowerEntity;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the follower's overhead chat.
 *
 * <p>A {@code RuneLiteObject} isn't an {@code Actor}, so the client's real overhead
 * chat system can't be used - the text is projected and drawn by hand, to the
 * client's own recipe (its chat-above-head draw, ported verbatim): the BOLD 12
 * glyph font, a black copy one pixel STRAIGHT DOWN (not diagonal), the coloured
 * text over it, centred on the entity's projected height point, and no fade -
 * real overhead text simply disappears when its timer ends.
 */
public class FollowerOverlay extends Overlay
{
	private static final int MAX_LINE_CHARS = 34;

	private final Client client;
	private final FollowerEntity follower;
	private final FollowerConfig config;
	private final com.follower.ui.GameFontRepository gameFonts;

	private String message;
	private long shownAtMs;
	private long durationMs;

	@Inject
	public FollowerOverlay(Client client, FollowerEntity follower, FollowerConfig config,
		com.follower.ui.GameFontRepository gameFonts)
	{
		this.client = client;
		this.follower = follower;
		this.config = config;
		this.gameFonts = gameFonts;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	public void show(String text, long durationMs)
	{
		this.message = text;
		this.shownAtMs = System.currentTimeMillis();
		this.durationMs = durationMs;
	}

	public void clear()
	{
		message = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (message == null || !follower.isSpawned())
		{
			return null;
		}

		long elapsed = System.currentTimeMillis() - shownAtMs;
		if (elapsed > durationMs)
		{
			message = null;
			return null;
		}

		LocalPoint location = follower.getLastRenderedLocation();
		if (location == null)
		{
			return null;
		}

		List<String> lines = wrap(message);
		int zOffset = config.speechHeight();
		int rgb = config.speechColor().getRGB() & 0xFFFFFF;

		// The client's own overhead draw: BOLD 12 glyphs, centred on the
		// entity's projected height point, black copy one pixel straight down,
		// coloured text over it, stacked upward by the font's height. No fade -
		// real overhead text just disappears.
		com.follower.ui.GameFont b12 = gameFonts.getByName("b12_full");
		if (b12 != null)
		{
			Point anchor = Perspective.localToCanvas(client, location,
				client.getTopLevelWorldView().getPlane(), zOffset);
			if (anchor == null)
			{
				return null;
			}
			int lineHeight = b12.getLineHeight();
			for (int i = 0; i < lines.size(); i++)
			{
				int baseline = anchor.getY() - (lines.size() - 1 - i) * lineHeight;
				b12.drawCenteredOverhead(graphics, lines.get(i),
					anchor.getX(), baseline, rgb);
			}
			return null;
		}

		// Fallback while fonts.json is missing: RuneLite's recreation.
		graphics.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics metrics = graphics.getFontMetrics();
		Point anchor = Perspective.getCanvasTextLocation(
			client, graphics, location, lines.get(0), zOffset);
		if (anchor == null)
		{
			return null;
		}
		int lineHeight = metrics.getHeight();
		int centreX = anchor.getX() + metrics.stringWidth(lines.get(0)) / 2;
		for (int i = 0; i < lines.size(); i++)
		{
			String line = lines.get(i);
			int x = centreX - metrics.stringWidth(line) / 2;
			int y = anchor.getY() - (lines.size() - 1 - i) * lineHeight;
			graphics.setColor(Color.BLACK);
			graphics.drawString(line, x, y + 1);
			graphics.setColor(config.speechColor());
			graphics.drawString(line, x, y);
		}

		return null;
	}

	private static List<String> wrap(String text)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();

		for (String word : text.split(" "))
		{
			if (line.length() > 0 && line.length() + 1 + word.length() > MAX_LINE_CHARS)
			{
				lines.add(line.toString());
				line.setLength(0);
			}
			if (line.length() > 0)
			{
				line.append(' ');
			}
			line.append(word);
		}

		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		if (lines.isEmpty())
		{
			lines.add(text);
		}
		return lines;
	}
}

package com.follower.speech;

import java.util.ArrayList;
import java.util.List;

/** Root object of phrases.json. */
public class RuleFile
{
	public static final int SUPPORTED_VERSION = 1;

	public int version = SUPPORTED_VERSION;

	/** Optional free text; ignored by the plugin. */
	public String comment;

	/**
	 * Names the follower may take to calling you by, keyed by the tally that
	 * earns each one: {@code {"deaths": "the gravedigger"}}.
	 *
	 * <p>Here rather than in the code because it is writing, and all the other
	 * writing is here. Whichever tally is highest, past a threshold, supplies
	 * {nickname}; a rule file that leaves this out simply has a follower that
	 * never gives you one.
	 */
	public java.util.Map<String, String> nicknames;

	public List<SpeechRule> rules = new ArrayList<>();
}

package com.follower.speech;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads phrases.json and reloads it when the file changes on disk, so you can edit
 * rules with the client running. Change detection is a lastModified/size poll
 * driven from the game tick — a WatchService buys nothing here and brings its own
 * platform quirks.
 */
@Slf4j
@Singleton
public class RuleLoader
{
	/** Fields the three-way must not touch: lines have their own pass. */
	private static final Set<String> SETTLED_BY_HAND =
		new HashSet<>(java.util.Arrays.asList("say", "id"));

	/** The bundled defaults as of the last merge, for the three-way. */
	public static final String BASE_FILE = "defaults-seen.json";

	public static final String FILE_NAME = "phrases.json";
	private static final String BUNDLED_DEFAULT = "/com/follower/default-phrases.json";

	private final Gson gson;

	@Getter
	private List<SpeechRule> rules = Collections.emptyList();
	private java.util.Set<String> bossNames = Collections.emptySet();
	private Path baseFile;

	@Getter
	private String status = "not loaded";

	@Getter
	private List<String> errors = Collections.emptyList();

	/**
	 * Whether any loaded rule uses the event-driven varbitChanged condition.
	 * Varbit changes arrive in floods (thousands at login), and dispatching
	 * each through every rule is pure waste when nothing listens - the
	 * state-based varbitEquals rules evaluate on the tick heartbeat instead.
	 */
	@Getter
	private boolean varbitEventRules;

	private Path file;
	private long lastModified = -1L;
	private long lastSize = -1L;

	@Inject
	public RuleLoader(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Points the loader at the data directory, writing the bundled default rules if
	 * no file exists yet, then loads.
	 */
	public void initialise(Path dataDir)
	{
		initialise(dataDir, false);
	}

	/**
	 * @param mergeDefaults whether to fold newly bundled rules into an
	 * existing file first. The plugin passes true; the test harnesses supply
	 * exact files and pass false through the plain overload.
	 */
	public void initialise(Path dataDir, boolean mergeDefaults)
	{
		file = dataDir.resolve(FILE_NAME);
		baseFile = dataDir.resolve(BASE_FILE);

		if (!Files.exists(file))
		{
			writeDefaults();
		}
		else if (mergeDefaults)
		{
			mergeNewDefaults();
		}

		reload();
	}

	/**
	 * Folds bundled changes into the player's file, three ways.
	 *
	 * <p>The old merge only ever APPENDED rules the file had never seen, which
	 * fixed the tester whose file predated the mimic rules and left a bigger
	 * hole behind it: a change to an existing rule reached nobody. Retuning the
	 * examine echo from 30% every three minutes to 70% every thirty, and
	 * writing twenty lines for it, changed nothing at all for anybody who
	 * already had the plugin - the work shipped and stayed invisible.
	 *
	 * <p>It could not be fixed by simply copying more across, because two
	 * situations look identical from the user's file alone: a line the update
	 * ADDED, and a line the player DELETED. Both are lines the bundled file has
	 * and theirs does not. Copying blindly resurrects everything anybody has
	 * ever removed.
	 *
	 * <p>So the defaults are kept as they stood at the last merge, in
	 * {@value #BASE_FILE}, and the question becomes answerable: bundled against
	 * BASE says what the update did, and theirs against base says what the
	 * player did. Upstream's changes are taken where the player has not touched
	 * that field, and the player wins everywhere they have. A line missing from
	 * theirs but present in base was deleted on purpose and stays gone; one
	 * that is in bundled but not in base is genuinely new and arrives.
	 *
	 * <p>Rules the editor deleted are recorded in the file's "removed" list and
	 * stay deleted. The file as it stood is kept beside the merged one as
	 * phrases.json.bak, and new nickname hooks arrive as before - existing keys
	 * are the user's to keep.
	 */
	private void mergeNewDefaults()
	{
		try (InputStream in = RuleLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				return;
			}
			Gson pretty = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
			com.google.gson.JsonObject bundled = pretty.fromJson(
				new java.io.InputStreamReader(in, StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			com.google.gson.JsonObject ours = pretty.fromJson(
				new String(Files.readAllBytes(file), StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			if (bundled == null || ours == null
				|| !bundled.has("rules") || !ours.has("rules"))
			{
				return;
			}

			// Null the first time this version runs: there is no record of what
			// shipped before, and mergeRule says what it does about that.
			com.google.gson.JsonObject base = readBase(pretty);

			Set<String> known = new HashSet<>();
			for (com.google.gson.JsonElement element : ours.getAsJsonArray("rules"))
			{
				String id = idOf(element);
				if (id != null)
				{
					known.add(id);
				}
			}
			if (ours.has("removed") && ours.get("removed").isJsonArray())
			{
				for (com.google.gson.JsonElement element : ours.getAsJsonArray("removed"))
				{
					if (element.isJsonPrimitive())
					{
						known.add(element.getAsString());
					}
				}
			}

			Map<String, com.google.gson.JsonObject> mine = byId(ours);
			Map<String, com.google.gson.JsonObject> was = byId(base);

			com.google.gson.JsonArray rules = ours.getAsJsonArray("rules");
			int added = 0;
			int updated = 0;
			for (com.google.gson.JsonElement element : bundled.getAsJsonArray("rules"))
			{
				String id = idOf(element);
				if (id == null || !element.isJsonObject())
				{
					continue;
				}
				if (!known.contains(id))
				{
					rules.add(element);
					added++;
					continue;
				}
				com.google.gson.JsonObject held = mine.get(id);
				// Absent but known means the editor deleted it; it stays deleted.
				if (held != null
					&& mergeRule(held, was.get(id), element.getAsJsonObject()) > 0)
				{
					updated++;
				}
			}

			int nicknamesAdded = 0;
			if (bundled.has("nicknames") && bundled.get("nicknames").isJsonObject())
			{
				com.google.gson.JsonObject theirs = bundled.getAsJsonObject("nicknames");
				com.google.gson.JsonObject held =
					ours.has("nicknames") && ours.get("nicknames").isJsonObject()
						? ours.getAsJsonObject("nicknames") : new com.google.gson.JsonObject();
				for (Map.Entry<String, com.google.gson.JsonElement> entry : theirs.entrySet())
				{
					if (!held.has(entry.getKey()))
					{
						held.add(entry.getKey(), entry.getValue());
						nicknamesAdded++;
					}
				}
				ours.add("nicknames", held);
			}

			if (added > 0 || updated > 0 || nicknamesAdded > 0)
			{
				Files.copy(file, file.resolveSibling(file.getFileName() + ".bak"),
					java.nio.file.StandardCopyOption.REPLACE_EXISTING);
				Files.write(file,
					(pretty.toJson(ours) + "\n").getBytes(StandardCharsets.UTF_8));
				log.info("Merged {} new rule(s), {} changed rule(s) and {} nickname(s) into {}",
					added, updated, nicknamesAdded, file);
			}

			// Written whether or not anything moved, and last, so a merge that
			// half-happened is retried rather than recorded as done. From here
			// on there is a base and the guessing above never runs again.
			writeBase(bundled, pretty);
		}
		catch (Exception e)
		{
			// A file that cannot be merged is one reload() will complain about
			// in its own words; do not block startup over it.
			log.warn("Could not merge new defaults into {}", file, e);
		}
	}

	/**
	 * Folds one bundled rule into the player's copy.
	 *
	 * @param base the rule as it was bundled at the last merge, or null when
	 * there is no record - see the bootstrap below
	 * @return how many changes were made, so the caller can count rules
	 */
	private static int mergeRule(com.google.gson.JsonObject held,
		com.google.gson.JsonObject base, com.google.gson.JsonObject bundled)
	{
		if (base == null)
		{
			return bootstrap(held, bundled);
		}

		return ThreeWay.fields(held, base, bundled, SETTLED_BY_HAND)
			+ ThreeWay.strings(held, "say", base, bundled);
	}

	/**
	 * The first run under this version, with no record of what shipped before.
	 *
	 * <p>Nothing can be deduced about deletions, so the only honest signal left
	 * is whether the player has written into the rule at all. If every line in
	 * their copy is one that ships, they have not - and taking the bundled rule
	 * is right, which is how a year of tuning finally reaches them. If they
	 * have added anything the rule is theirs and is left exactly alone this
	 * once; the base written afterwards makes every later merge exact.
	 *
	 * <p>{@code enabled} is the player's either way. Switching a rule off is a
	 * decision made in the editor and adopting over it would turn it back on.
	 */
	private static int bootstrap(com.google.gson.JsonObject held,
		com.google.gson.JsonObject bundled)
	{
		if (!ThreeWay.untouched(ThreeWay.strings(held, "say"),
			ThreeWay.strings(bundled, "say")))
		{
			return 0;
		}
		com.google.gson.JsonElement enabled = held.get("enabled");
		int before = ThreeWay.strings(held, "say").size();
		for (String key : new java.util.ArrayList<>(held.keySet()))
		{
			held.remove(key);
		}
		for (Map.Entry<String, com.google.gson.JsonElement> entry : bundled.entrySet())
		{
			held.add(entry.getKey(), entry.getValue());
		}
		if (enabled != null)
		{
			held.add("enabled", enabled);
		}
		return ThreeWay.strings(held, "say").size() == before && before > 0 ? 0 : 1;
	}

	private static Map<String, com.google.gson.JsonObject> byId(com.google.gson.JsonObject file)
	{
		return ThreeWay.byId(ThreeWay.array(file, "rules"));
	}

	/** The defaults as they stood at the last merge, or null if never written. */
	private com.google.gson.JsonObject readBase(Gson pretty)
	{
		if (baseFile == null || !Files.exists(baseFile))
		{
			return null;
		}
		try
		{
			return pretty.fromJson(
				new String(Files.readAllBytes(baseFile), StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
		}
		catch (Exception e)
		{
			// Unreadable is the same as absent: fall back to the bootstrap
			// rather than refusing to merge at all.
			log.warn("Could not read {}, merging without a base", baseFile, e);
			return null;
		}
	}

	private void writeBase(com.google.gson.JsonObject bundled, Gson pretty)
	{
		if (baseFile == null)
		{
			return;
		}
		try
		{
			Files.write(baseFile,
				(pretty.toJson(bundled) + "\n").getBytes(StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			// Only costs a repeat of the bootstrap next start, which is
			// idempotent, so it is not worth failing the merge over.
			log.warn("Could not record the merged defaults in {}", baseFile, e);
		}
	}

	private static String idOf(com.google.gson.JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		com.google.gson.JsonElement id = element.getAsJsonObject().get("id");
		return id != null && id.isJsonPrimitive() ? id.getAsString() : null;
	}

	public Path getFile()
	{
		return file;
	}

	/** Reloads if the file changed since last check. Returns true if rules were replaced. */
	public boolean reloadIfChanged()
	{
		if (file == null || !Files.isRegularFile(file))
		{
			return false;
		}

		try
		{
			long modified = Files.getLastModifiedTime(file).toMillis();
			long size = Files.size(file);
			if (modified == lastModified && size == lastSize)
			{
				return false;
			}
		}
		catch (IOException e)
		{
			return false;
		}

		reload();
		return true;
	}

	public void reload()
	{
		if (file == null)
		{
			return;
		}

		List<String> problems = new ArrayList<>();

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			RuleFile parsed = gson.fromJson(reader, RuleFile.class);

			if (parsed == null)
			{
				// An empty read is almost never an empty file on purpose. It is
				// what a poll sees in the instant between an editor truncating
				// the file and writing it back, and it is what a failed save
				// leaves behind. Treating it as "no rules" replaced the whole
				// personality with silence, which is exactly what the syntax
				// error path below is careful NOT to do. Keep what we had, say
				// so, and do not record this read as current - the next poll
				// then picks up the finished file.
				problems.add("File is empty; keeping " + rules.size() + " previous rules");
				errors = problems;
				status = "empty file, keeping " + rules.size() + " previous rules";
				log.warn("phrases.json read as empty; keeping the previous rules");
				return;
			}

			lastModified = Files.getLastModifiedTime(file).toMillis();
			lastSize = Files.size(file);

			if (parsed.version != RuleFile.SUPPORTED_VERSION)
			{
				problems.add("version is " + parsed.version + ", plugin expects " + RuleFile.SUPPORTED_VERSION);
			}

			List<SpeechRule> valid = new ArrayList<>();
			Set<String> seenIds = new HashSet<>();
			int index = 0;

			for (SpeechRule rule : parsed.rules == null ? Collections.<SpeechRule>emptyList() : parsed.rules)
			{
				index++;
				if (rule == null)
				{
					continue;
				}

				if (rule.id == null || rule.id.trim().isEmpty())
				{
					rule.id = "rule-" + index;
				}
				if (!seenIds.add(rule.id))
				{
					problems.add("Duplicate rule id '" + rule.id + "' — later one wins for cooldowns");
				}
				if (!rule.isValid())
				{
					problems.add("Rule '" + rule.id + "' needs a 'when' block and at least one of"
						+ " a non-empty 'say' list, an 'animation', or 'mirrorAnimation'");
					continue;
				}
				if (rule.group == null || rule.group.trim().isEmpty())
				{
					rule.group = "misc";
				}

				rule.reset();
				valid.add(rule);
			}

			valid.sort((a, b) -> Integer.compare(b.priority, a.priority));
			nicknames = parsed.nicknames == null
				? Collections.<String, String>emptyMap() : parsed.nicknames;
			apply(valid, problems, valid.size() + " rules");
		}
		catch (IOException e)
		{
			problems.add("Could not read " + file + ": " + e.getMessage());
			apply(Collections.emptyList(), problems, "read error");
		}
		catch (JsonParseException e)
		{
			// Keep the previous rules on a syntax error; losing your follower's whole
			// personality over a trailing comma is worse than running stale rules.
			problems.add("JSON error: " + e.getMessage());
			errors = problems;
			status = "syntax error, keeping " + rules.size() + " previous rules";
			log.warn("phrases.json failed to parse", e);
		}
	}

	/**
	 * Names the follower may earn for you, keyed by the tally that earns each.
	 * Reloaded with the rules, so editing the file re-reads them too.
	 */
	@lombok.Getter
	private Map<String, String> nicknames = Collections.emptyMap();

	/**
	 * Which condition type answers which event. Only the types that are gated
	 * on a specific event appear: a state condition (healthBelow, inRegion) can
	 * be true during ANY dispatch and so is never listed.
	 */
	private static final Map<TriggerEvent.Type, String[]> EVENT_CONDITIONS;

	static
	{
		EVENT_CONDITIONS = new EnumMap<>(TriggerEvent.Type.class);
		EVENT_CONDITIONS.put(TriggerEvent.Type.NPC_SPAWN, new String[]{"npcSpawn"});
		EVENT_CONDITIONS.put(TriggerEvent.Type.NPC_DESPAWN, new String[]{"npcDespawn"});
		EVENT_CONDITIONS.put(TriggerEvent.Type.VARBIT, new String[]{"varbitChanged"});
		// Busy scenes fire NPC overheads constantly; same economics as spawns.
		EVENT_CONDITIONS.put(TriggerEvent.Type.NPC_SHOUT, new String[]{"npcShout"});
	}

	private final Set<TriggerEvent.Type> listened = EnumSet.noneOf(TriggerEvent.Type.class);

	/**
	 * Whether any loaded rule can answer this kind of event.
	 *
	 * <p>Only meaningful for the FLOOD events - NPCs entering and leaving the
	 * scene, and varbits at login - which arrive in the hundreds within a single
	 * tick and each cost a pass over every rule. Everything else is rare enough
	 * that asking is not worth it.
	 *
	 * <p>Skipping a pass costs nothing a state rule needed: state only changes
	 * when the snapshot refreshes, once a tick, and the tick heartbeat always
	 * gets its own dispatch. It does mean a {@code chance} roll no longer
	 * happens per despawn, which is a fix rather than a loss - how talkative the
	 * follower is should not depend on how many NPCs happen to be wandering out
	 * of view.
	 */
	public boolean listensFor(TriggerEvent.Type type)
	{
		return !EVENT_CONDITIONS.containsKey(type) || listened.contains(type);
	}

	/**
	 * The NPC names the boss rules name, which is what the rest of the plugin
	 * means by "boss" - see {@link com.follower.speech.TriggerContext#isBoss}.
	 * Collected here because this is where the rules are already walked, and
	 * because the rule file is the only place the list should live.
	 */
	public java.util.Set<String> getBossNames()
	{
		return bossNames;
	}

	private void collectBossNames(Condition condition, java.util.Set<String> into)
	{
		if (condition == null)
		{
			return;
		}
		if (condition.type != null
			&& condition.type.toLowerCase(java.util.Locale.ROOT).startsWith("npc")
			&& condition.names != null)
		{
			into.addAll(condition.names);
		}
		if (condition.conditions != null)
		{
			for (Condition sub : condition.conditions)
			{
				collectBossNames(sub, into);
			}
		}
	}

	private void apply(List<SpeechRule> newRules, List<String> problems, String summary)
	{
		rules = newRules;
		errors = problems;

		java.util.Set<String> bosses = new java.util.HashSet<>();
		for (SpeechRule rule : newRules)
		{
			if ("boss".equalsIgnoreCase(rule.group))
			{
				collectBossNames(rule.when, bosses);
			}
		}
		bossNames = bosses;

		listened.clear();
		for (Map.Entry<TriggerEvent.Type, String[]> entry : EVENT_CONDITIONS.entrySet())
		{
			for (SpeechRule rule : newRules)
			{
				if (rule.when == null)
				{
					continue;
				}
				for (String conditionType : entry.getValue())
				{
					if (rule.when.usesType(conditionType))
					{
						listened.add(entry.getKey());
						break;
					}
				}
			}
		}
		varbitEventRules = listened.contains(TriggerEvent.Type.VARBIT);

		status = summary + (problems.isEmpty() ? "" : ", " + problems.size() + " warning(s)");
		log.info("Loaded rules: {}", status);
		log.debug("Flood events with listeners: {}", listened);
	}

	private void writeDefaults()
	{
		try (InputStream in = RuleLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				log.warn("Bundled default rules missing from jar");
				return;
			}
			Files.createDirectories(file.getParent());
			Files.copy(in, file);
			log.info("Wrote starter rules to {}", file);
		}
		catch (IOException e)
		{
			log.warn("Could not write default rules to {}", file, e);
		}
	}
}

package com.follower.speech;

import java.util.concurrent.ThreadLocalRandom;

/**
 * Decides when the follower has said enough for now.
 *
 * <p>The speech gap already stops two lines landing on top of each other, but a
 * gap is a floor and nothing more: at three seconds apart, a follower with
 * plenty to react to will talk for as long as things keep happening, and every
 * line lands in the same flat stream as the one before it. Nothing is ever
 * quiet, so nothing is ever loud.
 *
 * <p>This is the survival-horror director model, which exists for exactly that
 * problem. A running intensity rises with each thing said and decays with time;
 * crossing a peak forces a RELAX period during which only an occasion gets
 * through. The relax is the point. Contrast is not something a line can have on
 * its own - it is the silence either side of it - and the only way to make a
 * good line land is to have said less shortly before it.
 *
 * <p>The same object holds the settling-in damper, because it is the same
 * question asked about a longer span of time: how much should be said, given
 * what has been said lately.
 */
public class SpeechDirector
{
	/** What one spoken line adds to the running intensity. */
	private static final double RISE_PER_LINE = 1.0;

	/**
	 * Intensity at which the follower has had its say and stops for a bit.
	 *
	 * <p>Three lines close together, and not the 3.0 that implies: the third
	 * arrives two gaps after the first and the decay has already taken a slice
	 * off the two before it. Asking for a full three units would quietly mean
	 * four lines, which is a different and much longer burst.
	 */
	private static final double PEAK_AT = 2.5;

	/**
	 * How long a peak buys, in milliseconds, as a range.
	 *
	 * <p>Randomised because a constant is a metronome: a player who notices the
	 * follower goes quiet for exactly thirty seconds has found the machinery,
	 * and from then on hears a timer rather than someone choosing not to speak.
	 */
	private static final long RELAX_MIN_MS = 30_000L;
	private static final long RELAX_MAX_MS = 45_000L;

	/**
	 * Intensity decays one unit per this many speech gaps.
	 *
	 * <p>Expressed in gaps rather than seconds so the whole model scales with
	 * the chattiness setting instead of fighting it. At Normal, three lines
	 * inside forty-five seconds is a burst worth resting after; at Quiet, where
	 * the floor between lines is already twelve seconds, the same three lines
	 * are spread far enough that they never peak - which is correct, because a
	 * player who asked for quiet has already been given the contrast.
	 */
	private static final double DECAY_GAPS = 5.0;

	/**
	 * Sessions during which the follower is still settling in. The first
	 * evening and the first return.
	 */
	private static final int SETTLING_SESSIONS = 2;

	/** Groups that recite what the world is, rather than react to what happened in it. */
	private static final java.util.Set<String> LORE_GROUPS =
		new java.util.HashSet<>(java.util.Arrays.asList("area", "gear"));

	/** Gaps a settling-in follower leaves between two lore lines. */
	private static final int SETTLING_LORE_GAPS = 4;

	private double intensity;
	private long lastDecayMs;
	private long relaxUntilMs;
	private long lastLoreMs;

	/**
	 * The base speech gap, in milliseconds. Everything here is expressed as a
	 * multiple of it, so the chattiness setting moves the whole model at once.
	 *
	 * <p>Zero switches the director off entirely, which falls out of the same
	 * fact rather than being a special case bolted on: every window here is a
	 * multiple of the gap, so a gap of nothing makes all of them nothing. The
	 * chattiness setting has no such level - this is for the test harness,
	 * which wants rules evaluated without pacing in the way.
	 */
	private long baseGapMs = 3_000L;

	public void setBaseGapMs(long baseGapMs)
	{
		this.baseGapMs = Math.max(0L, baseGapMs);
	}

	public boolean isPacing()
	{
		return baseGapMs > 0L;
	}

	/**
	 * Sessions so far, this one included. Drives the settling-in damper only.
	 *
	 * <p>Zero means nobody has said yet, which is treated as NOT settling in.
	 * The damper is a claim that the follower is new, and an unanswered
	 * question is not evidence for it - defaulting the other way would have
	 * every fresh engine start out quiet about the scenery until something got
	 * round to correcting it.
	 */
	private int sessionCount;

	public void setSessionCount(int sessionCount)
	{
		this.sessionCount = sessionCount;
	}

	public boolean isSettlingIn()
	{
		return sessionCount >= 1 && sessionCount <= SETTLING_SESSIONS;
	}

	/** For the transcript and the debug command. */
	public double getIntensity()
	{
		return intensity;
	}

	public boolean isRelaxing(long now)
	{
		return now < relaxUntilMs;
	}

	public long relaxRemainingMs(long now)
	{
		return Math.max(0L, relaxUntilMs - now);
	}

	/**
	 * Why this rule should stay quiet right now, or null to let it speak.
	 *
	 * <p>Only ever consulted for rules that actually say something; an
	 * animation-only firing is movement rather than chatter and never reaches
	 * here.
	 */
	public String blocks(SpeechRule rule, long now)
	{
		if (!isPacing())
		{
			return null;
		}

		// An occasion is exempt from EVERYTHING this class does, and that has to
		// be said once at the top rather than repeated per damper. It was not,
		// and the settling check below quietly acquired the power to swallow
		// enter-wilderness - a line whose whole job is to reach a player who has
		// never seen the place, from a follower that is only settling in
		// because the player is new. The two conditions peak together.
		if (rule.isOccasion())
		{
			return null;
		}

		if (isRelaxing(now))
		{
			return "relax";
		}
		if (isLore(rule) && isSettlingIn() && now - lastLoreMs < baseGapMs * SETTLING_LORE_GAPS)
		{
			return "settling";
		}
		return null;
	}

	/**
	 * Whether this rule recites what the world IS, rather than reacting to
	 * what happened in it. Public so a test can assert the other way round -
	 * that nothing which must always be heard has been left in a group the
	 * damper thins.
	 */
	public static boolean isLore(SpeechRule rule)
	{
		return rule.group != null
			&& LORE_GROUPS.contains(rule.group.toLowerCase(java.util.Locale.ROOT));
	}

	/**
	 * Records that a line was actually said, and starts a relax period if that
	 * was one line too many.
	 *
	 * <p>Counted at the point of SPEAKING rather than of winning, for the same
	 * reason the mood is: a line the mute swallowed cost the player no
	 * attention, and resting afterwards would be resting from nothing.
	 */
	public void noteSpoke(SpeechRule rule, long now)
	{
		if (!isPacing())
		{
			return;
		}
		decayTo(now);

		if (isLore(rule))
		{
			lastLoreMs = now;
		}

		// An occasion is the thing the quiet was being saved for. Letting it
		// also build towards the next quiet would have the follower punish
		// itself for the one line it most wanted to say.
		if (rule.isOccasion())
		{
			return;
		}

		intensity += RISE_PER_LINE;
		if (intensity >= PEAK_AT)
		{
			intensity = 0.0;
			relaxUntilMs = now + RELAX_MIN_MS
				+ (long) ThreadLocalRandom.current().nextInt((int) (RELAX_MAX_MS - RELAX_MIN_MS) + 1);
		}
	}

	private void decayTo(long now)
	{
		if (lastDecayMs == 0L)
		{
			lastDecayMs = now;
			return;
		}
		long elapsed = now - lastDecayMs;
		lastDecayMs = now;
		if (elapsed <= 0L)
		{
			return;
		}
		intensity = Math.max(0.0, intensity - elapsed / (DECAY_GAPS * baseGapMs));
	}

	public void reset()
	{
		intensity = 0.0;
		lastDecayMs = 0L;
		relaxUntilMs = 0L;
		lastLoreMs = 0L;
	}
}

package com.follower.speech;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

/**
 * Evaluates every rule against every incoming event and speaks the winner.
 *
 * <p>The model is deliberately uniform: there is no separate notion of "event
 * rules" and "state rules". Every rule is evaluated on every event (including the
 * synthetic per-tick event) and fires on the rising edge of its condition. Event
 * conditions such as {@code npcSpawn} are only true while that event is being
 * processed, so they behave as edges naturally; state conditions such as
 * {@code healthBelow} stay true and therefore fire once per crossing.
 */
@Slf4j
@Singleton
public class SpeechEngine
{
	/**
	 * Callback for delivering a firing. Implemented by the plugin. {@code text}
	 * may be empty (an animation-only rule) and {@code animationId} is -1 when
	 * the rule plays nothing.
	 *
	 * <p>{@code onSaid} is the moment the line actually reaches the player. A
	 * sink that shows lines immediately runs it before returning; a sink that
	 * queues them runs it when the line takes the floor, and never for a line
	 * it drops. The engine hangs the states that OPEN something - a question,
	 * a want, a wish - on this, because each of those later puts an
	 * interaction in front of the player that only makes sense if the opening
	 * line was seen.
	 */
	public interface Sink
	{
		void speak(String text, SpeechOutput output, SpeechRule rule, int animationId,
			Runnable onSaid);
	}

	private final Client client;
	private final RuleLoader loader;

	private TriggerContext context;

	@Setter
	private Sink sink;

	/** Groups the config has switched off. Rule ids are matched too, for one-offs. */
	@Setter
	private Set<String> disabledGroups = Collections.emptySet();

	@Setter
	private SpeechOutput defaultOutput = SpeechOutput.OVERHEAD;

	/** Nothing speaks within this window of the previous line, whatever the rule. */
	private long globalCooldownMs = 3_000L;

	public void setGlobalCooldownMs(long globalCooldownMs)
	{
		this.globalCooldownMs = globalCooldownMs;
		director.setBaseGapMs(globalCooldownMs);
	}

	/**
	 * How much has been said lately, and whether it is time to stop for a bit.
	 * The gap above is a floor between two lines; this is a budget across many.
	 */
	@Getter
	private final SpeechDirector director = new SpeechDirector();

	/**
	 * How many unprompted idle remarks the current stretch of standing still
	 * has already produced, and when the last one was.
	 *
	 * <p>The director cannot see this problem. It handles BURSTS - intensity
	 * that rises faster than it decays - and a line every forty-five seconds
	 * decays completely between lines, so an idle afternoon sails under its
	 * peak forever while still producing eighty lines an hour. Measured, that
	 * is what a long AFK sounded like: the longest silence in forty minutes
	 * was two.
	 *
	 * <p>A companion does not drip at a fixed rate. It chats when you first
	 * stop, and then it runs out of things to say about standing still. So the
	 * first few remarks of a stretch are free, and each one after that needs a
	 * longer wait than the one before - the follower audibly winding down -
	 * until anything at all happens and the count starts over.
	 *
	 * <p>"Unprompted" is precise: a rule whose condition mentions {@code idle}
	 * is speaking because you are standing still, and is throttled. A reaction
	 * to something real - a cat, a passer-by, an errand - is not, because
	 * answering the world is not chatter. Occasions are exempt as everywhere.
	 */
	private int idleStretchSpoken;
	private long lastIdleRemarkMs;

	/**
	 * Three minutes with camera, feet and hands all untouched before the
	 * damper (R15) decides nobody is watching. Deliberately past the
	 * gone-away jokes' own threshold, so the follower notices the absence
	 * out loud before it stops performing to it.
	 */
	private static final int UNATTENDED_DAMPER_TICKS = 300;

	/** Idle remarks per stretch before the winding-down starts. */
	private static final int IDLE_FREE_REMARKS = 4;

	/** Each remark past the free ones waits this many gaps longer than the last. */
	private static final long TRAIL_STEP_GAPS = 30;

	/** The wind-down stops growing here: never rarer than one per this many gaps. */
	private static final long TRAIL_CAP_GAPS = 200;

	private boolean isIdleRemark(SpeechRule rule)
	{
		return rule.when != null && rule.when.usesType("idle") && !rule.isOccasion();
	}

	/**
	 * The events that end an idle stretch.
	 *
	 * <p>NOT movement. The first version reset when the idle counter did, and
	 * that would have made the whole mechanism a no-op in exactly the session
	 * it was built from: a player pottering about a bank moves every few
	 * seconds, and each little stop re-arms the idle rules' rising edges -
	 * that is precisely HOW an "idle" session produces a line every forty-five
	 * seconds. Shuffling two tiles is not doing something. Fighting, stealing,
	 * skilling, killing, arriving somewhere new, or dying is.
	 */
	private static final java.util.Set<TriggerEvent.Type> REAL_ACTIVITY =
		java.util.EnumSet.of(
			TriggerEvent.Type.ANIMATION,
			TriggerEvent.Type.COMBAT_START,
			TriggerEvent.Type.THIEVING_START,
			TriggerEvent.Type.NPC_KILL,
			TriggerEvent.Type.LOOT,
			TriggerEvent.Type.LEVEL_UP,
			TriggerEvent.Type.REGION_CHANGE,
			TriggerEvent.Type.PLAYER_DEATH,
			TriggerEvent.Type.WANT_FULFILLED,
			// Answering is the most direct evidence of a person there is:
			// somebody read a question and chose. Without it the damper could
			// silence the follower MID-CONVERSATION - the guessing game asks
			// you to stand still, so a player who then only clicks dialog
			// options never moves camera or feet, and the reveal of which
			// hand it was went to an "empty chair" that was answering it.
			TriggerEvent.Type.ANSWERED);

	/** How long the NEXT idle remark has to wait, given the stretch so far. */
	private long trailWaitMs()
	{
		if (idleStretchSpoken < IDLE_FREE_REMARKS)
		{
			return 0L;
		}
		long steps = idleStretchSpoken - IDLE_FREE_REMARKS + 1;
		return Math.min(TRAIL_CAP_GAPS, steps * TRAIL_STEP_GAPS) * globalCooldownMs;
	}

	@Setter
	private boolean muted;

	/**
	 * Where "now" comes from.
	 *
	 * <p>Every window in this class is wall-clock - the speech gap, the held
	 * floor, each rule's cooldown, the director's rest - which made all of them
	 * untestable together. A simulation runs ten thousand ticks a second, so it
	 * sits inside the first rest period for its entire length and proves
	 * nothing about what happens after one. Real seconds cannot be spent
	 * waiting and a fake clock is the only honest way to walk hours of them.
	 *
	 * <p>Defaults to the real one and is only ever replaced by tests.
	 */
	private java.util.function.LongSupplier clock = System::currentTimeMillis;

	public void setClock(java.util.function.LongSupplier clock)
	{
		this.clock = clock == null ? System::currentTimeMillis : clock;
	}

	private long now()
	{
		return clock.getAsLong();
	}

	@Getter
	private long lastSpokeMs;

	@Getter
	private String lastSpokenText = "";

	/**
	 * How many lines back the follower remembers having said, across every rule.
	 *
	 * <p>A shuffle bag can only keep one rule honest about itself. It cannot
	 * stop two rules that were written about the same thing - and there are
	 * plenty, since a companion notices standing still in several different
	 * ways - from handing the same observation back and forth. This is the
	 * window that does.
	 *
	 * <p>Twelve is a compromise with a real cost either way: too short and the
	 * ping-pong survives, too long and a rule with two variants finds both of
	 * them blocked and simply repeats anyway, having spent the effort.
	 */
	private static final int RECENT_LINES = 12;

	/**
	 * The last {@link #RECENT_LINES} things said, as TEMPLATES rather than as
	 * finished text. "{count}. I've been keeping track" is one line however
	 * many different numbers it has carried, and keying on the rendered version
	 * would let it through every time the count changed - which is every time.
	 */
	private final java.util.ArrayDeque<String> recentLines = new java.util.ArrayDeque<>();
	private final Set<String> recentLineSet = new java.util.HashSet<>();

	private void noteRecentLine(String template)
	{
		if (template == null || template.isEmpty() || !recentLineSet.add(template))
		{
			// Already in the window: move it to the front by dropping the old
			// entry, or a line said twice would leave the window early.
			if (template != null && !template.isEmpty())
			{
				recentLines.remove(template);
				recentLines.addLast(template);
			}
			return;
		}
		recentLines.addLast(template);
		while (recentLines.size() > RECENT_LINES)
		{
			recentLineSet.remove(recentLines.removeFirst());
		}
	}

	@Inject
	public SpeechEngine(Client client, RuleLoader loader)
	{
		this.client = client;
		this.loader = loader;
	}

	public TriggerContext getContext()
	{
		if (context == null)
		{
			context = new TriggerContext(client);
		}
		return context;
	}

	/** Refreshes the state snapshot. Call once per game tick, before dispatching. */
	public void refreshContext()
	{
		TriggerContext context = getContext();
		context.refresh();

		// Cheap, and it has to survive a reload: the rules are the source of
		// the boss list, so the context follows them rather than being told
		// once at startup and going stale the next time the file is saved.
		context.setBossNames(loader.getBossNames());

		// Synced here rather than pushed from wherever the count is loaded or
		// bumped, because there are several such places and the settling-in
		// damper being right depends on all of them remembering.
		director.setSessionCount(context.getSessionCount());


		// A want resolving is state becoming an event. It happens here rather
		// than in the plugin so the rules see it wherever the engine is driven
		// from, and exactly once - the poll consumes it.
		TriggerContext.WantOutcome outcome = context.pollWant();
		if (outcome != null)
		{
			// Counted as well as announced. A grudge then needs no machinery of
			// its own: "you have ignored me three times" is a tally condition,
			// and lives in phrases.json with everything else.
			context.tally(outcome == TriggerContext.WantOutcome.FULFILLED
				? "want:kept" : "want:missed");
			dispatch(TriggerEvent.want(
				outcome == TriggerContext.WantOutcome.FULFILLED
					? TriggerEvent.Type.WANT_FULFILLED
					: TriggerEvent.Type.WANT_EXPIRED,
				context.getWantLabel()));
		}

		// The souvenir going, and a prediction coming good or not. Same shape
		// as the want: state becoming an event, consumed exactly once.
		if (context.pollSouvenirLost())
		{
			dispatch(TriggerEvent.souvenirLost(context.getSouvenir()));
			context.clearSouvenir();
		}
		if (context.pollUnderfoot())
		{
			dispatch(TriggerEvent.simple(TriggerEvent.Type.UNDERFOOT));
		}

		TriggerContext.ChallengeOutcome challenge = context.pollChallenge();
		if (challenge != null)
		{
			dispatch(TriggerEvent.challenge(
				challenge == TriggerContext.ChallengeOutcome.MET
					? TriggerEvent.Type.CHALLENGE_MET
					: TriggerEvent.Type.CHALLENGE_FAILED,
				context.getChallengeAbout()));
		}

		TriggerContext.AdviceOutcome advice = context.pollAdvice();
		if (advice != null)
		{
			// Counted as well as announced, like a want, so "you never listen"
			// can be a tally condition rather than machinery of its own.
			context.tally(advice == TriggerContext.AdviceOutcome.HEEDED
				? "advice:taken" : "advice:ignored");
			dispatch(TriggerEvent.advice(
				advice == TriggerContext.AdviceOutcome.HEEDED
					? TriggerEvent.Type.ADVICE_HEEDED
					: TriggerEvent.Type.ADVICE_IGNORED,
				context.getAdviceAbout()));
		}

		TriggerContext.BetOutcome bet = context.pollBet();
		if (bet != null)
		{
			dispatch(TriggerEvent.bet(bet == TriggerContext.BetOutcome.WON
				? TriggerEvent.Type.BET_WON : TriggerEvent.Type.BET_LOST));
		}
	}

	/**
	 * Drops the held floor.
	 *
	 * <p>Must happen on a rule reload. The exemption that lets the holder speak
	 * through its own hush is identity-based, and a reload parses every rule
	 * afresh - so the holder becomes an object nothing points at any more, and
	 * the hush it left behind silences the whole file until it times out.
	 */
	public void clearFloor()
	{
		hushUntilMs = 0L;
		hushOwner = null;
	}

	/**
	 * Clears everything mid-flight but KEEPS the state snapshot.
	 *
	 * <p>For a world hop, where the scene goes and the player does not. What
	 * the follower is feeling, hoping for and counting are facts about the
	 * session rather than about the scene, and throwing them away because the
	 * world number changed is how a want quietly disappears on the way
	 * somewhere.
	 */
	public void resetForNewScene()
	{
		lastSpokeMs = 0L;
		pending.clear();
		// An announcement waiting on the old scene's prime window belongs to
		// that scene, not to the one arriving.
		afterPriming.clear();
		hushUntilMs = 0L;
		hushOwner = null;
		for (SpeechRule rule : loader.getRules())
		{
			// Edges only. The scene changed; what the follower has already said
			// did not, and neither did the player's memory of hearing it.
			rule.resetEdges();
		}
	}

	public void reset()
	{
		context = null;
		lastSpokeMs = 0L;
		afterPriming.clear();
		director.reset();
		recentLines.clear();
		recentLineSet.clear();
		idleStretchSpoken = 0;
		lastIdleRemarkMs = 0L;
		pending.clear();
		// A held floor must not outlive the thing that held it: toggling the
		// plugin mid-hush would otherwise leave the follower mute for it.
		hushUntilMs = 0L;
		hushOwner = null;
		for (SpeechRule rule : loader.getRules())
		{
			rule.reset();
		}
	}

	/** A won rule waiting out its delayTicks before speaking. */
	private static final class PendingSpeech
	{
		final SpeechRule rule;
		final TriggerEvent event;
		/** The wait as drawn at the win - kept for the log, since a ranged delay is not on the rule. */
		final int delay;
		int ticksLeft;

		PendingSpeech(SpeechRule rule, TriggerEvent event, int ticksLeft)
		{
			this.rule = rule;
			this.event = event;
			this.delay = ticksLeft;
			this.ticksLeft = ticksLeft;
		}
	}

	private final java.util.List<PendingSpeech> pending = new java.util.ArrayList<>();

	/**
	 * Set at login: evaluations record every rule's edge state without firing
	 * until a couple of ticks have passed WITH the player's composition
	 * actually readable. The world as found at spawn is baseline, not news - a
	 * rule should react to what CHANGES afterwards (gear equipped mid-session),
	 * not to whatever the player logged in wearing.
	 *
	 * <p>Two subtleties bought by bugs: the composition can lag several ticks
	 * behind login, so the countdown only consumes ticks the context reports
	 * ready; and edges rise on ANY dispatch (the login welcome chat message,
	 * an animation), so priming gates every event, not just the tick
	 * heartbeat. Delayed firings already queued (the login greeting) ride the
	 * pending path and are unaffected.
	 */
	private int primeTicksLeft;

	public void primeEdgesOnNextTick()
	{
		primeTicksLeft = 2;
	}

	/** Announcements waiting for the prime window to drain. */
	private final java.util.List<TriggerEvent> afterPriming = new java.util.ArrayList<>();

	/**
	 * Raises an event the plugin MEANT to raise - a world hop, an edited
	 * notebook - once the prime window has drained, or immediately if none is
	 * open.
	 *
	 * <p>These cannot simply be dispatched around the priming, and both ways
	 * of trying were wrong. Dispatched inside the window, the winner is
	 * discarded with everything else and the rule is silently dead. Dispatched
	 * just BEFORE arming it, the announcement lands on a rule set whose edges
	 * were cleared with the scene, so every piece of worn gear and the region
	 * underfoot rise on that same pass - and since one event has one winner
	 * and those rules outrank the announcement, the follower remarks on your
	 * gear as though you had just put it on and the hop goes unmentioned.
	 * Play report, exactly that.
	 *
	 * <p>Waiting is what makes it correct: the window baselines the state
	 * first, so by the time this lands, nothing else is rising and the
	 * announcement wins the pass it deserves to win.
	 */
	public void dispatchAfterPriming(TriggerEvent event)
	{
		if (primeTicksLeft <= 0)
		{
			dispatch(event);
			return;
		}
		afterPriming.add(event);
	}

	/**
	 * When the floor is held, and by whom.
	 *
	 * <p>A handful of moments are worth more than whatever else the follower
	 * was about to say. Walking into the place it asked to be taken is the
	 * clearest: the region change raises an area line at the same instant, and
	 * two lines about the same arrival is one line too many - the wrong one
	 * usually winning, since the area rule has no delay and gets there first.
	 */
	private long hushUntilMs;
	private SpeechRule hushOwner;

	/**
	 * Told when a rule won its event and was held back anyway. Set by the
	 * plugin so the transcript can see the half of the story the player never
	 * does; left null everywhere else, including in tests.
	 */
	@Setter
	private java.util.function.BiConsumer<SpeechRule, String> onSuppressed;

	private void noteSuppressed(SpeechRule rule, String reason)
	{
		if (onSuppressed != null)
		{
			onSuppressed.accept(rule, reason);
		}
	}

	/**
	 * Whether this rule is allowed to say its line right now.
	 *
	 * <p>The mute and the global window throttle SPEECH; a rule that only plays
	 * an animation (teleport mirroring, the flinch) is not chatter and skips
	 * both. The rule holding the floor skips them too - it is the reason
	 * everything else is quiet, so being caught by its own hush, or held back
	 * by whatever spoke a second before it, would defeat the point.
	 */
	private boolean cannotSpeak(SpeechRule rule, long now)
	{
		return blockedBy(rule, now) != null;
	}

	/**
	 * WHY this rule cannot speak, or null if it can.
	 *
	 * <p>Same decision as {@link #cannotSpeak}, phrased so the transcript can
	 * record the reason. A held-back line never reaches the player and so never
	 * reaches an impression, which makes it exactly the evidence needed to tell
	 * a follower with little to say from one that is being throttled.
	 */
	private String blockedBy(SpeechRule rule, long now)
	{
		if (!rule.hasSpeech())
		{
			return null;
		}
		if (rule == hushOwner && now < hushUntilMs)
		{
			return muted ? "muted" : null;
		}
		if (muted)
		{
			return "muted";
		}
		// Before the gap, because when both apply the director is the honest
		// answer: the gap is three seconds and would be gone by the next tick,
		// where a relax period is most of a minute and is the reason nothing
		// else got through either.
		String directed = director.blocks(rule, now);
		if (directed != null)
		{
			return directed;
		}
		// R15: speech scales to attention. With camera, feet and hands all
		// untouched this long, the world is playing to an empty chair -
		// reactions included, not just idle chatter. Occasions still land
		// (a warning matters the moment they glance back), and the rules
		// ABOUT the absence are exactly the ones that should speak into it.
		// Any input at all clears the state instantly.
		if (getContext().getUnattendedTicks() >= UNATTENDED_DAMPER_TICKS
			&& !rule.isOccasion()
			&& (rule.when == null || !rule.when.usesType("unattended")))
		{
			return "unattended";
		}
		// Ignored overtures rest. A question that lapsed unanswered is not
		// followed by another for a long while, and two ignored in one
		// session end the asking - a polite companion drops a hint twice and
		// lets it go, where re-asking at every cooldown reads as nagging.
		// A wish that lapsed unfulfilled rests more gently. Answering any
		// question, or granting any wish, clears the respective ledger.
		if (rule.asks != null && !rule.asks.isEmpty() && getContext().isAskBackedOff())
		{
			return "ignored";
		}
		if (rule.wish != null && getContext().isWishBackedOff())
		{
			return "ignored";
		}
		if (isIdleRemark(rule) && now - lastIdleRemarkMs < trailWaitMs())
		{
			return "trailing";
		}
		if (now - lastSpokeMs < moodScaledGap())
		{
			return "gap";
		}
		if (now < hushUntilMs)
		{
			return "hush";
		}
		return null;
	}

	/**
	 * Whether this firing says anything about WHERE it happened.
	 *
	 * <p>Two things have to be kept out of the place score, and neither is
	 * obvious from the mood value alone.
	 *
	 * <p>The first is the loop. The rules that remark on liking or disliking
	 * somewhere are themselves worth +10 and -8, so feeding those back would
	 * have the follower talk itself into an ever firmer opinion about a place
	 * on no evidence but its own earlier opinion.
	 *
	 * <p>The second is everything that is about the SESSION rather than the
	 * world. Logging in after a day away is worth +8, and it happens wherever
	 * you happened to log out - which is the same tile every time. Left in, the
	 * single most-loved place in the game would reliably be your bank.
	 */
	private boolean belongsToThisPlace(SpeechRule rule, TriggerEvent event)
	{
		if (rule.when != null && rule.when.usesType("feelsAbout"))
		{
			return false;
		}
		switch (event.getType())
		{
			// Things that happened to you, here.
			case TICK:
			case VARBIT:
			case PLAYER_DEATH:
			case NPC_KILL:
			case NPC_SPAWN:
			case LOOT:
			case LEVEL_UP:
			case DAMAGE_TAKEN:
			case COMBAT_START:
			case COMBAT_END:
			case THIEVING_START:
			case THIEVING_END:
			case REGION_CHANGE:
			case WANT_FULFILLED:
				return true;
			// Things about the session, the conversation, or the follower's
			// own belongings, which would happen the same anywhere.
			default:
				return false;
		}
	}

	/**
	 * The speech gap, stretched or shortened by how the follower feels.
	 *
	 * <p>Mood already decides WHAT it says. Until now it had no say in HOW MUCH,
	 * so a follower having a bad day recited sad lines at exactly the rate it
	 * recited cheerful ones - which reads as a costume rather than a mood.
	 * Somebody in a bad way talks less. Somebody in a good one talks over you.
	 *
	 * <p>Applied to the shared gap rather than to any rule, so it thins out
	 * everything evenly instead of silencing particular things: the follower
	 * still says what matters, just with more room around it.
	 */
	private long moodScaledGap()
	{
		return gapForMood(globalCooldownMs, getContext().getMoodBand());
	}

	/**
	 * The mapping itself, as a function of the band rather than of the engine,
	 * so a test can walk every band without having to make real seconds pass.
	 */
	static long gapForMood(long base, String band)
	{
		switch (band == null ? "" : band)
		{
			case "low":
				return base * 5 / 2;
			case "down":
				return base * 3 / 2;
			case "good":
				return base * 4 / 5;
			case "high":
				return base * 3 / 5;
			default:
				return base;
		}
	}

	/**
	 * Runs one evaluation pass. Every rule's edge state is updated regardless of
	 * whether it can speak, so cooldowns and mutes never desynchronise the edges.
	 */
	public void dispatch(TriggerEvent event)
	{
		long now = now();

		// An animation the player played may be them doing the thing they were
		// just told to. Offered before the rules run, so the settling and the
		// reaction land on the same tick rather than a tick apart.
		if (event.getType() == TriggerEvent.Type.ANIMATION && event.getId() != -1)
		{
			getContext().offerAct(event.getId());
		}

		// Doing something real ends the idle stretch, and the follower perks
		// back up. Checked on the event rather than on movement - see the note
		// on REAL_ACTIVITY for why a step is not enough. It is also evidence
		// of presence: you cannot level up from the kettle.
		if (REAL_ACTIVITY.contains(event.getType()))
		{
			idleStretchSpoken = 0;
			getContext().noteAttention();
		}

		// Delayed firings count down on the tick heartbeat and speak through
		// the same guarded path as everything else when their beat arrives.
		if (event.getType() == TriggerEvent.Type.TICK && !pending.isEmpty())
		{
			java.util.Iterator<PendingSpeech> it = pending.iterator();
			while (it.hasNext())
			{
				PendingSpeech delayed = it.next();
				if (--delayed.ticksLeft <= 0)
				{
					it.remove();
					String held = blockedBy(delayed.rule, now);
					if (held == null)
					{
						log.debug("rule '{}' fired after its {}-tick delay",
							delayed.rule.describe(), delayed.delay);
						speak(delayed.rule, delayed.event, now);
					}
					else
					{
						noteSuppressed(delayed.rule, held);
					}
				}
			}
		}

		SpeechRule winner = null;

		for (SpeechRule rule : loader.getRules())
		{
			boolean matching;
			try
			{
				matching = rule.when.matches(getContext(), event);
			}
			catch (RuntimeException e)
			{
				log.warn("Rule '{}' threw while evaluating; disabling it", rule.describe(), e);
				rule.enabled = Boolean.FALSE;
				continue;
			}

			boolean rising = rule.risingEdge(matching);

			if (!rising || !isActive(rule) || !rule.offCooldown(now))
			{
				continue;
			}

			// Belt and braces: the loader already hands rules over sorted by
			// priority descending, so the comparison can never actually differ
			// from "first match wins". Both are kept deliberately - the sort is
			// what makes this loop cheap, the comparison is what makes the
			// invariant true independently of it. Mutating either alone leaves
			// the behaviour correct, which is worth knowing before anyone
			// "simplifies" one of them away.
			if (winner == null || rule.priority > winner.priority)
			{
				winner = rule;
			}
		}

		// Something just ENDED: open the breather window (R6). Noted AFTER the
		// evaluation loop on purpose - a boundary rule should rise on the NEXT
		// pass rather than competing with the ending's own reaction on this
		// event, where losing would consume its edge for the whole window. The
		// breather comes after the reaction, which is also the right order to
		// hear them in.
		switch (event.getType())
		{
			case COMBAT_END:
				getContext().noteBoundary("combat");
				break;
			case LEVEL_UP:
				getContext().noteBoundary("level");
				break;
			case REGION_CHANGE:
				getContext().noteBoundary("arrival");
				break;
			case THIEVING_END:
				getContext().noteBoundary("thieving");
				break;
			default:
				break;
		}

		// While primed (just after login), edges have been recorded above but
		// nothing fires from ANY event: worn gear and standing state register
		// as already-true instead of as fresh rising edges. The countdown only
		// consumes ticks where the player composition is actually readable -
		// before that, "no equipment" is an artefact of loading, not a state.
		if (primeTicksLeft > 0)
		{
			if (event.getType() == TriggerEvent.Type.TICK && getContext().isPlayerReady()
				&& --primeTicksLeft == 0 && !afterPriming.isEmpty())
			{
				// The baseline is taken; anything held back now lands on a rule
				// set where only it is rising. Drained into a copy first, so a
				// re-entrant dispatch cannot see the queue twice.
				java.util.List<TriggerEvent> held = new java.util.ArrayList<>(afterPriming);
				afterPriming.clear();
				for (TriggerEvent announcement : held)
				{
					dispatch(announcement);
				}
			}
			return;
		}

		if (winner == null)
		{
			return;
		}

		// Taking the floor happens at the WIN, not when the line finally comes
		// out. A rule with a delay would otherwise leave its own gap open: the
		// want-fulfilled line waits a few ticks, and the region-change line
		// that arrives later in the same tick would walk straight into it.
		if (winner.hushMs != null && winner.hushMs > 0 && winner.hasSpeech())
		{
			hushUntilMs = now + winner.hushMs;
			hushOwner = winner;
		}

		// A delayed rule queues instead of speaking now; the cooldown is
		// charged at the win so re-triggers don't stack up more firings. The
		// wait is drawn HERE, once, so a ranged delay stays put while pending.
		int delay = winner.rollDelayTicks();
		if (delay > 0)
		{
			winner.markFired(now);
			pending.add(new PendingSpeech(winner, event, delay));
			return;
		}

		String blocked = blockedBy(winner, now);
		if (blocked != null)
		{
			// Still charge the cooldown so a suppressed rule doesn't fire the instant
			// the global window opens.
			log.debug("rule '{}' won but was suppressed ({})", winner.describe(), blocked);
			noteSuppressed(winner, blocked);
			winner.markFired(now);
			return;
		}

		log.debug("rule '{}' fired on {}", winner.describe(), event.getType());
		speak(winner, event, now);
	}

	/** Speaks an arbitrary line, bypassing rules — used by the chat commands. */
	public void say(String text, SpeechOutput output)
	{
		if (sink == null || text == null || text.isEmpty())
		{
			return;
		}
		lastSpokeMs = now();
		lastSpokenText = text;
		sink.speak(text, output == null ? defaultOutput : output, null, -1, () -> { });
	}

	/**
	 * Says a rule this instant, whatever its conditions, cooldown and the mute
	 * have to say about it.
	 *
	 * <p>For testing a rule you cannot conveniently provoke. Several of them
	 * only happen on a five percent roll after a minute of standing still, or
	 * on the hundredth login, and waiting for one of those in a live client is
	 * not testing, it is hoping.
	 *
	 * <p>Everything the rule carries still happens - the animation, the mood
	 * nudge, {@code asks}, {@code want} - because the point is to exercise the
	 * whole path rather than only the words. Placeholders that come from an
	 * event ({npc}, {want}, {value}) have no event to come from here and will
	 * print literally; that is the honest cost of firing something out of
	 * nowhere.
	 *
	 * @return whether a rule by that id exists
	 */
	public boolean force(String ruleId)
	{
		for (SpeechRule rule : loader.getRules())
		{
			if (ruleId.equalsIgnoreCase(rule.id))
			{
				long now = now();
				// Including the floor, so what you see when testing is what the
				// rule really does rather than a quieter version of it.
				if (rule.hushMs != null && rule.hushMs > 0 && rule.hasSpeech())
				{
					hushUntilMs = now + rule.hushMs;
					hushOwner = rule;
				}
				speak(rule, TriggerEvent.simple(TriggerEvent.Type.MANUAL), now);
				return true;
			}
		}
		return false;
	}

	private void speak(SpeechRule rule, TriggerEvent event, long now)
	{
		String template = rule.pickPhrase(recentLineSet,
			line -> getContext().lineWear(line));
		String text = substitute(template, event);
		Integer animation = rule.resolveAnimation(event);

		// A mirroring rule triggered by something OTHER than an animation event
		// - the repeating condition, which is how the follower joins in with
		// what the player is doing - has no id on the event to copy. The
		// player's current repeating animation is the thing being copied, and
		// only the state snapshot knows it.
		//
		// Which of the two the rule asks for matters, and the cache decides it:
		// mining, woodcutting, fishing and fletching are authored loops
		// (frameStep >= 0) and have to be held as a POSE, because playing one
		// as an emote waits forever for an end that never comes and leaves the
		// follower stuck mid-swing. Cooking, smithing, herblore and firemaking
		// are one-shots the server restarts each cycle, and mirrorAnimation
		// gives those a single honest go.
		if (animation == null
			&& (Boolean.TRUE.equals(rule.mirrorPose) || Boolean.TRUE.equals(rule.mirrorAnimation)))
		{
			int repeating = getContext().getRepeatingAnimation();
			animation = repeating > 0 ? repeating : null;
		}
		if (text.isEmpty() && animation == null && !rule.hasAnimationChain())
		{
			return;
		}

		rule.markFired(now);

		// Mood moves with what the follower ACTUALLY did. Applying it here
		// rather than at the win means a rule held back by a cooldown, a
		// disabled group or the mute does not quietly move the mood while
		// saying nothing - the state and the words stay one story.
		if (rule.mood != null && rule.mood != 0)
		{
			getContext().adjustMood(rule.mood);

			// And the place keeps its share of it. The rules already say how
			// much a moment was worth; this is only remembering where it was.
			if (belongsToThisPlace(rule, event))
			{
				getContext().notePlaceFeeling(rule.mood);
			}
		}

		// A question only counts as asked once it has actually been said - a
		// rule silenced by the mute must not leave the follower waiting for an
		// answer to something nobody heard. The same goes for the want and the
		// wish, and "said" is the sink's moment, not this method's: the plugin
		// queues lines behind the overhead box, and a queued line can still be
		// dropped - aged out, displaced by a full queue, cleared with the
		// scene. Each of these three later puts an interaction in front of the
		// player (a conversation, a thank-you, a gift option in the Talk-to
		// box), so opening them on a line nobody saw leaves that interaction
		// unexplained. They latch when the sink says the line landed.
		Runnable onSaid = () ->
		{
			// The wear ledger counts what was HEARD, not what was queued -
			// a line the queue dropped has not worn out its welcome.
			if (!text.isEmpty())
			{
				getContext().noteLineSaid(template);
			}
			if (rule.asks != null && !rule.asks.isEmpty() && !text.isEmpty())
			{
				getContext().noteQuestion(rule.asks);
			}
			if (rule.want != null && rule.want.region != null && !text.isEmpty())
			{
				getContext().setWant(rule.want.region, rule.want.label,
					rule.want.minutes == null ? 15 : rule.want.minutes);
			}
			if (rule.wish != null && rule.wish.what != null && !text.isEmpty())
			{
				getContext().setWish(rule.wish.what,
					rule.wish.minutes == null ? 45 : rule.wish.minutes,
					rule.wish.items);
			}
		};

		// An incident is filed whether or not the line was heard: the chicken
		// killed you regardless of whether the follower got a word in.
		if (rule.remember != null && rule.remember.key != null)
		{
			getContext().noteIncident(rule.remember.key, rule.remember.as);
		}

		// And the same moment against the place, when the rule says so.
		if (rule.markHere != null && !rule.markHere.isEmpty())
		{
			getContext().notePlaceMemory(rule.markHere);
		}

		// Picking something up and betting on something both need to have been
		// SAID, like the want - a souvenir nobody was told about is invisible,
		// and a silent prediction can only ever be right.
		if (rule.pickUp != null && rule.pickUp.what != null && !text.isEmpty())
		{
			// Substituted like a spoken line, so a souvenir can be named after
			// the wish it grants: "the {wish} you found me". A swap rule
			// replaces what is carried - it said the exchange out loud, which
			// is what the refuse-if-carrying guard exists to require.
			String what = substitute(rule.pickUp.what, event);
			int minutes = rule.pickUp.minutes == null ? 20 : rule.pickUp.minutes;
			if (Boolean.TRUE.equals(rule.pickUp.swap))
			{
				getContext().tradeFor(what, minutes);
			}
			else
			{
				getContext().pickUp(what, minutes);
			}
		}
		// AFTER the pickUp, which may still need the wish's name. The wish
		// closes on a SPOKEN thank-you only: the follower acknowledging the
		// gift is what spends it.
		if (Boolean.TRUE.equals(rule.grantsWish) && !text.isEmpty())
		{
			getContext().clearWish();
		}
		if (rule.bet != null && rule.bet.threshold != null && !text.isEmpty())
		{
			getContext().placeBet(Boolean.TRUE.equals(rule.bet.rich),
				rule.bet.threshold, rule.bet.minutes == null ? 5 : rule.bet.minutes);
		}
		if (rule.challenge != null && rule.challenge.tally != null && !text.isEmpty())
		{
			getContext().setChallenge(
				rule.challenge.about,
				rule.challenge.tally,
				rule.challenge.target == null ? 10 : rule.challenge.target,
				rule.challenge.minutes == null ? 5 : rule.challenge.minutes);
		}
		if (rule.advise != null && rule.advise.about != null && !text.isEmpty())
		{
			getContext().adviseOn(
				rule.advise.about,
				rule.advise.ids == null
					? java.util.Collections.emptySet()
					: new java.util.HashSet<>(rule.advise.ids),
				Boolean.TRUE.equals(rule.advise.room),
				rule.advise.minutes == null ? 1 : rule.advise.minutes);
		}

		if (!text.isEmpty())
		{
			// Only actual speech resets the global window; an animation-only
			// firing should not push back the next spoken line.
			lastSpokeMs = now;
			lastSpokenText = text;
			director.noteSpoke(rule, now);
			noteRecentLine(template);
			if (isIdleRemark(rule))
			{
				idleStretchSpoken++;
				lastIdleRemarkMs = now;
			}

			// A first is only spent once it has been heard. Marked here rather
			// than at the win for the same reason as the question and the want:
			// a line the mute swallowed was never said, and burning the one
			// chance the follower had to say it would be the worst possible
			// place to be strict.
			if (rule.isOnce())
			{
				getContext().noteSaidOnce(rule.id);
			}
		}

		SpeechOutput output = SpeechOutput.parse(rule.output, defaultOutput);
		if (sink != null)
		{
			sink.speak(text, output, rule, animation == null ? -1 : animation, onSaid);
		}
		log.debug("Rule '{}' fired: {}", rule.describe(),
			text.isEmpty() ? "(animation " + animation + ")" : text);
	}

	private boolean isActive(SpeechRule rule)
	{
		if (!rule.isEnabled() || (rule.isOnce() && getContext().hasSaidOnce(rule.id)))
		{
			return false;
		}
		String group = rule.group == null ? "misc" : rule.group.toLowerCase(Locale.ROOT);
		return !disabledGroups.contains(group)
			&& !(rule.id != null && disabledGroups.contains(rule.id.toLowerCase(Locale.ROOT)));
	}

	/** Replaces {@code {placeholder}} tokens from the event and the state snapshot. */
	private String substitute(String template, TriggerEvent event)
	{
		if (template == null || template.indexOf('{') < 0)
		{
			return template == null ? "" : template;
		}

		Map<String, String> values = new HashMap<>(event.getPlaceholders());
		TriggerContext ctx = getContext();
		// Available wherever the state is: a callback line wants {memory}
		// whatever event happened to trigger it.
		values.putIfAbsent("memory", ctx.getIncidentPhrase());
		values.putIfAbsent("souvenir", ctx.getSouvenir());
		values.putIfAbsent("wish", ctx.getWishLabel());
		values.putIfAbsent("here", ctx.getPlaceMemory());
		values.putIfAbsent("nickname", ctx.getNickname());
		values.putIfAbsent("left", Integer.toString(ctx.getChallengeLeft()));
		values.putIfAbsent("days", Integer.toString(ctx.getDaysKnown()));
		values.putIfAbsent("hp", Integer.toString(ctx.getHitpoints()));
		values.putIfAbsent("maxHp", Integer.toString(ctx.getMaxHitpoints()));
		values.putIfAbsent("hpPercent", Integer.toString(ctx.getHitpointsPercent()));
		values.putIfAbsent("prayer", Integer.toString(ctx.getPrayerPoints()));
		values.putIfAbsent("maxPrayer", Integer.toString(ctx.getMaxPrayerPoints()));
		values.putIfAbsent("prayerPercent", Integer.toString(ctx.getPrayerPercent()));
		values.putIfAbsent("player", ctx.getPlayerName());
		values.putIfAbsent("region", Integer.toString(ctx.getRegionId()));

		StringBuilder out = new StringBuilder(template.length() + 16);
		int i = 0;
		while (i < template.length())
		{
			char c = template.charAt(i);
			if (c != '{')
			{
				out.append(c);
				i++;
				continue;
			}

			int close = template.indexOf('}', i);
			if (close < 0)
			{
				out.append(template.substring(i));
				break;
			}

			String key = template.substring(i + 1, close);
			String replacement = values.get(key);
			out.append(replacement == null ? template.substring(i, close + 1) : replacement);
			i = close + 1;
		}

		return out.toString();
	}
}

package com.follower.speech;

import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * A record of what the follower actually said, and of what it wanted to say and
 * could not.
 *
 * <p>Every tuning decision in this plugin so far has rested on impressions and
 * on a model of what the rules COULD do. Neither is a record of what they did:
 * the engine kept one last-spoken line and some debug logging that is off by
 * default, so an hour of play left nothing to review. That makes questions like
 * "is it repeating itself" and "did the pacing change help" unanswerable except
 * by feel.
 *
 * <p>The suppressed entries are the more useful half. A line that was held back
 * by the shared gap never reaches the player and so never reaches an
 * impression, but it is exactly the evidence needed to tell a follower that has
 * little to say from one that is being throttled.
 */
@Slf4j
public class SpeechJournal
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm:ss");

	/** Flushed on a timer rather than per line, to keep file I/O off the hot path. */
	private static final long FLUSH_EVERY_MS = 30_000L;

	/**
	 * Distinct lines tracked for the repeat count. Comfortably above the whole
	 * rule file, so in practice nothing is ever evicted; the cap only exists so
	 * a runaway cannot grow without bound.
	 */
	private static final int MAX_TRACKED_LINES = 4_000;

	private Path file;

	@Getter
	private boolean enabled;

	/**
	 * Where the player was, supplied per line by the plugin.
	 *
	 * <p>Added after a verification run could not be read: place memory,
	 * taste, return visits and place scores are all answers to "where", and a
	 * transcript that records only "what" cannot be used to check any of them.
	 */
	private java.util.function.IntSupplier region = () -> -1;

	public void setRegionSource(java.util.function.IntSupplier source)
	{
		if (source != null)
		{
			region = source;
		}
	}

	private final List<String> pending = new ArrayList<>();
	private long lastFlushMs;

	// ---- session figures, kept in memory so a summary needs no file read ----

	private int spoken;
	private long firstSpokeMs;
	private long lastSpokeMs;
	private long shortestGapMs = Long.MAX_VALUE;
	private long longestGapMs;

	private final Map<String, Integer> byRule = new LinkedHashMap<>();
	private final Map<String, Integer> byLine = new LinkedHashMap<>();
	private final Map<String, Integer> byReason = new LinkedHashMap<>();
	private int suppressed;

	public void initialise(Path dataDir)
	{
		file = dataDir.resolve("transcript-" + LocalDate.now() + ".log");
	}

	public Path getFile()
	{
		return file;
	}

	/**
	 * @return the new state, so the caller can report it
	 */
	public boolean toggle()
	{
		setEnabled(!enabled);
		return enabled;
	}

	/**
	 * Turned on directly, so the plugin can restore it at startup.
	 *
	 * <p>A diagnostic that quietly switches itself off every time the client
	 * restarts is a diagnostic that records nothing on the run you most wanted
	 * it for - which is exactly what happened the first time this was used in
	 * anger.
	 */
	public void setEnabled(boolean on)
	{
		if (on == enabled)
		{
			return;
		}
		enabled = on;
		if (enabled)
		{
			append("---- transcript opened ----");
			// Written at once rather than on the next flush, so that "is it
			// actually recording" is a question the file can answer. Two
			// verification runs were lost to assuming it was on.
			flush();
		}
		else
		{
			append("---- transcript closed ----");
			flush();
		}
	}

	/** A line the player actually saw. */
	public void spoke(SpeechRule rule, String text)
	{
		if (!enabled || text == null || text.isEmpty())
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (spoken > 0)
		{
			long gap = now - lastSpokeMs;
			shortestGapMs = Math.min(shortestGapMs, gap);
			longestGapMs = Math.max(longestGapMs, gap);
		}
		else
		{
			firstSpokeMs = now;
		}
		lastSpokeMs = now;
		spoken++;

		// A command-driven line has no rule behind it.
		String id = rule == null ? "(command)" : rule.describe();
		String group = rule == null ? "-" : String.valueOf(rule.group);
		bump(byRule, id);
		if (byLine.size() < MAX_TRACKED_LINES || byLine.containsKey(text))
		{
			bump(byLine, text);
		}
		append(String.join("\t", stamp(), "said", id, group, where(), text));
	}

	/**
	 * A rule that won its event and was held back anyway.
	 *
	 * <p>This is the half of the story the player never sees, and the only way
	 * to tell a follower with little to say from one being throttled. A reason
	 * that never reaches here is a blind spot in the only diagnostic there is.
	 *
	 * @param reason whatever {@code SpeechEngine.blockedBy} decided: muted,
	 * gap, hush, or one of the director's - relax after a burst, settling while
	 * the follower is still new. Recorded verbatim rather than checked against
	 * a list, so a reason added later shows up in the transcript without this
	 * needing to know about it.
	 */
	public void suppressed(SpeechRule rule, String reason)
	{
		if (!enabled)
		{
			return;
		}
		suppressed++;
		bump(byReason, reason);
		append(String.join("\t", stamp(), "held", rule.describe(),
			String.valueOf(rule.group), where(), reason));
	}

	private static void bump(Map<String, Integer> counts, String key)
	{
		counts.merge(key, 1, Integer::sum);
	}

	private static String stamp()
	{
		return LocalTime.now().format(CLOCK);
	}

	/** The region id, in its own column so a reader can group by it. */
	private String where()
	{
		return "r" + region.getAsInt();
	}

	private void append(String line)
	{
		pending.add(line);
	}

	/** Called from the tick. Writes only when there is something and it is due. */
	public void flushIfDue()
	{
		long now = System.currentTimeMillis();
		if (!pending.isEmpty() && now - lastFlushMs >= FLUSH_EVERY_MS)
		{
			flush();
		}
	}

	public void flush()
	{
		lastFlushMs = System.currentTimeMillis();
		if (pending.isEmpty() || file == null)
		{
			return;
		}
		try (Writer writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8,
			StandardOpenOption.CREATE, StandardOpenOption.APPEND))
		{
			for (String line : pending)
			{
				writer.write(line);
				writer.write("\n");
			}
		}
		catch (IOException e)
		{
			// A diagnostic that breaks the thing it is diagnosing is worse than
			// no diagnostic. Drop the buffer and carry on.
			log.warn("Could not write the transcript to {}", file, e);
		}
		pending.clear();
	}

	/**
	 * The session so far, as lines for the chatbox.
	 *
	 * <p>Computed from memory rather than by reading the file back, so it works
	 * mid-session and cannot be thrown off by an earlier run appending to the
	 * same day's file.
	 */
	public List<String> summary()
	{
		List<String> out = new ArrayList<>();
		if (spoken == 0)
		{
			out.add("Transcript: nothing said yet"
				+ (enabled ? "." : " (and it is off)."));
			return out;
		}

		long span = Math.max(1, lastSpokeMs - firstSpokeMs);
		double minutes = span / 60_000.0;
		out.add(String.format("Transcript: %d lines over %s (%.0f/hour), %d held back.",
			spoken, human(span), spoken / (minutes / 60.0), suppressed));

		if (!byReason.isEmpty())
		{
			out.add("  held back by: " + join(byReason, 4));
		}
		if (shortestGapMs != Long.MAX_VALUE)
		{
			out.add("  closest together " + human(shortestGapMs)
				+ ", longest quiet " + human(longestGapMs) + ".");
		}
		out.add("  loudest rules: " + join(byRule, 5));

		Map.Entry<String, Integer> worst = byLine.entrySet().stream()
			.max(Comparator.comparingInt(Map.Entry::getValue)).orElse(null);
		if (worst != null && worst.getValue() > 1)
		{
			out.add(String.format("  most repeated (%dx): \"%s\"",
				worst.getValue(), worst.getKey()));
		}
		return out;
	}

	/** The top few entries of a count map, biggest first. */
	private static String join(Map<String, Integer> counts, int limit)
	{
		return counts.entrySet().stream()
			.sorted(Comparator.comparingInt((Map.Entry<String, Integer> e) -> e.getValue())
				.reversed())
			.limit(limit)
			.map(e -> e.getKey() + " " + e.getValue())
			.reduce((a, b) -> a + ", " + b)
			.orElse("none");
	}

	/** 4.2s / 3m11s / 1h04m - the way a person says a duration. */
	private static String human(long ms)
	{
		long seconds = ms / 1000;
		if (seconds < 60)
		{
			return String.format("%.1fs", ms / 1000.0);
		}
		if (seconds < 3600)
		{
			return String.format("%dm%02ds", seconds / 60, seconds % 60);
		}
		return String.format("%dh%02dm", seconds / 3600, (seconds % 3600) / 60);
	}

	/** Forgets the session figures. The file is left alone. */
	public void reset()
	{
		spoken = 0;
		suppressed = 0;
		firstSpokeMs = 0;
		lastSpokeMs = 0;
		shortestGapMs = Long.MAX_VALUE;
		longestGapMs = 0;
		byRule.clear();
		byLine.clear();
		byReason.clear();
	}
}

package com.follower.speech;

public enum SpeechOutput
{
	/** Text bubble drawn above the follower. */
	OVERHEAD("Overhead"),
	/** Coloured message in the game chatbox. */
	CHATBOX("Chatbox"),
	/** Both at once. */
	BOTH("Both");

	private final String label;

	SpeechOutput(String label)
	{
		this.label = label;
	}

	public static SpeechOutput parse(String text, SpeechOutput fallback)
	{
		if (text == null)
		{
			return fallback;
		}
		for (SpeechOutput value : values())
		{
			if (value.name().equalsIgnoreCase(text.trim()))
			{
				return value;
			}
		}
		return fallback;
	}

	public boolean showsOverhead()
	{
		return this == OVERHEAD || this == BOTH;
	}

	public boolean showsChatbox()
	{
		return this == CHATBOX || this == BOTH;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.follower.speech;

import java.util.List;
import java.util.concurrent.ThreadLocalRandom;

/**
 * One trigger -> phrase rule, as authored in phrases.json.
 *
 * <p>A rule fires on the <em>rising edge</em> of its {@code when} block: the tick it
 * becomes true having been false. That means {@code healthBelow: 30} speaks once
 * when you drop under 30%, not every tick you spend there.
 */
public class SpeechRule
{
	/** Stable identifier; used for cooldown bookkeeping and log messages. */
	public String id;

	/** Free text for your own benefit. Ignored by the plugin. */
	public String note;

	/** Group name, so the config panel can switch whole categories off. */
	public String group = "misc";

	public Boolean enabled = Boolean.TRUE;

	/** Highest priority wins when several rules fire on the same event. */
	public int priority = 50;

	/** Minimum gap between firings of this rule. */
	public long cooldownMs = 10_000L;

	/**
	 * Game ticks to wait between the trigger and the line - a companion
	 * NOTICING something has a beat before the comment, where an instant
	 * reaction reads as scripted. The suppression checks (mute, global speech
	 * window) apply when the delay expires, not when it is queued.
	 */
	public Integer delayTicks;

	/**
	 * Upper bound for a VARIABLE delay: when set, each firing waits a fresh
	 * number of ticks drawn between {@link #delayTicks} and this, inclusive.
	 *
	 * <p>A fixed delay still lands on the same beat every time, which reads as
	 * machinery once you have seen it twice - most obvious when the follower
	 * copies an emote, where a constant offset looks like a delay line rather
	 * than someone joining in. Leave it unset for a fixed wait.
	 */
	public Integer delayTicksMax;

	/** Overrides the config default. One of overhead / chatbox / both. */
	public String output;

	/** Optional emote animation id to play alongside the phrase. */
	public Integer animation;

	/**
	 * Replay the PLAYER'S animation on the follower instead of a fixed id. Only
	 * meaningful when the rule triggers on an animation event ({@code animationSelf});
	 * with it, one rule mirrors every teleport in its id list without hardcoding
	 * which animation the follower answers with.
	 */
	public Boolean mirrorAnimation;

	/**
	 * Mirror the player's animation as a held POSE rather than a one-shot, for
	 * the emotes you can keep doing until you stop.
	 *
	 * <p>The game splits those in two: clicking Dance plays an entry clip and
	 * then loops a second animation for as long as you hold it. The entry is a
	 * one-shot and {@link #mirrorAnimation} handles it; the loop never ends, so
	 * playing it as an emote would wait forever for a finish that never comes
	 * and leave the follower stuck. A pose override loops by nature and is
	 * released when the player's animation changes, which is what "until I am
	 * done" actually means.
	 */
	public Boolean mirrorPose;

	/**
	 * A CHAIN of animation ids played back to back - for sequences authored as
	 * separate clips, like the home teleport's five stages. Takes precedence
	 * over {@link #animation} and {@link #mirrorAnimation}.
	 */
	public List<Integer> animations;

	/**
	 * Spotanim (graphic) ids paired stage-for-stage with {@link #animations}:
	 * each fires as its stage begins. -1 skips a stage. The home teleport pairs
	 * its rune-circle pieces this way.
	 */
	public List<Integer> graphics;

	/**
	 * Chain pacing: {@code true} advances each stage when the PLAYER's animation
	 * steps to its next stage - the server's own schedule - instead of when the
	 * follower's clip runs out. Teleport clips end in long hold frames the
	 * server always cuts short, so clip-length pacing freezes between stages.
	 */
	public Boolean syncToPlayer;

	/**
	 * Teleport exit: when the follower's mirrored animation ends, it VANISHES -
	 * as the player does at the end of their cast - and reappears beside them
	 * once they land. An interrupted cast (the animation gets cancelled)
	 * disarms it, keeping the follower where it stands.
	 */
	public Boolean vanishAfter;

	/**
	 * Plant the follower where it stands for the length of the animation, and
	 * let it follow again once the animation ends.
	 *
	 * <p>Movement always wins over an emote, so an animation played while the
	 * follower is walking is cut off the moment it starts. That is most of the
	 * time for anything triggered by a fight: it walks back to you the instant
	 * the fight is over. Without this, a celebration is a celebration nobody
	 * ever sees.
	 */
	public Boolean holdStill;

	/**
	 * How much this firing moves the follower's mood, positive or negative.
	 *
	 * <p>This is the whole mechanism by which anything affects mood: there is
	 * no list of significant events in the code. A rule that already knows how
	 * to notice a boss dying or a death or a good drop is exactly the thing
	 * that should say how much it mattered, and a new influence is a line in
	 * this file rather than a change to the engine.
	 *
	 * <p>Applied when the rule actually fires, so a rule suppressed by its
	 * cooldown or a disabled group does not move the mood either - the
	 * follower's state and what it says stay the same story.
	 */
	public Integer mood;

	/**
	 * Marks this line as a question, and names the dialog tree that answers it.
	 *
	 * <p>The value is a tree id from dialogs.json. While the question is open,
	 * right-clicking Talk-to opens THAT conversation instead of the everyday
	 * one, and picking the branch marked with an answer is what replies.
	 *
	 * <p>The answer used to be a word typed into public chat. That asked the
	 * player to know a magic word, and it asked the follower to listen to
	 * everything said near it - in a crowd, somebody else's "yes" was
	 * indistinguishable from yours. A menu of options can be neither misheard
	 * nor guessed at.
	 *
	 * <p>The window is opened by SAYING it, not by winning: a question the mute
	 * swallowed is one the player never heard.
	 */
	public String asks;

	/**
	 * Takes the floor: nothing else speaks for this many milliseconds.
	 *
	 * <p>For the handful of moments worth more than whatever the follower was
	 * otherwise about to say. Arriving where it asked to be taken is the clear
	 * case - the region change raises an area line at the same instant, and two
	 * lines about one arrival is one too many.
	 *
	 * <p>The floor is taken when the rule WINS rather than when it speaks, or a
	 * rule with a delay would leave its own gap open for exactly the line it
	 * meant to displace. The holder is also exempt from the global speech gap,
	 * since being held back by whatever spoke a second earlier is the same
	 * failure from the other end.
	 *
	 * <p>Only speech is hushed. An animation-only rule is movement rather than
	 * chatter and carries on regardless.
	 */
	public Integer hushMs;

	/**
	 * A line the follower must not be too busy to say.
	 *
	 * <p>Distinct from {@link #priority}, which only decides who wins when
	 * several rules fire at once. This decides whether the winner gets through
	 * a RELAX period - the director stops ordinary chatter after a burst, and
	 * this is what the stopping was for. An occasion also spends no intensity
	 * of its own, so the moment does not cost the follower the next thing it
	 * wanted to say.
	 *
	 * <p>Two kinds of line qualify, and they are not the same kind. One is the
	 * moment worth marking - the pet, the anniversary, the place it asked to be
	 * taken. The other is the warning that has to land: if the player is about
	 * to die and the director has just told the follower to be quiet, silence
	 * is a worse failure than repetition could ever be.
	 *
	 * <p>Reserve it anyway, and judge it by how often the player HEARS one
	 * rather than by how many rules carry the flag. Forty-seven boss lines look
	 * like a lot in the file and amount to one a session in play.
	 */
	public Boolean occasion;

	/**
	 * Said once, ever, and then never again.
	 *
	 * <p>For firsts. A line that only has to hold up on a single hearing can be
	 * specific in a way no repeating line can afford to be - it can name the
	 * moment, admit something, or land a joke that would be unbearable the
	 * fourth time. That makes it the highest value per word in the file, and
	 * the only kind of line that never wears out.
	 *
	 * <p>What was spent is remembered by ID, alongside the tallies and the
	 * places, rather than on this object - so it survives both a restart and a
	 * rule reload, which throws every rule away and parses the file afresh.
	 */
	public Boolean once;

	/**
	 * A held prop and a pose to play over it, for the length of the line's
	 * moment: the writing flourish.
	 *
	 * <p>{@code {"item": 10485, "pose": 5354, "ticks": 8}} - the follower
	 * stops, the scroll comes out, the writing pose holds for the ticks given,
	 * and everything goes back where it was. For the lines that CLAIM the
	 * notebook - "That's going in the book" - so the claim and the act finally
	 * happen together.
	 *
	 * <p>The item must be wearable (the prop is equipment, transiently) and
	 * the pose id must be a LOOP, because it is held as a pose override. Both
	 * halves of the shipped pairing were verified in game before being written
	 * down here; see docs/prop-and-animation-catalogue.md before inventing new
	 * ones. Best effort by design: if the follower is mid-errand or otherwise
	 * spoken for, the line still says its words and the gesture is dropped.
	 */
	public Flourish prop;

	public static final class Flourish
	{
		public Integer item;
		public Integer pose;
		public Integer ticks;
	}

	/**
	 * Somewhere the follower would like to go, expressed as part of saying so.
	 *
	 * <p>{@code {"region": 10553, "label": "the fishing guild", "minutes": 20}}.
	 * Going there before the deadline fulfils it; the deadline passing expires
	 * it. Either way a rule gets to react, and the {want} placeholder carries
	 * the label - so the follower can be pleased about the specific thing it
	 * asked for rather than pleased in general.
	 */
	public Want want;

	public static final class Want
	{
		public Integer region;
		public String label;
		public Integer minutes;
	}

	/**
	 * A small thing the follower says it could use, opened by SAYING so, like
	 * the want. {@code {"what": "feather", "minutes": 45}}. While it is open
	 * the Talk-to script offers "Found you that feather." - the gift names
	 * the thing because the follower named it first.
	 *
	 * <p>The label is a bare noun phrase with no article, because everything
	 * downstream frames it: "that {wish}", "the {wish} you found me".
	 */
	public Wish wish;

	public static final class Wish
	{
		public String what;
		public Integer minutes;

		/**
		 * The real inventory items that grant it. The wish must be for a
		 * thing the player can actually go and get - play testing found the
		 * bluff on day one - so every authored wish names its item ids, and
		 * the gift checks the bag.
		 */
		public java.util.List<Integer> items;
	}

	/**
	 * This firing grants the open wish: the follower got the thing, and the
	 * wish closes. Only meaningful on rules reacting to the gift.
	 */
	public Boolean grantsWish;

	/**
	 * Files what just happened as the incident worth bringing up again.
	 *
	 * <p>{@code {"key": "chicken-death", "as": "that chicken"}}. The key is what
	 * a later rule recognises; the phrase is how the follower says it out loud,
	 * via {memory}.
	 *
	 * <p>This is the difference between counting and remembering. A tally makes
	 * "your four hundredth yew" possible, which is data delivered well. An
	 * incident makes "careful, I've seen what a chicken can do to you"
	 * possible, which is a shared history - and only one of those sounds like
	 * somebody who was there.
	 */
	public Incident remember;

	public static final class Incident
	{
		public String key;
		public String as;
	}

	/**
	 * Something the follower picks up and carries about for a while.
	 *
	 * <p>{@code {"what": "a nice flat rock", "minutes": 30}}. Nothing else it
	 * owns is an object: everything else is a number, a mood or a place.
	 */
	public Souvenir pickUp;

	public static final class Souvenir
	{
		public String what;
		public Integer minutes;

		/**
		 * Replace whatever is carried instead of refusing while the pocket is
		 * full. Only for rules that SAY the exchange - the refuse-if-carrying
		 * guard exists to stop silent swaps, not spoken ones.
		 */
		public Boolean swap;
	}

	/**
	 * A prediction about what the next drop is worth.
	 *
	 * <p>{@code {"rich": false, "threshold": 50000, "minutes": 5}} is the
	 * follower betting the next drop comes in UNDER fifty thousand. Being wrong
	 * is the better half - anything that can only be right is not predicting.
	 */
	public Bet bet;

	public static final class Bet
	{
		public Boolean rich;
		public Integer threshold;
		public Integer minutes;
	}

	/**
	 * Sets the player a challenge, against a counter and a clock.
	 *
	 * <p>{@code {"about": "ten kills", "tally": "kills", "target": 10,
	 * "minutes": 5}}. The bet is a wager on the world; this is a wager on you.
	 *
	 * <p>Any tally the follower already keeps will do, so a new challenge is a
	 * rule naming a counter and a number rather than a scoring system.
	 */
	public Challenge challenge;

	public static final class Challenge
	{
		public String about;
		public String tally;
		public Integer target;
		public Integer minutes;
	}

	/**
	 * Marks this line as ADVICE, and says what taking it would look like.
	 *
	 * <p>{@code {"about": "food", "ids": [829, 1191], "minutes": 1}} - the
	 * follower says eat something, and eating inside the minute settles it.
	 * {@code "room": true} settles instead on the inventory getting emptier,
	 * which covers banking, dropping, and eating the thing in the way.
	 *
	 * <p>What counts is named HERE rather than known by the engine, so adding a
	 * new piece of advice is a rule and not a code change.
	 *
	 * <p>Like a question, it only opens if the line was actually said: advice
	 * the mute swallowed is advice the player was never given, and holding it
	 * against them would be unfair as well as wrong.
	 */
	public Advice advise;

	public static final class Advice
	{
		public String about;
		public List<Integer> ids;
		public Boolean room;
		public Integer minutes;
	}

	/**
	 * Files this moment against the PLACE, for a rule to bring up next time you
	 * are standing here.
	 *
	 * <p>{@code "markHere": "the drop"} - said later via {here}, as in "this is
	 * where you got the drop". The incident in {@link #remember} is one thing
	 * anywhere; this is one thing per place, and waits for you to come back.
	 */
	public String markHere;

	public Condition when;

	/**
	 * Phrases to choose from, drawn without replacement. Optional when the rule
	 * plays an animation: an animation-only rule is a valid rule with no speech
	 * at all.
	 */
	public List<String> say;

	// ---- runtime state, not serialised ----
	private transient boolean lastState;
	private transient long lastFiredMs;
	private transient int lastPhraseIndex = -1;

	/**
	 * The shuffle bag: a shuffled run of every index, drawn through in order
	 * and refilled when it empties.
	 *
	 * <p>Uniform random with an anti-immediate-repeat guard sounds like the
	 * right thing and is not, because a player does not hear "random" - they
	 * hear the second time. With thirty variants, uniform draws start repeating
	 * after about eight, which is a quarter of the value of the writing. A bag
	 * gives all thirty first, every time.
	 */
	private transient int[] bag;
	private transient int bagPos;

	/** How long the say list was when the bag was built, so a hot-reloaded
	 * rule gets a fresh bag; the bag itself may be shorter than the list
	 * when worn lines are standing aside. */
	private transient int bagSaySize;

	/**
	 * Says past which a line is worn out: with anything fresher in the same
	 * rule, a line heard this many times stands aside at the next refill
	 * (R17). Relative rather than absolute - when every line in a rule is
	 * this worn, all of them come back, because retiring the lot would
	 * retire the rule.
	 */
	public static final int TIRED_AFTER = 20;

	public boolean isEnabled()
	{
		return enabled == null || enabled;
	}

	public boolean isOccasion()
	{
		return Boolean.TRUE.equals(occasion);
	}

	public boolean isOnce()
	{
		return Boolean.TRUE.equals(once);
	}

	public boolean isValid()
	{
		return when != null && (hasSpeech() || hasAnimationAction());
	}

	public boolean hasSpeech()
	{
		return say != null && !say.isEmpty();
	}

	/**
	 * How many ticks THIS firing waits: {@link #delayTicks}, or a fresh draw
	 * between it and {@link #delayTicksMax} when that is set. Rolled once per
	 * firing, so the wait is decided at the win and not re-rolled while the
	 * firing sits pending.
	 */
	public int rollDelayTicks()
	{
		int min = delayTicks == null ? 0 : Math.max(0, delayTicks);
		int max = delayTicksMax == null ? min : Math.max(min, delayTicksMax);
		return max > min
			? min + java.util.concurrent.ThreadLocalRandom.current().nextInt(max - min + 1)
			: min;
	}

	public boolean hasAnimationAction()
	{
		return animation != null
			|| Boolean.TRUE.equals(mirrorAnimation)
			|| Boolean.TRUE.equals(mirrorPose)
			|| hasAnimationChain();
	}

	public boolean hasAnimationChain()
	{
		return animations != null && !animations.isEmpty();
	}

	/**
	 * The animation this firing should play, or null for none: the fixed
	 * {@link #animation} id, unless {@link #mirrorAnimation} is set and the
	 * triggering event carries the player's animation to copy.
	 */
	public Integer resolveAnimation(TriggerEvent event)
	{
		if ((Boolean.TRUE.equals(mirrorAnimation) || Boolean.TRUE.equals(mirrorPose))
			&& event != null
			&& event.getType() == TriggerEvent.Type.ANIMATION
			&& event.getId() != -1)
		{
			return event.getId();
		}
		return animation;
	}

	/**
	 * Updates the stored edge state and reports whether this evaluation is a rising
	 * edge. Always call exactly once per evaluation pass, even when the rule is
	 * going to be skipped for cooldown, or the edge tracking drifts.
	 */
	public boolean risingEdge(boolean nowMatching)
	{
		boolean rising = nowMatching && !lastState;
		lastState = nowMatching;
		return rising;
	}

	public boolean offCooldown(long nowMs)
	{
		return nowMs - lastFiredMs >= cooldownMs;
	}

	public void markFired(long nowMs)
	{
		lastFiredMs = nowMs;
	}

	/**
	 * Forgets the edge and the cooldown, so the rule may fire again as soon as
	 * its condition next rises. Deliberately leaves the shuffle bag alone: what
	 * the follower has already said is not scene state, and a player who hops
	 * worlds often would otherwise be handed the front of a fresh bag every
	 * time and hear the same few lines for it.
	 */
	public void resetEdges()
	{
		lastState = false;
		lastFiredMs = 0L;
	}

	/** The full clear, bag included. For starting the follower over. */
	public void reset()
	{
		resetEdges();
		lastPhraseIndex = -1;
		bag = null;
		bagPos = 0;
	}

	public String pickPhrase()
	{
		return pickPhrase(java.util.Collections.<String>emptySet());
	}

	public String pickPhrase(java.util.Set<String> recentlySaid)
	{
		return pickPhrase(recentlySaid, line -> 0);
	}

	/**
	 * The next line, drawn without replacement.
	 *
	 * @param recentlySaid lines the follower has used lately, ACROSS every
	 * rule. Skipped when there is an alternative, which is what stops two
	 * neighbouring rules from ping-ponging the same observation at each other -
	 * a bag can only keep one rule honest about itself. Never allowed to
	 * produce silence: if everything in the bag has been heard lately, the
	 * draw stands, because a repeated line beats no line.
	 * @param wear how many times a line has been said across every session;
	 * lines at {@link #TIRED_AFTER} or beyond stand aside at the refill while
	 * anything fresher exists.
	 */
	public String pickPhrase(java.util.Set<String> recentlySaid,
		java.util.function.ToIntFunction<String> wear)
	{
		if (say == null || say.isEmpty())
		{
			return "";
		}
		if (say.size() == 1)
		{
			return say.get(0);
		}

		int index = draw(wear);

		// One pass over what is left in the bag, in bag order, looking for
		// something unheard. Bounded deliberately: the alternative is
		// reshuffling until something fits, which never terminates for a rule
		// whose every line is already in the window.
		if (recentlySaid.contains(say.get(index)))
		{
			int drawnAt = bagPos - 1;
			for (int i = bagPos; i < bag.length; i++)
			{
				if (!recentlySaid.contains(say.get(bag[i])))
				{
					// The rejected line goes back into the un-drawn part of the
					// bag, so it still gets its turn later in this cycle.
					//
					// The second assignment is dead and kept on purpose. Slots
					// below bagPos are never read again before the array is
					// rebuilt, so writing the fresher index there changes
					// nothing - but it keeps the array a true permutation at
					// every instant, which is the invariant this is easiest to
					// reason about and to assert. A mutation sweep flagged it
					// as unreachable, which is correct and not a defect.
					int fresher = bag[i];
					bag[i] = bag[drawnAt];
					bag[drawnAt] = fresher;
					index = fresher;
					break;
				}
			}
		}

		lastPhraseIndex = index;
		return say.get(index);
	}

	/** The next index out of the bag, refilling it when it runs dry. */
	private int draw(java.util.function.ToIntFunction<String> wear)
	{
		if (bag == null || bagSaySize != say.size() || bagPos >= bag.length)
		{
			refill(wear);
		}
		return bag[bagPos++];
	}

	private void refill(java.util.function.ToIntFunction<String> wear)
	{
		// Worn lines stand aside here, which keeps the bag's guarantee intact
		// for what remains: a cycle is still a cycle, just of fresher lines.
		// Wear is checked at the refill rather than the draw, so a line
		// crossing the threshold mid-cycle still finishes its turn.
		int fresh = 0;
		boolean[] tired = new boolean[say.size()];
		for (int i = 0; i < say.size(); i++)
		{
			tired[i] = wear.applyAsInt(say.get(i)) >= TIRED_AFTER;
			if (!tired[i])
			{
				fresh++;
			}
		}
		boolean everyoneWorn = fresh == 0;

		bag = new int[everyoneWorn ? say.size() : fresh];
		int at = 0;
		for (int i = 0; i < say.size(); i++)
		{
			if (everyoneWorn || !tired[i])
			{
				bag[at++] = i;
			}
		}
		for (int i = bag.length - 1; i > 0; i--)
		{
			int j = ThreadLocalRandom.current().nextInt(i + 1);
			int swap = bag[i];
			bag[i] = bag[j];
			bag[j] = swap;
		}

		// The one seam a bag has: the last line of one bag and the first of the
		// next are adjacent draws with nothing stopping them being the same
		// line. That is the exact back-to-back repeat the old code existed to
		// prevent, and it would happen once per bag rather than at random.
		if (bag.length > 1 && bag[0] == lastPhraseIndex)
		{
			int j = 1 + ThreadLocalRandom.current().nextInt(bag.length - 1);
			bag[0] = bag[j];
			bag[j] = lastPhraseIndex;
		}
		bagSaySize = say.size();
		bagPos = 0;
	}

	public String describe()
	{
		return id == null ? "(unnamed rule in group " + group + ")" : id;
	}
}

package com.follower.speech;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Folding an update into a file somebody has been editing.
 *
 * <p>Both the rules and the conversation trees ship with defaults, get edited,
 * and then have to receive the next version without losing the editing. Doing
 * that needs three copies rather than two, because from the player's file alone
 * a line the update ADDED and a line the player DELETED look identical - both
 * are lines the bundled file has and theirs does not. Keep the defaults as they
 * stood at the last merge and the question becomes answerable: bundled against
 * base is what the update did, theirs against base is what the player did.
 *
 * <p>The rule throughout is that upstream wins where the player has not touched
 * something, and the player wins everywhere they have. This is one class rather
 * than two copies because the two loaders drifting apart on a question this
 * subtle would be a bug nobody would find by reading either one.
 */
public final class ThreeWay
{
	private ThreeWay()
	{
	}

	/**
	 * Every field except the named ones. A field the update did not change is
	 * left alone; one the player changed is theirs; the rest take the update's
	 * value, or go if the update dropped them.
	 *
	 * @return how many fields moved
	 */
	public static int fields(JsonObject held, JsonObject base, JsonObject bundled,
		Set<String> except)
	{
		int changes = 0;
		Set<String> keys = new LinkedHashSet<>(bundled.keySet());
		keys.addAll(base.keySet());
		for (String key : keys)
		{
			if (except.contains(key))
			{
				continue;
			}
			JsonElement before = base.get(key);
			JsonElement now = bundled.get(key);
			if (Objects.equals(before, now))
			{
				// The update has nothing to offer here.
				continue;
			}
			if (!Objects.equals(held.get(key), before))
			{
				// The player moved it. A tuned cooldown or a reworded note is
				// a decision, not a stale copy.
				continue;
			}
			if (now == null)
			{
				held.remove(key);
			}
			else
			{
				held.add(key, now);
			}
			changes++;
		}
		return changes;
	}

	/**
	 * An array of strings, merged as a set with a history. What the update
	 * added arrives; what it removed goes, unless the player had already
	 * removed it; everything else - their own lines, their own rewordings - is
	 * left exactly where it is.
	 *
	 * @return how many lines moved
	 */
	public static int strings(JsonObject held, String key, JsonObject base, JsonObject bundled)
	{
		if (!held.has(key) || !held.get(key).isJsonArray())
		{
			return 0;
		}
		List<String> shipped = strings(bundled, key);
		Set<String> was = new HashSet<>(strings(base, key));
		Set<String> now = new HashSet<>(shipped);
		int changes = 0;

		List<String> kept = new ArrayList<>();
		for (String line : strings(held, key))
		{
			if (was.contains(line) && !now.contains(line))
			{
				changes++;
				continue;
			}
			kept.add(line);
		}
		for (String line : shipped)
		{
			if (!was.contains(line) && !kept.contains(line))
			{
				kept.add(line);
				changes++;
			}
		}
		if (changes > 0)
		{
			JsonArray out = new JsonArray();
			for (String line : kept)
			{
				out.add(line);
			}
			held.add(key, out);
		}
		return changes;
	}

	/** The strings under a key, or empty. */
	public static List<String> strings(JsonObject object, String key)
	{
		List<String> out = new ArrayList<>();
		if (object != null && object.has(key) && object.get(key).isJsonArray())
		{
			for (JsonElement element : object.getAsJsonArray(key))
			{
				if (element.isJsonPrimitive())
				{
					out.add(element.getAsString());
				}
			}
		}
		return out;
	}

	/**
	 * Whether the player has written anything of their own here.
	 *
	 * <p>The only question the first run can honestly ask. With no base there
	 * is no way to tell a deletion from an addition, but a file holding
	 * nothing but shipped lines has plainly not been written into, and can be
	 * brought up to date without taking anything away from anybody.
	 */
	public static boolean untouched(List<String> theirs, List<String> shipped)
	{
		Set<String> known = new HashSet<>(shipped);
		for (String line : theirs)
		{
			if (!known.contains(line))
			{
				return false;
			}
		}
		return true;
	}

	/** The objects of an array, by their {@code id}. */
	public static Map<String, JsonObject> byId(JsonArray array)
	{
		Map<String, JsonObject> map = new HashMap<>();
		if (array == null)
		{
			return map;
		}
		for (JsonElement element : array)
		{
			String id = idOf(element);
			if (id != null)
			{
				map.put(id, element.getAsJsonObject());
			}
		}
		return map;
	}

	public static JsonArray array(JsonObject object, String key)
	{
		return object != null && object.has(key) && object.get(key).isJsonArray()
			? object.getAsJsonArray(key) : null;
	}

	public static String idOf(JsonElement element)
	{
		if (element == null || !element.isJsonObject())
		{
			return null;
		}
		JsonElement id = element.getAsJsonObject().get("id");
		return id != null && id.isJsonPrimitive() ? id.getAsString() : null;
	}
}

package com.follower.speech;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;

/**
 * A snapshot of game state, refreshed once per game tick and shared by every
 * condition evaluated that tick.
 */
@lombok.extern.slf4j.Slf4j
public final class TriggerContext
{
	/** Prayer counts as "active" if points have dropped within this many ticks. */
	private static final int PRAYER_DRAIN_MEMORY_TICKS = 5;

	private final Client client;

	private int hitpoints;
	private int maxHitpoints;
	private int prayerPoints;
	private int maxPrayerPoints;
	private int regionId = -1;
	private int previousRegionId = -1;
	private int idleTicks;
	private int ticksSincePrayerDrain = Integer.MAX_VALUE;
	private int lastPrayerPoints = -1;
	private WorldPoint location;
	private Set<Integer> loadedRegions = new HashSet<>();
	private Set<Integer> equippedItems = new HashSet<>();

	public TriggerContext(Client client)
	{
		this.client = client;
	}

	/**
	 * Bumped every {@link #refresh()}: per-tick memoisation key for expensive
	 * state conditions (npcNearby caches its scan against it).
	 */
	@lombok.Getter
	private int refreshGeneration;

	public void refresh()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		refreshGeneration++;

		if (boundaryTicksLeft > 0)
		{
			boundaryTicksLeft--;
		}

		inWilderness = client.getVarbitValue(WILDERNESS_VARBIT) == 1;

		hitpoints = client.getBoostedSkillLevel(Skill.HITPOINTS);
		maxHitpoints = client.getRealSkillLevel(Skill.HITPOINTS);

		prayerPoints = client.getBoostedSkillLevel(Skill.PRAYER);
		maxPrayerPoints = client.getRealSkillLevel(Skill.PRAYER);

		// getEnergy counts hundredths of a percent, 0-10000 - the same scale
		// RuneLite's own run-energy plugin measures against.
		//
		// This used to divide only when the reading was above 100, meaning to
		// tolerate an older 0-100 API. That guard was backwards where it
		// mattered: 100 hundredths is one percent left, and it was reported as
		// a hundred. Every reading under one percent - exactly the moment a
		// low-energy line is worth saying - read as nearly full.
		energyPercent = client.getEnergy() / 100;

		skulled = local.getSkullIcon() != -1;

		if (lastPrayerPoints >= 0 && prayerPoints < lastPrayerPoints)
		{
			ticksSincePrayerDrain = 0;
		}
		else if (ticksSincePrayerDrain < Integer.MAX_VALUE)
		{
			ticksSincePrayerDrain++;
		}
		lastPrayerPoints = prayerPoints;

		WorldPoint previousLocation = location;
		location = local.getWorldLocation();
		if (location != null)
		{
			int newRegion = location.getRegionID();
			if (newRegion != regionId)
			{
				// Leaving is what turns a fresh memory into one worth
				// bringing up when you next come back.
				placesJustFiled.remove(regionId);
				previousRegionId = regionId;
				regionId = newRegion;
				noteRegionEntered(newRegion);
			}
			// Seen THIS tick, so pacing along a region boundary - which fires
			// the change over and over - never reads as a string of visits.
			regionLastSeenTick.put(newRegion, client.getTickCount());
		}

		if (previousLocation != null && previousLocation.equals(location) && local.getAnimation() == -1)
		{
			idleTicks++;
		}
		else
		{
			idleTicks = 0;
		}

		// Before combat, which asks whether this is thieving before deciding.
		refreshThieving(local);
		refreshCombat(local);

		refreshLoadedRegions();
		refreshEquipment(local.getPlayerComposition());
		refreshRepetition(local);
		ageQuestion();
		checkWant();
		checkSouvenir();
		checkBet();
		checkAdvice();
		checkChallenge();
		checkWishLapse();
		refreshAttention();
		driftMood();
	}

	// ------------------------------------------------------------------ combat

	/**
	 * How long a fight is considered to still be going after the last sign of
	 * one. Monsters die, targets are re-clicked, and a boss between phases can
	 * leave a tick or two with no interaction at all; without a grace window
	 * the follower would bob in and out of spectating throughout a kill.
	 */
	private static final int COMBAT_GRACE_TICKS = 8;

	/** A rough line between "a monster" and "a boss", by combat level. */
	private static final int BOSS_COMBAT_LEVEL = 100;

	private int ticksSinceCombat = Integer.MAX_VALUE;
	private String combatTarget = "";
	private int combatTargetLevel;

	/** Names the boss rules watch for, and those names compiled. */
	private java.util.Set<String> bossNames = java.util.Collections.emptySet();
	private java.util.List<java.util.regex.Pattern> bossPatterns =
		java.util.Collections.emptyList();

	/**
	 * Works out whether the player is fighting, from the two things that are
	 * always true of a fight: they are interacting with something that can
	 * fight back, or something is hitting them.
	 *
	 * <p>Interaction alone is not enough - talking to a banker and pickpocketing
	 * a guard are both interactions - so the target has to have a combat level.
	 * Damage is fed in separately by the plugin's hitsplat handler, which
	 * catches being attacked while doing nothing back.
	 */
	// ---------------------------------------------------------------- thieving

	/** HUMAN_PICKPOCKET, 1.78s. The attempt itself. */
	private static final int PICKPOCKET_ANIMATION = 881;

	/**
	 * Every stun the player can be put in for getting it wrong.
	 *
	 * <p>There is not one. Measured from the cache: 1054 STUNNED_THIEVING at
	 * 4.48s, 1874 STUNNED_BLACKJACK at 1.28s, 848 HUMAN_STUNNED at 0.64s, and
	 * a whole family sized to the stun's length - STUNNED_2CYCLE through
	 * 6CYCLE at 1.20s, 1.84s, 2.40s, 3.04s and 3.60s.
	 *
	 * <p>Recognising only STUNNED_THIEVING covered one case in seven, so any
	 * other target or method left the stun unaccounted for and the window
	 * running from the last successful attempt instead. That is the "sometimes"
	 * in "sometimes it comes back too early".
	 */
	private static final Set<Integer> THIEVING_STUNS = new HashSet<>(
		Arrays.asList(1054, 1874, 848, 14422, 14423, 14424, 10087, 10088));

	/**
	 * How long a thieving ANIMATION counts as an attempt in progress.
	 *
	 * <p>Only used to keep the session alive across the gap between attempts;
	 * the session itself is what everything else asks about.
	 */
	private static final int THIEVING_GRACE_TICKS = 20;

	/**
	 * How long the follower keeps its distance while the player stays put.
	 *
	 * <p>Much longer, because the cost is only that the follower stands a few
	 * tiles away. Anchored to WHERE the thieving happened rather than to a
	 * clock alone: it ends the moment the player walks off, which is the signal
	 * a person actually gives when they are done.
	 */
	/**
	 * How long a pause can run before the session is over. Two and a half
	 * minutes rather than ninety seconds: opening a run of coin pouches or
	 * drinking a stamina dose ran past the old figure, which ended the session
	 * mid-run and let the next failed pickpocket read as a fight.
	 */
	private static final int THIEVING_SESSION_TICKS = 250;
	/**
	 * How far the player may drift from the last attempt before the session is
	 * considered over.
	 *
	 * <p>Five tiles was sized for a STALL - a fixed point you stand at. Elves
	 * wander and you follow them, so five tiles ended the session every time
	 * the mark walked, several times a minute: the follower announced the end
	 * of a theft that was still going on, and cheered on the "fight" the next
	 * failed attempt looked like. The anchor moves to the player on every
	 * attempt, so this only has to cover the drift BETWEEN attempts.
	 */
	private static final int THIEVING_SESSION_RADIUS = 12;

	private int ticksSinceThieving = Integer.MAX_VALUE;
	private WorldPoint thievingSpot;

	private void refreshThieving(Player local)
	{
		int animation = local.getAnimation();
		if (animation == PICKPOCKET_ANIMATION || THIEVING_STUNS.contains(animation))
		{
			ticksSinceThieving = 0;
			thievingSpot = location;
		}
		else if (ticksSinceThieving < Integer.MAX_VALUE)
		{
			ticksSinceThieving++;
		}

		// Intent can arm the clock before there is anywhere to anchor it - the
		// click arrives from the menu, which does not wait for a refresh. Adopt
		// the first location seen after it, ONCE: without the latch this also
		// re-anchors a session that walking away had just ended, and walking
		// away stops working.
		if (awaitingThievingAnchor && location != null)
		{
			thievingSpot = location;
			awaitingThievingAnchor = false;
		}

		// Walking away ends the session outright, whatever the clock says.
		if (thievingSpot != null && location != null
			&& (location.getPlane() != thievingSpot.getPlane()
			|| location.distanceTo(thievingSpot) > THIEVING_SESSION_RADIUS
			|| ticksSinceThieving > THIEVING_SESSION_TICKS))
		{
			thievingSpot = null;
			awaitingThievingAnchor = false;
		}
	}

	/**
	 * The player has said they are about to steal something.
	 *
	 * <p>Arming on the ANIMATION was too late. Clicking Pickpocket on an elf
	 * across the room sets the interaction target immediately and then the
	 * player walks over, and for every tick of that walk the follower saw an
	 * NPC with a combat level and called it a fight - so the very first attempt
	 * of a session announced a battle that was actually a theft. The click is
	 * intent and arrives first; the animation is outcome and arrives after the
	 * damage.
	 */
	public void noteThievingIntent()
	{
		ticksSinceThieving = 0;
		if (location != null)
		{
			thievingSpot = location;
		}
		else
		{
			awaitingThievingAnchor = true;
		}
		log.debug("Thieving intent at {}", location);
	}

	/** Set when intent arrived before there was a location to pin it to. */
	private boolean awaitingThievingAnchor;

	/**
	 * The player has said they are about to fight something, which ends any
	 * theft outright.
	 *
	 * <p>The session deliberately outlives the gaps between attempts, and the
	 * cost of that is a window where a genuine fight goes unnoticed. An
	 * explicit Attack is the one unambiguous signal that the window should
	 * close now rather than when the player next wanders off.
	 */
	public void noteFightIntent()
	{
		thievingSpot = null;
		awaitingThievingAnchor = false;
		ticksSinceThieving = Integer.MAX_VALUE;
	}

	/**
	 * Whether the player is mid-attempt, or was a moment ago. Used to keep a
	 * picked pocket from reading as a fight.
	 */
	public boolean isThieving()
	{
		return ticksSinceThieving <= THIEVING_GRACE_TICKS;
	}

	/**
	 * Whether the player is still working this spot, gaps between attempts
	 * included. Used to decide whether the follower keeps its distance.
	 */
	public boolean isInThievingSession()
	{
		return thievingSpot != null;
	}

	private void refreshCombat(Player local)
	{
		// Pickpocketing is not a fight, and it looks exactly like one from
		// here: the target is an NPC with a combat level, and a failed attempt
		// lands a hitsplat. Both of the signals combat is read from are
		// therefore true, and the follower flickered in and out of spectating
		// for the whole run.
		//
		// The whole SESSION is suppressed rather than the attempt, because the
		// gap between attempts is longer than any window sized to a stun, and
		// a fight registered in that gap surfaces the moment thieving ends -
		// which is the follower announcing a fight that never happened.
		//
		// The cost is real and accepted: an actual attack while working a
		// pocket goes unnoticed until the session ends, which it does as soon
		// as the player moves off - and being attacked is one of the few
		// things that makes a player move.
		if (isInThievingSession())
		{
			return;
		}

		Actor target = local.getInteracting();
		boolean facing = target instanceof NPC && target.getCombatLevel() > 0
			&& target.getHealthRatio() != 0;

		if (facing && blowsHaveBeenExchanged(local, target))
		{
			combatTarget = target.getName() == null ? "" : target.getName();
			combatTargetLevel = target.getCombatLevel();
			ticksSinceCombat = 0;
		}
		else if (ticksSinceCombat < Integer.MAX_VALUE)
		{
			ticksSinceCombat++;
		}
	}

	/**
	 * Whether facing this NPC is a FIGHT, as opposed to merely looking at it.
	 *
	 * <p>Interaction alone used to be enough, and interaction covers walking
	 * up to somebody, talking to them and trading with them. Any levelled NPC
	 * would do - so approaching a guard for directions read as a battle
	 * starting, and the follower announced one.
	 *
	 * <p>A fight has two sides or it has blows. Either the NPC is facing back,
	 * or damage has passed between them recently - the first hit in either
	 * direction arms this through {@link #noteDamageTaken} and
	 * {@link #noteDamageDealt}, and this then keeps it alive for as long as the
	 * two are still squared up.
	 */
	private boolean blowsHaveBeenExchanged(Player local, Actor target)
	{
		return target.getInteracting() == local || isInCombat();
	}

	/**
	 * Called by the plugin when the player takes a hit.
	 *
	 * <p>A hit is combat only if the player is ENGAGED - facing a levelled
	 * NPC. Taken alone it is not: running through an aggressive area collects
	 * hits from things the player is neither fighting nor going to fight, and
	 * every combat line is written for the player's own fight ("room to
	 * swing", "you make this look easy") - which is wrong in kind, not just
	 * in volume, when they are the one being chased. Play report: a night's
	 * transcript at 57% combat that was mostly the player getting hit
	 * running past aggro. Retaliation still starts a fight instantly, since
	 * attacking back is interacting; a hit landed by the player still counts
	 * through {@link #noteDamageDealt}; and a boss whose mechanics hit the
	 * player while they are targeting it is engaged by definition.
	 */
	public void noteDamageTaken()
	{
		if (isInThievingSession())
		{
			return;
		}
		Player local = client.getLocalPlayer();
		Actor target = local == null ? null : local.getInteracting();
		boolean engaged = target instanceof NPC && target.getCombatLevel() > 0;
		if (engaged)
		{
			ticksSinceCombat = 0;
		}
	}

	/**
	 * The player landed a hit on something, which is the other way a fight
	 * starts - and the only signal available when the target dies before it
	 * can turn round, or cannot reach the player at all.
	 */
	public void noteDamageDealt()
	{
		if (isInThievingSession())
		{
			return;
		}
		ticksSinceCombat = 0;
	}

	/** Whether the player is fighting, or was a moment ago. */
	public boolean isInCombat()
	{
		return ticksSinceCombat <= COMBAT_GRACE_TICKS;
	}

	/** Whether that fight is with something big enough to call a boss. */
	/**
	 * The names the boss rules list, so that "boss" means one thing.
	 *
	 * <p>It used to mean combat level 100, in two places that had to be kept
	 * agreeing by hand, and the proxy simply fails for anything that fights
	 * above its level. Taking the names from the rules rather than from a
	 * second list in here means adding a boss rule is all it takes: the
	 * follower stands clear of it and cheers it going down without anybody
	 * remembering to say so twice.
	 */
	public void setBossNames(java.util.Set<String> names)
	{
		if (names == bossNames)
		{
			return;
		}
		bossNames = names == null ? java.util.Collections.emptySet() : names;
		java.util.List<java.util.regex.Pattern> compiled =
			new java.util.ArrayList<>(bossNames.size());
		for (String name : bossNames)
		{
			compiled.add(Condition.compileName(name));
		}
		bossPatterns = compiled;
	}

	public boolean isNamedBoss(String name)
	{
		if (name == null || name.isEmpty())
		{
			return false;
		}
		String normalised = Condition.normaliseName(name);
		for (java.util.regex.Pattern pattern : bossPatterns)
		{
			if (pattern.matcher(normalised).matches())
			{
				return true;
			}
		}
		return false;
	}

	/** Big enough to be a boss, or named as one. Either will do. */
	public boolean isBoss(String name, int level)
	{
		return level >= BOSS_COMBAT_LEVEL || isNamedBoss(name);
	}

	public boolean isBossFight()
	{
		return isInCombat() && isBoss(combatTarget, combatTargetLevel);
	}

	/** The name of what is being fought, for the {npc} placeholder. */
	public String getCombatTarget()
	{
		return combatTarget;
	}

	public int getCombatTargetLevel()
	{
		return combatTargetLevel;
	}

	// ------------------------------------------------------------ time away

	/**
	 * Minutes between the follower last seeing the player and this login, or -1
	 * when it has no idea - a first run, or a cleared config.
	 *
	 * <p>The only thing in here that outlives a session, and the only thing
	 * that should: it is the difference between a companion that exists when
	 * you are gone and one that is created fresh each time you look at it. A
	 * quick relog is not an absence; a day is.
	 */
	@lombok.Getter
	@lombok.Setter
	private long minutesAway = -1;

	// ---------------------------------------------------------------- tallies

	/**
	 * How many of each thing has happened, ever, keyed by a short label.
	 *
	 * <p>Nothing signals that someone is paying attention like a tally. The
	 * follower knowing this is the fiftieth kalphite is a different kind of
	 * remark from anything it can say about one kill, and it costs a map.
	 *
	 * <p>Keyed by string so a new thing to count needs no new field - the
	 * caller decides the label, the same way rules decide what moves the mood.
	 *
	 * <p>These outlive the session, written back to the config by the plugin.
	 * A count that resets every login is not a memory, it is a scoreboard for
	 * the current game: "your fiftieth" means nothing if the fifty were all
	 * this afternoon, and everything if they were the fifty since you met.
	 */
	private final java.util.Map<String, Integer> tallies = new java.util.HashMap<>();

	/**
	 * The best of each thing seen, keyed the same way. Separate from the
	 * tallies because the operation is different: one accumulates, the other
	 * only ever moves up, and a rule wants to know the moment it moved.
	 */
	private final java.util.Map<String, Integer> records = new java.util.HashMap<>();

	/**
	 * Whether anything countable has moved since the last save.
	 *
	 * <p>The save is nine kilobytes of JSON at the cap and it used to happen
	 * every minute regardless. Most minutes nothing is counted at all: no kill,
	 * no level, no death, and the longest-session record only moves on a day
	 * that beats every previous one.
	 */
	@lombok.Getter
	private boolean countersDirty;

	/** Marks the saved blob as needing a write, for state set from outside. */
	public void markCountersDirty()
	{
		countersDirty = true;
	}

	public void clearCountersDirty()
	{
		countersDirty = false;
	}

	/** Counts one, and returns the new total. */
	public int tally(String what)
	{
		countersDirty = true;
		return tallies.merge(what, 1, Integer::sum);
	}

	public int getTally(String what)
	{
		return tallies.getOrDefault(what, 0);
	}

	/**
	 * The suffix marking a counter as belonging to THIS session.
	 *
	 * <p>They live in the same map as the lifetime ones so a rule can ask about
	 * either with the same condition - "your third death today" and "your
	 * hundredth ever" are the same question with a different key. They are
	 * dropped at login and never written out, which is what makes today mean
	 * today.
	 */
	public static final String TODAY = ":today";

	/** Counts one against both the lifetime total and today's. */
	public int tallyBoth(String what)
	{
		tally(what + TODAY);
		return tally(what);
	}

	/** Called at login: yesterday's session counters are not today's. */
	public void clearDailyTallies()
	{
		tallies.keySet().removeIf(key -> key.endsWith(TODAY));
	}

	/**
	 * Files a value against a record.
	 *
	 * @return whether this BEAT a record that already existed. The first value
	 * ever seen seeds the record silently and returns false on purpose: the
	 * first hit of a new install is not a personal best, it is the only
	 * measurement, and announcing it would make the feature look broken to
	 * every new user at once.
	 */
	public boolean noteRecord(String what, int value)
	{
		Integer previous = records.get(what);
		if (previous == null)
		{
			records.put(what, value);
			countersDirty = true;
			return false;
		}
		if (value <= previous)
		{
			// The overwhelmingly common case, minute after minute: today is not
			// the longest day. Nothing changed, so nothing needs writing.
			return false;
		}
		records.put(what, value);
		countersDirty = true;
		return true;
	}

	public int getRecord(String what)
	{
		return records.getOrDefault(what, 0);
	}

	/**
	 * How many times the follower has been started up with this player,
	 * this one included. Counted at login, so the first session is 1.
	 */
	@lombok.Getter
	private int sessionCount;

	public void setSessionCount(int sessionCount)
	{
		this.sessionCount = sessionCount;
		countersDirty = true;
	}

	/** The live tally map, for the plugin to write out. Not a copy: read-only by convention. */
	public java.util.Map<String, Integer> getTallies()
	{
		return tallies;
	}

	public java.util.Map<String, Integer> getRecords()
	{
		return records;
	}

	/**
	 * Puts back what a previous session counted. Merged rather than replaced so
	 * a restore arriving after something has already been counted - a kill in
	 * the first ticks after login - does not throw that away.
	 */
	public void restoreCounters(java.util.Map<String, Integer> savedTallies,
		java.util.Map<String, Integer> savedRecords)
	{
		if (savedTallies != null)
		{
			savedTallies.forEach((key, value) -> tallies.merge(key, value, Integer::sum));
		}
		if (savedRecords != null)
		{
			savedRecords.forEach((key, value) -> records.merge(key, value, Math::max));
		}
		// A restore merges rather than replaces, so what is now in memory is
		// not what is on disk - the next save has real work to do.
		countersDirty = true;
	}

	// -------------------------------------------------------------- wilderness

	/**
	 * Standing in the Wilderness, as a STATE - the crossing already has its
	 * occasion via the varbit event; this is what lets whole bark sets swap
	 * while we are in there (R18).
	 */
	private boolean inWilderness;

	private static final int WILDERNESS_VARBIT = 5963;

	public boolean isInWilderness()
	{
		return inWilderness;
	}

	// -------------------------------------------------------------- stay mode

	/**
	 * True while the follower is on a player-commanded Stay (R25) - not the
	 * stays its own machinery takes for errands, spectating or thrall work.
	 * Fed by the plugin each tick, because only the plugin can tell those
	 * apart. Stay is when the follower is most watched and least occupied,
	 * which is exactly where a little life pays best.
	 */
	private boolean followerStaying;

	public void setFollowerStaying(boolean staying)
	{
		followerStaying = staying;
	}

	public boolean isFollowerStaying()
	{
		return followerStaying;
	}

	// --------------------------------------------------------------- boundaries

	/**
	 * A few ticks of breather after something ENDS (R6): combat, a level, an
	 * arrival, a thieving session, the bank. The research is blunt about
	 * timing - a line in the middle of a task is an interruption, the same
	 * line just after the task ends is company - and this is the state that
	 * lets rules aim at the second one.
	 */
	private int boundaryTicksLeft;
	private String boundaryKind = "";

	/** How long an ending stays fresh enough to remark on: about six seconds. */
	private static final int BOUNDARY_TICKS = 10;

	public void noteBoundary(String kind)
	{
		boundaryKind = kind == null ? "" : kind;
		boundaryTicksLeft = BOUNDARY_TICKS;
	}

	public boolean isAtBoundary()
	{
		return boundaryTicksLeft > 0;
	}

	public String getBoundaryKind()
	{
		return boundaryKind;
	}

	// ---------------------------------------------------------------- line wear

	/**
	 * How many times each line has actually been SAID, across every session -
	 * the ledger behind retiring content the player has heard to death (R17).
	 *
	 * <p>Keyed by the template's hash in hex rather than its text, so the
	 * saved blob stays small: a collision merely shares one wear count
	 * between two lines, which costs a little freshness and shows nothing.
	 * An edited line hashes fresh, which is right - new words are new
	 * content, and they arrive unheard.
	 */
	private final java.util.Map<String, Integer> lineWear = new java.util.HashMap<>();

	/**
	 * Entries kept. The least-worn are dropped first: they are the farthest
	 * from ever standing a line aside, so forgetting them costs the least.
	 */
	private static final int MAX_WORN_LINES = 500;

	private static String wearKey(String template)
	{
		return Integer.toHexString(template.hashCode());
	}

	/**
	 * One more actual saying of this line - called at delivery, not at the win.
	 *
	 * <p>Deliberately NOT marking the counters dirty: something is said every
	 * minute or two, and wear alone would turn the every-hundred-ticks
	 * housekeeping write back on for good - the exact rewriting the dirty
	 * flag exists to stop. The ledger rides out with the next write anything
	 * else causes, and the orderly shutdown writes unconditionally; a crash
	 * costs one session's wear, which a statistical ledger can afford.
	 */
	public void noteLineSaid(String template)
	{
		if (template == null || template.isEmpty())
		{
			return;
		}
		lineWear.merge(wearKey(template), 1, Integer::sum);
		while (lineWear.size() > MAX_WORN_LINES)
		{
			String lightest = null;
			int least = Integer.MAX_VALUE;
			for (java.util.Map.Entry<String, Integer> entry : lineWear.entrySet())
			{
				if (entry.getValue() < least)
				{
					least = entry.getValue();
					lightest = entry.getKey();
				}
			}
			lineWear.remove(lightest);
		}
	}

	public int lineWear(String template)
	{
		return template == null || template.isEmpty()
			? 0 : lineWear.getOrDefault(wearKey(template), 0);
	}

	/** The live ledger, for the plugin to write out. Read-only by convention. */
	public java.util.Map<String, Integer> getLineWear()
	{
		return lineWear;
	}

	public void restoreLineWear(java.util.Map<String, Integer> saved)
	{
		if (saved != null)
		{
			saved.forEach((key, value) -> lineWear.merge(key, value, Integer::sum));
			countersDirty = true;
		}
	}

	// ------------------------------------------------------------ one-time lines

	/**
	 * Rules marked {@code once} that have already had their one time.
	 *
	 * <p>Kept here rather than on the rule for two reasons, and each one is a
	 * bug avoided. The rule file reloads whenever it changes on disk, throwing
	 * every rule object away and parsing fresh ones - a flag on the object
	 * would un-say the follower's introduction every time a phrase was edited.
	 * And this belongs with the tallies and the places anyway: what the
	 * follower has already told you is memory, and memory is kept in one place.
	 */
	private final java.util.Set<String> spokenOnce = new java.util.HashSet<>();

	public boolean hasSaidOnce(String ruleId)
	{
		return ruleId != null && spokenOnce.contains(ruleId);
	}

	public void noteSaidOnce(String ruleId)
	{
		if (ruleId != null && spokenOnce.add(ruleId))
		{
			countersDirty = true;
		}
	}

	/** Live set, for the plugin to write out. Read-only by convention. */
	public java.util.Set<String> getSpokenOnce()
	{
		return spokenOnce;
	}

	public void restoreSpokenOnce(java.util.Collection<String> saved)
	{
		if (saved != null)
		{
			spokenOnce.addAll(saved);
		}
	}

	// -------------------------------------------------------------- repeating

	/**
	 * How long the player has been doing the same thing, in ticks.
	 *
	 * <p>Repetition is the texture of the game, and a companion that never
	 * notices it is not watching. This needs to know nothing about trees or
	 * rocks or fish: an animation repeating for minutes IS the activity, so
	 * counting the ticks it has been running covers every skill at once,
	 * including ones added later.
	 *
	 * <p>Brief gaps are tolerated. Most gathering drops to no animation for a
	 * tick between swings, and treating that as stopping would keep the count
	 * at zero forever.
	 */
	private static final int REPEAT_GAP_GRACE_TICKS = 4;

	private int repeatingAnimation = -1;
	private int repeatingTicks;
	private int ticksSinceAnimation;

	private void refreshRepetition(Player local)
	{
		int animation = local.getAnimation();

		if (animation == -1)
		{
			// A pause, not necessarily a stop. Hold the count for a moment.
			if (repeatingAnimation != -1 && ++ticksSinceAnimation > REPEAT_GAP_GRACE_TICKS)
			{
				repeatingAnimation = -1;
				repeatingTicks = 0;
			}
			return;
		}

		ticksSinceAnimation = 0;
		if (animation == repeatingAnimation)
		{
			repeatingTicks++;
		}
		else
		{
			repeatingAnimation = animation;
			repeatingTicks = 1;
		}
	}

	/** The animation the player has been repeating, or -1. */
	public int getRepeatingAnimation()
	{
		return repeatingAnimation;
	}

	/** How many ticks that animation has been going, gaps included. */
	public int getRepeatingTicks()
	{
		return repeatingTicks;
	}

	// -------------------------------------------------------------- attention

	/**
	 * How many ticks the mouse has been resting on the follower.
	 *
	 * <p>Fed by the plugin, which already projects the clickbox every client
	 * tick to draw the hover hint, so knowing this costs nothing extra.
	 */
	@lombok.Getter
	@lombok.Setter
	private int hoverTicks;

	// ------------------------------------------------------------- incidents

	/**
	 * The last thing daft enough to be worth bringing up again.
	 *
	 * <p>The tallies count; this remembers. They are not the same faculty and
	 * the difference is most of what makes a companion feel like one. "Your
	 * four hundredth yew" is data delivered well. "Careful, I've seen what a
	 * chicken can do to you" is a shared history, and it only works because
	 * something specific happened and was kept.
	 *
	 * <p>One at a time on purpose. A follower with a filing cabinet of
	 * grievances is a different and much worse character than one with a
	 * favourite story.
	 */
	private String incidentKey = "";
	private String incidentPhrase = "";
	private int incidentCount;

	/**
	 * Files an incident, or counts another of the same.
	 *
	 * @param key   what happened, for a rule to recognise
	 * @param phrase how to refer to it out loud - "that chicken"
	 */
	public void noteIncident(String key, String phrase)
	{
		if (key == null || key.isEmpty())
		{
			return;
		}
		if (key.equals(incidentKey))
		{
			incidentCount++;
		}
		else
		{
			incidentKey = key;
			incidentPhrase = phrase == null ? "" : phrase;
			incidentCount = 1;
		}
		countersDirty = true;
		log.debug("Incident: {} ({}), now {}", key, incidentPhrase, incidentCount);
	}

	public boolean hasIncident()
	{
		return !incidentKey.isEmpty();
	}

	public String getIncidentKey()
	{
		return incidentKey;
	}

	/** How to say it out loud, for the {memory} placeholder. */
	public String getIncidentPhrase()
	{
		return incidentPhrase;
	}

	public int getIncidentCount()
	{
		return incidentCount;
	}

	/** Puts back the incident a previous session was still thinking about. */
	public void restoreIncident(String key, String phrase, int count)
	{
		if (key == null || key.isEmpty())
		{
			return;
		}
		incidentKey = key;
		incidentPhrase = phrase == null ? "" : phrase;
		incidentCount = Math.max(1, count);
	}

	// ---------------------------------------------------------------- traits

	/**
	 * Places this particular follower likes and dislikes, rolled once and then
	 * kept for good.
	 *
	 * <p>Taste is what makes a mood legible. A number that goes up and down for
	 * reasons the player cannot see is just weather; a follower that is always
	 * pleased to be back at the same place and always grumbles about the same
	 * swamp is one you can come to KNOW, and the mood stops being a mechanic
	 * and starts being a temperament.
	 *
	 * <p>Rolled per character rather than shipped as a list, so two people with
	 * this plugin do not have the same follower.
	 */
	private java.util.Set<Integer> likedRegions = java.util.Collections.emptySet();
	private java.util.Set<Integer> dislikedRegions = java.util.Collections.emptySet();

	public void setTraits(java.util.Set<Integer> liked, java.util.Set<Integer> disliked)
	{
		likedRegions = liked == null ? java.util.Collections.emptySet() : liked;
		dislikedRegions = disliked == null ? java.util.Collections.emptySet() : disliked;
	}

	public java.util.Set<Integer> getLikedRegions()
	{
		return likedRegions;
	}

	public java.util.Set<Integer> getDislikedRegions()
	{
		return dislikedRegions;
	}

	/**
	 * The ROLLED feeling about where it is standing, ignoring everything
	 * experience has since proved.
	 *
	 * <p>{@link #feelsAbout} answers with experience outranking the roll,
	 * which is right everywhere except the one moment that makes the
	 * temperament visible: when the two disagree. A rule cannot express "it
	 * rolled dislike but the evidence says otherwise" through feelsAbout,
	 * because the override has already swallowed the disagreement - and the
	 * disagreement is the character. Conceding the facts while keeping the
	 * feeling needs both halves readable.
	 */
	public boolean rolledFeeling(String how)
	{
		return "disliked".equalsIgnoreCase(how)
			? dislikedRegions.contains(regionId)
			: likedRegions.contains(regionId);
	}

	// ------------------------------------------------------- earned taste

	/**
	 * What each place has come to mean, learned rather than rolled.
	 *
	 * <p>The rolled sets above give the follower a taste before anything has
	 * happened to it, which is the only honest thing to do on the first login.
	 * After that they are the WEAKER claim: a place you died in twice should
	 * not stay a favourite because a shuffle said so on day one.
	 *
	 * <p>The signal costs nothing to author, because the rules already carry
	 * it. Every rule that knows a boss dying is worth +18 and a death is worth
	 * -25 is already saying how much the moment mattered; all this does is
	 * remember WHERE it happened. A new influence on how the follower feels
	 * about a place is a mood value on a rule, same as before.
	 */
	private final java.util.Map<Integer, Integer> placeScores = new java.util.HashMap<>();

	/** What the follower brings up about a place, keyed the same way. */
	private final java.util.Map<Integer, String> placeMemories = new java.util.HashMap<>();

	/**
	 * Places whose memory was filed on THIS visit, and so is not yet worth
	 * bringing up.
	 *
	 * <p>Found in a transcript: the follower set a personal best, filed the
	 * spot, and told the player about the spot five seconds later - "this is
	 * where you hit harder than you ever had", said to somebody still standing
	 * there. The whole value of a place memory is that it waits, and nothing
	 * made it wait. A region leaves this set when the player leaves the region,
	 * which is precisely what "come back to it" means.
	 */
	private final java.util.Set<Integer> placesJustFiled = new java.util.HashSet<>();

	/** Past this, an accumulation of small moments counts as an opinion. */
	public static final int OPINION_AT = 40;

	/**
	 * Bounded so an opinion can be strong and still turn around. Without a cap
	 * a region farmed for a week reaches a score no amount of later misery can
	 * move, and the follower is left insisting it loves somewhere you both now
	 * hate.
	 */
	private static final int OPINION_CAP = 150;

	/** How many places it can hold an opinion about, oldest-weakest evicted. */
	private static final int MAX_PLACES = 60;

	/**
	 * Records that something worth {@code delta} happened where we are standing.
	 *
	 * @param delta the same number the rule moves the mood by
	 */
	public void notePlaceFeeling(int delta)
	{
		if (delta == 0 || regionId == 0)
		{
			return;
		}
		int now = placeScores.getOrDefault(regionId, 0) + delta;
		placeScores.put(regionId, Math.max(-OPINION_CAP, Math.min(OPINION_CAP, now)));
		countersDirty = true;
		trimPlaces();
	}

	/** Records what happened here, for a rule to bring up next time. */
	public void notePlaceMemory(String phrase)
	{
		if (phrase == null || phrase.isEmpty() || regionId == 0)
		{
			return;
		}
		placeMemories.put(regionId, phrase);
		placesJustFiled.add(regionId);
		countersDirty = true;
		trimPlaces();
	}

	/**
	 * Drops the places it feels least strongly about once there are too many.
	 * A follower with an opinion about everywhere has an opinion about nowhere,
	 * and the saved blob has to stay a sensible size.
	 */
	private void trimPlaces()
	{
		while (placeScores.size() > MAX_PLACES)
		{
			Integer weakest = null;
			int least = Integer.MAX_VALUE;
			for (java.util.Map.Entry<Integer, Integer> entry : placeScores.entrySet())
			{
				int strength = Math.abs(entry.getValue());
				if (strength < least)
				{
					least = strength;
					weakest = entry.getKey();
				}
			}
			if (weakest == null)
			{
				return;
			}
			placeScores.remove(weakest);
			placeMemories.remove(weakest);
		}
		while (placeMemories.size() > MAX_PLACES)
		{
			placeMemories.remove(placeMemories.keySet().iterator().next());
		}
	}

	public int getPlaceScore()
	{
		return placeScores.getOrDefault(regionId, 0);
	}

	public java.util.Map<Integer, Integer> getPlaceScores()
	{
		return placeScores;
	}

	public java.util.Map<Integer, String> getPlaceMemories()
	{
		return placeMemories;
	}

	public void restorePlaces(java.util.Map<Integer, Integer> scores,
		java.util.Map<Integer, String> memories)
	{
		placeScores.clear();
		placeMemories.clear();
		if (scores != null)
		{
			placeScores.putAll(scores);
		}
		if (memories != null)
		{
			placeMemories.putAll(memories);
		}
	}

	/**
	 * Something the follower remembers about this place, or empty.
	 *
	 * <p>Empty while the memory is still fresh from this visit: a thing that
	 * happened a moment ago is not a thing the place reminds you of.
	 */
	public String getPlaceMemory()
	{
		if (placesJustFiled.contains(regionId))
		{
			return "";
		}
		String here = placeMemories.get(regionId);
		return here == null ? "" : here;
	}

	public boolean hasPlaceMemory()
	{
		return !getPlaceMemory().isEmpty();
	}

	/**
	 * One rolled like and one rolled dislike that experience can never
	 * override (R23): a place it is fond of for no reason it will give.
	 * Over-adaptation reads as inauthentic - a companion the record can
	 * always argue around has no opinions of its own - so these two hold
	 * whatever happens there. 0 means none is set.
	 */
	private int coreLikedRegion;
	private int coreDislikedRegion;

	public void setCoreTastes(int liked, int disliked)
	{
		coreLikedRegion = liked;
		coreDislikedRegion = disliked;
	}

	public int getCoreLikedRegion()
	{
		return coreLikedRegion;
	}

	public int getCoreDislikedRegion()
	{
		return coreDislikedRegion;
	}

	/**
	 * Whether the follower feels the named way about where it is standing.
	 *
	 * <p>Experience outranks the roll, and only in the direction experience
	 * points: a place it has come to dislike is not liked, whatever the shuffle
	 * said on the first login. Where nothing has happened yet, the roll still
	 * answers, so a new follower has a temperament from the start.
	 *
	 * <p>Except in the two core places, where the roll outranks everything:
	 * the follower keeps one fondness and one grudge the player cannot argue
	 * it out of, because that is what having a temperament means.
	 */
	public boolean feelsAbout(String how)
	{
		boolean askingDisliked = "disliked".equalsIgnoreCase(how);

		if (regionId != 0 && regionId == coreLikedRegion)
		{
			return !askingDisliked;
		}
		if (regionId != 0 && regionId == coreDislikedRegion)
		{
			return askingDisliked;
		}

		int earned = getPlaceScore();
		if (earned <= -OPINION_AT)
		{
			return askingDisliked;
		}
		if (earned >= OPINION_AT)
		{
			return !askingDisliked;
		}
		return askingDisliked
			? dislikedRegions.contains(regionId)
			: likedRegions.contains(regionId);
	}

	// ---------------------------------------------------------------- wishes

	/**
	 * A small thing the follower has said it could use - a feather, a bit of
	 * string - waiting for the player to "find" one via the Talk-to gift.
	 *
	 * <p>The want asks for somewhere; the wish asks for someTHING, and it
	 * exists because the first gift design failed in play: an unspecified
	 * gift reads as a null action, and giving with no wanting before it has
	 * no pull. The wish is the wanting. Everything downstream - the option
	 * label, the thank-you, the souvenir - names the specific thing, so the
	 * player always knows what they gave because the follower said what it
	 * wanted.
	 *
	 * <p>One at a time, like the want and for the same reason. Lapses
	 * silently at its deadline: a small hope that quietly expires needs no
	 * announcement.
	 */
	private String wishLabel = "";
	private int wishDeadlineTick;
	private java.util.Set<Integer> wishItems = java.util.Collections.emptySet();

	public void setWish(String label, int minutes)
	{
		setWish(label, minutes, null);
	}

	/**
	 * @param itemIds the real inventory items that grant this wish. The wish
	 * is fictional in that nothing is consumed, but it is honest in that the
	 * thing must actually be in the bag - play testing found the bluff
	 * immediately, claiming a pot of ink with empty pockets, and a follower
	 * that cannot tell is a follower that cannot see.
	 */
	public void setWish(String label, int minutes, java.util.List<Integer> itemIds)
	{
		if (isWishing() || label == null || label.isEmpty())
		{
			return;
		}
		wishLabel = label;
		wishItems = itemIds == null || itemIds.isEmpty()
			? java.util.Collections.emptySet()
			: new java.util.HashSet<>(itemIds);
		wishDeadlineTick = client.getTickCount() + Math.max(1, minutes) * 100;
		log.info("Wish opened: {} for {} minutes, granted by {}", label, minutes, wishItems);
	}

	/**
	 * Whether the wished-for thing is actually in the player's bag right now.
	 * A wish with no item list is grantable on word alone.
	 */
	public boolean isWishedItemInBag()
	{
		if (!isWishing())
		{
			return false;
		}
		if (wishItems.isEmpty())
		{
			return true;
		}
		net.runelite.api.ItemContainer inventory =
			client.getItemContainer(net.runelite.api.gameval.InventoryID.INV);
		if (inventory == null)
		{
			return false;
		}
		for (net.runelite.api.Item item : inventory.getItems())
		{
			if (item != null && wishItems.contains(item.getId()))
			{
				return true;
			}
		}
		return false;
	}

	public boolean isWishing()
	{
		return !wishLabel.isEmpty() && client.getTickCount() <= wishDeadlineTick;
	}

	/** The small thing currently hoped for, or empty. */
	public String getWishLabel()
	{
		return isWishing() ? wishLabel : "";
	}

	/** The wish came true (or is being abandoned); either way it is over. */
	public void clearWish()
	{
		wishLabel = "";
	}

	/**
	 * A wish that lapses unfulfilled rests the wishing for a while (the
	 * gentler half of the ignored-overtures back-off). Detected here because
	 * the lapse itself is lazy - {@link #isWishing} simply reads false past
	 * the deadline - and the gift path ({@link #clearWish}) empties the label
	 * before the deadline, so a granted wish never trips this.
	 */
	private void checkWishLapse()
	{
		if (!wishLabel.isEmpty() && client.getTickCount() > wishDeadlineTick)
		{
			wishLabel = "";
			wishItems = java.util.Collections.emptySet();
			wishBackoffUntilTick = client.getTickCount() + WISH_BACKOFF_TICKS;
			log.debug("Wish lapsed unfulfilled; wishing rests until tick {}",
				wishBackoffUntilTick);
		}
	}

	// ----------------------------------------------------------------- wants

	/**
	 * Somewhere the follower has asked to go, and how long it will keep hoping.
	 *
	 * <p>This is the only thing in here that the follower WANTS rather than
	 * notices. Everything else in this class is a reaction: something happened,
	 * and a rule gets to remark on it. A want runs the other way - the follower
	 * says what it would like, and then the player either does it or does not,
	 * which makes the player's next few minutes an answer to something. A thing
	 * with desires that can be satisfied reads as alive in a way no amount of
	 * commentary manages.
	 *
	 * <p>Deliberately one at a time. Two open wants would make going anywhere
	 * satisfy something, which is the same as satisfying nothing.
	 */
	public enum WantOutcome
	{
		FULFILLED,
		EXPIRED,
	}

	private boolean wantOpen;
	private int wantRegion = -1;
	private String wantLabel = "";
	private int wantDeadlineTick;
	private WantOutcome wantOutcome;

	/**
	 * Asks for somewhere. Ignored while a want is already open, so a rule that
	 * fires twice extends nothing and a second rule cannot quietly replace the
	 * first - the follower asked for one thing, and that is the thing.
	 */
	public void setWant(int region, String label, int minutes)
	{
		if (wantOpen)
		{
			return;
		}
		// Asking to be taken somewhere you are already standing, and then being
		// delighted about arriving, is not a companion with a wish - it is a
		// companion that cannot see out of the window. The check has to be here
		// rather than in the rule, because a rule has no way to say "anywhere
		// except where we are".
		if (region == regionId)
		{
			log.info("Want refused: asked for region {} but we are standing in it", region);
			return;
		}
		wantOpen = true;
		wantRegion = region;
		wantLabel = label == null ? "" : label;
		// A hundred ticks to the minute.
		wantDeadlineTick = client.getTickCount() + Math.max(1, minutes) * 100;

		// Logged at INFO rather than debug, and so are both endings. A want
		// happens at most once every twenty minutes, so this is three lines a
		// session - and when one does not land the way it should, the log is
		// the only place that can say whether it opened, what it was watching
		// for, and where the player actually was.
		log.info("Want opened: {} (region {}), {} minutes, from region {}",
			wantLabel, region, minutes, regionId);
	}

	public boolean isWanting()
	{
		return wantOpen;
	}

	/** Which region the open want is for, or -1. */
	public int getWantRegion()
	{
		return wantOpen ? wantRegion : -1;
	}

	/** Ticks left before the open want gives up, or 0. */
	public int getWantTicksLeft()
	{
		return wantOpen ? Math.max(0, wantDeadlineTick - client.getTickCount()) : 0;
	}

	/** The label of the current want, or of the one that just resolved. */
	public String getWantLabel()
	{
		return wantLabel;
	}

	/**
	 * Takes the outcome of a want that has just resolved, if any. Consumed by
	 * the engine once per tick and turned into an event, so a resolution is
	 * announced exactly once.
	 */
	public WantOutcome pollWant()
	{
		WantOutcome outcome = wantOutcome;
		wantOutcome = null;
		return outcome;
	}

	private void checkWant()
	{
		if (!wantOpen)
		{
			return;
		}
		if (regionId == wantRegion)
		{
			wantOpen = false;
			wantOutcome = WantOutcome.FULFILLED;
			log.info("Want fulfilled: {} (region {})", wantLabel, wantRegion);
			return;
		}
		if (client.getTickCount() >= wantDeadlineTick)
		{
			wantOpen = false;
			wantOutcome = WantOutcome.EXPIRED;
			log.info("Want expired: {} (region {}), never left region {}",
				wantLabel, wantRegion, regionId);
		}
	}

	// --------------------------------------------------------- the souvenir

	/**
	 * Something the follower picked up and is carrying about.
	 *
	 * <p>Nothing else in the plugin persists an OBJECT. Everything it has is a
	 * number, a mood or a place - and a companion holding a particular rock it
	 * found is a different kind of detail: it is the same rock an hour later,
	 * and then one day it is not.
	 */
	private String souvenir = "";
	private int souvenirDroppedTick;

	public void pickUp(String what, int minutes)
	{
		if (what == null || what.isEmpty() || !souvenir.isEmpty())
		{
			return;
		}
		souvenir = what;
		souvenirDroppedTick = client.getTickCount() + Math.max(1, minutes) * 100;
		log.debug("Picked up {} for {} minutes", what, minutes);
	}

	/**
	 * Puts this down and carries that instead, deliberately.
	 *
	 * <p>{@link #pickUp} refuses while carrying, and that guard is right for
	 * every accidental path - a souvenir rule firing while the pocket is full
	 * must not silently vanish something the follower has been talking about.
	 * The trade is the AUTHORED swap: the rule that calls it says the
	 * exchange out loud, which is the whole difference.
	 */
	public void tradeFor(String what, int minutes)
	{
		if (what == null || what.isEmpty())
		{
			return;
		}
		log.debug("Traded {} for {}", souvenir, what);
		souvenir = what;
		souvenirDroppedTick = client.getTickCount() + Math.max(1, minutes) * 100;
	}

	public boolean isCarrying()
	{
		return !souvenir.isEmpty();
	}

	/** What it is carrying, or what it just lost, for the {souvenir} placeholder. */
	public String getSouvenir()
	{
		return souvenir;
	}

	private boolean souvenirLost;

	/** Consumed once by the engine when the souvenir goes, like a want outcome. */
	public boolean pollSouvenirLost()
	{
		boolean lost = souvenirLost;
		souvenirLost = false;
		return lost;
	}

	private void checkSouvenir()
	{
		if (souvenir.isEmpty() || client.getTickCount() < souvenirDroppedTick)
		{
			return;
		}
		souvenirLost = true;
		log.debug("Lost the {}", souvenir);
		// The name survives the loss so the line can mourn it by name.
		souvenirDroppedTick = 0;
	}

	/** Called once the loss has been announced. */
	public void clearSouvenir()
	{
		souvenir = "";
	}

	// ---------------------------------------------------- how long we have known each other

	/**
	 * The day the follower first met this player, as an epoch day.
	 *
	 * <p>The session count already says a hundred logins. It cannot say a
	 * hundred DAYS, and those are different claims about a friendship: one is a
	 * number of visits, the other is a stretch of somebody's life. Only a date
	 * can tell you it has been a year, and only a date can notice that today is
	 * the anniversary of the first one.
	 */
	private long metOnDay;

	public void setMetOnDay(long epochDay)
	{
		metOnDay = epochDay;
	}

	public long getMetOnDay()
	{
		return metOnDay;
	}

	/** Days since the first meeting, or 0 if it has not been recorded yet. */
	public int getDaysKnown()
	{
		if (metOnDay <= 0)
		{
			return 0;
		}
		long days = java.time.LocalDate.now().toEpochDay() - metOnDay;
		return days < 0 ? 0 : (int) Math.min(days, Integer.MAX_VALUE);
	}

	/**
	 * Whether today is the same day of the year as the first meeting - and not
	 * the first meeting itself, which is not an anniversary of anything.
	 */
	public boolean isAnniversary()
	{
		if (metOnDay <= 0 || getDaysKnown() < 300)
		{
			return false;
		}
		java.time.LocalDate met = java.time.LocalDate.ofEpochDay(metOnDay);
		java.time.LocalDate today = java.time.LocalDate.now();
		return met.getMonthValue() == today.getMonthValue()
			&& met.getDayOfMonth() == today.getDayOfMonth();
	}

	/**
	 * What the player is wearing now, and what they were wearing the day the
	 * follower met them, both in gp.
	 *
	 * <p>Priced by the plugin, which has the item manager; kept here so a
	 * condition can compare them. The comparison is the whole point - a number
	 * on its own is a wealth tracker, and there are better ones. "You were in
	 * bronze when I met you" is only available to something that was there.
	 */
	private int wornValue;
	private int metWearingValue = -1;

	public void setWornValue(int value)
	{
		wornValue = value;
	}

	public int getWornValue()
	{
		return wornValue;
	}

	public void setMetWearingValue(int value)
	{
		metWearingValue = value;
	}

	public int getMetWearingValue()
	{
		return metWearingValue;
	}

	/**
	 * How many times better dressed the player is than the day they met,
	 * or 0 while there is nothing to compare against.
	 */
	public int getTimesBetterDressed()
	{
		if (metWearingValue <= 0 || wornValue <= 0)
		{
			return 0;
		}
		return wornValue / Math.max(1, metWearingValue);
	}

	// ------------------------------------------------------------ the nickname

	/**
	 * What the follower has taken to calling you, earned from whatever you do
	 * most.
	 *
	 * <p>It counts everything already; this is the one place it draws a
	 * conclusion from the counting. The name moves as your play moves, which
	 * makes it a mirror rather than a label - and being called the gravedigger
	 * for a fortnight is a fact about you that no line written in advance could
	 * have known.
	 */
	private final java.util.Map<String, String> nicknamesFor = new java.util.LinkedHashMap<>();

	/** Registered by the plugin from the rule file, so the names stay editable. */
	public void setNicknames(java.util.Map<String, String> byTally)
	{
		nicknamesFor.clear();
		if (byTally != null)
		{
			nicknamesFor.putAll(byTally);
		}
	}

	/** How much of a lead a tally needs before it earns you the name. */
	private static final int NICKNAME_AT = 25;

	public String getNickname()
	{
		String best = "";
		int most = NICKNAME_AT;
		for (java.util.Map.Entry<String, String> entry : nicknamesFor.entrySet())
		{
			int count = getTally(entry.getKey());
			if (count > most)
			{
				most = count;
				best = entry.getValue();
			}
		}
		return best;
	}

	public boolean hasNickname()
	{
		return !getNickname().isEmpty();
	}

	// -------------------------------------------------------- the challenge

	/**
	 * A wager on the PLAYER, against the clock.
	 *
	 * <p>The bet is about what the world will do - what the next drop is worth.
	 * This is about what you will do, which is the difference between a
	 * companion watching and a companion involved. It also gives the follower
	 * something to be wrong about that is your fault, which is funnier.
	 *
	 * <p>Measured against a tally it already keeps, so a challenge is a rule
	 * naming a counter and a number, not a scoring system of its own.
	 */
	public enum ChallengeOutcome
	{
		MET,
		FAILED,
	}

	private String challengeAbout = "";
	private String challengeTally = "";
	private int challengeTarget;
	private int challengeStartedAt;
	private int challengeDeadlineTick;
	private ChallengeOutcome challengeOutcome;

	public void setChallenge(String about, String tally, int target, int minutes)
	{
		if (tally == null || tally.isEmpty() || isChallenging())
		{
			return;
		}
		challengeAbout = about == null ? "" : about;
		challengeTally = tally;
		challengeTarget = Math.max(1, target);
		challengeStartedAt = getTally(tally);
		challengeDeadlineTick = client.getTickCount() + Math.max(1, minutes) * 100;
		log.debug("Challenge: {} of {} in {} minutes", target, tally, minutes);
	}

	public boolean isChallenging()
	{
		return challengeDeadlineTick > 0;
	}

	/** What the challenge was, for the {challenge} placeholder. */
	public String getChallengeAbout()
	{
		return challengeAbout;
	}

	/** How many are still needed, for a line that can count down. */
	public int getChallengeLeft()
	{
		if (!isChallenging())
		{
			return 0;
		}
		return Math.max(0, challengeTarget - (getTally(challengeTally) - challengeStartedAt));
	}

	private void checkChallenge()
	{
		if (!isChallenging())
		{
			return;
		}
		if (getTally(challengeTally) - challengeStartedAt >= challengeTarget)
		{
			challengeDeadlineTick = 0;
			challengeOutcome = ChallengeOutcome.MET;
			return;
		}
		if (client.getTickCount() >= challengeDeadlineTick)
		{
			challengeDeadlineTick = 0;
			challengeOutcome = ChallengeOutcome.FAILED;
		}
	}

	public ChallengeOutcome pollChallenge()
	{
		ChallengeOutcome outcome = challengeOutcome;
		challengeOutcome = null;
		return outcome;
	}

	// ------------------------------------------------------------- underfoot

	/**
	 * The player clicked the tile the follower happened to be standing on.
	 *
	 * <p>The one nuisance of a companion that nothing in here acknowledged. It
	 * keeps clear of fights and it walks behind you, and then every so often it
	 * is simply in the way, and a follower that never notices that is a follower
	 * you are managing rather than travelling with.
	 *
	 * <p>Consumed on read, because it is a moment rather than a state: the tile
	 * is walked to a second later and the fact stops being true.
	 */
	private boolean underfoot;

	public void noteUnderfoot()
	{
		underfoot = true;
	}

	public boolean pollUnderfoot()
	{
		boolean was = underfoot;
		underfoot = false;
		return was;
	}

	// ------------------------------------------------------- gone, or just still

	/**
	 * Whether the player has stopped touching the controls, as distinct from
	 * standing still on purpose.
	 *
	 * <p>{@code idle} cannot tell those apart: a player at a furnace and a
	 * player who has gone to make tea look identical to it, and the follower
	 * saying "still here, still standing" to an empty chair is only funny by
	 * accident. The camera is one tell; the feet and hands are the others -
	 * a player who just moved or animated is at the keyboard whatever the
	 * camera is doing, which matters because plenty of real play (and every
	 * simulation) runs minutes at a time on an untouched camera.
	 */
	private int cameraX = Integer.MIN_VALUE;
	private int cameraY;
	private int cameraPitch;
	private int stillTicks;

	/** Evidence of presence from outside the snapshot: a real event arrived. */
	public void noteAttention()
	{
		stillTicks = 0;
	}

	private void refreshAttention()
	{
		int x = client.getCameraX();
		int y = client.getCameraY();
		int pitch = client.getCameraPitch();
		if (cameraX == Integer.MIN_VALUE)
		{
			cameraX = x;
			cameraY = y;
			cameraPitch = pitch;
			return;
		}
		boolean cameraMoved = x != cameraX || y != cameraY || pitch != cameraPitch;
		if (cameraMoved)
		{
			cameraX = x;
			cameraY = y;
			cameraPitch = pitch;
		}
		// Runs after the idle update on purpose: idleTicks at zero means the
		// player moved or animated THIS tick, which is presence too.
		if (cameraMoved || idleTicks == 0)
		{
			stillTicks = 0;
			return;
		}
		if (stillTicks < Integer.MAX_VALUE)
		{
			stillTicks++;
		}
	}

	/** Ticks since the camera last moved. */
	public int getUnattendedTicks()
	{
		return stillTicks;
	}

	// ----------------------------------------------------------- the advice

	/**
	 * Whether the player did the thing the follower just told them to.
	 *
	 * <p>Everything else here runs one way: something happens, and a rule gets
	 * to remark on it. The follower shouts "eat something!" and then, however
	 * that turns out, never mentions it again - which is commentary rather than
	 * conversation, and after the fiftieth time it is obviously a recording.
	 *
	 * <p>What satisfies a piece of advice is named by the RULE that gives it,
	 * not decided here, so there is no vocabulary of blessed actions in the
	 * code to fall out of date against the rule file.
	 */
	public enum AdviceOutcome
	{
		HEEDED,
		IGNORED,
	}

	private String adviceAbout = "";
	private java.util.Set<Integer> adviceIds = java.util.Collections.emptySet();
	private boolean adviceWantsRoom;
	private int adviceFreeSlotsAtStart;
	private int adviceStartTick;
	private int adviceDeadlineTick;

	/**
	 * How long the player must take before making room counts as taking the
	 * advice.
	 *
	 * <p>Only the room kind needs this. Eating when told to eat is a discrete
	 * act that can be attributed however quickly it happens; a bag getting
	 * emptier is ambient, and in any gathering loop it was going to happen
	 * anyway. Without the delay the follower warned about the bag and thanked
	 * the player four seconds later, over and over - fifty-six lines of one
	 * three-hour session, all of it noise.
	 */
	private static final int ROOM_ADVICE_MIN_TICKS = 25;
	private AdviceOutcome adviceOutcome;

	/**
	 * @param ids animations that would settle it - eating, teleporting
	 * @param wantsRoom whether freeing an inventory slot settles it instead
	 */
	public void adviseOn(String about, java.util.Set<Integer> ids, boolean wantsRoom, int minutes)
	{
		if (about == null || about.isEmpty() || isAdvising())
		{
			return;
		}
		adviceAbout = about;
		adviceIds = ids == null ? java.util.Collections.emptySet() : ids;
		adviceWantsRoom = wantsRoom;
		adviceFreeSlotsAtStart = getFreeInventorySlots();
		adviceStartTick = client.getTickCount();
		adviceDeadlineTick = client.getTickCount() + Math.max(1, minutes) * 100;
		log.debug("Advised about {} for {} minutes", about, minutes);
	}

	public boolean isAdvising()
	{
		return adviceDeadlineTick > 0;
	}

	/** What the last piece of advice was about, for the {advice} placeholder. */
	public String getAdviceAbout()
	{
		return adviceAbout;
	}

	/** Offered every animation the player plays, while advice is outstanding. */
	public void offerAct(int animationId)
	{
		if (isAdvising() && adviceIds.contains(animationId))
		{
			settleAdvice(AdviceOutcome.HEEDED);
		}
	}

	private void settleAdvice(AdviceOutcome outcome)
	{
		adviceDeadlineTick = 0;
		adviceOutcome = outcome;
		log.debug("Advice about {} was {}", adviceAbout, outcome);
	}

	public AdviceOutcome pollAdvice()
	{
		AdviceOutcome outcome = adviceOutcome;
		adviceOutcome = null;
		return outcome;
	}

	private void checkAdvice()
	{
		if (!isAdvising())
		{
			return;
		}
		// Making room counts the moment the bag is emptier than it was, which
		// covers banking, dropping and eating the thing that was in the way.
		if (adviceWantsRoom && getFreeInventorySlots() > adviceFreeSlotsAtStart
			&& client.getTickCount() - adviceStartTick >= ROOM_ADVICE_MIN_TICKS)
		{
			settleAdvice(AdviceOutcome.HEEDED);
			return;
		}
		if (client.getTickCount() >= adviceDeadlineTick)
		{
			settleAdvice(AdviceOutcome.IGNORED);
		}
	}

	// -------------------------------------------------------------- the bet

	/**
	 * A prediction about the next thing to drop, and what it is worth.
	 *
	 * <p>A companion with an opinion about what happens next has a stake in it,
	 * which is a different thing from commentary. Being WRONG is the better
	 * half: anything that can only be right is not really predicting.
	 */
	public enum BetOutcome
	{
		WON,
		LOST,
	}

	private boolean betOpen;
	private boolean betOnRich;
	private int betThreshold;
	private int betDeadlineTick;
	private BetOutcome betOutcome;

	/**
	 * @param onRich whether the follower is betting the drop BEATS the
	 * threshold. Both directions exist so it can be pessimistic, which is
	 * funnier and, on most drops, correct.
	 */
	public void placeBet(boolean onRich, int threshold, int minutes)
	{
		if (betOpen)
		{
			return;
		}
		betOpen = true;
		betOnRich = onRich;
		betThreshold = threshold;
		betDeadlineTick = client.getTickCount() + Math.max(1, minutes) * 100;
	}

	public boolean isBetting()
	{
		return betOpen;
	}

	/** Called by the plugin when loot lands, while a bet is open. */
	public void settleBet(int lootValue)
	{
		if (!betOpen)
		{
			return;
		}
		betOpen = false;
		boolean rich = lootValue >= betThreshold;
		betOutcome = rich == betOnRich ? BetOutcome.WON : BetOutcome.LOST;
		log.debug("Bet {} on {}{}: loot was {}", betOutcome,
			betOnRich ? ">=" : "<", betThreshold, lootValue);
	}

	public BetOutcome pollBet()
	{
		BetOutcome outcome = betOutcome;
		betOutcome = null;
		return outcome;
	}

	private void checkBet()
	{
		// A bet nobody collected on. Quietly forgotten rather than counted as
		// a win, which would let it be right by saying nothing.
		if (betOpen && client.getTickCount() >= betDeadlineTick)
		{
			betOpen = false;
		}
	}

	// ----------------------------------------------------------- the clock

	/**
	 * The hour on the player's own wall, 0-23.
	 *
	 * <p>Nothing else in the game acknowledges the room the player is sitting
	 * in, which is exactly why a follower noticing it lands the way it does.
	 */
	public int getHourOfDay()
	{
		return java.time.LocalTime.now().getHour();
	}

	/**
	 * Today's date on the same wall, packed month*100+day so a range compare
	 * can wrap past new year the way timeOfDay wraps past midnight.
	 */
	public int getMonthDay()
	{
		java.time.LocalDate today = java.time.LocalDate.now();
		return today.getMonthValue() * 100 + today.getDayOfMonth();
	}

	/** Minutes this session has run, fed by the plugin's own timer. */
	@lombok.Getter
	@lombok.Setter
	private int sessionMinutes;

	// ----------------------------------------------------------- conversation

	/**
	 * How long the follower keeps hoping for an answer.
	 *
	 * <p>Two minutes. It was twelve seconds when the answer was a word typed
	 * into public chat, which is about how long typing "yes" takes. Answering
	 * now means walking over and right-clicking Talk-to, and a window sized for
	 * typing would have expired somewhere around the second click.
	 */
	private static final int ANSWER_WINDOW_TICKS = 200;

	private int ticksSinceQuestion = Integer.MAX_VALUE;

	/**
	 * The dialog tree that answers the open question, or empty.
	 *
	 * <p>This is what makes Talk-to mean something different for a minute or
	 * two: the follower asked, so the conversation it opens is the one about
	 * what it asked, and the everyday script waits its turn.
	 */
	private String askedTree = "";

	/** Called when a rule carrying {@code asks} speaks. */
	public void noteQuestion(String treeId)
	{
		ticksSinceQuestion = 0;
		askedTree = treeId == null ? "" : treeId;
	}

	/** Called once the player has answered, or declined to. */
	public void noteAnswered()
	{
		ticksSinceQuestion = Integer.MAX_VALUE;
		askedTree = "";
		// Engaging with a question clears the ignored ledger: the back-off
		// exists for a player who is not answering, not one who just did.
		ignoredAsks = 0;
		askBackoffUntilTick = 0;
	}

	public boolean isAwaitingAnswer()
	{
		return ticksSinceQuestion <= ANSWER_WINDOW_TICKS;
	}

	/** The tree Talk-to should open right now, or empty for the everyday one. */
	public String getAskedTree()
	{
		return isAwaitingAnswer() ? askedTree : "";
	}

	private void ageQuestion()
	{
		if (ticksSinceQuestion < Integer.MAX_VALUE)
		{
			ticksSinceQuestion++;
		}
		// The question just lapsed with nobody answering. That is a signal,
		// not a non-event: a transcript showed fifteen outings asked into one
		// AFK afternoon, each politely expiring and each politely re-asked at
		// the next cooldown, which added up to nagging. A hint dropped and
		// ignored earns a long pause; two of them end the asking for the day.
		if (ticksSinceQuestion == ANSWER_WINDOW_TICKS + 1 && !askedTree.isEmpty())
		{
			askedTree = "";
			ignoredAsks++;
			askBackoffUntilTick = client.getTickCount() + ASK_BACKOFF_TICKS;
			log.debug("Question ignored ({} this session); asks rest until tick {}",
				ignoredAsks, askBackoffUntilTick);
		}
	}

	// ------------------------------------------------------- ignored overtures

	/** Two hours before an ignored question may be followed by another. */
	private static final int ASK_BACKOFF_TICKS = 12_000;

	/** Ignored questions per session before the asking stops altogether. */
	private static final int MAX_IGNORED_ASKS = 2;

	/** Ninety minutes of not wishing after a wish lapses unfulfilled. */
	private static final int WISH_BACKOFF_TICKS = 9_000;

	private int ignoredAsks;
	private int askBackoffUntilTick;
	private int wishBackoffUntilTick;

	/**
	 * Whether rules that ASK something should hold their tongue: a question
	 * was ignored recently, or two have been ignored this session. Answering
	 * any question resets both.
	 */
	public boolean isAskBackedOff()
	{
		return ignoredAsks >= MAX_IGNORED_ASKS
			|| client.getTickCount() < askBackoffUntilTick;
	}

	/** Whether the wishing should rest, after a wish lapsed unfulfilled. */
	public boolean isWishBackedOff()
	{
		return client.getTickCount() < wishBackoffUntilTick;
	}

	// ------------------------------------------------------------------- mood

	/**
	 * How the follower is feeling, 0 (flat) to 100 (delighted), starting even.
	 *
	 * <p>One number rather than several axes, because the point is not to model
	 * an emotion - it is to give the lines already written a STATE to be said
	 * from. A rule that only fires when the follower is low turns the same
	 * event into a different moment depending on how the session has gone,
	 * which is most of what makes a companion feel like it is present rather
	 * than reacting.
	 *
	 * <p>Nothing here decides what moves it. Rules do, by carrying a {@code
	 * mood} nudge, which means every trigger the engine already understands can
	 * affect it and a new influence is an edit to phrases.json rather than to
	 * this file.
	 *
	 * <p>Session-scoped on purpose. A follower that remembered last night's bad
	 * run would be strange, and a fresh start each login is also the honest
	 * default for something that cannot see what you did while it was gone.
	 */
	private static final int MOOD_NEUTRAL = 50;
	private static final int MOOD_MIN = 0;
	private static final int MOOD_MAX = 100;

	/** Ticks between one point of drift back toward neutral: about 30 seconds. */
	private static final int MOOD_DRIFT_TICKS = 50;

	private int mood = MOOD_NEUTRAL;
	private int ticksSinceMoodDrift;

	/** The mood right now, 0..100. */
	public int getMood()
	{
		return mood;
	}

	/**
	 * Nudges the mood and clamps it. Called when a rule carrying a nudge fires.
	 *
	 * @return the mood after the nudge
	 */
	public int adjustMood(int delta)
	{
		int before = mood;
		mood = Math.max(MOOD_MIN, Math.min(MOOD_MAX, mood + delta));
		if (mood != before)
		{
			log.debug("mood {} -> {} ({}{})", before, mood, delta > 0 ? "+" : "", delta);
		}
		return mood;
	}

	/**
	 * The band the mood falls in, which is what rules should normally ask for -
	 * a name reads better in a rule file than a number, and the boundaries can
	 * move without every rule having to.
	 */
	public String getMoodBand()
	{
		if (mood <= 20)
		{
			return "low";
		}
		if (mood <= 40)
		{
			return "down";
		}
		if (mood < 60)
		{
			return "even";
		}
		if (mood < 80)
		{
			return "good";
		}
		return "high";
	}

	/** Every band name, so a rule naming one that does not exist can be caught. */
	public static java.util.Set<String> moodBands()
	{
		return new java.util.LinkedHashSet<>(
			java.util.Arrays.asList("low", "down", "even", "good", "high"));
	}

	/**
	 * Pulls the mood back toward neutral a point at a time, so nothing that
	 * happens is permanent and a bad stretch is recovered from by carrying on.
	 */
	private void driftMood()
	{
		if (mood == MOOD_NEUTRAL)
		{
			ticksSinceMoodDrift = 0;
			return;
		}
		if (++ticksSinceMoodDrift < MOOD_DRIFT_TICKS)
		{
			return;
		}
		ticksSinceMoodDrift = 0;
		mood += mood > MOOD_NEUTRAL ? -1 : 1;
	}

	// ----------------------------------------------------------------- memory

	/**
	 * How long a region has to go unvisited before coming back counts as a
	 * RETURN rather than a wander along its edge. Region boundaries run through
	 * the middle of towns, so without this a trip across Varrock square would
	 * tally half a dozen visits.
	 */
	private static final int REVISIT_GAP_TICKS = 250;

	/** Death-site lines stay quiet this long after the death itself, since the
	 * first person at the spot is the dying player. */
	private static final int DEATH_SPOT_ARM_TICKS = 200;

	private final java.util.Map<Integer, Integer> regionVisits = new java.util.HashMap<>();
	private final java.util.Map<Integer, Integer> regionLastSeenTick = new java.util.HashMap<>();

	private WorldPoint deathLocation;
	private int deathTick = -1;

	private void noteRegionEntered(int region)
	{
		Integer lastSeen = regionLastSeenTick.get(region);
		if (lastSeen == null || client.getTickCount() - lastSeen > REVISIT_GAP_TICKS)
		{
			regionVisits.merge(region, 1, Integer::sum);
		}
	}

	/** Session visits to the CURRENT region, for the returnVisit condition. */
	public int getRegionVisits()
	{
		return regionVisits.getOrDefault(regionId, 0);
	}

	/**
	 * Called by the plugin when the player dies.
	 *
	 * <p>This used to be session memory, on the reasoning that a companion
	 * remembering last week's death forever would wear thin. That was the
	 * wrong call: within a session the only time you are near the spot is the
	 * walk back for your gravestone, which is the one moment the line must NOT
	 * fire - hence the arming delay. Kept between sessions it becomes what it
	 * was always trying to be, which is an anniversary.
	 */
	public void noteDeath(WorldPoint where)
	{
		deathLocation = where;
		deathTick = client.getTickCount();
		countersDirty = true;
	}

	/** Where the player last died, for the plugin to write out. */
	public WorldPoint getDeathLocation()
	{
		return deathLocation;
	}

	/**
	 * Puts back a death from a previous session. The arming delay is spent:
	 * whenever it was, it was not this walk back.
	 */
	public void restoreDeathSpot(WorldPoint where)
	{
		deathLocation = where;
		deathTick = Integer.MIN_VALUE / 2;
	}

	/**
	 * Whether the player is standing near where they last died - and long
	 * enough after the death that being there again is a RETURN, not the
	 * dying itself or the walk back for the gravestone.
	 */
	public boolean isNearDeathSpot(int within)
	{
		return deathLocation != null && location != null
			&& client.getTickCount() - deathTick > DEATH_SPOT_ARM_TICKS
			&& location.getPlane() == deathLocation.getPlane()
			&& location.distanceTo(deathLocation) <= within;
	}

	/**
	 * Worn item ids taken from the player's composition. Note this covers only
	 * slots with a visible model: rings and ammo never appear here.
	 */
	/**
	 * Whether a refresh has actually seen the local player's composition yet.
	 * False for the first ticks after login, while the player entity is still
	 * materialising - state read before this is empty, not truth.
	 */
	@lombok.Getter
	private boolean playerReady;

	/** Run energy as a whole percentage, 0-100. */
	@lombok.Getter
	private int energyPercent = 100;

	@lombok.Getter
	private boolean skulled;

	/** The raw arrays behind the two sets, kept so an unchanged tick costs nothing. */
	private int[] lastRegionIds;
	private int[] lastEquipmentIds;

	/**
	 * The loaded map regions, rebuilt only when they actually change.
	 *
	 * <p>They change on a chunk load and are identical on every other tick, so
	 * boxing the array into a fresh set each time was allocating for no reason
	 * several times a second for the whole session.
	 */
	private void refreshLoadedRegions()
	{
		int[] regions = client.getTopLevelWorldView().getMapRegions();
		if (Arrays.equals(regions, lastRegionIds))
		{
			return;
		}
		lastRegionIds = regions == null ? null : regions.clone();

		Set<Integer> rebuilt = new HashSet<>();
		if (regions != null)
		{
			for (int region : regions)
			{
				rebuilt.add(region);
			}
		}
		loadedRegions = rebuilt;
	}

	private void refreshEquipment(PlayerComposition composition)
	{
		playerReady = composition != null;
		int[] ids = composition == null ? null : composition.getEquipmentIds();

		// Same reasoning as the regions: worn gear is the same array tick after
		// tick, and the old code rebuilt a set and compared it just to decide
		// whether to log.
		if (Arrays.equals(ids, lastEquipmentIds))
		{
			return;
		}
		lastEquipmentIds = ids == null ? null : ids.clone();

		Set<Integer> worn = new HashSet<>();
		if (ids != null)
		{
			for (int raw : ids)
			{
				// Items start at 2048; 256..2047 is the kit range. Using 512 here
				// meant every body kit was reported as a worn item, so an
				// equippedItem rule could fire on a hairstyle.
				if (raw >= PlayerComposition.ITEM_OFFSET)
				{
					worn.add(raw - PlayerComposition.ITEM_OFFSET);
				}
			}
		}
		equippedItems = worn;
		log.debug("equipment now {}", worn);
	}

	public Client getClient()
	{
		return client;
	}

	public int getHitpoints()
	{
		return hitpoints;
	}

	public int getMaxHitpoints()
	{
		return maxHitpoints;
	}

	public int getHitpointsPercent()
	{
		return maxHitpoints <= 0 ? 100 : (hitpoints * 100) / maxHitpoints;
	}

	public int getPrayerPoints()
	{
		return prayerPoints;
	}

	public int getMaxPrayerPoints()
	{
		return maxPrayerPoints;
	}

	public int getPrayerPercent()
	{
		return maxPrayerPoints <= 0 ? 100 : (prayerPoints * 100) / maxPrayerPoints;
	}

	public boolean isPrayerActive()
	{
		return ticksSincePrayerDrain <= PRAYER_DRAIN_MEMORY_TICKS;
	}

	public int getRegionId()
	{
		return regionId;
	}

	public int getPreviousRegionId()
	{
		return previousRegionId;
	}

	public int getIdleTicks()
	{
		return idleTicks;
	}

	public WorldPoint getLocation()
	{
		return location;
	}

	public boolean isRegionLoaded(int region)
	{
		return loadedRegions.contains(region);
	}

	/** Everything worn, by item id. Used to decide when repricing is needed. */
	public Set<Integer> getEquippedItems()
	{
		return equippedItems;
	}

	public boolean isEquipped(int itemId)
	{
		return equippedItems.contains(itemId);
	}

	public boolean isNpcNearby(java.util.function.Predicate<NPC> predicate, int within)
	{
		return isNpcNearby(predicate, within, false);
	}

	/**
	 * @param requireVisible the NPC must also have line of sight to the
	 * player. For rules whose line invites the player to LOOK at something:
	 * "that thing is very large and very close" pointing at a wall with a
	 * kalphite behind it is worse than silence, because a bad callout teaches
	 * the player to stop checking. Distance alone was the whole test before
	 * this, and a different plane was only excluded by accident of
	 * {@code distanceTo} returning MAX_VALUE across planes.
	 */
	public boolean isNpcNearby(java.util.function.Predicate<NPC> predicate, int within,
		boolean requireVisible)
	{
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc == null || !predicate.test(npc))
			{
				continue;
			}
			WorldPoint npcLocation = npc.getWorldLocation();
			if (location == null || npcLocation == null)
			{
				continue;
			}
			if (npcLocation.distanceTo(location) > within)
			{
				continue;
			}
			if (!requireVisible || canSee(npcLocation, npcSize(npc)))
			{
				return true;
			}
		}
		return false;
	}

	private static int npcSize(NPC npc)
	{
		return npc.getComposition() == null ? 1
			: Math.max(1, npc.getComposition().getSize());
	}

	/**
	 * Line of sight from an NPC's area to the player, by the game's own
	 * algorithm - {@link net.runelite.api.coords.WorldArea#hasLineOfSightTo}
	 * reads the scene's sight-blocking collision flags, which is exactly what
	 * the game consults to decide the same question.
	 *
	 * <p>The area is built from location and size rather than asked of the
	 * actor, and no collision data reads as visible: during loading there is
	 * nothing to consult, and refusing to speak about a boss because the map
	 * has not finished arriving would be the wrong kind of caution.
	 */
	private boolean canSee(WorldPoint from, int size)
	{
		net.runelite.api.WorldView wv = client.getTopLevelWorldView();
		if (wv == null || wv.getCollisionMaps() == null)
		{
			return true;
		}
		return new net.runelite.api.coords.WorldArea(from, size, size)
			.hasLineOfSightTo(wv, location);
	}

	/**
	 * How many other players are standing within {@code within} tiles.
	 *
	 * <p>Memoised per tick against the refresh generation, like the NPC scan:
	 * a busy bank holds a couple of hundred players and the answer cannot
	 * change between two conditions evaluated on the same tick.
	 */
	public int countPlayersNearby(int within)
	{
		if (crowdGeneration == refreshGeneration && crowdWithin == within)
		{
			return crowdCached;
		}
		crowdGeneration = refreshGeneration;
		crowdWithin = within;

		int found = 0;
		Player local = client.getLocalPlayer();
		if (location != null)
		{
			for (Player other : client.getTopLevelWorldView().players())
			{
				if (other == null || other == local)
				{
					continue;
				}
				WorldPoint where = other.getWorldLocation();
				if (where != null && where.distanceTo(location) <= within)
				{
					found++;
				}
			}
		}
		crowdCached = found;
		return found;
	}

	private int crowdGeneration = -1;
	private int crowdWithin = -1;
	private int crowdCached;

	/** An inventory holds twenty-eight things and always has. */
	private static final int INVENTORY_SIZE = 28;

	private int freeSlotsGeneration = -1;
	private int freeSlots = INVENTORY_SIZE;

	/**
	 * Empty inventory slots.
	 *
	 * <p>Counted by walking the container and counting what is IN it, rather
	 * than trusting {@code size()} or {@code count()}: one of those is the
	 * container's capacity and the other the number of items, and which is
	 * which is not worth betting a wrong warning on. Everything with an id
	 * above zero occupies a slot under either reading, so counting those and
	 * subtracting is right whichever way round it is.
	 *
	 * <p>Worked out on demand and memoised per tick, so a rule set with no
	 * inventory rule in it never pays for this at all.
	 */
	public int getFreeInventorySlots()
	{
		if (freeSlotsGeneration == refreshGeneration)
		{
			return freeSlots;
		}
		freeSlotsGeneration = refreshGeneration;

		net.runelite.api.ItemContainer inventory =
			client.getItemContainer(net.runelite.api.gameval.InventoryID.INV);
		if (inventory == null)
		{
			// Not loaded yet. Reporting a full inventory here would have the
			// follower warning about a bag it has not seen.
			freeSlots = INVENTORY_SIZE;
			return freeSlots;
		}

		int used = 0;
		for (net.runelite.api.Item item : inventory.getItems())
		{
			if (item != null && item.getId() > 0)
			{
				used++;
			}
		}
		freeSlots = Math.max(0, INVENTORY_SIZE - used);
		return freeSlots;
	}

	public String getPlayerName()
	{
		Player local = client.getLocalPlayer();
		return local == null || local.getName() == null ? "you" : local.getName();
	}
}

package com.follower.speech;

import java.util.HashMap;
import java.util.Map;

/**
 * One thing that happened, handed to {@link SpeechEngine}. A synthetic
 * {@link Type#TICK} event is raised every game tick so that purely state-based
 * rules (low HP, low prayer) get a chance to fire.
 */
public final class TriggerEvent
{
	public enum Type
	{
		TICK,
		NPC_SPAWN,
		NPC_DESPAWN,
		CHAT,
		VARBIT,
		ANIMATION,
		LEVEL_UP,
		REGION_CHANGE,
		LOGIN,
		DAMAGE_TAKEN,
		EQUIPMENT_CHANGE,
		THRALL_START,
		THRALL_SWITCH,
		THRALL_END,
		ERRAND_START,
		ERRAND_END,
		COMBAT_START,
		COMBAT_END,
		THIEVING_START,
		THIEVING_END,
		NPC_KILL,
		PLAYER_DEATH,
		LOOT,
		RECORD,
		EXAMINED,
		WANT_FULFILLED,
		WANT_EXPIRED,
		ANSWERED,
		SOUVENIR_LOST,
		BET_WON,
		BET_LOST,
		ADVICE_HEEDED,
		ADVICE_IGNORED,
		CHALLENGE_MET,
		CHALLENGE_FAILED,
		UNDERFOOT,
		MANUAL,
		WORLD_HOP,
		GAME_UPDATE,
		NOTES_EDITED,
		MUSIC_UNLOCK,
		COLLECTION_ADD,
		QUEST_COMPLETE,
		GE_OFFER,
		CHANNEL_JOIN,
		CHANNEL_LEAVE,
		NPC_SHOUT,
		TRACK_CHANGE,
		EXAMINED_THING,
		ATTENDED_AGAIN,
		MINUTES_TAKEN,
	}

	/**
	 * The PLAYER examined something - the reverse direction of
	 * {@link Type#EXAMINED}, which is somebody examining the follower.
	 * {target} names what was looked at.
	 */
	public static TriggerEvent examinedThing(String target)
	{
		TriggerEvent event = new TriggerEvent(Type.EXAMINED_THING);
		event.name = target == null ? "" : target;
		event.placeholders.put("target", event.name);
		return event;
	}

	/**
	 * The game's music changed to another track - the local song, as against
	 * {@link Type#MUSIC_UNLOCK}, which is hearing one for the first time ever.
	 */
	public static TriggerEvent trackChange(String track)
	{
		TriggerEvent event = new TriggerEvent(Type.TRACK_CHANGE);
		event.name = track == null ? "" : track;
		event.placeholders.put("track", event.name);
		return event;
	}

	/** A world hop landed. {world} is the number on the new door. */
	public static TriggerEvent worldHop(int world)
	{
		TriggerEvent event = new TriggerEvent(Type.WORLD_HOP);
		event.value = world;
		event.placeholders.put("world", Integer.toString(world));
		return event;
	}

	/** A music track just unlocked. {track} names it for the catalogue. */
	public static TriggerEvent musicUnlock(String track)
	{
		TriggerEvent event = new TriggerEvent(Type.MUSIC_UNLOCK);
		event.name = track == null ? "" : track;
		event.placeholders.put("track", event.name);
		return event;
	}

	/** The other ledger gained a line. {item} is what went in it. */
	public static TriggerEvent collectionAdd(String item)
	{
		TriggerEvent event = new TriggerEvent(Type.COLLECTION_ADD);
		event.name = item == null ? "" : item;
		event.placeholders.put("item", event.name);
		return event;
	}

	/** A quest reward scroll was handed over. {quest} names the quest. */
	public static TriggerEvent questComplete(String quest)
	{
		TriggerEvent event = new TriggerEvent(Type.QUEST_COMPLETE);
		event.name = quest == null ? "" : quest;
		event.placeholders.put("quest", event.name);
		return event;
	}

	/**
	 * A Grand Exchange offer finished. The name carries "bought" or "sold"
	 * for the condition's {@code is}; {item} and {value} land as placeholders
	 * so the line can read like a clerk's telegram rather than a receipt.
	 */
	public static TriggerEvent geOffer(boolean bought, String item, long spent)
	{
		TriggerEvent event = new TriggerEvent(Type.GE_OFFER);
		event.name = bought ? "bought" : "sold";
		event.placeholders.put("item", item == null ? "" : item);
		event.placeholders.put("value", formatGp(spent));
		return event;
	}

	/** Somebody arrived in or left the player's chat channel. {name} says who. */
	public static TriggerEvent channel(Type type, String who)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.name = who == null ? "" : who;
		event.placeholders.put("name", event.name);
		return event;
	}

	/**
	 * A named NPC said something overhead. The name matches like npcSpawn's,
	 * the message like chatMessage's, and both land as placeholders - NPC
	 * overheads never reach the chatbox, so no chat rule can see these.
	 */
	public static TriggerEvent npcShout(String npc, String message)
	{
		TriggerEvent event = new TriggerEvent(Type.NPC_SHOUT);
		event.name = npc == null ? "" : npc;
		event.message = message == null ? "" : message;
		event.placeholders.put("npc", event.name);
		event.placeholders.put("message", event.message);
		return event;
	}

	/** The thing it was carrying is gone. {souvenir} names it one last time. */
	public static TriggerEvent souvenirLost(String what)
	{
		TriggerEvent event = new TriggerEvent(Type.SOUVENIR_LOST);
		event.name = what == null ? "" : what;
		event.placeholders.put("souvenir", event.name);
		return event;
	}

	/** A challenge was met inside the window, or it was not. */
	public static TriggerEvent challenge(Type type, String about)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.name = about == null ? "" : about;
		event.placeholders.put("challenge", event.name);
		return event;
	}

	/** The player took the follower's advice, or let the window shut. */
	public static TriggerEvent advice(Type type, String about)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.name = about == null ? "" : about;
		event.placeholders.put("advice", event.name);
		return event;
	}

	/** A prediction came good, or did not. */
	public static TriggerEvent bet(Type type)
	{
		return new TriggerEvent(type);
	}

	/**
	 * The player answered a question, by picking a branch in the conversation
	 * the follower opened. {@code yes} or {@code no}, and never anything else -
	 * an option cannot be misheard the way a typed word could.
	 */
	public static TriggerEvent answered(String answer)
	{
		TriggerEvent event = new TriggerEvent(Type.ANSWERED);
		event.name = answer == null ? "" : answer;
		event.placeholders.put("answer", event.name);
		return event;
	}

	/** A want got its answer, one way or the other. {want} names what it was. */
	public static TriggerEvent want(Type type, String label)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.name = label == null ? "" : label;
		event.placeholders.put("want", event.name);
		return event;
	}

	/**
	 * A personal best was just beaten. {record} names it, {value} is the new
	 * mark and {previous} the one it replaced - which is what makes the line
	 * land, since a record without the old number is just a number.
	 */
	public static TriggerEvent record(String what, int value, int previous)
	{
		TriggerEvent event = new TriggerEvent(Type.RECORD);
		event.name = what == null ? "" : what;
		event.value = value;
		event.previousValue = previous;
		event.placeholders.put("record", event.name);
		event.placeholders.put("value", Integer.toString(value));
		event.placeholders.put("previous", Integer.toString(previous));
		return event;
	}

	/** The player has died. Where it happened lives in the context, not here. */
	public static TriggerEvent death()
	{
		return new TriggerEvent(Type.PLAYER_DEATH);
	}

	/**
	 * Loot arrived. {@code value} carries the total for {@code lootWorth}
	 * conditions; {item} and {value} land as placeholders so a line can name
	 * the prize without quoting a raw number.
	 */
	public static TriggerEvent loot(int totalValue, String bestItem)
	{
		TriggerEvent event = new TriggerEvent(Type.LOOT);
		event.value = totalValue;
		event.name = bestItem == null ? "" : bestItem;
		event.placeholders.put("item", event.name);
		event.placeholders.put("value", formatGp(totalValue));
		return event;
	}

	/** 1.2M / 214K / 950 - the way a player says an amount, not a ledger. */
	private static String formatGp(long value)
	{
		if (value >= 1_000_000)
		{
			return String.format("%.1fM", value / 1_000_000.0);
		}
		if (value >= 10_000)
		{
			return (value / 1_000) + "K";
		}
		return Long.toString(value);
	}

	/**
	 * A fight starting or ending, with what is being fought in {npc} so a line
	 * can name it.
	 */
	public static TriggerEvent combat(Type type, String npcName)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.name = npcName == null ? "" : npcName;
		event.placeholders.put("npc", event.name);
		return event;
	}

	/**
	 * Something the PLAYER killed. {@code value} carries the combat level, which
	 * is how {@code npcKill} tells a boss from a rat; the name lands in {npc}.
	 *
	 * <p>Only raised for kills the player had a hand in - see the hitsplat
	 * attribution in the plugin - so a follower does not applaud a guard losing
	 * a fight with a dog on the other side of the street.
	 */
	public static TriggerEvent kill(int npcId, String npcName, int combatLevel)
	{
		return kill(npcId, npcName, combatLevel, 0);
	}

	/**
	 * @param count how many of this NPC have been killed this session, which
	 * rides along so a rule can fire on the fiftieth and say which one it was
	 */
	public static TriggerEvent kill(int npcId, String npcName, int combatLevel, int count)
	{
		TriggerEvent event = npc(Type.NPC_KILL, npcId, npcName);
		event.value = combatLevel;
		event.count = count;
		event.placeholders.put("level", Integer.toString(combatLevel));
		event.placeholders.put("count", Integer.toString(count));
		return event;
	}

	/** Thrall-mode transitions; {@code style} lands in the {style} placeholder. */
	public static TriggerEvent thrall(Type type, String style)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.name = style == null ? "" : style;
		event.placeholders.put("style", event.name);
		return event;
	}

	/**
	 * A resummon while already possessed: {@code style} is the new thrall
	 * type, {@code from} the one being left behind.
	 */
	public static TriggerEvent thrallSwitch(String from, String style)
	{
		TriggerEvent event = thrall(Type.THRALL_SWITCH, style);
		event.placeholders.put("from", from == null ? "" : from);
		return event;
	}

	/** Errand transitions; the errand's name matches rule {@code names} lists. */
	public static TriggerEvent errand(Type type, String errand)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.name = errand == null ? "" : errand;
		event.placeholders.put("errand", event.name);
		return event;
	}

	private final Type type;
	private final Map<String, String> placeholders = new HashMap<>();

	/** Generic payload; meaning depends on {@link #type}. */
	private String name = "";
	private int id = -1;
	private int value;

	/** How many times this has happened before, where the raiser counts. */
	private int count;
	private int previousValue;
	private String message = "";
	private int chatTypeId = -1;

	private TriggerEvent(Type type)
	{
		this.type = type;
	}

	public static TriggerEvent tick()
	{
		return new TriggerEvent(Type.TICK);
	}

	public static TriggerEvent npc(Type type, int npcId, String npcName)
	{
		TriggerEvent event = new TriggerEvent(type);
		event.id = npcId;
		event.name = npcName == null ? "" : npcName;
		event.placeholders.put("npc", event.name);
		event.placeholders.put("npcId", Integer.toString(npcId));
		return event;
	}

	/**
	 * Something was said. The sender rides along in {@link #getName()} so a rule
	 * can tell the player's own line from the rest of the street - which is the
	 * difference between a follower that answers you and one that answers
	 * everybody.
	 */
	public static TriggerEvent chat(String message, int chatTypeId, String sender)
	{
		TriggerEvent event = new TriggerEvent(Type.CHAT);
		event.message = message == null ? "" : message;
		event.chatTypeId = chatTypeId;
		event.name = sender == null ? "" : sender;
		event.placeholders.put("message", event.message);
		event.placeholders.put("speaker", event.name);
		return event;
	}

	public static TriggerEvent varbit(int varbitId, int newValue, int oldValue)
	{
		TriggerEvent event = new TriggerEvent(Type.VARBIT);
		event.id = varbitId;
		event.value = newValue;
		event.previousValue = oldValue;
		event.placeholders.put("value", Integer.toString(newValue));
		return event;
	}

	public static TriggerEvent animation(int animationId)
	{
		TriggerEvent event = new TriggerEvent(Type.ANIMATION);
		event.id = animationId;
		return event;
	}

	public static TriggerEvent levelUp(String skill, int level)
	{
		TriggerEvent event = new TriggerEvent(Type.LEVEL_UP);
		event.name = skill == null ? "" : skill;
		event.value = level;
		event.placeholders.put("skill", event.name);
		event.placeholders.put("level", Integer.toString(level));
		return event;
	}

	public static TriggerEvent regionChange(int newRegion, int oldRegion)
	{
		TriggerEvent event = new TriggerEvent(Type.REGION_CHANGE);
		event.id = newRegion;
		event.value = newRegion;
		event.previousValue = oldRegion;
		event.placeholders.put("region", Integer.toString(newRegion));
		return event;
	}

	public static TriggerEvent damageTaken(int amount)
	{
		TriggerEvent event = new TriggerEvent(Type.DAMAGE_TAKEN);
		event.value = amount;
		event.placeholders.put("damage", Integer.toString(amount));
		return event;
	}

	public static TriggerEvent simple(Type type)
	{
		return new TriggerEvent(type);
	}

	public Type getType()
	{
		return type;
	}

	public String getName()
	{
		return name;
	}

	public int getId()
	{
		return id;
	}

	public int getValue()
	{
		return value;
	}

	public int getCount()
	{
		return count;
	}

	public int getPreviousValue()
	{
		return previousValue;
	}

	public String getMessage()
	{
		return message;
	}

	public int getChatTypeId()
	{
		return chatTypeId;
	}

	public Map<String, String> getPlaceholders()
	{
		return placeholders;
	}
}

package com.follower.ui;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Model;

/**
 * Renders a model to an image, in software.
 *
 * <p>Chathead widgets can only show models the cache already holds - a widget
 * takes a model ID, and there is no way to hand it a composed one - so the
 * follower's own head is unreachable through the game's dialog interface. It is
 * reachable this way: the model exposes its vertices, faces and already-lit face
 * colours, so projecting and filling the triangles here produces a real picture
 * of the actual follower rather than a stand-in.
 *
 * <p>Uses the client's own widget-model camera - perspective, orbited to the
 * dialog's pitch at its zoom - with painter's-algorithm depth sorting, and fills
 * triangles through {@link GouraudRasterizer}, a verbatim port of the client's
 * integer scanline rasterizer, so the pixels come out the way the game's own
 * renderer produces them - down to which pixels a two-pixel pupil covers. */
@lombok.extern.slf4j.Slf4j
public final class ChatheadRenderer
{
	private ChatheadRenderer()
	{
	}

	/**
	 * The client's own chathead camera, read off live dialog widgets.
	 *
	 * <p>The head's angle arrives as the widget's rotationZ, but it drives THIS
	 * renderer's yaw: RuneLite's rotationZ is the axis that turns a chathead in
	 * the client's widget pipeline. NPC dialogs use 1882 and player dialogs 166 -
	 * exact mirrors (1882 = 2048 - 166), which is why an NPC and your own
	 * character face opposite ways. Applying it as a true Z-roll instead tilts the
	 * head sideways in the image plane, which is visibly wrong.
	 */
	public static final int GAME_YAW = 0;
	public static final int GAME_PITCH = 40;
	public static final int GAME_TURN_NPC = 1882;
	public static final int GAME_TURN_PLAYER = 166;
	public static final int GAME_ZOOM = 796;

	/** The client's projection: screen = model * 512 / depth. */
	private static final double FOCAL_LENGTH = 512;

	/** One-line shading census per render, cheap enough to leave on. */
	private static final boolean LOG_SHADING = false;

	/** Convenience overload: bounds come from the model itself, game camera. */
	public static BufferedImage render(Model model, int width, int height,
		int yaw, double headFraction)
	{
		return render(model, null, width, height, yaw, GAME_PITCH, GAME_ZOOM, headFraction);
	}

	/**
	 * @param model        the (possibly posed) model to draw
	 * @param boundsFrom   model to compute framing from, or null to use
	 *                     {@code model}. An animated head is framed by its UNPOSED
	 *                     base so the picture doesn't rescale as the jaw moves.
	 * @param yaw          model rotation about the vertical axis, in JAU - the
	 *                     widget's rotationY
	 * @param cameraPitch  the widget's rotationX. NOT a model tilt: the client
	 *                     orbits the CAMERA to this pitch at {@code zoom} distance
	 * @param zoom         camera distance, the widget's modelZoom
	 * @param headFraction share of the model's height, from the top, to include;
	 *                     1.0 draws the whole model (a real chathead model)
	 * @return the rendered image, or null if the model cannot be drawn
	 */
	public static BufferedImage render(Model model, Model boundsFrom, int width, int height,
		int yaw, int cameraPitch, int zoom, double headFraction)
	{
		return render(model, boundsFrom, width, height, yaw, cameraPitch, zoom,
			headFraction, -1, -1);
	}

	/**
	 * @param anchorX pixel where the model's ORIGIN projects, or -1 for centre.
	 *                The client anchors widget models at the widget's centre and
	 *                lets geometry overflow, clipped by the interface surface -
	 *                which is how tall hair gets cut at the dialog's top edge.
	 */
	public static BufferedImage render(Model model, Model boundsFrom, int width, int height,
		int yaw, int cameraPitch, int zoom, double headFraction, int anchorX, int anchorY)
	{
		if (model == null || width <= 0 || height <= 0)
		{
			return null;
		}
		Model frame = boundsFrom == null ? model : boundsFrom;

		float[] vx = model.getVerticesX();
		float[] vy = model.getVerticesY();
		float[] vz = model.getVerticesZ();
		float[] fx = frame.getVerticesX();
		float[] fy = frame.getVerticesY();
		int[] fa = model.getFaceIndices1();
		int[] fb = model.getFaceIndices2();
		int[] fc = model.getFaceIndices3();
		int[] colors = model.getFaceColors1();
		int[] hidden = model.getFaceColors3();

		if (vx == null || vy == null || vz == null || fx == null || fy == null
			|| fa == null || fb == null || fc == null || colors == null)
		{
			return null;
		}

		int verts = Math.min(model.getVerticesCount(), vx.length);
		if (Math.min(frame.getVerticesCount(), fx.length) != verts)
		{
			// A frame reference must be the same geometry (the unposed original).
			return null;
		}

		// The client's exact widget-model camera, from its drawInterface:
		//     eyeY = sin(rotationX) * zoom;  eyeZ = cos(rotationX) * zoom
		//     objRender(0, rotationY, 0, rotationX, 0, eyeY, eyeZ)
		// So the model is yawed, pushed out to `zoom`, and viewed by a camera
		// ORBITED to pitch rotationX - with a perspective divide. Approximating
		// that as a model-space tilt with an orthographic projection is what made
		// the framing need a fudged yaw to look right.
		double yawAngle = yaw / 2048.0 * 2.0 * Math.PI;
		double yawSin = Math.sin(yawAngle);
		double yawCos = Math.cos(yawAngle);
		double pitchAngle = cameraPitch / 2048.0 * 2.0 * Math.PI;
		double pitchSin = Math.sin(pitchAngle);
		double pitchCos = Math.cos(pitchAngle);
		double eyeY = pitchSin * zoom;
		double eyeZ = pitchCos * zoom;

		float[] rx = new float[verts];
		float[] ry = new float[verts];
		float[] rz = new float[verts];

		for (int i = 0; i < verts; i++)
		{
			double[] p = project(vx[i], vy[i], vz[i], yawSin, yawCos, pitchSin, pitchCos, eyeY, eyeZ);
			rx[i] = (float) p[0];
			ry[i] = (float) p[1];
			rz[i] = (float) p[2];
		}

		float minY = Float.MAX_VALUE;
		float maxY = -Float.MAX_VALUE;
		for (int i = 0; i < verts; i++)
		{
			minY = Math.min(minY, fy[i]);
			maxY = Math.max(maxY, fy[i]);
		}
		float cutoff = minY + (maxY - minY) * (float) headFraction;

		// Faces wholly inside the head region OF THE FRAME model, skipping ones
		// the client hides. Using the frame keeps face selection stable across
		// animation frames.
		List<Integer> keep = new ArrayList<>();
		for (int i = 0; i < fa.length; i++)
		{
			if (hidden != null && i < hidden.length && hidden[i] == -2)
			{
				continue;
			}
			int a = fa[i];
			int b = fb[i];
			int c = fc[i];
			if (a >= verts || b >= verts || c >= verts || a < 0 || b < 0 || c < 0)
			{
				continue;
			}
			if (fy[a] <= cutoff && fy[b] <= cutoff && fy[c] <= cutoff)
			{
				keep.add(i);
			}
		}
		if (keep.isEmpty())
		{
			return null;
		}

		// The client's own projection scale, not a fit-to-box. Widget models are
		// drawn at a fixed focal length about the model's ORIGIN, and they
		// overflow their widget rectangle freely - the real chathead widget is
		// 32x32 while the head it draws is far bigger. Fitting to a box instead
		// made size a guess; this makes it a consequence of zoom, exactly as in
		// game.
		int offsetX = anchorX < 0 ? width / 2 : anchorX;
		int offsetY = anchorY < 0 ? height / 2 : anchorY;

		// Screen coordinates the client's way: vertexScreenX = centerX +
		// (x << 9) / z, truncated to an INTEGER per vertex before any face is
		// drawn. The rasterizer walks scanlines between these ints; feeding it
		// float pixel centres instead is what dropped the sub-pixel eye faces.
		int[] sx = new int[verts];
		int[] sy = new int[verts];
		int[] sz = new int[verts];
		// vertexScreenZ, the client's convention: camera depth relative to the
		// model origin's depth (midZ), an INTEGER per vertex.
		double midZ = eyeY * pitchSin + eyeZ * pitchCos;
		for (int i = 0; i < verts; i++)
		{
			sx[i] = offsetX + (int) (rx[i] * FOCAL_LENGTH);
			sy[i] = offsetY + (int) (ry[i] * FOCAL_LENGTH);
			sz[i] = (int) (rz[i] - midZ);
		}

		// The client's calculateBoundsCylinder, for the depth-bucket range.
		double boundMaxY = 0;
		double boundMinY = 0;
		double radiusSqr = 0;
		for (int i = 0; i < verts; i++)
		{
			if (-vy[i] > boundMaxY)
			{
				boundMaxY = -vy[i];
			}
			if (vy[i] > boundMinY)
			{
				boundMinY = vy[i];
			}
			double r = vx[i] * vx[i] + vz[i] * vz[i];
			if (r > radiusSqr)
			{
				radiusSqr = r;
			}
		}
		int radius = (int) (Math.sqrt(radiusSqr) + 0.99);
		int minDepth = (int) (Math.sqrt(radius * radius + boundMaxY * boundMaxY) + 0.99);
		int maxDepth = minDepth + (int) (Math.sqrt(radius * radius + boundMinY * boundMinY) + 0.99);

		// Gouraud shading, the way the game itself draws models: each face carries
		// three per-corner lit colours (faceColors1/2/3), blended across the
		// triangle. Flat-filling with colours1 alone is what made every triangle
		// edge visible and the lighting angular. No antialiasing either - the
		// game's rasterizer has none, and crisp edges are part of the look.
		int[] colors2 = model.getFaceColors2();
		int[] colors3 = model.getFaceColors3();

		// Faces flagged -1 in colours3 are FLAT shaded - one colour across the
		// whole triangle - and no amount of interpolation smooths those. If a head
		// renders faceted, this ratio says whether the model is authored that way
		// or the blending is at fault.
		if (LOG_SHADING)
		{
			int flatFaces = 0;
			for (int face : keep)
			{
				if (colors3 == null || colors3[face] == -1)
				{
					flatFaces++;
				}
			}
			log.info("chathead: {} faces drawn, {} flat-shaded, {} gouraud",
				keep.size(), flatFaces, keep.size() - flatFaces);
		}

		// The client's draw2 ordering, not a painter's sort. Faces go into
		// INTEGER average-depth buckets ((zA+zB+zC)/3 + minDepth) in face-index
		// order, and buckets are emitted far to near with insertion order kept
		// inside each bucket. Model authors rely on that: a pupil sits coplanar
		// ON the eye-white face and is authored LATER in face order so the same
		// bucket draws it on top. Sorting by exact float depth instead let the
		// eye-white face land on top of the pupil on some animation frames -
		// the stray white pixels in the eyes.
		//
		// Backface culling happens here, before bucketing, with the client's own
		// test on the same INTEGER screen coordinates it rasterises with. Without
		// it the BACK of the head - lit from behind, darker - bled through along
		// cheeks and brow as triangular patches.
		int[] bucketCount = new int[maxDepth + 1];
		int[][] buckets = new int[maxDepth + 1][];
		for (int face : keep)
		{
			int a = fa[face];
			int b = fb[face];
			int c = fc[face];
			if (rz[a] < 0 || rz[b] < 0 || rz[c] < 0)
			{
				continue;
			}
			if ((sx[a] - sx[b]) * (sy[c] - sy[b]) - (sy[a] - sy[b]) * (sx[c] - sx[b]) <= 0)
			{
				continue;
			}

			int depthAverage = (sz[a] + sz[b] + sz[c]) / 3 + minDepth;
			if (depthAverage < 0)
			{
				depthAverage = 0;
			}
			else if (depthAverage > maxDepth)
			{
				depthAverage = maxDepth;
			}
			if (buckets[depthAverage] == null)
			{
				buckets[depthAverage] = new int[8];
			}
			else if (bucketCount[depthAverage] == buckets[depthAverage].length)
			{
				int[] grown = new int[buckets[depthAverage].length * 2];
				System.arraycopy(buckets[depthAverage], 0, grown, 0, bucketCount[depthAverage]);
				buckets[depthAverage] = grown;
			}
			buckets[depthAverage][bucketCount[depthAverage]++] = face;
		}

		int[] drawOrder = resolveDrawOrder(model.getFaceRenderPriorities(),
			buckets, bucketCount, maxDepth, fa.length);

		int[] pixels = new int[width * height];
		GouraudRasterizer raster = new GouraudRasterizer(pixels, width, height);

		for (int face : drawOrder)
		{
			int a = fa[face];
			int b = fb[face];
			int c = fc[face];

			// colours3 == -1 flags a flat-shaded face: all corners take colours1.
			// Corners stay PACKED - the client interpolates the palette index
			// across the triangle and looks the table up per pixel, and matching
			// its colours means doing the same. Corner colours pair with vertices
			// A/B/C directly, exactly as the client's drawFace passes them.
			boolean flat = colors3 == null || colors3[face] == -1;
			int colourA = colors[face] & 0xFFFF;
			int colourB = flat || colors2 == null ? colourA : colors2[face] & 0xFFFF;
			int colourC = flat ? colourA : colors3[face] & 0xFFFF;

			raster.gouraudTriangle(sx[a], sx[b], sx[c], sy[a], sy[b], sy[c],
				colourA, colourB, colourC);
		}

		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(0, 0, width, height, pixels, 0, width);
		return image;
	}

	/**
	 * The client's draw2 emission order, ported line for line. Without per-face
	 * render priorities: buckets far to near, insertion order within each. With
	 * priorities: the client's 12-class algorithm - faces collect into priority
	 * classes in depth order, classes 0..9 emit in class order, and the special
	 * classes 10 and 11 interleave into the stream whenever their next face is
	 * deeper than the running depth averages of classes 1+2 (checked before
	 * class 0), 3+4 (before class 3), and 6+8 (before class 5), with the
	 * leftovers emitted at the end. Player and NPC models rely on this to
	 * layer coplanar detail correctly.
	 */
	private static int[] resolveDrawOrder(byte[] priorities,
		int[][] buckets, int[] bucketCount, int maxDepth, int faceTotal)
	{
		int[] order = new int[faceTotal];
		int emitted = 0;

		if (priorities == null)
		{
			for (int depth = maxDepth; depth >= 0; depth--)
			{
				int count = bucketCount[depth];
				for (int i = 0; i < count; i++)
				{
					order[emitted++] = buckets[depth][i];
				}
			}
			return java.util.Arrays.copyOf(order, emitted);
		}

		int[] priorityFaceCounts = new int[12];
		int[][] priorityFaceLists = new int[12][faceTotal];
		int[] priorityDepthSum = new int[12];
		int[] priority10FaceDepth = new int[faceTotal];
		int[] priority11FaceDepth = new int[faceTotal];

		for (int depth = maxDepth; depth >= 0; depth--)
		{
			int faceCount = bucketCount[depth];
			for (int i = 0; i < faceCount; i++)
			{
				int face = buckets[depth][i];
				int priorityClass = Math.max(0, Math.min(11, priorities[face]));
				int classCount = priorityFaceCounts[priorityClass]++;
				priorityFaceLists[priorityClass][classCount] = face;
				if (priorityClass < 10)
				{
					priorityDepthSum[priorityClass] += depth;
				}
				else if (priorityClass == 10)
				{
					priority10FaceDepth[classCount] = depth;
				}
				else
				{
					priority11FaceDepth[classCount] = depth;
				}
			}
		}

		int averagePriorityDepthSum1_2 = 0;
		if (priorityFaceCounts[1] > 0 || priorityFaceCounts[2] > 0)
		{
			averagePriorityDepthSum1_2 = (priorityDepthSum[1] + priorityDepthSum[2])
				/ (priorityFaceCounts[1] + priorityFaceCounts[2]);
		}

		int averagePriorityDepthSum3_4 = 0;
		if (priorityFaceCounts[3] > 0 || priorityFaceCounts[4] > 0)
		{
			averagePriorityDepthSum3_4 = (priorityDepthSum[3] + priorityDepthSum[4])
				/ (priorityFaceCounts[3] + priorityFaceCounts[4]);
		}

		int averagePriorityDepthSum6_8 = 0;
		if (priorityFaceCounts[6] > 0 || priorityFaceCounts[8] > 0)
		{
			averagePriorityDepthSum6_8 = (priorityDepthSum[6] + priorityDepthSum[8])
				/ (priorityFaceCounts[6] + priorityFaceCounts[8]);
		}

		int priorityFace = 0;
		int priorityFaceCount = priorityFaceCounts[10];
		int[] priorityFaces = priorityFaceLists[10];
		int[] priorityFaceDepths = priority10FaceDepth;
		if (priorityFace == priorityFaceCount)
		{
			priorityFace = 0;
			priorityFaceCount = priorityFaceCounts[11];
			priorityFaces = priorityFaceLists[11];
			priorityFaceDepths = priority11FaceDepth;
		}

		int priorityDepth;
		if (priorityFace < priorityFaceCount)
		{
			priorityDepth = priorityFaceDepths[priorityFace];
		}
		else
		{
			priorityDepth = -1000;
		}

		for (int priority = 0; priority < 10; priority++)
		{
			while (priority == 0 && priorityDepth > averagePriorityDepthSum1_2)
			{
				order[emitted++] = priorityFaces[priorityFace++];
				if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
				{
					priorityFace = 0;
					priorityFaceCount = priorityFaceCounts[11];
					priorityFaces = priorityFaceLists[11];
					priorityFaceDepths = priority11FaceDepth;
				}
				if (priorityFace < priorityFaceCount)
				{
					priorityDepth = priorityFaceDepths[priorityFace];
				}
				else
				{
					priorityDepth = -1000;
				}
			}

			while (priority == 3 && priorityDepth > averagePriorityDepthSum3_4)
			{
				order[emitted++] = priorityFaces[priorityFace++];
				if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
				{
					priorityFace = 0;
					priorityFaceCount = priorityFaceCounts[11];
					priorityFaces = priorityFaceLists[11];
					priorityFaceDepths = priority11FaceDepth;
				}
				if (priorityFace < priorityFaceCount)
				{
					priorityDepth = priorityFaceDepths[priorityFace];
				}
				else
				{
					priorityDepth = -1000;
				}
			}

			while (priority == 5 && priorityDepth > averagePriorityDepthSum6_8)
			{
				order[emitted++] = priorityFaces[priorityFace++];
				if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
				{
					priorityFace = 0;
					priorityFaceCount = priorityFaceCounts[11];
					priorityFaces = priorityFaceLists[11];
					priorityFaceDepths = priority11FaceDepth;
				}
				if (priorityFace < priorityFaceCount)
				{
					priorityDepth = priorityFaceDepths[priorityFace];
				}
				else
				{
					priorityDepth = -1000;
				}
			}

			int count = priorityFaceCounts[priority];
			int[] faces = priorityFaceLists[priority];
			for (int i = 0; i < count; i++)
			{
				order[emitted++] = faces[i];
			}
		}

		while (priorityDepth != -1000)
		{
			order[emitted++] = priorityFaces[priorityFace++];
			if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
			{
				priorityFace = 0;
				priorityFaces = priorityFaceLists[11];
				priorityFaceCount = priorityFaceCounts[11];
				priorityFaceDepths = priority11FaceDepth;
			}
			if (priorityFace < priorityFaceCount)
			{
				priorityDepth = priorityFaceDepths[priorityFace];
			}
			else
			{
				priorityDepth = -1000;
			}
		}

		return java.util.Arrays.copyOf(order, emitted);
	}

	/**
	 * One vertex through the client's widget-model transform: yaw the model, push
	 * it to the camera distance, orbit the camera to its pitch, then divide by
	 * depth. Returns screen x, screen y and camera-space depth.
	 */
	private static double[] project(double vx, double vy, double vz,
		double yawSin, double yawCos, double pitchSin, double pitchCos,
		double eyeY, double eyeZ)
	{
		double x = vz * yawSin + vx * yawCos;
		double z = vz * yawCos - vx * yawSin;
		double y = vy;

		y += eyeY;
		z += eyeZ;

		double cy = y * pitchCos - z * pitchSin;
		double cz = y * pitchSin + z * pitchCos;

		// Behind or level with the camera: park it far away rather than divide by
		// zero; such faces are dropped by the depth guard when they are drawn.
		if (cz < 1)
		{
			return new double[]{0, 0, -1};
		}
		return new double[]{x / cz, cy / cz, cz};
	}
}

package com.follower.ui;

import com.follower.speech.DialogTree;
import com.google.gson.Gson;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.FileSystemException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The conversation editor: every node of a dialog tree as a row, with who
 * speaks, what they say, where it goes next and which branch counts as the
 * answer.
 *
 * <p>A table rather than raw JSON because a conversation is a graph and the
 * thing that goes wrong with a graph is an edge pointing at nothing. Seeing
 * every node id in one column next to every {@code next} that names one is what
 * makes a typo obvious; in a file it is invisible until the box shuts in
 * somebody's face.
 *
 * <p>Save validates the whole tree before writing. A dialog that dead-ends is
 * worse than one that never opens, because the player is already inside it.
 */
@Slf4j
public class DialogsDialog extends JDialog
{
	private final Gson gson;
	private final Path file;

	private final JComboBox<String> treePicker = new JComboBox<>();
	private final JPanel list = new JPanel();
	private final JLabel status = new JLabel(" ");
	private final List<Row> rows = new ArrayList<>();

	private DialogFile parsed;
	private boolean loading;

	/** The tree the rows on screen belong to, for reverting a cancelled switch. */
	private int shownTreeIndex;

	/**
	 * Whether anything on screen differs from the file. Guards every road out
	 * of the window - closing, reopening, switching tree - because unsaved
	 * node edits used to vanish silently on any of them.
	 */
	private boolean dirty;

	private final javax.swing.event.DocumentListener dirtyMarker =
		new javax.swing.event.DocumentListener()
	{
		@Override
		public void insertUpdate(javax.swing.event.DocumentEvent e)
		{
			dirty = true;
		}

		@Override
		public void removeUpdate(javax.swing.event.DocumentEvent e)
		{
			dirty = true;
		}

		@Override
		public void changedUpdate(javax.swing.event.DocumentEvent e)
		{
			dirty = true;
		}
	};

	public DialogsDialog(Gson gson, Path file)
	{
		super((java.awt.Frame) null, "Follower Buddy — Conversations", false);
		this.gson = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
		this.file = file;

		// Closing is handled below so unsaved edits get a say first.
		setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
		addWindowListener(new java.awt.event.WindowAdapter()
		{
			@Override
			public void windowClosing(java.awt.event.WindowEvent e)
			{
				if (confirmDirty())
				{
					setVisible(false);
				}
			}
		});

		JPanel root = new JPanel(new BorderLayout(0, 6));
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);
		root.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JLabel hint = new JLabel("<html>These are the conversations the follower"
			+ " <b>starts</b>. While it is waiting for an answer, right-clicking Talk-to"
			+ " opens the tree it asked through instead of the everyday one.<br>"
			+ "<b>Says</b> and <b>You</b> are one page per line. <b>Choices</b> are one"
			+ " per line, written <code>label -&gt; node-id</code>. <b>Answer</b> is what"
			+ " reaching that node tells the rules.</html>");
		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel top = new JPanel(new BorderLayout(6, 6));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.add(hint, BorderLayout.CENTER);
		treePicker.addActionListener(e ->
		{
			if (loading || treePicker.getSelectedIndex() < 0)
			{
				return;
			}
			int wanted = treePicker.getSelectedIndex();
			if (!confirmDirty())
			{
				// Cancelled: put the picker back without re-entering this.
				loading = true;
				treePicker.setSelectedIndex(shownTreeIndex);
				loading = false;
				return;
			}
			// Saving inside confirmDirty refreshes, which resets the picker to
			// the first tree; the user asked for a different one.
			if (treePicker.getSelectedIndex() != wanted)
			{
				loading = true;
				treePicker.setSelectedIndex(wanted);
				loading = false;
			}
			showSelectedTree();
		});
		top.add(treePicker, BorderLayout.SOUTH);
		root.add(top, BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JScrollPane scroll = new JScrollPane(list,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		root.add(scroll, BorderLayout.CENTER);

		JPanel bottom = new JPanel(new BorderLayout());
		bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		bottom.add(status, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JButton add = new JButton("Add node");
		add.setToolTipText("A new step in this conversation. Point something at it"
			+ " with Next or a Choice, or nothing will ever reach it.");
		add.addActionListener(e -> addBlankRow());
		buttons.add(add);

		JButton reload = new JButton("Reload");
		reload.setToolTipText("Discard unsaved edits and reload from disk");
		reload.addActionListener(e -> refresh());
		buttons.add(reload);

		JButton save = new JButton("Save");
		save.addActionListener(e -> save());
		buttons.add(save);
		bottom.add(buttons, BorderLayout.EAST);

		root.add(bottom, BorderLayout.SOUTH);

		setContentPane(root);
		setPreferredSize(new Dimension(700, 700));
		pack();
		setLocationRelativeTo(null);
	}

	/**
	 * Shows the window, fronting it if already open. Fresh file contents
	 * unless there are edits in progress - alt-tabbing away and clicking the
	 * panel button again must not wipe half-typed nodes.
	 */
	public void open()
	{
		if (!dirty)
		{
			refresh();
		}
		setVisible(true);
		toFront();
	}

	/**
	 * Gives unsaved edits a say before they would be lost.
	 *
	 * @return true when the action may proceed - nothing was pending, the
	 * edits were saved, or the user chose to discard them
	 */
	private boolean confirmDirty()
	{
		if (!dirty)
		{
			return true;
		}
		int choice = javax.swing.JOptionPane.showOptionDialog(this,
			"There are unsaved changes.", "Save changes?",
			javax.swing.JOptionPane.YES_NO_CANCEL_OPTION,
			javax.swing.JOptionPane.QUESTION_MESSAGE, null,
			new Object[]{"Save", "Discard", "Cancel"}, "Save");
		if (choice == 0)
		{
			return save();
		}
		if (choice == 1)
		{
			dirty = false;
			return true;
		}
		return false;
	}

	private void refresh()
	{
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			parsed = gson.fromJson(reader, DialogFile.class);
		}
		catch (Exception e)
		{
			log.warn("Could not read {}", file, e);
			setStatus("The conversations file couldn't be read - it may have been"
				+ " hand-edited. Fix it or restore a backup, then Reload.", true);
			return;
		}

		if (parsed == null || parsed.trees == null || parsed.trees.isEmpty())
		{
			setStatus("No conversations in dialogs.json", true);
			return;
		}

		loading = true;
		treePicker.removeAllItems();
		for (DialogTree tree : parsed.trees)
		{
			// The picker shows the same prettified names as the message editor;
			// the raw id still appears in each node's own rows for editing.
			treePicker.addItem(PhrasesDialog.prettyName(tree.id));
		}
		loading = false;
		showSelectedTree();
	}

	private DialogTree selectedTree()
	{
		int index = treePicker.getSelectedIndex();
		return parsed == null || parsed.trees == null
			|| index < 0 || index >= parsed.trees.size()
			? null : parsed.trees.get(index);
	}

	private void showSelectedTree()
	{
		rows.clear();
		list.removeAll();

		DialogTree tree = selectedTree();
		if (tree == null)
		{
			list.revalidate();
			list.repaint();
			return;
		}
		if (tree.nodes != null)
		{
			for (DialogTree.DialogNode node : tree.nodes)
			{
				list.add(buildRow(node));
			}
		}
		setStatus((tree.nodes == null ? 0 : tree.nodes.size()) + " nodes, starting at '"
			+ tree.startId() + "'", false);
		list.revalidate();
		list.repaint();
		shownTreeIndex = treePicker.getSelectedIndex();
		dirty = false;
	}

	private void addBlankRow()
	{
		DialogTree.DialogNode node = new DialogTree.DialogNode();
		node.id = "node-" + (rows.size() + 1);
		node.says = new ArrayList<>();
		list.add(buildRow(node));
		list.revalidate();
		list.repaint();
		dirty = true;
	}

	private static final class Row
	{
		final JTextField id = new JTextField();
		final JComboBox<String> speaker = new JComboBox<>(new String[]{"Follower", "You"});
		final JTextArea pages = new JTextArea(2, 40);
		final JTextField next = new JTextField();
		final JTextArea choices = new GhostArea("Yes please -> node-thanks", 2, 40);
		final JComboBox<String> answer = new JComboBox<>(new String[]{"—", "yes", "no"});
		boolean deleted;
		JPanel panel;
	}

	/**
	 * A text area that shows an example of its little syntax while empty, so
	 * "label -> node-id" is visible at the point of use rather than three
	 * paragraphs up in the header.
	 */
	private static final class GhostArea extends JTextArea
	{
		private final String ghost;

		GhostArea(String ghost, int rows, int columns)
		{
			super(rows, columns);
			this.ghost = ghost;
		}

		@Override
		protected void paintComponent(java.awt.Graphics g)
		{
			super.paintComponent(g);
			if (getText().isEmpty())
			{
				g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
				g.setFont(getFont().deriveFont(java.awt.Font.ITALIC));
				java.awt.Insets insets = getInsets();
				g.drawString(ghost, insets.left + 2,
					insets.top + g.getFontMetrics().getAscent());
			}
		}
	}

	private JPanel buildRow(DialogTree.DialogNode node)
	{
		Row row = new Row();
		rows.add(row);

		row.id.setText(node.id == null ? "" : node.id);
		row.speaker.setSelectedIndex(node.isPlayerSpeaking() ? 1 : 0);
		row.pages.setText(String.join("\n", node.pages()));
		row.next.setText(node.next == null ? "" : node.next);
		row.answer.setSelectedItem(node.answer == null ? "—" : node.answer);

		StringBuilder choiceText = new StringBuilder();
		if (node.choices != null)
		{
			for (DialogTree.DialogChoice choice : node.choices)
			{
				if (choice == null)
				{
					continue;
				}
				choiceText.append(choice.label == null ? "" : choice.label)
					.append(" -> ").append(choice.next == null ? "" : choice.next)
					.append('\n');
			}
		}
		row.choices.setText(choiceText.toString().trim());

		JPanel panel = new JPanel(new GridBagLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 6, 6, 6)));

		GridBagConstraints c = new GridBagConstraints();
		c.insets = new Insets(2, 2, 2, 2);
		c.fill = GridBagConstraints.HORIZONTAL;
		c.gridy = 0;

		c.gridx = 0;
		c.weightx = 0;
		panel.add(label("Node"), c);
		c.gridx = 1;
		c.weightx = 1;
		panel.add(row.id, c);
		c.gridx = 2;
		c.weightx = 0;
		panel.add(row.speaker, c);
		c.gridx = 3;
		JButton remove = new JButton("Delete");
		remove.setToolTipText("Remove this node. Anything pointing at it will need"
			+ " repointing, and Save will say so.");
		remove.addActionListener(e ->
		{
			row.deleted = true;
			panel.setVisible(false);
			dirty = true;
		});
		panel.add(remove, c);

		c.gridy = 1;
		c.gridx = 0;
		c.weightx = 0;
		panel.add(label("Says"), c);
		c.gridx = 1;
		c.gridwidth = 3;
		c.weightx = 1;
		panel.add(scrollable(row.pages), c);

		c.gridwidth = 1;
		c.gridy = 2;
		c.gridx = 0;
		c.weightx = 0;
		panel.add(label("Choices"), c);
		c.gridx = 1;
		c.gridwidth = 3;
		c.weightx = 1;
		panel.add(scrollable(row.choices), c);

		c.gridwidth = 1;
		c.gridy = 3;
		c.gridx = 0;
		c.weightx = 0;
		panel.add(label("Next"), c);
		c.gridx = 1;
		c.weightx = 1;
		panel.add(row.next, c);
		c.gridx = 2;
		c.weightx = 0;
		panel.add(label("Answer"), c);
		c.gridx = 3;
		panel.add(row.answer, c);

		// Attached after the values above are set, so populating a row does
		// not read as the user editing one.
		row.id.getDocument().addDocumentListener(dirtyMarker);
		row.pages.getDocument().addDocumentListener(dirtyMarker);
		row.choices.getDocument().addDocumentListener(dirtyMarker);
		row.next.getDocument().addDocumentListener(dirtyMarker);
		row.speaker.addActionListener(e -> dirty = true);
		row.answer.addActionListener(e -> dirty = true);

		row.panel = panel;
		return panel;
	}

	private static JLabel label(String text)
	{
		JLabel jLabel = new JLabel(text);
		jLabel.setFont(FontManager.getRunescapeSmallFont());
		jLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return jLabel;
	}

	private static JScrollPane scrollable(JTextArea area)
	{
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setBackground(ColorScheme.DARK_GRAY_COLOR);
		area.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		area.setCaretColor(ColorScheme.LIGHT_GRAY_COLOR);
		JScrollPane scroll = new JScrollPane(area,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR));
		return scroll;
	}

	/** @return whether the file was written */
	private boolean save()
	{
		DialogTree tree = selectedTree();
		if (tree == null)
		{
			return false;
		}

		List<DialogTree.DialogNode> rebuilt = new ArrayList<>();
		for (Row row : rows)
		{
			if (row.deleted)
			{
				continue;
			}
			String id = row.id.getText().trim();
			if (id.isEmpty())
			{
				continue;
			}

			DialogTree.DialogNode node = new DialogTree.DialogNode();
			node.id = id;

			List<String> pages = new ArrayList<>();
			for (String line : row.pages.getText().split("\r?\n"))
			{
				if (!line.trim().isEmpty())
				{
					pages.add(line.trim());
				}
			}
			if (row.speaker.getSelectedIndex() == 1)
			{
				node.you = pages;
			}
			else
			{
				node.says = pages;
			}

			List<DialogTree.DialogChoice> choices = new ArrayList<>();
			for (String line : row.choices.getText().split("\r?\n"))
			{
				String trimmed = line.trim();
				if (trimmed.isEmpty())
				{
					continue;
				}
				int arrow = trimmed.lastIndexOf("->");
				DialogTree.DialogChoice choice = new DialogTree.DialogChoice();
				if (arrow < 0)
				{
					// Left as a choice with no target so validation names it,
					// rather than silently dropping a line somebody typed.
					choice.label = trimmed;
				}
				else
				{
					choice.label = trimmed.substring(0, arrow).trim();
					choice.next = trimmed.substring(arrow + 2).trim();
				}
				choices.add(choice);
			}
			if (!choices.isEmpty())
			{
				node.choices = choices;
			}

			String next = row.next.getText().trim();
			node.next = next.isEmpty() ? null : next;

			Object answer = row.answer.getSelectedItem();
			node.answer = answer == null || "—".equals(answer) ? null : answer.toString();

			rebuilt.add(node);
		}

		List<DialogTree.DialogNode> previous = tree.nodes;
		String previousStart = tree.start;
		tree.nodes = rebuilt;
		// The start has to still exist, or the conversation opens on nothing.
		if (tree.start != null && tree.byId().get(tree.start) == null)
		{
			tree.start = rebuilt.isEmpty() ? null : rebuilt.get(0).id;
		}

		List<String> problems = tree.problems();
		if (!problems.isEmpty())
		{
			// Nothing is written. A conversation that dead-ends is worse than
			// one that never opens, because the player is already inside it
			// when it happens.
			tree.nodes = previous;
			tree.start = previousStart;
			setStatus("Not saved — " + String.join("; ", problems), true);
			return false;
		}

		try
		{
			writeAtomically(gson.toJson(parsed) + "\n");
			setStatus("Saved — the follower picks it up within a second", false);
			dirty = false;
			refresh();
			return true;
		}
		catch (Exception e)
		{
			log.warn("Could not save {}", file, e);
			tree.nodes = previous;
			tree.start = previousStart;
			setStatus("Save failed: " + e.getMessage(), true);
			return false;
		}
	}

	/**
	 * Replaces the file in one step, via a sibling temp file, with the same
	 * fall-back-to-in-place dance phrases.json uses: the plugin polls this
	 * file every couple of ticks, Windows will not rename over an open
	 * handle, and losing somebody's edits is worse than a torn read the loader
	 * already knows how to survive.
	 */
	private void writeAtomically(String contents) throws IOException
	{
		Path temp = file.resolveSibling(file.getFileName() + ".tmp");
		byte[] bytes = contents.getBytes(StandardCharsets.UTF_8);
		Files.write(temp, bytes);

		try
		{
			Files.move(temp, file,
				StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			Files.move(temp, file, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (FileSystemException e)
		{
			Files.write(file, bytes);
			Files.deleteIfExists(temp);
		}
	}

	private void setStatus(String text, boolean bad)
	{
		status.setText(text);
		status.setForeground(bad ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
	}

	/** Mirrors the on-disk shape so the whole file round-trips, not just one tree. */
	private static final class DialogFile
	{
		int version = 1;
		List<DialogTree> trees;
	}
}

