			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		resultScroll.setBorder(BorderFactory.createEmptyBorder());
		// Zero preferred WIDTH: a fixed one (this used to say PANEL_WIDTH)
		// out-demanded the sidebar and shoved the whole column off its right
		// edge. The height is the fixed part; the width is the container's.
		resultScroll.setPreferredSize(new Dimension(0, 240));
		resultScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 240));
		resultScroll.setAlignmentX(LEFT_ALIGNMENT);
		resultScroll.getVerticalScrollBar().setUnitIncrement(16);
		// The rest of the catalogue arrives as the list is scrolled toward
		// its end - every match is reachable, none is paid for up front.
		resultScroll.getVerticalScrollBar().addAdjustmentListener(e ->
		{
			javax.swing.JScrollBar bar = resultScroll.getVerticalScrollBar();
			if (!pendingResults.isEmpty()
				&& bar.getValue() + bar.getVisibleAmount() >= bar.getMaximum() - 64)
			{
				appendResults(RESULT_CHUNK);
			}
		});
		picker.add(resultScroll);

		content.add(picker);

		content.add(sectionHeader("BODY", "Styles cycle live on the follower; colours are the game's own"));
		// BoxLayout, NOT GridLayout: a grid splits its height evenly between
		// rows and ignores their maximum size, so every row grew as the
		// window did. A vertical box honours the fixed row height.
		bodyList.setLayout(new BoxLayout(bodyList, BoxLayout.Y_AXIS));
		bodyList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bodyList.setAlignmentX(LEFT_ALIGNMENT);
		content.add(bodyList);

		return content;
	}

	/**
	 * A panel whose scroll view always matches the viewport's width, whatever
	 * the viewport happens to be once the vertical scrollbar takes its share.
	 * Content adapts or wraps; it never slides out past the right edge.
	 */
	private static final class ScrollableColumn extends JPanel
		implements javax.swing.Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(java.awt.Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(java.awt.Rectangle visible, int orientation, int direction)
		{
			return visible.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private JPanel sectionHeader(String text, String tooltip)
	{
		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.setAlignmentX(LEFT_ALIGNMENT);
		wrap.setBorder(BorderFactory.createEmptyBorder(10, 0, 4, 0));
		wrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setToolTipText(tooltip);
		wrap.add(label, BorderLayout.WEST);

		JPanel rule = new JPanel();
		rule.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		rule.setPreferredSize(new Dimension(10, 1));
		JPanel ruleWrap = new JPanel(new BorderLayout());
		ruleWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		ruleWrap.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
		ruleWrap.add(rule, BorderLayout.CENTER);
		wrap.add(ruleWrap, BorderLayout.CENTER);

		return wrap;
	}

	/** Hover preview: a scaled-up sprite so you can see the item before equipping. */
	private JPanel buildPreview()
	{
		JPanel wrapper = new JPanel(new BorderLayout(6, 0));
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		wrapper.setAlignmentX(LEFT_ALIGNMENT);
		wrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, 116));

		previewIcon.setHorizontalAlignment(SwingConstants.CENTER);
		previewIcon.setVerticalAlignment(SwingConstants.CENTER);
		previewIcon.setPreferredSize(new Dimension(36 * PREVIEW_SCALE, 32 * PREVIEW_SCALE));
		wrapper.add(previewIcon, BorderLayout.WEST);

		previewName.setFont(FontManager.getRunescapeSmallFont());
		previewName.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		previewName.setVerticalAlignment(SwingConstants.TOP);
		// Fixed size: an HTML label sizes itself to its longest line, so a
		// long item name would widen this label, then the wrapper, then the
		// whole sidebar column - the layout visibly jumping on hover.
		previewName.setPreferredSize(new Dimension(PREVIEW_TEXT_WIDTH, 32 * PREVIEW_SCALE));
		previewName.setMaximumSize(new Dimension(PREVIEW_TEXT_WIDTH, 32 * PREVIEW_SCALE));
		wrapper.add(previewName, BorderLayout.CENTER);

		return wrapper;
	}

	/** Width the preview's name column is held to, so long names wrap instead of stretch. */
	private static final int PREVIEW_TEXT_WIDTH = 68;

	// -------------------------------------------------------------- plugin hooks

	public void setOutfit(Outfit outfit)
	{
		SwingUtilities.invokeLater(() ->
		{
			current = new Outfit(outfit);
			rebuildSlots();
		});
	}

	public void setStatus(String text)
	{
		SwingUtilities.invokeLater(() -> status.setText(text));
	}

	/** Called once the plugin has worked out which slot each item belongs to. */
	public void setSlotIndex(Map<Integer, KitType> index)
	{
		SwingUtilities.invokeLater(() ->
		{
			slotIndex = index;
			refreshResults();
		});
	}

	// ---------------------------------------------------------------- gear grid

	private void rebuildSlots()
	{
		gearGrid.removeAll();
		for (KitType[] row : GEAR_GRID)
		{
			for (KitType slot : row)
			{
				gearGrid.add(slot == null ? spacer() : buildSlotCell(slot));
			}
		}
		gearGrid.revalidate();
		gearGrid.repaint();

		bodyList.removeAll();
		bodyList.add(buildGenderRow());
		bodyList.add(javax.swing.Box.createVerticalStrut(2));
		bodyList.add(buildSkinRow());
		for (KitType part : BODY_PARTS)
		{
			bodyList.add(javax.swing.Box.createVerticalStrut(2));
			bodyList.add(buildBodyRow(part));
		}
		bodyList.revalidate();
		bodyList.repaint();
	}

	private JPanel spacer()
	{
		JPanel s = new JPanel();
		s.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return s;
	}

	private JPanel buildSlotCell(KitType slot)
	{
		boolean isActive = slot == activeSlot;
		boolean hasItem = current.isItem(slot);

		JPanel cell = new JPanel(new BorderLayout());
		cell.setPreferredSize(new Dimension(CELL, CELL));
		cell.setBackground(isActive ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		cell.setBorder(isActive
			? BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE, 1)
			: BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR, 1));
		cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		String slotName = slot.name().toLowerCase();
		if (hasItem)
		{
			int id = current.itemId(slot);
			String itemName = repository.itemName(id);
			cell.setToolTipText((itemName == null ? "item " + id : itemName)
				+ " - click to change, right-click to clear");

			JLabel icon = new JLabel();
			icon.setHorizontalAlignment(SwingConstants.CENTER);
			AsyncBufferedImage image = itemManager.getImage(id);
			if (image != null)
			{
				image.addTo(icon);
			}
			cell.add(icon, BorderLayout.CENTER);
		}
		else
		{
			cell.setToolTipText("Empty " + slotName + " slot - click to choose an item");

			JLabel empty = new JLabel(slotName);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			empty.setHorizontalAlignment(SwingConstants.CENTER);
			cell.add(empty, BorderLayout.CENTER);
		}

		cell.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isRightMouseButton(e))
				{
					onClear.accept(slot);
					return;
				}
				showPicker(slot == activeSlot ? null : slot);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (slot != activeSlot)
				{
					cell.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (slot != activeSlot)
				{
					cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				}
			}
		});

		return cell;
	}

	// --------------------------------------------------------------------- body

	private JPanel buildGenderRow()
	{
		JPanel row = bodyRowShell();

		JLabel name = new JLabel("body");
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		name.setPreferredSize(new Dimension(NAME_WIDTH, ROW_CONTENT_HEIGHT));
		row.add(name, BorderLayout.WEST);

		JPanel toggle = new JPanel(new GridLayout(1, 2, 2, 0));
		toggle.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		toggle.add(genderButton("male", 0));
		toggle.add(genderButton("female", 1));
		row.add(toggle, BorderLayout.CENTER);

		return row;
	}

	private JButton genderButton(String label, int gender)
	{
		boolean selected = current.getGender() == gender;
		JButton button = new JButton(label);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setForeground(selected ? Color.WHITE : ColorScheme.MEDIUM_GRAY_COLOR);
		if (selected)
		{
			button.setBackground(ColorScheme.MEDIUM_GRAY_COLOR.darker());
		}
		button.setToolTipText("Switches the whole body model, and the default kits with it");
		button.addActionListener(e ->
		{
			if (!selected)
			{
				onGender.accept(gender);
			}
		});
		return button;
	}

	/**
	 * Skin is its own control rather than part of any one slot: the same skin
	 * colours appear across the head, arms and hands, so recolouring them together
	 * is the only way to keep a body consistent.
	 */
	private JPanel buildSkinRow()
	{
		JPanel row = bodyRowShell();

		JLabel name = new JLabel("skin");
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		name.setPreferredSize(new Dimension(NAME_WIDTH, ROW_CONTENT_HEIGHT));
		row.add(name, BorderLayout.WEST);

		row.add(swatch(4, "skin", GamePalette.SKIN), BorderLayout.EAST);
		return row;
	}

	/** Label column width; the style label takes whatever is left over. */
	private static final int NAME_WIDTH = 52;
	private static final int ROW_CONTENT_HEIGHT = 20;
	private static final int ROW_HEIGHT = ROW_CONTENT_HEIGHT + 6;

	/**
	 * A body-part row: fixed height so the vertical BoxLayout cannot stretch
	 * it (rows doubled in height on a maximised window), and never wider than
	 * the panel so the scrollbar cannot clip the colour swatch off the right.
	 */
	private JPanel bodyRowShell()
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));
		row.setMinimumSize(new Dimension(0, ROW_HEIGHT));
		row.setPreferredSize(new Dimension(0, ROW_HEIGHT));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		row.setAlignmentX(LEFT_ALIGNMENT);
		return row;
	}

	/** One body part: cycle its kit, and set its colour. */
	private JPanel buildBodyRow(KitType part)
	{
		JPanel row = bodyRowShell();

		JLabel name = new JLabel(part.name().toLowerCase());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		name.setPreferredSize(new Dimension(NAME_WIDTH, ROW_CONTENT_HEIGHT));
		row.add(name, BorderLayout.WEST);

		// Kits have no names in the cache, so they're cycled and judged by eye - the
		// follower updates live, which makes it its own preview.
		//
		// BorderLayout rather than a flow: the arrows keep their size at the
		// edges and the label in the middle absorbs whatever width is left, so
		// a narrow sidebar squeezes the text instead of pushing the swatch out.
		JPanel cycle = new JPanel(new BorderLayout(2, 0));
		cycle.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JButton prev = new JButton("‹");
		prev.setToolTipText("Previous style");
		prev.setFocusPainted(false);
		prev.setMargin(new java.awt.Insets(0, 2, 0, 2));
		prev.setPreferredSize(new Dimension(18, ROW_CONTENT_HEIGHT));
		prev.addActionListener(e -> onCycleKit.accept(part, -1));
		cycle.add(prev, BorderLayout.WEST);

		java.util.List<Integer> choices = repository.kitsFor(part, current.getGender());
		int index = current.isKit(part) ? choices.indexOf(current.kitId(part)) : -1;
		String label = KitNames.label(part, index, choices.size());

		JLabel style = new JLabel(label);
		style.setFont(FontManager.getRunescapeSmallFont());
		style.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		style.setToolTipText(label);
		style.setPreferredSize(new Dimension(0, ROW_CONTENT_HEIGHT));
		style.setHorizontalAlignment(SwingConstants.CENTER);
		cycle.add(style, BorderLayout.CENTER);

		JButton next = new JButton("›");
		next.setToolTipText("Next style");
		next.setFocusPainted(false);
		next.setMargin(new java.awt.Insets(0, 2, 0, 2));
		next.setPreferredSize(new Dimension(18, ROW_CONTENT_HEIGHT));
		next.addActionListener(e -> onCycleKit.accept(part, 1));
		cycle.add(next, BorderLayout.EAST);

		row.add(cycle, BorderLayout.CENTER);

		// Colours come from the game's own palette tables - every choice here is a
		// colour the game can genuinely produce, applied exactly as the client does.
		// Jaw follows hair, arms follow torso, hands follow skin, as in the game.
		if (part == KitType.HAIR || part == KitType.TORSO
			|| part == KitType.LEGS || part == KitType.BOOTS)
		{
			int colorSlot = colorSlotFor(part);
			row.add(swatch(colorSlot, part.name().toLowerCase(),
				GamePalette.table(colorSlot)), BorderLayout.EAST);
		}

		return row;
	}

	/** A clickable colour square showing the current palette choice. */
	private JPanel swatch(int colorSlot, String title, short[] table)
	{
		JPanel square = new JPanel();
		square.setPreferredSize(new Dimension(20, 20));
		square.setBackground(new Color(HslColor.toRgb(table[paletteIndex(colorSlot)])));
		square.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR, 1));
		square.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		square.setToolTipText(title + " colour - the game's " + table.length + " exact choices");
		square.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				Integer chosen = pickPaletteIndex(title, table);
				if (chosen != null)
				{
					onBodyColor.accept(colorSlot, chosen);
				}
			}
		});

		JPanel wrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		wrap.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrap.add(square);
		return wrap;
	}

	/** Current palette index for a body-colour slot, bounds-safe. */
	private int paletteIndex(int colorSlot)
	{
		int[] colors = current.getColors();
		int index = colorSlot < colors.length ? colors[colorSlot] : 0;
		short[] table = GamePalette.table(colorSlot);
		return table != null && index >= 0 && index < table.length ? index : 0;
	}

	/** Body-colour slot a part's colour comes from, or -1 if skin covers it. */
	private static int colorSlotFor(KitType part)
	{
		switch (part)
		{
			case HAIR:
			case JAW:
				return 0;
			case TORSO:
			case ARMS:
				return 1;
			case LEGS:
				return 2;
			case BOOTS:
				return 3;
			default:
				return -1;
		}
	}

	private void showPicker(KitType slot)
	{
		activeSlot = slot;
		boolean open = slot != null;

		picker.setVisible(open);
		if (open)
		{
			pickerTitle.setText("Choose " + slot.name().toLowerCase()
				+ (current.isItem(slot) ? "  (right-click the slot to clear)" : ""));
			search.setText("");
			clearPreview();
			refreshResults();
			search.requestFocusInWindow();
		}

		rebuildSlots();
		revalidate();
		repaint();
	}

	// ------------------------------------------------------------------ results

	/**
	 * Swatch grid over one of the game's palette tables; returns the chosen INDEX.
	 *
	 * <p>The swatch is painted with the RGB of the packed table colour, but only the
	 * index is stored - the compose path replays the client's own find/replace with
	 * it, so what renders is the game's colour, not the swatch approximation.
	 */
	private Integer pickPaletteIndex(String title, short[] table)
	{
		JPanel grid = new JPanel(new GridLayout(0, 8, 3, 3));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final Integer[] picked = {null};
		final javax.swing.JDialog[] dialog = {null};

		for (int i = 0; i < table.length; i++)
		{
			int rgb = HslColor.toRgb(table[i]);
			final int index = i;

			JButton swatch = new JButton();
			swatch.setBackground(new Color(rgb));
			swatch.setOpaque(true);
			swatch.setBorderPainted(false);
			swatch.setPreferredSize(new Dimension(26, 26));
			swatch.setToolTipText(index + ": #" + String.format("%06X", rgb));
			swatch.addActionListener(e ->
			{
				picked[0] = index;
				if (dialog[0] != null)
				{
					dialog[0].dispose();
				}
			});
			grid.add(swatch);
		}

		javax.swing.JOptionPane pane = new javax.swing.JOptionPane(grid,
			javax.swing.JOptionPane.PLAIN_MESSAGE,
			javax.swing.JOptionPane.DEFAULT_OPTION, null, new Object[]{}, null);
		dialog[0] = pane.createDialog(this, title + " colour");
		dialog[0].setVisible(true);
		dialog[0].dispose();

		return picked[0];
	}

	private void refreshResults()
	{
		resultList.removeAll();
		pendingResults.clear();

		if (activeSlot == null)
		{
			resultList.revalidate();
			resultList.repaint();
			return;
		}

		// The cache-dumper detail belongs in the log, not in front of a user
		// who has never heard of the build tooling.
		if (!repository.isLoaded() || !repository.hasNames())
		{
			resultList.add(hint("<html><body style='width:180px'>Item data didn't"
				+ " load - try restarting the client. If it keeps happening,"
				+ " report a bug.</body></html>"));
		}
		else
		{
			// EVERY match, not a page of them: rows are built lazily as the
			// list scrolls (see the adjustment listener on resultScroll), so
			// the full catalogue is reachable without being paid for up front.
			// The limit is a formality search() multiplies internally - large,
			// but nowhere near where that multiply would overflow.
			List<ModelRepository.WearableItem> matches =
				repository.search(search.getText(), 100_000);

			boolean filter = !slotIndex.isEmpty() && !showAll.isSelected();
			for (ModelRepository.WearableItem item : matches)
			{
				// Only offer items that belong in this slot. Until the index is built
				// everything is offered, so the picker still works immediately.
				if (filter && slotIndex.get(item.id) != activeSlot)
				{
					continue;
				}
				pendingResults.addLast(item);
			}

			if (pendingResults.isEmpty())
			{
				if (slotIndex.isEmpty())
				{
					resultList.add(hint("Indexing items, try again in a moment..."));
				}
				else
				{
					resultList.add(hint("No " + activeSlot.name().toLowerCase()
						+ " items match - try \"Show items from every slot\""));
				}
			}
			else
			{
				appendResults(RESULT_CHUNK);
			}
		}

		resultList.revalidate();
		resultList.repaint();
	}

	/** Builds the next slice of pending matches into rows. */
	private void appendResults(int count)
	{
		for (int i = 0; i < count && !pendingResults.isEmpty(); i++)
		{
			resultList.add(buildResultRow(pendingResults.pollFirst()));
		}
		resultList.revalidate();
		resultList.repaint();
	}

	private JPanel buildResultRow(ModelRepository.WearableItem item)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
		row.setToolTipText(item.name + " - click to equip (id " + item.id + ")");
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		// Never taller or wider than a row needs: the list lives in a vertical
		// box, which would otherwise stretch rows to fill and let a long name
		// widen the whole column.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		AsyncBufferedImage image = itemManager.getImage(item.id);
		if (image != null)
		{
			image.addTo(icon);
		}
		row.add(icon, BorderLayout.WEST);

		JLabel name = new JLabel(item.name);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);
		// Zero preferred width: BorderLayout's centre takes whatever is left
		// over at layout time, and the label ellipsises rather than demanding
		// room for the full name. The tooltip carries the untruncated text.
		name.setPreferredSize(new Dimension(0, 20));
		row.add(name, BorderLayout.CENTER);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onEquip.accept(item.id, activeSlot);
				showPicker(null);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
				showPreview(item);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});

		return row;
	}

	// ------------------------------------------------------------------ preview

	private void showPreview(ModelRepository.WearableItem item)
	{
		// The body width is what makes long names WRAP; without it the label
		// grows sideways and drags the sidebar's layout with it.
		previewName.setText("<html><body style='width:" + (PREVIEW_TEXT_WIDTH - 4) + "px'><b>"
			+ escapeHtml(item.name) + "</b><br>id " + item.id + "</body></html>");

		AsyncBufferedImage image = itemManager.getImage(item.id);
		if (image == null)
		{
			previewIcon.setIcon(null);
			return;
		}

		// The sprite may not have arrived yet; scale it once it has.
		image.onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			Image scaled = image.getScaledInstance(
				image.getWidth() * PREVIEW_SCALE,
				image.getHeight() * PREVIEW_SCALE,
				Image.SCALE_SMOOTH);
			previewIcon.setIcon(new ImageIcon(scaled));
		}));
	}

	private void clearPreview()
	{
		previewIcon.setIcon(null);
		previewName.setText("Hover an item to preview it");
	}

	private JLabel hint(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		return label;
	}

	/** Item names are cache text; they must not be able to inject markup. */
	private static String escapeHtml(String text)
	{
		return text == null ? "" : text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.follower.ui;

/**
 * The client's 65,536-entry colour table, ported line for line from
 * {@code Pix3D.initColourTable}.
 *
 * <p>The game never converts packed HSL to RGB with a formula at draw time: it
 * precomputes this table - a bespoke HSL-to-RGB with half-step hue/saturation
 * offsets, truncating arithmetic, and a gamma curve from the brightness setting
 * (0.8 at the default "Normal") - and rasterises by interpolating the PACKED
 * index across each triangle, looking up the table per pixel. A plain linear
 * HSL conversion produces visibly different tones, which is why the follower's
 * face never quite matched a real chathead's colours.
 *
 * <p>The client also jitters brightness by up to ±0.015 per login; that noise is
 * deliberately omitted for determinism.
 */
public final class GameColourTable
{
	private static volatile int[] table = build(0.8);
	private static volatile double currentGamma = 0.8;

	private GameColourTable()
	{
	}

	/** RGB for a packed HSL value, through the game's own table. */
	public static int rgb(int packed)
	{
		return table[packed & 0xFFFF];
	}

	/**
	 * Rebuilds for the player's brightness setting, so the follower's head is on
	 * the SAME gamma table as every real chathead on screen. The setting's varp
	 * maps 1..4 to gammas 0.9, 0.8, 0.7, 0.6 (Dark to V.Bright) in the client.
	 */
	public static void setBrightnessSetting(int varpValue)
	{
		double gamma;
		switch (varpValue)
		{
			case 1:
				gamma = 0.9;
				break;
			case 3:
				gamma = 0.7;
				break;
			case 4:
				gamma = 0.6;
				break;
			case 2:
			default:
				gamma = 0.8;
				break;
		}

		if (gamma != currentGamma)
		{
			currentGamma = gamma;
			table = build(gamma);
		}
	}

	public static double getCurrentGamma()
	{
		return currentGamma;
	}

	private static int[] build(double brightness)
	{
		int[] table = new int[65536];
		int offset = 0;

		for (int y = 0; y < 512; y++)
		{
			double hue = (y / 8) / 64.0 + 0.0078125;
			double saturation = (y & 0x7) / 8.0 + 0.0625;

			for (int x = 0; x < 128; x++)
			{
				double lightness = x / 128.0;
				double r = lightness;
				double g = lightness;
				double b = lightness;

				if (saturation != 0.0)
				{
					double q;
					if (lightness < 0.5)
					{
						q = lightness * (saturation + 1.0);
					}
					else
					{
						q = lightness + saturation - lightness * saturation;
					}

					double p = lightness * 2.0 - q;

					double t = hue + (1.0 / 3.0);
					if (t > 1.0)
					{
						t--;
					}
					double d = hue - (1.0 / 3.0);
					if (d < 0.0)
					{
						d++;
					}

					r = channel(p, q, t);
					g = channel(p, q, hue);
					b = channel(p, q, d);
				}

				int rgb = ((int) (r * 256.0) << 16)
					+ ((int) (g * 256.0) << 8)
					+ (int) (b * 256.0);
				table[offset++] = gammaCorrect(rgb, brightness);
			}
		}
		return table;
	}

	private static double channel(double p, double q, double t)
	{
		if (t * 6.0 < 1.0)
		{
			return p + (q - p) * 6.0 * t;
		}
		if (t * 2.0 < 1.0)
		{
			return q;
		}
		if (t * 3.0 < 2.0)
		{
			return p + (q - p) * ((2.0 / 3.0) - t) * 6.0;
		}
		return p;
	}

	private static int gammaCorrect(int rgb, double gamma)
	{
		double r = (rgb >> 16) / 256.0;
		double g = ((rgb >> 8) & 0xFF) / 256.0;
		double b = (rgb & 0xFF) / 256.0;

		return ((int) (Math.pow(r, gamma) * 256.0) << 16)
			+ ((int) (Math.pow(g, gamma) * 256.0) << 8)
			+ (int) (Math.pow(b, gamma) * 256.0);
	}
}

package com.follower.ui;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

/**
 * One of the game's own bitmap fonts, rendered by blitting the cache's actual
 * glyph masks - the same pixels the client puts on screen. A TTF through a
 * system rasterizer never matches exactly (hinting, baselines and advances all
 * differ); these are the real glyphs with the real per-character advances and
 * bearings, dumped by tools/cache-dumper into fonts.json.
 *
 * <p>Draw semantics ported from the client's font renderer ({@code PixFont}):
 * glyphs blit at {@code (x + offsetX, top + offsetY)}, the pen advances by the
 * font's per-character advance, and a shadowed draw plots a black copy at
 * {@code (+1, +1)} first. Overhead text is the one exception - the client
 * draws its black copy at {@code (x, y + 1)}, straight down - so both shadow
 * styles are offered. Glyphs are indexed DIRECTLY by character code (the
 * dumped archives all carry 256 glyphs and 256 advances).
 */
public final class GameFont
{
	public static class Glyph
	{
		public final int width;
		public final int height;
		public final int offsetX;
		public final int offsetY;
		public final byte[] mask;

		Glyph(int width, int height, int offsetX, int offsetY, byte[] mask)
		{
			this.width = width;
			this.height = height;
			this.offsetX = offsetX;
			this.offsetY = offsetY;
			this.mask = mask;
		}
	}

	private final int ascent;
	private final int[] advances;
	private final Glyph[] glyphs;

	/** The client's PixFont.height: the tallest glyph mask, its line-stack step. */
	private final int lineHeight;

	/** Tinted glyph images, cached per (character, colour). */
	private final Map<Long, BufferedImage> tinted = new HashMap<>();

	public GameFont(int ascent, int[] advances, Glyph[] glyphs)
	{
		this.ascent = ascent;
		this.advances = advances;
		this.glyphs = glyphs;

		int tallest = 0;
		for (Glyph glyph : glyphs)
		{
			if (glyph != null && glyph.height > tallest)
			{
				tallest = glyph.height;
			}
		}
		this.lineHeight = tallest;
	}

	public int getAscent()
	{
		return ascent;
	}

	public int getLineHeight()
	{
		return lineHeight;
	}

	/** The exact pixel width the client would measure for this string. */
	public int stringWidth(String text)
	{
		if (text == null)
		{
			return 0;
		}
		int width = 0;
		for (int i = 0; i < text.length(); i++)
		{
			width += advances[text.charAt(i) & 0xFF];
		}
		return width;
	}

	/**
	 * Draws with {@code y} as the BASELINE, the widget text convention: a text
	 * line's baseline sits at its top plus the font's ascent.
	 */
	public void drawBaseline(Graphics2D g, String text, int x, int y, int rgb, boolean shadowed)
	{
		drawTop(g, text, x, y - ascent, rgb, shadowed);
	}

	/** Draws with {@code y} as the TOP of the glyph cell. */
	public void drawTop(Graphics2D g, String text, int x, int y, int rgb, boolean shadowed)
	{
		if (text == null)
		{
			return;
		}
		int pen = x;
		for (int i = 0; i < text.length(); i++)
		{
			int c = text.charAt(i) & 0xFF;
			Glyph glyph = glyphs[c];
			if (glyph != null && glyph.width > 0 && glyph.height > 0)
			{
				if (shadowed)
				{
					g.drawImage(tint(c, 0x000000),
						pen + glyph.offsetX + 1, y + glyph.offsetY + 1, null);
				}
				g.drawImage(tint(c, rgb), pen + glyph.offsetX, y + glyph.offsetY, null);
			}
			pen += advances[c];
		}
	}

	/** Centered on {@code x}, baseline at {@code y}. */
	public void drawCenteredBaseline(Graphics2D g, String text, int x, int y, int rgb, boolean shadowed)
	{
		drawBaseline(g, text, x - stringWidth(text) / 2, y, rgb, shadowed);
	}

	/**
	 * Overhead style, verbatim from the client's chat-above-head draw: the
	 * black copy sits at {@code (x, y + 1)} - straight below, not diagonal -
	 * with the coloured text on top, both centered. {@code y} is the baseline.
	 */
	public void drawCenteredOverhead(Graphics2D g, String text, int x, int y, int rgb)
	{
		int left = x - stringWidth(text) / 2;
		drawTopNoShadow(g, text, left, y + 1 - ascent, 0x000000);
		drawTopNoShadow(g, text, left, y - ascent, rgb);
	}

	private void drawTopNoShadow(Graphics2D g, String text, int x, int y, int rgb)
	{
		int pen = x;
		for (int i = 0; i < text.length(); i++)
		{
			int c = text.charAt(i) & 0xFF;
			Glyph glyph = glyphs[c];
			if (glyph != null && glyph.width > 0 && glyph.height > 0)
			{
				g.drawImage(tint(c, rgb), pen + glyph.offsetX, y + glyph.offsetY, null);
			}
			pen += advances[c];
		}
	}

	private BufferedImage tint(int character, int rgb)
	{
		long key = ((long) character << 32) | (rgb & 0xFFFFFFFFL);
		BufferedImage cached = tinted.get(key);
		if (cached != null)
		{
			return cached;
		}

		Glyph glyph = glyphs[character];
		BufferedImage image = new BufferedImage(glyph.width, glyph.height,
			BufferedImage.TYPE_INT_ARGB);
		int argb = 0xFF000000 | rgb;
		for (int i = 0; i < glyph.mask.length; i++)
		{
			if (glyph.mask[i] != 0)
			{
				image.setRGB(i % glyph.width, i / glyph.width, argb);
			}
		}
		tinted.put(key, image);
		return image;
	}
}

package com.follower.ui;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * The game's bitmap fonts, dumped from the cache by tools/cache-dumper. Keyed
 * by the id widgets report from {@code getFontId()} - the glyph sprite
 * archive's id - so a sniffed dialog's font maps straight to the exact glyphs
 * it renders with.
 */
@Slf4j
@Singleton
public class GameFontRepository
{
	public static final String FILE_NAME = "fonts.json";

	private static class GlyphEntry
	{
		int w;
		int h;
		int ox;
		int oy;
		String mask;
	}

	private static class FontEntry
	{
		int id;
		String name;
		int ascent;
		int[] advances;
		List<GlyphEntry> glyphs;
	}

	private static class Dump
	{
		int version;
		String cacheRevision;
		List<FontEntry> fonts;
	}

	private final Gson gson;
	private final Map<Integer, GameFont> fonts = new HashMap<>();
	private final Map<String, GameFont> fontsByName = new HashMap<>();

	@Getter
	private String status = "not loaded";

	@Inject
	public GameFontRepository(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Loads from {@code <dataDir>/fonts.json} when present (the development
	 * override), else from the bundled copy of the same dump. Fonts are
	 * bundled rather than parsed live because pairing font metrics to glyph
	 * sprites requires archive name hashes the runtime API does not expose -
	 * and the game's bitmap fonts have not changed in decades.
	 *
	 * <p>The BUNDLED dump carries only the two fonts the plugin draws with:
	 * 497 (q8_full) for the dialog box and 496 (b12_full) for the overhead
	 * line. The dumper still writes all 21, which is what you want on disk for
	 * identifying a sniffed widget's font, but shipping the other 19 cost
	 * around 60KB of the jar and 5,000 base64 glyph decodes at startup to hold
	 * glyphs nothing ever asked for. Add an id to the trim if something starts
	 * drawing with it - {@link #get} and {@link #getByName} return null for a
	 * font that is not there, and both callers fall back to a TTF, so the
	 * failure is quiet rather than loud.
	 */
	public void load(Path dataDir)
	{
		Path file = dataDir.resolve(FILE_NAME);
		if (Files.isRegularFile(file))
		{
			try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
			{
				if (read(reader, file.toString()))
				{
					return;
				}
			}
			catch (IOException | RuntimeException e)
			{
				status = "failed to read " + FILE_NAME;
				log.warn("Could not load {}", file, e);
			}
		}

		try (java.io.InputStream in = GameFontRepository.class
			.getResourceAsStream("/com/follower/" + FILE_NAME))
		{
			if (in == null)
			{
				status = "no " + FILE_NAME + " bundled or on disk";
				return;
			}
			read(new java.io.BufferedReader(
				new java.io.InputStreamReader(in, StandardCharsets.UTF_8)), "bundled resource");
		}
		catch (IOException | RuntimeException e)
		{
			status = "failed to read bundled " + FILE_NAME;
			log.warn("Could not load bundled font dump", e);
		}
	}

	private boolean read(Reader reader, String source)
	{
		Dump dump = gson.fromJson(reader, Dump.class);
		if (dump == null || dump.fonts == null)
		{
			status = FILE_NAME + " is empty (" + source + ")";
			return false;
		}

		for (FontEntry entry : dump.fonts)
		{
			GameFont.Glyph[] glyphs = new GameFont.Glyph[256];
			for (int i = 0; i < entry.glyphs.size() && i < 256; i++)
			{
				GlyphEntry g = entry.glyphs.get(i);
				glyphs[i] = new GameFont.Glyph(g.w, g.h, g.ox, g.oy,
					g.mask == null ? new byte[0] : Base64.getDecoder().decode(g.mask));
			}
			GameFont font = new GameFont(entry.ascent, entry.advances, glyphs);
			fonts.put(entry.id, font);
			if (entry.name != null)
			{
				fontsByName.put(entry.name, font);
			}
		}
		status = fonts.size() + " fonts (cache " + dump.cacheRevision + ")";
		log.info("Loaded {} game fonts from {} (cache {})",
			fonts.size(), source, dump.cacheRevision);
		return true;
	}

	/** The font for a widget font id, or null if unknown or not loaded. */
	public GameFont get(int fontId)
	{
		return fonts.get(fontId);
	}

	/** The font by cache archive name (p12_full, b12_full, ...), or null. */
	public GameFont getByName(String name)
	{
		return fontsByName.get(name);
	}

	public boolean isLoaded()
	{
		return !fonts.isEmpty();
	}
}

package com.follower.ui;

/**
 * The client's own triangle rasterizer, ported line for line from
 * {@code Pix3D.gouraudTriangle} and {@code Pix3D.gouraudRaster}.
 *
 * <p>This replaces a float barycentric fill that sampled pixel centres. On
 * triangles a few pixels across - the pupils of a chathead's eyes - the two
 * disagree visibly: a sub-pixel face can miss every pixel-centre sample and
 * vanish entirely, and adjacent faces can leave one-pixel cracks along shared
 * edges, letting the parchment behind show through as stray light pixels. The
 * game's rasterizer is an integer scanline walker with its own fill convention;
 * only running the same algorithm produces the same pixels.
 *
 * <p>Faithfulness notes:
 * <ul>
 * <li>x steps are 16.16 fixed point ({@code ((dx << 16) / dy)}), colour steps
 *     15-bit ({@code ((dc << 15) / dy)}); scanline endpoints are handed to the
 *     raster as {@code x >> 16} / {@code colour >> 7}, and the raster indexes
 *     the colour table with {@code colour >> 8} per pixel. Java's int division
 *     and shifts truncate exactly like the client's {@code | 0} arithmetic.</li>
 * <li>The three top-level cases order the vertices by smallest y; each splits
 *     again on edge-slope comparisons so the left/right raster arguments stay
 *     sorted without per-scanline swaps.</li>
 * <li>Only the paths this plugin exercises are ported: high detail
 *     ({@code lowDetail = false}), opaque ({@code trans = 0}), with horizontal
 *     clipping always on - the client's {@code hclip = false} path is a
 *     speed-up that skips clamping, not a different fill.</li>
 * <li>Colours interpolate as PACKED palette indices and resolve through
 *     {@link GameColourTable}, the same gamma table the game uses.</li>
 * </ul>
 */
final class GouraudRasterizer
{
	private final int[] pixels;
	private final int width;
	private final int sizeX;
	private final int clipMaxY;
	private final int[] scanline;

	GouraudRasterizer(int[] pixels, int width, int height)
	{
		this.pixels = pixels;
		this.width = width;
		this.sizeX = width;
		this.clipMaxY = height;
		this.scanline = new int[height];
		for (int y = 0; y < height; y++)
		{
			scanline[y] = width * y;
		}
	}

	@SuppressWarnings("java:S3776") // the client's control flow, kept verbatim
	void gouraudTriangle(int xA, int xB, int xC, int yA, int yB, int yC,
		int colourA, int colourB, int colourC)
	{
		int xStepAB = 0;
		int colourStepAB = 0;
		if (yB != yA)
		{
			xStepAB = ((xB - xA) << 16) / (yB - yA);
			colourStepAB = ((colourB - colourA) << 15) / (yB - yA);
		}

		int xStepBC = 0;
		int colourStepBC = 0;
		if (yC != yB)
		{
			xStepBC = ((xC - xB) << 16) / (yC - yB);
			colourStepBC = ((colourC - colourB) << 15) / (yC - yB);
		}

		int xStepAC = 0;
		int colourStepAC = 0;
		if (yC != yA)
		{
			xStepAC = ((xA - xC) << 16) / (yA - yC);
			colourStepAC = ((colourA - colourC) << 15) / (yA - yC);
		}

		if (yA <= yB && yA <= yC)
		{
			if (yA >= clipMaxY)
			{
				return;
			}
			if (yB > clipMaxY)
			{
				yB = clipMaxY;
			}
			if (yC > clipMaxY)
			{
				yC = clipMaxY;
			}

			if (yB < yC)
			{
				xC = xA <<= 16;
				colourC = colourA <<= 15;
				if (yA < 0)
				{
					xC -= xStepAC * yA;
					xA -= xStepAB * yA;
					colourC -= colourStepAC * yA;
					colourA -= colourStepAB * yA;
					yA = 0;
				}
				xB <<= 16;
				colourB <<= 15;
				if (yB < 0)
				{
					xB -= xStepBC * yB;
					colourB -= colourStepBC * yB;
					yB = 0;
				}
				if ((yA != yB && xStepAC < xStepAB) || (yA == yB && xStepAC > xStepBC))
				{
					yC -= yB;
					yB -= yA;
					yA = scanline[yA];
					while (true)
					{
						yB--;
						if (yB < 0)
						{
							while (true)
							{
								yC--;
								if (yC < 0)
								{
									return;
								}
								gouraudRaster(xC >> 16, xB >> 16, colourC >> 7, colourB >> 7, yA);
								xC += xStepAC;
								xB += xStepBC;
								colourC += colourStepAC;
								colourB += colourStepBC;
								yA += width;
							}
						}
						gouraudRaster(xC >> 16, xA >> 16, colourC >> 7, colourA >> 7, yA);
						xC += xStepAC;
						xA += xStepAB;
						colourC += colourStepAC;
						colourA += colourStepAB;
						yA += width;
					}
				}
				else
				{
					yC -= yB;
					yB -= yA;
					yA = scanline[yA];
					while (true)
					{
						yB--;
						if (yB < 0)
						{
							while (true)
							{
								yC--;
								if (yC < 0)
								{
									return;
								}
								gouraudRaster(xB >> 16, xC >> 16, colourB >> 7, colourC >> 7, yA);
								xC += xStepAC;
								xB += xStepBC;
								colourC += colourStepAC;
								colourB += colourStepBC;
								yA += width;
							}
						}
						gouraudRaster(xA >> 16, xC >> 16, colourA >> 7, colourC >> 7, yA);
						xC += xStepAC;
						xA += xStepAB;
						colourC += colourStepAC;
						colourA += colourStepAB;
						yA += width;
					}
				}
			}
			else
			{
				xB = xA <<= 16;
				colourB = colourA <<= 15;
				if (yA < 0)
				{
					xB -= xStepAC * yA;
					xA -= xStepAB * yA;
					colourB -= colourStepAC * yA;
					colourA -= colourStepAB * yA;
					yA = 0;
				}
				xC <<= 16;
				colourC <<= 15;
				if (yC < 0)
				{
					xC -= xStepBC * yC;
					colourC -= colourStepBC * yC;
					yC = 0;
				}
				if ((yA != yC && xStepAC < xStepAB) || (yA == yC && xStepBC > xStepAB))
				{
					yB -= yC;
					yC -= yA;
					yA = scanline[yA];
					while (true)
					{
						yC--;
						if (yC < 0)
						{
							while (true)
							{
								yB--;
								if (yB < 0)
								{
									return;
								}
								gouraudRaster(xC >> 16, xA >> 16, colourC >> 7, colourA >> 7, yA);
								xC += xStepBC;
								xA += xStepAB;
								colourC += colourStepBC;
								colourA += colourStepAB;
								yA += width;
							}
						}
						gouraudRaster(xB >> 16, xA >> 16, colourB >> 7, colourA >> 7, yA);
						xB += xStepAC;
						xA += xStepAB;
						colourB += colourStepAC;
						colourA += colourStepAB;
						yA += width;
					}
				}
				else
				{
					yB -= yC;
					yC -= yA;
					yA = scanline[yA];
					while (true)
					{
						yC--;
						if (yC < 0)
						{
							while (true)
							{
								yB--;
								if (yB < 0)
								{
									return;
								}
								gouraudRaster(xA >> 16, xC >> 16, colourA >> 7, colourC >> 7, yA);
								xC += xStepBC;
								xA += xStepAB;
								colourC += colourStepBC;
								colourA += colourStepAB;
								yA += width;
							}
						}
						gouraudRaster(xA >> 16, xB >> 16, colourA >> 7, colourB >> 7, yA);
						xB += xStepAC;
						xA += xStepAB;
						colourB += colourStepAC;
						colourA += colourStepAB;
						yA += width;
					}
				}
			}
		}
		else if (yB <= yC)
		{
			if (yB >= clipMaxY)
			{
				return;
			}
			if (yC > clipMaxY)
			{
				yC = clipMaxY;
			}
			if (yA > clipMaxY)
			{
				yA = clipMaxY;
			}

			if (yC < yA)
			{
				xA = xB <<= 16;
				colourA = colourB <<= 15;
				if (yB < 0)
				{
					xA -= xStepAB * yB;
					xB -= xStepBC * yB;
					colourA -= colourStepAB * yB;
					colourB -= colourStepBC * yB;
					yB = 0;
				}
				xC <<= 16;
				colourC <<= 15;
				if (yC < 0)
				{
					xC -= xStepAC * yC;
					colourC -= colourStepAC * yC;
					yC = 0;
				}
				if ((yB != yC && xStepAB < xStepBC) || (yB == yC && xStepAB > xStepAC))
				{
					yA -= yC;
					yC -= yB;
					yB = scanline[yB];
					while (true)
					{
						yC--;
						if (yC < 0)
						{
							while (true)
							{
								yA--;
								if (yA < 0)
								{
									return;
								}
								gouraudRaster(xA >> 16, xC >> 16, colourA >> 7, colourC >> 7, yB);
								xA += xStepAB;
								xC += xStepAC;
								colourA += colourStepAB;
								colourC += colourStepAC;
								yB += width;
							}
						}
						gouraudRaster(xA >> 16, xB >> 16, colourA >> 7, colourB >> 7, yB);
						xA += xStepAB;
						xB += xStepBC;
						colourA += colourStepAB;
						colourB += colourStepBC;
						yB += width;
					}
				}
				else
				{
					yA -= yC;
					yC -= yB;
					yB = scanline[yB];
					while (true)
					{
						yC--;
						if (yC < 0)
						{
							while (true)
							{
								yA--;
								if (yA < 0)
								{
									return;
								}
								gouraudRaster(xC >> 16, xA >> 16, colourC >> 7, colourA >> 7, yB);
								xA += xStepAB;
								xC += xStepAC;
								colourA += colourStepAB;
								colourC += colourStepAC;
								yB += width;
							}
						}
						gouraudRaster(xB >> 16, xA >> 16, colourB >> 7, colourA >> 7, yB);
						xA += xStepAB;
						xB += xStepBC;
						colourA += colourStepAB;
						colourB += colourStepBC;
						yB += width;
