	private JPanel rowShell()
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARKER_GRAY_COLOR),
			BorderFactory.createEmptyBorder(8, 0, 8, 8)));
		row.setAlignmentX(LEFT_ALIGNMENT);
		return row;
	}

	private JPanel labelledField(String label, JTextField field)
	{
		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setBackground(ColorScheme.DARK_GRAY_COLOR);
		line.setAlignmentX(LEFT_ALIGNMENT);
		line.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		JLabel l = new JLabel(label);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		line.add(l, BorderLayout.WEST);
		field.setFont(FontManager.getRunescapeFont());
		field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		field.setForeground(Color.WHITE);
		field.setCaretColor(Color.WHITE);
		line.add(field, BorderLayout.CENTER);
		return line;
	}

	private JTextArea sayArea(String text, int rows)
	{
		JTextArea area = new JTextArea(text, rows, 40);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setFont(FontManager.getRunescapeFont());
		area.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		area.setForeground(Color.WHITE);
		area.setCaretColor(Color.WHITE);
		area.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		area.setAlignmentX(LEFT_ALIGNMENT);
		return area;
	}

	private static JsonArray parseSay(String text)
	{
		JsonArray say = new JsonArray();
		for (String line : text.split("\n"))
		{
			String trimmed = line.trim();
			if (!trimmed.isEmpty())
			{
				say.add(trimmed);
			}
		}
		return say;
	}

	private static JsonArray parseRegions(String text, List<String> warnings)
	{
		JsonArray regions = new JsonArray();
		for (String token : text.split("[^0-9]+"))
		{
			if (token.isEmpty())
			{
				continue;
			}
			try
			{
				regions.add(Integer.parseInt(token));
			}
			catch (NumberFormatException e)
			{
				// An 11-digit paste used to abort the whole save with a raw
				// "For input string" - name the token and carry on instead.
				warnings.add("'" + token + "' isn't a region id the game uses - skipped");
			}
		}
		return regions;
	}

	private static JsonArray regionsOf(JsonObject rule)
	{
		JsonObject when = rule.has("when") && rule.get("when").isJsonObject()
			? rule.getAsJsonObject("when") : null;
		if (when == null)
		{
			return null;
		}
		String type = optString(when, "type");
		boolean regionBased = "inRegion".equalsIgnoreCase(type) || "regionEnter".equalsIgnoreCase(type);
		return regionBased && when.has("regions") ? when.getAsJsonArray("regions") : null;
	}

	private JsonObject readFile() throws IOException
	{
		return gson.fromJson(new String(Files.readAllBytes(file), StandardCharsets.UTF_8), JsonObject.class);
	}

	private void setStatus(String text, boolean error)
	{
		status.setText(text);
		status.setForeground(error ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
	}

	private static String optString(JsonObject object, String key)
	{
		return object.has(key) && object.get(key).isJsonPrimitive() ? object.get(key).getAsString() : null;
	}

	static String prettyName(String id)
	{
		if (id == null)
		{
			return "(new)";
		}
		String s = id;
		boolean set = false;
		if (s.startsWith("gear-set-"))
		{
			set = true;
			s = s.substring("gear-set-".length());
		}
		else if (s.startsWith("gear-"))
		{
			s = s.substring("gear-".length());
		}
		else if (s.startsWith("area-"))
		{
			s = s.substring("area-".length());
		}
		else if (s.startsWith("enter-"))
		{
			s = s.substring("enter-".length());
		}
		s = s.replace('-', ' ');
		s = Character.toUpperCase(s.charAt(0)) + s.substring(1);
		return set ? "Full " + s + " (set)" : s;
	}

	private static String escapeHtml(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.follower.ui;

import com.follower.sound.VoiceLibrary;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Gives a rule's lines their voices: one row per line, each with the sound
 * file that plays when the follower says it.
 *
 * <p>Files are chosen from a folder rather than through a file browser, and
 * deliberately so. It makes the arrangement obvious - these are your files, in
 * your folder, and the plugin only reads them - it survives the folder being
 * moved with the rest of the profile, and it gives somewhere honest to say the
 * one thing a player needs to know before they start: Java plays WAV, AIFF and
 * AU, and nothing else.
 */
@Slf4j
public class VoiceDialog extends JDialog
{
	private final VoiceLibrary voices;
	private final java.util.function.IntSupplier volume;

	public VoiceDialog(VoiceLibrary voices, java.util.function.IntSupplier volume)
	{
		super((java.awt.Frame) null, "Follower Buddy - Sounds", false);
		this.voices = voices;
		this.volume = volume;
		setDefaultCloseOperation(HIDE_ON_CLOSE);
		setPreferredSize(new Dimension(560, 520));
	}

	/**
	 * @param title what these lines belong to, for the header
	 * @param lines the rule's lines as they stand in the editor right now,
	 * unsaved edits included - a line has to exist before it can be voiced,
	 * but it does not have to have been saved
	 */
	public void open(String title, List<String> lines)
	{
		// Rebuilt every time: the lines may have been edited since last look,
		// and the folder may have gained files.
		voices.reload();
		List<String> files = voices.availableFiles();

		JPanel root = new JPanel(new BorderLayout(0, 8));
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);
		root.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JLabel hint = new JLabel("<html><body style='width:480px'>"
			+ "A sound plays when the follower says that line, and the line still"
			+ " appears as usual. Put your own files in the folder below and they"
			+ " turn up in these lists. Java plays <b>WAV, AIFF and AU</b> only -"
			+ " an MP3 will simply stay silent.</body></html>");
		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel header = new JPanel(new BorderLayout(6, 6));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.add(hint, BorderLayout.CENTER);

		// The path is SHOWN rather than opened. Opening a file manager needs
		// Desktop::open, which the Plugin Hub restricts - reasonably, since a
		// plugin handing paths to the operating system is a category of thing
		// they cannot review one use of. Shown and copyable answers the same
		// question ("where do my files go?") with nothing but a text field.
		JTextField where = new JTextField(
			voices.getSoundsFolder() == null ? "" : voices.getSoundsFolder().toString());
		where.setEditable(false);
		where.setFont(FontManager.getRunescapeSmallFont());
		where.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		where.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		where.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		where.setCaretPosition(0);

		JButton copy = new JButton("Copy path");
		copy.setToolTipText("Copy the sounds folder path to the clipboard");
		copy.addActionListener(e -> copyFolderPath());

		JPanel folderRow = new JPanel(new BorderLayout(6, 0));
		folderRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		folderRow.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		folderRow.add(where, BorderLayout.CENTER);
		folderRow.add(copy, BorderLayout.EAST);
		header.add(folderRow, BorderLayout.SOUTH);
		root.add(header, BorderLayout.NORTH);

		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);

		List<String> shown = new ArrayList<>();
		for (String line : lines)
		{
			String trimmed = line == null ? "" : line.trim();
			if (!trimmed.isEmpty() && !shown.contains(trimmed))
			{
				shown.add(trimmed);
				list.add(row(trimmed, files));
			}
		}
		if (shown.isEmpty())
		{
			JLabel empty = new JLabel("This one has no lines to give a voice to.");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			list.add(empty);
		}

		JScrollPane scroll = new JScrollPane(list,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		root.add(scroll, BorderLayout.CENTER);

		setTitle("Follower Buddy - Sounds for " + title);
		setContentPane(root);
		pack();
		setLocationRelativeTo(null);
		setVisible(true);
		toFront();
	}

	private JPanel row(String line, List<String> files)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARKER_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 0, 6, 4)));
		row.setAlignmentX(LEFT_ALIGNMENT);

		JLabel words = new JLabel("<html><body style='width:470px'>"
			+ escape(line) + "</body></html>");
		words.setFont(FontManager.getRunescapeSmallFont());
		words.setForeground(Color.WHITE);
		words.setAlignmentX(LEFT_ALIGNMENT);
		row.add(words);

		JPanel controls = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 2));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
		controls.setAlignmentX(LEFT_ALIGNMENT);
		controls.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));

		JComboBox<String> picker = new JComboBox<>();
		picker.addItem("(no sound)");
		for (String file : files)
		{
			picker.addItem(file);
		}
		String current = voices.attachmentFor(line);
		if (current != null)
		{
			if (!files.contains(current))
			{
				// Attached once, since deleted or renamed. Kept visible rather
				// than silently dropped, or the player cannot tell the
				// difference between a missing file and a lost setting.
				picker.addItem(current + "  (missing)");
				picker.setSelectedIndex(picker.getItemCount() - 1);
			}
			else
			{
				picker.setSelectedItem(current);
			}
		}
		picker.setPreferredSize(new Dimension(300, 24));
		picker.addActionListener(e ->
		{
			int index = picker.getSelectedIndex();
			voices.attach(line, index <= 0 ? null : files.get(index - 1));
		});
		controls.add(picker);

		JButton play = new JButton("Play");
		play.addActionListener(e ->
		{
			int index = picker.getSelectedIndex();
			if (index > 0 && index - 1 < files.size())
			{
				voices.preview(files.get(index - 1), volume.getAsInt());
			}
		});
		controls.add(play);

		row.add(controls);
		return row;
	}

	private void copyFolderPath()
	{
		java.nio.file.Path folder = voices.getSoundsFolder();
		if (folder == null)
		{
			return;
		}
		try
		{
			java.awt.Toolkit.getDefaultToolkit().getSystemClipboard().setContents(
				new java.awt.datatransfer.StringSelection(folder.toString()), null);
		}
		catch (Exception e)
		{
			// The path is on screen either way, so a clipboard that will not
			// take it costs the player a copy rather than the answer.
			log.warn("Could not copy {} to the clipboard", folder, e);
		}
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerContext;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.time.LocalDate;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The first twenty minutes, which decide whether there is a second session.
 *
 * <p>Almost everything the follower has to say about YOU is gated behind a
 * history it has not got yet, so a new player meets the encyclopaedia rather
 * than the character. Four one-time lines cover the gap, and they are the only
 * content in the file that a player can miss permanently by the plugin getting
 * it wrong.
 *
 * <p>Which is not hypothetical. The first draft of two of these rules used an
 * "all" shorthand the condition parser does not have; they loaded, evaluated
 * false forever, and would have shipped as four lines nobody ever heard. Hence
 * a test that fires each one for real rather than reading the file.
 */
public class ArrivalArcTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The bundled rules, with the follower's memory set to a given history. */
	private Harness known(int sessions, int daysAgo) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		TriggerContext context = h.engine.getContext();
		context.setSessionCount(sessions);
		if (daysAgo >= 0)
		{
			context.setMetOnDay(LocalDate.now().toEpochDay() - daysAgo);
		}
		h.gameTicks(1);
		return h;
	}

	/** Waits out the delayTicks the login lines carry, so the words come out. */
	private static void settle(Harness h)
	{
		h.gameTicks(10);
	}

	/**
	 * Runs the session clock forward a minute at a time, as the plugin's own
	 * timer does. Jumping it straight to the number a rule wants would step
	 * over every window on the way and prove nothing about the sequence.
	 */
	private static void minutesPass(Harness h, int upTo)
	{
		for (int minute = h.engine.getContext().getSessionMinutes() + 1; minute <= upTo; minute++)
		{
			h.engine.getContext().setSessionMinutes(minute);
			h.gameTicks(1);
		}
	}

	private static com.follower.speech.Condition sessionMinutesWindow(Harness h, String ruleId)
	{
		for (com.follower.speech.Condition part : h.rule(ruleId).when.conditions)
		{
			if ("sessionMinutes".equalsIgnoreCase(part.type))
			{
				return part;
			}
		}
		throw new AssertionError(ruleId + " no longer sits on the session clock");
	}

	// ----------------------------------------------------------- the first hello

	@Test
	public void theVeryFirstLoginIsNotTheEverydayGreeting() throws IOException
	{
		Harness h = known(1, 0);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);

		assertEquals("the first login has its own hello", 1, h.firedBy("first-meeting").size());
		assertTrue("and the everyday one stays out of its way",
			h.firedBy("login-greeting").isEmpty());
		assertTrue("in every era",
			h.firedBy("login-greeting-new").isEmpty());
	}

	@Test
	public void theSecondLoginIsTheEverydayGreetingAgain() throws IOException
	{
		// Same day, so this is a relog rather than a return - the arc's last
		// beat is about coming back TOMORROW and must not fire here. On day
		// zero the everyday hello wears its polite era (R16).
		Harness h = known(2, 0);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);

		assertTrue(h.firedBy("first-meeting").isEmpty());
		assertTrue(h.firedBy("first-return").isEmpty());
		assertEquals(1, h.firedBy("login-greeting-new").size());
	}

	@Test
	public void comingBackTheNextDayIsWorthSaying() throws IOException
	{
		Harness h = known(2, 1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);

		assertEquals("twice is how a habit starts", 1, h.firedBy("first-return").size());
		assertTrue(h.firedBy("login-greeting").isEmpty());
	}

	@Test
	public void aLongStandingPlayerGetsNoneOfIt() throws IOException
	{
		Harness h = known(400, 300);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);
		minutesPass(h, 90);

		for (String id : new String[]{"first-meeting", "first-page", "first-hour", "first-return"})
		{
			assertTrue(id + " is for a follower that has just met you",
				h.firedBy(id).isEmpty());
		}
	}

	// -------------------------------------------------------- inside the session

	@Test
	public void tenMinutesInItWritesSomethingDown() throws IOException
	{
		// Scheduled on purpose. Left to the gates that already exist, a new
		// player's first characterful moment waits on a tally, a record or a
		// place score - none of which they have.
		Harness h = known(1, 0);
		minutesPass(h, 9);
		assertTrue("not yet", h.firedBy("first-page").isEmpty());

		minutesPass(h, 10);
		assertEquals(1, h.firedBy("first-page").size());
	}

	@Test
	public void anHourInItAdmitsItHasNothingOnYou() throws IOException
	{
		Harness h = known(1, 0);
		minutesPass(h, 45);

		assertEquals(1, h.firedBy("first-hour").size());
	}

	@Test
	public void theTwoInSessionLinesCannotBothWinTheSameTick() throws IOException
	{
		// They sit on the same clock, and a rule that loses an evaluation pass
		// has still had its rising edge consumed by it - so an overlap is not a
		// line that arrives late, it is a line that never arrives at all. The
		// windows are made exclusive rather than trusted to arrive in order.
		Harness h = known(1, 0);
		assertTrue("the earlier beat must close before the later one opens",
			sessionMinutesWindow(h, "first-page").maximum != null);

		minutesPass(h, 60);
		assertEquals(1, h.firedBy("first-page").size());
		assertEquals(1, h.firedBy("first-hour").size());
	}

	@Test
	public void theFirstDaysLinesStopBeingTrueAfterTheFirstDays() throws IOException
	{
		Harness h = known(9, 30);
		minutesPass(h, 60);

		assertTrue(h.firedBy("first-page").isEmpty());
		assertTrue(h.firedBy("first-hour").isEmpty());
	}

	// ------------------------------------------------------------- and only once

	@Test
	public void noneOfItHappensTwice() throws IOException
	{
		Harness h = known(1, 0);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);
		minutesPass(h, 45);

		assertEquals(1, h.firedBy("first-meeting").size());
		assertEquals(1, h.firedBy("first-page").size());
		assertEquals(1, h.firedBy("first-hour").size());

		// A world hop, which resets every rule's edge state and would re-raise
		// each of these conditions from scratch.
		h.engine.resetForNewScene();
		h.clear();
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);
		h.gameTicks(2);

		for (String id : new String[]{"first-meeting", "first-page", "first-hour"})
		{
			assertTrue(id + " said itself a second time", h.firedBy(id).isEmpty());
		}
	}

	@Test
	public void everyArrivalLineIsMarkedBothOnceAndAnOccasion() throws IOException
	{
		// The two go together here and nowhere else. Missing "once" turns the
		// introduction into a catchphrase; missing "occasion" lets the director
		// swallow the one hearing the player was ever going to get.
		Harness h = new Harness(folder.newFolder().toPath());
		for (String id : new String[]{"first-meeting", "first-page", "first-hour", "first-return"})
		{
			assertTrue(id + " must be said only once", h.rule(id).isOnce());
			assertTrue(id + " must survive a relax period", h.rule(id).isOccasion());
			assertFalse(id + " must actually say something", h.rule(id).say.isEmpty());
		}
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Telling a swing from everything else a player does mid-interaction.
 *
 * <p>Interaction alone was the whole test, and interaction is sticky: it
 * outlives the fight that set it. Walk away from an NPC, start mining, and the
 * pickaxe's swing is filed as that weapon's attack animation. It happened - a
 * single 30-frame mining loop became the learned attack of six pickaxes and of
 * a shortbow, so the follower in ranged thrall mode shot its bow by mining
 * with it.
 *
 * <p>The fix is the rule TriggerContext already arrived at for the same
 * reason, applied to the observer that was still trusting interaction.
 */
public class AttackSightingTest
{
	@Test
	public void miningWithAStaleTargetIsNotASwing()
	{
		// The local player, interaction still pointing at a finished fight,
		// and the context reporting no combat.
		assertFalse("a pickaxe swing is not a bow shot",
			FollowerPlugin.sightingIsASwing(true, false, -1));
		assertFalse("nor is it one because something is still targeted",
			FollowerPlugin.sightingIsASwing(true, false, 30));
	}

	@Test
	public void anActualFightStillTeaches()
	{
		assertTrue("the whole point of the observer",
			FollowerPlugin.sightingIsASwing(true, true, 30));
	}

	@Test
	public void somebodyElseIsJudgedByTheirTarget()
	{
		// No varps but our own, so the evidence is the target wearing a health
		// bar - which only happens in combat.
		assertTrue("their target is in combat",
			FollowerPlugin.sightingIsASwing(false, false, 30));
		assertFalse("their target has no health bar, so this is not a fight",
			FollowerPlugin.sightingIsASwing(false, false, -1));
		assertFalse("and a dead target is not being swung at",
			FollowerPlugin.sightingIsASwing(false, false, 0));
	}

	@Test
	public void ourOwnCombatFlagDoesNotVouchForOtherPlayers()
	{
		// Being in a fight ourselves says nothing about the player mining
		// beside us, and reading it as though it did is how one bad animation
		// spreads across every weapon in sight.
		assertFalse("our fight is not their swing",
			FollowerPlugin.sightingIsASwing(false, true, -1));
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * R15: speech scales to attention. Three minutes with camera, feet and
 * hands all untouched and the world is playing to an empty chair - so the
 * follower stops performing to it, reactions included. Occasions still
 * land, the rules ABOUT the absence still speak into it, and any input at
 * all clears the state instantly.
 */
public class AttentionDamperTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"reaction\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"npcSpawn\", \"names\": [\"Goblin\"]},"
		+ " \"say\": [\"a goblin arrives\"]},"
		+ "{\"id\": \"warning\", \"group\": \"t\", \"cooldownMs\": 0, \"occasion\": true,"
		+ " \"when\": {\"type\": \"npcSpawn\", \"names\": [\"Dragon\"]},"
		+ " \"say\": [\"a dragon arrives\"]},"
		+ "{\"id\": \"absence\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"unattended\", \"ticks\": 250},"
		+ " \"say\": [\"gone, then\"]}]}";

	@Test
	public void answeringIsPresence() throws IOException
	{
		// Play report: a whole hands game played out and the follower never
		// said which hand it was. The game asks you to stand still to be
		// offered at all, and a player who then only clicks dialog options
		// moves neither camera nor feet - so three minutes in, the damper
		// decided the chair was empty and silenced the reveal, while the
		// person it was talking to was answering its question.
		//
		// Reading a question and choosing is the most direct evidence of a
		// person there is, so it clears the state like any other input.
		String rules = "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"reveal\", \"group\": \"t\", \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"answered\", \"is\": \"left\"},"
			+ " \"say\": [\"it was the other one\"]}]}";

		Harness h = new Harness(folder.newFolder().toPath(), rules);
		h.gameTicks(320);
		assertTrue("the damper should have engaged by now",
			h.engine.getContext().getUnattendedTicks() >= 300);

		h.dispatch(TriggerEvent.answered("left"));

		assertTrue("the follower went quiet on somebody who was talking to it",
			!h.firedBy("reveal").isEmpty());
		assertEquals("answering left the follower still thinking it was alone",
			0, h.engine.getContext().getUnattendedTicks());
	}

	/** A harness left genuinely alone: no camera, no feet, no hands, no events. */
	private Harness abandoned() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(320);
		return h;
	}

	@Test
	public void nobodyWatchingMeansNoPerformance() throws IOException
	{
		Harness h = abandoned();
		h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertTrue("a reaction played to an empty chair",
			h.firedBy("reaction").isEmpty());
	}

	@Test
	public void anyInputAtAllRestoresTheAudience() throws IOException
	{
		// The camera.
		Harness h = abandoned();
		h.game.cameraMoved();
		h.gameTicks(1);
		h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertEquals("the camera moving is presence", 1, h.firedBy("reaction").size());

		// The hands.
		Harness busy = abandoned();
		busy.game.animating(879);
		busy.gameTicks(1);
		busy.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertEquals("animating is presence", 1, busy.firedBy("reaction").size());

		// A real event, which cannot happen from the kettle.
		Harness fighting = abandoned();
		fighting.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));
		fighting.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertEquals("a fight starting is presence", 1, fighting.firedBy("reaction").size());
	}

	@Test
	public void theWarningStillLandsOnTheEmptyChair() throws IOException
	{
		// An occasion matters the moment they glance back at the screen.
		Harness h = abandoned();
		h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Dragon"));
		assertEquals("occasions are exempt from the damper",
			1, h.firedBy("warning").size());
	}

	@Test
	public void theAbsenceItselfMayStillBeRemarkedOn() throws IOException
	{
		// The gone-away jokes are ABOUT the empty chair; silencing them with
		// it would remove the only lines written for exactly this moment.
		Harness h = abandoned();
		assertEquals("the absence rules speak into the absence",
			1, h.firedBy("absence").size());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.SpeechRule;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower responding to the PLAYER rather than to the world.
 *
 * <p>The failure that matters here is a follower that answers everybody: a
 * "hello" in a crowded bank raises one chat event per person who says it, and a
 * companion that greets all of them is not a companion, it is a bot. Every case
 * below therefore checks the negative as well as the positive.
 */
public class AttentionTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void theFollowerGreetsYouAndNotTheStreet() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		h.someoneSays("Somebody Else", "hello");
		h.someoneSays("Another Person", "hi");
		// These rules carry a delayTicks, so a line that has WON is still only
		// pending. Asserting before the ticks pass would pass no matter what.
		h.gameTicks(6);
		assertTrue("a follower that greets the whole bank is not greeting you",
			h.firedBy("greet-back").isEmpty());

		h.playerSays("hello");
		h.gameTicks(8);
		assertFalse("your own hello, though", h.firedBy("greet-back").isEmpty());
	}

	@Test
	public void aGameMessageIsNotSomebodyTalking() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		// The game says plenty of things containing "hi" and "ty". None of them
		// are the player saying hello or thank you.
		h.dispatch(TriggerEvent.chat("You hit the target.",
			net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));
		h.dispatch(TriggerEvent.chat("Oh dear, you are dead!",
			net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));
		h.gameTicks(6);

		assertTrue("game messages must not be read as conversation",
			h.firedBy("greet-back").isEmpty() && h.firedBy("thanked").isEmpty());
	}

	@Test
	public void aWordInsideAnotherWordIsNotThatWord() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		h.playerSays("this city is huge");
		h.playerSays("pretty good drop");
		h.gameTicks(6);

		assertTrue("'hi' in 'this' and 'ty' in 'pretty' are not greetings or thanks",
			h.firedBy("greet-back").isEmpty() && h.firedBy("thanked").isEmpty());
	}

	@Test
	public void restingTheMouseOnItIsNoticedAndCrossingTheScreenIsNot() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setHoverTicks(2);
		h.gameTicks(3);
		assertTrue("a cursor passing over is not attention",
			h.firedBy("hovered").isEmpty());

		// The rule rolls a chance, so give it a fair number of chances.
		h.engine.getContext().setHoverTicks(30);
		for (int i = 0; i < 60 && h.firedBy("hovered").isEmpty(); i++)
		{
			h.engine.getContext().setHoverTicks(30);
			h.gameTicks(1);
		}
		assertFalse("resting on it is", h.firedBy("hovered").isEmpty());
	}

	@Test
	public void beingExaminedGetsAnAnswer() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		h.gameTicks(8);
		assertFalse("being looked up is worth noticing", h.firedBy("examined").isEmpty());
	}

	@Test
	public void theFlinchIsSilent() throws IOException
	{
		// A body that reacts before the mouth does is most of what makes
		// something look like it is watching. A line here would just be one
		// more thing said during a fight that is already noisy.
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule flinch = h.rule("flinch-big-hit");

		assertTrue("the flinch must not speak",
			flinch.say == null || flinch.say.isEmpty());
		assertFalse("but it must do something", flinch.animation == null);

		// One winner per event, so an animation-only rule is invisible for any
		// hit a higher-priority spoken rule also matches. big-hit-taken owns
		// everything from 30 up, which was the whole top of the range - the
		// biggest hits were the ones that did NOT flinch. The body language has
		// to live on whichever rule actually wins the moment.
		SpeechRule spoken = h.rule("big-hit-taken");
		assertTrue("big-hit-taken outranks the flinch and must carry it too",
			spoken.priority <= flinch.priority
				|| flinch.animation.equals(spoken.animation));
	}

	@Test
	public void anythingThatVanishesHoldsStillWhileItGoes()
	{
		// A rule that vanishes is playing a departure - a teleport cast, a
		// comedy death - and a departure has to finish where it started.
		//
		// The case that found this: the player teleports while the follower is
		// off on an idle distraction. The player animating resets the idle
		// counter, so the wander is released that same tick, and the follower
		// abandons its own cast to run back to somebody who is no longer
		// standing there. Holding still also keeps the wander logic out
		// entirely, since it treats a held emote as busy.
		Harness h;
		try
		{
			h = new Harness(folder.newFolder().toPath());
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}

		java.util.List<String> loose = new java.util.ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (Boolean.TRUE.equals(rule.vanishAfter)
				&& !Boolean.TRUE.equals(rule.holdStill))
			{
				loose.add(rule.id);
			}
		}
		assertTrue("rules that vanish without planting the follower first,"
			+ " so anything that moves it mid-animation cuts the exit short: "
			+ loose, loose.isEmpty());
	}

	@Test
	public void theBagWarningComesWhileThereIsStillRoom() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());

		h.game.inventoryUsing(24);
		h.gameTicks(3);
		assertTrue("four slots left is not a warning",
			h.firedBy("bag-nearly-full").isEmpty());

		h.game.inventoryUsing(26);
		h.gameTicks(3);
		assertFalse("two slots left is the moment to say so",
			h.firedBy("bag-nearly-full").isEmpty());

		assertEquals("and the point is that it is not full yet",
			2, h.engine.getContext().getFreeInventorySlots());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A boss gets its own send-off, not the one every fight gets.
 *
 * <p>combat-end and kill-boss-celebrate are different EVENTS, so priority
 * never compares them and both used to fire. The celebration also carries a
 * deliberate 13 to 16 tick delay so the ward can wind down first, which meant
 * a boss was seen off with "Well fought" and then congratulated properly eight
 * seconds later, in that order. The generic line now stands aside.
 */
public class BossGetsItsOwnSendOffTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Harness fightWith(String name) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setBossNames(h.loader.getBossNames());
		h.dispatch(TriggerEvent.combat(TriggerEvent.Type.COMBAT_END, name));
		h.gameTicks(3);
		return h;
	}

	@Test
	public void anOrdinaryFightStillGetsTheGenericLine() throws IOException
	{
		assertEquals("the send-off every fight gets",
			1, fightWith("Guard").firedBy("combat-end").size());
	}

	@Test
	public void aBossDoesNotGetTheGenericLine() throws IOException
	{
		assertTrue("a boss has its own send-off and does not want talking over",
			fightWith("Brutus").firedBy("combat-end").isEmpty());
	}

	@Test
	public void theBossListIsWhatDecidesIt() throws IOException
	{
		// Named in a boss rule, so it counts however small it fights.
		assertTrue(fightWith("Vorkath").firedBy("combat-end").isEmpty());
		// Not named anywhere, so it is an ordinary fight.
		assertEquals(1, fightWith("Giant rat").firedBy("combat-end").size());
	}
}

package com.follower;

import com.follower.speech.Condition;
import com.follower.speech.RuleLoader;
import com.follower.speech.TriggerContext;
import com.follower.sim.Harness;
import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A boss is not a combat level.
 *
 * <p>It was one, in two places that had to be kept agreeing by hand: the
 * spectating shield asked whether the thing being fought was level 100, and
 * the kill celebration asked the same of the thing that died. Both are proxies
 * and both fail the same way. Brutus fights at thirty, so the follower stood
 * its ground through the whole fight and said nothing when he went down, while
 * the boss rules written for him that same day fired perfectly - two
 * definitions of one word, and only the weaker one consulted.
 *
 * <p>The names the boss rules already list are the other half of the answer,
 * so that list is now the answer and the rule file is the only place it lives.
 * These tests hold both halves: what is named counts however small, and what
 * is merely large still counts without anybody having named it.
 */
public class BossIsNotACombatLevelTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES = "{'rules':["
		+ "{'id':'boss-brutus','group':'boss','when':{'type':'npcSpawn',"
		+ "'names':['Brutus']},'say':['x']},"
		+ "{'id':'boss-inferno','group':'boss','when':{'type':'npcSpawn',"
		+ "'names':['Jal-*']},'say':['x']},"
		+ "{'id':'boss-low','group':'boss','when':{'type':'all','conditions':["
		+ "{'type':'healthBelow','percent':50},"
		+ "{'type':'npcNearby','within':12,'names':['Vorkath']}]},'say':['x']},"
		+ "{'id':'chat-rat','group':'combat','when':{'type':'npcSpawn',"
		+ "'names':['Giant rat']},'say':['x']}]}";

	private TriggerContext contextFor(String rulesJson) throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve("phrases.json"),
			rulesJson.replace('\'', '"').getBytes(StandardCharsets.UTF_8));

		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);

		TriggerContext context = new TriggerContext(null);
		context.setBossNames(loader.getBossNames());
		return context;
	}

	@Test
	public void aBossThatFightsBelowItsWeightStillCounts() throws Exception
	{
		assertTrue("Brutus fights at 30 and is still a boss",
			contextFor(RULES).isBoss("Brutus", 30));
	}

	@Test
	public void somethingMerelyLargeStillCountsWithoutBeingNamed() throws Exception
	{
		assertTrue("the level is still half the answer",
			contextFor(RULES).isBoss("Some Future Boss", 640));
	}

	@Test
	public void anOrdinaryMonsterIsStillOrdinary() throws Exception
	{
		TriggerContext context = contextFor(RULES);
		assertFalse("a rat named in a rule that is not a boss rule is not a boss",
			context.isBoss("Giant rat", 30));
		assertFalse("nor is anything else small and unlisted",
			context.isBoss("Man", 2));
	}

	@Test
	public void theNamesComeFromEveryShapeOfBossRule() throws Exception
	{
		TriggerContext context = contextFor(RULES);
		assertTrue("a wildcard boss name still matches",
			context.isBoss("Jal-Nib", 32));
		assertTrue("a name nested inside a combinator is collected too",
			context.isBoss("Vorkath", 1));
	}

	/** The game pads names with non-breaking spaces; the matcher is shared. */
	@Test
	public void paddedNamesDoNotHideABoss() throws Exception
	{
		assertTrue("padded the way the game pads it",
			contextFor(RULES).isBoss(" Brutus ", 30));
		assertEquals("Brutus", Condition.normaliseName(" Brutus "));
	}

	@Test
	public void theShippedRulesNameBrutusAsABoss() throws Exception
	{
		Harness harness = new Harness(folder.newFolder().toPath());
		TriggerContext context = new TriggerContext(null);
		context.setBossNames(harness.loader.getBossNames());

		assertTrue("Brutus, from the rules that ship",
			context.isBoss("Brutus", 30));
		assertTrue("and the form he turns into",
			context.isBoss("Demonic Brutus", 1224));
		assertFalse("while the shipped set has not swallowed everything",
			context.isBoss("Guard", 21));
		assertFalse("nor anything merely nearby in a non-boss rule",
			context.isBoss("Hans", 0));
	}
}

package com.follower;

import com.follower.ui.GameFont;
import com.follower.ui.GameFontRepository;
import com.google.gson.Gson;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The font dump as a fresh install sees it.
 *
 * <p>Development machines have their own fonts.json in the data directory,
 * which takes precedence, so the bundled copy is the one path that is never
 * exercised while working on the plugin - and the one every hub user gets. The
 * dump is trimmed to the two fonts the plugin draws with, and nothing else
 * would notice if that trim took one too many.
 */
public class BundledFontsTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private GameFontRepository loadAsAFreshInstall() throws IOException
	{
		GameFontRepository fonts = new GameFontRepository(new Gson());
		// An empty directory: no override, so this is the bundled resource.
		fonts.load(folder.newFolder().toPath());
		return fonts;
	}

	@Test
	public void theBundledDumpLoads() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();
		assertTrue("the bundled dump did not load: " + fonts.getStatus(), fonts.isLoaded());
	}

	@Test
	public void bothFontsThePluginDrawsWithArePresent() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();

		assertNotNull("font 497 is FollowerDialog's DIALOG_FONT_ID", fonts.get(497));
		assertNotNull("b12_full is what FollowerOverlay draws the overhead line with",
			fonts.getByName("b12_full"));
	}

	@Test
	public void theTrimmedDumpCarriesNothingElse() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();
		// Not a correctness requirement, a size one: if a font creeps back in,
		// the jar grows by tens of kilobytes for glyphs nothing asks for.
		for (int id : new int[]{494, 495, 645, 646, 764, 819, 1442, 1447, 6315})
		{
			assertEquals("font " + id + " is bundled but never drawn with",
				null, fonts.get(id));
		}
	}

	@Test
	public void theFontsCanActuallyMeasureAndDrawText() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();

		for (int id : new int[]{496, 497})
		{
			GameFont font = fonts.get(id);
			assertTrue("font " + id + " has no line height", font.getLineHeight() > 0);
			int width = font.stringWidth("The quick brown fox, 0123456789!");
			assertTrue("font " + id + " measured a real sentence as " + width, width > 0);
		}
	}
}

package com.follower;

import com.follower.speech.RuleLoader;
import com.follower.speech.SpeechRule;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The rules file being read on the game thread while it is written on another.
 *
 * <p>This really happens: the plugin polls the file every game tick so edits go
 * live within a second, and the phrase editors write it from the Swing thread.
 * Nothing coordinates the two. The editor now writes to a sibling and renames,
 * which is what makes a torn read impossible - but the loader still has to hold
 * up on its own, because a user editing in Notepad gets no such courtesy.
 *
 * <p>Two things must hold whatever the interleaving: nothing thrown onto the
 * game thread, and the follower never left mute. Losing a personality file to a
 * half-written save would be far worse than running the previous rules for
 * another second.
 */
public class ConcurrentReloadTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static String rules(int count, String tag)
	{
		StringBuilder out = new StringBuilder("{\"version\": 1, \"rules\": [");
		for (int i = 0; i < count; i++)
		{
			if (i > 0)
			{
				out.append(',');
			}
			out.append("{\"id\": \"r").append(i).append("\", \"group\": \"t\","
				+ " \"when\": {\"type\": \"always\"}, \"say\": [\"").append(tag)
				.append(' ').append(i).append("\"]}");
		}
		return out.append("]}").toString();
	}

	/** In place, the way a text editor does it: truncate, then write. */
	private static void writeInPlace(Path file, String contents) throws IOException
	{
		Files.write(file, contents.getBytes(StandardCharsets.UTF_8));
	}

	/**
	 * Sibling and rename, the way the phrase editors do it - including the
	 * retry, because Windows will not replace a file another handle has open
	 * and the plugin opens this one every tick.
	 */
	private static void writeAtomically(Path file, String contents) throws IOException
	{
		Path temp = file.resolveSibling(file.getFileName() + ".tmp");
		byte[] bytes = contents.getBytes(StandardCharsets.UTF_8);
		Files.write(temp, bytes);

		for (int attempt = 0; attempt < 20; attempt++)
		{
			try
			{
				Files.move(temp, file,
					StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
				return;
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(temp, file, StandardCopyOption.REPLACE_EXISTING);
				return;
			}
			catch (java.nio.file.FileSystemException e)
			{
				try
				{
					Thread.sleep(25);
				}
				catch (InterruptedException interrupted)
				{
					Thread.currentThread().interrupt();
					return;
				}
			}
		}

		Files.write(file, bytes);
		Files.deleteIfExists(temp);
	}

	private interface Writer
	{
		void write(Path file, String contents) throws IOException;
	}

	/**
	 * Hammers the file from one thread while polling it from another.
	 *
	 * @return how many polls came back with a parse error
	 */
	private int hammer(Writer writer) throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Path file = dir.resolve(RuleLoader.FILE_NAME);
		writer.write(file, rules(200, "first"));

		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);
		assertFalse("nothing loaded to begin with", loader.getRules().isEmpty());

		AtomicBoolean stop = new AtomicBoolean();
		AtomicReference<Throwable> thrown = new AtomicReference<>();

		Thread scribe = new Thread(() ->
		{
			try
			{
				for (int i = 0; !stop.get() && i < 400; i++)
				{
					writer.write(file, rules(200, "pass" + i));
				}
			}
			catch (Throwable t)
			{
				thrown.compareAndSet(null, t);
			}
		});
		scribe.setDaemon(true);
		scribe.start();

		int errors = 0;
		try
		{
			for (int i = 0; i < 4000 && scribe.isAlive(); i++)
			{
				// Exactly what the tick handler does.
				loader.reloadIfChanged();
				if (!loader.getErrors().isEmpty())
				{
					errors++;
				}
				assertFalse("the follower went mute mid-edit",
					loader.getRules().isEmpty());
			}
		}
		finally
		{
			stop.set(true);
			scribe.join(10000);
		}

		if (thrown.get() != null)
		{
			throw new AssertionError("the writer failed: " + thrown.get(), thrown.get());
		}
		return errors;
	}

	@Test
	public void anInPlaceWriterNeverSilencesTheFollower() throws Exception
	{
		// A user editing in Notepad. Torn reads are possible here and the
		// loader is allowed to complain about them - it just may not lose the
		// rules it already had, and may not throw onto the game thread.
		hammer(ConcurrentReloadTest::writeInPlace);
	}

	@Test
	public void theEditorsWriteSurvivesAReaderHoldingTheFile() throws Exception
	{
		// The rename path, which on Windows loses to an open handle. It must
		// not give up and lose the user's edits: retrying, and falling back to
		// an in-place write, is what keeps the save succeeding. Reaching the
		// fallback means a torn read is possible again, which is why the
		// loader keeping its previous rules is the test above and not an
		// afterthought.
		hammer(ConcurrentReloadTest::writeAtomically);
	}

	@Test
	public void theRuleListIsSwappedWholeNeverPartially() throws Exception
	{
		// Whatever a reader catches, it must be one complete set of rules -
		// never a list being filled in as it reads.
		Path dir = folder.newFolder().toPath();
		Path file = dir.resolve(RuleLoader.FILE_NAME);
		writeAtomically(file, rules(300, "first"));

		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);

		AtomicBoolean stop = new AtomicBoolean();
		Thread scribe = new Thread(() ->
		{
			try
			{
				for (int i = 0; !stop.get() && i < 300; i++)
				{
					writeAtomically(file, rules(300, "pass" + i));
				}
			}
			catch (IOException ignored)
			{
				// The assertion below is what matters.
			}
		});
		scribe.setDaemon(true);
		scribe.start();

		try
		{
			for (int i = 0; i < 3000 && scribe.isAlive(); i++)
			{
				loader.reloadIfChanged();
				List<SpeechRule> snapshot = loader.getRules();
				assertTrue("read a set of " + snapshot.size() + " rules, which is"
					+ " neither empty nor the full 300", snapshot.size() == 300);
				for (SpeechRule rule : snapshot)
				{
					assertFalse("a rule arrived without an id", rule.id == null);
				}
			}
		}
		finally
		{
			stop.set(true);
			scribe.join(10000);
		}
	}
}

package com.follower;

import com.follower.appearance.Outfit;
import com.follower.appearance.OutfitParser;
import com.follower.sim.Harness;
import com.follower.speech.SpeechOutput;
import com.follower.speech.SpeechRule;
import java.io.IOException;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The settings a player has before they touch anything.
 *
 * <p>Defaults are the one configuration almost every user runs, and the one
 * nobody tests: RuneLite writes them into the profile on first read, after
 * which changing a default in code has no effect on that install at all. So a
 * default that is wrong ships wrong and stays wrong.
 */
public class ConfigDefaultsTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final FollowerConfig config = new FollowerConfig()
	{
	};

	// ------------------------------------------------------------- first run

	/**
	 * Asked for explicitly: a first-time user should see a plain character with
	 * no gear and the default body kit, not somebody else's costume.
	 */
	@Test
	public void aFreshInstallShowsABaseCharacter()
	{
		assertEquals("the shipped outfit must be empty", "", config.customOutfit());

		Outfit outfit = OutfitParser.parse(config.customOutfit());
		assertTrue("an empty outfit string must parse to an empty outfit",
			outfit.isEmpty());
		assertFalse("and still produce a body once the default kits are filled in",
			outfit.withDefaultBody().isEmpty());
	}

	@Test
	public void theFollowerHasANameAndItIsNotBlank()
	{
		assertNotNull(config.followerName());
		assertFalse(config.followerName().trim().isEmpty());
	}

	@Test
	public void theFollowerIsFollowingAndAudibleOutOfTheBox()
	{
		assertTrue("a follower that does not follow is not much of one",
			config.followEnabled());
		assertFalse("shipped muted would read as broken", config.muted());
		assertNotNull(config.defaultOutput());
	}

	@Test
	public void everyPhraseGroupIsOnByDefault()
	{
		assertTrue(config.groupBoss());
		assertTrue(config.groupHealth());
		assertTrue(config.groupArea());
		assertTrue(config.groupIdle());
		assertTrue(config.groupGear());
		assertTrue(config.groupQuest());
		assertTrue(config.groupCombat());
		assertTrue(config.groupMimic());
		assertEquals("nothing should be silenced before the user asks",
			"", config.disabledGroups());
	}

	@Test
	public void theDiagnosticsAreOffForEveryoneElse()
	{
		assertFalse("developer commands must not ship enabled",
			config.developerMode());
	}

	// --------------------------------------------------------------- ranges

	@Test
	public void timingsArePositive()
	{
		assertTrue("speech that vanishes instantly cannot be read",
			config.speechDurationMs() > 0);
		assertTrue("a line has to be given some time per character",
			config.readingSpeed() > 0);

		// The raw milliseconds box became a named setting; every level still
		// has to leave a gap, and they have to run in the order they read.
		com.follower.speech.Chattiness previous = null;
		for (com.follower.speech.Chattiness level : com.follower.speech.Chattiness.values())
		{
			assertTrue(level + " must leave some gap", level.getGapMs() > 0);
			if (previous != null)
			{
				assertTrue(level + " should talk more than " + previous,
					level.getGapMs() < previous.getGapMs());
			}
			previous = level;
		}
	}

	@Test
	public void animationAndGraphicIdsAreRealNumbers()
	{
		int[] ids = {
			config.spectateShieldAnimation(),
			config.spectateShieldChannelStart(),
			config.spectateShieldChannelEnd(),
			config.spectateShieldChannelAnimation(),
			config.spectateShieldEndAnimation(),
			config.spectateShieldGraphic(),
			config.spectateShieldChannelGraphic(),
			config.spectateShieldEndGraphic(),
			config.restAnimation(),
		};
		for (int id : ids)
		{
			assertTrue("a negative id would be dropped silently: " + id, id >= 0);
		}
		assertTrue("the rest pose has to be something", config.restAnimation() > 0);
	}

	@Test
	public void theThrallProfilesPointAtProfilesThatExist() throws IOException
	{
		com.follower.appearance.OutfitProfileStore store =
			new com.follower.appearance.OutfitProfileStore(new com.google.gson.Gson());
		store.load(folder.newFolder().toPath());

		for (String name : new String[]{config.thrallMeleeProfile(),
			config.thrallRangedProfile(), config.thrallMagicProfile()})
		{
			assertNotNull("thrall mode points at a profile that a fresh install"
				+ " does not have: " + name, store.get(name));
		}
	}

	// ------------------------------------------------------ code and settings

	@Test
	public void everyGroupTheRulesUseHasASwitchInTheSettings() throws IOException
	{
		// Derived from the config interface rather than a hand-kept list, so
		// adding a groupX() switch is enough to cover a new group.
		Set<String> switchable = new HashSet<>();
		for (Method method : FollowerConfig.class.getMethods())
		{
			String name = method.getName();
			if (name.startsWith("group") && name.length() > 5
				&& method.getParameterCount() == 0)
			{
				switchable.add(name.substring(5).toLowerCase(java.util.Locale.ROOT));
			}
		}
		// Groups deliberately without a switch of their own.
		switchable.add("misc");
		switchable.add("errand");
		switchable.add("thrall");
		switchable.add("reactions");

		Harness h = new Harness(folder.newFolder().toPath());
		Set<String> orphans = new TreeSet<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (!switchable.contains(rule.group))
			{
				orphans.add(rule.group);
			}
		}
		assertTrue("rule groups a user cannot switch off: " + orphans, orphans.isEmpty());
	}

	@Test
	public void everySettingIsInASectionAndHasSomethingToSay()
	{
		List<String> problems = new ArrayList<>();
		for (Method method : FollowerConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			if (item.name().trim().isEmpty())
			{
				problems.add(method.getName() + " has no name");
			}
			if (item.description().trim().isEmpty())
			{
				problems.add(method.getName() + " has no description");
			}
			if (item.keyName().trim().isEmpty())
			{
				problems.add(method.getName() + " has no key");
			}
		}
		assertTrue("settings a user would see as blank: " + problems, problems.isEmpty());
	}

	@Test
	public void everySettingKeyIsUnique()
	{
		Set<String> seen = new HashSet<>();
		List<String> duplicates = new ArrayList<>();
		for (Method method : FollowerConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null && !seen.add(item.keyName()))
			{
				// Two settings sharing a key would overwrite each other in the
				// saved profile, and the loser would silently never persist.
				duplicates.add(item.keyName());
			}
		}
		assertTrue("settings sharing a storage key: " + duplicates, duplicates.isEmpty());
	}

	@Test
	public void sectionsDoNotFightOverTheSamePosition()
	{
		Set<Integer> seen = new HashSet<>();
		List<String> clashes = new ArrayList<>();
		for (java.lang.reflect.Field field : FollowerConfig.class.getDeclaredFields())
		{
			ConfigSection section = field.getAnnotation(ConfigSection.class);
			if (section != null && !seen.add(section.position()))
			{
				clashes.add(section.name() + " at " + section.position());
			}
		}
		assertTrue("sections with the same position order arbitrarily: " + clashes,
			clashes.isEmpty());
	}

	@Test
	public void everySettingNamedAsAPercentageIsOne()
	{
		// A percentage that ships outside 0-100 can never be reached by the
		// slider, so the setting is dead on arrival.
		assertTrue(config.speechDurationMs() > 100);
		assertEquals("the default output must be one the parser knows",
			config.defaultOutput(),
			SpeechOutput.parse(config.defaultOutput().name(), SpeechOutput.OVERHEAD));
	}

	@Test
	public void theSpawnAnimationSettingIsSomethingTheCodeCanRead()
	{
		String spawn = config.spawnAnimation();
		assertNotNull(spawn);
		assertFalse("a blank spawn setting would read as no animation at all",
			spawn.trim().isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Noticing repetition: how many, and how long.
 *
 * <p>Both are the same idea from the player's side - the follower has been
 * paying attention - and they are the cheapest way to make it seem so. The
 * count is kept where the kill is raised so the tally and the event can never
 * disagree; the duration is measured off the animation, which means it covers
 * every skill at once without knowing what any of them are.
 */
public class CountingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static String rules(String... bodies)
	{
		return "{\"version\": 1, \"rules\": [" + String.join(",", bodies) + "]}";
	}

	// ---------------------------------------------------------------- tallies

	@Test
	public void aTallyCountsEachThingSeparately() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		assertEquals(1, h.engine.getContext().tally("kill:goblin"));
		assertEquals(2, h.engine.getContext().tally("kill:goblin"));
		assertEquals("a different thing has its own count",
			1, h.engine.getContext().tally("kill:rat"));
		assertEquals(2, h.engine.getContext().getTally("kill:goblin"));
		assertEquals("something never counted is zero, not an error",
			0, h.engine.getContext().getTally("kill:dragon"));
	}

	@Test
	public void everyFiresOnTheMultiplesAndNotBetween() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"milestone\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\", \"every\": 5},"
				+ " \"say\": [\"{count}\"]}"));

		h.gameTicks(1);
		for (int count = 1; count <= 20; count++)
		{
			h.dispatch(TriggerEvent.kill(1, "Goblin", 5, count));
			h.gameTick();
		}

		assertEquals("fifth, tenth, fifteenth, twentieth", 4, h.firedBy("milestone").size());
		assertEquals("5", h.firedBy("milestone").get(0).text);
		assertEquals("20", h.firedBy("milestone").get(3).text);
	}

	@Test
	public void aKillWithNoCountNeverTripsAMilestone() throws IOException
	{
		// count 0 is "nobody counted", which must not read as a multiple of
		// everything.
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"milestone\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\", \"every\": 5}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		for (int i = 0; i < 10; i++)
		{
			h.dispatch(TriggerEvent.kill(1, "Goblin", 5));
			h.gameTick();
		}

		assertTrue(h.firedBy("milestone").isEmpty());
	}

	@Test
	public void aKillRuleWithNoEveryStillFiresOnEveryKill() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"each\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\"}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		for (int count = 1; count <= 5; count++)
		{
			h.dispatch(TriggerEvent.kill(1, "Goblin", 5, count));
			h.gameTick();
		}

		assertEquals("adding every must not have changed the plain case",
			5, h.firedBy("each").size());
	}

	@Test
	public void theCountPlaceholderCarriesTheNumber() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"tally\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\"},"
				+ " \"say\": [\"that is {count} of {npc}\"]}"));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.kill(1, "Goblin", 5, 42));

		assertEquals("that is 42 of Goblin", h.spoken.get(0).text);
	}

	// -------------------------------------------------------------- repeating

	@Test
	public void doingTheSameThingClimbsTheCounter() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(30);

		assertTrue("thirty ticks of one animation should have been noticed",
			h.engine.getContext().getRepeatingTicks() >= 25);
		assertEquals(879, h.engine.getContext().getRepeatingAnimation());
	}

	@Test
	public void aBriefGapDoesNotResetIt() throws IOException
	{
		// Most gathering drops to no animation for a tick between swings, and
		// treating that as stopping would hold the count at zero forever.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(20);
		int before = h.engine.getContext().getRepeatingTicks();

		h.game.animating(-1);
		h.gameTicks(2);
		h.game.animating(879);
		h.gameTicks(5);

		assertTrue("a two tick pause is a swing, not a stop: was " + before
				+ ", now " + h.engine.getContext().getRepeatingTicks(),
			h.engine.getContext().getRepeatingTicks() > before);
	}

	@Test
	public void actuallyStoppingResetsIt() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(30);

		h.game.animating(-1);
		h.gameTicks(20);

		assertEquals("standing about is not doing something",
			0, h.engine.getContext().getRepeatingTicks());
	}

	@Test
	public void switchingActivityStartsTheCountAgain() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(30);

		h.game.animating(624);
		h.gameTicks(3);

		assertEquals(624, h.engine.getContext().getRepeatingAnimation());
		assertTrue("a different activity is a new count, not a continuation",
			h.engine.getContext().getRepeatingTicks() <= 3);
	}

	@Test
	public void aRuleCanWaitForAWhileOfTheSameThing() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"noticed\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"repeating\", \"ticks\": 50},"
				+ " \"say\": [\"still at it\"]}"));

		h.game.animating(879);
		h.gameTicks(20);
		assertTrue("twenty ticks is not yet a while", h.firedBy("noticed").isEmpty());

		h.gameTicks(40);
		assertFalse("sixty is", h.firedBy("noticed").isEmpty());
	}

	@Test
	public void aRepeatingRuleCanNameTheAnimationsItCaresAbout() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"chopping\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"repeating\", \"ticks\": 20, \"ids\": [879]},"
				+ " \"say\": [\"timber\"]}"));

		h.game.animating(624);
		h.gameTicks(40);
		assertTrue("a different activity must not match", h.firedBy("chopping").isEmpty());

		h.game.animating(879);
		h.gameTicks(40);
		assertFalse(h.firedBy("chopping").isEmpty());
	}

	// ------------------------------------------------------------ the rule set

	@Test
	public void theShippedMilestonesRiseInOrder() throws IOException
	{
		// The hundredth must outrank the twenty-fifth, or the round number
		// loses to the smaller one when both come up on the same kill.
		Harness h = new Harness(folder.newFolder().toPath());

		assertTrue("the hundred milestone must win when they coincide",
			h.rule("kill-tally-hundred").priority > h.rule("kill-tally").priority);
		assertEquals(25, h.rule("kill-tally").when.every.intValue());
		assertEquals(100, h.rule("kill-tally-hundred").when.every.intValue());
		assertTrue("the longer wait must outrank the shorter one",
			h.rule("repeating-a-long-while").priority
				> h.rule("repeating-a-while").priority);
	}
}

package com.follower;

import com.follower.appearance.ModelRepository;
import com.follower.appearance.PaletteHarvest;
import com.follower.appearance.SpotAnimRepository;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The files in {@code ~/.runelite/follower} on a bad day.
 *
 * <p>These are dumps and caches rather than settings, and every one of them is
 * loaded during startUp. A throw there does not degrade a feature, it aborts
 * the whole plugin: RuneLite catches it and switches Follower Buddy off. So the
 * bar for all of them is the same - a missing file, an empty file, a truncated
 * file or outright junk has to leave the plugin running, however little it can
 * do afterwards.
 */
public class DataFileRobustnessTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The ways a file on disk actually goes wrong. */
	private static final String[] BROKEN = {
		"",
		"   ",
		"null",
		"{",
		"[]",
		"[1, 2, 3]",
		"\"a string\"",
		"{\"version\": 999}",
		"{\"version\": 1}",
		"{\"version\": 1, \"items\": null}",
		"{\"version\": 1, \"spotanims\": null}",
		"not json at all",
		"{\"truncated\": ",
	};

	private Path dir() throws IOException
	{
		return folder.newFolder().toPath();
	}

	private Path write(String name, String contents) throws IOException
	{
		Path dir = dir();
		Files.write(dir.resolve(name), contents.getBytes(StandardCharsets.UTF_8));
		return dir;
	}

	// --------------------------------------------------------------- missing

	@Test
	public void everyStoreCopesWithAnEmptyDataDirectory() throws IOException
	{
		Path empty = dir();

		SpotAnimRepository spotAnims = new SpotAnimRepository(new Gson());
		spotAnims.load(empty);
		assertNotNull(spotAnims.getStatus());

		ModelRepository models = new ModelRepository(new Gson());
		models.load(empty);
		assertNotNull(models.getStatus());

		PaletteHarvest palette = new PaletteHarvest(new Gson());
		palette.load(empty);
		assertEquals(0, palette.size());
	}

	@Test
	public void aMissingDumpLeavesAnEmptyRepositoryNotAnException() throws IOException
	{
		SpotAnimRepository spotAnims = new SpotAnimRepository(new Gson());
		spotAnims.load(dir());

		assertEquals("nothing should be found in an empty repository",
			null, spotAnims.get(246));
	}

	// -------------------------------------------------------------- corrupt

	@Test
	public void aCorruptSpotAnimDumpDoesNotStopStartup() throws IOException
	{
		for (String junk : BROKEN)
		{
			SpotAnimRepository repository = new SpotAnimRepository(new Gson());
			repository.load(write(SpotAnimRepository.FILE_NAME, junk));
			assertNotNull("no status after loading " + summarise(junk),
				repository.getStatus());
			// Still answerable, whatever it made of the file.
			repository.get(246);
			repository.isLoaded();
		}
	}

	@Test
	public void aCorruptModelDumpDoesNotStopStartup() throws IOException
	{
		for (String junk : BROKEN)
		{
			ModelRepository repository = new ModelRepository(new Gson());
			repository.load(write(ModelRepository.FILE_NAME, junk));
			assertNotNull("no status after loading " + summarise(junk),
				repository.getStatus());
			repository.itemName(4151);
			repository.isLoaded();
			repository.unload();
		}
	}

	@Test
	public void aCorruptPaletteHarvestDoesNotStopStartup() throws IOException
	{
		for (String junk : BROKEN)
		{
			PaletteHarvest palette = new PaletteHarvest(new Gson());
			palette.load(write("palette-harvest.json", junk));
			assertTrue("negative size after loading " + summarise(junk),
				palette.size() >= 0);
		}
	}

	private static String summarise(String contents)
	{
		return contents.length() > 30 ? contents.substring(0, 30) + "..." : "'" + contents + "'";
	}

	// ------------------------------------------------------------ a directory

	@Test
	public void aDirectoryWhereAFileShouldBeIsNotACrash() throws IOException
	{
		// Rare, but it happens - a sync client, a botched restore.
		Path dir = dir();
		Files.createDirectories(dir.resolve(SpotAnimRepository.FILE_NAME));

		SpotAnimRepository repository = new SpotAnimRepository(new Gson());
		repository.load(dir);
		assertNotNull(repository.getStatus());
	}

	// ------------------------------------------------------------- round trip

	@Test
	public void harvestedPaletteRunsSurviveASaveAndReload() throws IOException
	{
		Path dir = dir();
		PaletteHarvest first = new PaletteHarvest(new Gson());
		first.load(dir);

		java.util.Map<Short, Short> pairs = new java.util.HashMap<>();
		pairs.put((short) 100, (short) 200);
		int size = first.record(new int[]{1, 2, 3, 4, 5}, pairs);
		assertTrue("nothing was recorded", size > 0);

		PaletteHarvest second = new PaletteHarvest(new Gson());
		second.load(dir);
		assertEquals("the harvest did not survive the round trip", size, second.size());
	}

	@Test
	public void recordingTheSameRunTwiceDoesNotDoubleIt() throws IOException
	{
		PaletteHarvest palette = new PaletteHarvest(new Gson());
		palette.load(dir());

		java.util.Map<Short, Short> pairs = new java.util.HashMap<>();
		pairs.put((short) 100, (short) 200);
		int[] colours = {1, 2, 3, 4, 5};

		int first = palette.record(colours, pairs);
		int second = palette.record(colours, pairs);
		assertEquals("the same observation was counted twice", first, second);
	}

	// ------------------------------------------------------------- bundled

	@Test
	public void theBundledStanceLibraryIsReadableOnAFreshInstall() throws IOException
	{
		// Not a data file the user owns, but it loads on the same path and a
		// failure here would leave every weapon animating as unarmed.
		com.follower.follower.StanceLibrary library =
			new com.follower.follower.StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir());

		assertTrue("the shipped stance library is empty or unreadable",
			library.size() > 100);
		assertNotNull("unarmed must always resolve", library.forWeapon(0));
	}

	@Test
	public void aCorruptLearnedStanceFileFallsBackToTheBundledOne() throws IOException
	{
		Path dir = write("stances.json", "{ this is broken");

		com.follower.follower.StanceLibrary library =
			new com.follower.follower.StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir);

		assertTrue("a broken learned file must not take the shipped stances"
			+ " down with it", library.size() > 100);
	}

	@Test
	public void savingWithNothingToSaveWritesNothingSurprising() throws IOException
	{
		Path dir = dir();
		com.follower.follower.StanceLibrary library =
			new com.follower.follower.StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir);
		library.save();

		// Whatever it wrote, reading it back has to work.
		com.follower.follower.StanceLibrary again =
			new com.follower.follower.StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		again.load(dir);
		assertTrue(again.size() > 100);
	}

	// ------------------------------------------------------ unwritable places

	@Test
	public void savingIntoAPlaceThatCannotBeWrittenIsNotACrash() throws IOException
	{
		Path dir = dir();
		com.follower.follower.StanceLibrary library =
			new com.follower.follower.StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir);
		library.setManual(999999, 808, 819, 824, 390);

		// Replace the target with a directory so the write cannot succeed.
		Files.deleteIfExists(dir.resolve("stances.json"));
		Files.createDirectories(dir.resolve("stances.json"));

		library.save();

		assertFalse("a failed save must not be fatal", Files.isRegularFile(
			dir.resolve("stances.json")));
	}
}

package com.follower;

import com.follower.speech.DialogLoader;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The conversation trees have the same upgrade gap the rules had.
 *
 * <p>Appending only whole new trees meant a reworded node, an added choice or
 * a fixed dead end reached nobody who already had the plugin. The trees change
 * rarely, which is exactly why this would have gone unnoticed for a long time:
 * the bug only shows the day somebody finally edits one.
 *
 * <p>Trees merge at two levels, so these tests work at both - a tree's own
 * fields, and the nodes inside it.
 */
public class DialogMergeTest
{
	private static final Gson GSON = new Gson();

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static JsonObject shipped()
	{
		try (InputStream in = DialogLoader.class
			.getResourceAsStream("/com/follower/default-dialogs.json"))
		{
			return GSON.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
				JsonObject.class);
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}

	private static JsonObject tree(JsonObject file, String id)
	{
		for (JsonElement e : file.getAsJsonArray("trees"))
		{
			if (id.equals(e.getAsJsonObject().get("id").getAsString()))
			{
				return e.getAsJsonObject();
			}
		}
		return null;
	}

	private static String firstTreeId(JsonObject file)
	{
		return file.getAsJsonArray("trees").get(0).getAsJsonObject().get("id").getAsString();
	}

	private static JsonObject node(JsonObject file, String treeId, String nodeId)
	{
		for (JsonElement e : tree(file, treeId).getAsJsonArray("nodes"))
		{
			if (nodeId.equals(e.getAsJsonObject().get("id").getAsString()))
			{
				return e.getAsJsonObject();
			}
		}
		return null;
	}

	private static String firstNodeId(JsonObject file, String treeId)
	{
		return tree(file, treeId).getAsJsonArray("nodes").get(0)
			.getAsJsonObject().get("id").getAsString();
	}

	private static List<String> says(JsonObject node)
	{
		List<String> out = new ArrayList<>();
		for (JsonElement e : node.getAsJsonArray("says"))
		{
			out.add(e.getAsString());
		}
		return out;
	}

	private static void setSays(JsonObject node, List<String> lines)
	{
		JsonArray says = new JsonArray();
		lines.forEach(says::add);
		node.add("says", says);
	}

	/**
	 * A previous version: the first node of the first tree short of its last
	 * line. Built from the shipped file so everything else is genuinely real.
	 */
	private static JsonObject previousVersion()
	{
		JsonObject old = shipped();
		String t = firstTreeId(old);
		JsonObject n = node(old, t, firstNodeId(old, t));
		List<String> fewer = new ArrayList<>(says(n));
		fewer.remove(fewer.size() - 1);
		setSays(n, fewer);
		return old;
	}

	private JsonObject merge(JsonObject theirs, JsonObject base) throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			GSON.toJson(theirs).getBytes(StandardCharsets.UTF_8));
		if (base != null)
		{
			Files.write(dir.resolve(DialogLoader.BASE_FILE),
				GSON.toJson(base).getBytes(StandardCharsets.UTF_8));
		}
		new DialogLoader(GSON).initialise(dir, true);
		return GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(DialogLoader.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
	}

	@Test
	public void aRewordedNodeReachesAnExistingInstall() throws Exception
	{
		JsonObject merged = merge(previousVersion(), previousVersion());

		String t = firstTreeId(merged);
		assertEquals("the line the update added arrives",
			says(node(shipped(), t, firstNodeId(shipped(), t))),
			says(node(merged, t, firstNodeId(merged, t))));
	}

	@Test
	public void aLineThePlayerDeletedFromANodeStaysDeleted() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		JsonObject n = node(theirs, t, firstNodeId(theirs, t));
		List<String> without = new ArrayList<>(says(n));
		String removed = without.remove(0);
		setSays(n, without);

		JsonObject merged = merge(theirs, base);

		assertFalse("their deletion is a decision",
			says(node(merged, t, firstNodeId(merged, t))).contains(removed));
	}

	@Test
	public void aNodeThePlayerRewroteIsTheirs() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		String id = firstNodeId(theirs, t);
		setSays(node(theirs, t, id), java.util.Arrays.asList("My own opening."));

		JsonObject merged = merge(theirs, base);

		assertTrue("what they wrote survives",
			says(node(merged, t, id)).contains("My own opening."));
	}

	@Test
	public void aNodeTheUpdateAddedArrives() throws Exception
	{
		// Base and theirs both lack a node the shipped file has.
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		String doomed = tree(shipped(), t).getAsJsonArray("nodes")
			.get(1).getAsJsonObject().get("id").getAsString();
		for (JsonObject file : new JsonObject[]{base, theirs})
		{
			JsonArray kept = new JsonArray();
			for (JsonElement e : tree(file, t).getAsJsonArray("nodes"))
			{
				if (!doomed.equals(e.getAsJsonObject().get("id").getAsString()))
				{
					kept.add(e);
				}
			}
			tree(file, t).add("nodes", kept);
		}

		JsonObject merged = merge(theirs, base);

		assertNotNull("a node the update added arrives", node(merged, t, doomed));
	}

	@Test
	public void aNodeThePlayerDeletedStaysDeleted() throws Exception
	{
		// The base HAS the node, so its absence from theirs is a deletion.
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		String gone = tree(theirs, t).getAsJsonArray("nodes")
			.get(1).getAsJsonObject().get("id").getAsString();
		JsonArray kept = new JsonArray();
		for (JsonElement e : tree(theirs, t).getAsJsonArray("nodes"))
		{
			if (!gone.equals(e.getAsJsonObject().get("id").getAsString()))
			{
				kept.add(e);
			}
		}
		tree(theirs, t).add("nodes", kept);

		JsonObject merged = merge(theirs, base);

		assertNull("a node they removed is not put back", node(merged, t, gone));
	}

	@Test
	public void mergingTwiceChangesNothingTheSecondTime() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));
		Files.write(dir.resolve(DialogLoader.BASE_FILE),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));

		new DialogLoader(GSON).initialise(dir, true);
		String once = new String(Files.readAllBytes(dir.resolve(DialogLoader.FILE_NAME)),
			StandardCharsets.UTF_8);
		new DialogLoader(GSON).initialise(dir, true);
		String twice = new String(Files.readAllBytes(dir.resolve(DialogLoader.FILE_NAME)),
			StandardCharsets.UTF_8);

		assertEquals(once, twice);
	}

	@Test
	public void withNoBaseAnUntouchedTreeIsBroughtUpToDate() throws Exception
	{
		JsonObject merged = merge(previousVersion(), null);

		String t = firstTreeId(merged);
		assertEquals("a tree nobody edited is brought up to date",
			says(node(shipped(), t, firstNodeId(shipped(), t))),
			says(node(merged, t, firstNodeId(merged, t))));
	}

	@Test
	public void withNoBaseATreeThePlayerWroteIntoIsLeftAlone() throws Exception
	{
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		String id = firstNodeId(theirs, t);
		List<String> plus = new ArrayList<>(says(node(theirs, t, id)));
		plus.add("A line of my own.");
		setSays(node(theirs, t, id), plus);

		JsonObject merged = merge(theirs, null);

		assertEquals("without a base, their tree is not ours to touch",
			plus, says(node(merged, t, id)));
	}

	@Test
	public void theBaseIsRecordedSoTheGuessworkHappensOnlyOnce() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));
		assertFalse(Files.exists(dir.resolve(DialogLoader.BASE_FILE)));

		new DialogLoader(GSON).initialise(dir, true);

		assertTrue(Files.exists(dir.resolve(DialogLoader.BASE_FILE)));
	}
}

package com.follower;

import com.follower.speech.Condition;
import com.follower.speech.DialogLoader;
import com.follower.speech.DialogTree;
import com.follower.speech.FollowerDialog;
import com.follower.speech.RuleLoader;
import com.follower.speech.SpeechRule;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The conversations the follower opens, which are data rather than code.
 *
 * <p>A dialog fails in the worst way available: the box opens and shuts again,
 * or a branch dead-ends on a node id with a typo in it, and the player is
 * already inside it when that happens. Nothing about that shows up as an error
 * at runtime, so every structural check is made once at load and again here.
 */
public class DialogTreeTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private DialogLoader loaded() throws IOException
	{
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(folder.newFolder().toPath());
		return loader;
	}

	private DialogLoader loadedFrom(String json) throws IOException
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME), json.getBytes(StandardCharsets.UTF_8));
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(dir);
		return loader;
	}

	@Test
	public void theShippedTreesLoadWithoutComplaint() throws IOException
	{
		DialogLoader loader = loaded();
		assertTrue("the trees the plugin ships must load clean: " + loader.getErrors(),
			loader.getErrors().isEmpty());
		assertFalse("and there has to be at least one", loader.getTrees().isEmpty());
	}

	@Test
	public void everyBranchLeadsSomewhereReal() throws IOException
	{
		// The failure this exists for: a branch pointing at a node id that does
		// not exist. The conversation simply stops, mid-sentence, with the
		// player looking at a closed box wondering what they did wrong.
		DialogLoader loader = loaded();
		for (DialogTree tree : loader.getTrees())
		{
			assertEquals(tree.id + " has structural problems", 0, tree.problems().size());
		}
	}

	@Test
	public void aTreeWithADeadBranchIsRefusedRatherThanHalfLoaded() throws IOException
	{
		// Everything else about this tree is fine - it answers, it starts
		// somewhere real - so the ONLY thing wrong is the branch pointing at a
		// node called "nowhere". Anything else here and the test would pass on
		// the strength of a different check.
		DialogLoader loader = loadedFrom("{\"version\": 1, \"trees\": [{"
			+ "\"id\": \"broken\", \"start\": \"a\", \"nodes\": ["
			+ "{\"id\": \"a\", \"says\": [\"hello\"], \"choices\": ["
			+ "{\"label\": \"fine\", \"next\": \"b\"},"
			+ "{\"label\": \"onwards\", \"next\": \"nowhere\"}]},"
			+ "{\"id\": \"b\", \"says\": [\"right\"], \"answer\": \"yes\"}]}]}");

		assertNull("a tree that can dead-end must not be offered at all",
			loader.get("broken"));
		assertTrue("and the reason has to name the branch: " + loader.getErrors(),
			loader.getErrors().toString().contains("nowhere"));
	}

	@Test
	public void aTreeNobodyCanAnswerIsRefused() throws IOException
	{
		// These trees exist to collect an answer. One with no answer in it is a
		// conversation that wastes the single moment the follower had.
		DialogLoader loader = loadedFrom("{\"version\": 1, \"trees\": [{"
			+ "\"id\": \"pointless\", \"start\": \"a\", \"nodes\": ["
			+ "{\"id\": \"a\", \"says\": [\"nice weather\"]}]}]}");

		assertNull(loader.get("pointless"));
	}

	@Test
	public void aBadReadKeepsTheTreesItAlreadyHad() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(dir);
		int before = loader.getTrees().size();
		assertTrue("start from something", before > 0);

		// What a poll sees between an editor truncating the file and writing it
		// back. Losing every conversation over that would be absurd.
		Files.write(dir.resolve(DialogLoader.FILE_NAME), new byte[0]);
		loader.reload();
		assertEquals("an empty read must not wipe the trees",
			before, loader.getTrees().size());

		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			"{ not json at all".getBytes(StandardCharsets.UTF_8));
		loader.reload();
		assertEquals("nor must a syntax error", before, loader.getTrees().size());
		assertFalse(loader.getErrors().isEmpty());
	}

	@Test
	public void buildingATreeCarriesTheChoicesAndTheAnswerAcross() throws IOException
	{
		DialogLoader loader = loaded();
		DialogTree tree = loader.get("want-outing");
		assertNotNull("the shipped question tree", tree);

		List<String> answers = new ArrayList<>();
		Map<String, FollowerDialog.Node> script =
			FollowerDialog.build(tree, answers::add);

		assertTrue("every node has to survive the build",
			script.keySet().containsAll(tree.byId().keySet()));
		assertNotNull("and it has to start somewhere", script.get(tree.startId()));

		// Both answers have to be reachable, or the player has been offered a
		// question they can only answer one way.
		Set<String> reachable = new HashSet<>();
		for (DialogTree.DialogNode node : tree.nodes)
		{
			if (node.answer != null)
			{
				reachable.add(node.answer.toLowerCase(java.util.Locale.ROOT));
			}
		}
		assertTrue("yes has to be sayable", reachable.contains("yes"));
		assertTrue("and so does no", reachable.contains("no"));
	}

	@Test
	public void whatTheEditorWritesIsWhatTheLoaderReads() throws IOException
	{
		// The editor rebuilds the whole file from its own model and writes it
		// back. If that model has drifted from the loader's - a renamed field,
		// a list where an object was - the save silently produces a file that
		// no longer loads, and the first anyone knows is an empty Talk-to.
		DialogLoader first = loaded();
		int before = first.getTrees().size();

		Gson pretty = new Gson().newBuilder().setPrettyPrinting()
			.disableHtmlEscaping().create();
		EditorShape shape = new EditorShape();
		shape.version = 1;
		shape.trees = first.getTrees();

		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			pretty.toJson(shape).getBytes(StandardCharsets.UTF_8));

		DialogLoader second = new DialogLoader(new Gson());
		second.initialise(dir);
		assertTrue("a round trip through the editor's shape must load clean: "
			+ second.getErrors(), second.getErrors().isEmpty());
		assertEquals("and keep every tree", before, second.getTrees().size());

		DialogTree tree = second.get("want-outing");
		assertNotNull("including the one that answers the question", tree);
		boolean playerSpeaks = false;
		for (DialogTree.DialogNode node : tree.nodes)
		{
			playerSpeaks |= node.isPlayerSpeaking();
		}
		assertTrue("and who speaks each line has to survive it", playerSpeaks);
	}

	/** The shape {@code DialogsDialog} serialises; kept in step by the test above. */
	private static final class EditorShape
	{
		int version;
		List<DialogTree> trees;
	}

	@Test
	public void everyAskedTreeIsOneThatExists() throws IOException
	{
		// A rule naming a tree that is not there falls back to the everyday
		// script, so the follower asks a question and then has nothing to say
		// about it when you come over - which looks exactly like a bug.
		DialogLoader dialogs = loaded();
		RuleLoader rules = new RuleLoader(new Gson());
		rules.initialise(folder.newFolder().toPath());

		int asking = 0;
		for (SpeechRule rule : rules.getRules())
		{
			if (rule.asks == null || rule.asks.isEmpty())
			{
				continue;
			}
			asking++;
			assertNotNull(rule.id + " asks via '" + rule.asks
				+ "', which is not a tree in dialogs.json", dialogs.get(rule.asks));
		}
		assertTrue("something has to be asking, or none of this runs", asking > 0);
	}

	@Test
	public void everyAnswerATreeCanGiveHasARuleListeningForIt() throws IOException
	{
		// An answer is any plain word now, not just yes and no. That is what
		// lets a tree be a game, and it is also what makes this check the only
		// thing standing between "left" and a typo: an answered rule spelt
		// wrong never fires, and a tree branch nothing listens for means the
		// player picks an option and the follower stares back.
		DialogLoader dialogs = loaded();
		RuleLoader rules = new RuleLoader(new Gson());
		rules.initialise(folder.newFolder().toPath());

		Set<String> offered = new TreeSet<>();
		for (DialogTree tree : dialogs.getTrees())
		{
			for (DialogTree.DialogNode node : tree.nodes)
			{
				if (node.answer != null && !node.answer.isEmpty())
				{
					offered.add(node.answer.toLowerCase(java.util.Locale.ROOT));
				}
			}
		}

		// The everyday talk script is the second source of answers - "gift"
		// was its first. Those only exist inside finish runnables, so the
		// honest enumeration is to run every node's finish against a
		// recording consumer. Built with a wish open in BOTH bag states,
		// because the script branches on the bag and each branch answers
		// differently: gift with the thing held, bluff without - and in a
		// low band too, because "comforted" only exists behind the
		// sharpened question.
		for (boolean held : new boolean[]{true, false})
		{
			for (String band : new String[]{"even", "low"})
			{
				for (FollowerDialog.Node node : FollowerPlugin.talkScript(
					() -> new String[]{""},
					answer -> offered.add(answer.toLowerCase(java.util.Locale.ROOT)),
					"feather", held, band).values())
				{
					node.runFinish();
				}
			}
		}

		Set<String> listened = new TreeSet<>();
		for (SpeechRule rule : rules.getRules())
		{
			collectAnswers(rule.when, listened);
		}

		Set<String> deaf = new TreeSet<>(offered);
		deaf.removeAll(listened);
		assertTrue("answers a tree can give that no rule reacts to, so picking"
			+ " them does nothing: " + deaf, deaf.isEmpty());

		Set<String> imagined = new TreeSet<>(listened);
		imagined.removeAll(offered);
		assertTrue("rules waiting on answers no tree can give, so they can never"
			+ " fire: " + imagined, imagined.isEmpty());
	}

	private static void collectAnswers(Condition condition, Set<String> into)
	{
		if (condition == null)
		{
			return;
		}
		if ("answered".equalsIgnoreCase(condition.type) && condition.is != null)
		{
			into.add(condition.is.toLowerCase(java.util.Locale.ROOT));
		}
		if (condition.conditions != null)
		{
			for (Condition child : condition.conditions)
			{
				collectAnswers(child, into);
			}
		}
	}

	@Test
	public void everyQuestionRefusesToTalkOverAnotherOne() throws IOException
	{
		// Opening a question REPLACES whatever was waiting for an answer. With
		// one question in the file that was harmless; with two, a follower that
		// asks to go somewhere and then offers a game has silently withdrawn
		// the outing, and the player answers a question nobody is listening
		// for. The guard is a none/asking block, and every asks rule needs it.
		RuleLoader rules = new RuleLoader(new Gson());
		rules.initialise(folder.newFolder().toPath());

		List<String> unguarded = new ArrayList<>();
		for (SpeechRule rule : rules.getRules())
		{
			if (rule.asks == null || rule.asks.isEmpty())
			{
				continue;
			}
			if (rule.when == null || !rule.when.usesType("asking"))
			{
				unguarded.add(rule.id);
			}
		}
		assertTrue("rules that ask a question without checking whether one is"
			+ " already on the table: " + unguarded, unguarded.isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * What one pass over the whole rule set costs.
 *
 * <p>Every rule is evaluated against every event, and the events are not rare:
 * a tick heartbeat, plus one per NPC entering or leaving the scene, which on a
 * chunk load is hundreds at once. This is not a benchmark to tune against - the
 * numbers move with the machine - but a tripwire for a change that makes the
 * pass pathologically slow, and a place to read the real figure from.
 */
public class DispatchCostTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void aFullRulePassIsCheapEnoughToRunHundredsOfTimesATick() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		int rules = h.loader.getRules().size();

		// A busy scene: enough NPCs that the nearby scans have real work.
		for (int i = 0; i < 60; i++)
		{
			h.game.spawnNpc(3029 + i, "Goblin " + i, 5);
		}
		h.gameTicks(5);

		// Warm up, so the timing is of the code and not of the JIT.
		for (int i = 0; i < 200; i++)
		{
			h.engine.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		}
		h.clear();

		int passes = 2000;
		long start = System.nanoTime();
		for (int i = 0; i < passes; i++)
		{
			h.engine.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		}
		long spawnNanos = (System.nanoTime() - start) / passes;

		start = System.nanoTime();
		for (int i = 0; i < passes; i++)
		{
			h.engine.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_DESPAWN, 3029, "Goblin"));
		}
		long despawnNanos = (System.nanoTime() - start) / passes;

		start = System.nanoTime();
		for (int i = 0; i < passes; i++)
		{
			h.engine.dispatch(TriggerEvent.tick());
		}
		long tickNanos = (System.nanoTime() - start) / passes;

		System.out.printf("%n  rule pass over %d rules:%n"
				+ "    npc spawn   %6d ns%n"
				+ "    npc despawn %6d ns%n"
				+ "    tick        %6d ns%n%n",
			rules, spawnNanos, despawnNanos, tickNanos);

		// A game tick is 600ms and a chunk load can raise a few hundred spawns
		// inside one. Anything approaching a millisecond a pass would be felt.
		assertTrue("a single rule pass took " + spawnNanos + "ns, which would stall"
			+ " the client on a busy scene", spawnNanos < 1_000_000L);
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.SpeechRule;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Randomly generated rule sets, driven by randomly generated events.
 *
 * <p>The hand-written tests check the cases somebody thought of. This one
 * explores the combinations nobody did - a rule that is delayed AND on cooldown
 * AND in a disabled group, fired by an event that arrives while another firing
 * is still pending - and asserts the promises that must hold whatever the
 * combination.
 *
 * <p>Seeded, so a failure is reproducible rather than a story about something
 * that happened once.
 */
public class EngineSoakTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String[] CONDITIONS = {
		"{\"type\": \"always\"}",
		"{\"type\": \"chance\", \"percent\": 50}",
		"{\"type\": \"healthBelow\", \"percent\": 50}",
		"{\"type\": \"healthAbove\", \"percent\": 20}",
		"{\"type\": \"idle\", \"ticks\": 3}",
		"{\"type\": \"energyBelow\", \"percent\": 50}",
		"{\"type\": \"combat\"}",
		"{\"type\": \"login\"}",
		"{\"type\": \"playerDeath\"}",
		"{\"type\": \"npcSpawn\", \"names\": [\"Goblin\"]}",
		"{\"type\": \"npcNearby\", \"names\": [\"Goblin\"], \"within\": 5}",
		"{\"type\": \"animationSelf\", \"ids\": [862]}",
		"{\"type\": \"lootWorth\", \"minimum\": 100}",
		"{\"type\": \"npcKill\", \"minimum\": 1}",
		"{\"type\": \"combatStart\"}",
		"{\"type\": \"damageTaken\", \"minimum\": 1}",
		"{\"type\": \"inRegion\", \"regions\": [12850]}",
		"{\"type\": \"itemEquipped\", \"ids\": [4151]}",
		// The 2026-08-12 batch: state conditions the driver flips at random,
		// so combinators wrapping them open and close mid-flight.
		"{\"type\": \"boundary\"}",
		"{\"type\": \"boundary\", \"is\": \"bank\"}",
		"{\"type\": \"staying\"}",
		"{\"type\": \"inWilderness\"}",
		"{\"type\": \"rolledFeeling\", \"is\": \"disliked\"}",
		"{\"type\": \"daysKnown\", \"minimum\": 0, \"maximum\": 3}",
		"{\"type\": \"none\", \"conditions\": [{\"type\": \"repeating\"}]}",
	};

	private static String condition(Random random, int depth)
	{
		if (depth > 0 && random.nextInt(4) == 0)
		{
			String combinator = new String[]{"all", "any", "none"}[random.nextInt(3)];
			int count = 1 + random.nextInt(3);
			StringBuilder children = new StringBuilder();
			for (int i = 0; i < count; i++)
			{
				if (i > 0)
				{
					children.append(',');
				}
				children.append(condition(random, depth - 1));
			}
			return "{\"type\": \"" + combinator + "\", \"conditions\": [" + children + "]}";
		}
		return CONDITIONS[random.nextInt(CONDITIONS.length)];
	}

	private static String rules(Random random, int count)
	{
		StringBuilder out = new StringBuilder("{\"version\": 1, \"rules\": [");
		for (int i = 0; i < count; i++)
		{
			if (i > 0)
			{
				out.append(',');
			}
			out.append("{\"id\": \"r").append(i).append('"')
				.append(", \"group\": \"g").append(random.nextInt(4)).append('"')
				.append(", \"priority\": ").append(random.nextInt(100))
				.append(", \"cooldownMs\": ").append(random.nextInt(3) * 5000);
			if (random.nextInt(3) == 0)
			{
				int min = random.nextInt(4);
				out.append(", \"delayTicks\": ").append(min);
				if (random.nextBoolean())
				{
					out.append(", \"delayTicksMax\": ").append(min + random.nextInt(4));
				}
			}
			if (random.nextInt(5) == 0)
			{
				out.append(", \"animation\": 862");
			}
			out.append(", \"when\": ").append(condition(random, 2))
				.append(", \"say\": [\"line ").append(i).append("\"]}");
		}
		return out.append("]}").toString();
	}

	private void randomEvent(Harness h, Random random)
	{
		switch (random.nextInt(14))
		{
			case 0:
				h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
				break;
			case 1:
				h.dispatch(TriggerEvent.animation(862));
				break;
			case 2:
				h.dispatch(TriggerEvent.loot(random.nextInt(200000), "Bones"));
				break;
			case 3:
				h.dispatch(TriggerEvent.kill(1, "Goblin", random.nextInt(800)));
				break;
			case 4:
				h.dispatch(TriggerEvent.death());
				break;
			case 5:
				h.dispatch(TriggerEvent.damageTaken(1 + random.nextInt(40)));
				break;
			case 6:
				h.dispatch(TriggerEvent.combat(TriggerEvent.Type.COMBAT_START, "Goblin"));
				break;
			case 7:
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
				break;
			case 8:
				h.game.hitpoints(1 + random.nextInt(99), 99);
				break;
			case 9:
				h.game.energy(random.nextInt(10001));
				break;
			case 10:
				h.engine.getContext().noteBoundary(
					new String[]{"combat", "bank", "reunion"}[random.nextInt(3)]);
				break;
			case 11:
				h.engine.getContext().setFollowerStaying(random.nextBoolean());
				break;
			case 12:
				h.game.varbit(5963, random.nextInt(2));
				break;
			default:
				h.game.animating(random.nextBoolean() ? 879 : -1);
				break;
		}
	}

	@Test
	public void randomRuleSetsUnderRandomEventsKeepTheirPromises() throws IOException
	{
		for (int seed = 0; seed < 40; seed++)
		{
			Random random = new Random(seed);
			Harness h = new Harness(folder.newFolder().toPath(), rules(random, 25));

			Set<String> disabled = new HashSet<>();
			if (random.nextBoolean())
			{
				disabled.add("g" + random.nextInt(4));
			}
			h.engine.setDisabledGroups(disabled);
			h.game.spawnNpc(3029, "Goblin", 5);

			Map<String, Long> lastSpokeAt = new HashMap<>();
			int before = 0;

			for (int step = 0; step < 300; step++)
			{
				if (random.nextInt(3) == 0)
				{
					randomEvent(h, random);
				}
				h.gameTick();

				// Nothing from a group that was switched off.
				for (int i = before; i < h.spoken.size(); i++)
				{
					Harness.Spoken spoken = h.spoken.get(i);
					SpeechRule rule = spoken.rule;
					assertTrue("seed " + seed + ": '" + rule.id + "' spoke from the"
							+ " disabled group '" + rule.group + "'",
						!disabled.contains(rule.group));

					// Never twice inside its own cooldown.
					Long previous = lastSpokeAt.get(rule.id);
					long now = System.currentTimeMillis();
					if (previous != null && rule.cooldownMs > 0)
					{
						assertTrue("seed " + seed + ": '" + rule.id + "' spoke twice"
								+ " inside its " + rule.cooldownMs + "ms cooldown",
							now - previous >= 0);
					}
					lastSpokeAt.put(rule.id, now);
				}
				before = h.spoken.size();
			}

			// Still alive and answering after all that.
			h.clear();
			h.game.hitpoints(1, 99);
			h.gameTicks(5);
		}
	}

	@Test
	public void aDelayedFiringNeverArrivesEarlierThanItsFloor() throws IOException
	{
		// Ten ticks of delay, checked exactly: the queue must not leak a firing
		// forward when other events are arriving in between.
		for (int seed = 0; seed < 20; seed++)
		{
			Random random = new Random(seed);
			Harness h = new Harness(folder.newFolder().toPath(),
				"{\"version\": 1, \"rules\": [{\"id\": \"slow\", \"group\": \"t\","
					+ " \"cooldownMs\": 0, \"delayTicks\": 10,"
					+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}]}");

			h.gameTicks(1);
			h.dispatch(TriggerEvent.death());

			for (int tick = 1; tick <= 9; tick++)
			{
				if (random.nextBoolean())
				{
					randomEvent(h, random);
				}
				h.gameTick();
				assertTrue("seed " + seed + ": spoke on tick " + tick + " of a 10 tick wait",
					h.firedBy("slow").isEmpty());
			}
			h.gameTick();
			assertEquals("seed " + seed + ": did not speak when the wait was up",
				1, h.firedBy("slow").size());
		}
	}

	@Test
	public void atMostOneRuleSpeaksPerDispatch() throws IOException
	{
		// Twenty rules that are all true at once, all off cooldown. The engine
		// picks a single winner per pass; anything else is two lines at once.
		StringBuilder out = new StringBuilder("{\"version\": 1, \"rules\": [");
		for (int i = 0; i < 20; i++)
		{
			if (i > 0)
			{
				out.append(',');
			}
			out.append("{\"id\": \"r").append(i).append("\", \"group\": \"t\","
				+ " \"priority\": ").append(i).append(", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"always\"}, \"say\": [\"x\"]}");
		}
		Harness h = new Harness(folder.newFolder().toPath(), out.append("]}").toString());

		h.gameTick();
		int afterFirst = h.spoken.size();
		assertTrue("twenty true rules produced " + afterFirst + " lines in one pass",
			afterFirst <= 1);

		List<String> speakers = new ArrayList<>();
		for (int tick = 0; tick < 20; tick++)
		{
			int before = h.spoken.size();
			h.gameTick();
			assertTrue("more than one line in a single tick",
				h.spoken.size() - before <= 1);
			for (int i = before; i < h.spoken.size(); i++)
			{
				speakers.add(h.spoken.get(i).rule.id);
			}
		}

		// "always" never falls, so after the first pass no rule has a rising
		// edge left and nothing more should be said at all.
		assertTrue("a permanently true rule kept talking: " + speakers,
			speakers.isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Every condition type the rule format advertises, driven until it fires.
 *
 * <p>A condition that never returns true is invisible: the rule using it simply
 * stays quiet, and nothing is logged. The bundled rules only use 36 of the 44
 * types, so the remaining 8 are advertised in the README and documented in
 * {@code Condition} with nothing anywhere proving they work at all. Each case
 * below sets up the state that should make it fire, and then asserts it did -
 * and, where the condition takes a threshold, that it does NOT fire on the
 * other side of it.
 */
public class EveryConditionTypeTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** Types checked by a case here, so the coverage assertion can be honest. */
	private final Set<String> exercised = new HashSet<>();

	private Harness harnessFor(String when) throws IOException
	{
		return new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [{\"id\": \"probe\", \"group\": \"t\","
				+ " \"cooldownMs\": 0, \"when\": " + when + ", \"say\": [\"fired\"]}]}");
	}

	private void note(String... types)
	{
		for (String type : types)
		{
			exercised.add(type.toLowerCase(java.util.Locale.ROOT));
		}
	}

	private static void assertFired(Harness h, String why)
	{
		assertFalse(why + " - the condition never became true", h.firedBy("probe").isEmpty());
	}

	private static void assertQuiet(Harness h, String why)
	{
		assertTrue(why + " - it fired when it should not have", h.firedBy("probe").isEmpty());
	}

	// ----------------------------------------------------------- combinators

	@Test
	public void combinators() throws IOException
	{
		note("all", "any", "none", "always");

		Harness all = harnessFor("{\"type\": \"all\", \"conditions\": ["
			+ "{\"type\": \"always\"}, {\"type\": \"healthBelow\", \"percent\": 50}]}");
		all.game.hitpoints(10, 99);
		all.gameTicks(2);
		assertFired(all, "all");

		Harness allFails = harnessFor("{\"type\": \"all\", \"conditions\": ["
			+ "{\"type\": \"always\"}, {\"type\": \"healthBelow\", \"percent\": 50}]}");
		allFails.gameTicks(2);
		assertQuiet(allFails, "all with one false member");

		Harness any = harnessFor("{\"type\": \"any\", \"conditions\": ["
			+ "{\"type\": \"healthBelow\", \"percent\": 1}, {\"type\": \"always\"}]}");
		any.gameTicks(2);
		assertFired(any, "any");

		Harness none = harnessFor("{\"type\": \"none\", \"conditions\": ["
			+ "{\"type\": \"healthBelow\", \"percent\": 1}]}");
		none.gameTicks(2);
		assertFired(none, "none");

		Harness noneFails = harnessFor("{\"type\": \"none\", \"conditions\": ["
			+ "{\"type\": \"always\"}]}");
		noneFails.gameTicks(2);
		assertQuiet(noneFails, "none over a true member");
	}

	@Test
	public void anEmptyCombinatorDoesNotThrow() throws IOException
	{
		// all over nothing is vacuously true, any over nothing is false. What
		// matters is that a half-written rule cannot take the dispatch down.
		Harness all = harnessFor("{\"type\": \"all\", \"conditions\": []}");
		all.gameTicks(2);
		assertFired(all, "an empty all is vacuously true");

		Harness any = harnessFor("{\"type\": \"any\", \"conditions\": []}");
		any.gameTicks(2);
		assertQuiet(any, "an empty any has nothing to be true");

		Harness missing = harnessFor("{\"type\": \"all\"}");
		missing.gameTicks(2);
		assertFired(missing, "a combinator with no conditions key at all");
	}

	@Test
	public void chance() throws IOException
	{
		note("chance");

		Harness never = harnessFor("{\"type\": \"chance\", \"percent\": 0}");
		never.gameTicks(50);
		assertQuiet(never, "zero percent");

		Harness always = harnessFor("{\"type\": \"chance\", \"percent\": 100}");
		always.gameTicks(2);
		assertFired(always, "a hundred percent");
	}

	// ----------------------------------------------------------------- state

	@Test
	public void healthAndPrayerThresholds() throws IOException
	{
		note("healthBelow", "healthAbove", "prayerBelow", "prayerAbove");

		Harness below = harnessFor("{\"type\": \"healthBelow\", \"percent\": 50}");
		below.game.hitpoints(10, 99);
		below.gameTicks(2);
		assertFired(below, "healthBelow");

		Harness above = harnessFor("{\"type\": \"healthAbove\", \"percent\": 50}");
		above.gameTicks(2);
		assertFired(above, "healthAbove");

		Harness prayerLow = harnessFor("{\"type\": \"prayerBelow\", \"percent\": 20}");
		prayerLow.game.prayer(5, 99);
		prayerLow.gameTicks(2);
		assertFired(prayerLow, "prayerBelow");

		Harness prayerHigh = harnessFor("{\"type\": \"prayerAbove\", \"percent\": 20}");
		prayerHigh.gameTicks(2);
		assertFired(prayerHigh, "prayerAbove");
	}

	@Test
	public void prayerBelowCanRequireItToBeDraining() throws IOException
	{
		Harness h = harnessFor("{\"type\": \"prayerBelow\", \"percent\": 50,"
			+ " \"requirePrayerActive\": true}");
		h.game.prayer(10, 99);
		h.gameTicks(3);
		assertQuiet(h, "low prayer that is not draining is not prayer being used");

		h.game.prayer(9, 99);
		h.gameTicks(1);
		assertFired(h, "prayer dropping is prayer active");
	}

	@Test
	public void poisonAndVenomAndSkull() throws IOException
	{
		note("poisoned", "venomed", "skulled");
		int poisonVarp = net.runelite.api.gameval.VarPlayerID.POISON;

		Harness poisoned = harnessFor("{\"type\": \"poisoned\"}");
		poisoned.game.varp(poisonVarp, 12);
		poisoned.gameTicks(2);
		assertFired(poisoned, "poisoned");

		Harness venomed = harnessFor("{\"type\": \"venomed\"}");
		venomed.game.varp(poisonVarp, 1_000_050);
		venomed.gameTicks(2);
		assertFired(venomed, "venomed");

		// Venom is the same varp pushed past a million, so it must not also
		// read as ordinary poison.
		Harness notPoison = harnessFor("{\"type\": \"poisoned\"}");
		notPoison.game.varp(poisonVarp, 1_000_050);
		notPoison.gameTicks(2);
		assertQuiet(notPoison, "venom read as poison");

		Harness skulled = harnessFor("{\"type\": \"skulled\"}");
		skulled.game.skulled(true);
		skulled.gameTicks(2);
		assertFired(skulled, "skulled");
	}

	@Test
	public void energyAndIdleBounds() throws IOException
	{
		note("energyBelow", "idle", "idleBelow");

		Harness energy = harnessFor("{\"type\": \"energyBelow\", \"percent\": 20}");
		energy.game.energy(1500);
		energy.gameTicks(2);
		assertFired(energy, "energyBelow");

		Harness idle = harnessFor("{\"type\": \"idle\", \"ticks\": 5}");
		idle.gameTicks(8);
		assertFired(idle, "idle");

		Harness idleBelow = harnessFor("{\"type\": \"all\", \"conditions\": ["
			+ "{\"type\": \"idle\", \"ticks\": 3},"
			+ "{\"type\": \"idleBelow\", \"ticks\": 6}]}");
		idleBelow.gameTicks(5);
		assertFired(idleBelow, "the idle window between two bounds");
	}

	@Test
	public void itemEquipped() throws IOException
	{
		note("itemEquipped");

		Harness h = harnessFor("{\"type\": \"itemEquipped\", \"ids\": [4151]}");
		h.gameTicks(2);
		assertQuiet(h, "nothing worn");

		h.game.wearing(4151);
		h.gameTicks(2);
		assertFired(h, "itemEquipped");
	}

	@Test
	public void varbitEquals() throws IOException
	{
		note("varbitEquals");

		Harness h = harnessFor("{\"type\": \"varbitEquals\", \"varbit\": 4200, \"value\": 3}");
		h.game.varbit(4200, 1);
		h.gameTicks(2);
		assertQuiet(h, "the wrong value");

		h.game.varbit(4200, 3);
		h.gameTicks(2);
		assertFired(h, "varbitEquals");
	}

	// -------------------------------------------------------------- location

	@Test
	public void inRegionAndInArea() throws IOException
	{
		note("inRegion", "inArea");

		WorldPoint lumbridge = new WorldPoint(3222, 3218, 0);
		Harness region = harnessFor("{\"type\": \"inRegion\", \"regions\": ["
			+ lumbridge.getRegionID() + "]}");
		region.gameTicks(2);
		assertFired(region, "inRegion");

		// And the half that was missing: it has to stay quiet ELSEWHERE.
		// Fifty-eight area rules hang off this one condition, so a version
		// that matched everywhere would have the follower announcing Lumbridge
		// from Varrock - and every test here passed against exactly that.
		Harness elsewhere = harnessFor("{\"type\": \"inRegion\", \"regions\": ["
			+ lumbridge.getRegionID() + "]}");
		elsewhere.game.at(2624, 3648, 0);
		elsewhere.gameTicks(3);
		assertQuiet(elsewhere, "a region rule fired somewhere else entirely");

		Harness area = harnessFor("{\"type\": \"inArea\", \"x1\": 3200, \"y1\": 3200,"
			+ " \"x2\": 3250, \"y2\": 3250, \"plane\": 0}");
		area.gameTicks(2);
		assertFired(area, "inArea");

		Harness wrongPlane = harnessFor("{\"type\": \"inArea\", \"x1\": 3200, \"y1\": 3200,"
			+ " \"x2\": 3250, \"y2\": 3250, \"plane\": 2}");
		wrongPlane.gameTicks(2);
		assertQuiet(wrongPlane, "the area on another floor");
	}

	@Test
	public void inAreaAcceptsItsCornersInEitherOrder() throws IOException
