		// Written back to front, which is easy to do by hand from two clicks.
		Harness h = harnessFor("{\"type\": \"inArea\", \"x1\": 3250, \"y1\": 3250,"
			+ " \"x2\": 3200, \"y2\": 3200}");
		h.gameTicks(2);
