	// ----------------------------------------------------------------- scene

	@Test
	public void npcSpawnDespawnAndNearby() throws IOException
	{
		note("npcSpawn", "npcDespawn", "npcNearby", "petNearby");

		Harness spawn = harnessFor("{\"type\": \"npcSpawn\", \"names\": [\"Goblin\"]}");
