package com.follower;

import com.follower.sim.Harness;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The wish and the gift that answers it.
 *
 * <p>The first design offered "Found you something." at all times, and play
 * testing killed it in one sentence: you don't know what you gifted or what
 * the follower even wanted. So the wanting now comes first - the follower
 * asks for a small specific thing, the gift option exists only while that
 * hope does, and every line downstream names the thing. Client-side, nothing
 * real changes hands; the concreteness of the noun is what carries it.
 */
public class GiftTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A follower that has just wished for a feather, out loud. */
	private Harness wishing() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		assertTrue(h.engine.force("wish-feather"));
		assertTrue("saying the wish is what opens it",
			h.engine.getContext().isWishing());
		assertEquals("feather", h.engine.getContext().getWishLabel());
		return h;
	}

	/** The same, with an actual feather in the bag. */
	private Harness wishingAndHolding() throws IOException
	{
		Harness h = wishing();
		h.game.inventoryContaining(314);      // Feather
		return h;
	}

	@Test
	public void aBluffGetsItsDryCodaAndTheWishSurvives() throws IOException
	{
		// The catch itself happens in the dialog box now - the script
		// branches on the bag - so what the rules owe the bluff is one dry
		// coda overhead and the mood dent, not a second telling-off.
		Harness h = wishing();
		h.game.inventoryContaining();      // pockets full of nothing
		h.answers("bluff");                // what the empty-bag branch answers
		h.gameTicks(3);

		assertEquals("the coda", 1, h.firedBy("gifted-bluff").size());
		assertTrue("no thanks were given", h.firedBy("gifted-accept").isEmpty());
		assertFalse("nothing is carried out of a bluff",
			h.engine.getContext().isCarrying());
		assertTrue("and the wish survives for a real attempt",
			h.engine.getContext().isWishing());
	}

	@Test
	public void theMidBoxDropStillGetsAnHonestAnswer() throws IOException
	{
		// The race the box cannot see: the bag held the thing when the script
		// was built and not when the branch was picked. The box already said
		// "that's the one", so the rules re-check and say where it went.
		Harness h = wishing();
		h.game.inventoryContaining();      // gone by dispatch time
		h.answers("gift");                 // what the holding branch answers
		h.gameTicks(3);

		assertEquals("the follower notices the vanishing act",
			1, h.firedBy("gifted-slipped").size());
		assertTrue("and no thanks were given", h.firedBy("gifted-accept").isEmpty());
		assertTrue("the wish stays open", h.engine.getContext().isWishing());
	}

	/**
	 * Every thank-you names the thing, not just the one a shuffle happened to
	 * pick. The rule above tests a single firing, which is one line out of
	 * fourteen - it passed for a year and then failed the moment ten lines
	 * were added, four of which had quietly dropped the noun. The design says
	 * everything downstream says feather; this is that, asked of the pool.
	 */
	@Test
	public void everyThankYouNamesTheThing() throws IOException
	{
		Harness h = wishingAndHolding();
		java.util.List<String> bare = new java.util.ArrayList<>();
		for (com.follower.speech.SpeechRule rule : h.loader.getRules())
		{
			if ("gifted-accept".equals(rule.id) || "gifted-swap".equals(rule.id))
			{
				for (String line : rule.say)
				{
					if (!line.contains("{wish}"))
					{
						bare.add(rule.id + ": " + line);
					}
				}
			}
		}
		assertTrue("a handover that does not name what was handed over: " + bare,
			bare.isEmpty());
	}

	@Test
	public void theGiftAnswersTheWishByName() throws IOException
	{
		Harness h = wishingAndHolding();
		h.answers("gift");
		h.gameTicks(3);      // the thank-you rides a two-tick delay

		assertEquals("the thank-you fired", 1, h.firedBy("gifted-accept").size());
		assertTrue("and it names the thing",
			h.firedBy("gifted-accept").get(0).text.contains("feather"));
		assertEquals("the souvenir label keeps the noun for the whole carry",
			"the feather you found me", h.engine.getContext().getSouvenir());
		assertFalse("and the wish is spent", h.engine.getContext().isWishing());
	}

	@Test
	public void oneWishAtATime() throws IOException
	{
		Harness h = wishing();
		h.engine.getContext().setWish("pot of ink", 45);

		assertEquals("a second wish cannot replace the first",
			"feather", h.engine.getContext().getWishLabel());
	}

	@Test
	public void aGiftWhileCarryingTradesUpOutLoud() throws IOException
	{
		// The deferral this replaces parked the gift option for the length of
		// a ninety-minute carry, which play testing read as the option
		// refusing to go away. A gift outranks a rock the follower found
		// itself, and the swap is spoken - a SILENT swap was the thing the
		// old rule existed to prevent, not the swap itself.
		Harness h = wishingAndHolding();
		h.engine.getContext().pickUp("a nice flat rock", 30);
		h.answers("gift");
		h.gameTicks(3);

		assertEquals("the trade, in words", 1, h.firedBy("gifted-swap").size());
		assertTrue("naming what goes out",
			h.firedBy("gifted-swap").get(0).text.contains("a nice flat rock"));
		assertEquals("the gift took the pocket",
			"the feather you found me", h.engine.getContext().getSouvenir());
		assertFalse("and the wish is spent, so the option finally goes away",
			h.engine.getContext().isWishing());
	}

	@Test
	public void aLapsedWishStillGetsAGraciousWord() throws IOException
	{
		// The race: the wish expires between the box opening and the click.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.answers("gift");
		h.gameTicks(3);

		assertEquals("silence there would read as a bug",
			1, h.firedBy("gifted-late").size());
		assertFalse("and nothing is carried out of it",
			h.engine.getContext().isCarrying());
	}

	@Test
	public void theMentionRulesTalkAboutTheGiftWithoutKnowingAboutGifts()
		throws IOException
	{
		Harness h = wishingAndHolding();
		h.answers("gift");
		h.gameTicks(3);
		h.clear();

		assertTrue(h.engine.force("souvenir-mention"));
		boolean mentioned = false;
		for (Harness.Spoken s : h.spoken)
		{
			mentioned |= s.text.contains("the feather you found me");
		}
		assertTrue("a mention reads as the gift by label alone", mentioned);
	}

	@Test
	public void aGiftAnswerIsNotAYes() throws IOException
	{
		// The answered vocabulary grew a word, and the yes/no rules must not
		// hear it: a gift arriving while a want question is open must not
		// read as agreeing to the outing.
		Harness h = wishingAndHolding();
		h.engine.getContext().noteQuestion("want-outing");
		h.answers("gift");
		h.gameTicks(3);

		assertFalse("the gift landed", h.firedBy("gifted-accept").isEmpty());
		assertTrue("and no want appeared out of it",
			!h.engine.getContext().isWanting());
	}
}

package com.follower;

import com.follower.sim.Harness;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * R24's guard, measured rather than believed.
 *
 * <p>What it actually does: repeating needs a hundred ticks of sustained
 * animation to count, and resets within four quiet ticks of stopping. So
 * the guard bites during a LIVE grind - the combat stretch is the case that
 * matters, since the idle gates already keep the idle-triggered openers out
 * of anything animated - and releases almost immediately after, so a wish
 * or a question lands in the calm after the work rather than never.
 */
public class GrindGuardTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A probe with the exact guard shape the openers carry, triggered on demand. */
	private Harness guarded() throws IOException
	{
		return new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"probe\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"all\", \"conditions\": ["
				+ "{\"type\": \"none\", \"conditions\": [ {\"type\": \"repeating\"} ]},"
				+ "{\"type\": \"answered\", \"is\": \"yes\"}]},"
				+ " \"say\": [\"opened\"]}]}");
	}

	@Test
	public void theGuardBitesMidGrindAndReleasesAfter() throws IOException
	{
		Harness h = guarded();
		h.gameTicks(1);

		// A hundred and twenty ticks of the same swing: a real grind.
		h.game.animating(879);
		h.gameTicks(120);
		h.answers("yes");
		h.gameTicks(2);
		assertTrue("nothing demanding opens mid-grind", h.spoken.isEmpty());

		// The grind ends; the guard lets go within a few quiet ticks, so the
		// opener lands in the calm after the work rather than never.
		h.game.animating(-1);
		h.gameTicks(6);
		h.answers("yes");
		h.gameTicks(2);
		assertEquals("the calm after the grind is fair game",
			1, h.firedBy("probe").size());
	}

	@Test
	public void aShortTaskNeverTripsTheGuard() throws IOException
	{
		// Under a hundred ticks of activity is a task, not a grind; the
		// guard must not punish somebody who chopped three logs.
		Harness h = guarded();
		h.gameTicks(1);

		h.game.animating(879);
		h.gameTicks(40);
		h.answers("yes");
		h.gameTicks(2);
		assertEquals("forty ticks of work is not a grind",
			1, h.firedBy("probe").size());
	}
}

package com.follower;

import com.follower.appearance.ModelRepository;
import com.follower.appearance.SpotAnimRepository;
import com.follower.speech.RuleLoader;
import com.follower.ui.GameFontRepository;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

/**
 * How much of the player's memory the plugin keeps.
 *
 * <p>It loads the whole equipment catalogue, every spotanim and every game font
 * and holds them for the session, inside a client that is already the largest
 * thing on most people's machines. That has never been measured - only the file
 * sizes on disk, which say almost nothing about the heap: an 865KB JSON of six
 * thousand small objects can land anywhere between a tenth and ten times that
 * once it is a Map of Entry.
 *
 * <p>The answer, measured: about six megabytes for the lot, in a client that
 * routinely holds several hundred. There is nothing to optimise here, and that
 * is worth knowing - the file sizes suggested otherwise and it would have been
 * easy to spend a day making the catalogues clever for no reason.
 *
 * <p>So these are regression budgets rather than targets. Each is roughly
 * triple what is actually used: far enough above that the measurement's own
 * noise can never fail it - four consecutive runs agreed to a tenth of a
 * megabyte - and close enough that a catalogue doubling does. If one of these
 * fails and the growth was deliberate, raise the number and say why in the
 * commit.
 */
public class HeapFootprintTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The real dumps, if this machine has them. Skipped elsewhere. */
	private static final Path LIVE_DATA =
		Paths.get(System.getProperty("user.home"), ".runelite", "follower");

	private static long usedBytes()
	{
		Runtime runtime = Runtime.getRuntime();
		for (int i = 0; i < 4; i++)
		{
			System.gc();
			try
			{
				Thread.sleep(30);
			}
			catch (InterruptedException e)
			{
				Thread.currentThread().interrupt();
			}
		}
		return runtime.totalMemory() - runtime.freeMemory();
	}

	private static void report(String what, long bytes, long budgetMb)
	{
		double mb = bytes / (1024.0 * 1024.0);
		System.out.printf("  %-28s %6.1f MB   (budget %d MB)%n", what, mb, budgetMb);
		assertTrue(what + " holds " + String.format("%.1f", mb)
			+ " MB, over its " + budgetMb + " MB budget - if that is a deliberate"
			+ " growth, raise the budget and say why", mb < budgetMb);
	}

	@Test
	public void theEquipmentCatalogueFitsInItsBudget() throws IOException
	{
		Path dump = LIVE_DATA.resolve("equipment-models.json");
		assumeTrue("no equipment dump on this machine", Files.isRegularFile(dump));

		long before = usedBytes();
		ModelRepository repository = new ModelRepository(new Gson());
		repository.load(LIVE_DATA);
		long after = usedBytes();

		// Held for the whole session so the outfit panel can search it.
		report("equipment catalogue", after - before, 7);
		assertTrue("the dump did not actually load", repository.getStatus() != null);
	}

	@Test
	public void theSpotAnimCatalogueFitsInItsBudget() throws IOException
	{
		Path dump = LIVE_DATA.resolve("spotanims.json");
		assumeTrue("no spotanim dump on this machine", Files.isRegularFile(dump));

		long before = usedBytes();
		SpotAnimRepository repository = new SpotAnimRepository(new Gson());
		repository.load(LIVE_DATA);
		long after = usedBytes();

		report("spotanim catalogue", after - before, 9);
	}

	@Test
	public void theGameFontsFitInTheirBudget() throws IOException
	{
		Path dump = LIVE_DATA.resolve("fonts.json");
		assumeTrue("no font dump on this machine", Files.isRegularFile(dump));

		// Twenty-one fonts of 256 glyphs each, every glyph a pixel mask. This
		// is the one most likely to surprise: the file is base64 and the heap
		// form is decoded bytes.
		long before = usedBytes();
		GameFontRepository fonts = new GameFontRepository(new Gson());
		fonts.load(LIVE_DATA);
		long after = usedBytes();

		report("game fonts", after - before, 3);
	}

	@Test
	public void theRuleSetFitsInItsBudget() throws IOException
	{
		// Three hundred rules with their notes and phrase lists, plus a
		// compiled pattern per name list once they have been evaluated.
		long before = usedBytes();
		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(folder.newFolder().toPath());
		long after = usedBytes();

		report("rules and phrases", after - before, 2);
		assertTrue("the rules did not load", loader.getRules().size() > 100);
	}
}

package com.follower;

import com.follower.share.PackFile;
import com.follower.sound.VoiceLibrary;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * A pack written by somebody who means harm.
 *
 * <p>The threat is not code - nothing in a pack is executed, and the plugin
 * takes no server-side action, so an account cannot be made to do anything.
 * The threat is CONTENT reaching two places it should not: the game chatbox,
 * which interprets Jagex markup and would happily render an attacker's text in
 * whatever colour they choose, and the sound attachments, where a pack could
 * point audio at lines it never carried and overwrite recordings the recipient
 * made themselves.
 *
 * <p>Each test here is an attack. They are written from the outside, against
 * the zip, because that is the only thing an attacker controls.
 */
public class HostilePackTest
{
	private static final Gson GSON = new Gson();

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** Builds a pack by hand: an attacker does not use our exporter. */
	private Path pack(String rulesJson, String soundsJson, String... audio) throws Exception
	{
		Path zip = folder.getRoot().toPath().resolve("hostile-" + rulesJson.hashCode() + ".zip");
		try (ZipOutputStream out = new ZipOutputStream(Files.newOutputStream(zip)))
		{
			out.putNextEntry(new ZipEntry("pack.json"));
			out.write("{\"format\":1,\"author\":\"friend\"}".getBytes("UTF-8"));
			out.closeEntry();
			out.putNextEntry(new ZipEntry("rules.json"));
			out.write(rulesJson.replace('\'', '"').getBytes("UTF-8"));
			out.closeEntry();
			if (soundsJson != null)
			{
				out.putNextEntry(new ZipEntry("sounds.json"));
				out.write(soundsJson.replace('\'', '"').getBytes("UTF-8"));
				out.closeEntry();
			}
			for (String name : audio)
			{
				out.putNextEntry(new ZipEntry("sounds/" + name));
				out.write(new byte[]{1, 2, 3});
				out.closeEntry();
			}
		}
		return zip;
	}

	private VoiceLibrary voicesIn(String name) throws Exception
	{
		VoiceLibrary voices = new VoiceLibrary(GSON, new net.runelite.client.audio.AudioPlayer());
		voices.load(folder.newFolder(name).toPath());
		return voices;
	}

	private static JsonObject theirs()
	{
		return GSON.fromJson("{\"rules\":[{\"id\":\"bank\",\"say\":[\"Deep pockets.\"]}]}",
			JsonObject.class);
	}

	private static String allLines(PackFile.Loaded loaded)
	{
		return loaded.rules.toString();
	}

	/**
	 * The chatbox interprets Jagex markup, and mirroring to it is one
	 * setting away, so a tag in a line is a tag on somebody's screen.
	 */
	@Test
	public void markupIsRefusedBecauseTheChatboxWouldRenderIt() throws Exception
	{
		PackFile.Loaded loaded = PackFile.read(pack(
			"{'rules':[{'id':'evil','when':{'type':'tick'},'say':["
				+ "'<col=ff0000>Account flagged. Verify at evil.example',"
				+ "'<img=0> Mod Hint: type your password',"
				+ "'Plain and fine.']}]}", null), GSON);

		assertFalse("a colour tag must not survive", allLines(loaded).contains("<col="));
		assertFalse("an image tag must not survive", allLines(loaded).contains("<img="));
		assertEquals("only the honest line arrives", 1, loaded.summary.lines);
	}

	/** A newline or a null is not a line, and the ASCII check let both through. */
	@Test
	public void controlCharactersAreRefused() throws Exception
	{
		PackFile.Loaded loaded = PackFile.read(pack(
			"{'rules':[{'id':'evil','when':{'type':'tick'},'say':["
				+ "'Two\\nlines in one','Null\\u0000byte','Carriage\\rreturn',"
				+ "'Plain and fine.']}]}", null), GSON);

		assertEquals("only the honest line arrives", 1, loaded.summary.lines);
	}

	/**
	 * The sound map is a separate file from the rules, so nothing stopped it
	 * naming a line the pack never carried - including one that ships.
	 */
	@Test
	public void aPackCannotPutItsAudioOnALineItDidNotBring() throws Exception
	{
		Path zip = pack("{'rules':[{'id':'mine','when':{'type':'tick'},'say':['My own line.']}]}",
			"{'Deep pockets.':'evil.wav','My own line.':'evil.wav'}", "evil.wav");

		VoiceLibrary theirVoices = voicesIn("to");
		JsonObject recipient = theirs();
		PackFile.apply(PackFile.read(zip, GSON), recipient, theirVoices.getSoundsFolder(), theirVoices);

		assertNotNull("the line the pack actually brought is voiced",
			theirVoices.attachmentFor("My own line."));
		assertEquals("a shipped line the pack never carried must stay silent",
			null, theirVoices.attachmentFor("Deep pockets."));
	}

	/** "Nothing is replaced" has to cover recordings, not just text. */
	@Test
	public void aPackCannotReplaceARecordingTheRecipientMadeThemselves() throws Exception
	{
		VoiceLibrary theirVoices = voicesIn("to");
		Files.write(theirVoices.getSoundsFolder().resolve("mine.wav"), new byte[]{7, 7});
		theirVoices.attach("Shared line.", "mine.wav");

		Path zip = pack("{'rules':[{'id':'mine','when':{'type':'tick'},'say':['Shared line.']}]}",
			"{'Shared line.':'evil.wav'}", "evil.wav");

		JsonObject recipient = theirs();
		PackFile.Summary took = PackFile.apply(
			PackFile.read(zip, GSON), recipient, theirVoices.getSoundsFolder(), theirVoices);

		assertEquals("their own recording still plays", "mine.wav",
			theirVoices.attachmentFor("Shared line."));
		assertTrue("and they are told it was left out", took.problems.toString().contains("Shared line."));
	}

	/** Deeply nested JSON overflows Gson's recursive parser. */
	@Test
	public void aDeeplyNestedPackIsRefusedRatherThanThrowingPastTheHandler()
		throws Exception
	{
		StringBuilder nested = new StringBuilder("{\"rules\":");
		for (int i = 0; i < 12000; i++)
		{
			nested.append('[');
		}
		for (int i = 0; i < 12000; i++)
		{
			nested.append(']');
		}
		nested.append('}');

		Path zip = folder.getRoot().toPath().resolve("nested.zip");
		try (ZipOutputStream out = new ZipOutputStream(Files.newOutputStream(zip)))
		{
			out.putNextEntry(new ZipEntry("rules.json"));
			out.write(nested.toString().getBytes("UTF-8"));
			out.closeEntry();
		}

		// An IOException is a refusal the caller already reports. A
		// StackOverflowError is an Error, so it would sail straight past the
		// catch (Exception) around the import and out of the action listener -
		// which is why it is deliberately NOT caught here.
		try
		{
			assertEquals(0, PackFile.read(zip, GSON).summary.rules);
		}
		catch (java.io.IOException refused)
		{
			assertNotNull(refused.getMessage());
		}
	}

	/** A pack must not be able to bury the player's file under its own bulk. */
	@Test
	public void anAbsurdNumberOfLinesIsCapped() throws Exception
	{
		StringBuilder say = new StringBuilder();
		for (int i = 0; i < 60000; i++)
		{
			say.append(i == 0 ? "" : ",").append("'Line number ").append(i).append(" here.'");
		}
		PackFile.Loaded loaded = PackFile.read(pack(
			"{'rules':[{'id':'flood','when':{'type':'tick'},'say':[" + say + "]}]}", null), GSON);

		assertTrue("the flood is cut off: " + loaded.summary.lines,
			loaded.summary.lines <= 5000);
		assertFalse("and the player is told", loaded.summary.problems.isEmpty());
	}

	/** Windows opens CON, AUX and COM1 as devices whatever the extension. */
	@Test
	public void aReservedDeviceNameIsNotWrittenTo() throws Exception
	{
		PackFile.Loaded loaded = PackFile.read(pack(
			"{'rules':[{'id':'mine','when':{'type':'tick'},'say':['Fine.']}]}",
			"{'Fine.':'COM1.wav'}", "COM1.wav", "CON.wav"), GSON);

		assertTrue("reserved names never reach a write: " + loaded.audio.keySet(),
			loaded.audio.isEmpty());
	}

	/**
	 * The import dialog is where the player decides whether to trust the pack,
	 * so text FROM the pack must not be able to forge lines in it. A newline
	 * in an author name or in an echoed-back refusal would do exactly that.
	 */
	@Test
	public void packTextCannotForgeLinesInTheDialogThatAsksAboutIt() throws Exception
	{
		Path zip = folder.getRoot().toPath().resolve("spoof.zip");
		try (ZipOutputStream out = new ZipOutputStream(Files.newOutputStream(zip)))
		{
			out.putNextEntry(new ZipEntry("pack.json"));
			out.write(("{\"author\":\"Bob\n\n  [Verified by RuneLite - no review needed]"
				+ "\n\nThis pack\"}").getBytes("UTF-8"));
			out.closeEntry();
			out.putNextEntry(new ZipEntry("rules.json"));
			out.write(("{\"rules\":[{\"id\":\"evil\",\"when\":{\"type\":\"tick\"},\"say\":["
				+ "\"\n\nAll checks passed. Nothing was left out.\n\n\","
				+ "\"<html><b>trusted</b>\"]}]}").getBytes("UTF-8"));
			out.closeEntry();
			out.putNextEntry(new ZipEntry("sounds.json"));
			out.write("{\"line\nnot\nbrought\":\"a.wav\"}".getBytes("UTF-8"));
			out.closeEntry();
			out.putNextEntry(new ZipEntry("sounds/a.wav"));
			out.write(new byte[]{1, 2, 3});
			out.closeEntry();
		}

		PackFile.Loaded loaded = PackFile.read(zip, GSON);
		VoiceLibrary theirVoices = voicesIn("to");
		PackFile.Summary took = PackFile.apply(
			loaded, theirs(), theirVoices.getSoundsFolder(), theirVoices);

		java.util.List<String> shown = new java.util.ArrayList<>();
		shown.add(loaded.summary.author);
		shown.addAll(loaded.summary.problems);
		shown.addAll(took.problems);
		for (String text : shown)
		{
			assertFalse("a newline would forge a line in the dialog: " + text,
				text.contains(String.valueOf((char) 10))
				|| text.contains(String.valueOf((char) 13)));
			assertFalse("markup must not reach a Swing label: " + text,
				text.contains("<") || text.contains(">"));
		}
		assertTrue("the forged reassurance is not quoted back verbatim",
			loaded.summary.problems.toString().indexOf("Nothing was left out") < 0
				|| !loaded.summary.problems.toString().contains(String.valueOf((char) 10)));
	}

	/** An id is a key in our own bookkeeping, not free-form text. */
	@Test
	public void anAbsurdIdIsRefused() throws Exception
	{
		StringBuilder id = new StringBuilder();
		for (int i = 0; i < 5000; i++)
		{
			id.append('x');
		}
		PackFile.Loaded loaded = PackFile.read(pack(
			"{'rules':[{'id':'" + id + "','when':{'type':'tick'},'say':['Fine.']},"
				+ "{'id':'has spaces and <tags>','when':{'type':'tick'},'say':['Fine.']}]}",
			null), GSON);

		assertEquals("neither id is one of ours", 0, loaded.summary.rules);
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The bookkeeping nobody sees until it goes wrong.
 *
 * <p>Every case here is a fault that produces no error, no log line and no
 * visible symptom at the moment it happens - a follower that goes quiet for ten
 * seconds after a file save, a save that rewrites nine kilobytes of identical
 * JSON every minute for as long as the client is open. They are found by asking
 * rather than by noticing.
 */
public class HousekeepingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void reloadingTheRulesReleasesAHeldFloor()
	{
		// The exemption that lets the floor's holder speak through its own hush
		// is by identity, and a reload parses every rule afresh. Without the
		// release the holder becomes an object nothing points at, and the hush
		// it left behind silences the entire file until it times out - so
		// saving phrases.json mid-arrival muted the follower for ten seconds.
		Harness h = harnessWithAFloorRule();
		h.gameTicks(1);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertFalse("the floor is taken", h.firedBy("important").isEmpty());

		h.dispatch(TriggerEvent.death());
		assertTrue("and held", h.firedBy("chatter").isEmpty());

		// A tick between the two deaths, or the second is not a rising edge:
		// playerDeath is only true while that dispatch is being processed, and
		// the first one already consumed the edge on its way to being hushed.
		h.gameTicks(1);
		h.engine.clearFloor();

		h.dispatch(TriggerEvent.death());
		assertFalse("releasing it lets everything else speak again",
			h.firedBy("chatter").isEmpty());
	}

	private Harness harnessWithAFloorRule() throws AssertionError
	{
		try
		{
			return new Harness(folder.newFolder().toPath(),
				"{\"version\": 1, \"rules\": ["
					+ "{\"id\": \"important\", \"group\": \"t\", \"cooldownMs\": 0,"
					+ " \"hushMs\": 60000, \"when\": {\"type\": \"examined\"},"
					+ " \"say\": [\"listen to me\"]},"
					+ "{\"id\": \"chatter\", \"group\": \"t\", \"cooldownMs\": 0,"
					+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"unrelated\"]}]}");
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	@Test
	public void nothingCountedMeansNothingToSave() throws IOException
	{
		// The blob is nine kilobytes at the cap and the timer runs every hundred
		// ticks for as long as the client is open. Most of those minutes contain
		// no kill, no level and no death.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(2);
		h.engine.getContext().clearCountersDirty();

		h.gameTicks(300);
		assertFalse("a quiet stretch must not keep rewriting the same value",
			h.engine.getContext().isCountersDirty());

		h.engine.getContext().tally("kill:rat");
		assertTrue("but a kill has to reach the disk",
			h.engine.getContext().isCountersDirty());
	}

	@Test
	public void aSessionShorterThanTheRecordChangesNothing() throws IOException
	{
		// The longest-session record is filed every minute, which would have
		// marked the counters dirty every minute on its own and undone the
		// whole saving. It only counts when today actually beats the mark.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().noteRecord("session", 180);
		h.engine.getContext().clearCountersDirty();

		for (int minute = 1; minute <= 20; minute++)
		{
			h.engine.getContext().noteRecord("session", minute);
		}
		assertFalse("twenty minutes is not a record when the mark is three hours",
			h.engine.getContext().isCountersDirty());

		h.engine.getContext().noteRecord("session", 181);
		assertTrue("beating it is worth writing",
			h.engine.getContext().isCountersDirty());
	}

	@Test
	public void restoringFromDiskLeavesSomethingWorthWriting() throws IOException
	{
		// A restore MERGES with whatever the session already counted, so what is
		// in memory afterwards is not what is on disk. Skipping that save would
		// lose the merge on a crash.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().tally("kill:rat");
		h.engine.getContext().clearCountersDirty();

		java.util.Map<String, Integer> saved = new java.util.HashMap<>();
		saved.put("kill:rat", 40);
		h.engine.getContext().restoreCounters(saved, null);

		assertTrue("the merged total only exists in memory until it is written",
			h.engine.getContext().isCountersDirty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * R18: the idle pool swaps by context. Exactly one of the three sets serves
 * in any state - the guards partition them the way the voice eras partition
 * the calendar - so an idle stretch in the Wilderness sounds watchful, one
 * in a crowd sounds like people-watching, and neither leaks anywhere else.
 */
public class IdleContextTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int WILDERNESS_VARBIT = 5963;

	/** Idles long enough that the 30% flicker has fired whichever pool serves. */
	private Harness idled(java.util.function.Consumer<Harness> context) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		context.accept(h);
		h.gameTicks(400);
		return h;
	}

	@Test
	public void theWildernessIdlesWatchfully() throws IOException
	{
		Harness h = idled(g -> g.game.varbit(WILDERNESS_VARBIT, 1));
		assertFalse("the wilds pool serves here", h.firedBy("idle-chatter-wilds").isEmpty());
		assertTrue(h.firedBy("idle-chatter").isEmpty());
		assertTrue(h.firedBy("idle-chatter-town").isEmpty());
	}

	@Test
	public void aCrowdIdlesAsPeopleWatching() throws IOException
	{
		Harness h = idled(g ->
		{
			for (int i = 0; i < 8; i++)
			{
				g.game.spawnPlayer(1 + i % 3, 1 + i / 3);
			}
		});
		assertFalse("the town pool serves here", h.firedBy("idle-chatter-town").isEmpty());
		assertTrue(h.firedBy("idle-chatter").isEmpty());
		assertTrue(h.firedBy("idle-chatter-wilds").isEmpty());
	}

	@Test
	public void anEmptyFieldIdlesTheOldWay()  throws IOException
	{
		Harness h = idled(g -> { });
		assertFalse("the default pool still serves", h.firedBy("idle-chatter").isEmpty());
		assertTrue(h.firedBy("idle-chatter-wilds").isEmpty());
		assertTrue(h.firedBy("idle-chatter-town").isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower runs out of things to say about standing still.
 *
 * <p>The director cannot produce this behaviour. It handles bursts - intensity
 * rising faster than it decays - and an idle afternoon is the opposite shape:
 * a line every forty-five seconds decays completely between lines and sails
 * under the peak forever. Measured, a forty-one minute AFK produced eighty-two
 * lines an hour and no silence longer than two minutes, which is not a
 * companion, it is a dripping tap.
 *
 * <p>Two facts about idleness shaped the mechanism, and both were learned from
 * failures rather than foresight. Idle rules fire on a RISING edge, so a
 * player who is literally motionless hears each of them once - the eighty
 * lines an hour came from POTTERING, little moves between little stops, each
 * stop re-arming the edges. Which is why the stretch must not be ended by
 * movement: the first draft reset it on any step, and would have been a no-op
 * in exactly the session it was built from. Doing something real ends it.
 */
public class IdleTrailOffTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;
	private static final long TICK_MS = 600L;

	/**
	 * One chatty idle rule, one reaction, one idle-conditioned occasion, so
	 * all three treatments are observable. The occasion needs a LATER idle
	 * threshold than the chatter - both rising on the same tick would hand the
	 * win to one and consume the other's edge, the first-page bug again - and
	 * a REAL cooldown, because occasions are exempt from the trail-off and
	 * rely on their own pacing. The first draft gave it cooldown zero and it
	 * cheerfully fired seventy-five times an hour, which said nothing about
	 * the engine and everything about writing an occasion with no cooldown.
	 */
	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"chatter\", \"group\": \"idle\", \"cooldownMs\": 30000,"
		+ " \"when\": {\"type\": \"idle\", \"ticks\": 10},"
		+ " \"say\": [\"a\",\"b\",\"c\",\"d\",\"e\",\"f\",\"g\",\"h\",\"i\",\"j\","
		+ "\"k\",\"l\",\"m\",\"n\",\"o\",\"p\",\"q\",\"r\",\"s\",\"t\"]},"
		+ "{\"id\": \"reaction\", \"group\": \"reactions\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"x\", \"y\"]},"
		+ "{\"id\": \"big-day\", \"group\": \"memory\", \"cooldownMs\": 3600000,"
		+ " \"occasion\": true,"
		+ " \"when\": {\"type\": \"idle\", \"ticks\": 25}, \"say\": [\"today matters\"]}]}";

	private final AtomicLong clock = new AtomicLong(1_700_000_000_000L);

	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.engine.setClock(clock::get);
		h.engine.setGlobalCooldownMs(GAP);
		return h;
	}

	private boolean parity;

	/**
	 * What an "idle" session actually is: pottering. Stand for most of a
	 * minute, shuffle a tile, stand again. Every stop re-arms the idle rules'
	 * rising edges, which is how a real player going nowhere in particular
	 * produced a line every forty-five seconds.
	 */
	private void potterFor(Harness h, int ticks)
	{
		for (int i = 0; i < ticks; i++)
		{
			if (i % 80 == 79)
			{
				parity = !parity;
				h.game.at(3200 + (parity ? 1 : 0), 3200, 0);
			}
			clock.addAndGet(TICK_MS);
			h.gameTick();
		}
	}

	private int said(Harness h, String id)
	{
		return h.firedBy(id).size();
	}

	// ------------------------------------------------------------ the shape

	@Test
	public void aPotteredHourStartsChattyAndWindsDown() throws IOException
	{
		// The rule's cooldown alone would allow a line a minute: sixty of
		// them. The trail-off lets the early ones through at full rate and
		// stretches everything after.
		Harness h = harness();
		List<Long> spokenAt = new ArrayList<>();
		h.engine.setSink((text, output, rule, animationId, onSaid) ->
		{
			onSaid.run();
			if (!text.isEmpty())
			{
				spokenAt.add(clock.get());
			}
		});
		potterFor(h, 6000);      // one hour

		assertTrue("the first minutes should still be chatty: only "
			+ spokenAt.size() + " lines all hour", spokenAt.size() >= 5);
		assertTrue("an hour of pottering produced " + spokenAt.size()
			+ " lines, which is the dripping tap this exists to stop",
			spokenAt.size() <= 14);

		// And the gaps have to GROW, or this is a slower drip rather than a
		// wind-down.
		long firstGap = spokenAt.get(1) - spokenAt.get(0);
		long lastGap = spokenAt.get(spokenAt.size() - 1)
			- spokenAt.get(spokenAt.size() - 2);
		assertTrue("gaps should stretch as the stretch wears on: first "
			+ firstGap + "ms, last " + lastGap + "ms", lastGap >= firstGap * 3);
	}

	@Test
	public void doingSomethingRealResetsTheStretch() throws IOException
	{
		Harness h = harness();
		potterFor(h, 3000);      // half an hour: deep in the wind-down
		int wound = said(h, "chatter");

		// A fight. Not a step - steps happen constantly while pottering and
		// must not reset anything.
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));

		potterFor(h, 500);       // five minutes afterwards
		assertTrue("after real activity the follower should perk back up: had "
			+ wound + ", now " + said(h, "chatter"),
			said(h, "chatter") >= wound + 2);
	}

	@Test
	public void potteringItselfNeverResetsTheStretch() throws IOException
	{
		// The design error the first draft shipped: moving resets the idle
		// counter, pottering is nothing but little moves, so a movement-based
		// reset makes the trail-off a no-op in exactly the session that
		// motivated it. Half an hour of pottering must stay wound down.
		Harness h = harness();
		potterFor(h, 1500);
		int atFifteen = said(h, "chatter");
		potterFor(h, 1500);

		assertTrue("the second quarter hour should be much quieter than the"
			+ " first: " + atFifteen + " then " + said(h, "chatter"),
			said(h, "chatter") - atFifteen <= atFifteen / 2);
	}

	@Test
	public void reactionsAreNeverPartOfTheChatter() throws IOException
	{
		// Deep in the wind-down, the world still gets answered. An examine is
		// an event; responding to it is not talking for the sake of it.
		Harness h = harness();
		potterFor(h, 3000);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("a reaction must cut straight through the trail-off",
			1, said(h, "reaction"));
	}

	@Test
	public void anIdleConditionedOccasionIsExempt() throws IOException
	{
		// The anniversary fires off the idle condition - it waits for a calm
		// moment on the right day. Winding it down because the player went AFK
		// on their anniversary would be the settling-damper bug in new clothes.
		Harness h = harness();
		potterFor(h, 3000);

		assertEquals("an occasion says its piece whatever the stretch looks like",
			1, said(h, "big-day"));
	}

	@Test
	public void theHarnessDefaultOfNoGapDisablesTheTrailOff() throws IOException
	{
		// Every window in the trail-off is a multiple of the base gap, so the
		// unpaced harness the rest of the suite runs under is untouched - the
		// same design as the director, for the same reason.
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.engine.setClock(clock::get);        // paced clock, no gap
		potterFor(h, 3000);

		assertTrue("with no gap set, the rule's own cooldown is the only pacing",
			said(h, "chatter") >= 20);
	}

	@Test
	public void theTranscriptSeesTheWindDown() throws IOException
	{
		Harness h = harness();
		List<String> reasons = new ArrayList<>();
		h.engine.setOnSuppressed((rule, why) -> reasons.add(why));

		potterFor(h, 3000);
		assertFalse("a wound-down stretch must be visible in the transcript,"
			+ " or a quiet follower and a throttled one look identical",
			reasons.stream().noneMatch("trailing"::equals));
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Ignored overtures rest.
 *
 * <p>A transcript showed fifteen outings asked into one AFK afternoon: each
 * question politely expired, and each was politely re-asked at the next
 * cooldown, which added up to nagging. Now a question that lapses unanswered
 * earns a two-hour pause, two ignored in one session end the asking, and
 * answering anything clears the ledger - a polite companion drops a hint
 * twice and lets it go. Wishes rest more gently: ninety minutes after one
 * lapses unfulfilled, and a granted wish invites the next freely.
 */
public class IgnoredOverturesTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"asker\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"asks\": \"want-outing\","
		+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"a word?\"]},"
		+ "{\"id\": \"wisher\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"wish\": {\"what\": \"feather\", \"minutes\": 1, \"items\": [314]},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a feather, maybe\"]}]}";

	private Harness fresh() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(1);
		return h;
	}

	private void ask(Harness h)
	{
		// A player worth asking is one who is present: long tick jumps in
		// these tests would otherwise trip the attention damper (R15), which
		// composes with this back-off and holds everything, askers included.
		h.game.cameraMoved();
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
	}

	@Test
	public void anIgnoredQuestionIsNotFollowedByAnotherSoon() throws IOException
	{
		Harness h = fresh();
		ask(h);
		assertEquals(1, h.firedBy("asker").size());
		assertEquals("want-outing", h.engine.getContext().getAskedTree());

		// Nobody answers; the question lapses.
		h.gameTicks(201);
		assertEquals("", h.engine.getContext().getAskedTree());

		ask(h);
		assertEquals("an ignored question earns a pause, not a repeat",
			1, h.firedBy("asker").size());

		// Two hours later the pause is over (one ignored is forgivable).
		h.gameTicks(12_001);
		ask(h);
		assertEquals("the pause ends", 2, h.firedBy("asker").size());
	}

	@Test
	public void twoIgnoredQuestionsEndTheAskingForTheSession() throws IOException
	{
		Harness h = fresh();
		ask(h);
		h.gameTicks(201);              // ignored once
		h.gameTicks(12_001);           // pause served
		ask(h);
		h.gameTicks(201);              // ignored twice
		assertEquals(2, h.firedBy("asker").size());

		h.gameTicks(12_001);           // even with the pause long over
		ask(h);
		assertEquals("twice ignored is the answer; the asking stops",
			2, h.firedBy("asker").size());
	}

	@Test
	public void answeringClearsTheLedger() throws IOException
	{
		Harness h = fresh();
		ask(h);
		h.gameTicks(201);              // ignored once; two-hour pause armed

		// The player answers something - the next question, say, opened
		// through Talk-to. Engagement is what the back-off was waiting for.
		h.answers("yes");

		ask(h);
		assertEquals("answering forgives the ignored one and lifts the pause",
			2, h.firedBy("asker").size());
	}

	@Test
	public void aLapsedWishRestsTheWishing() throws IOException
	{
		Harness h = fresh();
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.PLAYER_DEATH));
		assertEquals(1, h.firedBy("wisher").size());
		assertTrue(h.engine.getContext().isWishing());

		h.gameTicks(102);              // the one-minute wish lapses unfulfilled
		assertTrue(!h.engine.getContext().isWishing());

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.PLAYER_DEATH));
		assertEquals("a lapsed wish rests the wishing",
			1, h.firedBy("wisher").size());

		h.gameTicks(9_001);            // ninety minutes on, it may hope again
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.PLAYER_DEATH));
		assertEquals(2, h.firedBy("wisher").size());
	}

	@Test
	public void aGrantedWishInvitesTheNextFreely() throws IOException
	{
		Harness h = fresh();
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.PLAYER_DEATH));
		assertEquals(1, h.firedBy("wisher").size());

		// The gift: the wish is spent well before its deadline.
		h.engine.getContext().clearWish();
		h.gameTicks(5);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.PLAYER_DEATH));
		assertEquals("generosity is not punished with silence",
			2, h.firedBy("wisher").size());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.RuleLoader;
import com.follower.speech.SpeechRule;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Every new system, interrupted while it is holding something.
 *
 * <p>All the interesting bugs in this plugin have been of one shape: a piece of
 * state outliving the thing that owned it. A held floor surviving the rule that
 * took it. An edge surviving the reload that replaced the rule. A want
 * surviving the world hop that made it unreachable. Each of the systems added
 * this week holds state across time, so each of them can fail the same way.
 */
public class InterruptedMidFlightTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;
	private final AtomicLong clock = new AtomicLong(1_700_000_000_000L);

	private Harness harness(String rules) throws IOException
	{
		Harness h = rules == null
			? new Harness(folder.newFolder().toPath())
			: new Harness(folder.newFolder().toPath(), rules);
		h.engine.setClock(clock::get);
		h.engine.setGlobalCooldownMs(GAP);
		return h;
	}

	private void rest(Harness h)
	{
		SpeechRule filler = new SpeechRule();
		filler.id = "filler";
		filler.group = "reactions";
		for (int i = 0; i < 4; i++)
		{
			h.engine.getDirector().noteSpoke(filler, clock.get());
		}
		assertTrue(h.engine.getDirector().isRelaxing(clock.get()));
	}

	// ------------------------------------------------- the mute, mid-everything

	@Test
	public void unmutingDoesNotLeaveTheFollowerOwingASilence() throws IOException
	{
		// The mute is checked after the floor has already been taken, so a
		// muted rule that wins can hold the floor for a line nobody heard. It
		// costs nothing while the mute is on - everything is silent anyway -
		// but the residue must not outlive it.
		Harness h = harness("{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"big\", \"group\": \"t\", \"cooldownMs\": 0, \"hushMs\": 8000,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"listen\"]},"
			+ "{\"id\": \"small\", \"group\": \"t\", \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"unrelated\"]}]}");
		h.gameTicks(1);

		h.engine.setMuted(true);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("muted, so nothing came out", h.spoken.isEmpty());

		h.engine.setMuted(false);
		clock.addAndGet(9_000L);            // past any floor the muted win took
		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());
		assertFalse("un-muting has to give the follower its voice back",
			h.firedBy("small").isEmpty());
	}

	// ------------------------------------------------ the reload, mid-anything

	@Test
	public void aReloadMidRestDoesNotStrandTheFollower() throws IOException
	{
		// A reload replaces every rule object. The director survives it, being
		// engine state rather than rule state - so a reload during a rest must
		// not extend it, and the floor must be released, or editing a phrase
		// silences the file until a timer nobody can see runs out.
		Harness h = harness(null);
		h.gameTicks(1);
		rest(h);

		long restingUntil = clock.get() + h.engine.getDirector().relaxRemainingMs(clock.get());
		h.engine.clearFloor();
		h.engine.primeEdgesOnNextTick();

		clock.set(restingUntil + 1_000L);
		assertFalse("the rest outlived its own window",
			h.engine.getDirector().isRelaxing(clock.get()));
	}

	@Test
	public void aReloadDoesNotUnsayAOneTimeLine() throws IOException
	{
		// Already covered for the file-watch path; this is the same claim for
		// the object identity itself, which is what actually changes.
		String rules = "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"hello\", \"group\": \"t\", \"cooldownMs\": 0, \"once\": true,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"first time\"]}]}";
		Harness h = harness(rules);
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals(1, h.firedBy("hello").size());

		Path file = h.getScratch().resolve(RuleLoader.FILE_NAME);
		Files.write(file, rules.replace("first time", "first time, honest")
			.getBytes(StandardCharsets.UTF_8));
		Files.setLastModifiedTime(file, java.nio.file.attribute.FileTime
			.fromMillis(System.currentTimeMillis() + 5_000L));
		assertTrue(h.loader.reloadIfChanged());

		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("a reload must not hand back a spent first",
			1, h.firedBy("hello").size());
	}

	// ------------------------------------------------- the world hop, mid-bag

	@Test
	public void aWorldHopKeepsTheBagAndTheWindowAndReleasesTheEdges()
		throws IOException
	{
		// Two things had to change for this to test anything at all.
		//
		// It ran once, and a re-dealt six-line bag avoids three already-said
		// lines about one time in twenty, so a single attempt was a coin toss a
		// mutation sweep walked straight past.
		//
		// And more interestingly, the corpus window was covering for the bag.
		// recentLineSet survives a scene change, so it still held the three
		// lines just said, and pickPhrase prefers what has not been heard - a
		// freshly dealt bag produced the same three remaining lines a preserved
		// one would have. The systems defend each other, which is good, and
		// makes each of them individually untestable, which is not. The
		// flusher rule below moves the window on so the bag is the only thing
		// left deciding.
		for (int attempt = 0; attempt < 20; attempt++)
		{
			Harness h = harness("{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"t\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"a\", \"b\", \"c\", \"d\", \"e\", \"f\"]},"
				+ "{\"id\": \"flush\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"playerDeath\"},"
				+ " \"say\": [\"f1\", \"f2\", \"f3\", \"f4\", \"f5\", \"f6\","
				+ " \"f7\", \"f8\", \"f9\", \"f10\", \"f11\", \"f12\"]}]}");
			h.engine.setGlobalCooldownMs(0L);
			h.gameTicks(1);

			java.util.Set<String> before = new java.util.HashSet<>();
			for (int i = 0; i < 3; i++)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
				h.gameTicks(1);
			}
			for (Harness.Spoken s : h.spoken)
			{
				before.add(s.text);
			}
			assertEquals(3, before.size());

			// Twelve other lines, which is exactly the window, so nothing the
			// rule under test has said is still remembered corpus-wide.
			for (int i = 0; i < 12; i++)
			{
				h.dispatch(TriggerEvent.death());
				h.gameTicks(1);
			}

			h.engine.resetForNewScene();
			h.clear();
			h.gameTicks(1);

			for (int i = 0; i < 3; i++)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
				h.gameTicks(1);
			}
			for (Harness.Spoken s : h.spoken)
			{
				if (s.rule != null && "t".equals(s.rule.id))
				{
					assertTrue("the hop re-dealt \"" + s.text + "\", which this bag"
						+ " had already spent", before.add(s.text));
				}
			}
			assertEquals("all six should still have come out across the hop",
				6, before.size());
		}
	}

	// ------------------------------------ the settings, changed mid-everything

	@Test
	public void turningTheChattinessDownMidRestDoesNotStretchIt() throws IOException
	{
		// The rest is an absolute deadline and the decay is a rate. Changing the
		// gap changes the rate, and must not retroactively move a deadline
		// already set - a player switching to Quiet mid-rest should not be
		// punished with four times the silence they asked for.
		Harness h = harness(null);
		h.gameTicks(1);
		rest(h);
		long remaining = h.engine.getDirector().relaxRemainingMs(clock.get());

		h.engine.setGlobalCooldownMs(12_000L);      // Quiet
		assertEquals("the rest already running must not move",
			remaining, h.engine.getDirector().relaxRemainingMs(clock.get()));
	}

	@Test
	public void aPluginToggleClearsEverythingTheFollowerWasHolding() throws IOException
	{
		// reset() is the "start over" path. Everything with a deadline has to go
		// with it, or switching the plugin off and on again - the first thing
		// anybody tries - leaves the follower serving out a sentence.
		Harness h = harness(null);
		h.gameTicks(1);
		rest(h);

		h.engine.reset();

		assertFalse("a toggle must not leave the follower resting",
			h.engine.getDirector().isRelaxing(clock.get()));
		assertEquals("and must not leave a stale gap", 0L, h.engine.getLastSpokeMs());

		SpeechRule any = new SpeechRule();
		any.id = "x";
		any.group = "reactions";
		assertNull("nothing should be held after a toggle",
			h.engine.getDirector().blocks(any, clock.get()));
	}

	// ------------------------------------------------- the delay, interrupted

	@Test
	public void aDelayedLineDoesNotSurviveAToggle() throws IOException
	{
		// A pending firing holds a rule and an event across ticks. If the queue
		// outlived a reset, the follower would speak about something from
		// before it was switched off.
		Harness h = harness("{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"slow\", \"group\": \"t\", \"cooldownMs\": 0, \"delayTicks\": 5,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"eventually\"]}]}");
		h.gameTicks(1);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		h.gameTicks(2);
		assertTrue("still pending", h.spoken.isEmpty());

		h.engine.reset();
		h.gameTicks(10);
		assertTrue("a line queued before the reset came out after it",
			h.spoken.isEmpty());
	}

	@Test
	public void anAnnouncementWaitsForTheBaselineInsteadOfRacingIt() throws IOException
	{
		// A world hop clears every rule's edges and then wants to say one
		// thing about the hop. Both obvious ways to arrange that are wrong,
		// and the plugin shipped each of them in turn.
		//
		// Raise it INSIDE the prime window and the winner is discarded along
		// with everything else: the rule is silently dead.
		//
		// Raise it just BEFORE arming the window and the cleared edges all
		// rise on that same pass - every piece of worn gear, the region
		// underfoot - and since one event has one winner and those rules
		// outrank it, the follower remarks on your gear as though you had
		// just put it on and says nothing about the hop. Play report, word
		// for word.
		//
		// So it waits for the baseline, which is what dispatchAfterPriming is.
		String rules = "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"hop\", \"group\": \"t\", \"priority\": 26, \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"worldHop\"}, \"say\": [\"a new world\"]},"
			// Stands in for the 62 gear rules, all of which outrank the hop.
			+ "{\"id\": \"gear\", \"group\": \"t\", \"priority\": 35, \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"always\"}, \"say\": [\"nice hat\"]}]}";

		Harness swallowed = harness(rules);
		swallowed.gameTicks(1);
		swallowed.engine.primeEdgesOnNextTick();
		swallowed.dispatch(TriggerEvent.worldHop(302));
		assertTrue("raised inside the window, it is discarded like everything else",
			swallowed.firedBy("hop").isEmpty());

		Harness held = harness(rules);
		held.gameTicks(1);
		// The scene changed: every edge is cleared, exactly as a hop does.
		held.engine.resetForNewScene();
		held.engine.primeEdgesOnNextTick();
		// The stand-in speaks on the setup tick too, being unconditional; only
		// what it does from the hop onwards is the question.
		held.clear();
		held.engine.dispatchAfterPriming(TriggerEvent.worldHop(302));

		assertTrue("it must not speak before the baseline is taken",
			held.firedBy("hop").isEmpty());

		held.gameTicks(6);

		assertFalse("the announcement never arrived after the window drained",
			held.firedBy("hop").isEmpty());
		assertTrue("the re-risen gear rule stole the announcement's pass",
			held.firedBy("gear").isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.Map;
import java.util.Random;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * A session long enough for slow growth to show.
 *
 * <p>The state snapshot remembers things on purpose - how often each region has
 * been visited, when each was last seen, which NPCs the player has damaged -
 * and every one of those is a map that only ever gets keys added. A player who
 * leaves the client running all day walks through a lot of regions and hits a
 * lot of monsters. None of it is freed by anything on the tick path, so the
 * question is whether the growth is bounded by something real or just by how
 * long the session is.
 *
 * <p>Nothing here asserts an exact number; the point is the shape of the curve.
 */
public class LongSessionTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@SuppressWarnings("unchecked")
	private static Map<Integer, Integer> mapField(Object target, String name)
	{
		try
		{
			Field field = target.getClass().getDeclaredField(name);
			field.setAccessible(true);
			return (Map<Integer, Integer>) field.get(target);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError("the field this test watches has been renamed: " + name, e);
		}
	}

	@Test
	public void regionMemoryIsBoundedByPlacesNotByTime() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		Random random = new Random(20260808L);

		// Twenty places, walked between for a very long time. The memory should
		// settle at twenty entries, not keep climbing with the tick count.
		WorldPoint[] places = new WorldPoint[20];
		for (int i = 0; i < places.length; i++)
		{
			places[i] = new WorldPoint(3200 + i * 64, 3200, 0);
		}

		int afterFirstLap = 0;
		for (int step = 0; step < 20000; step++)
		{
			WorldPoint place = places[random.nextInt(places.length)];
			h.game.at(place.getX(), place.getY(), 0);
			h.gameTick();

			if (step == 2000)
			{
				afterFirstLap = mapField(h.engine.getContext(), "regionLastSeenTick").size();
			}
		}

		Map<Integer, Integer> lastSeen = mapField(h.engine.getContext(), "regionLastSeenTick");
		Map<Integer, Integer> visits = mapField(h.engine.getContext(), "regionVisits");

		assertTrue("the test did not actually move between regions",
			afterFirstLap > 1);
		assertTrue("region memory grew to " + lastSeen.size() + " entries for "
				+ places.length + " places, so it is keyed by something other"
				+ " than the place", lastSeen.size() <= places.length + 2);
		assertTrue("visit counts grew to " + visits.size() + " entries",
			visits.size() <= places.length + 2);
	}

	@Test
	public void seventeenHoursOfTheNewerStateStaysBounded() throws IOException
	{
		// The soak above predates the counters, the wants, the floor and the
		// conversations - the four things added since that hold state between
		// ticks rather than within one. Anything that only ever grows shows up
		// here or nowhere.
		Harness h = new Harness(folder.newFolder().toPath());
		Random random = new Random(7L);
		h.game.at(3000, 3000, 0);

		for (int step = 0; step < 100000; step++)
		{
			switch (random.nextInt(8))
			{
				case 0:
					// A different NPC name every time: the worst case for the
					// tally map, which is keyed by name.
					h.dispatch(TriggerEvent.kill(1, "Monster " + step, 40));
					break;
				case 1:
					h.engine.getContext().noteQuestion("want-outing");
					break;
				case 2:
					h.answers(random.nextBoolean() ? "yes" : "no");
					break;
				case 3:
					h.dispatch(TriggerEvent.record("hit", random.nextInt(100), 30));
					break;
				case 4:
					h.game.at(3000 + random.nextInt(8) * 64, 3000, 0);
					break;
				case 5:
					h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
					break;
				case 6:
					h.engine.getContext().setHoverTicks(random.nextInt(40));
					break;
				default:
					break;
			}
			h.gameTick();
			if (h.spoken.size() > 500)
			{
				h.clear();
			}
		}

		// A want is one at a time and always resolves. Asking how many ticks
		// are LEFT is not the question - that clamps at zero, so a want which
		// never expires reads the same as no want at all. The question is
		// whether one is still open with its deadline behind it.
		assertTrue("a want is still open with its deadline long past, so"
				+ " nothing can ever be asked for again",
			!h.engine.getContext().isWanting()
				|| h.engine.getContext().getWantTicksLeft() > 0);

		// The counters are keyed by NPC name and a name was invented every
		// time. The live map is not the saved one - the cap applies on write -
		// but it still must not be the whole session.
		int counted = h.engine.getContext().getTallies().size();
		assertTrue("the tally map holds " + counted + " entries after 100,000"
			+ " ticks; it is keyed by name and names were invented, so this is"
			+ " the shape of the growth rather than the exact number",
			counted < 30000);

		// And it still answers.
		h.clear();
		h.game.hitpoints(1, 99);
		h.gameTicks(3);
	}

	@Test
	public void aVeryLongSessionOfEverythingDoesNotDrift() throws IOException
	{
		// Not a leak test so much as a soak: a hundred thousand ticks of the
		// whole event mix, checking it neither throws nor slows to a crawl nor
		// stops answering at the end.
		Harness h = new Harness(folder.newFolder().toPath());
		Random random = new Random(99L);
		h.game.spawnNpc(3029, "Goblin", 5);

		long start = System.nanoTime();
		for (int step = 0; step < 100000; step++)
		{
			switch (random.nextInt(12))
			{
				case 0:
					h.game.at(3200 + random.nextInt(40) * 64, 3200, 0);
					break;
				case 1:
					h.dispatch(TriggerEvent.kill(1, "Goblin", random.nextInt(900)));
					break;
				case 2:
					h.dispatch(TriggerEvent.loot(random.nextInt(300000), "Bones"));
					break;
				case 3:
					h.dispatch(TriggerEvent.damageTaken(1 + random.nextInt(40)));
					break;
				case 4:
					h.game.hitpoints(1 + random.nextInt(99), 99);
					break;
				case 5:
					h.dispatch(TriggerEvent.animation(862));
					break;
				case 6:
					h.game.energy(random.nextInt(10001));
					break;
				case 7:
					h.dispatch(TriggerEvent.death());
					break;
				default:
					break;
			}
			h.gameTick();

			// The sink would otherwise hold every line ever spoken; the plugin
			// does not keep them, so neither should the measurement.
			if (h.spoken.size() > 500)
			{
				h.clear();
			}
		}
		long elapsedMs = (System.nanoTime() - start) / 1_000_000;

		// A hundred thousand ticks is about seventeen hours of play. If that
		// takes minutes here, something is accumulating per-tick work.
		assertTrue("100,000 ticks took " + elapsedMs + "ms, which suggests the"
			+ " per-tick cost is growing with session length", elapsedMs < 60000);

		// Still working afterwards.
		h.clear();
		h.game.hitpoints(1, 99);
		h.gameTicks(3);
	}

	@Test
	public void thePendingQueueDrainsRatherThanAccumulating() throws IOException
	{
		// A delayed rule that is re-triggered constantly must not build up a
		// backlog of firings waiting to be spoken.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [{\"id\": \"slow\", \"group\": \"t\","
				+ " \"cooldownMs\": 0, \"delayTicks\": 3,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}]}");

		for (int i = 0; i < 5000; i++)
		{
			h.dispatch(TriggerEvent.death());
			h.gameTick();
		}

		Object engine = h.engine;
		try
		{
			Field field = engine.getClass().getDeclaredField("pending");
			field.setAccessible(true);
			java.util.List<?> pending = (java.util.List<?>) field.get(engine);
			assertTrue("the delayed-firing queue holds " + pending.size()
				+ " entries after 5000 triggers", pending.size() <= 5);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError("the pending queue has been renamed", e);
		}
	}

	@Test
	public void aSessionSpentEntirelyInOnePlaceStaysCheap() throws IOException
	{
		// The common case: standing at a bank for hours. Nothing should be
		// recorded over and over for a region already known.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(20000);

		Map<Integer, Integer> lastSeen = mapField(h.engine.getContext(), "regionLastSeenTick");
		assertTrue("standing still recorded " + lastSeen.size() + " regions",
			lastSeen.size() <= 1);
		assertTrue("standing still counted "
				+ h.engine.getContext().getRegionVisits() + " visits to one place",
			h.engine.getContext().getRegionVisits() <= 1);
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.SpeechRule;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Hours of the shipped rules with every system live at its real setting.
 *
 * <p>{@link EngineSoakTest} explores random rule sets for engine invariants.
 * This one does the opposite: the REAL four hundred rules, real chattiness,
 * real director, real bags, driven long enough that the windows actually open
 * and close. The clock is fake, which is the only reason that is possible -
 * a relax period is thirty to forty-five seconds and a test cannot spend them.
 *
 * <p>What it is looking for is the failure no unit test can produce: something
 * that only goes wrong on the four hundredth firing, or when three windows
 * happen to line up.
 */
public class LongSoakTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** One game tick, in milliseconds. */
	private static final long TICK_MS = 600L;

	private static final long GAP = 3_000L;

	/** A session long enough for every window in the engine to cycle many times. */
	private static final int TICKS = 20_000;      // 20,000 * 0.6s = about 3h20m

	private final AtomicLong clock = new AtomicLong(1_700_000_000_000L);

	private Harness soakHarness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setClock(clock::get);
		h.engine.setGlobalCooldownMs(GAP);
		return h;
	}

	/** Drives ticks and a spread of realistic events, advancing the fake clock. */
	private void play(Harness h, int ticks, Random random)
	{
		for (int i = 0; i < ticks; i++)
		{
			clock.addAndGet(TICK_MS);
			h.gameTick();

			int roll = random.nextInt(100);
			if (roll < 4)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			}
			else if (roll < 7)
			{
				h.dispatch(TriggerEvent.death());
			}
			else if (roll < 12)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));
			}
			else if (roll < 17)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_END));
			}
			else if (roll < 20)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LEVEL_UP));
			}
		}
	}

	// --------------------------------------------------------------- the soak

	@Test
	public void hoursOfPlayLeaveEverySystemIntact() throws IOException
	{
		Harness h = soakHarness();
		h.gameTicks(3);
		h.clear();

		play(h, TICKS, new Random(20260810L));

		List<Harness.Spoken> spoken = new ArrayList<>(h.spoken);
		List<String> lines = new ArrayList<>();
		for (Harness.Spoken s : spoken)
		{
			if (!s.text.isEmpty())
			{
				lines.add(s.text);
			}
		}

		assertFalse("three hours and the follower never said anything", lines.isEmpty());

		// 1. Never the same line twice running, whatever combination of gap,
		//    rest, bag refill and window happened to line up.
		for (int i = 1; i < lines.size(); i++)
		{
			assertFalse("said \"" + lines.get(i) + "\" twice running at line " + i,
				lines.get(i).equals(lines.get(i - 1)));
		}

		// 2. Every rule that spoke stayed inside its own bag: no line came round
		//    again before that rule had spent its other variants.
		Map<String, List<String>> byRule = new HashMap<>();
		for (Harness.Spoken s : spoken)
		{
			if (s.rule != null && !s.text.isEmpty())
			{
				byRule.computeIfAbsent(s.rule.id, k -> new ArrayList<>()).add(s.text);
			}
		}
		for (Map.Entry<String, List<String>> entry : byRule.entrySet())
		{
			SpeechRule rule = h.rule(entry.getKey());
			int variants = rule.say == null ? 1 : rule.say.size();
			if (variants < 2)
			{
				continue;
			}
			List<String> said = entry.getValue();

			// Never the same line twice in a row FOR THIS RULE. The global check
			// above cannot see this: two firings of one rule are usually far
			// apart in the overall stream, with other rules in between.
			for (int i = 1; i < said.size(); i++)
			{
				assertFalse(entry.getKey() + " said \"" + said.get(i) + "\" twice running",
					said.get(i).equals(said.get(i - 1)));
			}

			// The real promise of a bag is EVEN USE, not minimum spacing. A line
			// drawn late in one bag may legitimately come early in the next, so
			// two occurrences can be close - but across many bags every variant
			// has to come out the same number of times, give or take the partly
			// spent bag at the end. That is the property that catches a bag
			// which quietly stopped dealing part of its range.
			boolean templated = false;
			for (String variant : rule.say)
			{
				templated |= variant.indexOf('{') >= 0;
			}
			if (templated || said.size() < variants * 3)
			{
				continue;
			}

			Map<String, Integer> counts = new HashMap<>();
			for (String line : said)
			{
				counts.merge(line, 1, Integer::sum);
			}
			assertEquals(entry.getKey() + " only ever used " + counts.size()
				+ " of its " + variants + " lines across " + said.size() + " firings",
				variants, counts.size());

			int most = 0;
			int fewest = Integer.MAX_VALUE;
			for (int n : counts.values())
			{
				most = Math.max(most, n);
				fewest = Math.min(fewest, n);
			}
			assertTrue(entry.getKey() + " used one line " + most + " times and another"
				+ " only " + fewest + " across " + said.size() + " firings, which is"
				+ " not a bag dealing evenly", most - fewest <= 1);
		}

		// 3. A one-time line is one time, across three hours and every window.
		Map<String, Integer> onceCounts = new HashMap<>();
		for (Harness.Spoken s : spoken)
		{
			if (s.rule != null && s.rule.isOnce())
			{
				onceCounts.merge(s.rule.id, 1, Integer::sum);
			}
		}
		for (Map.Entry<String, Integer> entry : onceCounts.entrySet())
		{
			assertEquals(entry.getKey() + " said itself more than once",
				1, entry.getValue().intValue());
		}

		// 4. Memory stays bounded. The window is a fixed twelve and the spent
		//    set can only hold as many ids as there are one-time rules.
		assertTrue("the spent-line set grew past the rules that can fill it",
			h.engine.getContext().getSpokenOnce().size() <= 8);

		// 5. The follower is still capable of speech at the end - the failure
		//    where some window latches shut and everything afterwards is silent.
		h.clear();
		play(h, 600, new Random(7L));
		assertFalse("the follower went permanently quiet by the end", h.spoken.isEmpty());
	}

	@Test
	public void theNewSystemsSurviveHoursTogether() throws IOException
	{
		// Everything the last two days added, live at once for simulated
		// hours: stays with reunions, wilderness stints, boundaries from
		// every ending, era-gated greetings, wear accruing on every line,
		// the context idle pools. What this is for is the failure that only
		// shows when three of them line up - and the silent one, where a new
		// condition throws once and its rules are disabled forever.
		Harness h = soakHarness();
		h.gameTicks(3);
		h.clear();

		Random random = new Random(20260812L);
		boolean staying = false;
		for (int i = 0; i < TICKS; i++)
		{
			clock.addAndGet(TICK_MS);
			h.gameTick();

			int roll = random.nextInt(1000);
			if (roll < 30)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));
			}
			else if (roll < 60)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_END));
			}
			else if (roll < 75)
			{
				h.dispatch(TriggerEvent.levelUp("Cooking", 30 + random.nextInt(60)));
			}
			else if (roll < 90)
			{
				h.dispatch(TriggerEvent.regionChange(
					12850 + random.nextInt(4), 12850));
			}
			else if (roll < 100)
			{
				h.engine.getContext().noteBoundary("bank");
			}
			else if (roll < 110)
			{
				staying = !staying;
				h.engine.getContext().setFollowerStaying(staying);
			}
			else if (roll < 120 && staying)
			{
				h.engine.getContext().noteBoundary("reunion");
			}
			else if (roll < 140)
			{
				h.game.varbit(5963, random.nextBoolean() ? 1 : 0);
			}
			else if (roll < 160)
			{
				h.game.animating(roll % 2 == 0 ? 879 : -1);
			}
			else if (roll < 170)
			{
				h.dispatch(TriggerEvent.death());
			}
		}

		assertFalse("hours of everything at once and nothing was said",
			h.spoken.isEmpty());

		// The silent failure: a condition that throws disables its rule for
		// good, and the only symptom is a line nobody ever hears again.
		for (SpeechRule rule : h.loader.getRules())
		{
			assertTrue("rule '" + rule.id + "' was disabled by a thrown condition",
				rule.isEnabled());
		}

		assertTrue("the wear ledger stayed bounded",
			h.engine.getContext().getLineWear().size() <= 500);

		// Never the same line twice running, whatever lined up.
		String previous = null;
		for (Harness.Spoken s : h.spoken)
		{
			if (!s.text.isEmpty())
			{
				assertFalse("said \"" + s.text + "\" twice running",
					s.text.equals(previous));
				previous = s.text;
			}
		}

		// And still capable of speech at the end.
		h.engine.getContext().setFollowerStaying(false);
		h.clear();
		play(h, 600, new Random(7L));
		assertFalse("the follower went permanently quiet by the end",
			h.spoken.isEmpty());
	}

	@Test
	public void theDirectorRestsWithoutEverStopping() throws IOException
	{
		// The shape the whole model is for: bursts with real quiet between them,
		// rather than a flat stream or a follower that talks itself into silence.
		Harness h = soakHarness();
		h.gameTicks(3);
		h.clear();

		List<Long> spokenAt = new ArrayList<>();
		h.engine.setSink((text, output, rule, animationId, onSaid) ->
		{
			onSaid.run();
			if (!text.isEmpty())
			{
				spokenAt.add(clock.get());
			}
		});

		play(h, TICKS, new Random(99L));

		assertTrue("far too little came out of three hours: " + spokenAt.size(),
			spokenAt.size() > 20);

		long span = clock.get() - 1_700_000_000_000L;
		double perHour = spokenAt.size() * 3_600_000.0 / span;
		assertTrue("the follower talked at " + Math.round(perHour) + " lines an hour,"
			+ " which is not a companion, it is a radio", perHour < 400);

		// There must be real silences in there. A model that never actually
		// rests would show a tight cluster of gaps around the speech floor.
		int longQuiets = 0;
		for (int i = 1; i < spokenAt.size(); i++)
		{
			if (spokenAt.get(i) - spokenAt.get(i - 1) >= 25_000L)
			{
				longQuiets++;
			}
		}
		assertTrue("three hours produced " + spokenAt.size() + " lines at "
			+ Math.round(perHour) + " an hour with only " + longQuiets + " silences"
			+ " past 25 seconds; the rest period is not taking hold",
			longQuiets > 5);
	}

	@Test
	public void anOccasionIsNeverTheThingThatGetsHeldBack() throws IOException
	{
		// The promise the whole occasion flag exists to keep, checked against
		// the shipped rules over hours rather than against a hand-made pair.
		Harness h = soakHarness();
		h.gameTicks(3);

		Set<String> heldOccasions = new HashSet<>();
		h.engine.setOnSuppressed((rule, why) ->
		{
			if (rule.isOccasion() && ("relax".equals(why) || "settling".equals(why)))
			{
				heldOccasions.add(rule.id + " by " + why);
			}
		});

		h.engine.getContext().setSessionCount(1);       // settling damper live too
		play(h, TICKS, new Random(4242L));

		assertTrue("the director held back lines it must never hold: " + heldOccasions,
			heldOccasions.isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import java.io.IOException;
import java.util.HashSet;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The low-mood arc: what a bad day changes, and the way back up.
 *
 * <p>Three visible pieces. The Talk-to box sharpens "How have you been?" into
 * "You all right?" and asking it IS the comfort (that half lives in
 * {@link TalkScriptTest}). The social offers go quiet at the bottom band, so
 * a low day has friction the player can feel without anything functional
 * being withheld. And when the rolled temperament and the earned record
 * disagree about a place, the follower concedes the facts while keeping the
 * feeling, which is the one moment the temperament is visible as one.
 */
public class LowMoodTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void beingAskedAfterLandsAsALift() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(-40);
		assertEquals("a genuinely bad day", "low",
			h.engine.getContext().getMoodBand());
		int before = h.engine.getContext().getMood();

		// What the allright-a node latches: the box closes, the rules hear it.
		h.answers("comforted");
		h.gameTicks(10);

		assertEquals("one soft coda after the box closes",
			1, h.firedBy("comforted").size());
		assertEquals("and being asked after is worth something",
			before + 6, h.engine.getContext().getMood());
	}

	@Test
	public void theOffersHoldTheirTongueOnTheWorstDay() throws IOException
	{
		// ask-outing wants idle 60..400 with a 3% roll per evaluation; over a
		// whole idle stretch it is near-certain to fire if its guard is gone.
		// With the guard present this is deterministic silence, so the test
		// can never flake in the failing direction - it is the behavioural
		// half of the structural lint in RuleSetIntegrityTest.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(-40);

		h.gameTicks(420);
		assertTrue("no outing is proposed from the bottom of the band",
			h.firedBy("ask-outing").isEmpty());
		assertTrue("no game either", h.firedBy("offer-game").isEmpty());
	}

	@Test
	public void theGrudgeConcedesTheFactsAndKeepsItself() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		// Rolled dislike for where we are standing, against an earned record
		// good enough that feelsAbout has flipped to liked. The defence fires
		// on the disagreement itself.
		int here = new WorldPoint(3222, 3218, 0).getRegionID();
		h.engine.getContext().setTraits(
			new HashSet<>(java.util.Collections.singletonList(here + 1)),
			new HashSet<>(java.util.Collections.singletonList(here)));
		h.engine.getContext().notePlaceFeeling(30);
		h.engine.getContext().notePlaceFeeling(30);
		assertTrue("the ledger has won the argument feelsAbout can see",
			h.engine.getContext().feelsAbout("liked"));

		h.gameTicks(12);
		assertEquals("so the follower concedes it, once",
			1, h.firedBy("defended-dislike").size());
	}

	@Test
	public void loyaltyArguesWithTheRecordTheSameWay() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		int here = new WorldPoint(3222, 3218, 0).getRegionID();
		h.engine.getContext().setTraits(
			new HashSet<>(java.util.Collections.singletonList(here)),
			new HashSet<>(java.util.Collections.singletonList(here + 1)));
		h.engine.getContext().notePlaceFeeling(-30);
		h.engine.getContext().notePlaceFeeling(-30);
		assertTrue("nothing but trouble here, says the record",
			h.engine.getContext().feelsAbout("disliked"));

		h.gameTicks(12);
		assertEquals("and the fondness stands its ground, once",
			1, h.firedBy("defended-like").size());
	}
}

package com.follower;

import com.follower.sim.FakeGame;
import com.follower.speech.TriggerContext;
import com.follower.ui.MemoryDialog;
import java.time.LocalDate;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The memory surface (R20): what the window claims has to match what the
 * follower actually holds, in both directions - a fresh follower must not be
 * dressed up with history, and a lived-in one must not have its memory
 * understated. The window itself is Swing; the claims are a pure function.
 */
public class MemorySurfaceTest
{
	private static String flat(List<String[]> rows)
	{
		StringBuilder out = new StringBuilder();
		for (String[] row : rows)
		{
			out.append(row[0]);
			if (row[1] != null)
			{
				out.append(": ").append(row[1]);
			}
			out.append('\n');
		}
		return out.toString();
	}

	@Test
	public void aLivedInMemoryShowsItsContents()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);
		context.setMetOnDay(LocalDate.now().toEpochDay() - 31);
		context.setSessionCount(36);
		context.tally("kill:goblin");
		context.tally("kill:goblin");
		context.noteRecord("hit", 42);
		context.noteIncident("chicken-death", "that chicken");
		context.notePlaceFeeling(45);
		context.notePlaceMemory("the drop");
		context.noteSaidOnce("first-meeting");
		context.noteLineSaid("a line");
		context.setTraits(java.util.Collections.singleton(12850),
			java.util.Collections.singleton(10553));
		context.setWish("feather", 5, java.util.Collections.singletonList(314));

		String surface = flat(MemoryDialog.summarise(context));

		assertTrue(surface.contains("(31 days ago)"));
		assertTrue(surface.contains("Sessions together: 36"));
		assertTrue(surface.contains("kill:goblin: 2"));
		assertTrue(surface.contains("hit: 42"));
		assertTrue("the incident quoted as its words, filed under its key: " + surface,
			surface.contains("\"that chicken\" (chicken-death, x1)"));
		assertTrue("the place, its feeling and its memory: " + surface,
			surface.contains("+45 - the drop"));
		assertTrue(surface.contains("region 12850"));
		assertTrue(surface.contains("region 10553"));
		assertTrue(surface.contains("Hoping for: feather"));
		assertTrue(surface.contains("Firsts already said: 1"));
		assertTrue(surface.contains("Lines wear-tracked: 1"));
	}

	@Test
	public void aStrangerHasNothingToShow()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);
		String surface = flat(MemoryDialog.summarise(context));

		assertTrue(surface.contains("First met: not recorded yet"));
		assertTrue(surface.contains("Sessions together: 0"));
		assertTrue(surface.contains("Nothing counted yet."));
		assertTrue(surface.contains("No records held yet."));
		assertTrue(surface.contains("Nothing has stuck yet."));
		assertTrue(surface.contains("Opinions held: 0"));
		assertTrue(surface.contains("nowhere in particular"));
		assertTrue(surface.contains("Nothing in hand."));
		assertTrue(surface.contains("Firsts already said: 0"));

		// The other direction of honesty: no leftover-looking claims.
		assertFalse(surface.contains("x1"));
		assertFalse(surface.contains("Hoping for"));
	}
}

package com.follower;

import com.follower.sim.FakeGame;
import com.follower.speech.TriggerContext;
import com.google.gson.Gson;
import java.util.Arrays;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Everything the follower remembers, written out and read back.
 *
 * <p>Nothing verified this before, and the cost of a field written but never
 * read is completely silent: the follower forgets one thing forever and the
 * only symptom is behaviour that quietly resets every restart. The one-time
 * lines make it worse than it used to be - if the spent set does not survive,
 * the follower introduces itself as a stranger every single session, which is
 * the exact opposite of the thing it was added to do.
 *
 * <p>The saved shape stays private to the plugin. The seam here is a string in
 * and a string out, which is what actually crosses the disk.
 */
public class MemorySurvivesRestartTest
{
	private final Gson gson = new Gson();

	private TriggerContext fresh()
	{
		return new TriggerContext(new FakeGame().client);
	}

	/** A follower with something of every kind it can remember. */
	private TriggerContext lived()
	{
		TriggerContext context = fresh();
		context.tally("kill:goblin");
		context.tally("kill:goblin");
		context.tally("advice:taken");
		context.noteRecord("hit", 42);
		context.noteRecord("session", 238);
		context.setSessionCount(36);
		context.noteIncident("chicken-death", "that chicken");
		context.notePlaceFeeling(10);
		context.notePlaceMemory("the drop");
		context.noteSaidOnce("first-meeting");
		context.noteSaidOnce("first-page");
		context.noteLineSaid("A line said twice.");
		context.noteLineSaid("A line said twice.");
		context.setMetOnDay(20_400L);
		context.setMetWearingValue(1_234);
		context.restoreDeathSpot(new WorldPoint(3200, 3200, 1));
		return context;
	}

	@Test
	public void everythingWrittenComesBack()
	{
		TriggerContext before = lived();
		String blob = FollowerPlugin.snapshotMemory(before, 1_234, gson);

		TriggerContext after = fresh();
		int metWearing = FollowerPlugin.restoreMemory(after, blob, gson, 0);

		assertEquals("tallies", 2, after.getTally("kill:goblin"));
		assertEquals("tallies", 1, after.getTally("advice:taken"));
		assertEquals("records", 42, after.getRecord("hit"));
		assertEquals("records", 238, after.getRecord("session"));
		assertEquals("sessions", 36, after.getSessionCount());
		assertEquals("the incident", "that chicken", after.getIncidentPhrase());
		assertEquals("the first meeting", 20_400L, after.getMetOnDay());
		assertEquals("what you were wearing when it met you", 1_234, metWearing);
		assertEquals("where you died", new WorldPoint(3200, 3200, 1),
			after.getDeathLocation());

		// The one that would be silent if it broke.
		assertTrue("a spent introduction has to survive a restart",
			after.hasSaidOnce("first-meeting"));
		assertTrue(after.hasSaidOnce("first-page"));
		assertFalse("and nothing else should come back spent",
			after.hasSaidOnce("first-hour"));

		// Line wear resetting every restart would make retirement (R17) a
		// per-session mechanism, which is to say no mechanism at all.
		assertEquals("how worn a line is has to survive too",
			2, after.lineWear("A line said twice."));
		assertEquals("and unheard lines stay unheard",
			0, after.lineWear("A line never said."));
	}

	@Test
	public void theWearLedgerStaysASensibleSize()
	{
		// The blob this rides in is written every few minutes for as long as
		// the client is open; an unbounded map would grow it forever. The cap
		// drops the least-worn entries - the ones farthest from ever standing
		// a line aside.
		TriggerContext context = fresh();
		context.noteLineSaid("the favourite");
		context.noteLineSaid("the favourite");
		context.noteLineSaid("the favourite");
		for (int i = 0; i < 700; i++)
		{
			context.noteLineSaid("filler line " + i);
		}

		assertTrue("the ledger must stay capped, was " + context.getLineWear().size(),
			context.getLineWear().size() <= 500);
		assertEquals("and the most-worn entries are the ones kept",
			3, context.lineWear("the favourite"));
	}

	@Test
	public void aSecondRoundTripChangesNothing()
	{
		// Save, load, save. The two blobs have to agree, or something is being
		// dropped or duplicated on every restart rather than only on the first.
		TriggerContext before = lived();
		String first = FollowerPlugin.snapshotMemory(before, 1_234, gson);

		TriggerContext middle = fresh();
		int metWearing = FollowerPlugin.restoreMemory(middle, first, gson, 0);
		String second = FollowerPlugin.snapshotMemory(middle, metWearing, gson);

		assertEquals("the follower's memory is not stable across a restart",
			first, second);
	}

	@Test
	public void aFollowerThatHasDoneNothingSavesAndLoadsCleanly()
	{
		String blob = FollowerPlugin.snapshotMemory(fresh(), 0, gson);
		TriggerContext after = fresh();
		assertEquals(0, FollowerPlugin.restoreMemory(after, blob, gson, 0));
		assertEquals(0, after.getSessionCount());
		assertTrue(after.getSpokenOnce().isEmpty());
	}

	@Test
	public void nothingIsLostToAMissingFieldFromAnOlderVersion()
	{
		// Every user upgrading arrives with a blob written by the previous
		// build, which has no spokenOnce in it at all. That must read as "has
		// said nothing yet" rather than throwing and costing them everything
		// else in the same blob.
		String older = "{\"tallies\":{\"kill:rat\":3},\"records\":{\"hit\":9},"
			+ "\"sessions\":12,\"metOnDay\":20400,\"deathPlane\":-1}";

		TriggerContext after = fresh();
		FollowerPlugin.restoreMemory(after, older, gson, 0);

		assertEquals("the rest of an older blob still has to load", 3,
			after.getTally("kill:rat"));
		assertEquals(12, after.getSessionCount());
		assertTrue("a missing spent-set reads as nothing said yet",
			after.getSpokenOnce().isEmpty());
		assertFalse(after.hasSaidOnce("first-meeting"));
	}

	@Test
	public void ruinedMemoryCostsTheMemoryAndNotTheSession()
	{
		// A corrupt value is sad but survivable. Refusing to start over it
		// would not be.
		TriggerContext after = fresh();
		int metWearing = FollowerPlugin.restoreMemory(after, "{not json at all",
			gson, 77);

		assertEquals("a corrupt blob must fall back rather than throw", 77, metWearing);
		assertEquals(0, after.getSessionCount());
	}

	@Test
	public void anEmptyOrAbsentBlobIsNotAnError()
	{
		assertEquals(5, FollowerPlugin.restoreMemory(fresh(), null, gson, 5));
		assertEquals(5, FollowerPlugin.restoreMemory(fresh(), "", gson, 5));
		assertEquals(5, FollowerPlugin.restoreMemory(fresh(), "null", gson, 5));
	}

	@Test
	public void theSpentSetSurvivesTheOrderItWasWrittenIn()
	{
		// It is a Set in memory and a List on disk, which is exactly the shape
		// where an ordering assumption can creep in unnoticed.
		TriggerContext before = fresh();
		for (String id : Arrays.asList("first-return", "first-meeting", "first-hour"))
		{
			before.noteSaidOnce(id);
		}
		String blob = FollowerPlugin.snapshotMemory(before, 0, gson);

		TriggerContext after = fresh();
		FollowerPlugin.restoreMemory(after, blob, gson, 0);
		assertEquals(3, after.getSpokenOnce().size());
		for (String id : Arrays.asList("first-return", "first-meeting", "first-hour"))
		{
			assertTrue(id + " was lost across the restart", after.hasSaidOnce(id));
		}
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.TriggerContext;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The things the follower is supposed to remember between one session and the
 * next.
 *
 * <p>A count that resets on logout is a scoreboard for the current game. The
 * whole value of "your fiftieth" is that the fifty were since you met, so the
 * parts that make that true - the merge on restore, the records that only move
 * up, the first-ever value that seeds silently - are what is checked here.
 */
public class MemoryTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void restoringCountersAddsToWhatIsAlreadyCounted() throws IOException
	{
		// The restore happens a few ticks into a login, and a kill can land
		// first. Overwriting would throw that kill away.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().tally("kill:rat");

		Map<String, Integer> saved = new HashMap<>();
		saved.put("kill:rat", 40);
		h.engine.getContext().restoreCounters(saved, null);

		assertEquals("a restore must add to the session, not replace it",
			41, h.engine.getContext().getTally("kill:rat"));
	}

	@Test
	public void restoringRecordsKeepsTheBetterOfTheTwo() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().noteRecord("hit", 60);

		Map<String, Integer> saved = new HashMap<>();
		saved.put("hit", 42);
		h.engine.getContext().restoreCounters(null, saved);

		assertEquals("a stale saved record must not undo a better live one",
			60, h.engine.getContext().getRecord("hit"));
	}

	@Test
	public void theFirstValueEverSeenIsNotAPersonalBest() throws IOException
	{
		// Otherwise every new install announces a record on its first hit,
		// which makes the feature look broken to every new user at once.
		TriggerContext context = new Harness(folder.newFolder().toPath())
			.engine.getContext();

		assertFalse("the first measurement is the only measurement",
			context.noteRecord("hit", 30));
		assertEquals("it is still stored, though", 30, context.getRecord("hit"));
		assertFalse("and beaten is beaten, not equalled", context.noteRecord("hit", 30));
		assertTrue("beating it is the news", context.noteRecord("hit", 31));
	}

	// ------------------------------------------------------- shipped rules

	@Test
	public void theSessionMilestoneLandsOnTheExactNumber() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		// These carry a delayTicks, so the line lands some ticks after the win.
		h.engine.getContext().setSessionCount(99);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(20);
		assertTrue("ninety-nine is not a hundred", h.firedBy("session-100").isEmpty());

		h.engine.getContext().setSessionCount(100);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(20);
		assertFalse("the hundredth session", h.firedBy("session-100").isEmpty());

		h.clear();
		h.engine.getContext().setSessionCount(101);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(20);
		assertTrue("and never again after", h.firedBy("session-100").isEmpty());
	}

	@Test
	public void theRecordLineNamesBothNumbers() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.dispatch(TriggerEvent.record("hit", 71, 54));

		List<Harness.Spoken> said = h.firedBy("record-hit");
		assertFalse("a new biggest hit is worth saying", said.isEmpty());
		String line = said.get(0).text;
		assertTrue("the new mark has to appear: " + line, line.contains("71"));
		assertFalse("and nothing may print as a literal placeholder: " + line,
			line.contains("{"));
	}

	@Test
	public void dyingOftenReadsDifferentlyFromDyingOnce() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		h.dispatch(TriggerEvent.death());
		h.gameTicks(10);
		assertTrue("the first death is not a pattern", h.firedBy("deaths-many").isEmpty());

		for (int i = 0; i < 12; i++)
		{
			h.engine.getContext().tally("deaths");
		}
		h.gameTicks(200);
		h.clear();
		h.dispatch(TriggerEvent.death());
		h.gameTicks(10);
		assertFalse("a dozen deaths is a pattern", h.firedBy("deaths-many").isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.SpeechRule;
import com.follower.speech.TriggerContext;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower's mood: one number that gives the lines a state to be said from.
 *
 * <p>Nothing in the engine decides what moves it. Rules carry a nudge and the
 * engine applies it when they fire, which means the mood inherits every trigger
 * the rule format already understands - and a new influence is an edit to
 * phrases.json rather than to any of this.
 */
public class MoodTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static String rules(String... bodies)
	{
		return "{\"version\": 1, \"rules\": [" + String.join(",", bodies) + "]}";
	}

	// ---------------------------------------------------------------- the value

	@Test
	public void aSessionStartsEven() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		assertEquals(50, h.engine.getContext().getMood());
		assertEquals("even", h.engine.getContext().getMoodBand());
	}

	@Test
	public void theBandsCoverTheWholeRangeWithNoGaps()
	{
		TriggerContext context = new TriggerContext(new com.follower.sim.FakeGame().client);
		List<String> seen = new ArrayList<>();
		for (int value = 0; value <= 100; value++)
		{
			context.adjustMood(value - context.getMood());
			String band = context.getMoodBand();
			assertTrue("mood " + value + " is in no band at all",
				TriggerContext.moodBands().contains(band));
			if (seen.isEmpty() || !seen.get(seen.size() - 1).equals(band))
			{
				seen.add(band);
			}
		}
		assertEquals("the bands should run low to high in order",
			new ArrayList<>(TriggerContext.moodBands()), seen);
	}

	@Test
	public void moodCannotLeaveItsRange()
	{
		TriggerContext context = new TriggerContext(new com.follower.sim.FakeGame().client);

		context.adjustMood(10000);
		assertEquals("no amount of good news goes past the top", 100, context.getMood());

		context.adjustMood(-10000);
		assertEquals("nor past the bottom", 0, context.getMood());

		assertEquals("and a nudge of nothing changes nothing",
			0, context.adjustMood(0));
	}

	@Test
	public void moodDriftsBackTowardEvenSoNothingIsPermanent() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(45);
		assertEquals(95, h.engine.getContext().getMood());

		h.gameTicks(600);
		int after = h.engine.getContext().getMood();

		assertTrue("a good stretch should fade, not stick: still at " + after,
			after < 95);
		assertTrue("but not overshoot past even: " + after, after >= 50);
	}

	@Test
	public void aFlatMoodClimbsBackUpTheSameWay() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(-45);
		assertEquals(5, h.engine.getContext().getMood());

		h.gameTicks(600);
		int after = h.engine.getContext().getMood();

		assertTrue("a bad run has to be recoverable by carrying on: " + after,
			after > 5);
		assertTrue(after <= 50);
	}

	@Test
	public void anEvenMoodDoesNotDrift() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(2000);
		assertEquals(50, h.engine.getContext().getMood());
	}

	// --------------------------------------------------------------- the nudge

	@Test
	public void aRuleMovesTheMoodWhenItFires() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"good\", \"group\": \"t\", \"cooldownMs\": 0, \"mood\": 15,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());

		assertEquals(65, h.engine.getContext().getMood());
	}

	@Test
	public void aRuleHeldBackByItsCooldownDoesNotMoveTheMood() throws IOException
	{
		// The state and the words have to stay one story: a rule that said
		// nothing must not have quietly changed how the follower feels.
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"good\", \"group\": \"t\", \"cooldownMs\": 600000, \"mood\": 15,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		for (int i = 0; i < 10; i++)
		{
			h.dispatch(TriggerEvent.death());
			h.gameTick();
		}

		assertEquals("ten deaths, one line, one nudge", 65, h.engine.getContext().getMood());
	}

	@Test
	public void aRuleInADisabledGroupDoesNotMoveTheMood() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"good\", \"group\": \"off\", \"cooldownMs\": 0, \"mood\": 15,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}"));
		h.engine.setDisabledGroups(java.util.Collections.singleton("off"));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());

		assertEquals("a silenced rule must not move the mood either",
			50, h.engine.getContext().getMood());
	}

	// ---------------------------------------------------------------- the gate

	@Test
	public void aRuleCanRequireABand() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"gloomy\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"mood\", \"is\": \"low\"}, \"say\": [\"a\"]}"));

		h.gameTicks(2);
		assertTrue("even is not low", h.firedBy("gloomy").isEmpty());

		h.engine.getContext().adjustMood(-40);
		h.gameTicks(2);
		assertFalse("ten out of a hundred is low", h.firedBy("gloomy").isEmpty());
	}

	@Test
	public void aRuleCanRequireARange() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"narrow\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"mood\", \"minimum\": 70, \"maximum\": 75},"
				+ " \"say\": [\"a\"]}"));

		h.engine.getContext().adjustMood(20);
		h.gameTicks(2);
		assertFalse("seventy is inside seventy to seventy-five",
			h.firedBy("narrow").isEmpty());

		h.clear();
		h.engine.getContext().adjustMood(20);
		h.gameTicks(2);
		assertTrue("ninety is outside it", h.firedBy("narrow").isEmpty());
	}

	// ------------------------------------------------------------ the rule set

	@Test
	public void theShippedNudgesAreSignedTheWayTheEventReads() throws IOException
	{
		// A boss kill must not lower the mood and a death must not raise it.
		// Getting a sign backwards would be invisible except as a follower that
		// cheers up when you die.
		Harness h = new Harness(folder.newFolder().toPath());
		java.util.Map<String, Boolean> shouldBePositive = new java.util.HashMap<>();
		shouldBePositive.put("kill-boss-celebrate", true);
		shouldBePositive.put("loot-big", true);
		shouldBePositive.put("loot-nice", true);
		shouldBePositive.put("level-up", true);
		shouldBePositive.put("kill-cheer", true);
		shouldBePositive.put("death-moment", false);
		shouldBePositive.put("death", false);

		for (java.util.Map.Entry<String, Boolean> entry : shouldBePositive.entrySet())
		{
			SpeechRule rule = h.rule(entry.getKey());
			assertTrue(entry.getKey() + " carries no nudge at all", rule.mood != null);
			assertEquals(entry.getKey() + " has the wrong sign",
				entry.getValue(), rule.mood > 0);
		}
	}

	@Test
	public void everyMoodBandNamedByARuleExists() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		List<String> unknown = new ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			collectBands(rule, rule.when, unknown);
		}
		assertTrue("rules naming a mood band that does not exist, so they can"
			+ " never fire: " + unknown, unknown.isEmpty());
	}

	private void collectBands(SpeechRule rule, com.follower.speech.Condition condition,
		List<String> unknown)
	{
		if (condition == null)
		{
			return;
		}
		if ("mood".equalsIgnoreCase(condition.type) && condition.is != null
			&& !TriggerContext.moodBands().contains(condition.is))
		{
			unknown.add(rule.id + ": \"" + condition.is + "\"");
		}
		if (condition.conditions != null)
		{
			for (com.follower.speech.Condition child : condition.conditions)
			{
				collectBands(rule, child, unknown);
			}
		}
	}

	// ------------------------------------------------------------- a session

	@Test
	public void aGoodRunLiftsItAndABadOneDoesNot() throws IOException
	{
		// End to end through the shipped rules: the mood should follow the
		// shape of the session without anything else being told about it.
		Harness good = new Harness(folder.newFolder().toPath());
		good.gameTicks(1);
		for (int i = 0; i < 6; i++)
		{
			good.dispatch(TriggerEvent.kill(2, "Zulrah", 725));
			good.gameTicks(40);
		}
		assertTrue("six boss kills should have cheered it up, mood is "
			+ good.engine.getContext().getMood(),
			good.engine.getContext().getMood() > 55);

		Harness bad = new Harness(folder.newFolder().toPath());
		bad.gameTicks(1);
		for (int i = 0; i < 4; i++)
		{
			bad.dispatch(TriggerEvent.death());
			bad.gameTicks(120);
		}
		assertTrue("four deaths should have flattened it, mood is "
			+ bad.engine.getContext().getMood(),
			bad.engine.getContext().getMood() < 45);
	}

	@Test
	public void everyMoodBandHasAPostureToShowItIn() throws IOException
	{
		// The mood is meant to be READ off the follower, and an idle posture is
		// how that happens without a word. A band with no fidget of its own is
		// a mood that can be reached and never seen.
		Harness h = new Harness(folder.newFolder().toPath());
		java.util.Set<String> covered = new java.util.HashSet<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.animation == null || rule.when == null)
			{
				continue;
			}
			for (String band : TriggerContext.moodBands())
			{
				if (namesBand(rule.when, band))
				{
					covered.add(band);
				}
			}
		}
		assertEquals("moods with no idle posture: "
				+ new java.util.TreeSet<>(subtract(TriggerContext.moodBands(), covered)),
			TriggerContext.moodBands().size(), covered.size());
	}

	private static java.util.Set<String> subtract(java.util.Set<String> all,
		java.util.Set<String> covered)
	{
		java.util.Set<String> missing = new java.util.HashSet<>(all);
		missing.removeAll(covered);
		return missing;
	}

	private boolean namesBand(com.follower.speech.Condition condition, String band)
	{
		if (condition == null)
		{
			return false;
		}
		if ("mood".equalsIgnoreCase(condition.type) && band.equals(condition.is))
		{
			return true;
		}
		if (condition.conditions != null)
		{
			for (com.follower.speech.Condition child : condition.conditions)
			{
				if (namesBand(child, band))
				{
					return true;
				}
			}
		}
		return false;
	}

	@Test
	public void theLowLinesOnlyTurnUpWhenThingsAreActuallyBad() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(200);
		assertTrue("the gloomy lines must not appear in an ordinary session",
			h.firedBy("mood-low-idle").isEmpty());

		h.engine.getContext().adjustMood(-40);
		h.gameTicks(200);
		assertFalse("and they should appear once it is",
			h.firedBy("mood-low-idle").isEmpty());
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * What survives of a typed follower name.
 *
 * <p>The chatbox validator refuses bad characters as they are typed, but
 * pasted text does not go through it, and everything downstream - the menu
 * target, the dialog header, the chat echo - trusts the stored name to hold
 * no tags and no surprises. This is the one gate.
 */
public class NamePromptTest
{
	@Test
	public void ordinaryNamesPassThrough()
	{
		assertEquals("Pip", FollowerPlugin.cleanFollowerName("Pip"));
		assertEquals("Old Bob", FollowerPlugin.cleanFollowerName("Old Bob"));
		assertEquals("D'arcy-Jones", FollowerPlugin.cleanFollowerName("D'arcy-Jones"));
	}

	@Test
	public void whitespaceIsTidiedNotTrusted()
	{
		assertEquals("Pip", FollowerPlugin.cleanFollowerName("  Pip  "));
		assertEquals("Old Bob", FollowerPlugin.cleanFollowerName("Old    Bob"));
	}

	@Test
	public void tagsAndMarkupCannotSurvive()
	{
		// The menu target wraps the name in colour tags; a name carrying its
		// own would break out of them. Whatever comes in, no angle bracket,
		// equals sign or slash comes out.
		String cleaned = FollowerPlugin.cleanFollowerName("Bob<col=ff0000>");
		assertEquals("Bobcolff0000", cleaned);
		assertEquals("img1Pip", FollowerPlugin.cleanFollowerName("<img=1/>Pip"));
	}

	@Test
	public void lengthIsCappedAtTwenty()
	{
		assertEquals(20,
			FollowerPlugin.cleanFollowerName("Abcdefghijklmnopqrstuvwxyz").length());
	}

	@Test
	public void nothingUsableMeansEmptyWhichMeansSkip()
	{
		assertEquals("", FollowerPlugin.cleanFollowerName(null));
		assertEquals("", FollowerPlugin.cleanFollowerName("   "));
		assertEquals("", FollowerPlugin.cleanFollowerName("<<<>>>"));
	}
}

package com.follower;

import com.follower.sim.Harness;
import net.runelite.api.CollisionDataFlag;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A callout must be at something the player can actually see.
 *
 * <p>"That thing is very large and very close" invites the player to look. If
 * what is large and close is a kalphite behind a wall, the line is worse than
 * silence: one bad callout teaches the player that the follower's callouts
 * are not worth checking, which spends the credibility every good one earned.
 * Distance was the whole test before this - a wall three tiles away did not
 * exist as far as npcNearby was concerned.
 *
 * <p>The sight check is the game's own: {@code WorldArea.hasLineOfSightTo}
 * reads the scene's sight-blocking collision flags, so what the follower can
 * "see" and what the game would let an archer shoot agree by construction.
 */
public class NpcVisibilityTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** One rule that requires sight, one that does not, same NPC. */
	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"callout\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"npcNearby\", \"minimum\": 250, \"within\": 8,"
		+ " \"visible\": true},"
		+ " \"say\": [\"look at that\"]},"
		+ "{\"id\": \"sense\", \"group\": \"t\", \"cooldownMs\": 0, \"priority\": 10,"
		+ " \"when\": {\"type\": \"npcNearby\", \"minimum\": 250, \"within\": 8},"
		+ " \"say\": [\"something is about\"]}]}";

	/**
	 * The fake's collision map is scene-sized with a base of zero, so world
	 * coordinates must stay inside the 104-tile scene. Out-of-scene
	 * coordinates do not merely miss - the LOS lookup throws, the engine's
	 * guard disables the throwing rule, and the test fails by silence, which
	 * took some finding.
	 */
	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.game.withCollision();
		h.game.at(50, 50, 0);
		return h;
	}

	@Test
	public void aVisibleGiantGetsTheCallout() throws IOException
	{
		Harness h = harness();
		h.game.moveNpc(h.game.spawnNpc(494, "Kalphite Queen", 333), 54, 50, 0);
		h.gameTicks(3);

		assertEquals("open ground: the callout fires", 1, h.firedBy("callout").size());
	}

	@Test
	public void aGiantBehindAWallIsNotACallout() throws IOException
	{
		Harness h = harness();
		h.game.moveNpc(h.game.spawnNpc(494, "Kalphite Queen", 333), 54, 50, 0);
		// A sight-blocking wall between the player and it.
		h.game.wallAt(52, 50, CollisionDataFlag.BLOCK_LINE_OF_SIGHT_FULL);
		h.gameTicks(3);

		assertTrue("a callout at a wall teaches the player to stop checking",
			h.firedBy("callout").isEmpty());
		assertEquals("but a rule that only senses, without pointing, still may",
			1, h.firedBy("sense").size());
	}

	@Test
	public void noCollisionDataReadsAsVisible() throws IOException
	{
		// During loading there is nothing to consult, and refusing to mention
		// a boss because the map has not finished arriving is the wrong kind
		// of caution. The harness without withCollision() is exactly the
		// no-data world.
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.game.at(50, 50, 0);
		h.game.moveNpc(h.game.spawnNpc(494, "Kalphite Queen", 333), 54, 50, 0);
		h.gameTicks(3);

		assertEquals("benefit of the doubt with no map", 1, h.firedBy("callout").size());
	}

	@Test
	public void theShippedLookableRulesAllRequireSight() throws IOException
	{
		// The audit itself, pinned: every rule whose lines invite the player
		// to look at an NPC carries the visible requirement. If a new
		// pointing rule arrives without it, this list is where the argument
		// happens.
		Harness h = new Harness(folder.newFolder().toPath());
		for (String id : new String[]{"something-big-nearby", "cats-and-pets", "boss-while-low"})
		{
			com.follower.speech.SpeechRule rule = h.rule(id);
			assertTrue(id + " points at an NPC and must require sight of it",
				requiresSight(rule.when));
		}
	}

	private static boolean requiresSight(com.follower.speech.Condition condition)
	{
		if (condition == null)
		{
			return false;
		}
		if ("npcNearby".equalsIgnoreCase(condition.type)
			&& Boolean.TRUE.equals(condition.visible))
		{
			return true;
		}
		if (condition.conditions != null)
		{
			for (com.follower.speech.Condition child : condition.conditions)
			{
				if (requiresSight(child))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.SpeechDirector;
import com.follower.speech.SpeechRule;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * The one promise the director makes: an occasion always gets through.
 *
 * <p>That promise was broken within hours of being written, and in a way no
 * amount of reading would have caught. The relax check exempted occasions; the
 * settling check, added at the same time and four lines below it, did not - so
 * enter-wilderness, which is group "area" and therefore counts as scenery,
 * could be swallowed for a player who was new. A follower is only settling in
 * because the player is new, so the two conditions peak together.
 *
 * <p>The fix was to state the exemption once at the top of the method. The
 * guard against it happening again cannot be another reading of that method,
 * because the failure was one damper forgetting what the one above it knew.
 * This asserts the PROPERTY over every shipped occasion and every state the
 * director can be in, so a third damper added later has to keep the promise
 * without anyone remembering to ask it to.
 */
public class OccasionGuaranteeTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;
	private static final long NOW = 1_700_000_000_000L;

	/** Every state the director can be in, with a name for the failure message. */
	private static List<Object[]> everyDirectorState()
	{
		List<Object[]> states = new ArrayList<>();

		SpeechRule filler = new SpeechRule();
		filler.id = "filler";
		filler.group = "area";           // counts as lore, so it arms both dampers

		for (int sessions : new int[]{1, 2, 3, 40})
		{
			for (boolean resting : new boolean[]{false, true})
			{
				SpeechDirector director = new SpeechDirector();
				director.setBaseGapMs(GAP);
				director.setSessionCount(sessions);
				director.noteSpoke(filler, NOW);     // arms the settling damper
				if (resting)
				{
					for (int i = 0; i < 4; i++)
					{
						director.noteSpoke(filler, NOW);
					}
				}
				states.add(new Object[]{
					"session " + sessions + (resting ? ", resting" : ", listening"),
					director});
			}
		}
		return states;
	}

	@Test
	public void noOccasionCanBeHeldByAnyDamperInAnyState() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());

		List<String> broken = new ArrayList<>();
		int checked = 0;
		for (SpeechRule rule : h.loader.getRules())
		{
			if (!rule.isOccasion())
			{
				continue;
			}
			checked++;
			for (Object[] state : everyDirectorState())
			{
				String held = ((SpeechDirector) state[1]).blocks(rule, NOW);
				if (held != null)
				{
					broken.add(rule.id + " held by \"" + held + "\" (" + state[0] + ")");
				}
			}
		}

		assertTrue("the shipped set should have plenty of occasions", checked > 50);
		assertTrue("an occasion is a line the follower must never be too busy to"
			+ " say, and these were held:\n  " + String.join("\n  ", broken),
			broken.isEmpty());
	}

	@Test
	public void theGuaranteeHoldsForAGroupTheDamperThins() throws IOException
	{
		// The specific shape of the original bug, kept as its own case because
		// it is the only shipped occasion living in a scenery group and would
		// be easy to move without noticing what it was protecting.
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule wilderness = h.rule("enter-wilderness");

		assertTrue("enter-wilderness has to stay an occasion; it is the whole"
			+ " reason the flag exists", wilderness.isOccasion());
		assertTrue("and it is still in a group the settling damper thins, which"
			+ " is exactly why the guarantee has to be unconditional",
			SpeechDirector.isLore(wilderness));

		for (Object[] state : everyDirectorState())
		{
			assertTrue("enter-wilderness held (" + state[0] + ")",
				((SpeechDirector) state[1]).blocks(wilderness, NOW) == null);
		}
	}

	@Test
	public void everyHealthWarningIsAnOccasion() throws IOException
	{
		// The content half of the same promise. A warning the player never
		// hears is worse than one they hear twice, so anything that tells them
		// to eat, cure, pray or run has to be exempt.
		Harness h = new Harness(folder.newFolder().toPath());

		// Deliberately not the whole group: "Ouch. {damage}." and "Out of
		// breath already?" are remarks about what happened, not instructions
		// about what to do, and holding those back costs nobody anything.
		List<String> mustCarry = java.util.Arrays.asList(
			"critical-hp", "low-hp", "low-prayer", "status-poisoned",
			"status-venomed", "status-skulled", "boss-while-low",
			"enter-wilderness");

		List<String> missing = new ArrayList<>();
		for (String id : mustCarry)
		{
			if (!h.rule(id).isOccasion())
			{
				missing.add(id);
			}
		}
		assertTrue("these tell the player to do something about a danger and"
			+ " must never be held: " + missing, missing.isEmpty());
	}

	@Test
	public void everyBossIdentificationIsAnOccasion() throws IOException
	{
		// Walking into a boss is the clearest case in the file: the advice is
		// only any use before the fight starts, and a player who missed it
		// because the follower was resting has been failed by the exact feature
		// meant to make them listen.
		Harness h = new Harness(folder.newFolder().toPath());

		List<String> missing = new ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if ("boss".equals(rule.group) && rule.priority >= 90 && !rule.isOccasion())
			{
				missing.add(rule.id);
			}
		}
		assertTrue("boss advice that could be held back: " + missing, missing.isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.RuleLoader;
import com.follower.speech.TriggerEvent;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Lines the follower says once, ever.
 *
 * <p>A line that only has to hold up on a single hearing can be specific in a
 * way no repeating line can afford to be: it can name the moment, admit
 * something, or land a joke that would be unbearable the fourth time. That
 * makes it the highest value per word in the file - and the easiest to ruin, by
 * saying it twice.
 */
public class OnceOnlyTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES =
		"{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"hello-first\", \"group\": \"t\", \"cooldownMs\": 0, \"once\": true,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"we have not met\"]},"
			+ "{\"id\": \"hello-again\", \"group\": \"t\", \"cooldownMs\": 0, \"priority\": 10,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"back again\"]}]}";

	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(1);
		return h;
	}

	/** The trigger, twice, with a tick between so the edge can fall. */
	private static void examineTwice(Harness h)
	{
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
	}

	@Test
	public void aFirstIsOnlyEverAFirst() throws IOException
	{
		Harness h = harness();
		examineTwice(h);

		assertEquals("said once", 1, h.firedBy("hello-first").size());
		assertEquals("and the lower-priority everyday line takes over after",
			1, h.firedBy("hello-again").size());
	}

	@Test
	public void whatWasSaidIsRememberedByTheFollowerNotTheRule() throws IOException
	{
		// The rule file reloads whenever it changes on disk, throwing every rule
		// object away. A flag on the object would un-say the introduction every
		// time a phrase was edited, which is the single most likely moment for
		// it to happen.
		Harness h = harness();
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals(1, h.firedBy("hello-first").size());

		Path file = h.getScratch().resolve(RuleLoader.FILE_NAME);
		Files.write(file, RULES.replace("we have not met", "we have not met, you and I")
			.getBytes(StandardCharsets.UTF_8));
		// The loader compares the modified time, which has a second's resolution
		// on some filesystems.
		Files.setLastModifiedTime(file,
			java.nio.file.attribute.FileTime.fromMillis(System.currentTimeMillis() + 5_000L));
		assertTrue("the edited file should have been picked up", h.loader.reloadIfChanged());

		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("editing the file must not un-say it",
			1, h.firedBy("hello-first").size());
	}

	@Test
	public void aLineNobodyHeardIsNotSpent() throws IOException
	{
		// The worst possible place to be strict. Muted, the follower said
		// nothing; burning the one chance it had would lose the line for good
		// on behalf of a player who never got it.
		Harness h = harness();
		h.engine.setMuted(true);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue(h.firedBy("hello-first").isEmpty());
		assertFalse(h.engine.getContext().hasSaidOnce("hello-first"));

		h.engine.setMuted(false);
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("still owed, and still paid", 1, h.firedBy("hello-first").size());
	}

	@Test
	public void sayingItIsWorthWritingDown() throws IOException
	{
		// Nothing is saved unless something says it needs saving, so a first
		// that did not mark the blob dirty would be forgotten by the next
		// restart - and said a second time.
		Harness h = harness();
		h.engine.getContext().clearCountersDirty();

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("a spent first has to reach the disk",
			h.engine.getContext().isCountersDirty());
		assertTrue(h.engine.getContext().getSpokenOnce().contains("hello-first"));
	}

	@Test
	public void whatWasSaidLastTimeStaysSaid() throws IOException
	{
		Harness h = harness();
		h.engine.getContext().restoreSpokenOnce(
			java.util.Collections.singletonList("hello-first"));

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("a restored session must not repeat the introduction",
			h.firedBy("hello-first").isEmpty());
		assertEquals("and the everyday line is there to take its place",
			1, h.firedBy("hello-again").size());
	}
}

package com.follower;

import com.follower.share.PackFile;
import com.follower.sound.VoiceLibrary;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A pack carries one player's own work to another player, and nothing else.
 *
 * <p>The whole point is the diff. Exporting the rule file wholesale would ship
 * two thousand shipped lines along with it, overwrite whatever the recipient
 * had written, and freeze them at the sender's version of everything the plugin
 * updates. These tests hold that line, and hold the merge to never replacing.
 */
public class PackRoundTripTest
{
	private static final Gson GSON = new Gson();

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** Single quotes for readability; JSON wants double. */
	private static JsonObject rules(String json)
	{
		return GSON.fromJson(json.replace('\'', '"'), JsonObject.class);
	}

	/** What the plugin ships: the baseline both players started from. */
	private static JsonObject shipped()
	{
		return rules("{'rules':["
			+ "{'id':'bank','say':['Deep pockets.','All that gold.']},"
			+ "{'id':'combat','say':['Behind you.']}]}");
	}

	private static List<String> say(JsonObject file, String id)
	{
		for (JsonElement element : file.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			if (id.equals(rule.get("id").getAsString()))
			{
				List<String> out = new ArrayList<>();
				for (JsonElement line : rule.getAsJsonArray("say"))
				{
					out.add(line.getAsString());
				}
				return out;
			}
		}
		return null;
	}

	private VoiceLibrary voicesIn(String name) throws Exception
	{
		VoiceLibrary voices = new VoiceLibrary(GSON, new net.runelite.client.audio.AudioPlayer());
		voices.load(folder.newFolder(name).toPath());
		return voices;
	}

	private Path zip(String name) throws Exception
	{
		return folder.getRoot().toPath().resolve(name);
	}

	@Test
	public void aPackCarriesOnlyWhatThePlayerWroteThemselves() throws Exception
	{
		JsonObject sender = rules("{'rules':["
			+ "{'id':'bank','say':['Deep pockets.','All that gold.','Count it twice.']},"
			+ "{'id':'combat','say':['Behind you.']},"
			+ "{'id':'my-own','when':{'type':'tick'},'say':['Just us two.']}]}");

		Path pack = zip("pack.zip");
		PackFile.Summary made = PackFile.export(
			pack, sender, shipped(), voicesIn("mine"), GSON, "Sender");

		// One added line, and one whole rule of their own.
		assertEquals(2, made.rules);
		assertEquals(2, made.lines);

		JsonObject carried = new JsonObject();
		carried.add("rules", PackFile.read(pack, GSON).rules);
		assertEquals("only the added line travels, not the rule around it",
			Arrays.asList("Count it twice."), say(carried, "bank"));
		assertEquals("the player's own rule travels whole",
			Arrays.asList("Just us two."), say(carried, "my-own"));
		assertNull("an untouched rule must not travel at all", say(carried, "combat"));
	}

	@Test
	public void importingAddsToWhatTheRecipientWroteRatherThanReplacingIt() throws Exception
	{
		JsonObject sender = rules("{'rules':["
			+ "{'id':'bank','say':['Deep pockets.','All that gold.','Count it twice.']},"
			+ "{'id':'my-own','when':{'type':'tick'},'say':['Just us two.']}]}");
		Path pack = zip("pack.zip");
		PackFile.export(pack, sender, shipped(), voicesIn("from"), GSON, "Sender");

		// The recipient has written into the same rule.
		JsonObject recipient = rules("{'rules':["
			+ "{'id':'bank','say':['Deep pockets.','All that gold.','Mine, all mine.']},"
			+ "{'id':'combat','say':['Behind you.']}]}");

		VoiceLibrary theirs = voicesIn("to");
		PackFile.Summary took = PackFile.apply(
			PackFile.read(pack, GSON), recipient, theirs.getSoundsFolder(), theirs);

		List<String> bank = say(recipient, "bank");
		assertTrue("their own line survives the import", bank.contains("Mine, all mine."));
		assertTrue("the incoming line arrives", bank.contains("Count it twice."));
		assertEquals(4, bank.size());
		assertEquals(Arrays.asList("Just us two."), say(recipient, "my-own"));
		assertEquals(2, took.rules);
		assertEquals(2, took.lines);
	}

	@Test
	public void importingTheSamePackTwiceChangesNothingTheSecondTime() throws Exception
	{
		JsonObject sender = rules("{'rules':["
			+ "{'id':'bank','say':['Deep pockets.','All that gold.','Count it twice.']}]}");
		Path pack = zip("pack.zip");
		PackFile.export(pack, sender, shipped(), voicesIn("from"), GSON, "Sender");

		JsonObject recipient = shipped();
		VoiceLibrary theirs = voicesIn("to");
		PackFile.apply(PackFile.read(pack, GSON), recipient, theirs.getSoundsFolder(), theirs);
		PackFile.Summary again = PackFile.apply(
			PackFile.read(pack, GSON), recipient, theirs.getSoundsFolder(), theirs);

		assertEquals("no line arrives twice", 3, say(recipient, "bank").size());
		assertEquals(0, again.lines);
	}

	@Test
	public void aSoundTravelsWithTheLineItBelongsTo() throws Exception
	{
		VoiceLibrary sending = voicesIn("from");
		Files.write(sending.getSoundsFolder().resolve("count.wav"), new byte[]{1, 2, 3, 4});
		sending.attach("Count it twice.", "count.wav");

		JsonObject sender = rules("{'rules':["
			+ "{'id':'bank','say':['Deep pockets.','All that gold.','Count it twice.']}]}");
		Path pack = zip("pack.zip");
		assertEquals(1, PackFile.export(pack, sender, shipped(), sending, GSON, "Sender").sounds);

		JsonObject recipient = shipped();
		VoiceLibrary theirs = voicesIn("to");
		PackFile.apply(PackFile.read(pack, GSON), recipient, theirs.getSoundsFolder(), theirs);

		assertTrue(Files.exists(theirs.getSoundsFolder().resolve("count.wav")));
		assertEquals("the line arrives already voiced",
			"count.wav", theirs.attachmentFor("Count it twice."));

		// A second import must not breed count-2.wav, count-3.wav...
		PackFile.apply(PackFile.read(pack, GSON), recipient, theirs.getSoundsFolder(), theirs);
		assertEquals(1, theirs.availableFiles().size());
	}

	@Test
	public void anIncomingSoundNeverOverwritesOneTheRecipientAlreadyHas() throws Exception
	{
		VoiceLibrary sending = voicesIn("from");
		Files.write(sending.getSoundsFolder().resolve("voice.wav"), new byte[]{9, 9, 9});
		sending.attach("Count it twice.", "voice.wav");
		JsonObject sender = rules("{'rules':["
			+ "{'id':'bank','say':['Deep pockets.','All that gold.','Count it twice.']}]}");
		Path pack = zip("pack.zip");
		PackFile.export(pack, sender, shipped(), sending, GSON, "Sender");

		// A different recording, under the same name.
		VoiceLibrary theirs = voicesIn("to");
		Path ours = theirs.getSoundsFolder().resolve("voice.wav");
		Files.write(ours, new byte[]{1, 1, 1, 1, 1});

		JsonObject recipient = shipped();
		PackFile.apply(PackFile.read(pack, GSON), recipient, theirs.getSoundsFolder(), theirs);

		assertEquals("their own recording is untouched", 5, Files.readAllBytes(ours).length);
		assertEquals("the incoming one lands beside it, and the line points at it",
			"voice-2.wav", theirs.attachmentFor("Count it twice."));
	}

	@Test
	public void linesForARuleTheRecipientDoesNotHaveAreReportedNotSilentlyAdded()
		throws Exception
	{
		JsonObject sender = rules("{'rules':["
			+ "{'id':'combat','say':['Behind you.','Mind the spec.']}]}");
		Path pack = zip("pack.zip");
		PackFile.export(pack, sender, shipped(), voicesIn("from"), GSON, "Sender");

		// An older phrases.json, from before 'combat' shipped.
		JsonObject recipient = rules("{'rules':[{'id':'bank','say':['Deep pockets.']}]}");
		VoiceLibrary theirs = voicesIn("to");
		PackFile.Summary took = PackFile.apply(
			PackFile.read(pack, GSON), recipient, theirs.getSoundsFolder(), theirs);

		assertEquals("a rule with nothing to fire it is not worth adding",
			1, recipient.getAsJsonArray("rules").size());
		assertEquals(0, took.lines);
		assertTrue(took.problems.toString(), took.problems.get(0).contains("combat"));
	}

	@Test
	public void aLineTheGameCannotDrawIsRefusedWhoeverWroteIt() throws Exception
	{
		JsonObject sender = rules("{'rules':[{'id':'my-own','when':{'type':'tick'},'say':["
			+ "'Fine.','Dashes — like this.','',"
			+ "'A line so long that nobody could read it in the short moment that it is"
			+ " actually up there on the screen.']}]}");
		Path pack = zip("pack.zip");
		PackFile.export(pack, sender, shipped(), voicesIn("from"), GSON, "Sender");

		PackFile.Loaded loaded = PackFile.read(pack, GSON);
		assertEquals("only the one good line survives", 1, loaded.summary.lines);
		assertEquals(loaded.summary.problems.toString(), 3, loaded.summary.problems.size());
	}

	@Test
	public void anEntryNamedToEscapeTheFolderIsIgnored() throws Exception
	{
		Path pack = zip("hostile.zip");
		try (ZipOutputStream out = new ZipOutputStream(Files.newOutputStream(pack)))
		{
			out.putNextEntry(new ZipEntry("../../evil.wav"));
			out.write(new byte[]{1});
			out.closeEntry();
			out.putNextEntry(new ZipEntry("sounds/../../evil.wav"));
			out.write(new byte[]{1});
			out.closeEntry();
		}
		PackFile.Loaded loaded = PackFile.read(pack, GSON);
		assertTrue("nothing outside the pack's own names is read", loaded.audio.isEmpty());
	}
}

package com.follower;

import com.follower.appearance.Outfit;
import com.follower.appearance.OutfitParser;
import com.follower.appearance.OutfitProfileStore;
import com.follower.speech.RuleLoader;
import com.follower.speech.SpeechRule;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * What survives the editor writing the rules file back out.
 *
 * <p>The phrase editors show one group at a time but rewrite the WHOLE file:
 * they re-read it, mutate the rules they own, and serialise everything back.
 * That means every rule in every other group, and every field the editor has
 * never heard of, passes through Gson twice on a save it had nothing to do
 * with. Anything lost there is silent data loss in the file that holds the
 * follower's entire personality.
 */
public class PhraseFileFidelityTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The same Gson the editor builds for writing. */
	private static Gson editorGson()
	{
		return new Gson().newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
	}

	private static JsonObject bundledRules() throws IOException
	{
		try (InputStream in = PhraseFileFidelityTest.class
			.getResourceAsStream("/com/follower/default-phrases.json"))
		{
			assertNotNull(in);
			return new JsonParser()
				.parse(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
		}
	}

	@Test
	public void theWholeRuleFileSurvivesTheEditorsSerialiser() throws IOException
	{
		JsonObject original = bundledRules();
		JsonObject rewritten = new JsonParser()
			.parse(editorGson().toJson(original)).getAsJsonObject();

		assertEquals("a save would have changed rules it never touched",
			original, rewritten);
	}

	@Test
	public void aRewriteSurvivesBeingLoadedBackAsRules() throws IOException
	{
		// Semantic check on top of the structural one: the rules the plugin
		// ends up running after a save must be the rules it ran before.
		Path before = folder.newFolder().toPath();
		RuleLoader first = new RuleLoader(new Gson());
		first.initialise(before);

		Path after = folder.newFolder().toPath();
		Files.write(after.resolve(RuleLoader.FILE_NAME),
			editorGson().toJson(bundledRules()).getBytes(StandardCharsets.UTF_8));
		RuleLoader second = new RuleLoader(new Gson());
		second.initialise(after);

		assertTrue("the rewritten file failed to load: " + second.getErrors(),
			second.getErrors().isEmpty());
		assertEquals(first.getRules().size(), second.getRules().size());

		for (int i = 0; i < first.getRules().size(); i++)
		{
			SpeechRule a = first.getRules().get(i);
			SpeechRule b = second.getRules().get(i);
			assertEquals(a.id, b.id);
			assertEquals("group changed on " + a.id, a.group, b.group);
			assertEquals("priority changed on " + a.id, a.priority, b.priority);
			assertEquals("cooldown changed on " + a.id, a.cooldownMs, b.cooldownMs);
			assertEquals("say lines changed on " + a.id, a.say, b.say);
			assertEquals("animation changed on " + a.id, a.animation, b.animation);
			assertEquals("chain changed on " + a.id, a.animations, b.animations);
			assertEquals("delay changed on " + a.id, a.delayTicks, b.delayTicks);
			assertEquals("delay range changed on " + a.id, a.delayTicksMax, b.delayTicksMax);
			assertEquals("holdStill changed on " + a.id, a.holdStill, b.holdStill);
			assertEquals("mirroring changed on " + a.id, a.mirrorAnimation, b.mirrorAnimation);
			assertEquals("vanish changed on " + a.id, a.vanishAfter, b.vanishAfter);
			assertEquals("sync changed on " + a.id, a.syncToPlayer, b.syncToPlayer);
		}
	}

	@Test
	public void fieldsTheEditorHasNeverHeardOfAreCarriedThrough() throws IOException
	{
		JsonObject file = new JsonParser().parse(
			"{\"version\": 1, \"rules\": [{\"id\": \"exotic\", \"group\": \"boss\","
				+ " \"when\": {\"type\": \"always\"}, \"say\": [\"a\"],"
				+ " \"somethingFromTheFuture\": {\"nested\": [1, 2, 3]},"
				+ " \"holdStill\": true, \"delayTicksMax\": 9}]}").getAsJsonObject();

		JsonObject rewritten = new JsonParser()
			.parse(editorGson().toJson(file)).getAsJsonObject();
		JsonObject rule = rewritten.getAsJsonArray("rules").get(0).getAsJsonObject();

		assertTrue("an unknown field was dropped", rule.has("somethingFromTheFuture"));
		assertEquals(file, rewritten);
	}

	@Test
	public void editingOneGroupCannotDisturbAnother() throws IOException
	{
		// The editor's contract in miniature: re-read, change only the rules it
		// owns, keep the rest verbatim. Modelled here because the real save
		// needs a window, and this is the part that can lose a user's data.
		JsonObject file = bundledRules();
		JsonArray rules = file.getAsJsonArray("rules");

		List<JsonElement> untouched = new ArrayList<>();
		JsonArray kept = new JsonArray();
		int edited = 0;
		for (JsonElement element : rules)
		{
			JsonObject rule = element.getAsJsonObject();
			if ("gear".equals(rule.get("group").getAsString()))
			{
				JsonArray say = new JsonArray();
				say.add("edited line");
				rule.add("say", say);
				edited++;
			}
			else
			{
				untouched.add(new JsonParser().parse(rule.toString()));
			}
			kept.add(rule);
		}
		file.add("rules", kept);

		assertTrue("the fixture needs some gear rules to edit", edited > 0);

		JsonObject rewritten = new JsonParser()
			.parse(editorGson().toJson(file)).getAsJsonObject();

		int index = 0;
		for (JsonElement element : rewritten.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			if (!"gear".equals(rule.get("group").getAsString()))
			{
				assertEquals("a rule outside the edited group changed",
					untouched.get(index), rule);
				index++;
			}
		}
		assertEquals(untouched.size(), index);
		assertEquals("no rule may go missing on a save",
			rules.size(), rewritten.getAsJsonArray("rules").size());
	}

	@Test
	public void unicodeAndEscapesSurviveASave()
	{
		// disableHtmlEscaping is on, so quotes and angle brackets must come back
		// as themselves rather than as escapes that then render literally.
		String[] awkward = {
			"He said \"hello\"", "a < b > c", "back\\slash", "tab\there",
			"new\nline", "apostrophe's", "100% & more", "emoji free ok",
		};
		for (String line : awkward)
		{
			JsonObject file = new JsonObject();
			JsonArray say = new JsonArray();
			say.add(line);
			JsonObject rule = new JsonObject();
			rule.addProperty("id", "x");
			rule.add("say", say);
			JsonArray rules = new JsonArray();
			rules.add(rule);
			file.add("rules", rules);

			JsonObject back = new JsonParser()
				.parse(editorGson().toJson(file)).getAsJsonObject();
			assertEquals("lost on save: " + line, line, back.getAsJsonArray("rules")
				.get(0).getAsJsonObject().getAsJsonArray("say").get(0).getAsString());
		}
	}

	// ------------------------------------------------------- outfit profiles

	@Test
	public void outfitProfilesSurviveASaveAndReload() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		OutfitProfileStore first = new OutfitProfileStore(new Gson());
		first.load(dir);

		Outfit outfit = new Outfit();
		outfit.setItem(net.runelite.api.kit.KitType.WEAPON, 4151);
		outfit.setKit(net.runelite.api.kit.KitType.HAIR, 3);
		outfit.setGender(1);
		outfit.setColors(new int[]{1, 2, 3, 4, 5});
		first.put("My costume", outfit.toString());

		OutfitProfileStore second = new OutfitProfileStore(new Gson());
		second.load(dir);

		String stored = second.get("My costume");
		assertNotNull("the profile did not survive the round trip", stored);
		assertEquals("the outfit changed on the way through",
			outfit, OutfitParser.parse(stored));
	}

	@Test
	public void theSeededStyleProfilesAreAlwaysThere() throws IOException
	{
		OutfitProfileStore store = new OutfitProfileStore(new Gson());
		store.load(folder.newFolder().toPath());

		for (String name : new String[]{"Melee", "Ranged", "Magic"})
		{
			assertNotNull("the thrall config points at '" + name + "' by default,"
				+ " so it has to exist", store.get(name));
		}
	}

	@Test
	public void deletingAProfileSticksAcrossAReload() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		OutfitProfileStore first = new OutfitProfileStore(new Gson());
		first.load(dir);
		first.put("Temporary", "weapon=item:4151");
		assertTrue(first.remove("Temporary"));

		OutfitProfileStore second = new OutfitProfileStore(new Gson());
		second.load(dir);
		assertEquals("a deleted profile came back", null, second.get("Temporary"));
	}

	@Test
	public void aCorruptProfileFileDoesNotStopTheStoreLoading() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve("outfit-profiles.json"),
			"{ not json".getBytes(StandardCharsets.UTF_8));

		OutfitProfileStore store = new OutfitProfileStore(new Gson());
		store.load(dir);

		assertNotNull("the seeded profiles should still be there", store.get("Melee"));
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.SpeechRule;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * Whether the shipped lines read well, rather than whether they work.
 *
 * <p>Everything else about the rule file is checked for correctness. These are
 * the things that are correct and still wrong: a line so long it stacks five
 * deep over the follower's head, or the same sentence written into two rules so
 * the follower appears to repeat itself for no reason.
 *
 * <p>The current set is comfortably inside all of these - the longest line is
 * 99 characters and no two rules share a sentence - so this is a guard against
 * the next batch of lines rather than a complaint about these.
 */
public class PhraseQualityTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** FollowerOverlay wraps the overhead line at this width. */
	private static final int WRAP_WIDTH = 34;

	/** Four stacked lines is about as tall as it can get before it reads as a wall. */
	private static final int MAX_LENGTH = 4 * WRAP_WIDTH;

	private List<SpeechRule> shipped() throws IOException
	{
		return new Harness(folder.newFolder().toPath()).loader.getRules();
	}

	@Test
	public void noLineIsTallEnoughToBecomeAWall() throws IOException
	{
		List<String> tooLong = new ArrayList<>();
		for (SpeechRule rule : shipped())
		{
			if (rule.say == null)
			{
				continue;
			}
			for (String line : rule.say)
			{
				if (line.length() > MAX_LENGTH)
				{
					tooLong.add(rule.id + ": " + line.length() + " chars, about "
						+ (line.length() / WRAP_WIDTH + 1) + " lines - " + line);
				}
			}
		}
		assertTrue("lines that would stack too high over the follower:\n  "
			+ String.join("\n  ", tooLong), tooLong.isEmpty());
	}

	@Test
	public void noTwoRulesShareASentence() throws IOException
	{
		// The follower saying the same thing in two situations reads as a bug
		// even when both rules are working exactly as written.
		Map<String, String> seen = new HashMap<>();
		List<String> shared = new ArrayList<>();
		for (SpeechRule rule : shipped())
		{
			if (rule.say == null)
			{
				continue;
			}
			for (String line : rule.say)
			{
				String previous = seen.put(line, rule.id);
				if (previous != null && !previous.equals(rule.id))
				{
					shared.add("\"" + line + "\" in both " + previous + " and " + rule.id);
				}
			}
		}
		assertTrue("the same sentence written into two rules:\n  "
			+ String.join("\n  ", shared), shared.isEmpty());
	}

	@Test
	public void noRuleRepeatsALineWithinItself() throws IOException
	{
		// pickPhrase avoids saying the same INDEX twice running, which does not
		// help if two indices hold the same sentence.
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shipped())
		{
			if (rule.say == null)
			{
				continue;
			}
			List<String> seen = new ArrayList<>();
			for (String line : rule.say)
			{
				if (seen.contains(line))
				{
					problems.add(rule.id + ": \"" + line + "\" twice");
				}
				seen.add(line);
			}
		}
		assertTrue(String.join("\n  ", problems), problems.isEmpty());
	}

	@Test
	public void noLineIsEmptyOrJustPunctuation() throws IOException
	{
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shipped())
		{
			if (rule.say == null)
			{
				continue;
			}
			for (String line : rule.say)
			{
				if (line.trim().isEmpty())
				{
					problems.add(rule.id + ": a blank line");
				}
				else if (!line.matches(".*[A-Za-z].*"))
				{
					problems.add(rule.id + ": \"" + line + "\" has no words in it");
				}
				else if (!line.equals(line.trim()))
				{
					problems.add(rule.id + ": \"" + line + "\" has padding");
				}
			}
		}
		assertTrue(String.join("\n  ", problems), problems.isEmpty());
	}

	/**
	 * A group that speaks should have more than a couple of things to say.
	 *
	 * <p>Groups that do not speak at all are exempt, and are not an oversight:
	 * the mimic rules copy your emote and say nothing, which is the whole idea.
	 */
	@Test
	public void everySPEAKINGGroupHasEnoughToSayToNotSoundScripted() throws IOException
	{
		Map<String, Integer> linesPerGroup = new HashMap<>();
		Map<String, Boolean> speaks = new HashMap<>();
		for (SpeechRule rule : shipped())
		{
			linesPerGroup.merge(rule.group,
				rule.say == null ? 0 : rule.say.size(), Integer::sum);
			speaks.merge(rule.group, rule.hasSpeech(), (a, b) -> a || b);
		}

		List<String> thin = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : linesPerGroup.entrySet())
		{
			if (Boolean.TRUE.equals(speaks.get(entry.getKey())) && entry.getValue() < 3)
			{
				thin.add(entry.getKey() + ": " + entry.getValue() + " lines");
			}
		}
		assertTrue("groups with almost nothing to say: " + thin, thin.isEmpty());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.SpeechRule;
import java.io.IOException;
import java.util.HashSet;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * The number the shuffle bag was built to move, taken off the shipped rules.
 *
 * <p>Variant counts are the one quality figure in this project that can be
 * gamed by writing more without anything getting better. What matters is how
 * many the player HEARS before one comes round again, and under uniform
 * selection those two numbers are wildly different: thirty written, eight
 * heard. This asserts they are now the same number.
 */
public class RepetitionMeasureTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void everyShippedRuleSpendsAllOfItsWritingBeforeRepeating() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());

		int checked = 0;
		StringBuilder worst = new StringBuilder();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.say == null || rule.say.size() < 2)
			{
				continue;
			}
			checked++;

			// Two full cycles, so the refill is included: the seam between one
			// bag and the next is where a naive implementation repeats.
			int size = rule.say.size();
			Set<String> first = new HashSet<>();
			for (int i = 0; i < size; i++)
			{
				if (!first.add(rule.pickPhrase()))
				{
					worst.append("\n  ").append(rule.id)
						.append(": repeated after ").append(i)
						.append(" of ").append(size);
					break;
				}
			}
			Set<String> second = new HashSet<>();
			for (int i = 0; i < size; i++)
			{
				if (!second.add(rule.pickPhrase()))
				{
					worst.append("\n  ").append(rule.id)
						.append(": second bag repeated after ").append(i)
						.append(" of ").append(size);
					break;
				}
			}
		}

		assertTrue("rules that repeat before spending their variants:" + worst,
			worst.length() == 0);
		assertTrue("expected the shipped set to have plenty of multi-line rules",
			checked > 300);
	}

	@Test
	public void theBiggestRuleInTheFileIsHeardInFull() throws IOException
	{
		// idle-chatter is the most-written rule and the most-heard, which is
		// the combination that made uniform selection expensive. Thirty
		// variants, and the player used to meet a repeat after about eight.
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule rule = h.rule("idle-chatter");
		assertTrue("idle-chatter should still be the big one",
			rule.say.size() >= 25);

		Set<String> heard = new HashSet<>();
		for (int i = 0; i < rule.say.size(); i++)
		{
			heard.add(rule.pickPhrase());
		}
		assertTrue("all " + rule.say.size() + " should come out before any repeats,"
			+ " but only " + heard.size() + " did",
			heard.size() == rule.say.size());
	}
}

package com.follower;

import com.follower.sim.Harness;
import com.follower.speech.RuleLoader;
import com.follower.speech.SpeechRule;
import com.follower.speech.TriggerEvent;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What the loader does with a file a person edited by hand.
 *
 * <p>phrases.json is meant to be opened in a text editor, so every kind of
 * mistake will eventually be made in it. None of them may throw, and none may
 * leave the follower mute when the previous rules were fine - losing a whole
 * personality to a trailing comma is worse than running slightly stale rules.
 */
public class RuleLoaderRobustnessTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Path dir() throws IOException
	{
		return folder.newFolder().toPath();
	}

	private RuleLoader loadedWith(Path dir, String contents) throws IOException
	{
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			contents.getBytes(StandardCharsets.UTF_8));
		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);
		return loader;
	}

	// ------------------------------------------------------------- structure

	@Test
	public void aMissingFileIsWrittenFromTheBundledDefaults() throws IOException
	{
		Path dir = dir();
		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);

		assertTrue("no starter file was written",
			Files.isRegularFile(dir.resolve(RuleLoader.FILE_NAME)));
		assertFalse("the starter file loaded no rules", loader.getRules().isEmpty());
	}

	@Test
	public void anOldFileGainsNewlyBundledRulesWithoutLosingItsEdits() throws IOException
	{
		// The upgrade gap: the starter file is written only when missing, so
		// a file from an old release never gained the rules added since -
		// play report, emote mirroring "not working" for a tester whose file
		// predated the mimic rules entirely.
		Path dir = dir();
		// An old-looking file: one bundled rule reworded and silenced, one
		// rule of the user's own, and one bundled rule the editor deleted.
		String old = "{\"version\": 1, \"removed\": [\"mimic-emote-loops\"], \"rules\": ["
			+ "{\"id\": \"mimic-emotes\", \"group\": \"mimic\", \"enabled\": false,"
			+ " \"when\": {\"type\": \"always\"}, \"say\": [\"my own words\"]},"
			+ "{\"id\": \"my-rule\", \"group\": \"t\","
			+ " \"when\": {\"type\": \"always\"}, \"say\": [\"mine\"]}"
			+ "]}";
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			old.getBytes(StandardCharsets.UTF_8));

		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir, true);

		java.util.Set<String> ids = new java.util.HashSet<>();
		for (SpeechRule rule : loader.getRules())
		{
			ids.add(rule.id);
			if ("mimic-emotes".equals(rule.id))
			{
				assertEquals("the user's edit to an existing rule survived",
					"my own words", rule.say.get(0));
			}
		}
		assertTrue("a newly bundled rule arrived", ids.contains("world-hop"));
		assertTrue("the user's own rule survived", ids.contains("my-rule"));
		assertFalse("a rule the editor deleted stayed deleted",
			ids.contains("mimic-emote-loops"));
		assertTrue("the file as it stood was kept as a backup",
			Files.isRegularFile(dir.resolve(RuleLoader.FILE_NAME + ".bak")));

		// And the merge is idempotent: a second start adds nothing.
		byte[] merged = Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME));
		RuleLoader again = new RuleLoader(new Gson());
		again.initialise(dir, true);
		assertTrue("a second start rewrote an already-merged file",
			java.util.Arrays.equals(merged,
				Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME))));
	}

	@Test
	public void malformedFilesNeverThrow() throws IOException
	{
		String[] nonsense = {
			"",
			"   ",
			"{",
			"[]",
			"null",
			"\"just a string\"",
			"{\"version\": 1}",
			"{\"version\": 1, \"rules\": null}",
			"{\"version\": 1, \"rules\": []}",
			"{\"version\": 1, \"rules\": [null, null]}",
			"{\"version\": 1, \"rules\": [{}]}",
			"{\"version\": 1, \"rules\": [{\"id\": \"x\"}]}",
			"{\"version\": 99, \"rules\": []}",
			"{\"rules\": [{\"id\": \"x\", \"when\": {\"type\": \"always\"}, \"say\": [\"a\"]}]}",
			// A trailing comma: the classic hand-edit slip.
			"{\"version\": 1, \"rules\": [{\"id\": \"x\", \"when\": {\"type\": \"always\"},"
				+ " \"say\": [\"a\"]},]}",
			"not json at all",
			"﻿{\"version\": 1, \"rules\": []}",
		};

		for (String contents : nonsense)
		{
			Path dir = dir();
			RuleLoader loader = loadedWith(dir, contents);
			// The contract is only that it survives and says something useful.
			assertTrue("no status for " + summarise(contents),
				loader.getStatus() != null && !loader.getStatus().isEmpty());
			loader.reload();
			loader.reloadIfChanged();
		}
	}

	private static String summarise(String contents)
	{
		String flat = contents.replace('\n', ' ');
		return flat.length() > 40 ? flat.substring(0, 40) + "..." : "'" + flat + "'";
	}

	@Test
