package com.follower.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Which side-step a weapon uses when its own was never observed.
 *
 * <p>The measured rule, and the one that produced the visible bug: of the 26
 * weapons using the DEFAULT walk, all 26 also use the default side-steps, so
 * the standard set is exactly right for them. Of the 41 with a weapon-specific
 * walk, only 5 use the standard side-step and not one uses the standard
 * back-pedal - so borrowing it is wrong about nine times in ten, and it shows:
 * an empty-handed strafe while carrying a bulwark.
 *
 * <p>Anything with its own walk therefore falls back to that walk instead,
 * which is the client's own behaviour for a pose resolving to -1 and keeps the
 * weapon in hand.
 */
public class DirectionalFallbackTest
{
	private static final int STANDARD_SIDESTEP = PlayerPose.SIDESTEP_LEFT;
	private static final int STANDARD_BACKPEDAL = PlayerPose.TURN_180;

	private static StanceLibrary.Stance walkingWith(int walk)
	{
		StanceLibrary.Stance stance = new StanceLibrary.Stance();
		stance.walk = walk;
		return stance;
	}

	@Test
	public void anUnarmedStanceTakesTheStandardDirectionalPoses()
	{
		StanceLibrary.Stance unarmed = walkingWith(PlayerPose.WALK);

		assertEquals("a default walk means the default side-step is right",
			STANDARD_SIDESTEP,
			FollowerEntity.directionalFallback(unarmed, STANDARD_SIDESTEP));
		assertEquals(STANDARD_BACKPEDAL,
			FollowerEntity.directionalFallback(unarmed, STANDARD_BACKPEDAL));
	}

	@Test
	public void aWeaponWithItsOwnWalkKeepsWalkingRatherThanBorrowing()
	{
		// A bulwark, a halberd, anything carried distinctively.
		int weaponWalk = 7511;
		StanceLibrary.Stance armed = walkingWith(weaponWalk);

		assertEquals("strafing must not drop into the empty-handed side-step",
			weaponWalk,
			FollowerEntity.directionalFallback(armed, STANDARD_SIDESTEP));
		assertEquals("and nor must backing away",
			weaponWalk,
			FollowerEntity.directionalFallback(armed, STANDARD_BACKPEDAL));
	}

	@Test
	public void theRuleTurnsOnTheWalkAloneNotOnTheStandardAskedFor()
	{
		// Whatever pose is asked for, the answer depends only on whether this
		// stance walks the default way.
		StanceLibrary.Stance armed = walkingWith(9999);
		for (int standard : new int[]{PlayerPose.SIDESTEP_LEFT,
			PlayerPose.SIDESTEP_RIGHT, PlayerPose.TURN_180, PlayerPose.IDLE_TURN})
		{
			assertEquals(9999, FollowerEntity.directionalFallback(armed, standard));
		}

		StanceLibrary.Stance unarmed = walkingWith(PlayerPose.WALK);
		for (int standard : new int[]{PlayerPose.SIDESTEP_LEFT,
			PlayerPose.SIDESTEP_RIGHT, PlayerPose.TURN_180, PlayerPose.IDLE_TURN})
		{
			assertEquals(standard,
				FollowerEntity.directionalFallback(unarmed, standard));
		}
	}

	@Test
	public void aStanceWithNoWalkAtAllStillAnswersSomething()
	{
		// A stance saved before the directional fields existed deserialises
		// with zeroes; it must not hand back a standard pose as though the
		// weapon had been observed walking the default way.
		StanceLibrary.Stance empty = new StanceLibrary.Stance();
		assertEquals("a missing walk is not the default walk", 0,
			FollowerEntity.directionalFallback(empty, STANDARD_SIDESTEP));
	}

	@Test
	public void theBundledUnarmedStanceUsesTheStandardSet()
	{
		// The one stance that is built in rather than learned. If it ever
		// stopped matching PlayerPose.WALK, every unarmed follower would
		// strafe with the wrong animation.
		StanceLibrary library = new StanceLibrary(new com.google.gson.Gson(),
			new com.follower.appearance.ModelRepository(new com.google.gson.Gson()));
		StanceLibrary.Stance unarmed = library.forWeapon(0);

		assertEquals("unarmed must walk with the standard walk pose",
			PlayerPose.WALK, unarmed.walk);
		assertEquals(STANDARD_SIDESTEP,
			FollowerEntity.directionalFallback(unarmed, STANDARD_SIDESTEP));
	}
}

package com.follower.follower;

import com.follower.FollowerConfig;
import com.follower.appearance.SpotAnimRepository;
import com.follower.sim.FakeGame;
import com.follower.speech.TriggerEvent;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Errands, which are the only thing that sends the follower away on its own.
 *
 * <p>Everything here is about the refusals. An errand is a small piece of
 * character that must never cost the player anything, so it may not begin
 * while they are fighting, in the wilderness, or already using the follower for
 * something else - and once begun it has to let go the moment any of that
 * changes, leaving the follower back at heel rather than standing in a bank
 * three rooms away.
 *
 * <p>Only bootlace and glance are driven end to end. The rest look for a scene
 * object, and a scene is the one thing this harness has none of - which is
 * fine, because "found nothing, so did not start" is itself a refusal worth
 * checking.
 *
 * <p>It does mean the TELEPORT home is out of reach here. Both errands that run
 * to completion are the two that come back on foot, and every errand that walks
 * far enough to teleport is one that needs an object to walk to. That path is
 * checked in game rather than pretended at.
 */
public class ErrandSimulationTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** Records what the follower was asked to do; does none of it. */
	private static final class RecordingFollower extends FollowerEntity
	{
		boolean spawned = true;
		boolean settled = true;
		boolean staying;
		boolean following = true;
		boolean teleportedHome;
		WorldPoint where = new WorldPoint(3222, 3218, 0);
		final List<Integer> animations = new ArrayList<>();

		RecordingFollower()
		{
			super(null, null);
		}

		@Override
		public boolean isSpawned()
		{
			return spawned;
		}

		@Override
		public boolean isSettled()
		{
			return settled;
		}

		@Override
		public boolean isStaying()
		{
			return staying;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return where;
		}

		@Override
		public boolean stayAt(WorldPoint target)
		{
			staying = true;
			following = false;
			where = target;
			return target != null;
		}

		@Override
		public void stayHere()
		{
			staying = true;
			following = false;
		}

		@Override
		public void resumeFollowing()
		{
			staying = false;
			following = true;
		}

		@Override
		public void teleportToPlayer()
		{
			teleportedHome = true;
			where = new WorldPoint(3222, 3218, 0);
		}

		int poseOverride;

		@Override
		public void setPoseOverride(int id)
		{
			poseOverride = id;
		}

		@Override
		public void playAnimation(int id)
		{
			animations.add(id);
		}

		@Override
		public void setStayFaceTile(WorldPoint tile)
		{
		}

		@Override
		public void hideAfterEmote(int ms)
		{
		}
	}

	private static final int WILDERNESS_VARBIT = 5963;

	private FakeGame game;
	private RecordingFollower follower;
	private ErrandController errands;
	private List<TriggerEvent> dispatched;
	private boolean busy;
	private int tick;

	@Before
	public void setUp() throws IOException
	{
		game = new FakeGame();
		follower = new RecordingFollower();
		dispatched = new ArrayList<>();
		busy = false;

		SpotAnimRepository spotAnims = new SpotAnimRepository(new Gson());
		spotAnims.load(folder.newFolder().toPath());

		errands = new ErrandController(game.client, follower, config(),
			dispatched::add, spotAnims, () -> busy, new ErrandController.Hands()
			{
				@Override
				public void hold(int itemId)
				{
					heldProp = itemId;
				}

				@Override
				public void release()
				{
					heldProp = 0;
				}
			});
	}

	/** What the hands are holding; 0 for nothing. */
	private int heldProp;

	/** For the secondary controllers a few tests build: hands nobody watches. */
	private static ErrandController.Hands idleHands()
	{
		return new ErrandController.Hands()
		{
			@Override
			public void hold(int itemId)
			{
			}

			@Override
			public void release()
			{
			}
		};
	}

	private FollowerConfig config()
	{
		return new FollowerConfig()
		{
		};
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			game.tick(++tick);
			errands.tick();
		}
	}

	private boolean started(String key)
	{
		for (TriggerEvent event : dispatched)
		{
			if (event.getType() == TriggerEvent.Type.ERRAND_START
				&& key.equals(event.getName()))
			{
				return true;
			}
		}
		return false;
	}

	// --------------------------------------------------------------- happy path

	@Test
	public void aBootlaceErrandRunsAndGivesTheFollowerBack()
	{
		errands.force("bootlace");
		tick(1);

		assertTrue("the errand never started", errands.isBusy());
		assertTrue("it should have stopped where it stood", follower.staying);
		assertFalse("and played something", follower.animations.isEmpty());
		assertTrue("and announced itself", started("bootlace"));

		tick(30);

		assertFalse("the errand should have finished", errands.isBusy());
		assertTrue("and handed the follower back", follower.following);
	}

	@Test
	public void aGlanceSendsItAShortWayAndBringsItBack()
	{
		errands.force("glance");
		tick(1);

		assertTrue(errands.isBusy());
		assertTrue("it should have been sent somewhere", follower.where != null);
		assertTrue("but not far", follower.where
			.distanceTo(new WorldPoint(3222, 3218, 0)) <= 4);

		tick(60);
		assertFalse(errands.isBusy());
		assertTrue(follower.following);
	}

	@Test
	public void theDocumentErrandHoldsTheScrollForExactlyTheRead()
	{
		errands.force("document");
		tick(1);

		assertTrue("the errand never started", errands.isBusy());
		assertTrue("it should have stopped where it stood", follower.staying);
		assertEquals("the scroll is out", 10485, heldProp);
		assertEquals("and the pose plays from the same tick - the dump path is"
			+ " synchronous, so waiting only shows a scroll in idle hands",
			5354, follower.poseOverride);
		assertTrue("and it announced itself", started("document"));

		tick(30);
		assertFalse("the errand should have finished", errands.isBusy());
		assertEquals("the pose released", 0, follower.poseOverride);
		assertEquals("and the scroll went away", 0, heldProp);
		assertTrue("and the follower came back", follower.following);
	}

	@Test
	public void anInterruptedDocumentStillPutsTheScrollAway()
	{
		// The failure shape every interesting bug here has had: state
		// outliving its owner. A follower stuck holding a scroll in its
		// walking pose would wear this bug forever.
		errands.force("document");
		tick(3);
		assertEquals(5354, follower.poseOverride);

		busy = true;      // the dialog opened mid-read
		tick(1);

		assertFalse("the errand should have aborted", errands.isBusy());
		assertEquals("the pose must not outlive it", 0, follower.poseOverride);
		assertEquals("nor the scroll", 0, heldProp);
	}

	@Test
	public void aStudyLooksBeforeItWritesAndNamesWhatItStudied()
	{
		// The find half needs a real scene; everything after it is lifecycle,
		// injected through the same seam a real find would use.
		assertTrue(errands.beginStudyAt(new WorldPoint(3225, 3218, 0), "Well"));
		assertTrue(errands.isBusy());
		assertTrue("it announced the specific thing", started("study-well"));

		tick(2);      // arrive (the recording follower is always settled)
		assertEquals("looking first: no scroll during the look", 0, heldProp);
		assertEquals("and no pose either", 0, follower.poseOverride);

		tick(5);      // the look ends
		assertEquals("the scroll comes out", 10485, heldProp);
		assertEquals("with the pose on the same tick", 5354, follower.poseOverride);

		tick(30);
		assertFalse("the study should have finished", errands.isBusy());
		assertEquals(0, follower.poseOverride);
		assertEquals(0, heldProp);

		boolean endNamed = false;
		for (TriggerEvent event : dispatched)
		{
			endNamed |= event.getType() == TriggerEvent.Type.ERRAND_END
				&& "study-well".equals(event.getName());
		}
		assertTrue("the verdict names the thing too", endNamed);
	}

	@Test
	public void anExploreLooksThenNotesItDownForPosterity()
	{
		// The explore is the study's nosy sibling: same trip, same
		// look-then-write beat - everything explored goes in the scroll.
		assertTrue(errands.beginExploreAt(new WorldPoint(3225, 3218, 0), "Chest"));
		assertTrue(errands.isBusy());
		assertTrue("it announced the specific thing", started("explore-chest"));

		tick(2);      // arrive (the recording follower is always settled)
		assertEquals("looking first: no scroll during the look", 0, heldProp);
		assertEquals("and no pose either", 0, follower.poseOverride);

		tick(5);      // the look ends
		assertEquals("the entry gets written", 10485, heldProp);
		assertEquals("with the pose on the same tick", 5354, follower.poseOverride);

		tick(25);
		assertFalse("the look should have finished", errands.isBusy());
		assertEquals("the scroll went away", 0, heldProp);
		assertEquals("and the pose released", 0, follower.poseOverride);
		assertTrue("and the follower came back", follower.following);

		boolean endNamed = false;
		for (TriggerEvent event : dispatched)
		{
			endNamed |= event.getType() == TriggerEvent.Type.ERRAND_END
				&& "explore-chest".equals(event.getName());
		}
		assertTrue("the verdict names the thing too", endNamed);
	}

	@Test
	public void anInterruptedExploreReleasesEverything()
	{
		errands.beginExploreAt(new WorldPoint(3225, 3218, 0), "Chest");
		tick(9);      // deep enough that the scroll is out and the pose holds
		assertEquals(5354, follower.poseOverride);

		busy = true;
		tick(1);

		assertFalse(errands.isBusy());
		assertEquals("the pose must not outlive the look", 0, follower.poseOverride);
		assertEquals("nor the scroll", 0, heldProp);
	}

	@Test
	public void arrivingSomewhereNewEarnsALookOnceSettled()
	{
		// The R19 half: a region change arms a watch, and the explore begins
		// only after the player holds still - never while they are mid-run,
		// where the distance abort would yank it back three ticks later.
		game.at(50, 50, 0);
		follower.where = new WorldPoint(50, 51, 0);
		game.placeObject(9001, "Chest", 53, 50, 0);

		errands.noticeArrival();
		tick(1);

		// Stop-start travel: never eight QUIET ticks in a row, though far
		// more than eight in total. The watch must demand consecutive
		// stillness - a counter that merely accumulated across the pauses
		// in the walking would start the errand mid-journey. (The first
		// version of this test moved too briefly to tell the difference;
		// the mutation sweep caught it.)
		for (int leg = 0; leg < 4; leg++)
		{
			game.at(51 + leg, 50, 0);
			tick(4);
		}
		assertFalse("no exploring while the player is stop-starting",
			errands.isBusy());

		// Now they genuinely stop, and eight quiet ticks later the
		// nosiness begins.
		tick(8);
		assertTrue("the settled arrival earns a look", started("explore-chest"));
		assertTrue(errands.isBusy());

		tick(40);
		assertFalse(errands.isBusy());
		assertTrue(follower.following);
	}

	@Test
	public void anArrivalLostToAFightDoesNotBurnTheCooldown()
	{
		// Settling mid-combat forfeits THIS look, not the next one: the
		// cooldown is charged only when an explore actually starts, so the
		// next region change still gets its curiosity.
		game.at(50, 50, 0);
		follower.where = new WorldPoint(50, 51, 0);
		game.placeObject(9001, "Chest", 53, 50, 0);

		game.fighting(game.spawnNpc(3029, "Goblin", 5));
		errands.noticeArrival();
		tick(12);
		assertFalse("no nosing about mid-fight", errands.isBusy());

		game.fighting(null);
		errands.noticeArrival();
		tick(12);
		assertTrue("the next arrival still gets its look", started("explore-chest"));
	}

	@Test
	public void arrivalLooksAreRationedByTheCooldown()
	{
		game.at(50, 50, 0);
		follower.where = new WorldPoint(50, 51, 0);
		game.placeObject(9001, "Chest", 53, 50, 0);

		errands.noticeArrival();
		tick(10);
		assertTrue(started("explore-chest"));
		tick(40);
		assertFalse(errands.isBusy());

		// The next region, minutes too soon: watched, settled, and refused.
		errands.noticeArrival();
		tick(15);

		int starts = 0;
		for (TriggerEvent event : dispatched)
		{
			if (event.getType() == TriggerEvent.Type.ERRAND_START)
			{
				starts++;
			}
		}
		assertEquals("a trip through several regions is one inspection, not several",
			1, starts);
	}

	@Test
	public void anInterruptedStudyReleasesEverything()
	{
		errands.beginStudyAt(new WorldPoint(3225, 3218, 0), "Anvil");
		tick(9);      // deep enough that the scroll is out and the pose holds

		busy = true;
		tick(1);

		assertFalse(errands.isBusy());
		assertEquals("the pose must not outlive the study", 0, follower.poseOverride);
		assertEquals("nor the scroll", 0, heldProp);
	}

	@Test
	public void anErrandAnnouncesBothItsEndsExactlyOnce()
	{
		errands.force("bootlace");
		tick(40);

		int starts = 0;
		int ends = 0;
		for (TriggerEvent event : dispatched)
		{
			if (event.getType() == TriggerEvent.Type.ERRAND_START)
			{
				starts++;
			}
			if (event.getType() == TriggerEvent.Type.ERRAND_END)
			{
				ends++;
			}
		}
		assertEquals("one start", 1, starts);
		assertEquals("one end", 1, ends);
	}

	// ---------------------------------------------------------- the refusals

	@Test
	public void nothingStartsWhileThePlayerIsFighting()
	{
		game.fighting(game.spawnNpc(3029, "Goblin", 5));
		errands.force("bootlace");
		tick(10);

		assertFalse("an errand must not begin mid-fight", errands.isBusy());
	}

	@Test
	public void nothingStartsInTheWilderness()
	{
		game.varbit(WILDERNESS_VARBIT, 1);
		errands.force("bootlace");
		tick(10);

		assertFalse("wandering off in the wilderness is how a follower gets lost",
			errands.isBusy());
	}

	@Test
	public void nothingStartsWhileSomethingElseOwnsTheFollower()
	{
		busy = true;
		errands.force("bootlace");
		tick(10);

		assertFalse("thrall mode and spectating outrank an errand", errands.isBusy());
	}

	@Test
	public void nothingStartsWhileTheFollowerIsAlreadyPosed()
	{
		follower.staying = true;
		errands.force("bootlace");
		tick(10);

		assertFalse(errands.isBusy());
	}

	@Test
	public void nothingStartsWithNoFollowerInTheWorld()
	{
		follower.spawned = false;
		errands.force("bootlace");
		tick(10);

		assertFalse(errands.isBusy());
	}

	@Test
	public void anErrandThatCanFindNowhereToGoSimplyDoesNotStart()
	{
		// No scene here, so every errand that needs an object finds none.
		for (String key : new String[]{"bank", "altar", "fire", "cat"})
		{
			setUpQuietly();
			errands.force(key);
			tick(5);
			assertFalse(key + " started with nothing to go to", errands.isBusy());
		}
	}

	private void setUpQuietly()
	{
		try
		{
			setUp();
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	// -------------------------------------------------------- letting go again

	@Test
	public void theFollowerIsAlwaysReleasedHoweverAnErrandEnds()
	{
		String[] interruptions = {"fight", "wilderness", "busy", "despawn", "walked away"};
		for (String interruption : interruptions)
		{
			setUpQuietly();
			errands.force("glance");
			tick(1);
			assertTrue(interruption + ": the errand never started", errands.isBusy());

			switch (interruption)
			{
				case "fight":
					game.fighting(game.spawnNpc(3029, "Goblin", 5));
					break;
				case "wilderness":
					game.varbit(WILDERNESS_VARBIT, 1);
					break;
				case "busy":
					busy = true;
					break;
				case "despawn":
					follower.spawned = false;
					break;
				default:
					// The player teleports away and leaves it behind.
					game.at(3300, 3300, 0);
					break;
			}
			tick(3);

			assertFalse(interruption + ": the errand carried on regardless",
				errands.isBusy());
			assertTrue(interruption + ": the follower was left posed, not following",
				follower.following);
		}
	}

	@Test
	public void aFollowerLeftBehindIsBroughtHomeRatherThanStranded()
	{
		errands.force("glance");
		tick(1);

		// It ended up a long way off and the player has gone.
		follower.where = new WorldPoint(3300, 3300, 0);
		game.at(3400, 3400, 0);
		tick(3);

		assertTrue("a follower stranded out of sight has to be brought back",
			follower.teleportedHome);
		assertTrue(follower.following);
	}

	@Test
	public void switchingErrandsOffMidErrandEndsItAtOnce()
	{
		FollowerConfig off = new FollowerConfig()
		{
			@Override
			public boolean errandsEnabled()
			{
				return false;
			}
		};
		ErrandController disabled = new ErrandController(game.client, follower, off,
			dispatched::add, new SpotAnimRepository(new Gson()), () -> busy, idleHands());

		disabled.force("bootlace");
		for (int i = 0; i < 10; i++)
		{
			game.tick(++tick);
			disabled.tick();
		}

		assertFalse("the setting is off", disabled.isBusy());
		assertTrue(follower.following);
	}

	// ---------------------------------------------------------------- resets

	@Test
	public void aResetLeavesNothingOwedToTheNextSession()
	{
		errands.force("bootlace");
		errands.reset();
		tick(20);

		assertFalse("a forced errand from before a logout must not fire after it",
			errands.isBusy());
		assertTrue(started("bootlace") == false);
	}

	@Test
	public void aResetMidErrandStopsIt()
	{
		errands.force("bootlace");
		tick(1);
		assertTrue(errands.isBusy());

		errands.reset();
		assertFalse(errands.isBusy());
	}

	// ----------------------------------------------------------- long running

	/**
	 * Left alone, errands should happen on their own - that is the whole point
	 * - but at the pace the setting describes rather than back to back.
	 *
	 * <p>Bootlace and glance need nothing from the scene, so these are the two
	 * that can run here. At the default frequency the interval is 1800 ticks
	 * either side of 40%, which is around eighteen minutes of real time.
	 */
	@Test
	public void leftAloneErrandsHappenButAreSpacedOut()
	{
		tick(20000);

		int starts = 0;
		for (TriggerEvent event : dispatched)
		{
			if (event.getType() == TriggerEvent.Type.ERRAND_START)
			{
				starts++;
			}
		}

		assertTrue("over 20,000 ticks the follower never once did anything"
			+ " off its own back", starts > 0);
		assertTrue("errands fired " + starts + " times in 20,000 ticks, which is"
			+ " far more often than the interval allows", starts <= 20);
		assertTrue("it should be back at heel at the end", follower.following);
	}

	@Test
	public void everyToggleOffMeansNoErrandsAtAll()
	{
		FollowerConfig none = new FollowerConfig()
		{
			@Override
			public boolean errandBank()
			{
				return false;
			}

			@Override
			public boolean errandAltar()
			{
				return false;
			}

			@Override
			public boolean errandFire()
			{
				return false;
			}

			@Override
			public boolean errandCat()
			{
				return false;
			}

			@Override
			public boolean errandBootlace()
			{
				return false;
			}

			@Override
			public boolean errandGlance()
			{
				return false;
			}

			@Override
			public boolean errandDocument()
			{
				return false;
			}
		};
		ErrandController silent = new ErrandController(game.client, follower, none,
			dispatched::add, new SpotAnimRepository(new Gson()), () -> busy, idleHands());

		for (int i = 0; i < 3000; i++)
		{
			game.tick(++tick);
			silent.tick();
		}

		assertFalse(silent.isBusy());
		assertTrue("with every errand switched off, none may run", dispatched.isEmpty());
	}

	// ------------------------------------------------------------- rotation

	@Test
	public void theSameErrandDoesNotComeRoundAgainAndAgain()
	{
		// Fifteen days of real play, measured: three errands were 84% of every
		// one that ran. Not because the roll preferred them - it shuffles -
		// but because they are the three that need nothing in the world. A
		// bank errand needs a booth in sight; the bootlace needs only a boot,
		// so it won every roll the others could not. It ran 189 times on five
		// lines, and the player heard each of them thirty-seven times.
		//
		// An empty scene is exactly that situation: nothing to walk to, so
		// only the self-contained errands can start. Whatever runs here must
		// still take turns.
		List<String> order = new ArrayList<>();
		for (int i = 0; i < 20_000; i++)
		{
			game.tick(++tick);
			errands.tick();
			for (TriggerEvent event : dispatched)
			{
				if (event.getType() == TriggerEvent.Type.ERRAND_START)
				{
					order.add(event.getName());
				}
			}
			dispatched.clear();
		}

		assertTrue("nothing ran at all, so this proves nothing", order.size() >= 4);

		int repeats = 0;
		for (int i = 1; i < order.size(); i++)
		{
			if (order.get(i).equals(order.get(i - 1)))
			{
				repeats++;
			}
		}
		assertEquals("an errand ran twice in a row: " + order, 0, repeats);

		long distinct = order.stream().distinct().count();
		assertTrue("only one kind of errand ever ran: " + order, distinct >= 2);
	}
}

package com.follower.follower;

import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The rule-sized writing gesture: stop, scroll out, pose, everything back.
 *
 * <p>Same lifecycle promises as the errand's scroll handling, tested the same
 * way: the prop leads the pose by the settle ticks, the cleanup runs whole
 * from both the finish and the abort, and a second request mid-gesture is
 * dropped rather than queued.
 */
public class PropFlourishTest
{
	/** Records what it was asked; does none of it. */
	private static final class RecordingFollower extends FollowerEntity
	{
		boolean staying;
		boolean following = true;
		int poseOverride;

		RecordingFollower()
		{
			super(null, null);
		}

		@Override
		public void stayHere()
		{
			staying = true;
			following = false;
		}

		@Override
		public void resumeFollowing()
		{
			staying = false;
			following = true;
		}

		@Override
		public void setPoseOverride(int id)
		{
			poseOverride = id;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return new WorldPoint(3222, 3218, 0);
		}
	}

	private RecordingFollower follower;
	private PropFlourish flourish;
	private int held;

	@Before
	public void setUp()
	{
		follower = new RecordingFollower();
		flourish = new PropFlourish(follower, new ErrandController.Hands()
		{
			@Override
			public void hold(int itemId)
			{
				held = itemId;
			}

			@Override
			public void release()
			{
				held = 0;
			}
		});
	}

	@Test
	public void theScrollAndThePoseArriveTogether()
	{
		// On the same tick, and so the same rendered frame. The first version
		// held the pose back two "settle" ticks out of caution about a rebuild
		// delay the dump path does not have - and those ticks were exactly the
		// window in which the follower stood in its idle pose holding a
		// scroll, which the eye reads as wrong immediately.
		assertTrue(flourish.start(10485, 5354, 5));
		assertTrue(flourish.isActive());
		assertTrue("it should stop to write", follower.staying);
		assertEquals("the scroll is out", 10485, held);
		assertEquals("and the pose is already playing", 5354, follower.poseOverride);
	}

	@Test
	public void everythingGoesBackWhenTheMomentPasses()
	{
		flourish.start(10485, 5354, 3);
		for (int i = 0; i < 10; i++)
		{
			flourish.tick();
		}

		assertFalse(flourish.isActive());
		assertEquals("the pose released", 0, follower.poseOverride);
		assertEquals("the scroll went away", 0, held);
		assertTrue("and the follower walks again", follower.following);
	}

	@Test
	public void anAbortPutsEverythingBackToo()
	{
		flourish.start(10485, 5354, 20);
		flourish.tick();
		flourish.tick();
		assertEquals(5354, follower.poseOverride);

		flourish.abort();

		assertFalse(flourish.isActive());
		assertEquals(0, follower.poseOverride);
		assertEquals(0, held);
		assertTrue(follower.following);
	}

	@Test
	public void aSecondGestureMidGestureIsDroppedNotQueued()
	{
		assertTrue(flourish.start(10485, 5354, 10));
		assertFalse("a backlog of gestures stops reading as spontaneous",
			flourish.start(10485, 5354, 10));
	}

	@Test
	public void nonsenseNeverStarts()
	{
		assertFalse(flourish.start(0, 5354, 10));
		assertFalse(flourish.start(10485, 0, 10));
		assertFalse("and nothing was touched", follower.staying);
		assertEquals(0, held);
	}
}

package com.follower.follower;

import com.follower.FollowerConfig;
import com.follower.appearance.SpotAnimRepository;
import com.follower.sim.FakeGame;
import com.follower.speech.TriggerContext;
import com.follower.speech.TriggerEvent;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The whole spectating sequence, driven tick by tick with nothing running.
 *
 * <p>It is the plugin's longest-lived state machine - step clear, raise a ward,
 * hold it, drop it, walk back - and every stage of it hands the follower's
 * weapon away and takes it back again. A stage that never completes leaves the
 * follower unarmed indefinitely, which is a bug the player only notices much
 * later, so the transitions are worth pinning individually.
 */
public class SpectateSimulationTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A follower that records what it was told to do and does none of it. */
	private static final class FakeFollower extends FollowerEntity
	{
		boolean spawned = true;
		boolean settled = true;
		boolean emoting;
		/**
		 * A cast has to FINISH, or the controller waits on it forever - the
		 * summon hands over to the channel only once the emote has played out.
		 * Two ticks stands in for a real one-shot clip.
		 */
		int emoteTicksLeft;
		WorldPoint stayingAt;
		boolean following = true;
		int poseOverride;
		final List<int[]> chains = new ArrayList<>();
		final List<SpotAnimRepository.Entry> spotAnims = new ArrayList<>();

		/** Tiles the arena refuses; null means everywhere is standable. */
		java.util.function.Predicate<WorldPoint> walled;
		int stayAttempts;

		FakeFollower()
		{
			super(null, null);
		}

		@Override
		public boolean isSpawned()
		{
			return spawned;
		}

		@Override
		public boolean isSettled()
		{
			return settled;
		}

		@Override
		public boolean isStaying()
		{
			return stayingAt != null;
		}

		@Override
		public boolean isEmotePlaying()
		{
			return emoting;
		}

		@Override
		public boolean stayAt(WorldPoint target)
		{
			stayAttempts++;
			if (target == null || (walled != null && walled.test(target)))
			{
				return false;
			}
			stayingAt = target;
			following = false;
			return true;
		}

		@Override
		public void resumeFollowing()
		{
			following = true;
			stayingAt = null;
		}

		@Override
		public void setPoseOverride(int pose)
		{
			poseOverride = pose;
		}

		@Override
		public void playAnimations(int[] ids, SpotAnimRepository.Entry[] graphics)
		{
			chains.add(ids.clone());
			emoting = true;
			emoteTicksLeft = 2;
		}

		/** Runs the clock on whatever is playing, as the animation controller would. */
		void advance()
		{
			if (emoting && --emoteTicksLeft <= 0)
			{
				emoting = false;
			}
		}

		@Override
		public void playSpotAnim(SpotAnimRepository.Entry entry)
		{
			spotAnims.add(entry);
		}
	}

	private FakeGame game;
	private TriggerContext context;
	private FakeFollower follower;
	private SpectateController spectate;
	private List<TriggerEvent> spoken;
	private List<Boolean> disarms;
	private int tick;

	@Before
	public void setUp() throws IOException
	{
		game = new FakeGame();
		context = new TriggerContext(game.client);
		follower = new FakeFollower();
		spoken = new ArrayList<>();
		disarms = new ArrayList<>();

		SpotAnimRepository spotAnims = new SpotAnimRepository(new Gson());
		spotAnims.load(folder.newFolder().toPath());

		spectate = new SpectateController(game.client, follower, config(),
			() -> context, spotAnims, spoken::add, disarms::add);
	}

	/** The shipped defaults, which is what a player will actually be running. */
	private FollowerConfig config()
	{
		return new FollowerConfig()
		{
		};
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			game.tick(++tick);
			context.refresh();
			follower.advance();
			spectate.tick(false);
		}
	}

	private NPC fight(String name, int level)
	{
		NPC target = game.spawnNpc(100, name, level);
		// Standing off to one side, so there is a direction to step away in.
		game.at(3222, 3218, 0);
		game.fighting(target);
		return target;
	}

	private boolean spoke(TriggerEvent.Type type)
	{
		for (TriggerEvent event : spoken)
		{
			if (event.getType() == type)
			{
				return true;
			}
		}
		return false;
	}

	// ------------------------------------------------------------ engagement

	@Test
	public void nothingHappensWhileThereIsNoFight()
	{
		tick(10);

		assertFalse("it should not be spectating an empty room", spectate.isSpectating());
		assertTrue("nor holding a position", follower.following);
		assertTrue("nor saying anything", spoken.isEmpty());
	}

	@Test
	public void aFightMakesItStepClearAndSaySo()
	{
		fight("Goblin", 5);
		tick(2);

		assertTrue(spectate.isSpectating());
		assertTrue("it should have moved out of the way", follower.stayingAt != null);
		assertTrue("and announced the fight", spoke(TriggerEvent.Type.COMBAT_START));
	}

	@Test
	public void spectatingSurvivesTheEngineReplacingItsContext()
	{
		// The real bug behind two boss-fight reports. SpeechEngine.reset()
		// nulls its context and lazily builds a NEW one - on every login
		// screen, the memory eraser, a plugin toggle. The controller was
		// handed the ORIGINAL object at startup and kept reading it: a
		// context nobody refreshed any more, inCombat false forever. The
		// rules kept cheering (they read the live one), the follower stood
		// glued to the player, and both arena fixes were beside the point
		// because start() never ran. The controller now reads through a
		// supplier, so it sees whichever context the engine currently owns.
		TriggerContext[] live = {context};
		spectate = new SpectateController(game.client, follower, config(),
			() -> live[0], new SpotAnimRepository(new Gson()), spoken::add, disarms::add);

		// A relog: the engine throws its context away and starts a fresh one.
		live[0] = new TriggerContext(game.client);

		NPC boss = game.spawnNpc(100, "Vorkath", 392);
		game.at(3222, 3218, 0);
		game.fighting(boss);
		for (int i = 0; i < 3; i++)
		{
			game.tick(++tick);
			live[0].refresh();          // the plugin refreshes the LIVE one
			follower.advance();
			spectate.tick(false);
		}

		assertTrue("the fight after a relog must still be spectated",
			spectate.isSpectating());
		assertTrue("and stepped clear of", follower.stayingAt != null);
		assertTrue(spoke(TriggerEvent.Type.COMBAT_START));
	}

	@Test
	public void aWalledArenaStillFindsSomewhereNotUnderfoot()
	{
		// The player fights with their back to a wall - everything on the
		// away-from-the-boss side is stone. The old fan only ever tried that
		// side and gave up; the follower stood glued to the player for the
		// whole fight. Any tile at a distance that is not beside the boss
		// serves the real goal, which is "not underfoot".
		NPC boss = game.spawnNpc(100, "Vorkath", 392);
		game.at(3222, 3218, 0);
		game.fighting(boss);
		WorldPoint player = new WorldPoint(3222, 3218, 0);
		WorldPoint threat = boss.getWorldLocation();
		int awayX = Integer.signum(player.getX() - threat.getX());
		int awayY = Integer.signum(player.getY() - threat.getY());
		// Wall: everything on the away side (and straight sideways).
		follower.walled = tile ->
			Integer.signum(tile.getX() - player.getX()) == awayX
				&& Integer.signum(tile.getY() - player.getY()) == awayY
			|| tile.getY() == player.getY() || tile.getX() == player.getX();

		tick(2);

		assertTrue(spectate.isSpectating());
		assertTrue("the ring found a standable tile the fan could not",
			follower.stayingAt != null);
		assertTrue("and it is not beside the boss",
			follower.stayingAt.distanceTo(threat) >= 3);
	}

	@Test
	public void anUnseatedSpectatorKeepsLookingAsTheFightMoves()
	{
		// Nowhere at all to stand on the first tick - and then the fight
		// shifts and a tile opens. The old code never looked again: a null
		// watch tile made holdPosition return every tick until the fight
		// ended, which is the whole boss fight spent underfoot.
		NPC boss = game.spawnNpc(100, "Vorkath", 392);
		game.at(3222, 3218, 0);
		game.fighting(boss);
		follower.walled = tile -> true;      // the arena is all wall
		tick(2);
		assertTrue(spectate.isSpectating());
		assertTrue("nowhere to go yet", follower.stayingAt == null);
		int attemptsSoFar = follower.stayAttempts;

		follower.walled = null;              // the fight moved; tiles open
		tick(6);                             // past the retry interval

		assertTrue("it looked again", follower.stayAttempts > attemptsSoFar);
		assertTrue("and stepped clear once it could",
			follower.stayingAt != null);
	}

	@Test
	public void anotherSystemStealingTheSeatGetsItTakenBack()
	{
		// The stay is held through FollowerEntity, and plenty of hands can
		// release it without telling this controller - the thrall exit's
		// stayHere/resumeFollowing/snapBeside chain, the leash snap, scene
		// recovery. Play report, near verbatim: "out of thrall mode they
		// don't step away, but they still do the magic barrier animations."
		fight("Boss", 300);
		tick(3);
		assertTrue(spectate.isSpectating());
		assertTrue("seated", follower.stayingAt != null);

		// The thrall exit hands the feet back to plain following.
		follower.stayingAt = null;
		int attemptsSoFar = follower.stayAttempts;
		tick(2);

		assertTrue("it noticed and took the seat back",
			follower.stayAttempts > attemptsSoFar);
		assertTrue(follower.stayingAt != null);
	}

	@Test
	public void aBossThatHitsYouWhileYouTargetItIsAFightToStepClearOf()
	{
		// The shape a real boss fight takes from the client's side: the player
		// is targeting it (one-way interaction - a boss between phases or at
		// range need never be seen facing back), it is landing hits, and its
		// health ratio can read as zero until it has taken damage. Play
		// report: a boss fight where the follower never stepped clear.
		NPC boss = game.spawnNpc(100, "Vorkath", 392);
		game.at(3222, 3218, 0);
		game.facing(boss);
		tick(1);
		assertFalse("targeting alone is not yet a fight", spectate.isSpectating());

		context.noteDamageTaken();
		tick(2);

		assertTrue("a hit while targeting the boss is the fight",
			spectate.isSpectating());
		assertTrue("and the follower steps clear", follower.stayingAt != null);
		assertTrue(spoke(TriggerEvent.Type.COMBAT_START));
	}

	@Test
	public void itStepsAwayFromTheThingBeingFoughtNotTowardsIt()
	{
		NPC target = fight("Goblin", 5);
		// Put the target well to the west; the follower should end up east.
		game.moveNpc(target, 3210, 3218, 0);
		tick(2);

		assertTrue("it never moved", follower.stayingAt != null);
		assertTrue("it stood between the player and the fight, which is the one"
				+ " place it must not be: " + follower.stayingAt,
			follower.stayingAt.getX() >= 3222);
	}

	@Test
	public void theFightEndingSendsItBackAndSaysSo()
	{
		fight("Goblin", 5);
		tick(2);
		assertTrue(spectate.isSpectating());

		game.fighting(null);
		tick(15);

		assertFalse("the fight is over", spectate.isSpectating());
		assertTrue("it should have said so", spoke(TriggerEvent.Type.COMBAT_END));
		assertTrue("and gone back to following", follower.following);
	}

	@Test
	public void beingBusyWithSomethingElseOutranksSpectating()
	{
		fight("Goblin", 5);
		tick(2);
		assertTrue(spectate.isSpectating());

		// An errand or thrall mode owns the feet.
		game.tick(++tick);
		context.refresh();
		follower.advance();
		spectate.tick(true);

		assertFalse("spectating must yield to whatever else has the follower",
			spectate.isSpectating());
	}

	@Test
	public void aDespawnedFollowerStopsSpectating()
	{
		fight("Goblin", 5);
		tick(2);

		follower.spawned = false;
		tick(2);

		assertFalse(spectate.isSpectating());
	}

	// ---------------------------------------------------------------- shield

	@Test
	public void anOrdinaryMonsterGetsNoWard()
	{
		fight("Goblin", 5);
		tick(20);

		assertTrue("a goblin does not warrant a protective spell",
			follower.chains.isEmpty());
		assertTrue("and nothing should have been put away", disarms.isEmpty());
	}

	@Test
	public void aBossGetsTheWholeSpellFromSummonToDispel()
	{
		fight("Zulrah", 725);
		tick(3);

		assertFalse("a boss should have raised a ward", follower.chains.isEmpty());
		assertEquals("the hands are emptied as the spell goes up",
			Boolean.TRUE, disarms.get(0));

		// Channelling: a looping pose is held, not a one-shot.
		tick(4);
		assertTrue("the channel pose was never taken", follower.poseOverride != 0);

		game.fighting(null);
		tick(20);

		assertEquals("the channel pose must be released at the end",
			0, follower.poseOverride);
		assertEquals("and the weapon handed back",
			Boolean.FALSE, disarms.get(disarms.size() - 1));
		assertTrue("it must end up following again", follower.following);
	}

	@Test
	public void theWeaponAlwaysComesBackHoweverTheFightEnds()
	{
		// Every way out of a fight, checked for the same thing: the follower
		// must not be left holding nothing.
		String[] endings = {"target lost", "busy", "despawned", "walked off"};
		for (String ending : endings)
		{
			setUpQuietly();
			fight("Zulrah", 725);
			tick(6);
			assertFalse(ending + ": the ward never went up", disarms.isEmpty());

			switch (ending)
			{
				case "target lost":
					game.fighting(null);
					tick(25);
					break;
				case "busy":
					for (int i = 0; i < 25; i++)
					{
						game.tick(++tick);
						context.refresh();
						follower.advance();
						spectate.tick(true);
					}
					break;
				case "despawned":
					follower.spawned = false;
					tick(25);
					break;
				default:
					follower.settled = false;
					tick(25);
					break;
			}

			assertEquals(ending + ": the follower was left disarmed",
				Boolean.FALSE, disarms.get(disarms.size() - 1));
		}
	}

	private void setUpQuietly()
	{
		try
		{
			setUp();
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	@Test
	public void walkingBreaksTheChannelRatherThanLeavingItStuck()
	{
		fight("Zulrah", 725);
		tick(6);
		assertTrue(follower.poseOverride != 0);

		// Dragged along behind the player for several ticks.
		follower.settled = false;
		tick(5);

		assertEquals("a broken channel must drop its pose", 0, follower.poseOverride);
		assertEquals("and give the weapon back straight away, since there is no"
				+ " closing animation left to protect",
			Boolean.FALSE, disarms.get(disarms.size() - 1));
	}

	@Test
	public void aMomentaryWobbleDoesNotEndTheSpell()
	{
		fight("Zulrah", 725);
		tick(6);
		int poseWhileChannelling = follower.poseOverride;
		assertTrue(poseWhileChannelling != 0);

		follower.settled = false;
		tick(1);
		follower.settled = true;
		tick(2);

		assertTrue("one unsettled tick should not have dropped the ward",
			follower.poseOverride != 0);
	}

	@Test
	public void theWardIsRenewedSoItDoesNotBlinkOut()
	{
		fight("Zulrah", 725);
		tick(3);
		int afterSummon = follower.spotAnims.size();

		tick(12);

		assertTrue("the channelled effect should be renewed as it fades,"
				+ " not left to lapse",
			follower.spotAnims.size() >= afterSummon);
	}

	@Test
	public void switchingItOffMidFightPutsEverythingBack()
	{
		FollowerConfig off = new FollowerConfig()
		{
			@Override
			public boolean spectateCombat()
			{
				return false;
			}
		};
		SpectateController disabled = new SpectateController(game.client, follower,
			off, () -> context, new SpotAnimRepository(new Gson()), spoken::add, disarms::add);

		fight("Zulrah", 725);
		for (int i = 0; i < 10; i++)
		{
			game.tick(++tick);
			context.refresh();
			follower.advance();
			disabled.tick(false);
		}

		assertFalse("the setting is off", disabled.isSpectating());
		assertTrue("nothing should have been taken away", disarms.isEmpty());
	}

	// ------------------------------------------------------------ diagnostics

	@Test
	public void describeExplainsItselfWithoutThrowing()
	{
		assertTrue(spectate.describe(false).contains("spectate"));
		fight("Zulrah", 725);
		tick(4);
		String busy = spectate.describe(true);
		assertTrue("the report should name what it is doing: " + busy,
			busy.contains("spectating=true"));
	}

	@Test
	public void aLongFightDoesNotAccumulateAnything()
	{
		fight("Zulrah", 725);
		tick(400);

		assertTrue("still spectating a fight that is still going",
			spectate.isSpectating());
		// One summon, and no repeats of it: the chain is raised once.
		assertTrue("the ward was raised " + follower.chains.size() + " times over"
				+ " one fight", follower.chains.size() <= 2);
	}
}

package com.follower.follower;

import com.follower.appearance.ModelRepository;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * How a weapon nobody has been seen holding gets an animation anyway.
 *
 * <p>This is the plugin's most consequential guesswork, and its failure mode is
 * silent: a wrong borrow gives a weapon somebody else's swing, which reads as a
 * bug in the follower rather than in a lookup table. The rules it follows were
 * measured, and each one is pinned here - including the refusals, which are the
 * half that stops the borrowing going too far.
 */
public class StanceInheritanceTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A model repository that knows only the names this test gives it. */
	private static final class Names extends ModelRepository
	{
		private final Map<Integer, String> names = new HashMap<>();

		Names()
		{
			super(new Gson());
		}

		Names name(int id, String name)
		{
			names.put(id, name);
			return this;
		}

		@Override
		public String itemName(int itemId)
		{
			return names.get(itemId);
		}
	}

	private Names names;
	private StanceLibrary library;

	/**
	 * Two invented pose classes and an item id range the game does not use.
	 *
	 * <p>{@link StanceLibrary#load} always reads the SHIPPED library first, so
	 * a test naming a real weapon is really testing the 191 stances that come
	 * with the plugin. Worse, real pose ids overlap the unarmed set, which
	 * would make "borrowed correctly" and "fell back to unarmed" look identical.
	 * Made-up numbers keep the question being asked an honest one.
	 */
	private static final int[] SCIMITAR = {900001, 900002, 900003};
	private static final int[] STAFF = {910001, 910002, 910003};

	/** Item ids well past anything the shipped library holds. */
	private static final int BASE = 800000;

	@Before
	public void setUp() throws IOException
	{
		names = new Names();
		library = new StanceLibrary(new Gson(), names);
		Path dir = folder.newFolder().toPath();
		library.load(dir);
	}

	private void observe(int itemId, String name, int[] poses, int attack)
	{
		names.name(itemId, name);
		library.setManual(itemId, poses[0], poses[1], poses[2], attack);
	}

	// --------------------------------------------------------- attack styles

	@Test
	public void theStyleTheWeaponWasSwungInWinsOverTheGenericSwing()
	{
		// Everyone in the scene teaches the generic swing; only the local
		// player can teach a styled one, because which style anyone else has
		// selected is not readable. So a weapon ends up with both, and the
		// styled slot is the better answer when there is one.
		observe(BASE + 40, "Dragon scimitar", SCIMITAR, 390);
		library.forWeapon(BASE + 40).attackByStyle = new int[]{0, 386, 0, 0};

		assertEquals("with no style asked for, the generic swing",
			390, library.attackFor(BASE + 40));
		assertEquals("the animation this weapon really uses in that style",
			386, library.attackFor(BASE + 40, 1));
		assertEquals("a style it has never been swung in falls back",
			390, library.attackFor(BASE + 40, 2));
	}

	@Test
	public void aStyleSlotIsNeverBorrowedFromAnotherWeapon()
	{
		// The generic swing borrows across a stance class; a styled one must
		// not. A style NUMBER means different things on different weapon
		// types, so another weapon's slot 1 is not this weapon's slot 1 - even
		// when the two are close enough to share a carry class and a swing.
		observe(BASE + 41, "Rune scimitar", SCIMITAR, 390);
		library.forWeapon(BASE + 41).attackByStyle = new int[]{0, 386, 0, 0};
		observe(BASE + 42, "Rune longsword", SCIMITAR, 390);

		assertEquals("it took the neighbour's styled animation",
			390, library.attackFor(BASE + 42, 1));
	}

	// -------------------------------------------------------------- variants

	@Test
	public void aTrimmedWeaponInheritsFromThePlainOne()
	{
		observe(BASE + 1, "Abyssal whip", SCIMITAR, 1658);
		names.name(BASE + 2, "Abyssal whip (or)");

		StanceLibrary.Stance inherited = library.forWeapon(BASE + 2);
		assertEquals("the ornamented whip should walk like the plain one",
			SCIMITAR[0], inherited.idle);
		assertTrue(library.knows(BASE + 2));
	}

	@Test
	public void aPoisonedDaggerInheritsFromThePlainOne()
	{
		observe(BASE + 3, "Dragon dagger", SCIMITAR, 376);
		names.name(BASE + 4, "Dragon dagger(p++)");
		assertEquals(SCIMITAR[0], library.forWeapon(BASE + 4).idle);
	}

	@Test
	public void aDegradedBarrowsWeaponInheritsFromTheFullOne()
	{
		observe(BASE + 5, "Dharok's greataxe", STAFF, 2067);
		names.name(BASE + 6, "Dharok's greataxe 25");
		assertEquals(STAFF[0], library.forWeapon(BASE + 6).idle);
	}

	@Test
	public void aWeaponWithTwoMarkersStillFindsItsPlainForm()
	{
		observe(BASE + 7, "Rune scimitar", SCIMITAR, 390);
		names.name(BASE + 8, "Rune scimitar (bh)(p++)");
		assertEquals(SCIMITAR[0], library.forWeapon(BASE + 8).idle);
	}

	// ------------------------------------------------------------ metal tiers

	@Test
	public void aDifferentMetalOfTheSameWeaponInherits()
	{
		observe(BASE + 9, "Black longsword", SCIMITAR, 390);
		names.name(BASE + 10, "Adamant longsword");
		assertEquals("adamant should walk like black", SCIMITAR[0],
			library.forWeapon(BASE + 10).idle);
	}

	/**
	 * Measured before it was adopted: the Dragon longsword animates at 809
	 * where the Black one animates at 808, so the ornamental tiers are excluded
	 * on purpose. A dragon weapon must fall back rather than borrow.
	 */
	@Test
	public void anOrnamentalTierDoesNotBorrowFromAPlainMetal()
	{
		observe(BASE + 9, "Black longsword", SCIMITAR, 390);
		names.name(BASE + 11, "Dragon longsword");

		StanceLibrary.Stance stance = library.forWeapon(BASE + 11);
		assertEquals("dragon must fall back to unarmed, not borrow from black",
			library.forWeapon(0).idle, stance.idle);
	}

	// ----------------------------------------------------------- the refusals

	@Test
	public void aDifferentWeaponSharingAWordDoesNotInherit()
	{
		observe(BASE + 12, "Dragon axe", SCIMITAR, 401);
		names.name(BASE + 13, "Dragon felling axe");

		assertEquals("a felling axe is not an axe with a marker on it",
			library.forWeapon(0).idle, library.forWeapon(BASE + 13).idle);
	}

	@Test
	public void aWeaponWithNoNameAtAllFallsBackQuietly()
	{
		StanceLibrary.Stance stance = library.forWeapon(999999);
		assertNotNull("an unknown weapon must still get something to walk with", stance);
		assertEquals(library.forWeapon(0).idle, stance.idle);
	}

	@Test
	public void unarmedIsAlwaysKnown()
	{
		assertTrue(library.knows(0));
		assertTrue("a negative id is unarmed too", library.knows(-1));
		assertNotNull(library.forWeapon(-1));
	}

	// -------------------------------------------------------- attack borrowing

	private StanceLibrary.StyleSource styles(Map<Integer, Integer> usage)
	{
		return itemId -> usage.getOrDefault(itemId, StanceLibrary.StyleSource.UNKNOWN);
	}

	@Test
	public void anUnseenWeaponBorrowsTheAttackItsClassAgreesOn()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);

		// Three scimitars seen swinging: two share the generic swing, one has a
		// signature of its own.
		observe(BASE + 14, "Steel scimitar", SCIMITAR, 390);
		observe(BASE + 15, "Mithril scimitar", SCIMITAR, 390);
		observe(BASE + 16, "Dragon scimitar", SCIMITAR, 12031);
		for (int id : new int[]{BASE + 14, BASE + 15, BASE + 16})
		{
			usage.put(id, melee);
		}

		// A fourth, never seen used, but in the same class and style.
		names.name(BASE + 17, "Adamant scimitar");
		library.setManual(BASE + 17, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 17, melee);
		library.setStyleSource(styles(usage));

		assertEquals("the attack the most of its class agree on", 390,
			library.attackFor(BASE + 17));
	}

	@Test
	public void aTieGoesToTheLowerItemIdSoItIsTheSameEverySession()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);

		// One vote each, so only the item id can separate them. The LOWER id is
		// the one that must win, whichever order they were entered in.
		int lower = BASE + 18;
		int higher = BASE + 19;
		observe(higher, "Alpha blade", SCIMITAR, 555);
		observe(lower, "Beta blade", SCIMITAR, 111);
		usage.put(higher, melee);
		usage.put(lower, melee);

		names.name(BASE + 20, "Gamma blade");
		library.setManual(BASE + 20, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 20, melee);
		library.setStyleSource(styles(usage));

		// The lower donor id breaks the tie, so the answer cannot depend on
		// hash order and change between sessions.
		int first = library.attackFor(BASE + 20);
		assertEquals(111, first);
		for (int i = 0; i < 20; i++)
		{
			assertEquals("the tie-break must be stable", first, library.attackFor(BASE + 20));
		}
	}

	@Test
	public void aBorrowNeverCrossesCombatStyles()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);
		int ranged = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.RANGED, false);

		// A harpoon and a bow can be CARRIED alike; they are not swung alike.
		observe(BASE + 21, "Harpoon", SCIMITAR, 390);
		usage.put(BASE + 21, melee);

		names.name(BASE + 22, "Shortbow");
		library.setManual(BASE + 22, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 22, ranged);
		library.setStyleSource(styles(usage));

		assertEquals("a bow must not borrow a melee swing", 0, library.attackFor(BASE + 22));
	}

	@Test
	public void aBorrowNeverCrossesHandedness()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int oneHanded = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.RANGED, false);
		int twoHanded = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.RANGED, true);

		observe(BASE + 23, "Bronze dart", SCIMITAR, 806);
		usage.put(BASE + 23, oneHanded);

		names.name(BASE + 22, "Shortbow");
		library.setManual(BASE + 22, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 22, twoHanded);
		library.setStyleSource(styles(usage));

		assertEquals("a thrown dart and a drawn bow are not the same motion",
			0, library.attackFor(BASE + 22));
	}

	@Test
	public void withNoStyleSourceNothingIsBorrowed()
	{
		observe(BASE + 14, "Steel scimitar", SCIMITAR, 390);
		names.name(BASE + 17, "Adamant scimitar");
		library.setManual(BASE + 17, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);

		assertEquals("without knowing the style, refuse rather than guess",
			0, library.attackFor(BASE + 17));
	}

	@Test
	public void aWeaponWithItsOwnAttackKeepsIt()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);
		observe(BASE + 14, "Steel scimitar", SCIMITAR, 390);
		observe(BASE + 16, "Dragon scimitar", SCIMITAR, 12031);
		usage.put(BASE + 14, melee);
		usage.put(BASE + 16, melee);
		library.setStyleSource(styles(usage));

		assertEquals("an observed attack always wins over a borrowed one",
			12031, library.attackFor(BASE + 16));
	}

	// ------------------------------------------------------------ persistence

	@Test
	public void whatIsLearnedSurvivesASaveAndReload() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		StanceLibrary first = new StanceLibrary(new Gson(), names);
		first.load(dir);
		names.name(BASE + 1, "Abyssal whip");
		first.setManual(4151, 808, 819, 824, 1658);
		first.save();

		StanceLibrary second = new StanceLibrary(new Gson(), names);
		second.load(dir);

		StanceLibrary.Stance stance = second.describe(4151);
		assertNotNull("the observation did not survive the round trip", stance);
		assertEquals(808, stance.idle);
		assertEquals(819, stance.walk);
		assertEquals(824, stance.run);
		assertEquals(1658, stance.attack);
	}

	@Test
	public void savingWithNothingLearnedDoesNotFail() throws IOException
	{
		StanceLibrary fresh = new StanceLibrary(new Gson(), names);
		fresh.load(folder.newFolder().toPath());
		fresh.save();
		fresh.save();
	}

	@Test
	public void theBundledLibraryLoadsAndCoversARealWeapon() throws IOException
	{
		// The shipped stances.json is what a new install starts from; if it
		// stopped loading, every weapon would quietly fall back to unarmed.
		StanceLibrary shipped = new StanceLibrary(new Gson(), names);
		shipped.load(folder.newFolder().toPath());
		assertTrue("the bundled library should hold hundreds of weapons",
			shipped.size() > 100);
	}

	@Test
	public void clearingLearnedAttacksKeepsHowEachWeaponIsCarried()
	{
		// The repair for a library that learned blocks as attacks: a shortbow
		// had filed the unarmed block as its swing, so the thrall flinched
		// instead of shooting. Only the attack is forgotten - the carry poses
		// come from the composition, not from a moment of combat, and losing
		// them would strip walk and idle from every weapon ever seen.
		observe(BASE + 40, "Rune scimitar", SCIMITAR, 424);
		assertEquals(424, library.attackFor(BASE + 40));

		library.clearLearnedAttacks();

		assertEquals("the block was still remembered as an attack",
			0, library.forWeapon(BASE + 40).attack);
		assertEquals("the weapon forgot how it is held, not just how it swings",
			SCIMITAR[0], library.forWeapon(BASE + 40).idle);
	}
}

package com.follower.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The two name reductions that decide which weapons may inherit an animation
 * from which.
 *
 * <p>Both are deliberately narrow, and the narrowness is the point: over-eager
 * matching hands a weapon the wrong stance, which looks worse than having no
 * stance at all. These cases are the ones that drove the current shape - the
 * markers the old whitelist missed, and the pairs that must NOT collapse.
 */
public class StanceNamingTest
{
	// -------------------------------------------------------------- baseName

	@Test
	public void ornamentAndPoisonMarkersAreStripped()
	{
		assertEquals("abyssal whip", StanceLibrary.baseName("Abyssal whip (or)"));
		assertEquals("dragon dagger", StanceLibrary.baseName("Dragon dagger(p++)"));
		assertEquals("dragon spear", StanceLibrary.baseName("Dragon spear(kp)"));
		assertEquals("granite maul", StanceLibrary.baseName("Granite maul (or)"));
	}

	@Test
	public void twoMarkersOnOneNameBothGo()
	{
		assertEquals("rune scimitar", StanceLibrary.baseName("Rune scimitar (bh)(p++)"));
	}

	@Test
	public void wearAndChargeCountsAreStripped()
	{
		assertEquals("dharok's greataxe", StanceLibrary.baseName("Dharok's greataxe 25"));
		assertEquals("dharok's greataxe", StanceLibrary.baseName("Dharok's greataxe 100"));
		assertEquals("enchanted lyre", StanceLibrary.baseName("Enchanted lyre(2)"));
	}

	@Test
	public void differentWeaponsThatMerelyShareAWordStayApart()
	{
		// The reason the match stays exact on what is left: these two are not
		// the same weapon and must never share a stance.
		assertEquals("toxic staff", StanceLibrary.baseName("Toxic staff (uncharged)"));
		assertEquals("toxic staff of the dead",
			StanceLibrary.baseName("Toxic staff of the dead"));
	}

	@Test
	public void junkNamesReduceToNothingRatherThanToAKey()
	{
		assertNull(StanceLibrary.baseName(null));
		assertNull(StanceLibrary.baseName(""));
		assertNull(StanceLibrary.baseName("null"));
		assertNull("a name that is only a marker must not become a group",
			StanceLibrary.baseName("(or)"));
	}

	// ---------------------------------------------------------- tierBaseName

	@Test
	public void plainMetalTiersCollapseTogether()
	{
		assertEquals("longsword", StanceLibrary.tierBaseName("Adamant longsword"));
		assertEquals("longsword", StanceLibrary.tierBaseName("Black longsword"));
		assertEquals("longsword", StanceLibrary.tierBaseName("Rune longsword"));
		assertEquals("scimitar", StanceLibrary.tierBaseName("Mithril scimitar"));
	}

	@Test
	public void tierStrippingRunsAfterMarkerStripping()
	{
		assertEquals("scimitar", StanceLibrary.tierBaseName("Rune scimitar (bh)"));
	}

	/**
	 * Measured, not assumed: the Dragon longsword animates at 809 where the
	 * Black longsword animates at 808, so the ornamental tiers are excluded on
	 * purpose. If this test ever goes green, the exclusion has been lost.
	 */
	@Test
	public void ornamentalTiersAreNotTreatedAsPlainMetal()
	{
		assertNull(StanceLibrary.tierBaseName("Dragon longsword"));
		assertNull(StanceLibrary.tierBaseName("Crystal halberd"));
		assertNull(StanceLibrary.tierBaseName("Gilded scimitar"));
		assertNull(StanceLibrary.tierBaseName("3rd age longsword"));
	}

	@Test
	public void anUntieredWeaponNeverJoinsATierGroup()
	{
		assertNull("nothing to strip means no group at all",
			StanceLibrary.tierBaseName("Abyssal whip"));
		assertNull(StanceLibrary.tierBaseName("Toktz-xil-ak"));
	}

	@Test
	public void aTierWordOnItsOwnIsNotAWeapon()
	{
		assertNull(StanceLibrary.tierBaseName("Rune"));
		assertNull(StanceLibrary.tierBaseName("Bronze "));
	}

	@Test
	public void aTierWordInsideANameIsNotAPrefix()
	{
		// "Black" here is part of the noun, and the pattern is anchored so it
		// cannot be mistaken for a tier.
		assertEquals("mask", StanceLibrary.tierBaseName("Black mask"));
		assertNull(StanceLibrary.tierBaseName("Ancient staff"));
	}
}

package com.follower.follower;

import com.follower.sim.FakeGame;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The follower must never walk through a wall.
 *
 * <p>Everything else about it is an illusion held up by obeying the same rules
 * as everything else in the world. A model sliding through stone does not look
 * like a bug in the pathing, it looks like the whole thing is fake - which it
 * is, and the point is that you should not be able to tell.
 *
 * <p>The greedy stepper used to end with a raw step "so missing collision data
 * never freezes the follower". But no data already reads as open, so that
 * branch only ever fired when collision was PRESENT and said no. Indoors, where
 * the player is often two tiles away through a partition, it fired constantly.
 */
public class WallPathingTest
{
	private FollowerEntity followerOn(FakeGame game)
	{
		return new FollowerEntity(game.client, null);
	}

	@Test
	public void aWallStopsTheGreedyStepper()
	{
		// Standing at (10,10) wanting (12,10), with a wall on the east edge of
		// (10,10). There is no legal step east, so there is no step at all.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		FollowerEntity follower = followerOn(game);

		WorldPoint from = new WorldPoint(10, 10, 0);
		assertFalse("the wall has to be readable at all",
			follower.canStep(from, 1, 0));
		assertNull("the follower must not step through it",
			follower.stepToward(from, new WorldPoint(12, 10, 0), false));
	}

	@Test
	public void itStepsRoundTheWallWhenThereIsAWayRound()
	{
		// The same wall, but the target is up and to the right, so the stepper
		// has a legal diagonal-turned-cardinal to take instead of giving up.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		FollowerEntity follower = followerOn(game);

		WorldPoint step = follower.stepToward(
			new WorldPoint(10, 10, 0), new WorldPoint(12, 14, 0), false);
		assertNotNull("blocked one way is not blocked every way", step);
		assertTrue("and whatever it picked has to be legal",
			follower.canStep(new WorldPoint(10, 10, 0),
				step.getX() - 10, step.getY() - 10));
	}

	@Test
	public void retracingThePlayersOwnPathMayStepAnyway()
	{
		// The one place the raw step survives. These tiles were walked by the
		// player a moment ago, so a collision reading that disagrees is the
		// reading that is wrong, and refusing would leave the follow tile
		// unknown - which is worse than trusting the footprints.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		FollowerEntity follower = followerOn(game);

		assertNotNull("the player's own path is always walkable",
			follower.stepToward(new WorldPoint(10, 10, 0),
				new WorldPoint(12, 10, 0), true));
	}

	@Test
	public void aFullyBlockedTileIsNeverSteppedOnto()
	{
		FakeGame game = new FakeGame().withCollision();
		game.blockTile(11, 10);
		FollowerEntity follower = followerOn(game);

		WorldPoint from = new WorldPoint(10, 10, 0);
		assertFalse(follower.canStep(from, 1, 0));
		assertNull("a solid tile is not a step",
			follower.stepToward(from, new WorldPoint(11, 10, 0), false));
	}

	@Test
	public void noCollisionDataStillReadsAsOpen()
	{
		// An instance edge, or a scene that has not loaded. Refusing here would
		// freeze the follower for a reason that is not a wall - which is what
		// the raw fallback was originally defending against, and it is already
		// handled without it.
		FakeGame game = new FakeGame();
		FollowerEntity follower = followerOn(game);

		WorldPoint from = new WorldPoint(10, 10, 0);
		assertTrue("no data means no obstacle", follower.canStep(from, 1, 0));
		assertNotNull("so the follower still moves",
			follower.stepToward(from, new WorldPoint(12, 10, 0), false));
	}

	@Test
	public void aWallIsSeenFromBothSides()
	{
		// The game stores a wall on one tile's edge; the tile on the other side
		// carries the opposite bit for the same edge. Checking only the near
		// side would let the follower through half of every wall in the game.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(11, 10, CollisionDataFlag.BLOCK_MOVEMENT_WEST);
		FollowerEntity follower = followerOn(game);

		assertFalse("approaching from the west",
			follower.canStep(new WorldPoint(10, 10, 0), 1, 0));
		assertFalse("and from the east",
			follower.canStep(new WorldPoint(11, 10, 0), -1, 0));
	}

	@Test
	public void aDiagonalCannotSlipPastACornerPost()
	{
		// Cutting a corner diagonally past two walls that meet is the classic
		// way through a building, and it is exactly what the game forbids.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_NORTH);
		FollowerEntity follower = followerOn(game);

		assertFalse("the corner is shut",
			follower.canStep(new WorldPoint(10, 10, 0), 1, 1));
	}

	// ------------------------------------------------------------- teleports

	/**
	 * Walking obeys the walls; snapping used to ignore them entirely.
	 *
	 * <p>Every teleport, plane change and scene recovery put the follower one
	 * step west of the player by arithmetic alone, and arithmetic does not
	 * know about stone. Play report: the follower teleporting onto tiles it
	 * could not stand on.
	 */
	@Test
	public void aSnapNeverLandsSomewhereItCouldNotWalkTo()
	{
		FakeGame game = new FakeGame().withCollision();
		// The tile a snap wants - one west of the player - is solid.
		game.wallAt(9, 10, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
		FollowerEntity follower = followerOn(game);

		WorldPoint player = new WorldPoint(10, 10, 0);
		WorldPoint wanted = new WorldPoint(9, 10, 0);
		WorldPoint landing = follower.landingTile(wanted, player);

		assertFalse("it landed inside the scenery it was told to land in",
			wanted.equals(landing));
		// Not necessarily adjacent - going round the blocked tile can cost two
		// steps - but it must be somewhere connected to the player rather than
		// a hole on the far side of a wall.
		assertNotNull("whatever it chose has to be walkable ground",
			follower.stepToward(landing, player, false));
	}

	@Test
	public void aTileAThrallCanStandOnIsNotAlwaysOneTheFollowerCan()
	{
		// The gap that outlives possession. A thrall stands behind counters,
		// over water and inside scenery quite legally, and while possessed the
		// follower copies it exactly - correctly, because it IS the thrall.
		// The moment that ends, the same tile is just somewhere it cannot be,
		// so ending the hold there had to stop being unconditional.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(12, 12, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
		FollowerEntity follower = followerOn(game);

		assertFalse("a solid tile is not somewhere to be left standing",
			follower.standable(new WorldPoint(12, 12, 0)));
		assertTrue("and open ground still is",
			follower.standable(new WorldPoint(10, 10, 0)));
	}

	@Test
	public void aPlayerBoxedInGetsTheirOwnTileShared()
	{
		// Nowhere legal at all: standing on top of the player for a moment is
		// a far smaller lie than standing inside a wall, and their tile is
		// standable by definition because they are standing on it.
		FakeGame game = new FakeGame().withCollision();
		for (int dx = -2; dx <= 2; dx++)
		{
			for (int dy = -2; dy <= 2; dy++)
			{
				if (dx == 0 && dy == 0)
				{
					continue;
				}
				game.wallAt(10 + dx, 10 + dy, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
			}
		}
		FollowerEntity follower = followerOn(game);

		WorldPoint player = new WorldPoint(10, 10, 0);
		assertEquals("with nowhere else to go it must share the player's tile",
			player,
			follower.landingTile(new WorldPoint(9, 10, 0), player));
	}
}

package com.follower.follower;

import java.lang.reflect.Proxy;
import java.util.Arrays;
import java.util.function.BiFunction;
import java.util.function.IntPredicate;
import java.util.function.IntSupplier;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Where the loop-wrap lerp writes its blend.
 *
 * <p>The client hands every animated frame to the renderer in one shared
 * per-frame temp, and the base controller returns that temp, so the lerp writes
 * into it the same way. But a frame with no transform can come back as the
 * follower's base model itself, or as a model sharing its vertex arrays, and a
 * write there would bend the base for good. These pin both halves: the blend
 * lands in the temp, and the base is never written. Nor is a temp posed from a
 * model the snapshotted endpoints no longer fit.
 */
public class WrapLerpControllerTest
{
	private static final int FRAMES = 3;
	private static final int FRAME_LENGTH = 4;
	private static final int VERTICES = 5;

	private static final float BASE = 1f;
	private static final float LAST_POSE = 10f;
	private static final float LOOP_POSE = 20f;
	private static final float OTHER_POSE = 30f;

	private Model base;
	/** The client's shared per-frame temp: one set of arrays, reposed every call. */
	private Model temp;
	/** How many vertices the temp holds: as many as the model last posed into it. */
	private int tempCount;
	/** What the render-time call hands back instead of the temp, or null for the temp. */
	private Model renderReturns;

	private Client client;
	private Animation animation;

	@Before
	public void setUp()
	{
		base = model(filled(BASE), filled(BASE), filled(BASE));
		temp = model(new float[VERTICES], new float[VERTICES], new float[VERTICES], () -> tempCount);
		client = fake(Client.class, (name, args) ->
		{
			switch (name)
			{
				case "getAnimationInterpolationFilter":
					return (IntPredicate) id -> true;
				case "applyTransformations":
					return transform((Model) args[0], (int) args[2]);
				default:
					throw new UnsupportedOperationException(name);
			}
		});
		animation = fake(Animation.class, (name, args) ->
		{
			switch (name)
			{
				case "getId":
					return 808;
				case "isMayaAnim":
					return false;
				case "getFrameLengths":
					int[] lengths = new int[FRAMES];
					Arrays.fill(lengths, FRAME_LENGTH);
					return lengths;
				case "getFrameStep":
					return -1;
				case "getDuration":
					return FRAMES;
				default:
					throw new UnsupportedOperationException(name);
			}
		});
	}

	@Test
	public void blendLandsInTheRenderTemp()
	{
		WrapLerpController controller = onFinalFrame();
		Model drawn = controller.animate(base, null);

		assertSame("the lerp returns the client's own temp", temp, drawn);
		float halfway = (LAST_POSE + LOOP_POSE) / 2;
		assertArrayEquals(filled(halfway), drawn.getVerticesX(), 0f);
		assertArrayEquals(filled(halfway), drawn.getVerticesY(), 0f);
		assertArrayEquals(filled(halfway), drawn.getVerticesZ(), 0f);
		assertBaseUntouched();
		assertFalse(controller.isDisabled());
	}

	@Test
	public void neverWritesTheBaseWhenTheTempIsTheBase()
	{
		renderReturns = base;
		WrapLerpController controller = onFinalFrame();

		assertSame(base, controller.animate(base, null));
		assertBaseUntouched();
		assertTrue("the measured wrap trim takes over", controller.isDisabled());
	}

	@Test
	public void neverWritesTheBaseThroughSharedArrays()
	{
		Model alias = model(base.getVerticesX(), base.getVerticesY(), base.getVerticesZ());
		renderReturns = alias;
		WrapLerpController controller = onFinalFrame();

		assertSame(alias, controller.animate(base, null));
		assertBaseUntouched();
		assertTrue("the measured wrap trim takes over", controller.isDisabled());
	}

	@Test
	public void aModelThatNoLongerMatchesTheEndpointsSwitchesTheLerpOff()
	{
		WrapLerpController controller = onFinalFrame();
		controller.animate(base, null);

		// A different model under the same animation: the endpoints were taken from
		// the base, and blending them into this one would scramble it.
		Model smaller = model(new float[2], new float[2], new float[2]);
		Model drawn = controller.animate(smaller, null);

		assertSame(temp, drawn);
		assertEquals("posed by the client, not blended", LAST_POSE, drawn.getVerticesX()[0], 0f);
		assertBaseUntouched();
		assertTrue("the measured wrap trim takes over", controller.isDisabled());
	}

	/** Halfway through the final frame, so the blend differs from both endpoints. */
	private WrapLerpController onFinalFrame()
	{
		WrapLerpController controller = new WrapLerpController(client, animation);
		controller.setFrame(FRAMES - 1);
		controller.tick(FRAME_LENGTH / 2);
		return controller;
	}

	/**
	 * Stands in for Client#applyTransformations. The endpoint snapshots ask with a
	 * plain frame index; the render call arrives packed (high bit set while
	 * smoothing accepts the animation), which is where a test swaps in the base or
	 * an alias of it.
	 */
	private Model transform(Model posed, int frame)
	{
		if (frame < 0 && renderReturns != null)
		{
			return renderReturns;
		}
		int index = frame & 0xFFFF;
		float pose = index == FRAMES - 1 ? LAST_POSE : index == 0 ? LOOP_POSE : OTHER_POSE;
		tempCount = posed.getVerticesCount();
		Arrays.fill(temp.getVerticesX(), 0, tempCount, pose);
		Arrays.fill(temp.getVerticesY(), 0, tempCount, pose);
		Arrays.fill(temp.getVerticesZ(), 0, tempCount, pose);
		return temp;
	}

	private void assertBaseUntouched()
	{
		assertArrayEquals("base x", filled(BASE), base.getVerticesX(), 0f);
		assertArrayEquals("base y", filled(BASE), base.getVerticesY(), 0f);
		assertArrayEquals("base z", filled(BASE), base.getVerticesZ(), 0f);
	}

	private static float[] filled(float value)
	{
		float[] out = new float[VERTICES];
		Arrays.fill(out, value);
		return out;
	}

	private static Model model(float[] x, float[] y, float[] z)
	{
		return model(x, y, z, () -> x.length);
	}

	private static Model model(float[] x, float[] y, float[] z, IntSupplier count)
	{
		return fake(Model.class, (name, args) ->
		{
			switch (name)
			{
				case "getVerticesCount":
					return count.getAsInt();
				case "getVerticesX":
					return x;
				case "getVerticesY":
					return y;
				case "getVerticesZ":
					return z;
				default:
					throw new UnsupportedOperationException(name);
			}
		});
	}

	/** Answers only what the lerp should ask; anything else fails loudly. */
	@SuppressWarnings("unchecked")
	private static <T> T fake(Class<T> type, BiFunction<String, Object[], Object> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "equals":
						return proxy == args[0];
					case "hashCode":
						return System.identityHashCode(proxy);
					case "toString":
						return type.getSimpleName() + "@fake";
					default:
						return answers.apply(method.getName(), args);
				}
			});
	}
}

package com.follower.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The wrap trims, and the file they live in.
 *
 * <p>A trim is how many frames to cut off the end of a looping animation, so
 * the follower's loop wraps where the player's does. They are MEASURED over a
 * session and written out, which means the file is the only thing keeping work
 * the plugin did once - and it was the last of the plugin's stores with no test.
 *
 * <p>Two kinds live in it and the difference matters: measured values the
 * plugin worked out, and manual ones somebody set by hand with
 * {@code ::follower wrapearly}. Merging them the wrong way round would have a
 * measurement quietly overwrite a deliberate override.
 */
public class WrapTrimStoreTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The entity only has to hold two maps here; nothing touches a client. */
	private static FollowerEntity bareFollower()
	{
		return new FollowerEntity(null, null);
	}

	@Test
	public void trimsSurviveASaveAndLoad()
	{
		Path dir = folderPath();
		FollowerEntity saved = bareFollower();

		Map<Integer, Integer> manual = new HashMap<>();
		manual.put(808, 3);
		Map<Integer, Integer> measured = new HashMap<>();
		measured.put(819, 5);
		measured.put(824, 1);
		saved.restoreTrims(manual, measured);

		WrapTrimStore store = new WrapTrimStore(new Gson());
		store.load(dir, saved);
		store.save(saved);

		FollowerEntity reloaded = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, reloaded);

		assertEquals("the hand-set trim came back", Integer.valueOf(3),
			reloaded.getWrapTrims().get(808));
		assertEquals("and both measured ones", Integer.valueOf(5),
			reloaded.getMeasuredTrims().get(819));
		assertEquals(Integer.valueOf(1), reloaded.getMeasuredTrims().get(824));
	}

	@Test
	public void aMeasurementNeverOverwritesAHandSetTrim()
	{
		// The two maps are separate for exactly this reason: a manual trim is
		// somebody deciding, a measurement is the plugin guessing. Round-trip
		// them together and the manual one has to still be manual.
		Path dir = folderPath();
		FollowerEntity follower = bareFollower();

		Map<Integer, Integer> manual = new HashMap<>();
		manual.put(808, 3);
		Map<Integer, Integer> measured = new HashMap<>();
		measured.put(808, 9);
		follower.restoreTrims(manual, measured);

		WrapTrimStore store = new WrapTrimStore(new Gson());
		store.load(dir, follower);
		store.save(follower);

		FollowerEntity reloaded = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, reloaded);

		assertEquals("the same animation is in both maps and they must not merge",
			Integer.valueOf(3), reloaded.getWrapTrims().get(808));
		assertEquals(Integer.valueOf(9), reloaded.getMeasuredTrims().get(808));
	}

	@Test
	public void nothingLearnedWritesNoFileAtAll()
	{
		// A fresh install should not litter the data directory with an empty
		// object, and an empty file is one more thing the loader has to
		// survive on the next start.
		Path dir = folderPath();
		WrapTrimStore store = new WrapTrimStore(new Gson());
		FollowerEntity follower = bareFollower();

		store.load(dir, follower);
		store.save(follower);

		assertFalse("an empty store wrote a file anyway",
			Files.exists(dir.resolve(WrapTrimStore.FILE_NAME)));
	}

	@Test
	public void aMissingFileIsAFreshStartRatherThanAFailure()
	{
		FollowerEntity follower = bareFollower();
		new WrapTrimStore(new Gson()).load(folderPath(), follower);

		assertTrue("nothing to load is not an error", follower.getWrapTrims().isEmpty());
		assertTrue(follower.getMeasuredTrims().isEmpty());
	}

	@Test
	public void aCorruptFileLeavesTheFollowerUsableRatherThanThrowing()
	{
		// This runs during startup. Throwing here would take the plugin down
		// over a file whose only job is to save re-measuring some animations.
		Path dir = folderPath();
		write(dir.resolve(WrapTrimStore.FILE_NAME), "{ this is not json");

		FollowerEntity follower = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, follower);

		assertTrue("a bad file must leave empty trims, not half-read ones",
			follower.getWrapTrims().isEmpty());
	}

	@Test
	public void anEmptyFileIsSurvivedToo()
	{
		Path dir = folderPath();
		write(dir.resolve(WrapTrimStore.FILE_NAME), "");

		FollowerEntity follower = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, follower);

		assertTrue(follower.getWrapTrims().isEmpty());
	}

	@Test
	public void savingWithoutLoadingFirstDoesNothing()
	{
		// save() has nowhere to write until load() has told it where the data
		// directory is. Guessing would put the file somewhere unexpected.
		FollowerEntity follower = bareFollower();
		Map<Integer, Integer> manual = new HashMap<>();
		manual.put(808, 3);
		follower.restoreTrims(manual, null);

		new WrapTrimStore(new Gson()).save(follower);
		// The assertion is that this returned quietly rather than throwing at
		// a null path; there is nowhere to look for a file it never named.
	}

	// ------------------------------------------------------------- plumbing

	private Path folderPath()
	{
		try
		{
			return folder.newFolder().toPath();
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	private static void write(Path file, String contents)
	{
		try
		{
			Files.createDirectories(file.getParent());
			Files.write(file, contents.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}
}

package com.follower.sim;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * A game that is not running, good enough to evaluate rules against.
 *
 * <p>The speech engine only ever asks the client a couple of dozen questions -
 * skill levels, where the player is, what is nearby - so the whole client can
 * be a dynamic proxy that answers from a map and returns harmless defaults for
 * everything else. That is worth far more than mocking each interface by hand:
 * {@link Client} has hundreds of methods and only the answers matter here.
 *
 * <p>Defaults are chosen to be the LEAST eventful reading possible - full
 * health, no gear, nothing nearby, standing still - so a test that does not
 * mention a thing gets a quiet game rather than an accidental trigger.
 */
public final class FakeGame
{
	/**
	 * An answer to one method call. Given the call's arguments so that readings
	 * keyed by an id - varbits, varplayers, skill levels - can differ per id
	 * rather than all sharing one value.
	 */
	private interface Answer
	{
		Object get(Object[] args);
	}

	private final Map<String, Object> clientAnswers = new HashMap<>();
	private final Map<String, Object> playerAnswers = new HashMap<>();
	private final List<NPC> npcs = new ArrayList<>();
	/** Each NPC's answer map, so a spawned one can still be moved about. */
	private final Map<NPC, Map<String, Object>> npcAnswers = new HashMap<>();

	private final Map<Integer, Integer> varbits = new HashMap<>();
	private final Map<Integer, Integer> varps = new HashMap<>();
	private final Map<Skill, int[]> skillLevels = new HashMap<>();

	private int[] mapRegions = {12850};
	private int[] equipment = new int[12];

	private final List<Player> others = new ArrayList<>();

	/** Null until a test says otherwise: the container is not always loaded. */
	private Item[] inventory;

	/**
	 * Collision flags by scene tile, or null for "no data" - which the follower
	 * reads as open, the same way it does at an instance edge.
	 */
	private int[][] collisionFlags;

	public final Client client;
	public final Player player;

	public FakeGame()
	{
		player = proxy(Player.class, playerAnswers);
		client = proxy(Client.class, clientAnswers);

		// A healthy, unremarkable player standing in Lumbridge doing nothing.
		playerAnswers.put("getName", "Tester");
		playerAnswers.put("getWorldLocation", new WorldPoint(3222, 3218, 0));
		playerAnswers.put("getAnimation", -1);
		playerAnswers.put("getSkullIcon", -1);
		playerAnswers.put("getInteracting", null);
		playerAnswers.put("getHealthRatio", -1);
		playerAnswers.put("getCombatLevel", 0);
		playerAnswers.put("getPlayerComposition", composition());

		clientAnswers.put("getLocalPlayer", player);
		clientAnswers.put("getEnergy", 10000);
		clientAnswers.put("getTickCount", 0);
		WorldView view = worldView();
		clientAnswers.put("getTopLevelWorldView", view);
		clientAnswers.put("getWorldView", (Answer) args -> view);
		clientAnswers.put("findWorldViewFromWorldPoint", (Answer) args -> view);

		// Keyed readings: everything unset reads as the quiet default.
		clientAnswers.put("getVarbitValue",
			(Answer) args -> varbits.getOrDefault((Integer) args[0], 0));
		clientAnswers.put("getVarpValue",
			(Answer) args -> varps.getOrDefault((Integer) args[0], 0));
		clientAnswers.put("getBoostedSkillLevel", (Answer) args -> levels(args[0])[0]);
		clientAnswers.put("getRealSkillLevel", (Answer) args -> levels(args[0])[1]);
		clientAnswers.put("getItemContainer",
			(Answer) args -> inventory == null ? null : inventoryContainer());

		// The camera is how the follower tells "gone" from "standing still on
		// purpose", so a test needs to be able to move it and leave it.
		clientAnswers.put("getCameraX", 0);
		clientAnswers.put("getCameraY", 0);
		clientAnswers.put("getCameraPitch", 128);

		clientAnswers.put("getObjectDefinition", (Answer) args ->
		{
			String name = objectNames.get((Integer) args[0]);
			if (name == null)
			{
				return null;
			}
			Map<String, Object> answers = new HashMap<>();
			answers.put("getName", name);
			answers.put("getImpostorIds", null);
			return proxy(net.runelite.api.ObjectComposition.class, answers);
		});
	}

	private int[] levels(Object skill)
	{
		return skillLevels.getOrDefault(skill, DEFAULT_LEVELS);
	}

	private static final int[] DEFAULT_LEVELS = {99, 99};

	// ------------------------------------------------------------------ setup

	public FakeGame tick(int tickCount)
	{
		clientAnswers.put("getTickCount", tickCount);
		return this;
	}

	/** Nudges the camera, which is what somebody being at the keyboard looks like. */
	public FakeGame cameraMoved()
	{
		clientAnswers.put("getCameraX",
			((Integer) clientAnswers.get("getCameraX")) + 64);
		return this;
	}

	public FakeGame at(int x, int y, int plane)
	{
		playerAnswers.put("getWorldLocation", new WorldPoint(x, y, plane));
		// Scene base is 0 here, so scene coords equal world coords. Only
		// meaningful for tests that keep their coordinates inside the
		// 104-tile scene.
		playerAnswers.put("getLocalLocation",
			net.runelite.api.coords.LocalPoint.fromWorld(proxyScene(), x, y));
		return this;
	}

	/** Scene objects by tile, keyed plane:x:y; see {@link #placeObject}. */
	private final Map<String, List<net.runelite.api.GameObject>> placedObjects = new HashMap<>();
	private final Map<Integer, String> objectNames = new HashMap<>();

	/**
	 * Puts a named object into the scene, the way the errand scanner sees one.
	 * The scene base is 0, so world coordinates must stay under the 104-tile
	 * scene size for the object to be inside the tile grid at all.
	 */
	public FakeGame placeObject(int id, String name, int x, int y, int plane)
	{
		objectNames.put(id, name);
		Map<String, Object> answers = new HashMap<>();
		answers.put("getId", id);
		answers.put("getWorldLocation", new WorldPoint(x, y, plane));
		placedObjects
			.computeIfAbsent(plane + ":" + x + ":" + y, k -> new ArrayList<>())
			.add(proxy(net.runelite.api.GameObject.class, answers));
		return this;
	}

	public FakeGame animating(int id)
	{
		playerAnswers.put("getAnimation", id);
		return this;
	}

	/** Hitpoints as a level pair; the context turns them into a percentage. */
	public FakeGame hitpoints(int current, int max)
	{
		skillLevels.put(Skill.HITPOINTS, new int[]{current, max});
		return this;
	}

	/** No local player, as between the login screen and the world loading. */
	public FakeGame loggedOut()
