		mapRegions = regions;
		return this;
	}

	/** Worn item ids, in the composition's raw encoding. */
	public FakeGame wearing(int... itemIds)
	{
		equipment = new int[Math.max(12, itemIds.length)];
		for (int i = 0; i < itemIds.length; i++)
		{
