		return this;
	}

	/**
	 * Fills the inventory with that many occupied slots. What is in them does
	 * not matter: only how many slots are left.
	 */
	public FakeGame inventoryUsing(int slots)
	{
		// Item is a final class rather than an interface, so this is the real
		// thing rather than a proxy - which is better anyway.
		inventory = new Item[28];
		for (int i = 0; i < inventory.length; i++)
		{
			inventory[i] = i < slots ? new Item(1511, 1) : new Item(-1, 0);
		}
		return this;
	}

	/** No inventory container at all, as in the first ticks after login. */
	public FakeGame noInventory()
	{
		inventory = null;
		return this;
	}

	/** An inventory holding exactly these item ids, one of each. */
	public FakeGame inventoryContaining(int... ids)
	{
		inventory = new Item[28];
		for (int i = 0; i < inventory.length; i++)
		{
			inventory[i] = i < ids.length ? new Item(ids[i], 1) : new Item(-1, 0);
		}
		return this;
	}

	/**
	 * Turns collision data on, everything open. Until this is called the scene
	 * has no collision map at all, which is the "off-scene" reading.
	 */
	public FakeGame withCollision()
	{
		collisionFlags = new int[net.runelite.api.Perspective.SCENE_SIZE]
			[net.runelite.api.Perspective.SCENE_SIZE];
		return this;
	}

	/**
	 * Adds a wall on one edge of a world tile. The flag names the side of the
	 * tile it sits on, so a wall between two tiles has to be declared from one
	 * of them - exactly as the game stores it.
	 */
	public FakeGame wallAt(int x, int y, int flag)
	{
		if (collisionFlags == null)
		{
			withCollision();
		}
		collisionFlags[x][y] |= flag;
		return this;
	}

	/** Blocks a whole tile, the way a solid object does. */
	public FakeGame blockTile(int x, int y)
	{
		return wallAt(x, y, net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_FULL);
	}

	/** A varbit reading, by id. Unset varbits read zero. */
	public FakeGame varbit(int id, int value)
	{
		varbits.put(id, value);
		return this;
	}

	/** A varplayer reading, by id. This is where poison and venom live. */
	public FakeGame varp(int id, int value)
	{
		varps.put(id, value);
		return this;
	}

	public FakeGame skulled(boolean skulled)
	{
		playerAnswers.put("getSkullIcon", skulled ? 0 : -1);
		return this;
	}

	/** Prayer points, which the context also uses to decide if prayer is draining. */
	public FakeGame prayer(int current, int max)
	{
		skillLevels.put(Skill.PRAYER, new int[]{current, max});
		return this;
	}

	/** Moves an NPC that is already in the scene. */
	public FakeGame moveNpc(NPC npc, int x, int y, int plane)
	{
		npcAnswers.get(npc).put("getWorldLocation", new WorldPoint(x, y, plane));
		return this;
	}

	/**
	 * A real fight: both sides squared up at each other.
	 *
	 * <p>This used to set only the player's side, on the reasoning that
	 * interacting with an NPC is what combat looks like. It is also what
	 * walking up to a guard for directions looks like, and what trading and
	 * talking look like - so the context could not tell them apart and called
	 * all of them a fight. Now that it needs evidence, the harness has to model
	 * the evidence: a fight has two sides.
	 */
	public FakeGame fighting(NPC target)
	{
		playerAnswers.put("getInteracting", target);
		if (target != null)
		{
			// null is how a test says the target is gone.
			npcAnswers.get(target).put("getInteracting", player);
		}
		return this;
	}

	/**
	 * Facing an NPC without fighting it - walking over to talk, to trade, or
	 * to rob it. One-way interaction, which is precisely the case that used to
	 * be indistinguishable from combat.
	 */
	public FakeGame facing(NPC target)
	{
		playerAnswers.put("getInteracting", target);
		return this;
	}

	// ---------------------------------------------------------------- plumbing

	private PlayerComposition composition()
	{
		Map<String, Object> answers = new HashMap<>();
		answers.put("getEquipmentIds", (Answer) args -> equipment);
		return proxy(PlayerComposition.class, answers);
	}

	private WorldView worldView()
	{
		Map<String, Object> answers = new HashMap<>();
		answers.put("getMapRegions", (Answer) args -> mapRegions);
		answers.put("getBaseX", (Answer) args -> 0);
		answers.put("getBaseY", (Answer) args -> 0);
		answers.put("getSizeX", (Answer) args -> net.runelite.api.Perspective.SCENE_SIZE);
		answers.put("getSizeY", (Answer) args -> net.runelite.api.Perspective.SCENE_SIZE);
		answers.put("isInstance", (Answer) args -> false);
		answers.put("getCollisionMaps", (Answer) args -> collisionFlags == null
			? null
			: new CollisionData[]{proxyCollision(), proxyCollision(),
				proxyCollision(), proxyCollision()});
		// hasLineOfSightTo reads the scene's tiles for bridge handling; a grid
		// of nulls is honest for a fake with no bridges, where a null SCENE is
		// a NullPointerException that the engine's rule guard then swallows -
		// the throwing rule gets disabled and the test fails by silence.
		answers.put("getScene", (Answer) args -> proxyScene());
		answers.put("npcs", (Answer) args -> indexed(npcs));
		// The local player is in the real list too, so the crowd count has to
		// exclude it by identity - which is exactly what it does.
		answers.put("players", (Answer) args ->
		{
			List<Player> all = new ArrayList<>(others);
			all.add(player);
			return indexed(all);
		});
		return proxy(WorldView.class, answers);
	}

	private CollisionData proxyCollision()
	{
		Map<String, Object> answers = new HashMap<>();
		answers.put("getFlags", (Answer) args -> collisionFlags);
		return proxy(CollisionData.class, answers);
	}

	/**
	 * Built once: the LOS walk skips any null tile pair, so an empty grid
	 * reads as "nothing can see anything" rather than "nothing is in the
	 * way". Each tile only ever answers the two questions the sight check
	 * asks - its plane and its scene location.
	 */
	private net.runelite.api.Tile[][][] sceneTiles;

	private net.runelite.api.Scene proxyScene()
	{
		Map<String, Object> answers = new HashMap<>();
		answers.put("getTiles", (Answer) args ->
		{
			if (sceneTiles == null)
			{
				int size = net.runelite.api.Perspective.SCENE_SIZE;
				sceneTiles = new net.runelite.api.Tile[4][size][size];
				for (int plane = 0; plane < 4; plane++)
				{
					for (int x = 0; x < size; x++)
					{
						for (int y = 0; y < size; y++)
						{
							Map<String, Object> tile = new HashMap<>();
							tile.put("getPlane", plane);
							tile.put("getSceneLocation",
								new net.runelite.api.Point(x, y));
							// Read fresh, so objects placed after the grid
							// was built still appear; empty rather than null
							// because the errand scanner iterates it bare.
							String key = plane + ":" + x + ":" + y;
							tile.put("getGameObjects", (Answer) callArgs ->
							{
								List<net.runelite.api.GameObject> here =
									placedObjects.get(key);
								return here == null
									? new net.runelite.api.GameObject[0]
									: here.toArray(new net.runelite.api.GameObject[0]);
							});
							sceneTiles[plane][x][y] =
								proxy(net.runelite.api.Tile.class, tile);
						}
					}
				}
			}
			return sceneTiles;
		});
		answers.put("getBaseX", 0);
		answers.put("getBaseY", 0);
		return proxy(net.runelite.api.Scene.class, answers);
	}

	private ItemContainer inventoryContainer()
	{
		Map<String, Object> answers = new HashMap<>();
		answers.put("getItems", (Answer) args -> inventory);
		return proxy(ItemContainer.class, answers);
	}

	private static <T> IndexedObjectSet<T> indexed(List<T> backing)
	{
		return new IndexedObjectSet<T>()
		{
			@Override
			public T byIndex(int index)
			{
				return index >= 0 && index < backing.size() ? backing.get(index) : null;
			}

			@Override
			public Iterator<T> iterator()
			{
				return backing.iterator();
			}
		};
	}

	/**
	 * Answers from the map when it has an entry for the method NAME, otherwise
	 * returns the harmless default for the return type. A {@link Function} value
	 * is called at answer time, so mutable state (the scene, worn gear) is read
	 * fresh rather than frozen when the proxy was built.
	 */
	@SuppressWarnings("unchecked")
	private static <T> T proxy(Class<T> type, Map<String, Object> answers)
	{
		InvocationHandler handler = (instance, method, args) ->
		{
			String name = method.getName();

			// equals/hashCode/toString must behave, or collections misbehave.
			switch (name)
			{
				case "equals":
					return instance == args[0];
				case "hashCode":
					return System.identityHashCode(instance);
				case "toString":
					return type.getSimpleName() + "@fake";
				default:
					break;
			}

			if (answers.containsKey(name))
			{
				Object answer = answers.get(name);
				return answer instanceof Answer
					? ((Answer) answer).get(args)
					: answer;
			}
			return defaultFor(method.getReturnType());
		};

		return (T) Proxy.newProxyInstance(
			type.getClassLoader(), new Class<?>[]{type}, handler);
	}

	private static Object defaultFor(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}
		if (type == boolean.class)
		{
			return Boolean.FALSE;
		}
		if (type == void.class)
		{
			return null;
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == double.class)
		{
			return 0.0d;
		}
		if (type == float.class)
		{
			return 0.0f;
		}
		if (type == char.class)
		{
			return (char) 0;
		}
		if (type == byte.class)
		{
			return (byte) 0;
		}
		if (type == short.class)
		{
			return (short) 0;
		}
		return 0;
	}
}

package com.follower.sim;

import com.follower.speech.RuleLoader;
import com.follower.speech.SpeechEngine;
import com.follower.speech.SpeechOutput;
import com.follower.speech.SpeechRule;
import com.follower.speech.TriggerEvent;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * A running speech engine with nothing behind it but {@link FakeGame}.
 *
 * <p>Loads the rules the plugin actually ships - the loader writes them from the
 * bundled resource into a scratch directory - so these tests exercise the real
 * rule set rather than a hand-written stand-in that could drift from it.
 */
public final class Harness
{
	/** One thing the engine asked the plugin to say. */
	public static final class Spoken
	{
		public final String text;
		public final SpeechOutput output;
		public final SpeechRule rule;
		public final int animationId;

		Spoken(String text, SpeechOutput output, SpeechRule rule, int animationId)
		{
			this.text = text;
			this.output = output;
			this.rule = rule;
			this.animationId = animationId;
		}

		@Override
		public String toString()
		{
			return (rule == null ? "(direct)" : rule.describe())
				+ " -> \"" + text + "\" anim=" + animationId;
		}
	}

	public final FakeGame game = new FakeGame();
	public final RuleLoader loader = new RuleLoader(new Gson());
	public final SpeechEngine engine;
	public final List<Spoken> spoken = new ArrayList<>();

	private final Path scratch;
	private int tick;

	/** Loads the rules the plugin ships with. */
	public Harness(Path scratch) throws IOException
	{
		this(scratch, null);
	}

	/**
	 * @param rulesJson the body of a phrases.json to use instead of the bundled
	 * rules, or null for the bundled set. Written to disk and read back through
	 * the real loader, so a focused test still goes through parsing and
	 * validation rather than around them.
	 */
	public Harness(Path scratch, String rulesJson) throws IOException
	{
		this.scratch = scratch;
		Files.createDirectories(scratch);
		Path file = scratch.resolve(RuleLoader.FILE_NAME);
		if (rulesJson != null)
		{
			Files.write(file, rulesJson.getBytes(java.nio.charset.StandardCharsets.UTF_8));
		}
		else
		{
			Files.deleteIfExists(file);
		}

		loader.initialise(scratch);
		engine = new SpeechEngine(game.client, loader);
		// No queue in the harness: every line is delivered the moment it is
		// handed over, so the said-conditional latches run before the engine
		// call returns - same order the old immediate latching had.
		engine.setSink((text, output, rule, animationId, onSaid) ->
		{
			onSaid.run();
			spoken.add(new Spoken(text, output, rule, animationId));
		});
		// Off by default: the global window is a separate thing to test, and
		// leaving it on would silently swallow most firings in every other test.
		engine.setGlobalCooldownMs(0L);
	}

	public Path getScratch()
	{
		return scratch;
	}

	/**
	 * One game tick: advances the clock, refreshes the state snapshot and
	 * dispatches the tick heartbeat, in the order the plugin does it.
	 */
	public Harness gameTick()
	{
		game.tick(++tick);
		engine.refreshContext();
		engine.dispatch(TriggerEvent.tick());
		return this;
	}

	public Harness gameTicks(int count)
	{
		for (int i = 0; i < count; i++)
		{
			gameTick();
		}
		return this;
	}

	/** Dispatches an event mid-tick, as the plugin's own subscribers do. */
	public Harness dispatch(TriggerEvent event)
	{
		engine.dispatch(event);
		return this;
	}

	/** The local player saying something in public chat. */
	public Harness playerSays(String message)
	{
		engine.dispatch(TriggerEvent.chat(message,
			net.runelite.api.ChatMessageType.PUBLICCHAT.getType(), "Tester"));
		return this;
	}

	/**
	 * The player picking a branch that answers, as the dialog does: the
	 * question closes and the rules are told, in that order.
	 */
	public Harness answers(String yesOrNo)
	{
		engine.getContext().noteAnswered();
		engine.dispatch(TriggerEvent.answered(yesOrNo));
		return this;
	}

	/** Somebody else in public chat. */
	public Harness someoneSays(String who, String message)
	{
		engine.dispatch(TriggerEvent.chat(message,
			net.runelite.api.ChatMessageType.PUBLICCHAT.getType(), who));
		return this;
	}

	public List<Spoken> firedBy(String ruleId)
	{
		List<Spoken> hits = new ArrayList<>();
		for (Spoken s : spoken)
		{
			if (s.rule != null && ruleId.equals(s.rule.id))
			{
				hits.add(s);
			}
		}
		return hits;
	}

	public SpeechRule rule(String id)
	{
		for (SpeechRule rule : loader.getRules())
		{
			if (id.equals(rule.id))
			{
				return rule;
			}
		}
		throw new AssertionError("no rule '" + id + "' in the bundled set");
	}

	public void clear()
	{
		spoken.clear();
	}
}

package com.follower.speech;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * WHEN a conversation delivers its answer.
 *
 * <p>Lives in the engine's own package because the seams it uses are: reaching
 * a node the real way needs a follower to face the player and a client to
 * compose a chathead from, and neither exists headlessly. The moment the answer
 * lands is worth pinning down on its own anyway - it is not a detail of
 * rendering, it is the difference between hearing the reply and missing it.
 */
public class DialogTimingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private DialogTree shippedTree() throws IOException
	{
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(folder.newFolder().toPath());
		DialogTree tree = loader.get("want-outing");
		assertNotNull("the shipped question tree", tree);
		return tree;
	}

	private static String answeringNode(DialogTree tree)
	{
		for (DialogTree.DialogNode node : tree.nodes)
		{
			if (node.answer != null)
			{
				return node.id;
			}
		}
		throw new AssertionError("the tree has no answering node");
	}

	@Test
	public void theAnswerIsDeliveredWhenTheBoxCloses() throws IOException
	{
		// The follower's reply to its own question goes OVERHEAD. Delivering
		// the answer the instant the branch is picked puts that line above a
		// dialog box the player is still reading, so the one thing they were
		// waiting to hear is the one thing they miss.
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		Map<String, FollowerDialog.Node> script = FollowerDialog.build(tree, answers::add);

		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(script);

		dialog.reachForTest(answeringNode(tree));
		assertTrue("picking the branch must not deliver it yet", answers.isEmpty());

		dialog.close();
		assertEquals("closing the box is what delivers it", 1, answers.size());

		dialog.close();
		assertEquals("and it must not arrive twice", 1, answers.size());
	}

	@Test
	public void closingEarlyStillCounts() throws IOException
	{
		// Walking off, or being interrupted, after picking an answer. The
		// player answered; whether they read the rest of it is their business,
		// and a follower that forgot the answer because the box was dismissed
		// would look like it had not been listening.
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(FollowerDialog.build(tree, answers::add));

		dialog.reachForTest(answeringNode(tree));
		dialog.close();
		assertEquals(1, answers.size());
	}

	@Test
	public void aFreshConversationInheritsNoAnswerFromTheLastOne() throws IOException
	{
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		Map<String, FollowerDialog.Node> script = FollowerDialog.build(tree, answers::add);

		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(script);
		dialog.reachForTest(answeringNode(tree));

		// Talked to again before the first one ended. A latch carried across
		// would answer a question that is no longer being asked.
		dialog.openForTest(script);
		dialog.close();
		assertTrue("a new conversation must not carry the old latch", answers.isEmpty());
	}

	@Test
	public void aConversationNobodyAnsweredDeliversNothing() throws IOException
	{
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(FollowerDialog.build(tree, answers::add));

		dialog.reachForTest(tree.startId());
		dialog.close();
		assertTrue("opening and shutting the box is not an answer", answers.isEmpty());
	}
}

package com.follower.speech;

import com.follower.sim.Harness;
import java.io.IOException;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The two things a mood does beyond choosing words, and the guard that keeps
 * the follower's opinion of a place about the place.
 *
 * <p>Both were found by a mutation sweep rather than by review: the sweep said
 * they were covered, and they were not - the run before each had left a compile
 * error behind, so the "failure" that looked like a catch was the build, not a
 * test. Hence these, which fail for the reason they claim to.
 */
public class MoodAndPlaceTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void aBadDayMakesTheFollowerSayLessRatherThanSaySadderThings()
	{
		long base = 3_000L;

		// The point of the feature: the gap is not the same in every mood.
		assertTrue("a low mood has to leave more room than an even one",
			SpeechEngine.gapForMood(base, "low") > SpeechEngine.gapForMood(base, "even"));
		assertTrue("a high mood has to leave less",
			SpeechEngine.gapForMood(base, "high") < SpeechEngine.gapForMood(base, "even"));

		// And it has to be monotonic across the bands, or the follower gets
		// chattier on the way DOWN through one of them.
		long low = SpeechEngine.gapForMood(base, "low");
		long down = SpeechEngine.gapForMood(base, "down");
		long even = SpeechEngine.gapForMood(base, "even");
		long good = SpeechEngine.gapForMood(base, "good");
		long high = SpeechEngine.gapForMood(base, "high");
		assertTrue("low > down > even > good > high",
			low > down && down > even && even > good && good > high);

		// An unknown band is the ordinary gap, not zero: a follower that talked
		// without pause because a band was renamed would be a bad way to find
		// out about the rename.
		assertEquals("an unrecognised band falls back to the plain gap",
			base, SpeechEngine.gapForMood(base, "nonsense"));
		assertEquals(base, SpeechEngine.gapForMood(base, null));
	}

	@Test
	public void loggingInDoesNotMakeYourBankTheFollowersFavouritePlace()
		throws IOException
	{
		// Every rule that carries a mood teaches the follower how it feels
		// about where it happened. Logging in after a day away is worth +8 and
		// happens wherever you logged OUT - the same tile, every single time.
		// Left in, the most-loved place in the game would reliably be the spot
		// you park on, which is a fact about your habits and not about the
		// world.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"welcome\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"mood\": 8, \"when\": {\"type\": \"login\"},"
				+ " \"say\": [\"there you are\"]}]}");

		h.gameTicks(1);
		for (int i = 0; i < 6; i++)
		{
			h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		}

		assertTrue("something has to have fired for this to prove anything",
			!h.firedBy("welcome").isEmpty());
		assertEquals("logging in says nothing about where you logged in",
			0, h.engine.getContext().getPlaceScore());
	}

	@Test
	public void whatHappensToYouHereDoesCount() throws IOException
	{
		// The other side of the same guard: an event that IS about the world
		// has to reach the place, or the feature does nothing at all.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"ouch\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"mood\": -20, \"when\": {\"type\": \"playerDeath\"},"
				+ " \"say\": [\"well then\"]}]}");

		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());
		h.gameTicks(1);

		assertTrue("dying here has to count against the place",
			h.engine.getContext().getPlaceScore() < 0);

		// And it belongs to THIS place, not to the follower in general.
		h.game.at(2624, 3648, 0);
		h.gameTicks(2);
		assertEquals("somewhere else is still innocent",
			0, h.engine.getContext().getPlaceScore());
	}

	@Test
	public void aPlaceDoesNotRemindYouOfSomethingYouJustDid() throws IOException
	{
		// Found in a transcript: the follower set a personal best, filed the
		// spot, and five seconds later told the player "this is where you hit
		// harder than you ever had" - to somebody who had not moved. The value
		// of a place memory is entirely in the waiting.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"recall\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"happenedHere\"},"
				+ " \"say\": [\"this is where {here}\"]}]}");

		h.gameTicks(1);
		h.engine.getContext().notePlaceMemory("you hit harder than you ever had");
		h.gameTicks(5);
		assertTrue("standing where it happened is not being reminded of it",
			h.firedBy("recall").isEmpty());

		// Leave, come back.
		h.game.at(2624, 3648, 0);
		h.gameTicks(2);
		h.game.at(3222, 3218, 0);
		h.gameTicks(2);
		assertFalse("coming back is what makes it worth saying",
			h.firedBy("recall").isEmpty());
	}

	@Test
	public void aPlaceCannotTalkItselfIntoAnOpinion() throws IOException
	{
		// place-liked and place-disliked are themselves worth mood, and they
		// fire BECAUSE of how the follower feels about where it is. Counted,
		// they would be evidence for their own conclusion, and the score would
		// run away from a single lucky roll.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"lovely\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"mood\": 10,"
				+ " \"when\": {\"type\": \"feelsAbout\", \"is\": \"liked\"},"
				+ " \"say\": [\"I like it here\"]}]}");

		int here = new WorldPoint(3222, 3218, 0).getRegionID();
		h.engine.getContext().setTraits(
			new java.util.HashSet<>(java.util.Collections.singletonList(here)),
			new java.util.HashSet<>());

		h.gameTicks(30);
		assertTrue("the rule has to have fired for this to prove anything",
			!h.firedBy("lovely").isEmpty());
		assertEquals("liking a place is not evidence that the place is likeable",
			0, h.engine.getContext().getPlaceScore());
	}
}

package com.follower.speech;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The small pieces that show up in what the follower actually says: where a
 * line is sent, and how an amount of gold is written.
 */
public class SpeechDetailsTest
{
	// ----------------------------------------------------------------- output

	@Test
	public void outputModesParseHoweverTheyAreWritten()
	{
		assertEquals(SpeechOutput.OVERHEAD, SpeechOutput.parse("overhead", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.OVERHEAD, SpeechOutput.parse("OVERHEAD", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.CHATBOX, SpeechOutput.parse("  ChatBox  ", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse("both", SpeechOutput.OVERHEAD));
	}

	@Test
	public void anUnknownOutputFallsBackRatherThanFailing()
	{
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse(null, SpeechOutput.BOTH));
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse("", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse("shouting", SpeechOutput.BOTH));
	}

	@Test
	public void eachModeGoesWhereItsNameSays()
	{
		assertTrue(SpeechOutput.OVERHEAD.showsOverhead());
		assertFalse(SpeechOutput.OVERHEAD.showsChatbox());

		assertFalse(SpeechOutput.CHATBOX.showsOverhead());
		assertTrue(SpeechOutput.CHATBOX.showsChatbox());

		assertTrue(SpeechOutput.BOTH.showsOverhead());
		assertTrue(SpeechOutput.BOTH.showsChatbox());
	}

	// ------------------------------------------------------------------- gold

	/** The {value} placeholder in a loot line, written the way a player says it. */
	private static String gp(int amount)
	{
		return TriggerEvent.loot(amount, "thing").getPlaceholders().get("value");
	}

	@Test
	public void goldIsWrittenTheWayAPlayerSaysIt()
	{
		assertEquals("0", gp(0));
		assertEquals("950", gp(950));
		assertEquals("9999", gp(9999));
		assertEquals("10K", gp(10_000));
		assertEquals("214K", gp(214_500));
		assertEquals("999K", gp(999_999));
		assertEquals("1.0M", gp(1_000_000));
		assertEquals("1.2M", gp(1_234_567));
	}

	@Test
	public void aHugeDropDoesNotOverflowIntoNonsense()
	{
		assertEquals("2147.5M", gp(Integer.MAX_VALUE));
	}

	@Test
	public void aLootEventCarriesTheItemAndTheAmount()
	{
		TriggerEvent event = TriggerEvent.loot(1_500_000, "Twisted bow");
		assertEquals("Twisted bow", event.getPlaceholders().get("item"));
		assertEquals("1.5M", event.getPlaceholders().get("value"));
		assertEquals("the raw value is what lootWorth compares against",
			1_500_000, event.getValue());
	}

	@Test
	public void aLootEventWithNoNamedItemIsStillUsable()
	{
		TriggerEvent event = TriggerEvent.loot(100, null);
		assertEquals("", event.getPlaceholders().get("item"));
	}

	// ------------------------------------------------------------- kill event

	@Test
	public void aKillCarriesEverythingAKillLineCouldWant()
	{
		TriggerEvent event = TriggerEvent.kill(2042, "Zulrah", 725);
		assertEquals("Zulrah", event.getPlaceholders().get("npc"));
		assertEquals("2042", event.getPlaceholders().get("npcId"));
		assertEquals("725", event.getPlaceholders().get("level"));
		assertEquals("the combat level is what npcKill brackets on",
			725, event.getValue());
	}

	@Test
	public void aKillWithNoNameDoesNotCarryANull()
	{
		TriggerEvent event = TriggerEvent.kill(1, null, 3);
		assertEquals("", event.getPlaceholders().get("npc"));
	}

	// --------------------------------------------------------------- phrases

	@Test
	public void aSinglePhraseRuleAlwaysSaysIt()
	{
		SpeechRule rule = new SpeechRule();
		rule.say = java.util.Collections.singletonList("only line");
		for (int i = 0; i < 20; i++)
		{
			assertEquals("only line", rule.pickPhrase());
		}
	}

	@Test
	public void aRuleWithNoLinesSaysNothingRatherThanFailing()
	{
		assertEquals("", new SpeechRule().pickPhrase());

		SpeechRule empty = new SpeechRule();
		empty.say = new java.util.ArrayList<>();
		assertEquals("", empty.pickPhrase());
	}

	@Test
	public void aPhraseIsNeverRepeatedBackToBack()
	{
		SpeechRule rule = new SpeechRule();
		rule.say = java.util.Arrays.asList("a", "b", "c");

		String previous = null;
		for (int i = 0; i < 500; i++)
		{
			String picked = rule.pickPhrase();
			assertFalse("said '" + picked + "' twice in a row", picked.equals(previous));
			previous = picked;
		}
	}

	@Test
	public void twoPhrasesAlternateRatherThanHanging()
	{
		// The no-repeat draw loops until it gets a different index; with only
		// two lines that leaves exactly one choice each time. The liveness half
		// of this is that it returns at all - a draw that could not satisfy
		// itself would spin forever on the game thread.
		//
		// The name also claims they ALTERNATE, which nothing here checked: the
		// case passed just as well against a draw that returned "a" a hundred
		// times. Now it says both.
		SpeechRule rule = new SpeechRule();
		rule.say = java.util.Arrays.asList("a", "b");

		String previous = null;
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (int i = 0; i < 100; i++)
		{
			String picked = rule.pickPhrase();
			seen.add(picked);
			if (previous != null)
			{
				assertNotEquals("with two lines every draw has to swap", previous, picked);
			}
			previous = picked;
		}
		assertEquals("both lines have to come up", 2, seen.size());
	}
}

package com.follower.speech;

import com.follower.sim.Harness;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The transcript.
 *
 * <p>It exists to answer questions that were previously settled by feel - is it
 * repeating itself, is it being throttled, did that pacing change help - so the
 * thing worth testing is that its figures are right and that it writes nothing
 * at all until asked.
 */
public class SpeechJournalTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private SpeechJournal journalIn(Path dir)
	{
		SpeechJournal journal = new SpeechJournal();
		journal.initialise(dir);
		return journal;
	}

	private static SpeechRule rule(String id, String group)
	{
		SpeechRule r = new SpeechRule();
		r.id = id;
		r.group = group;
		return r;
	}

	@Test
	public void writesNothingUntilItIsSwitchedOn() throws IOException
	{
		// A diagnostic that logs a player's session unasked is a surprising
		// thing for a plugin to do. Off is the default and off must mean off.
		Path dir = folder.newFolder().toPath();
		SpeechJournal journal = journalIn(dir);

		assertFalse("starts off", journal.isEnabled());
		journal.spoke(rule("idle-chatter", "idle"), "Still here. Still standing.");
		journal.suppressed(rule("low-hp", "health"), "gap");
		journal.flush();

		assertFalse("no file until it is asked for",
			Files.exists(journal.getFile()));
		assertTrue("and nothing counted either",
			journal.summary().get(0).contains("nothing said yet"));
	}

	@Test
	public void beingSwitchedOnDirectlyIsTheSameAsToggling() throws IOException
	{
		// The plugin restores the saved state this way at startup. Found the
		// hard way: the first real bug-fix verification run recorded nothing,
		// because a restart quietly turned the transcript off again.
		java.nio.file.Path dir = folder.newFolder().toPath();
		SpeechJournal journal = journalIn(dir);

		journal.setEnabled(true);
		assertTrue(journal.isEnabled());
		journal.spoke(rule("idle-chatter", "idle"), "Quiet, isn't it.");
		journal.flush();
		assertTrue("recording after being switched on directly",
			Files.exists(journal.getFile()));

		// And setting it to what it already is must not open a second time.
		journal.setEnabled(true);
		journal.flush();
		String written = new String(Files.readAllBytes(journal.getFile()),
			StandardCharsets.UTF_8);
		assertEquals("one opening marker, not two", 1,
			written.split("transcript opened", -1).length - 1);
	}

	@Test
	public void recordsWhatWasSaidAndWhatWasHeldBack() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		SpeechJournal journal = journalIn(dir);
		journal.toggle();

		journal.spoke(rule("idle-chatter", "idle"), "Still here. Still standing.");
		journal.suppressed(rule("low-hp", "health"), "gap");
		journal.suppressed(rule("combat-cheer", "combat"), "gap");
		journal.suppressed(rule("area-varrock", "area"), "hush");
		journal.flush();

		String written = new String(Files.readAllBytes(journal.getFile()),
			StandardCharsets.UTF_8);
		assertTrue("the line the player saw", written.contains("Still here. Still standing."));
		assertTrue("the rule that said it", written.contains("idle-chatter"));
		assertTrue("and the ones that could not", written.contains("low-hp"));
		assertTrue("with the reason", written.contains("hush"));

		String head = journal.summary().get(0);
		assertTrue("counts both halves: " + head,
			head.contains("1 lines") && head.contains("3 held back"));
	}

	@Test
	public void everyRowSaysWhereItHappened() throws IOException
	{
		// Several behaviours are answers to "where" - place memory, taste,
		// return visits - and a transcript without it cannot be used to check
		// any of them. A verification run was lost to exactly that.
		Path dir = folder.newFolder().toPath();
		SpeechJournal journal = journalIn(dir);
		journal.setRegionSource(() -> 12850);
		journal.toggle();

		journal.spoke(rule("place-remembers", "area"), "This is where it happened.");
		journal.suppressed(rule("low-hp", "health"), "gap");
		journal.flush();

		for (String line : new String(Files.readAllBytes(journal.getFile()),
			StandardCharsets.UTF_8).split("\n"))
		{
			if (line.startsWith("----") || line.isEmpty())
			{
				continue;
			}
			assertTrue("every row carries the region: " + line,
				line.contains("\tr12850\t"));
		}
	}

	@Test
	public void withNoRegionSourceItStillWrites() throws IOException
	{
		// The supplier is set by the plugin; nothing else sets it, and a
		// missing one must not take the transcript down.
		Path dir = folder.newFolder().toPath();
		SpeechJournal journal = journalIn(dir);
		journal.toggle();
		journal.spoke(rule("idle-chatter", "idle"), "Quiet, isn't it.");
		journal.flush();
		assertTrue(Files.exists(journal.getFile()));
	}

	@Test
	public void findsTheLineItKeepsRepeating()
	{
		// The question the transcript exists to answer.
		SpeechJournal journal = journalIn(folder.getRoot().toPath());
		journal.toggle();

		SpeechRule idle = rule("idle-chatter", "idle");
		journal.spoke(idle, "Quiet, isn't it.");
		journal.spoke(idle, "Still here. Still standing.");
		journal.spoke(idle, "Quiet, isn't it.");
		journal.spoke(idle, "Quiet, isn't it.");

		String repeated = journal.summary().stream()
			.filter(l -> l.contains("most repeated"))
			.findFirst().orElse("");
		assertTrue("should name the repeat: " + repeated,
			repeated.contains("Quiet, isn't it.") && repeated.contains("3x"));
	}

	@Test
	public void saysNothingAboutRepeatsWhenThereAreNone()
	{
		SpeechJournal journal = journalIn(folder.getRoot().toPath());
		journal.toggle();
		journal.spoke(rule("a", "idle"), "One.");
		journal.spoke(rule("b", "idle"), "Two.");

		assertTrue("a line said once is not a repeat",
			journal.summary().stream().noneMatch(l -> l.contains("most repeated")));
	}

	@Test
	public void ranksTheLoudestRules()
	{
		SpeechJournal journal = journalIn(folder.getRoot().toPath());
		journal.toggle();
		for (int i = 0; i < 5; i++)
		{
			journal.spoke(rule("combat-cheer", "combat"), "Keep at it. " + i);
		}
		journal.spoke(rule("idle-chatter", "idle"), "Quiet, isn't it.");

		String loudest = journal.summary().stream()
			.filter(l -> l.contains("loudest rules"))
			.findFirst().orElse("");
		assertTrue("the busiest rule comes first: " + loudest,
			loudest.indexOf("combat-cheer") < loudest.indexOf("idle-chatter"));
	}

	@Test
	public void aCommandDrivenLineHasNoRuleAndIsStillRecorded()
	{
		// ::follower say goes through the same sink with a null rule; it must
		// not take the transcript down with it.
		SpeechJournal journal = journalIn(folder.getRoot().toPath());
		journal.toggle();
		journal.spoke(null, "Testing, testing.");
		assertTrue(journal.summary().get(0).contains("1 lines"));
	}

	@Test
	public void theEngineReportsWhyALineWasHeldBack() throws IOException
	{
		// The half of the story the player never sees, and the reason the
		// transcript is worth having at all. Driven through the real engine
		// rather than by calling the journal directly.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"chatty\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"always\"}, \"say\": [\"one\", \"two\"]}]}");

		List<String> reasons = new java.util.ArrayList<>();
		h.engine.setOnSuppressed((rule, why) -> reasons.add(rule.describe() + ":" + why));

		h.engine.setMuted(true);
		h.gameTicks(3);

		assertFalse("a muted rule still wins and is still held back", reasons.isEmpty());
		assertEquals("chatty:muted", reasons.get(0));
	}

	@Test
	public void theDirectorsReasonsReachTheTranscript() throws IOException
	{
		// The transcript is the only way to tell a follower with little to say
		// from one being throttled, and the director became the biggest source
		// of throttling in the plugin the day it landed. A reason that stops at
		// the engine is a blind spot in the one diagnostic there is.
		// An "always" rule rises exactly once and then never again, so it can
		// never be suppressed twice - which is why this needs a real event to
		// re-trigger on, with a tick between to let the edge fall.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"scenery\", \"group\": \"area\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"one\", \"two\"]}]}");

		SpeechJournal journal = new SpeechJournal();
		journal.initialise(folder.newFolder().toPath());
		journal.setEnabled(true);
		h.engine.setOnSuppressed(journal::suppressed);

		h.engine.setGlobalCooldownMs(3_000L);
		h.engine.getContext().setSessionCount(1);
		h.gameTicks(1);

		// The first one speaks, which arms the settling damper; the next two
		// arrive well inside its window and are the ones held.
		for (int i = 0; i < 3; i++)
		{
			h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			h.gameTicks(1);
		}

		// Then a rest, by handing the director a burst directly.
		com.follower.speech.SpeechRule filler = new com.follower.speech.SpeechRule();
		filler.id = "filler";
		filler.group = "reactions";
		for (int i = 0; i < 4; i++)
		{
			h.engine.getDirector().noteSpoke(filler, System.currentTimeMillis());
		}
		for (int i = 0; i < 2; i++)
		{
			h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			h.gameTicks(1);
		}
		journal.flush();

		String written = String.join("\n", java.nio.file.Files.readAllLines(
			journal.getFile()));
		assertTrue("the transcript never mentions the director resting:\n" + written,
			written.contains("\trelax"));
		assertTrue("the transcript never mentions the settling damper:\n" + written,
			written.contains("\tsettling"));
	}
}

package com.follower.ui;

import org.junit.After;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The gamma table every drawn pixel of the follower's face resolves through.
 *
 * <p>It exists so the follower's chathead sits on the SAME table as every real
 * chathead on screen - the client rebuilds its own when the brightness setting
 * changes, and a head lit differently from the one beside it is immediately
 * obvious. The table is indexed by packed HSL, and the index is masked rather
 * than checked, so the interesting questions are about its edges.
 */
public class GameColourTableTest
{
	@After
	public void restoreDefaultBrightness()
	{
		// Static state shared with every other test in the JVM.
		GameColourTable.setBrightnessSetting(2);
	}

	// ---------------------------------------------------------------- lookup

	@Test
	public void everyPackedValueResolvesToAColour()
	{
		// 16 bits of packed HSL, all of which a model can contain.
		for (int packed = 0; packed <= 0xFFFF; packed++)
		{
			int rgb = GameColourTable.rgb(packed);
			assertTrue("packed " + packed + " gave " + rgb, rgb >= 0);
			assertTrue("packed " + packed + " overflowed 24 bits", rgb <= 0xFFFFFF);
		}
	}

	@Test
	public void anOutOfRangeIndexIsMaskedNotAnException()
	{
		// The rasterizer interpolates colour endpoints and can run past the
		// range; masking is what keeps that from throwing mid-render.
		GameColourTable.rgb(-1);
		GameColourTable.rgb(Integer.MAX_VALUE);
		GameColourTable.rgb(Integer.MIN_VALUE);
		GameColourTable.rgb(0x1FFFF);

		assertEquals("the mask should wrap, not clamp",
			GameColourTable.rgb(0), GameColourTable.rgb(0x10000));
	}

	@Test
	public void theTableIsNotAllOneColour()
	{
		// A build that silently produced zeroes would draw a black face.
		int distinct = 0;
		int previous = -1;
		for (int packed = 0; packed < 4096; packed++)
		{
			int rgb = GameColourTable.rgb(packed);
			if (rgb != previous)
			{
				distinct++;
				previous = rgb;
			}
		}
		assertTrue("the table only produced " + distinct + " runs of colour",
			distinct > 100);
	}

	// ------------------------------------------------------------ brightness

	@Test
	public void theFourBrightnessSettingsMapToTheClientsGammas()
	{
		// The client's varp maps 1..4 to Dark through V.Bright.
		GameColourTable.setBrightnessSetting(1);
		assertEquals(0.9, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(2);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(3);
		assertEquals(0.7, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(4);
		assertEquals(0.6, GameColourTable.getCurrentGamma(), 0.0001);
	}

	@Test
	public void anUnknownSettingFallsBackToTheDefault()
	{
		GameColourTable.setBrightnessSetting(99);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(-5);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(0);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);
	}

	@Test
	public void changingBrightnessActuallyChangesTheColours()
	{
		GameColourTable.setBrightnessSetting(1);
		int dark = GameColourTable.rgb(9000);

		GameColourTable.setBrightnessSetting(4);
		int bright = GameColourTable.rgb(9000);

		assertFalse("the table was not rebuilt for the new setting", dark == bright);
	}

	@Test
	public void aBrighterSettingIsActuallyBrighter()
	{
		// Lower gamma means brighter in the client's scheme, which is easy to
		// get backwards.
		GameColourTable.setBrightnessSetting(1);
		long darkTotal = luminanceOver(2000, 12000);

		GameColourTable.setBrightnessSetting(4);
		long brightTotal = luminanceOver(2000, 12000);

		assertTrue("V.Bright came out darker than Dark", brightTotal > darkTotal);
	}

	private static long luminanceOver(int from, int to)
	{
		long total = 0;
		for (int packed = from; packed < to; packed++)
		{
			int rgb = GameColourTable.rgb(packed);
			total += ((rgb >> 16) & 0xFF) + ((rgb >> 8) & 0xFF) + (rgb & 0xFF);
		}
		return total;
	}

	@Test
	public void settingTheSameBrightnessTwiceIsCheapAndStable()
	{
		GameColourTable.setBrightnessSetting(3);
		int first = GameColourTable.rgb(9000);

		for (int i = 0; i < 100; i++)
		{
			GameColourTable.setBrightnessSetting(3);
		}

		assertEquals("re-setting the same value must not disturb the table",
			first, GameColourTable.rgb(9000));
		assertEquals(0.7, GameColourTable.getCurrentGamma(), 0.0001);
	}
}

package com.follower.ui;

import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Path;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The glyph renderer every line the follower says goes through.
 *
 * <p>Its one sharp edge is how a character becomes a glyph: {@code charAt(i) &
 * 0xFF}. Nothing is rejected and nothing is mapped, so a character above
 * U+00FF is silently drawn as a DIFFERENT character, and the text on screen is
 * wrong in a way no log will ever mention. That is pinned here so the rule
 * cannot quietly change, and so the phrase-file check has something to agree
 * with.
 */
public class GameFontTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private GameFont overhead;
	private GameFont dialog;

	@Before
	public void setUp() throws IOException
	{
		GameFontRepository fonts = new GameFontRepository(new Gson());
		Path empty = folder.newFolder().toPath();
		fonts.load(empty);
		overhead = fonts.getByName("b12_full");
		dialog = fonts.get(497);
		assertNotNull(overhead);
		assertNotNull(dialog);
	}

	private static Graphics2D canvas()
	{
		return new BufferedImage(400, 100, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	// ------------------------------------------------------------- measuring

	@Test
	public void anEmptyStringHasNoWidth()
	{
		assertEquals(0, overhead.stringWidth(""));
	}

	@Test
	public void aNullStringIsNotACrash()
	{
		assertEquals(0, overhead.stringWidth(null));
		overhead.drawTop(canvas(), null, 0, 0, 0xFFFFFF, false);
	}

	@Test
	public void widthGrowsWithTheText()
	{
		int one = overhead.stringWidth("a");
		int two = overhead.stringWidth("aa");
		assertTrue("a single character should measure something", one > 0);
		assertEquals("measuring should be the sum of its advances", one * 2, two);
	}

	@Test
	public void aRealSentenceMeasuresSensibly()
	{
		int width = overhead.stringWidth("The quick brown fox jumps over the lazy dog");
		assertTrue("suspiciously narrow: " + width, width > 100);
		assertTrue("suspiciously wide: " + width, width < 1000);
	}

	@Test
	public void bothFontsHaveARealLineHeight()
	{
		assertTrue(overhead.getLineHeight() > 0);
		assertTrue(dialog.getLineHeight() > 0);
		assertTrue(overhead.getAscent() > 0);
	}

	// -------------------------------------------------------------- drawing

	@Test
	public void drawingActuallyPutsPixelsDown()
	{
		BufferedImage image = new BufferedImage(400, 100, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		overhead.drawTop(graphics, "Hello", 10, 10, 0xFF0000, false);

		boolean any = false;
		for (int x = 0; x < image.getWidth() && !any; x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					any = true;
					break;
				}
			}
		}
		assertTrue("nothing was drawn at all", any);
	}

	@Test
	public void everyDrawEntryPointSurvivesOrdinaryText()
	{
		Graphics2D graphics = canvas();
		overhead.drawTop(graphics, "Hello", 10, 10, 0xFFFFFF, false);
		overhead.drawTop(graphics, "Hello", 10, 10, 0xFFFFFF, true);
		overhead.drawBaseline(graphics, "Hello", 10, 40, 0xFFFFFF, false);
		overhead.drawCenteredBaseline(graphics, "Hello", 200, 40, 0xFFFFFF, true);
		overhead.drawCenteredOverhead(graphics, "Hello", 200, 60, 0x00FF00);
	}

	@Test
	public void drawingOffTheEdgeOfTheCanvasIsHarmless()
	{
		Graphics2D graphics = canvas();
		overhead.drawTop(graphics, "Hello", -500, -500, 0xFFFFFF, false);
		overhead.drawTop(graphics, "Hello", 100000, 100000, 0xFFFFFF, false);
	}

	// ------------------------------------------------------ the sharp edge

	@Test
	public void everyLatin1CharacterCanBeMeasuredAndDrawn()
	{
		Graphics2D graphics = canvas();
		for (int c = 0; c <= 0xFF; c++)
		{
			String text = String.valueOf((char) c);
			assertTrue("negative width for char " + c, overhead.stringWidth(text) >= 0);
			overhead.drawTop(graphics, text, 10, 10, 0xFFFFFF, false);
			dialog.drawTop(graphics, text, 10, 10, 0xFFFFFF, false);
		}
	}

	/**
	 * The behaviour that makes the phrase-file check necessary. An em-dash is
	 * U+2014; the low byte is 0x14, so it is drawn as whatever sits there - not
	 * as the em-dash glyph the font really holds at 0x97, and not as nothing.
	 */
	@Test
	public void aCharacterPastLatin1IsTruncatedNotRejected()
	{
		assertEquals("an em-dash is measured as the character at its low byte",
			overhead.stringWidth(String.valueOf((char) 0x14)),
			overhead.stringWidth("—"));

		assertEquals("and as a different width from the glyph cp1252 would pick",
			overhead.stringWidth(String.valueOf((char) 0x97)),
			overhead.stringWidth(""));
	}

	@Test
	public void charactersWayPastLatin1StillDoNotThrow()
	{
		Graphics2D graphics = canvas();
		String[] awkward = {
			"—", "’", "…", "€", "�",
			"中文", "😀",
		};
		for (String text : awkward)
		{
			assertTrue(overhead.stringWidth(text) >= 0);
			overhead.drawTop(graphics, text, 10, 10, 0xFFFFFF, false);
			overhead.drawCenteredOverhead(graphics, text, 200, 60, 0xFFFFFF);
		}
	}

	@Test
	public void aVeryLongLineDoesNotOverflowItsMeasurement()
	{
		StringBuilder text = new StringBuilder();
		for (int i = 0; i < 5000; i++)
		{
			text.append('W');
		}
		int width = overhead.stringWidth(text.toString());
		assertTrue("width overflowed to a negative: " + width, width > 0);
	}
}

package com.follower.ui;

import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The client's triangle rasterizer, which draws the follower's face.
 *
 * <p>It is a verbatim port of integer scanline code, run once per triangle of a
 * chathead every frame a dialog is open. Two things can go wrong in that shape
 * of code and neither is subtle in effect: writing outside the pixel buffer,
 * which is an exception thrown from inside a render, and a degenerate triangle
 * sending the scanline walk somewhere it does not come back from.
 *
 * <p>So the tests here are mostly about what it must NOT do, driven with the
 * inputs a real model produces: sub-pixel faces, faces partly off every edge,
 * zero-area faces, and vertices in every order.
 */
public class GouraudRasterizerTest
{
	private static final int WIDTH = 64;
	private static final int HEIGHT = 64;

	/**
	 * Slack past the end of the visible buffer. The rasterizer takes its bounds
	 * from the width and height it is given rather than from the array length,
	 * so anything written past WIDTH * HEIGHT lands here instead of throwing -
	 * which is the point. An index error is loud; an off-by-one that happens to
	 * stay inside the allocation is silent, and in the real client the memory
	 * past the buffer belongs to something else.
	 */
	private static final int GUARD = 512;

	/** A canvas with a guard band after it, so an overrun is detectable. */
	private static final class Canvas
	{
		final int[] pixels = new int[WIDTH * HEIGHT + GUARD];
		final GouraudRasterizer raster = new GouraudRasterizer(pixels, WIDTH, HEIGHT);

		int painted()
		{
			int count = 0;
			for (int i = 0; i < WIDTH * HEIGHT; i++)
			{
				if (pixels[i] != 0)
				{
					count++;
				}
			}
			return count;
		}

		void assertGuardIntact(String what)
		{
			for (int i = WIDTH * HEIGHT; i < pixels.length; i++)
			{
				assertEquals(what + ": wrote " + pixels[i] + " past the end of the"
					+ " buffer, at offset " + (i - WIDTH * HEIGHT), 0, pixels[i]);
			}
		}
	}

	// ------------------------------------------------------------- it draws

	@Test
	public void anOrdinaryTriangleFillsPixels()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(10, 50, 30, 10, 20, 50, 8000, 8000, 8000);

		assertTrue("nothing was drawn at all", canvas.painted() > 0);
	}

	@Test
	public void aTriangleIsDrawnWhicheverOrderItsVerticesArriveIn()
	{
		// The three top-level cases order by smallest y; a model hands them over
		// in whatever order the mesh has them.
		int[][] orders = {
			{0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0},
		};
		int[] xs = {10, 50, 30};
		int[] ys = {10, 20, 50};

		for (int[] order : orders)
		{
			Canvas canvas = new Canvas();
			canvas.raster.gouraudTriangle(
				xs[order[0]], xs[order[1]], xs[order[2]],
				ys[order[0]], ys[order[1]], ys[order[2]],
				8000, 8000, 8000);
			assertTrue("winding order " + java.util.Arrays.toString(order)
				+ " drew nothing", canvas.painted() > 0);
		}
	}

	/**
	 * The reason this rasterizer exists: the float fill it replaced sampled
	 * pixel centres, and the pupils of an eye are faces only a few pixels
	 * across. Measured rather than assumed - a face spanning a single pixel
	 * covers no scanline at all under the client's half-open convention and
	 * correctly paints nothing, and from two pixels up the coverage grows with
	 * the area: 1, 3, 6, 10, 15.
	 */
	@Test
	public void faceOfAFewPixelsIsFilledAndScalesWithItsArea()
	{
		int[] expected = {0, 1, 3, 6, 10, 15};
		for (int size = 1; size <= expected.length; size++)
		{
			Canvas canvas = new Canvas();
			canvas.raster.gouraudTriangle(30, 30 + size, 30, 30, 30 + size, 30 + size,
				8000, 8000, 8000);
			assertEquals("a face " + size + " pixels across",
				expected[size - 1], canvas.painted());
		}
	}

	// -------------------------------------------------------- it stays inside

	@Test
	public void nothingIsWrittenOutsideTheBufferHoweverFarOffScreen()
	{
		int[][] cases = {
			{-500, -400, -450, 10, 20, 30},
			{500, 600, 550, 10, 20, 30},
			{10, 20, 30, -500, -400, -450},
			{10, 20, 30, 500, 600, 550},
			{-1000, 1000, 0, -1000, 1000, 0},
			{Integer.MIN_VALUE / 4, Integer.MAX_VALUE / 4, 0, -10, 10, 0},
			{0, 0, 0, Integer.MIN_VALUE / 4, Integer.MAX_VALUE / 4, 0},
		};

		for (int[] c : cases)
		{
			Canvas canvas = new Canvas();
			// Two ways this fails. An ArrayIndexOutOfBounds surfaces as an
			// exception thrown from inside the client's render loop, and that
			// one announces itself. A write that lands just past the visible
			// buffer does not - so the guard band is checked as well, which is
			// what the name of this case actually claims.
			canvas.raster.gouraudTriangle(c[0], c[1], c[2], c[3], c[4], c[5],
				8000, 9000, 10000);
			canvas.assertGuardIntact(java.util.Arrays.toString(c));
		}
	}

	@Test
	public void aTriangleStraddlingAnEdgeIsClippedNotWrapped()
	{
		Canvas canvas = new Canvas();
		// Hanging off the left edge. A missing clamp would wrap the scanline
		// onto the previous row, which looks like a smear across the face.
		canvas.raster.gouraudTriangle(-20, 20, 0, 10, 10, 40, 8000, 8000, 8000);

		for (int y = 0; y < HEIGHT; y++)
		{
			// Nothing may appear on a row the triangle does not cover.
			if (y < 10 || y > 40)
			{
				for (int x = 0; x < WIDTH; x++)
				{
					assertEquals("painted row " + y + ", outside the triangle",
						0, canvas.pixels[y * WIDTH + x]);
				}
			}
		}
	}

	@Test
	public void aTriangleEntirelyBelowTheClipIsSkipped()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(10, 30, 20, HEIGHT + 5, HEIGHT + 20, HEIGHT + 10,
			8000, 8000, 8000);

		assertEquals("something was drawn below the clip line", 0, canvas.painted());
	}

	// ----------------------------------------------------------- degenerate

	@Test
	public void degenerateTrianglesDoNotHangOrThrow()
	{
		int[][] degenerate = {
			{20, 20, 20, 20, 20, 20},       // a point
			{10, 40, 25, 20, 20, 20},       // flat, zero height
			{20, 20, 20, 10, 40, 25},       // a vertical line, zero width
			{10, 20, 30, 10, 10, 40},       // two vertices sharing a y
			{10, 20, 30, 40, 10, 10},       // the other two sharing a y
			{0, 0, 0, 0, 0, 0},             // the origin
		};

		for (int[] c : degenerate)
		{
			Canvas canvas = new Canvas();
			canvas.raster.gouraudTriangle(c[0], c[1], c[2], c[3], c[4], c[5],
				8000, 8000, 8000);
		}
	}

	@Test
	public void colourEndpointsAtTheExtremesDoNotThrow()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(10, 50, 30, 10, 20, 50,
			0, 0xFFFF, 0x7FFF);
		canvas.raster.gouraudTriangle(10, 50, 30, 10, 20, 50,
			Integer.MAX_VALUE / 2, 0, Integer.MIN_VALUE / 2);
	}

	// ----------------------------------------------------------------- fuzz

	@Test
	public void randomTrianglesNeverEscapeTheBuffer()
	{
		// A chathead is a few hundred triangles a frame; over a session that is
		// millions of calls with whatever the model geometry produces.
		Random random = new Random(20260808L);
		Canvas canvas = new Canvas();

		for (int i = 0; i < 20000; i++)
		{
			int range = 200;
			canvas.raster.gouraudTriangle(
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(0x10000),
				random.nextInt(0x10000),
				random.nextInt(0x10000));
		}

		assertTrue("twenty thousand random faces drew nothing, so the fuzz is"
			+ " not actually exercising the fill", canvas.painted() > 0);
	}

	@Test
	public void aTallThinTriangleIsDrawnRatherThanSkipped()
	{
		// The shape a nose or a fringe of hair produces.
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(30, 31, 30, 5, 30, 55, 8000, 8000, 8000);
		assertTrue(canvas.painted() > 0);
	}

	@Test
	public void aWideFlatTriangleIsDrawnRatherThanSkipped()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(5, 55, 30, 30, 30, 32, 8000, 8000, 8000);
		assertTrue(canvas.painted() > 0);
	}

	@Test
	public void aOnePixelHighCanvasIsNotACrash()
	{
		int[] pixels = new int[WIDTH];
		GouraudRasterizer raster = new GouraudRasterizer(pixels, WIDTH, 1);
		raster.gouraudTriangle(0, WIDTH, WIDTH / 2, 0, 0, 1, 8000, 8000, 8000);

		boolean anyPainted = false;
		for (int pixel : pixels)
		{
			anyPainted |= pixel != 0;
		}
		assertFalse("a canvas one pixel tall has no room for a triangle,"
			+ " but it must not crash trying", anyPainted && pixels.length != WIDTH);
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.File;
import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.ItemManager;
import net.runelite.cache.definitions.ItemDefinition;
import net.runelite.cache.definitions.KitDefinition;
import net.runelite.cache.definitions.SpotAnimDefinition;
import net.runelite.cache.definitions.loaders.KitLoader;
import net.runelite.cache.definitions.loaders.SpotAnimLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Writes equipment-models.json for the Follower Buddy plugin.
 *
 * <p>Run once, and again after a game update that adds gear you care about:
 *
 * <pre>
 *   gradlew run --args="&lt;cacheDir&gt; &lt;outputFile&gt;"
 * </pre>
 *
 * Both arguments are optional; the defaults are RuneLite's own cache directory
 * and {@code ~/.runelite/follower/equipment-models.json}.
 *
 * <p>Only items with at least one worn model are emitted — roughly 4,000 of the
 * 30,000-odd item definitions — which keeps the output a few megabytes rather
 * than tens.
 */
public class EquipmentDumper
{
	private static final int FORMAT_VERSION = 1;

	/** Mirrors com.follower.appearance.ModelRepository.Entry. */
	static class Entry
	{
		/** Item name, so the plugin's outfit picker has a searchable catalogue. */
		String n;
		/** Kits only: KitDefinition.bodyPartId - identifies part AND gender. */
		Integer bp;
		/**
		 * Vertical offsets the client applies to a worn model before merging it.
		 * Without them every piece sits at its raw origin and neighbouring pieces
		 * clip into one another.
		 */
		Integer mo;
		Integer fo;
		/**
		 * Equipment slots this item occupies. wp1 is the slot it goes in; wp2 and wp3
		 * are further slots it HIDES - a platebody hides the arms kit, a full helm
		 * hides hair and jaw. They index the same 12-slot array as KitType.
		 */
		Integer wp1;
		Integer wp2;
		Integer wp3;
		int[] m;
		int[] f;
		short[] cf;
		short[] cr;
		short[] tf;
		short[] tr;
		/**
		 * Chathead models: for items, the male/female dialogue head variants; for
		 * kits, KitDefinition.chatheadModels. These are what real dialogs animate -
		 * separate models with their own talk-animation skeletons.
		 */
		int[] hm;
		int[] hf;
		int[] ch;
	}

	static class Dump
	{
		int version = FORMAT_VERSION;
		String cacheRevision;
		Map<String, Entry> items = new LinkedHashMap<>();
		Map<String, Entry> kits = new LinkedHashMap<>();
	}

	/** Mirrors com.follower.appearance.SpotAnimRepository.Entry. */
	static class SpotAnimEntry
	{
		int m;
		int a;
		Integer rx;
		Integer ry;
		Integer rot;
		Integer am;
		Integer co;
		short[] cf;
		short[] cr;
		short[] tf;
		short[] tr;
	}

	static class SpotAnimDump
	{
		int version = FORMAT_VERSION;
		String cacheRevision;
		Map<String, SpotAnimEntry> spotanims = new LinkedHashMap<>();
	}

	public static void main(String[] args) throws IOException
	{
		Path cacheDir = args.length > 0
			? Paths.get(args[0])
			: defaultCacheDir();

		Path output = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "equipment-models.json");

		if (!Files.isDirectory(cacheDir))
		{
			System.err.println("Cache directory not found: " + cacheDir);
			System.err.println("Pass it explicitly: gradlew run --args=\"C:/path/to/cache out.json\"");
			System.exit(1);
		}

		System.out.println("Reading cache from " + cacheDir);

		Dump dump = new Dump();
		dump.cacheRevision = LocalDate.now().toString();

		SpotAnimDump spotAnims = new SpotAnimDump();
		spotAnims.cacheRevision = dump.cacheRevision;
		FontDump fontDump = new FontDump();
		fontDump.cacheRevision = dump.cacheRevision;

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			dumpItems(store, dump);
			dumpKits(store, dump);
			dumpSpotAnims(store, spotAnims);
			dumpFonts(store, fontDump);
		}

		Files.createDirectories(output.getParent());
		Gson gson = new GsonBuilder().create();
		try (Writer writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8))
		{
			gson.toJson(dump, writer);
		}

		Path spotAnimOutput = output.resolveSibling("spotanims.json");
		try (Writer writer = Files.newBufferedWriter(spotAnimOutput, StandardCharsets.UTF_8))
		{
			gson.toJson(spotAnims, writer);
		}

		Path fontOutput = output.resolveSibling("fonts.json");
		try (Writer writer = Files.newBufferedWriter(fontOutput, StandardCharsets.UTF_8))
		{
			gson.toJson(fontDump, writer);
		}
		System.out.printf("Wrote %d fonts to %s (%.1f KB)%n",
			fontDump.fonts.size(), fontOutput, Files.size(fontOutput) / 1024.0);

		System.out.printf("Wrote %d items and %d kits to %s (%.1f MB)%n",
			dump.items.size(), dump.kits.size(), output, Files.size(output) / 1024.0 / 1024.0);
		System.out.printf("Wrote %d spotanims to %s (%.1f KB)%n",
			spotAnims.spotanims.size(), spotAnimOutput, Files.size(spotAnimOutput) / 1024.0);
	}

	private static void dumpItems(Store store, Dump dump) throws IOException
	{
		ItemManager itemManager = new ItemManager(store);
		itemManager.load();

		for (ItemDefinition item : itemManager.getItems())
		{
			if (item == null)
			{
				continue;
			}

			boolean wearable = item.maleModel0 != -1 || item.femaleModel0 != -1;
			if (!wearable)
			{
				continue;
			}

			Entry entry = new Entry();
			entry.n = item.name;
			entry.mo = item.maleOffset;
			entry.fo = item.femaleOffset;
			entry.wp1 = item.wearPos1;
			entry.wp2 = item.wearPos2;
			entry.wp3 = item.wearPos3;
			entry.m = new int[]{item.maleModel0, item.maleModel1, item.maleModel2};
			entry.f = new int[]{item.femaleModel0, item.femaleModel1, item.femaleModel2};
			if (item.maleHeadModel != -1 || item.maleHeadModel2 != -1)
			{
				entry.hm = new int[]{item.maleHeadModel, item.maleHeadModel2};
			}
			if (item.femaleHeadModel != -1 || item.femaleHeadModel2 != -1)
			{
				entry.hf = new int[]{item.femaleHeadModel, item.femaleHeadModel2};
			}
			entry.cf = item.colorFind;
			entry.cr = item.colorReplace;
			entry.tf = item.textureFind;
			entry.tr = item.textureReplace;

			dump.items.put(Integer.toString(item.id), entry);
		}
	}

	private static void dumpKits(Store store, Dump dump) throws IOException
	{
		Storage storage = store.getStorage();
		Index index = store.getIndex(IndexType.CONFIGS);
		Archive archive = index.getArchive(ConfigType.IDENTKIT.getId());

		byte[] archiveData = storage.loadArchive(archive);
		ArchiveFiles files = archive.getFiles(archiveData);
		KitLoader loader = new KitLoader();

		for (FSFile file : files.getFiles())
		{
			KitDefinition kit = loader.load(file.getFileId(), file.getContents());
			if (kit == null || kit.models == null || kit.models.length == 0)
			{
				continue;
			}

			Entry entry = new Entry();
			entry.bp = kit.bodyPartId;
			// Kits are gender-specific by id, so both genders map to the same models.
			entry.m = kit.models;
			entry.f = kit.models;
			boolean anyHead = false;
			for (int headModel : kit.chatheadModels)
			{
				anyHead |= headModel != -1;
			}
			if (anyHead)
			{
				entry.ch = kit.chatheadModels;
			}
			entry.cf = kit.recolorToFind;
			entry.cr = kit.recolorToReplace;
			entry.tf = kit.retextureToFind;
			entry.tr = kit.retextureToReplace;

			dump.kits.put(Integer.toString(file.getFileId()), entry);
		}
	}

	/** Mirrors com.follower.ui.GameFontRepository's expected format. */
	static class GlyphEntry
	{
		int w;
		int h;
		int ox;
		int oy;
		/** Base64 of one byte per pixel, row-major: 0 = off, nonzero = on. */
		String mask;
	}

	static class FontEntry
	{
		/** The sprite archive id - the same id widgets report as getFontId(). */
		int id;
		/** Resolved archive name (p12_full, b12_full, ...) or null if unknown. */
		String name;
		int ascent;
		int[] advances;
		java.util.List<GlyphEntry> glyphs = new java.util.ArrayList<>();
	}

	/** Candidate font archive names, resolved against name hashes. */
	private static final String[] FONT_NAMES = {
		"p11_full", "p12_full", "b12_full", "q8_full",
		"quill_oblique_large", "quill_caps_large", "lunar_alphabet", "lunar_alphabet_lrg",
		"barbassault_font", "surok_font", "verdana_11pt_regular", "verdana_11pt_bold",
		"verdana_13pt_regular", "verdana_13pt_bold", "verdana_15pt_regular",
	};

	static class FontDump
	{
		int version = FORMAT_VERSION;
		String cacheRevision;
		java.util.List<FontEntry> fonts = new java.util.ArrayList<>();
	}

	/**
	 * The game's text is GLYPH BITMAPS from the cache, not a TTF - no system
	 * font rasterizer reproduces it exactly. Metrics (per-char advances,
	 * ascent) live in the FONTS index keyed by name hash; the glyph images are
	 * the sprite archive with the SAME name hash, and that sprite archive's id
	 * is precisely the id widgets report from {@code getFontId()}.
	 */
	private static void dumpFonts(Store store, FontDump dump) throws IOException
	{
		Storage storage = store.getStorage();
		Index fontIndex = store.getIndex(IndexType.FONTS);
		Index spriteIndex = store.getIndex(IndexType.SPRITES);
		net.runelite.cache.definitions.loaders.FontLoader fontLoader =
			new net.runelite.cache.definitions.loaders.FontLoader();
		net.runelite.cache.definitions.loaders.SpriteLoader spriteLoader =
			new net.runelite.cache.definitions.loaders.SpriteLoader();

		for (Archive fontArchive : fontIndex.getArchives())
		{
			byte[] metricData = storage.loadArchive(fontArchive);
			FSFile metricFile = fontArchive.getFiles(metricData).findFile(0);
			net.runelite.cache.definitions.FontDefinition metrics =
				fontLoader.load(metricFile.getContents());

			Archive glyphArchive = null;
			for (Archive candidate : spriteIndex.getArchives())
			{
				if (candidate.getNameHash() == fontArchive.getNameHash())
				{
					glyphArchive = candidate;
					break;
				}
			}
			if (glyphArchive == null)
			{
				System.out.printf("Font archive %d has no matching glyph sprites%n",
					fontArchive.getArchiveId());
				continue;
			}

			FSFile glyphFile = glyphArchive.getFiles(storage.loadArchive(glyphArchive)).findFile(0);
			net.runelite.cache.definitions.SpriteDefinition[] glyphs =
				spriteLoader.load(glyphArchive.getArchiveId(), glyphFile.getContents());

			FontEntry entry = new FontEntry();
			entry.id = glyphArchive.getArchiveId();
			entry.ascent = metrics.getAscent();
			entry.advances = metrics.getAdvances();
			for (String candidate : FONT_NAMES)
			{
				if (net.runelite.cache.util.Djb2.hash(candidate) == fontArchive.getNameHash())
				{
					entry.name = candidate;
					break;
				}
			}

			for (net.runelite.cache.definitions.SpriteDefinition glyph : glyphs)
			{
				GlyphEntry g = new GlyphEntry();
				g.w = glyph.getWidth();
				g.h = glyph.getHeight();
				g.ox = glyph.getOffsetX();
				g.oy = glyph.getOffsetY();
				int[] pixels = glyph.getPixels();
				byte[] mask = new byte[g.w * g.h];
				for (int i = 0; i < mask.length && pixels != null && i < pixels.length; i++)
				{
					mask[i] = (byte) (pixels[i] != 0 ? 1 : 0);
				}
				g.mask = java.util.Base64.getEncoder().encodeToString(mask);
				entry.glyphs.add(g);
			}

			dump.fonts.add(entry);
			System.out.printf("Font id=%d name=%s: %d glyphs, %d advances, ascent %d%n",
				entry.id, entry.name, entry.glyphs.size(),
				entry.advances == null ? 0 : entry.advances.length, entry.ascent);
		}
	}

	/**
	 * Spotanims are the game's "graphics": teleport swirls, spell impacts, the
	 * home teleport's rune circle. Each maps a graphic id to a model, the
	 * animation that plays it, scaling, rotation, recolours and lighting tweaks.
	 * The live client API exposes none of this, which is why it is dumped.
	 */
	private static void dumpSpotAnims(Store store, SpotAnimDump dump) throws IOException
	{
		Storage storage = store.getStorage();
		Index index = store.getIndex(IndexType.CONFIGS);
		Archive archive = index.getArchive(ConfigType.SPOTANIM.getId());

		byte[] archiveData = storage.loadArchive(archive);
		ArchiveFiles files = archive.getFiles(archiveData);
		SpotAnimLoader loader = new SpotAnimLoader();

		for (FSFile file : files.getFiles())
		{
			SpotAnimDefinition def = loader.load(file.getFileId(), file.getContents());
			if (def == null || def.modelId <= 0)
			{
				continue;
			}

			SpotAnimEntry entry = new SpotAnimEntry();
			entry.m = def.modelId;
			entry.a = def.animationId;
			// Defaults are omitted so the file stays small: 128 scale is 100%,
			// rotation 0, ambient/contrast 0.
			entry.rx = def.resizeX == 128 ? null : def.resizeX;
			entry.ry = def.resizeY == 128 ? null : def.resizeY;
			entry.rot = def.rotaton == 0 ? null : def.rotaton;
			entry.am = def.ambient == 0 ? null : def.ambient;
			entry.co = def.contrast == 0 ? null : def.contrast;
			entry.cf = def.recolorToFind;
			entry.cr = def.recolorToReplace;
			entry.tf = def.textureToFind;
			entry.tr = def.textureToReplace;

			dump.spotanims.put(Integer.toString(file.getFileId()), entry);
		}
	}

	private static Path defaultCacheDir()
	{
		Path runeliteCache = Paths.get(System.getProperty("user.home"),
			".runelite", "jagexcache", "oldschool", "LIVE");
		if (Files.isDirectory(runeliteCache))
		{
			return runeliteCache;
		}

		// Fall back to the standalone client's cache.
		return Paths.get(System.getProperty("user.home"), "jagexcache", "oldschool", "LIVE");
	}
}

package com.follower.tools;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.loaders.NpcLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Looks a name up in the cache, so a question about what an NPC actually is
 * gets answered by the game rather than by memory.
 *
 * <p>Prints every NPC whose name contains the text, with its id, combat level
 * and the options on its right-click menu - enough to tell a boss from a pet
 * from a piece of scenery that happens to share a name.
 *
 *   gradlew runNpcFind --args="brutus [cacheDir]"
 */
public class NpcFind
{
	public static void main(String[] args) throws Exception
	{
		if (args.length < 1)
		{
			System.out.println("usage: runNpcFind --args=\"<name fragment> [cacheDir]\"");
			return;
		}
		String wanted = args[0].toLowerCase(Locale.ROOT);
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");

		List<NpcDefinition> hits = new ArrayList<>();
		int total = 0;
		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index index = store.getIndex(IndexType.CONFIGS);
			Archive archive = index.getArchive(ConfigType.NPC.getId());
			byte[] data = storage.loadArchive(archive);
			ArchiveFiles files = archive.getFiles(data);
			NpcLoader loader = new NpcLoader();
			for (FSFile file : files.getFiles())
			{
				NpcDefinition npc = loader.load(file.getFileId(), file.getContents());
				total++;
				if (npc.name != null && !"null".equals(npc.name)
					&& npc.name.toLowerCase(Locale.ROOT).contains(wanted))
				{
					hits.add(npc);
				}
			}
		}

		System.out.println("Searched " + total + " NPCs for \"" + args[0] + "\"");
		System.out.println();
		if (hits.isEmpty())
		{
			System.out.println("  no NPC in the cache has that in its name");
			return;
		}
		for (NpcDefinition npc : hits)
		{
			System.out.println("  id " + npc.id + "  \"" + npc.name + "\""
				+ "  combat " + npc.combatLevel
				+ "  size " + npc.size
				+ (npc.varbitId == -1 ? "" : "  varbit " + npc.varbitId)
				+ (npc.varpIndex == -1 ? "" : "  varp " + npc.varpIndex)
				+ (npc.configs == null ? ""
					: "  becomes " + java.util.Arrays.toString(npc.configs)));
		}
	}
}

package com.follower.tools;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.loaders.NpcLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Lists every NPC the game treats as a pet, so a rule can greet them by name
 * without the list being guesswork.
 *
 * <p>Written after a cat called Trotters walked past a follower that had been
 * told to look for NPCs named "Cat" and "Kitten". Guessing names one encounter
 * at a time never converges; the game already knows which NPCs are pets.
 *
 * <p>The signal is not a heuristic: {@code NpcDefinition.isFollower} is the
 * game's own flag for an NPC that trots along behind a player. Nothing has to
 * be inferred from names or options.
 *
 * <pre>
 *   gradlew runPetProbe
 * </pre>
 */
public class PetProbe
{
	public static void main(String[] args) throws IOException
	{
		Path cacheDir = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");

		// An optional name fragment turns this into a lookup: what IS that NPC,
		// and does the game consider it a follower?
		String search = null;
		for (String arg : args)
		{
			if (arg.startsWith("find="))
			{
				search = arg.substring(5).toLowerCase();
			}
		}

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);
			Archive archive = configs.getArchive(ConfigType.NPC.getId());
			ArchiveFiles files = archive.getFiles(storage.loadArchive(archive));
			NpcLoader loader = new NpcLoader();

			List<String> pets = new ArrayList<>();
			List<String> cats = new ArrayList<>();
			int total = 0;

			for (FSFile file : files.getFiles())
			{
				total++;
				NpcDefinition def = loader.load(file.getFileId(), file.getContents());
				if (def == null || def.name == null || "null".equals(def.name))
				{
					continue;
				}

				String lower = def.name.toLowerCase();
				if (search != null && lower.contains(search))
				{
					System.out.printf("FOUND id %-6d %-28s isFollower=%s combatLevel=%d size=%d%n",
						def.id, def.name, def.isFollower, def.combatLevel, def.size);
				}
				boolean catLike = lower.contains("cat") || lower.contains("kitten");

				if (def.isFollower)
				{
					pets.add(def.name);
				}
				else if (catLike)
				{
					cats.add(def.name);
				}
			}

			java.util.Collections.sort(pets);
			java.util.Collections.sort(cats);

			System.out.printf("%d NPC definitions scanned%n%n", total);
			System.out.printf("--- %d flagged isFollower (pets) ---%n", pets.size());
			for (String name : dedupe(pets))
			{
				System.out.println("  " + name);
			}
			System.out.printf("%n--- %d more matching cat/kitten by name ---%n", cats.size());
			for (String name : dedupe(cats))
			{
				System.out.println("  " + name);
			}
		}
	}

	/** The same pet exists once per variant; the rule only needs the name. */
	private static List<String> dedupe(List<String> names)
	{
		List<String> unique = new ArrayList<>();
		String last = null;
		for (String name : names)
		{
			if (!name.equals(last))
			{
				unique.add(name);
				last = name;
			}
		}
		return unique;
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.cache.AreaManager;
import net.runelite.cache.WorldMapManager;
import net.runelite.cache.definitions.AreaDefinition;
import net.runelite.cache.definitions.WorldMapElementDefinition;
import net.runelite.cache.fs.Store;
import net.runelite.cache.region.Position;

/**
 * Audits the location rules in phrases.json against the game's own world map.
 *
 * <p>The area rules were written with region ids computed from documented
 * coordinates, which is a guess wherever the documentation is loose. The cache
 * settles it: the world map's labels are {@link AreaDefinition}s carrying the
 * text the game draws ("Lumbridge", "Prifddinas"), and each is PLACED by a
 * {@link WorldMapElementDefinition} at a world position. Name plus position
 * gives the true region id for every named place in the game, with no walking
 * and nothing assumed.
 *
 * <pre>
 *   gradlew runAudit --args="&lt;phrases.json&gt; [cacheDir]"
 * </pre>
 *
 * <p>For each rule it prints the regions the game says that place occupies,
 * and flags any rule whose ids do not include them.
 */
public class RegionAudit
{
	/** Region id from world coordinates, exactly as the client computes it. */
	private static int regionOf(int x, int y)
	{
		return (x >> 6) * 256 + (y >> 6);
	}

	public static void main(String[] args) throws IOException
	{
		Path phrases = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "phrases.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		if (!Files.isRegularFile(phrases))
		{
			System.err.println("phrases.json not found: " + phrases);
			System.exit(1);
		}

		// name (lowercased) -> every region the map labels with it
		Map<String, TreeSet<Integer>> mapRegions = new HashMap<>();
		Map<String, TreeSet<String>> mapCoords = new HashMap<>();
		// the reverse: region -> every label the map draws inside it
		Map<Integer, TreeSet<String>> labelsByRegion = new HashMap<>();

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();

			AreaManager areas = new AreaManager(store);
			areas.load();
			Map<Integer, AreaDefinition> byId = new HashMap<>();
			for (AreaDefinition area : areas.getAreas())
			{
				byId.put(area.getId(), area);
			}

			WorldMapManager worldMap = new WorldMapManager(store);
			worldMap.load();

			for (WorldMapElementDefinition element : worldMap.getElements())
			{
				AreaDefinition area = byId.get(element.getAreaDefinitionId());
				Position at = element.getWorldPosition();
				if (area == null || area.getName() == null || at == null)
				{
					continue;
				}
				String key = normalise(area.getName());
				int region = regionOf(at.getX(), at.getY());
				mapRegions.computeIfAbsent(key, k -> new TreeSet<>()).add(region);
				mapCoords.computeIfAbsent(key, k -> new TreeSet<>())
					.add(at.getX() + "," + at.getY());
				labelsByRegion.computeIfAbsent(region, k -> new TreeSet<>()).add(key);
			}
		}

		System.out.printf("World map carries %d distinct labelled place names%n", mapRegions.size());

		JsonObject root;
		try (Reader reader = Files.newBufferedReader(phrases, StandardCharsets.UTF_8))
		{
			root = new Gson().fromJson(reader, JsonObject.class);
		}

		int checked = 0;
		int confirmed = 0;
		List<String> problems = new ArrayList<>();

		for (JsonElement element : root.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			if (!"area".equals(optString(rule, "group")))
			{
				continue;
			}
			JsonObject when = rule.getAsJsonObject("when");
			if (when == null || !when.has("regions"))
			{
				continue;
			}

			String id = optString(rule, "id");
			List<Integer> ruleRegions = new ArrayList<>();
			for (JsonElement r : when.getAsJsonArray("regions"))
			{
				ruleRegions.add(r.getAsInt());
			}

			// "area-tree-gnome-stronghold" -> "tree gnome stronghold"
			String place = normalise(id.startsWith("area-") ? id.substring(5).replace('-', ' ') : id);
			String label = matchLabel(mapRegions.keySet(), place);
			checked++;

			if (label == null)
			{
				problems.add(String.format("%-24s NO MAP LABEL%s%s",
					id, suggest(mapRegions, place), inside(labelsByRegion, ruleRegions)));
				continue;
			}

			TreeSet<Integer> truth = mapRegions.get(label);
			// A label marks where the map draws its TEXT, near the middle of
			// the place - a town spans several regions, so a rule region one
			// region away is the same town, not an error. Only a rule that
			// lands well clear of every label is actually suspect.
			int best = Integer.MAX_VALUE;
			for (int region : ruleRegions)
			{
				for (int labelled : truth)
				{
					best = Math.min(best, regionDistance(region, labelled));
				}
			}

			if (best == 0)
			{
				confirmed++;
			}
			else if (best <= 1)
			{
				confirmed++;
				System.out.printf("  %-24s adjacent to \"%s\" %s - same place, fine%n",
					id, label, truth);
			}
			else
			{
				problems.add(String.format("%-24s rule %s is %d regions from \"%s\" %s at %s%s",
					id, ruleRegions, best, label, truth, mapCoords.get(label),
					inside(labelsByRegion, ruleRegions)));
			}
		}

		System.out.printf("%n%d location rules checked, %d confirmed against the map%n",
			checked, confirmed);
		if (problems.isEmpty())
		{
			System.out.println("No mismatches.");
			return;
		}
		System.out.printf("%n%d need attention:%n", problems.size());
		for (String problem : problems)
		{
			System.out.println("  " + problem);
		}
	}

	/**
	 * Map labels are drawn text: they carry {@code <br>} line breaks and
	 * punctuation ("Seers'<br>Village"). Flatten to bare lowercase words so a
	 * rule id can be compared to them.
	 */
	private static String normalise(String text)
	{
		return text.toLowerCase()
			.replace("<br>", " ")
			.replaceAll("[^a-z0-9]+", " ")
			.trim();
	}

	/**
	 * What the map actually labels INSIDE the rule's own regions - the
	 * decisive check for underground places, whose surface entrance label
	 * sits regions away from the area the player is standing in.
	 */
	private static String inside(Map<Integer, TreeSet<String>> labelsByRegion, List<Integer> regions)
	{
		TreeSet<String> found = new TreeSet<>();
		for (int region : regions)
		{
			TreeSet<String> here = labelsByRegion.get(region);
			if (here != null)
			{
				found.addAll(here);
			}
		}
		return found.isEmpty()
			? "\n" + " ".repeat(29) + "nothing labelled inside the rule's own regions"
			: "\n" + " ".repeat(29) + "INSIDE those regions the map labels: " + found;
	}

	/** Labels sharing the place's first word, to steer a manual check. */
	private static String suggest(Map<String, TreeSet<Integer>> mapRegions, String place)
	{
		String first = place.split(" ")[0];
		List<String> near = new ArrayList<>();
		for (Map.Entry<String, TreeSet<Integer>> entry : mapRegions.entrySet())
		{
			if (entry.getKey().contains(first))
			{
				near.add("\"" + entry.getKey() + "\" " + entry.getValue());
			}
			if (near.size() == 3)
			{
				break;
			}
		}
		return near.isEmpty() ? " - verify this one in game" : " - map has " + String.join(", ", near);
	}

	/** Chebyshev distance in regions: 0 same, 1 touching, more is far apart. */
	private static int regionDistance(int a, int b)
	{
		int dx = Math.abs((a / 256) - (b / 256));
		int dy = Math.abs((a % 256) - (b % 256));
		return Math.max(dx, dy);
	}

	/**
	 * The map label that best names a rule's place: exact first, then the
	 * most specific label containing the whole place name, then the longest
	 * label the place name contains ("east ardougne" -> "Ardougne").
	 *
	 * <p>Short labels are excluded from that last case. The map has one and
	 * two character labels, and letting those match by containment matched
	 * nearly every rule to the same stray marker.
	 */
	private static String matchLabel(java.util.Set<String> labels, String place)
	{
		if (labels.contains(place))
		{
			return place;
		}
		String best = null;
		for (String label : labels)
		{
			if (label.contains(place) && (best == null || label.length() < best.length()))
			{
				best = label;
			}
		}
		if (best != null)
		{
			return best;
		}
		for (String label : labels)
		{
			if (label.length() >= 5 && place.contains(label)
				&& (best == null || label.length() > best.length()))
			{
				best = label;
			}
		}
		return best;
	}

	private static String optString(JsonObject object, String key)
	{
		return object.has(key) && object.get(key).isJsonPrimitive()
			? object.get(key).getAsString() : null;
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Pattern;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.ItemDefinition;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.loaders.ItemLoader;
import net.runelite.cache.definitions.loaders.NpcLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Checks that every NPC name and item id the rules key on exists in the game.
 *
 * <p>These two are the silent failures of the rule file. A rule that watches
 * for an NPC called "Hans " with a trailing space, or "Guard" where the game
 * says "Guard dog", never fires and never says why - it is indistinguishable
 * from a rule whose trigger simply has not happened yet. The same holds for an
 * itemEquipped id that is one digit out.
 *
 * <p>Names are matched the way the plugin matches them: case-insensitively,
 * whole, with {@code *} as a wildcard. So this asks exactly the question the
 * plugin will ask at runtime, against the same cache it will ask it of.
 *
 * <pre>
 *   gradlew runTargetAudit --args="&lt;phrases.json&gt; [cacheDir]"
 * </pre>
 */
public class RuleTargetAudit
{
	public static void main(String[] args) throws IOException
	{
		if (args.length < 1)
		{
			System.out.println("usage: runTargetAudit --args=\"<phrases.json> [cacheDir]\"");
			return;
		}
		Path phrases = Paths.get(args[0]);
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");

		Set<String> npcNames = new HashSet<>();
		Map<Integer, String> items = new TreeMap<>();
		Set<Integer> npcIds = new HashSet<>();

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);

			Archive npcArchive = configs.getArchive(ConfigType.NPC.getId());
			ArchiveFiles npcFiles = npcArchive.getFiles(storage.loadArchive(npcArchive));
			NpcLoader npcLoader = new NpcLoader();
			for (FSFile file : npcFiles.getFiles())
			{
				NpcDefinition npc = npcLoader.load(file.getFileId(), file.getContents());
				if (npc.name != null && !"null".equals(npc.name))
				{
					npcNames.add(normalise(npc.name));
					npcIds.add(npc.id);
				}
			}

			Archive itemArchive = configs.getArchive(ConfigType.ITEM.getId());
			ArchiveFiles itemFiles = itemArchive.getFiles(storage.loadArchive(itemArchive));
			ItemLoader itemLoader = new ItemLoader();
			for (FSFile file : itemFiles.getFiles())
			{
				ItemDefinition item = itemLoader.load(file.getFileId(), file.getContents());
				if (item.name != null && !"null".equals(item.name))
				{
					items.put(item.id, item.name);
				}
			}
		}

		System.out.printf("cache holds %d named NPCs and %d named items%n%n",
			npcNames.size(), items.size());

		JsonObject file;
		try (Reader reader = Files.newBufferedReader(phrases, StandardCharsets.UTF_8))
		{
			file = new Gson().fromJson(reader, JsonObject.class);
		}

		Map<String, List<String>> namesByRule = new LinkedHashMap<>();
		Map<String, List<Integer>> idsByRule = new LinkedHashMap<>();
		Map<String, List<Integer>> npcIdsByRule = new LinkedHashMap<>();
		for (JsonElement element : file.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			collect(rule.get("id").getAsString(), rule.getAsJsonObject("when"),
				namesByRule, idsByRule, npcIdsByRule);
		}

		int checkedNames = 0;
		List<String> deadNames = new ArrayList<>();
		for (Map.Entry<String, List<String>> entry : namesByRule.entrySet())
		{
			for (String name : entry.getValue())
			{
				checkedNames++;
				if (!matchesAny(name, npcNames))
				{
					deadNames.add(String.format("%-28s \"%s\"", entry.getKey(), name));
				}
			}
		}

		int checkedItems = 0;
		List<String> deadItems = new ArrayList<>();
		for (Map.Entry<String, List<Integer>> entry : idsByRule.entrySet())
		{
			for (int id : entry.getValue())
			{
				checkedItems++;
				if (!items.containsKey(id))
				{
					deadItems.add(String.format("%-28s item %d", entry.getKey(), id));
				}
			}
		}

		int checkedNpcIds = 0;
		List<String> deadNpcIds = new ArrayList<>();
		for (Map.Entry<String, List<Integer>> entry : npcIdsByRule.entrySet())
		{
			for (int id : entry.getValue())
			{
				checkedNpcIds++;
				if (!npcIds.contains(id))
				{
					deadNpcIds.add(String.format("%-28s npc %d", entry.getKey(), id));
				}
			}
		}

		report("NPC names", checkedNames, deadNames,
			"these rules watch for an NPC the game does not have, so they can never fire");
		report("item ids", checkedItems, deadItems,
			"these rules watch for an item that does not exist");
		report("NPC ids", checkedNpcIds, deadNpcIds,
			"these rules watch for an NPC id that does not exist");
	}

	private static void report(String what, int checked, List<String> dead, String why)
	{
		System.out.printf("%d %s checked, %d dead%n", checked, what, dead.size());
		if (dead.isEmpty())
		{
			System.out.println("  all resolve\n");
			return;
		}
		System.out.println("  " + why + ":");
		for (String line : dead)
		{
			System.out.println("    " + line);
		}
		System.out.println();
	}

	private static void collect(String ruleId, JsonObject condition,
		Map<String, List<String>> names, Map<String, List<Integer>> items,
		Map<String, List<Integer>> npcIds)
	{
		if (condition == null)
		{
			return;
		}
		JsonElement typeElement = condition.get("type");
		String type = typeElement == null ? "" : typeElement.getAsString().toLowerCase(Locale.ROOT);

		if (type.equals("npcspawn") || type.equals("npcdespawn") || type.equals("npcnearby")
			|| type.equals("npckill"))
		{
			JsonArray list = condition.getAsJsonArray("names");
			if (list != null)
			{
				for (JsonElement name : list)
				{
					names.computeIfAbsent(ruleId, key -> new ArrayList<>())
						.add(name.getAsString());
				}
			}
			JsonArray ids = condition.getAsJsonArray("ids");
			if (ids != null)
			{
				for (JsonElement id : ids)
				{
					npcIds.computeIfAbsent(ruleId, key -> new ArrayList<>())
						.add(id.getAsInt());
				}
			}
		}
		if (type.equals("itemequipped"))
		{
			JsonArray ids = condition.getAsJsonArray("ids");
			if (ids != null)
			{
				for (JsonElement id : ids)
				{
					items.computeIfAbsent(ruleId, key -> new ArrayList<>())
						.add(id.getAsInt());
				}
			}
		}

		JsonArray children = condition.getAsJsonArray("conditions");
		if (children != null)
		{
			for (JsonElement child : children)
			{
				collect(ruleId, child.getAsJsonObject(), names, items, npcIds);
			}
		}
	}

	/** The plugin's own matching: whole-name, case-insensitive, {@code *} wildcards. */
	private static boolean matchesAny(String name, Set<String> known)
	{
		String normalised = normalise(name);
		if (normalised.indexOf('*') < 0)
		{
			return known.contains(normalised);
		}
		StringBuilder pattern = new StringBuilder();
		for (String literal : normalised.split("\\*", -1))
		{
			if (pattern.length() > 0)
			{
				pattern.append(".*");
			}
			pattern.append(Pattern.quote(literal));
		}
		Pattern compiled = Pattern.compile(pattern.toString());
		for (String candidate : known)
		{
			if (compiled.matcher(candidate).matches())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The game pads some names with non-breaking spaces; the plugin strips them,
	 * so this has to as well or the comparison is not the one that will run.
	 * Written as a code point: the literal does not survive being carried
	 * through tooling, which is how it arrived here broken the first time.
	 */
	private static String normalise(String name)
	{
		return name.replace((char) 0x00A0, ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.follower.tools;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.ObjectDefinition;
import net.runelite.cache.definitions.SequenceDefinition;
import net.runelite.cache.definitions.loaders.NpcLoader;
import net.runelite.cache.definitions.loaders.ObjectLoader;
import net.runelite.cache.definitions.loaders.SequenceLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Checks the names and ids hardcoded in the PLUGIN's own Java against the game.
 *
 * <p>{@link com.follower.tools.RuleTargetAudit} covers the rule file; this
 * covers the other half, which is just as able to fail silently. The errand
 * controller looks for scene objects by name - "Bank booth", "Forester's
 * Campfire" - and an errand whose name matches nothing simply never happens.
 * There is no error, no log line, and nothing to distinguish it from an errand
 * that has not been rolled yet.
 *
 * <p>The pose constants have the same shape of risk one level down: a pose id
 * that is not a sequence in the cache leaves the follower standing still, or
 * sliding along in its idle animation.
 *
 * <pre>
 *   gradlew runSceneAudit
 * </pre>
 */
public class SceneNameAudit
{
	/** Object names ErrandController searches the scene for. */
	private static final String[] OBJECT_NAMES = {
		"Altar", "Bank booth", "Bank chest", "Grand Exchange booth",
		"Fire", "Campfire", "Forester's Campfire",
	};

	/** NPC names it searches for. */
	private static final String[] NPC_NAMES = {
		"Banker", "Grand Exchange Clerk", "Cat", "Kitten", "Stray dog",
	};

	/** PlayerPose, the standard unarmed set every fallback leans on. */
	private static final int[][] POSES = {
		{808, 0}, {819, 0}, {824, 0}, {820, 0}, {821, 0}, {822, 0}, {823, 0},
	};

	private static final String[] POSE_NAMES = {
		"IDLE", "WALK", "RUN", "TURN_180", "SIDESTEP_LEFT", "SIDESTEP_RIGHT", "IDLE_TURN",
	};

	public static void main(String[] args) throws IOException
	{
		Path cacheDir = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");

		Set<String> objects = new HashSet<>();
		Set<String> npcs = new HashSet<>();
		Set<Integer> sequences = new HashSet<>();

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);

			Archive objectArchive = configs.getArchive(ConfigType.OBJECT.getId());
			ArchiveFiles objectFiles = objectArchive.getFiles(storage.loadArchive(objectArchive));
			ObjectLoader objectLoader = new ObjectLoader();
			for (FSFile file : objectFiles.getFiles())
			{
				ObjectDefinition object = objectLoader.load(file.getFileId(), file.getContents());
				if (object.getName() != null && !"null".equals(object.getName()))
				{
					objects.add(normalise(object.getName()));
				}
			}

			Archive npcArchive = configs.getArchive(ConfigType.NPC.getId());
			ArchiveFiles npcFiles = npcArchive.getFiles(storage.loadArchive(npcArchive));
			NpcLoader npcLoader = new NpcLoader();
			for (FSFile file : npcFiles.getFiles())
			{
				NpcDefinition npc = npcLoader.load(file.getFileId(), file.getContents());
				if (npc.name != null && !"null".equals(npc.name))
				{
					npcs.add(normalise(npc.name));
				}
			}

			Archive seqArchive = configs.getArchive(ConfigType.SEQUENCE.getId());
			ArchiveFiles seqFiles = seqArchive.getFiles(storage.loadArchive(seqArchive));
			SequenceLoader seqLoader = new SequenceLoader();
			for (FSFile file : seqFiles.getFiles())
			{
				SequenceDefinition sequence = seqLoader.load(file.getFileId(), file.getContents());
				if (sequence != null)
				{
					sequences.add(file.getFileId());
				}
			}
		}

		System.out.printf("cache holds %d named objects, %d named NPCs, %d sequences%n%n",
			objects.size(), npcs.size(), sequences.size());

		List<String> dead = new ArrayList<>();

		System.out.println("errand scene objects:");
		for (String name : OBJECT_NAMES)
		{
			boolean found = objects.contains(normalise(name));
			System.out.printf("  %-24s %s%n", name, found ? "found" : "NOT IN THE GAME");
			if (!found)
			{
				dead.add("object \"" + name + "\"");
			}
		}

		System.out.println("\nerrand NPCs:");
		for (String name : NPC_NAMES)
		{
			boolean found = npcs.contains(normalise(name));
			System.out.printf("  %-24s %s%n", name, found ? "found" : "NOT IN THE GAME");
			if (!found)
			{
				dead.add("npc \"" + name + "\"");
			}
		}

		System.out.println("\nPlayerPose constants:");
		for (int i = 0; i < POSES.length; i++)
		{
			int id = POSES[i][0];
			boolean found = sequences.contains(id);
			System.out.printf("  %-16s %-6d %s%n", POSE_NAMES[i], id,
				found ? "found" : "NOT A SEQUENCE");
			if (!found)
			{
				dead.add("pose " + POSE_NAMES[i] + " (" + id + ")");
			}
		}

		System.out.println();
		if (dead.isEmpty())
		{
			System.out.println("everything the plugin hardcodes resolves against the cache");
		}
		else
		{
			System.out.println("THESE CANNOT EVER MATCH:");
			for (String line : dead)
			{
				System.out.println("  " + line);
			}
		}

		// A near-miss list is what actually helps when something is wrong.
		if (!dead.isEmpty())
		{
			System.out.println("\nnear misses in the cache:");
			for (String line : dead)
			{
				int quote = line.indexOf('"');
				if (quote < 0)
				{
					continue;
				}
				String wanted = normalise(line.substring(quote + 1, line.lastIndexOf('"')));
				String head = wanted.split(" ")[0];
				Set<String> pool = line.startsWith("object") ? objects : npcs;
				Set<String> near = new TreeSet<>();
				for (String candidate : pool)
				{
					if (candidate.contains(head))
					{
						near.add(candidate);
					}
				}
				System.out.printf("  %s -> %s%n", wanted,
					near.isEmpty() ? "(nothing similar)" : near);
			}
		}
	}

	private static String normalise(String name)
	{
		return name.replace((char) 0x00A0, ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.follower.tools;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.SequenceDefinition;
import net.runelite.cache.definitions.loaders.SequenceLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Prints what an animation id actually IS, so a number taken from anywhere
 * outside the game can be checked before it is trusted.
 *
 * <p>Weapon stances cannot be read from the cache, so ids sometimes have to
 * come from elsewhere. The animation itself still lives in the cache though:
 * an id that does not exist there is simply wrong, and the frame count and
 * duration say whether what does exist is the right shape for the job.
 *
 * <pre>
 *   gradlew runSeqInfo --args="7508 7509 7510 7511"
 * </pre>
 */
public class SequenceInfo
{
	public static void main(String[] args) throws IOException
	{
		Path cacheDir = Paths.get(System.getProperty("user.home"),
			".runelite", "jagexcache", "oldschool", "LIVE");

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);
			Archive archive = configs.getArchive(ConfigType.SEQUENCE.getId());
			ArchiveFiles files = archive.getFiles(storage.loadArchive(archive));
			SequenceLoader loader = new SequenceLoader();

			for (String arg : args)
			{
				int id;
				try
				{
					id = Integer.parseInt(arg.trim());
				}
				catch (NumberFormatException e)
				{
					continue;
				}

				FSFile file = files.findFile(id);
				if (file == null)
				{
					System.out.printf("%-6d DOES NOT EXIST - the id is wrong%n", id);
					continue;
				}

				SequenceDefinition def = loader.load(id, file.getContents());
				int frames = def.frameIDs == null ? 0 : def.frameIDs.length;
				int ticks = 0;
				if (def.frameLengths != null)
				{
					for (int length : def.frameLengths)
					{
						ticks += length;
					}
				}
				// frameStep is NOT a stance/attack discriminator: pose
				// animations carry -1 just as attacks do, which is why the
				// follower has to loop them defensively. What this tool
				// actually proves is that an id EXISTS and how long it runs.
				System.out.printf("%-6d %2d frames, %3d client ticks (%.2fs), frameStep %d%n",
					id, frames, ticks, ticks * 0.02, def.frameStep);
			}
		}
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import net.runelite.cache.IndexType;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * The last and broadest search for weapon stance data: item params, item
 * category and structs were all ruled out, but the cache library only names
 * the config archives it happens to know about. The pose table could sit in an
 * archive nobody has named.
 *
 * <p>So this looks everywhere, without assuming a format. Every archive of
 * every index, every file, scanned for 16-bit values matching the pose ids the
 * plugin has genuinely observed. A file holding two or more of them is a
 * stance record - the numbers are far too specific to co-occur by chance.
 *
 * <pre>
 *   gradlew runArchiveProbe --args="&lt;stances.json&gt;"
 * </pre>
 */
public class StanceArchiveProbe
{
	public static void main(String[] args) throws IOException
	{
		Path stancesFile = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "stances.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		JsonObject stances;
		try (Reader reader = Files.newBufferedReader(stancesFile, StandardCharsets.UTF_8))
		{
			stances = new Gson().fromJson(reader, JsonObject.class);
		}

		// Pose ids we have actually seen, and the triples they came in.
		Set<Integer> poseIds = new TreeSet<>();
		Map<String, String> tripleOwner = new TreeMap<>();
		for (Map.Entry<String, JsonElement> entry : stances.entrySet())
		{
			JsonObject stance = entry.getValue().getAsJsonObject();
			int idle = stance.get("idle").getAsInt();
			int walk = stance.get("walk").getAsInt();
			int run = stance.get("run").getAsInt();
			if (idle > 0 && walk > 0)
			{
				poseIds.add(idle);
				poseIds.add(walk);
				poseIds.add(run);
				tripleOwner.put(idle + "/" + walk + "/" + run, entry.getKey());
			}
		}
		System.out.printf("looking for %d observed pose ids from %d stance classes%n",
			poseIds.size(), tripleOwner.size());

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();

			int filesScanned = 0;
			Map<String, Integer> hitsByArchive = new TreeMap<>();
			int reported = 0;

			for (Index index : store.getIndexes())
			{
				// Maps and models are megabytes of geometry; a 16-bit scan
				// there is all false positives and no signal.
				if (index.getId() == IndexType.MAPS.getNumber()
					|| index.getId() == IndexType.MODELS.getNumber()
					|| index.getId() == IndexType.SPRITES.getNumber()
					|| index.getId() == IndexType.MUSIC_TRACKS.getNumber())
				{
					continue;
				}

				for (Archive archive : index.getArchives())
				{
					byte[] raw;
					try
					{
						raw = storage.loadArchive(archive);
						if (raw == null)
						{
							continue;
						}
						ArchiveFiles files = archive.getFiles(raw);
						for (FSFile file : files.getFiles())
						{
							byte[] data = file.getContents();
							if (data == null || data.length < 4)
							{
								continue;
							}
							filesScanned++;
							Set<Integer> found = scan(data, poseIds);
							if (found.size() >= 2)
							{
								String key = "index " + index.getId() + " archive " + archive.getArchiveId();
								hitsByArchive.merge(key, 1, Integer::sum);
								if (reported++ < 12)
								{
									System.out.printf("  %s file %d holds %s%n",
										key, file.getFileId(), new TreeSet<>(found));
								}
							}
						}
					}
					catch (RuntimeException e)
					{
						// Encrypted or unreadable archive; nothing to learn here.
					}
				}
			}

			System.out.printf("%n%d files scanned%n", filesScanned);
			if (hitsByArchive.isEmpty())
			{
				System.out.println();
				System.out.println("Nothing anywhere in the cache pairs these pose ids.");
				System.out.println("Weapon stances are assembled by the client at runtime, not");
				System.out.println("stored as a table - observation really is the only source.");
			}
			else
			{
				System.out.println();
				System.out.println("archives holding paired pose ids:");
				for (Map.Entry<String, Integer> hit : hitsByArchive.entrySet())
				{
					System.out.printf("  %-28s %d files%n", hit.getKey(), hit.getValue());
				}
			}
		}
	}

	/** Every observed pose id appearing as a 16-bit big-endian value. */
	private static Set<Integer> scan(byte[] data, Set<Integer> poseIds)
	{
		Set<Integer> found = new HashSet<>();
		for (int i = 0; i + 1 < data.length; i++)
		{
			int value = ((data[i] & 0xFF) << 8) | (data[i + 1] & 0xFF);
			if (poseIds.contains(value))
			{
				found.add(value);
			}
		}
		return found;
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.EnumDefinition;
import net.runelite.cache.definitions.loaders.EnumLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Chases the one lead the broad archive sweep left standing: 41 ENUM files
 * hold two or more real pose ids. Enums are how the game keys tables off item
 * ids, so if a weapon's stance is data anywhere, it is here.
 *
 * <p>This decodes every enum properly rather than scanning bytes, and reports
 * any whose values include observed pose ids - with its key type, so we can
 * see whether it is keyed BY ITEM (which would give a direct weapon to stance
 * mapping) or by something else.
 *
 * <pre>
 *   gradlew runEnumProbe --args="&lt;stances.json&gt;"
 * </pre>
 */
public class StanceEnumProbe
{
	public static void main(String[] args) throws IOException
	{
		Path stancesFile = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "stances.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		JsonObject stances;
		try (Reader reader = Files.newBufferedReader(stancesFile, StandardCharsets.UTF_8))
		{
			stances = new Gson().fromJson(reader, JsonObject.class);
		}

		Set<Integer> poseIds = new TreeSet<>();
		Map<Integer, String> weaponStance = new HashMap<>();
		for (Map.Entry<String, JsonElement> entry : stances.entrySet())
		{
			JsonObject stance = entry.getValue().getAsJsonObject();
			int idle = stance.get("idle").getAsInt();
			int walk = stance.get("walk").getAsInt();
			int run = stance.get("run").getAsInt();
			if (idle <= 0 || walk <= 0)
			{
				continue;
			}
			poseIds.add(idle);
			poseIds.add(walk);
			poseIds.add(run);
			try
			{
				weaponStance.put(Integer.parseInt(entry.getKey()), idle + "/" + walk + "/" + run);
			}
			catch (NumberFormatException ignored)
			{
				// not an item id
			}
		}

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);
			Archive archive = configs.getArchive(ConfigType.ENUM.getId());
			ArchiveFiles files = archive.getFiles(storage.loadArchive(archive));
			EnumLoader loader = new EnumLoader();

			int total = 0;
			int interesting = 0;

			for (FSFile file : files.getFiles())
			{
				total++;
				EnumDefinition def = loader.load(file.getFileId(), file.getContents());
				if (def == null)
				{
					continue;
				}
				int[] vals = def.getIntVals();
				int[] keys = def.getKeys();
				if (vals == null || keys == null)
				{
					continue;
				}

				Set<Integer> found = new HashSet<>();
				for (int value : vals)
				{
					if (poseIds.contains(value))
					{
						found.add(value);
					}
				}
				if (found.size() < 2)
				{
					continue;
				}
				interesting++;

				// The decisive question: are the KEYS weapons we know? If an
				// enum keyed by item id maps our weapons to their real pose
				// ids, every weapon in the game resolves without observation.
				int keyedWeapons = 0;
				int agreeing = 0;
				for (int i = 0; i < keys.length && i < vals.length; i++)
				{
					String known = weaponStance.get(keys[i]);
					if (known != null)
					{
						keyedWeapons++;
						if (known.startsWith(vals[i] + "/") || known.contains("/" + vals[i]))
						{
							agreeing++;
						}
					}
				}

				System.out.printf("enum %-6d key=%-12s val=%-12s size=%-5d pose ids %s%n",
					def.getId(), def.getKeyType(), def.getValType(), def.getSize(),
					new TreeSet<>(found));
				if (keyedWeapons > 0)
				{
					System.out.printf("        keys include %d weapons we know, %d agree%s%n",
						keyedWeapons, agreeing,
						agreeing == keyedWeapons ? "   <-- THIS MAPS WEAPONS TO POSES" : "");
				}
			}

			System.out.printf("%n%d enums, %d hold two or more real pose ids%n", total, interesting);
		}
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.cache.ItemManager;
import net.runelite.cache.definitions.ItemDefinition;
import net.runelite.cache.fs.Store;

/**
 * Works out whether a weapon's animations can be READ from the cache instead
 * of learned by watching players wield it.
 *
 * <p>The plugin currently learns stances by observation, which means a weapon
 * nobody has been seen holding falls back to unarmed. The game itself clearly
 * does not need to watch anyone, so the data must be in the cache somewhere -
 * the likeliest home being item params (opcode 249), a free-form int-keyed
 * map. This correlates every learned stance against every param of that item:
 * if some param consistently holds the idle id, that param IS the idle pose
 * and every weapon in the game can be resolved without teaching.
 *
 * <pre>
 *   gradlew runProbe --args="&lt;stances.json&gt; [cacheDir]"
 * </pre>
 */
public class StanceParamProbe
{
	/** The stance fields we would like to resolve, in the JSON's own names. */
	private static final String[] FIELDS = {
		"idle", "walk", "run", "walkBack", "walkLeft", "walkRight",
		"turnLeft", "turnRight", "attack",
	};

	public static void main(String[] args) throws IOException
	{
		Path stancesFile = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "stances.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		JsonObject stances;
		try (Reader reader = Files.newBufferedReader(stancesFile, StandardCharsets.UTF_8))
		{
			stances = new Gson().fromJson(reader, JsonObject.class);
		}
		System.out.printf("%d learned weapons to correlate%n", stances.size());

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			ItemManager items = new ItemManager(store);
			items.load();

			Map<Integer, ItemDefinition> byId = new HashMap<>();
			for (ItemDefinition item : items.getItems())
			{
				if (item != null)
				{
					byId.put(item.id, item);
				}
			}

			// paramKey -> field -> how many weapons agree
			Map<Integer, Map<String, Integer>> hits = new TreeMap<>();
			Map<Integer, Integer> paramSeen = new TreeMap<>();
			int withParams = 0;
			int examined = 0;

			for (Map.Entry<String, JsonElement> entry : stances.entrySet())
			{
				int weaponId;
				try
				{
					weaponId = Integer.parseInt(entry.getKey());
				}
				catch (NumberFormatException e)
				{
					continue;
				}
				if (weaponId <= 0)
				{
					continue;   // the unarmed baseline is not an item
				}
				ItemDefinition item = byId.get(weaponId);
				if (item == null)
				{
					continue;
				}
				examined++;
				Map<Integer, Object> params = item.params;
				if (params == null || params.isEmpty())
				{
					continue;
				}
				withParams++;

				JsonObject stance = entry.getValue().getAsJsonObject();
				for (Map.Entry<Integer, Object> param : params.entrySet())
				{
					paramSeen.merge(param.getKey(), 1, Integer::sum);
					if (!(param.getValue() instanceof Integer))
					{
						continue;
					}
					int value = (Integer) param.getValue();
					for (String field : FIELDS)
					{
						if (!stance.has(field))
						{
							continue;
						}
						int want = stance.get(field).getAsInt();
						if (want > 0 && want == value)
						{
							hits.computeIfAbsent(param.getKey(), k -> new TreeMap<>())
								.merge(field, 1, Integer::sum);
						}
					}
				}
			}

			System.out.printf("%d weapons found in the cache, %d of them carry params%n",
				examined, withParams);

			if (hits.isEmpty())
			{
				System.out.println();
				System.out.println("NO param on any weapon matched any learned animation id.");
				System.out.println("Weapon poses are not stored in item params - they live in");
				System.out.println("the weapon-type structs the combat scripts read, which is a");
				System.out.println("different lookup entirely.");
			}
			else
			{
				System.out.println();
				System.out.println("param -> field agreement (param seen on N weapons):");
				for (Map.Entry<Integer, Map<String, Integer>> hit : hits.entrySet())
				{
					System.out.printf("  param %-6d seen %-4d  %s%n",
						hit.getKey(), paramSeen.get(hit.getKey()), hit.getValue());
				}
			}

			// Stances are clearly shared between weapons - a harpoon and a mace
			// use the same one - so the real question is which cache field
			// names that GROUP. Whatever predicts it lets one observation
			// cover every weapon of that class.
			System.out.println();
			System.out.println("which field predicts the stance group?");

			Map<String, Map<String, String>> byCandidate = new TreeMap<>();
			Map<String, Integer> conflicts = new TreeMap<>();
			Map<String, Integer> covered = new TreeMap<>();

			for (Map.Entry<String, JsonElement> entry : stances.entrySet())
			{
				int weaponId;
				try
				{
					weaponId = Integer.parseInt(entry.getKey());
				}
				catch (NumberFormatException e)
				{
					continue;
				}
				ItemDefinition item = byId.get(weaponId);
				if (item == null || weaponId <= 0)
				{
					continue;
				}
				JsonObject stance = entry.getValue().getAsJsonObject();
				String signature = stance.get("idle").getAsInt() + "/"
					+ stance.get("walk").getAsInt() + "/" + stance.get("run").getAsInt();

				Map<String, String> candidates = new TreeMap<>();
				candidates.put("category", Integer.toString(item.category));
				if (item.params != null)
				{
					for (Map.Entry<Integer, Object> param : item.params.entrySet())
					{
						if (param.getValue() instanceof Integer)
						{
							candidates.put("param" + param.getKey(), param.getValue().toString());
						}
					}
				}

				for (Map.Entry<String, String> candidate : candidates.entrySet())
				{
					String key = candidate.getKey() + "=" + candidate.getValue();
					Map<String, String> seen = byCandidate
						.computeIfAbsent(candidate.getKey(), k -> new TreeMap<>());
					String previous = seen.putIfAbsent(key, signature);
					covered.merge(candidate.getKey(), 1, Integer::sum);
					if (previous != null && !previous.equals(signature))
					{
						conflicts.merge(candidate.getKey(), 1, Integer::sum);
					}
				}
			}

			for (Map.Entry<String, Map<String, String>> candidate : byCandidate.entrySet())
			{
				String name = candidate.getKey();
				int seen = covered.getOrDefault(name, 0);
				int bad = conflicts.getOrDefault(name, 0);
				if (seen < 30)
				{
					continue;   // too rare to conclude anything from
				}
				System.out.printf("  %-10s covers %-4d weapons in %-4d groups, %d disagreements%s%n",
					name, seen, candidate.getValue().size(), bad,
					bad == 0 ? "   <-- PREDICTS THE STANCE" : "");
			}
		}
	}

}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.cache.StructManager;
import net.runelite.cache.definitions.StructDefinition;
import net.runelite.cache.fs.Store;

/**
 * Second half of the stance question: item params turned out to hold combat
 * stats, not animations, so this asks whether the pose sets live in STRUCTs -
 * the cache's reusable property bags, which is where modern content keeps
 * this sort of table.
 *
 * <p>The test needs no assumptions: take the idle/walk/run triples the plugin
 * has genuinely observed and look for a struct carrying two or more of them
 * together. A struct that holds a real stance triple IS the weapon-type
 * record, and finding one would mean every weapon in the game could be
 * resolved without anybody teaching it.
 *
 * <pre>
 *   gradlew runStructProbe --args="&lt;stances.json&gt;"
 * </pre>
 */
public class StanceStructProbe
{
	public static void main(String[] args) throws IOException
	{
		Path stancesFile = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "stances.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		JsonObject stances;
		try (Reader reader = Files.newBufferedReader(stancesFile, StandardCharsets.UTF_8))
		{
			stances = new Gson().fromJson(reader, JsonObject.class);
		}

		// Every distinct pose id we have actually seen, and the triples.
		Set<Integer> poseIds = new TreeSet<>();
		Set<String> triples = new TreeSet<>();
		for (Map.Entry<String, JsonElement> entry : stances.entrySet())
		{
			JsonObject stance = entry.getValue().getAsJsonObject();
			int idle = stance.get("idle").getAsInt();
			int walk = stance.get("walk").getAsInt();
			int run = stance.get("run").getAsInt();
			if (idle > 0 && walk > 0)
			{
				poseIds.add(idle);
				poseIds.add(walk);
				poseIds.add(run);
				triples.add(idle + "/" + walk + "/" + run);
			}
		}
		System.out.printf("%d distinct pose ids across %d distinct stance sets%n",
			poseIds.size(), triples.size());
		System.out.println("stance sets observed: " + triples);

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			StructManager structs = new StructManager(store);
			structs.load();

			int examined = 0;
			int matched = 0;
			for (StructDefinition struct : structs.getStructs().values())
			{
				examined++;
				if (struct.params == null || struct.params.isEmpty())
				{
					continue;
				}
				Set<Integer> found = new HashSet<>();
				for (Object value : struct.params.values())
				{
					if (value instanceof Integer && poseIds.contains((Integer) value))
					{
						found.add((Integer) value);
					}
				}
				// One hit is coincidence - animation ids are just numbers. Two
				// or more from the same small set is a stance record.
				if (found.size() >= 2)
				{
					matched++;
					if (matched <= 15)
					{
						System.out.printf("  struct %-6d holds pose ids %s%n      params=%s%n",
							struct.id, new TreeSet<>(found), struct.params);
					}
				}
			}

			System.out.printf("%n%d structs examined, %d hold two or more observed pose ids%n",
				examined, matched);
			if (matched == 0)
			{
				System.out.println();
				System.out.println("Structs do not carry pose sets either. Weapon animations are");
				System.out.println("resolved by the client's own scripts at equip time, which the");
				System.out.println("cache does not expose as data - so observation stays the only");
				System.out.println("honest source.");
			}
		}
	}
}

package com.follower.tools;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.ItemDefinition;
import net.runelite.cache.definitions.loaders.ItemLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Asks the cache whether it knows which animation a weapon attacks with.
 *
 * <p>The stance library learns attack animations by watching them, which is why
 * a thousand weapons are still missing one. If the cache carried the mapping
 * directly there would be nothing to learn and nothing to ask anybody for, so
 * this checks rather than assumes: it prints the params and category of a few
 * named weapons, and reports how many items carry each param id, so a param
 * that looks like an animation can be spotted by its spread.
 *
 *   gradlew runWeaponAnims --args="4151 1333 841 11802 [cacheDir]"
 */
public class WeaponAnimProbe
{
	public static void main(String[] args) throws Exception
	{
		List<Integer> wanted = new ArrayList<>();
		Path cacheDir = null;
		for (String arg : args)
		{
			try
			{
				wanted.add(Integer.parseInt(arg));
			}
			catch (NumberFormatException notAnId)
			{
				cacheDir = Paths.get(arg);
			}
		}
		if (cacheDir == null)
		{
			cacheDir = Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");
		}

		Map<Integer, Integer> paramSpread = new LinkedHashMap<>();
		int items = 0;
		int withParams = 0;

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index index = store.getIndex(IndexType.CONFIGS);
			Archive archive = index.getArchive(ConfigType.ITEM.getId());
			byte[] data = storage.loadArchive(archive);
			ArchiveFiles files = archive.getFiles(data);
			ItemLoader loader = new ItemLoader();

			for (FSFile file : files.getFiles())
			{
				ItemDefinition item = loader.load(file.getFileId(), file.getContents());
				items++;
				if (item.params != null && !item.params.isEmpty())
				{
					withParams++;
					for (Object key : item.params.keySet())
					{
						int id = ((Number) key).intValue();
						paramSpread.merge(id, 1, Integer::sum);
					}
				}
				if (wanted.contains(item.id))
				{
					System.out.println("== " + item.id + "  " + item.name);
					System.out.println("   category : " + item.category);
					System.out.println("   params   : "
						+ (item.params == null ? "(none)" : item.params));
				}
			}
		}

		System.out.println();
		System.out.println("items scanned: " + items + ", carrying params: " + withParams);
		System.out.println("param ids by how many items use them:");
		paramSpread.entrySet().stream()
			.sorted((a, b) -> b.getValue() - a.getValue())
			.limit(25)
			.forEach(e -> System.out.println("   param " + e.getKey()
				+ "  on " + e.getValue() + " items"));
	}
}
